INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0ef8644e50886b15', 'act-english', 's-gram', 1, 'By the time we reached the trailhead, the sun had already <u>rose</u> over the ridge.', 'Which choice is the correct form after ''had''?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"raised","letter":"B"},{"is_no_change":false,"label":"rised","letter":"C"},{"is_no_change":false,"label":"risen","letter":"D"}]', 'D', '{"A":"''Rose'' is the simple past — ''had'' needs the past participle.","B":"''Raised'' comes from ''raise'' (to lift something) — the sun rises on its own.","C":"''Rised'' isn''t a form of this irregular verb.","D":"''Had risen'' pairs the helper with the participle."}', 'After ''had'', irregular verbs use their **past participle**: had risen.', 'The simple past ''rose'' is the form we say most often.', 'Rise-rose-risen; raise-raised-raised. Helpers (have/had) take the third form.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-115a1f54729c0934', 'act-english', 's-gram', 1, 'I <u>seen</u> the meteor shower from the roof of the parking garage.', 'Which choice is the correct past form of the verb?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"saw","letter":"B"},{"is_no_change":false,"label":"have saw","letter":"C"},{"is_no_change":false,"label":"seed","letter":"D"}]', 'B', '{"A":"''Seen'' is a participle — it can''t stand alone without ''have'' or ''had''.","B":"''Saw'' is the simple past and needs no helper.","C":"''Have saw'' pairs the helper with the wrong form.","D":"''Seed'' isn''t a verb form at all here."}', 'Alone, the past of ''see'' is **saw**; ''seen'' only works with a helper.', '''I seen it'' is common in casual speech.', 'See-saw-seen: ''saw'' stands alone; ''seen'' rides with have/has/had.', 'underlined-span-mc', 'using casual ''seen'' for the past participle', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1f9624c3292b98e5', 'act-english', 's-gram', 1, 'Every morning, the <u>batch of croissants rise</u> unevenly if the layered butter softens before the trays reach the oven.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"batch of croissants rises","letter":"B"},{"is_no_change":false,"label":"batch of croissants are rising","letter":"C"},{"is_no_change":false,"label":"batches of croissant rises","letter":"D"}]', 'B', '{"A":"Nearest-noun trap: the verb has been matched to the plural ''croissants'' inside the prepositional phrase instead of to the singular subject ''batch.''","B":"Correct: the true subject is the singular ''batch,'' so it takes the singular verb; ''of croissants'' is only a modifier.","C":"Uses a plural verb and needlessly shifts into a progressive form, both of which fail with the singular, habitual subject.","D":"Rewrites the subject instead of fixing the verb — and the new plural ''batches'' still disagrees with the singular verb."}', 'The subject is the singular **batch**, so it needs a singular verb; the prepositional phrase ''of croissants'' cannot control agreement.', 'The plural noun sitting directly beside the verb makes a plural verb sound natural to the ear.', '1) Find the verb. 2) Ask ''who or what does this?'' 3) Cross out any prepositional phrase (''of ___'') between subject and verb. 4) Match the verb to the head noun that remains. 5) Reread the sentence to confirm it sounds right without the crossed-out phrase.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3d7b1786e115d2ae', 'act-english', 's-gram', 1, 'We <u>could of</u> caught the earlier bus if the drills had ended on time.', 'Which choice is the correct form of the verb phrase?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"could","letter":"B"},{"is_no_change":false,"label":"could off","letter":"C"},{"is_no_change":false,"label":"could have","letter":"D"}]', 'D', '{"A":"''Of'' is a preposition — it can''t help a verb.","B":"Dropping the helper changes the meaning from missed chance to plain ability.","C":"''Off'' makes it worse, not better.","D":"The helper is ''have'': could have caught."}', 'The contraction ''could''ve'' spells out as **could have** — never ''could of''.', '''Could''ve'' SOUNDS exactly like ''could of''.', 'Would/could/should pair with HAVE; the ''-of'' spelling is always an ear-spelling error.', 'underlined-span-mc', 'hearing ''could''ve'' as ''could of''', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4a1e99e3d7ed6552', 'act-english', 's-gram', 1, 'Pigeons tuck <u>there</u> nests into window ledges, bridge beams, and traffic-light housings all over downtown.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"their","letter":"B"},{"is_no_change":false,"label":"they''re","letter":"C"},{"is_no_change":false,"label":"there''s","letter":"D"}]', 'B', '{"A":"Confuses the place word with the possessive: ''there'' points to a location, but the nests belong to the pigeons (confused_homophone).","B":"Correct: the possessive form is needed because the nests belong to the pigeons.","C":"Contraction error: expanding it gives ''Pigeons tuck they are nests,'' which fails (contraction_for_possessive).","D":"Contraction of ''there is,'' a verb phrase that cannot modify the noun ''nests'' (contraction_for_possessive)."}', 'The nests belong to the pigeons, so the **possessive** form of the pronoun is required before ''nests.''', '''There'' is pronounced identically to the possessive, so students who spell by ear rather than by function pick it.', '1) Ask what job the word is doing: place, ownership, or contraction. 2) Try expanding the word to ''they are'' or ''there is'' — if the sentence still works, the apostrophe form is right. 3) If the word points to a location (''over there''), use the t-h-e-r-e spelling. 4) If something belongs to ''them,'' use the possessive spelling. 5) Re-read the sentence with your chosen form to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4ae6a4ffb48ec23d', 'act-english', 's-gram', 1, 'Yesterday the choir <u>sung</u> the national anthem, and the whole stadium rose to its feet.', 'Which choice fits the time the sentence describes?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"singed","letter":"B"},{"is_no_change":false,"label":"sang","letter":"C"},{"is_no_change":false,"label":"sings","letter":"D"}]', 'C', '{"A":"''Sung'' is the past participle and needs a helping verb (''had sung''); alone it cannot serve as the simple past.","B":"''Singed'' means lightly burned; it is not a form of ''sing''.","C":"''Sang'' is the simple past of ''sing'' — exactly what ''Yesterday'' calls for.","D":"''Sings'' is present tense, clashing with ''Yesterday''."}', 'Irregular verb: sing → **sang** (simple past) → sung (participle, needs a helper).', '''Sung'' sounds vaguely past-tense, and the sung/sang pair is easy to swap.', 'Use the simple past form alone; save the participle (sung, swum, begun) for perfect tenses with ''have/had''.', 'underlined-span-mc', 'swapping sang/sung after a helper', true, 'gpt-4o-mini+gpt-4o>=d2@641234d1808d41ec98477ba4961d06d7')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-61a600f134c0969a', 'act-english', 's-gram', 1, 'The council debated <u>weather</u> to repave Main Street before winter.', 'Which choice is the correct word for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"wether","letter":"B"},{"is_no_change":false,"label":"whether","letter":"C"},{"is_no_change":false,"label":"wheather","letter":"D"}]', 'C', '{"A":"''Weather'' means atmospheric conditions, not a choice between options.","B":"''Wether'' is a castrated ram — a real word, but not this one.","C":"''Whether'' introduces the choice the council is weighing.","D":"''Wheather'' is not a word; it misspells ''whether''."}', '**''Whether''** introduces alternatives (''whether X or Y''); ''weather'' is the sky.', '''Weather'' and ''whether'' sound identical, so the everyday spelling slips in.', 'Match the homophone to its meaning: whether = if/choice, weather = climate.', 'underlined-span-mc', 'confusing weather/whether by sound', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-689be41bb9faba70', 'act-english', 's-gram', 1, 'The second week of practice went <u>more smooth</u> than the first.', 'Which choice compares the two weeks correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"more smoothly","letter":"B"},{"is_no_change":false,"label":"smoother","letter":"C"},{"is_no_change":false,"label":"most smoothly","letter":"D"}]', 'B', '{"A":"''Went'' needs an adverb — ''smooth'' is the adjective.","B":"''More smoothly'' is the comparative ADVERB the verb needs.","C":"''Smoother'' compares two nouns, but here we''re describing how practice WENT.","D":"''Most'' is the superlative — there are only two weeks."}', 'Comparing how something happened takes a **comparative adverb**: more smoothly.', '''Smooth'' and ''smoother'' sound fine because the adjective is so familiar.', 'Modify a verb with an adverb; compare two with ''more + adverb'', not the bare adjective.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b21cca2fbc4a3c98', 'act-english', 's-gram', 1, 'Passage I — Learning to Sail — The summer I turned fourteen, my uncle <u>teached</u> me to sail. His old wooden boat, named the <em>Osprey</em>, had belonged to my grandfather. On our first morning out, the wind was calm, and we drifted lazily across the bay. However, by noon a stiff breeze had risen, and the <em>Osprey</em> leaned hard against it. My uncle showed me how to read the wind by watching the surface of the water. "Dark patches mean gusts," he said, "and you must be ready." At first I was nervous, gripping the lines too tightly. But after an hour, I begun to relax. By the end of the day, I could steer the boat myself. Although I still had much to learn, I felt a new confidence. Sailing, I realized, was not about controlling the wind but about working with it.', 'Which choice corrects the underlined verb''s past-tense form?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"taught","letter":"B"},{"is_no_change":false,"label":"teaches","letter":"C"},{"is_no_change":false,"label":"had teached","letter":"D"}]', 'B', '{"A":"This option leaves or introduces an error under the tested rule.","B":"Past tense of \"teach\" is \"taught.\"","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Past tense of "teach" is "taught."', 'The original can read smoothly until you apply the rule.', 'Rule focus: Conventions (irregular verb)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@2e145cb2f5514579b1cae251b777cff0')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e8caf2efaea6d18c', 'act-english', 's-gram', 1, 'Last night the power flickered twice, and the smoke alarm <u>chirps</u> until Dad changed its battery.', 'Which choice keeps the sentence in one time frame?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"chirped","letter":"B"},{"is_no_change":false,"label":"chirping","letter":"C"},{"is_no_change":false,"label":"will chirp","letter":"D"}]', 'B', '{"A":"''Last night'' and ''changed'' set the past — present ''chirps'' jumps the track.","B":"Past ''chirped'' matches ''flickered'' and ''changed''.","C":"''Chirping'' leaves the clause without a real verb.","D":"Future tense contradicts a finished story."}', 'Stay in the tense the sentence establishes — here, the **past**.', 'The alarm''s chirping is easy to picture as happening ''now''.', 'Match every verb to the sentence''s time markers unless the meaning truly changes time.', 'underlined-span-mc', 'the alarm''s chirping is easy to picture as happening ''now''', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fd776d1d6c01289c', 'act-english', 's-gram', 1, '<u>The stack of press releases sits</u> on the copy desk until an editor sorts through it each afternoon.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The stack of press releases sit","letter":"B"},{"is_no_change":false,"label":"The stacks of press releases sits","letter":"C"},{"is_no_change":false,"label":"The stack of press releases are sitting","letter":"D"}]', 'A', '{"A":"Correct: the subject is the singular ''stack''; ''of press releases'' is only a prepositional phrase, so the singular verb agrees.","B":"Matches the verb to ''releases,'' the plural noun nearest the verb, instead of to the true subject — nearest-noun attraction.","C":"Rewrites the subject as plural while keeping a singular verb, trading one agreement error for another.","D":"Uses the plural verb ''are'' with the singular subject ''stack,'' the same attraction error in progressive form."}', 'The subject is the singular **stack** — the phrase ''of press releases'' is only a prepositional modifier — so ''sits'' agrees.', '''Sit'' tempts students who match the verb to ''releases,'' the plural noun sitting closest to it.', '1) Find the verb. 2) Ask ''who or what does it?'' to find the subject. 3) Cross out prepositional phrases (of..., on..., with...) between subject and verb. 4) Match the verb to the remaining head noun. 5) Re-read the trimmed sentence to confirm it sounds right.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0234d28238192294', 'act-english', 's-gram', 2, 'Each of the branch libraries <u>keeps</u> a binder of local bus schedules behind its reference desk.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"keep","letter":"B"},{"is_no_change":false,"label":"are keeping","letter":"C"},{"is_no_change":false,"label":"have kept","letter":"D"}]', 'A', '{"A":"Correct: the subject is the singular pronoun ''Each,'' so the singular verb agrees.","B":"Matches the verb to ''libraries,'' the nearest noun, but that noun is the object of ''of,'' not the subject.","C":"Doubles the error: the plural helper ''are'' clashes with singular ''Each,'' and progressive aspect misfits a routine habit.","D":"Uses the plural helper ''have'' with the singular subject and shifts a present routine into the perfect tense."}', 'The true subject is **Each**, which is always singular, so the singular verb is required.', 'The plural noun ''libraries'' sits right next to the verb, so students match the verb to the nearest noun instead of the true subject.', '1) Find the verb. 2) Ask ''who or what does this?'' 3) Cross out prepositional phrases such as ''of the branch libraries.'' 4) Match the verb to the remaining head word — each, one, and everyone are singular. 5) Re-read the sentence with the phrase removed to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-029593c1fe5291ac', 'act-english', 's-gram', 2, 'Each kayak in the rental fleet has <u>their</u> own numbered paddle.', 'Which pronoun matches the word it stands for?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"there","letter":"B"},{"is_no_change":false,"label":"his","letter":"C"},{"is_no_change":false,"label":"its","letter":"D"}]', 'D', '{"A":"''Each kayak'' is singular; ''their'' is plural.","B":"''There'' is a place word, not a possessive.","C":"A kayak isn''t a person.","D":"One kayak at a time → ''its'' paddle."}', '''Each'' keeps the antecedent **singular** — one kayak, its paddle.', 'The plural ''fleet'' nearby pulls the pronoun plural.', 'Each/every + noun stays singular no matter what plural stands nearby.', 'underlined-span-mc', 'letting a nearby plural noun pull agreement', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-08bdc4466f53c76d', 'act-english', 's-gram', 2, 'The set of loaner telescopes <u>are stored</u> in a closet behind the circulation desk until a patron requests one.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have been stored","letter":"B"},{"is_no_change":false,"label":"were stored","letter":"C"},{"is_no_change":false,"label":"is stored","letter":"D"}]', 'D', '{"A":"Nearest-noun trap: ''are'' agrees with ''telescopes,'' but the true subject is the singular ''set.''","B":"''Have'' is another plural form pulled toward the nearby noun instead of the singular head noun ''set.''","C":"''Were'' is both plural and past tense, though the subject is singular and the routine is ongoing.","D":"Correct: the singular head noun ''set'' takes the singular present verb, matching the ongoing routine."}', 'The **head noun** ''set'' — not the nearby ''telescopes'' — controls the verb, so a singular present-tense verb is required.', 'The plural ''are stored'' tempts students because ''telescopes'' sits right next to the verb and sounds like the subject.', '1) Find the verb. 2) Ask ''who or what does this?'' and cross out every prepositional phrase before the verb (''of loaner telescopes''). 3) Identify the head noun that remains (''set''). 4) Match the verb to that noun''s number. 5) Confirm the tense fits the sentence''s time frame.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0930accab0c621a8', 'act-english', 's-gram', 2, 'By the time the pace group reached mile eighteen, the morning fog <u>had lifted</u>, and the runners could finally see the harbor.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has lifted","letter":"B"},{"is_no_change":false,"label":"lifts","letter":"C"},{"is_no_change":false,"label":"will have lifted","letter":"D"}]', 'A', '{"A":"Correct: past perfect ''had lifted'' shows the fog cleared before the past-tense event ''reached.''","B":"Present perfect anchors the lifting to the present moment, clashing with the past-tense clause ''reached mile eighteen'' (present_perfect_in_past).","C":"Simple present drops the fog into the present even though the narrative is in the past (tense_shift_present).","D":"Future perfect points ahead in time, contradicting the completed past events in both clauses (future_in_past_narrative)."}', 'The fog cleared **before** the past event of reaching mile eighteen, and the past perfect is the tense built to show an earlier past action.', '''Has lifted'' tempts students because present perfect also describes a completed action, hiding its clash with the past-tense frame.', '1) Find the anchor verb that sets the time frame (here, ''reached''). 2) Identify its tense. 3) Ask whether the underlined action happened before, during, or after the anchor. 4) For an action completed before a past anchor, use had + past participle. 5) Re-read both clauses to confirm the sequence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0aaac9cacc717d4b', 'act-english', 's-gram', 2, 'Each of my cousins has traced <u>their</u> branch of the family back to the village outside Guadalajara where our great-grandparents were married.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"his or her","letter":"B"},{"is_no_change":false,"label":"its","letter":"C"},{"is_no_change":false,"label":"they''re","letter":"D"}]', 'B', '{"A":"''Their'' is plural, but the true subject ''each'' is grammatically singular, so the pronoun clashes with its antecedent in number.","B":"Correct: the singular subject ''each'' requires a singular, person-appropriate possessive.","C":"''Its'' is singular but refers to things, not people; the cousins are human beings.","D":"''They''re'' is the contraction of ''they are,'' not a possessive form at all."}', '**Each** is grammatically singular, so the possessive that refers back to it must be singular and suited to people.', '''Their'' matches everyday speech and avoids awkwardness, but the ACT requires number agreement with the singular ''each.''', '1) Find the pronoun and ask what noun it points back to. 2) Cross out the prepositional phrase after the subject — *of my cousins* — leaving *each*. 3) Classify the antecedent: *each* is always singular. 4) Ask whether the antecedent is a person or a thing. 5) Choose a singular, person-appropriate possessive; reject contractions posing as possessives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0dcd672f1f8d3b8a', 'act-english', 's-gram', 2, 'Peanut butter and jelly <u>makes</u> a decent trail lunch when the cooler ice runs out.', 'Which choice agrees with the compound subject?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has made","letter":"B"},{"is_no_change":false,"label":"is making","letter":"C"},{"is_no_change":false,"label":"make","letter":"D"}]', 'D', '{"A":"Two foods joined by ''and'' form a plural subject — ''makes'' is singular.","B":"''Has made'' is singular and shifts the general claim into a finished past.","C":"''Is making'' is still singular and adds a progressive the sentence doesn''t need.","D":"''And'' builds a plural subject, and ''make'' agrees with it."}', 'Subjects joined by **''and'' are plural** — they take a plural verb.', 'The pair feels like one sandwich, so a singular verb sounds natural.', 'X and Y → plural verb, unless the pair names a single fixed unit (macaroni and cheese IS).', 'underlined-span-mc', 'treating a compound subject as singular', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2068637d9db97759', 'act-english', 's-gram', 2, 'Each new member of the photo club must label <u>their</u> box of printing paper before storing it in the paper safe.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"them","letter":"B"},{"is_no_change":false,"label":"his or her","letter":"C"},{"is_no_change":false,"label":"its","letter":"D"}]', 'C', '{"A":"Uses a plural pronoun for the grammatically singular ''each new member'' (plural_for_each), which the ACT counts as an agreement error.","B":"Puts an object pronoun where a possessive is required before the noun ''box'' (object_for_possessive).","C":"Correct: ''each new member'' is singular and human, so the singular personal possessive agrees in number and kind.","D":"Chooses a singular pronoun but one reserved for things, not people (nonhuman_pronoun), so it cannot refer to a club member."}', '''Each new member'' is grammatically **singular**, so the pronoun must be a singular possessive that can refer to a person.', '''Their'' matches how most people speak, so students accept the plural pronoun without noticing that ''each'' forces a singular antecedent on the ACT.', '1) Find the pronoun''s antecedent. 2) Check its number — words like ''each,'' ''every,'' and ''neither'' are singular. 3) Check its kind — person or thing. 4) Confirm the pronoun''s job (possessive before a noun, subject, or object). 5) Pick the pronoun matching all three: number, kind, and job.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2347e23051258ddd', 'act-english', 's-gram', 2, 'By the time the bus finally arrived, Maria <u>waits</u> at the corner for over an hour.', 'Which verb form best completes the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"will wait","letter":"B"},{"is_no_change":false,"label":"is waiting","letter":"C"},{"is_no_change":false,"label":"had been waiting","letter":"D"}]', 'D', '{"A":"Present-tense ''waits'' clashes with the past-tense ''arrived'' that anchors the sentence.","B":"''Will wait'' pushes the waiting into the future, after the bus arrived — backwards.","C":"''Is waiting'' is present tense; the arrival already happened.","D":"''Had been waiting'' places the hour of waiting BEFORE the past arrival — exactly the sequence the sentence describes."}', 'An action ongoing **before** a past event takes the past perfect (progressive): *had been waiting*.', 'Each verb form sounds fine alone; only checking it against ''arrived'' exposes the clash.', 'Match verb tense to the sentence''s time anchors; ''by the time X happened'' demands past perfect.', 'underlined-span-mc', 'each verb form sounds fine alone; only checking it against ''arrived''…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-28f60f99a18ae389', 'act-english', 's-gram', 2, 'During last month''s dress rehearsal, the stage manager <u>calls</u> each lighting cue from the booth while the cast moved through the second act.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has called","letter":"B"},{"is_no_change":false,"label":"called","letter":"C"},{"is_no_change":false,"label":"will call","letter":"D"}]', 'C', '{"A":"Present-tense ''calls'' ignores the time markers ''last month''s'' and ''moved,'' which fix the event in the past (tense_ignores_time_markers).","B":"Present perfect ''has called'' ties the action to the present moment, but the rehearsal began and ended last month (perfect_for_finished_past).","C":"Correct: simple past ''called'' matches both the time marker ''last month''s'' and the past-tense verb ''moved.''","D":"Future ''will call'' contradicts an event the sentence says already happened (future_for_past_event)."}', 'The time marker ''last month''s'' and the past verb ''moved'' fix the sentence in the **past**, so the simple past form is required.', 'Students pick the present perfect because ''has called'' sounds polished and complete, even though it wrongly links a finished past event to now.', '1) Circle every time marker in the sentence (words like ''last,'' ''next,'' ''yesterday''). 2) Find all other verbs and note their tense. 3) Ask: is the underlined action in the same time frame? 4) Choose the verb form that matches the established frame. 5) Reread the whole sentence to confirm the timeline is consistent.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-293cc0b3217916e9', 'act-english', 's-gram', 2, 'The library extended <u>their</u> weekend hours during exam season.', 'Which pronoun agrees with ''the library''?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"it''s","letter":"B"},{"is_no_change":false,"label":"its","letter":"C"},{"is_no_change":false,"label":"there","letter":"D"}]', 'C', '{"A":"''Their'' is plural, but ''the library'' is one thing.","B":"''It''s'' means ''it is'' — not a possessive.","C":"Singular, non-person antecedent → ''its''.","D":"''There'' points to a place; it can''t possess hours."}', 'A singular thing takes the singular possessive **''its''**.', 'Organizations feel like the people inside them, so ''their'' slips in.', 'Match the pronoun to the antecedent''s number: one library → its.', 'underlined-span-mc', 'treating an organization as plural ''their''', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2b7e0cd3bb36cb99', 'act-english', 's-gram', 2, 'At the awards banquet, the publisher thanked the intern <u>who had organized</u> fifty years of photo negatives into a searchable archive.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"whom had organized","letter":"B"},{"is_no_change":false,"label":"which had organized","letter":"C"},{"is_no_change":false,"label":"whomever had organized","letter":"D"}]', 'A', '{"A":"Correct: ''who'' is the subject performing ''had organized,'' so subject case is required.","B":"Hypercorrect ''whom'' places an object form in the subject seat of its clause.","C":"''Which'' cannot refer to a person; the antecedent is ''the intern.''","D":"''Whomever'' is both object case and an open-ended pronoun, and neither feature fits a specific intern doing the verb."}', '**Who** is correct because the pronoun is the subject of ''had organized'' — the he/him test yields ''he had organized.''', '''Whom'' tempts students who assume the fancier form is safer after a verb like ''thanked.''', '1) Isolate the clause the pronoun starts. 2) Replace the pronoun with ''he'' or ''him'' and read the clause alone. 3) If ''he'' works, use who/whoever; if ''him'' works, use whom/whomever. 4) Confirm the pronoun refers to a person, not a thing. 5) Re-read the full sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2f27b759b69745cb', 'act-english', 's-gram', 2, 'The saucier <u>who the head chef trusted</u> with the evening''s consommé had apprenticed for a decade in Marseille.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"whom the head chef trusted","letter":"B"},{"is_no_change":false,"label":"which the head chef trusted","letter":"C"},{"is_no_change":false,"label":"whom the head chef trusted him","letter":"D"}]', 'B', '{"A":"Case error: the pronoun is the object of ''trusted'' (the head chef trusted *her*), so the subject form fails.","B":"Correct: the relative pronoun receives the action of ''trusted,'' so it must take the object case.","C":"Uses a relative pronoun reserved for things to refer to a person.","D":"Pronoun doubling: the relative pronoun already fills the object slot, so adding ''him'' names the object twice."}', 'The pronoun is the **object** of ''trusted'' — the head chef trusted *her* — so the object-case relative pronoun is required.', 'Because the pronoun appears right where a subject usually sits, before ''the head chef,'' the subject form sounds natural.', '1) Isolate the relative clause. 2) Rearrange it into a plain sentence: ''the head chef trusted ___.'' 3) Test with he/him: if *him* fits, use the object-case relative pronoun; if *he* fits, use the subject form. 4) Confirm the pronoun refers to a person, not a thing. 5) Check that no extra pronoun repeats the same slot.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-36ee7811583ee9f3', 'act-english', 's-gram', 2, 'Every morning the ferry leaves at six, crosses the sound in forty minutes, and <u>docked</u> beside the fish market.', 'Which choice keeps the daily routine consistent?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"docks","letter":"B"},{"is_no_change":false,"label":"was docking","letter":"C"},{"is_no_change":false,"label":"had docked","letter":"D"}]', 'B', '{"A":"''Docked'' drops one leg of a present-tense routine into the past.","B":"Present ''docks'' matches ''leaves'' and ''crosses'' — a habit, not a memory.","C":"''Was docking'' shifts to a past scene mid-list.","D":"''Had docked'' reaches even further back than the plain past."}', 'A routine described in present tense keeps **every verb present**.', 'Any single leg of the trip can be remembered as a past event.', 'Verbs in a series share the sentence''s time frame — don''t shift without a reason.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-44238efe8683dc31', 'act-english', 's-gram', 2, 'Weeks of cold rain had <u>effected</u> the crew''s morale, so the leader called a layover day at the lake.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"effected upon","letter":"B"},{"is_no_change":false,"label":"affected","letter":"C"},{"is_no_change":false,"label":"afflicted","letter":"D"}]', 'C', '{"A":"This is the classic effect/affect ear-swap: *effected* means ''brought about,'' which would absurdly claim the rain created the morale rather than influenced it.","B":"Adds a preposition to the same misspelled verb; *effected upon* is not idiomatic English and the spelling error remains.","C":"*Affected* means ''influenced,'' which is exactly the intended meaning: the rain influenced the crew''s morale.","D":"*Afflicted* means ''caused suffering to'' and takes a person or body as its object, so it cannot sensibly act on an abstract noun like morale."}', 'The sentence needs the verb meaning **to influence**, and *affected* is that verb.', '*Effected* sounds identical to the correct verb when read aloud, so students who spell by ear keep the original.', '1) Locate the sound-alike verb. 2) Substitute a one-word definition: ''influence'' or ''bring about.'' 3) If the sentence means ''influence,'' use the a-spelling verb; if it means ''bring about a result'' (as in ''effected a change''), use the e-spelling verb. 4) Reread the sentence with your definition in place to confirm the meaning holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4a85ad4f4cd29984', 'act-english', 's-gram', 2, 'New members spend their first month learning <u>to wedge the clay, to center it on the wheel, and to pull</u> an even cylinder.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to wedge the clay, centering it on the wheel, and to pull","letter":"B"},{"is_no_change":false,"label":"to wedge the clay, to center it on the wheel, and pulling","letter":"C"},{"is_no_change":false,"label":"wedging the clay, to center it on the wheel, and to pull","letter":"D"}]', 'A', '{"A":"Correct: all three items in the series share the same to + verb form.","B":"Swaps the middle item to an -ing form, breaking the pattern set by the first and third items (mixed forms mid-series).","C":"Lets the final item drift into an -ing form after two matching items (last-item drift).","D":"Opens the series with an -ing form that the second and third items then abandon (mismatched first item)."}', 'Items in a series must be **parallel** — here, three matching to + verb phrases.', 'The -ing swap in the middle is easy to miss because each item still sounds fine read in isolation.', '1) Spot the list — look for commas plus ''and''. 2) Write the items in a column. 3) Check that each item begins with the same grammatical shape. 4) If one item breaks the pattern, reject that version. 5) Choose the version whose items all match.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4aca940020a34632', 'act-english', 's-gram', 2, 'As the tide slipped away, the crab scuttled <u>quickly</u> across the wet ledge toward a shaded crevice.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"quick","letter":"B"},{"is_no_change":false,"label":"real quick","letter":"C"},{"is_no_change":false,"label":"quicker","letter":"D"}]', 'A', '{"A":"Correct: the adverb properly modifies the verb ''scuttled,'' telling how the crab moved.","B":"''Quick'' is an adjective and cannot modify the action verb ''scuttled'' (adj_for_adverb).","C":"''Real quick'' is a colloquial adverb phrase, doubly nonstandard in formal writing.","D":"A comparative form has nothing being compared, so it cannot describe the single action."}', 'An **adverb** is needed to modify the verb ''scuttled,'' and the -ly form does that job.', 'The bare adjective sounds fine in speech, so students forget that modifying a verb requires the adverb form.', '1) Find the word being described. 2) If it is a verb or action, use an adverb (often -ly). 3) If it is a noun, use an adjective. 4) Reject comparative forms unless two things are actually compared.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-57ace155ae370f70', 'act-english', 's-gram', 2, 'The moon''s gravity greatly <u>effects</u> the ocean''s tides.', 'Which choice best fits the meaning of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"affect","letter":"B"},{"is_no_change":false,"label":"effect","letter":"C"},{"is_no_change":false,"label":"affects","letter":"D"}]', 'D', '{"A":"Uses ''effects,'' which as a verb means ''to bring about,'' wrongly saying the gravity creates the tides rather than influences them (confused_homophone).","B":"''Affect'' is the right word, but the singular subject ''the moon''s gravity'' requires the -s form (sv_agreement).","C":"''Effect'' is normally a noun (a result), so using it as the verb misstates both the word and the action (confused_homophone).","D":"Correct: the verb meaning ''to influence'' is ''affect,'' and the singular subject calls for ''affects.''"}', '**Affect** is the verb meaning ''to influence,'' and the singular subject requires ''affects.''', '''Effects'' looks nearly identical to the intended word, so students who blur the affect/effect pair pick it by ear.', '1) Decide whether the slot needs a verb or a noun. 2) If it needs a verb meaning ''to influence,'' use a form of ''affect.'' 3) Reserve ''effect'' for the noun (a result). 4) Match the verb to the subject''s number: a singular subject takes the -s form.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5c506f2cebb6e381', 'act-english', 's-gram', 2, 'Passage IV — Night Shift at the Observatory — My first night as a volunteer at the observatory, I expected glamour. Instead, I found cold floors, humming machines, and a long checklist. The astronomer on duty, Dr. Okafor, greeted me warmly but immediately put me to work. <u>Their</u> were dozens of small tasks: calibrating instruments, logging temperatures, and to check the dome''s rotation. None of it looked like the dramatic discoveries I had imagined. Yet as the hours passed, I began to understand that this quiet, careful labor was the real work of science. Around 2 a.m., Dr. Okafor called me over. On the screen was a faint smudge of light — a distant galaxy. "It isn''t much to look at," she said, "but light from there left before humans existed." In that moment, the cold floors and checklists seemed worth it.', 'Which choice uses the correct word for the underlined homophone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"There","letter":"B"},{"is_no_change":false,"label":"They''re","letter":"C"},{"is_no_change":false,"label":"There''re","letter":"D"}]', 'B', '{"A":"This option leaves or introduces an error under the tested rule.","B":"\"There were dozens\" — \"There,\" not \"Their/They''re.\"","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', '"There were dozens" — "There," not "Their/They''re."', 'The original can read smoothly until you apply the rule.', 'Rule focus: Conventions (homophone)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-644e30a1183f75cd', 'act-english', 's-gram', 2, 'Of the two species, the blue whale grows <u>more larger</u> than the fin whale.', 'Which choice is most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"larger","letter":"B"},{"is_no_change":false,"label":"largest","letter":"C"},{"is_no_change":false,"label":"most large","letter":"D"}]', 'B', '{"A":"Stacks two comparative markers (''more'' plus ''-er''), forming a double comparative (double_comparative).","B":"Correct: a two-item comparison of a short adjective takes the single comparative ''-er'' form.","C":"Uses the superlative, which is for singling out one of three or more, not comparing two (superlative_for_two).","D":"Uses ''most'' plus the base word, a superlative that is both wrong for two items and nonstandard for a one-syllable adjective (superlative_for_two)."}', 'A comparison of exactly **two** items uses the comparative form, and short adjectives form it with ''-er.''', '''More larger'' sounds emphatic, so students who want to stress the size double up the comparative.', '1) Count how many items are compared. 2) For exactly two, use the comparative; for three or more, use the superlative. 3) Form a short adjective''s comparative with ''-er'' or ''more,'' never both. 4) Re-read to confirm only one comparative marker appears.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a18f5715603f1c5', 'act-english', 's-gram', 2, 'By late summer, each colony fiercely defends <u>its</u> honey stores against raiding wasps.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"their","letter":"B"},{"is_no_change":false,"label":"it''s","letter":"C"},{"is_no_change":false,"label":"its''","letter":"D"}]', 'A', '{"A":"Correct: ''each colony'' is a singular antecedent, and the singular possessive ''its'' agrees with it.","B":"Uses a plural pronoun for the singular antecedent ''each colony,'' a number-agreement error triggered by picturing many colonies.","C":"Substitutes the contraction of ''it is'' where the sentence needs a possessive pronoun.","D":"Puts an apostrophe on a possessive pronoun, producing a form that does not exist in English."}', 'Because **each** makes its noun singular, the singular possessive pronoun agrees with ''each colony.''', 'Students picture many colonies across the apiary and reach for the plural ''their,'' ignoring that ''each'' forces a one-at-a-time reading.', '1) Circle the pronoun and draw an arrow back to its antecedent. 2) If the antecedent starts with ''each,'' ''every,'' or ''either,'' treat it as singular. 3) Match the pronoun''s number to the antecedent''s. 4) If an apostrophe appears, expand it (''it is'') to test whether a contraction fits; possessive pronouns never take apostrophes.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6d1b683baf09e036', 'act-english', 's-gram', 2, 'The understudy performed so <u>good</u> on opening night that the director rewrote the schedule.', 'Which choice correctly describes how the understudy performed?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"well","letter":"B"},{"is_no_change":false,"label":"goodly","letter":"C"},{"is_no_change":false,"label":"great","letter":"D"}]', 'B', '{"A":"''Good'' is an adjective; ''performed'' needs an adverb.","B":"''Well'' is the adverb that tells HOW she performed.","C":"''Goodly'' is archaic and means ''sizable'', not ''skillfully''.","D":"''Great'' is another adjective in an adverb''s slot."}', 'Describe a verb with an **adverb**: performed well.', '''Did good'' is everywhere in casual speech.', 'Good describes nouns; well describes verbs (except health: ''I feel well'').', 'underlined-span-mc', 'using ''good'' where an adverb is required', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6fe81833e4b4c8dc', 'act-english', 's-gram', 2, 'The <u>basket of hand-spun yarns sit</u> beside the loom in her studio.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"basket of hand-spun yarns sits","letter":"B"},{"is_no_change":false,"label":"basket of hand-spun yarns are sitting","letter":"C"},{"is_no_change":false,"label":"baskets of hand-spun yarn sit","letter":"D"}]', 'B', '{"A":"''Sit'' agrees with the nearby plural ''yarns'' instead of the true subject, ''basket.''","B":"Correct: the subject is the singular ''basket,'' so a singular verb is required; ''of hand-spun yarns'' is only a prepositional phrase.","C":"''Are sitting'' still matches the plural noun inside the prepositional phrase rather than the singular subject.","D":"Making the subject plural forces agreement but changes the sentence''s meaning from one basket to several."}', 'The verb must agree with the **subject** ''basket,'' not with the noun inside the prepositional phrase.', 'The original sounds right to many students because the plural ''yarns'' lands immediately before the verb.', '1) Find the verb. 2) Ask ''who or what does this?'' to find the subject. 3) Cross out any ''of/in/with'' phrase between subject and verb. 4) Match the verb to the remaining subject''s number. 5) Reject options that fix agreement by changing the meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-710a3599e4abf52e', 'act-english', 's-gram', 2, 'In early New Orleans funeral processions, brass bands played solemn hymns on the march to the cemetery and raucous stomps on <u>they''re return</u> to town.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"there return","letter":"B"},{"is_no_change":false,"label":"they are return","letter":"C"},{"is_no_change":false,"label":"their return","letter":"D"}]', 'D', '{"A":"confused_homophone: *they''re* is the contraction of *they are*, which cannot show possession of *return*.","B":"*There* points to a place and never marks possession, so it cannot tell whose return this is.","C":"Expanding the contraction to *they are return* produces nonsense, proving a subject-verb pair cannot fill this slot.","D":"Correct: the possessive *their* shows that the return belongs to the bands."}', 'The slot needs the **possessive** form to show whose return it is.', '*They''re* sounds identical to the possessive when read aloud, so ear-spellers accept it without testing the expansion.', '1) Expand the word: does *they are* make sense in the slot? 2) If yes, the apostrophe form is right; if no, reject it. 3) If the word answers *whose?*, use the possessive spelling. 4) If it answers *where?*, use the t-h-e-r-e spelling. 5) Reread the sentence with your pick.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-73397f1454c099be', 'act-english', 's-gram', 2, 'Early brakemen learned to couple cars, to set the hand brakes, and <u>signaling the engineer</u> with a swinging lantern.', 'Which choice is best for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to signal the engineer","letter":"B"},{"is_no_change":false,"label":"they signaled the engineer","letter":"C"},{"is_no_change":false,"label":"the signaling of the engineer","letter":"D"}]', 'B', '{"A":"''Signaling'' breaks the pattern set by the infinitives ''to couple'' and ''to set.''","B":"Correct: ''to signal'' completes the series in the same infinitive form as the first two items.","C":"''They signaled'' inserts a full clause into a list of phrases, derailing the parallel series.","D":"''The signaling of'' switches to a noun phrase that cannot follow ''learned'' alongside the other items."}', 'Items in a series must share one grammatical form, and the first two items are **infinitives**.', 'The -ing form sounds natural read alone, so students who don''t scan back to the start of the list accept it.', '1) Find the list and mark each item''s first word. 2) Identify the form of item one (to + verb, -ing, noun). 3) Force every later item into that same form. 4) Reread the whole series to confirm each item hooks onto the lead-in verb.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-761f60222a4710aa', 'act-english', 's-gram', 2, 'Modern cable-stayed bridges are capable <u>of withstanding</u> both hurricane-force winds and constant truck traffic.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to withstand","letter":"B"},{"is_no_change":false,"label":"of withstand","letter":"C"},{"is_no_change":false,"label":"for withstanding","letter":"D"}]', 'A', '{"A":"The idiom is ''capable of'' plus a gerund, so ''capable of withstanding'' is standard English.","B":"Borrows the infinitive pattern of ''able to,'' but ''capable'' does not take an infinitive (misconception: idiom_wrong_pattern_able).","C":"Keeps the right preposition but strands a bare verb stem after it; prepositions require gerunds (misconception: bare_verb_after_preposition).","D":"Substitutes ''for'' where the fixed idiom demands ''of'' (misconception: idiom_wrong_preposition)."}', 'The adjective ''capable'' takes the fixed pairing **of + -ing form**, which the original already uses.', 'Because ''able to withstand'' is correct English, students transfer that infinitive pattern onto ''capable,'' which follows a different idiom.', '1) Spot the adjective before the underlined portion. 2) Recall its fixed preposition partner (capable of, interested in, famous for). 3) Confirm the verb after the preposition is in its -ing form. 4) Read the full phrase aloud to verify it matches the established idiom.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7a31749e549850b4', 'act-english', 's-gram', 2, 'At its annual fan appreciation night, the Meadowlark Falls Owls handed out <u>not only free caps and</u> vouchers for discounted season tickets.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"not only free caps as well as","letter":"B"},{"is_no_change":false,"label":"not only free caps, and also","letter":"C"},{"is_no_change":false,"label":"not only free caps but also","letter":"D"}]', 'D', '{"A":"Leaves ''not only'' hanging without its required partner conjunction; a plain ''and'' cannot complete the correlative pair.","B":"Substitutes the near-synonym ''as well as'' for the fixed partner that ''not only'' demands (correlative_wrong_partner).","C":"Adds a comma and ''also,'' but the correlative pair is still broken because the fixed partner phrase never appears.","D":"Correct: ''not only'' must be completed by its fixed correlative partner, which this choice supplies."}', '**Correlative** conjunctions come in fixed pairs, and this choice completes the pair that ''not only'' opens.', '''As well as'' sounds natural in everyday speech, so students accept it as an interchangeable substitute for the fixed pair.', '1) Spot a pair-opener such as ''not only,'' ''either,'' ''neither,'' or ''both.'' 2) Recall the one fixed partner that opener requires. 3) Scan ahead in the sentence for that exact partner. 4) If any other connector sits in its place, replace it with the fixed partner. 5) Confirm the two joined elements are parallel in form.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7afd3d8cdb0ad393', 'act-english', 's-gram', 2, 'The lineup of giveaway promotions <u>were announced</u> at a press event before the home opener.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have been announced","letter":"B"},{"is_no_change":false,"label":"was announced","letter":"C"},{"is_no_change":false,"label":"are announced","letter":"D"}]', 'C', '{"A":"Matches the verb to the nearby plural ''promotions'' instead of the true singular subject ''lineup'' (sv_nearest_noun).","B":"Repeats the nearest-noun error in the perfect tense: plural ''have'' still agrees with the wrong word.","C":"Correct: the head noun ''lineup'' is singular, so it takes the singular past verb.","D":"Wrong on two counts: the verb is plural and present tense, but the subject is singular and the event already happened."}', 'The **subject** is the head noun ''lineup,'' which is singular, so the verb must be singular and past to match the completed press event.', 'The plural noun ''promotions'' sits right next to the verb, so the ear locks onto it instead of the true subject.', '1) Find the verb. 2) Ask ''who or what does this?'' and find the head noun, not the closest noun. 3) Cross out any prepositional phrase between subject and verb. 4) Match the verb''s number to the head noun. 5) Check the tense against the sentence''s time cues.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7b0a90320a7cab4d', 'act-english', 's-gram', 2, 'Before going on air, the meteorologist checks the radar loop, updates the temperature graphic, and <u>is reviewing</u> the script one final time.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"reviews","letter":"B"},{"is_no_change":false,"label":"to review","letter":"C"},{"is_no_change":false,"label":"reviewing","letter":"D"}]', 'B', '{"A":"''Is reviewing'' breaks the series of simple present verbs ''checks'' and ''updates'' (misconception: any present-time form counts as parallel).","B":"Correct: ''reviews'' matches the simple present form of the other verbs in the series.","C":"''To review'' switches the third item to an infinitive, snapping the parallel pattern (misconception: an infinitive reads as an upcoming action).","D":"''Reviewing'' is a bare participle that cannot stand as the third verb in a series of conjugated verbs (misconception: -ing forms are interchangeable with finite verbs)."}', 'Items in a series must share one grammatical form, so the third verb must be **simple present** like ''checks'' and ''updates.''', '''Is reviewing'' still sounds present-time, so students miss that the helping verb breaks the series'' matching form.', '1) Find the list and mark each item. 2) Label the grammatical form of item one. 3) Check every later item against that label. 4) Rewrite any item that wears a different form. 5) Read the full series aloud to confirm the rhythm matches.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-81ceeecf407bc4e2', 'act-english', 's-gram', 2, 'Gallery lighting is kept dim during the watercolor exhibition because prolonged exposure can <u>effect the pigments and alter they''re appearance</u> permanently.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"affect the pigments and alter they''re appearance","letter":"B"},{"is_no_change":false,"label":"effect the pigments and alter their appearance","letter":"C"},{"is_no_change":false,"label":"affect the pigments and alter their appearance","letter":"D"}]', 'D', '{"A":"Keeps both ear-spellings: ''effect'' is misused as the verb meaning ''to influence,'' and ''they''re'' is a contraction where a possessive is required.","B":"Fixes the verb but keeps ''they''re,'' a contraction of ''they are'' that cannot modify the noun ''appearance.''","C":"Fixes the possessive but keeps ''effect,'' whose verb sense means ''to bring about,'' which does not fit influencing existing pigments.","D":"Correct: the verb meaning ''to influence'' is needed after ''can,'' and the possessive determiner is needed before ''appearance.''"}', 'The sentence needs the **verb** meaning ''to influence'' plus a **possessive** determiner before the noun ''appearance.''', 'Both wrong words sound identical to the right ones when read aloud, so students who trust their ear miss one or both swaps.', '1) Circle every homophone-prone word in the span. 2) For effect/affect, ask: is it a noun (a thing) or a verb (an action of influencing)? 3) For any apostrophe word, expand the contraction (''they''re'' = ''they are'') and reread. 4) If the expansion sounds wrong, you need the possessive form instead. 5) Confirm every flagged word is fixed before choosing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-91267b839fcc2bd4', 'act-english', 's-gram', 2, 'The technical director insisted that every crew member <u>comply to</u> the safety rules posted beside the fly rail.', 'Which choice best conforms to the conventions of standard written English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"comply at","letter":"B"},{"is_no_change":false,"label":"comply for","letter":"C"},{"is_no_change":false,"label":"comply with","letter":"D"}]', 'D', '{"A":"''Comply to'' swaps in a near-sounding preposition that is not part of the fixed idiom (idiom_wrong_preposition).","B":"''Comply at'' treats the rules like a location rather than something followed (idiom_location_preposition).","C":"''Comply for'' wrongly signals purpose or benefit instead of adherence (idiom_purpose_preposition).","D":"Correct: the verb ''comply'' takes the fixed preposition ''with'' in standard English."}', '''Comply'' is an **idiom** with one fixed partner preposition, and only that pairing is standard written English.', 'Students choose ''comply to'' because ''agree to'' and ''adhere to'' sound similar, so ''to'' feels natural after a rule-following verb.', '1) Isolate the verb and its preposition. 2) Recall or test the fixed pairing in a short, familiar sentence (''Drivers ___ the speed limit''). 3) Substitute a synonym like ''follow'' to check the meaning. 4) Reject any preposition that changes the relationship to place, purpose, or direction. 5) Reread with the standard pairing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-91f26a5cebd7b585', 'act-english', 's-gram', 2, 'When inspectors examined the aging truss bridge last spring, they <u>discovered</u> hairline cracks in two of its steel joints.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"discover","letter":"B"},{"is_no_change":false,"label":"will discover","letter":"C"},{"is_no_change":false,"label":"are discovering","letter":"D"}]', 'A', '{"A":"Past tense ''discovered'' matches the past verb ''examined'' and the time marker ''last spring,'' keeping the timeline consistent.","B":"Present tense ignores the explicit past-time marker ''last spring'' (misconception: tense_ignores_time_marker).","C":"Future tense contradicts an event the sentence says already happened during a completed inspection (misconception: tense_future_for_past).","D":"Present progressive suggests the discovery is happening right now, clashing with the finished past inspection (misconception: progressive_for_completed)."}', 'The **past** tense verb matches both ''examined'' and the time marker ''last spring,'' so the original is already correct.', 'Students often shift to present tense because the cracks presumably still exist, overlooking that the sentence narrates a past event.', '1) Circle any time markers in the sentence (last spring, currently, by 2030). 2) Find the other verbs and note their tense. 3) Make the underlined verb match both the markers and the surrounding verbs. 4) Reread the whole sentence to confirm one consistent timeline.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9a5e8f822d630e4d', 'act-english', 's-gram', 2, 'Last July, the survey team snowmobiled to the glacier''s upper basin, drilled a shallow core, and <u>labels</u> each segment before the weather turned.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"will label","letter":"B"},{"is_no_change":false,"label":"labeled","letter":"C"},{"is_no_change":false,"label":"is labeling","letter":"D"}]', 'C', '{"A":"Present-tense ''labels'' breaks the past-tense sequence established by ''snowmobiled'' and ''drilled'' (tense shift within a series).","B":"Future ''will label'' contradicts a narrative of events already completed last July (future_in_past_narrative).","C":"The past-tense verb matches the other verbs in the series and the time marker ''Last July.''","D":"The present progressive describes an ongoing action, clashing with the completed past events (progressive_shift)."}', 'The series began in the past (''snowmobiled... drilled''), so the third verb must stay in the **past tense**.', '''Labels'' sounds fine in isolation, so students who read only the underlined words miss the past-tense verbs earlier in the sentence.', '1) Find every verb in the sentence. 2) Circle the time marker (here, ''Last July''). 3) Make all verbs in the same series match that time frame. 4) Reject any option that jumps to a different time without a reason.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9cbd8a204a750367', 'act-english', 's-gram', 2, 'Purists <u>insisted on preserving</u> the original verses, even when audiences clearly preferred the smoother modern arrangements.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"insisted in preserving","letter":"B"},{"is_no_change":false,"label":"insisted to preserve","letter":"C"},{"is_no_change":false,"label":"insisted for preserving","letter":"D"}]', 'A', '{"A":"Correct: the idiom is ''insist on'' followed by a gerund.","B":"''Insist in'' swaps in a near-sounding preposition that is not part of the fixed idiom.","C":"''Insist to preserve'' forces an infinitive where the idiom requires a preposition plus gerund.","D":"''Insist for'' invents a pairing that standard English does not use."}', 'Standard English pairs **insist** with the preposition ''on'' plus a gerund, exactly as written.', '''Insisted to preserve'' tempts students because many verbs (wanted, hoped, tried) do take infinitives.', '1) Identify the verb and ask whether it belongs to a fixed verb-plus-preposition pair. 2) Say the pair aloud in a simple test sentence (''She insisted ___ leaving early''). 3) Reject any preposition or verb form that breaks the fixed pattern. 4) Confirm the following verb form (gerund vs. infinitive) matches the idiom.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a59c1d9a66b839a9', 'act-english', 's-gram', 2, 'Medieval tapestry workshops prized dyes made not only from local plants <u>but on imported insects</u> such as cochineal.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"and from imported insects","letter":"B"},{"is_no_change":false,"label":"but also imported insects","letter":"C"},{"is_no_change":false,"label":"but also from imported insects","letter":"D"}]', 'D', '{"A":"Completes ''not only'' with a bare ''but'' plus the mismatched preposition ''on,'' breaking the correlative pair.","B":"Swaps in ''and,'' which cannot complete ''not only''; correlative conjunctions work only in fixed pairs.","C":"Supplies ''but also'' but drops ''from,'' so the two linked phrases are no longer parallel.","D":"Correct: ''not only...but also'' is completed, and ''from'' is repeated so both linked phrases match in form."}', '**Not only** must be completed by **but also**, and the elements joined must be parallel (''from local plants...from imported insects'').', 'Students often accept ''but also imported insects'' because the pair sounds complete even though the required preposition is missing.', '1) Spot the first half of a correlative pair (not only, either, neither, both). 2) Confirm its fixed partner appears (but also, or, nor, and). 3) Compare what follows each half word for word. 4) Make both halves the same grammatical shape, repeating the preposition if the first half has one.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b71faa75b88c9e90', 'act-english', 's-gram', 2, 'Tighten the strap so the helmet doesn''t come <u>lose</u> on the downhill.', 'Which choice is the right word for the strap''s problem?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"loose","letter":"B"},{"is_no_change":false,"label":"loosen","letter":"C"},{"is_no_change":false,"label":"lost","letter":"D"}]', 'B', '{"A":"''Lose'' is a verb (to misplace); the sentence needs a describing word.","B":"''Loose'' (rhymes with ''goose'') means not tight.","C":"''Loosen'' is an action, and ''come loosen'' isn''t English.","D":"''Come lost'' garbles the idiom ''come loose''."}', '**Loose** = not tight; **lose** = to misplace or be defeated.', 'One letter apart and pronounced almost alike, the pair swaps constantly.', 'Loose rhymes with goose (adjective); lose rhymes with snooze (verb).', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bf62b35e86d40ada', 'act-english', 's-gram', 2, 'The new dwarf saplings <u>adapted surprising quick</u> to the sandy hillside soil.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"adapted surprising quickly","letter":"B"},{"is_no_change":false,"label":"adapted surprisingly quick","letter":"C"},{"is_no_change":false,"label":"adapted surprisingly quickly","letter":"D"}]', 'D', '{"A":"Both modifiers are stuck in adjective form even though each one is doing an adverb''s job.","B":"''Quickly'' is fixed, but ''surprising'' still needs the -ly form because it modifies another modifier.","C":"''Surprisingly'' is fixed, but ''quick'' describes how the saplings adapted, so it must be an adverb.","D":"Correct: ''quickly'' modifies the verb ''adapted,'' and ''surprisingly'' modifies ''quickly,'' so both need adverb form."}', 'A word modifying a **verb** or another modifier must be an adverb, so both words here take -ly.', 'Students often fix the more obvious word and stop, leaving the other one stranded in adjective form.', '1) Find the word each modifier is describing. 2) If it describes a noun, use an adjective. 3) If it describes a verb, an adjective, or another adverb, use the -ly adverb form. 4) Check every modifier in the span, not just the first one.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c2e3cfc94b83c390', 'act-english', 's-gram', 2, 'By 1964, the campus radio hour <u>features</u> two full hours of live ballads, and touring singers competed fiercely for its Friday slot.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"will feature","letter":"B"},{"is_no_change":false,"label":"has featured","letter":"C"},{"is_no_change":false,"label":"featured","letter":"D"}]', 'D', '{"A":"Present tense clashes with the past time marker ''By 1964'' and the past-tense verb ''competed'' later in the sentence.","B":"Future tense contradicts a sentence describing events already set in 1964.","C":"Present perfect ties an action to the present moment, but this sentence is anchored entirely in the past.","D":"Correct: simple past matches both the date marker and the past-tense ''competed.''"}', 'The date marker and the later verb ''competed'' anchor the sentence in the past, so the **simple past** is required.', '''Has featured'' feels safely ''past'' to many students, but present perfect actually links the action to right now.', '1) Underline every time marker in the sentence (dates, ''by,'' ''last year''). 2) Find the other verbs and note their tense. 3) Ask: does the underlined verb sit on the same timeline? 4) If not, shift it to match the established time frame and re-read the whole sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d53bdbd643bd7b69', 'act-english', 's-gram', 2, 'Determined <u>to making</u> a fresh start, my great-uncle Emil sold his cobbler''s bench and booked third-class passage on a steamer bound for Halifax.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to have made","letter":"B"},{"is_no_change":false,"label":"for making","letter":"C"},{"is_no_change":false,"label":"to make","letter":"D"}]', 'D', '{"A":"Pairs the infinitive marker ''to'' with an -ing form, a mixed verb form that standard English rejects after ''determined.''","B":"Uses a perfect infinitive, which wrongly places the fresh start before the determination in time.","C":"Swaps the infinitive that ''determined'' idiomatically requires for a preposition-plus-gerund pattern.","D":"Correct: ''determined'' takes a plain infinitive complement, so the base verb follows ''to.''"}', 'After **determined**, English requires a plain infinitive, so the base form of the verb must follow *to*.', '''For making'' mirrors familiar patterns like ''responsible for making,'' so the preposition-plus-gerund construction sounds idiomatic.', '1) Find the governing word before the underlined verb (here, *determined*). 2) Recall which complement that word takes: infinitive, gerund, or preposition + gerund. 3) If infinitive *to* is present, put the bare base form after it — never an -ing form. 4) Check that the option does not shift the action''s time with *have* + participle. 5) Pick the option that passes every check.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e73633e49a46700b', 'act-english', 's-gram', 2, 'By the time the picking crew arrived at dawn, the frost <u>had melted</u> from the upper branches.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has melted","letter":"B"},{"is_no_change":false,"label":"melts","letter":"C"},{"is_no_change":false,"label":"will have melted","letter":"D"}]', 'A', '{"A":"Correct: past perfect ''had melted'' shows the melting was complete before the past action ''arrived.''","B":"Present perfect ''has melted'' ties the melting to the present, clashing with the past-tense ''arrived.''","C":"Simple present ''melts'' cannot describe an event finished before a past arrival.","D":"Future perfect ''will have melted'' points forward, but the sentence looks back from a past moment."}', 'Past perfect (**had** + past participle) marks an action completed before another past action.', '''Has melted'' sounds equally finished, so students miss that present perfect cannot sit behind a past-tense clause.', '1) Underline every verb and its time marker. 2) Place the events on a timeline. 3) If one past event finished before another past event, the earlier one takes ''had'' + past participle. 4) Reject any tense that points to the present or future when the anchor clause is past.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-eeedf6557d108a36', 'act-english', 's-gram', 2, 'The new policy will <u>affect</u> how employees request time off.', 'Which choice uses the right word for the sentence''s meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"effect","letter":"B"},{"is_no_change":false,"label":"affects","letter":"C"},{"is_no_change":false,"label":"effected","letter":"D"}]', 'A', '{"A":"''Affect'' is the verb meaning to influence — ''will affect how employees request time off'' is already correct.","B":"''Effect'' as a verb means to bring something about (''effect change''); it cannot take ''how employees request'' as its object.","C":"''Will affects'' stacks a conjugated verb after ''will'', which requires the base form.","D":"''Will effected'' is doubly wrong: wrong word and wrong form after ''will''."}', 'To influence something = **affect** (verb); the sentence already uses it correctly.', 'The affect/effect pair is so notorious that a correct ''affect'' invites second-guessing.', 'Affect = verb (to influence); effect = noun (a result) — and check before you ''fix'' what isn''t broken.', 'underlined-span-mc', 'second-guessing affect/effect', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fb64033d78c6ae8e', 'act-english', 's-gram', 2, 'The engine ran <u>quiet</u> after the mechanic replaced the worn belt.', 'Which choice correctly modifies how the engine ran?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"quietly","letter":"B"},{"is_no_change":false,"label":"quieter","letter":"C"},{"is_no_change":false,"label":"most quiet","letter":"D"}]', 'B', '{"A":"''Quiet'' is an adjective; it can''t describe the verb ''ran''.","B":"''Quietly'' is the adverb that correctly modifies how the engine ran.","C":"''Quieter'' is a comparative with nothing being compared here.","D":"''Most quiet'' is a superlative, also uncalled for and still adjectival."}', 'An action is described by an **adverb** — ''ran quietly'', not ''ran quiet''.', 'In casual speech ''ran quiet'' is common, so the adjective sounds acceptable.', 'Use an adverb (usually -ly) to modify a verb; save the adjective for a noun.', 'underlined-span-mc', 'using an adjective where an adverb is required', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-008e6e42275f539a', 'act-english', 's-gram', 3, 'County health codes <u>prohibit vendors to sell</u> samples that have sat unrefrigerated for more than two hours.', 'Which choice conforms to the conventions of standard written English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"prohibit vendors from selling","letter":"B"},{"is_no_change":false,"label":"prohibit that vendors sell","letter":"C"},{"is_no_change":false,"label":"prohibit vendors selling","letter":"D"}]', 'B', '{"A":"''Prohibit'' does not take a to-infinitive; this borrows the pattern of ''forbid'' (idiom_wrong_pattern).","B":"Correct — ''prohibit'' idiomatically takes an object plus ''from'' with an -ing form.","C":"Hypercorrects with a ''that'' clause, a structure ''prohibit'' does not allow (idiom_that_clause).","D":"Drops the required preposition, leaving a nonstandard shortcut (idiom_dropped_prep)."}', 'The verb **prohibit** takes the fixed pattern ''prohibit someone from doing something.''', '''Forbid vendors to sell'' is standard English, so students transfer the infinitive pattern onto ''prohibit.''', '1) Identify the verb that controls the underlined pattern. 2) Recall its fixed companion pattern by testing a familiar example (''the sign prohibits visitors ___ feeding the ducks''). 3) Eliminate any option that borrows a different verb''s pattern. 4) Eliminate any option missing the required connector. 5) Confirm the survivor reads naturally in the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-01bcf552622af4e7', 'act-english', 's-gram', 3, 'Switching to the aluminum bat made Dev''s swing <u>more faster</u> through the strike zone.', 'Which choice states the comparison without doubling it?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"more fast","letter":"B"},{"is_no_change":false,"label":"faster","letter":"C"},{"is_no_change":false,"label":"fastest","letter":"D"}]', 'C', '{"A":"''More faster'' marks the comparison twice — once with ''more'', once with ''-er''.","B":"''More fast'' uses the wrong marker for a one-syllable adjective.","C":"''Faster'' carries the whole comparison in one form.","D":"''Fastest'' is the superlative — only two swings are being compared."}', 'Use **one** comparative marker: -er OR ''more'', never both.', 'Doubling the marker feels like extra emphasis.', 'Short adjectives take -er/-est; longer ones take more/most; never stack the two.', 'underlined-span-mc', 'doubling a tense/aspect marker for emphasis', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-03e8dc4d409295fc', 'act-english', 's-gram', 3, 'Each of the drones <u>carry</u> a spare battery, while the pilots on the ground track them all at once.', 'Which choice matches the true subject of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"carries","letter":"B"},{"is_no_change":false,"label":"are carrying","letter":"C"},{"is_no_change":false,"label":"have carried","letter":"D"}]', 'B', '{"A":"The subject is ''each'', not ''drones'' — and ''each'' is singular.","B":"''Each'' takes a singular verb no matter what plural follows ''of''.","C":"''Are carrying'' agrees with the nearby plural, not the actual subject.","D":"''Have carried'' is plural and abandons the present-tense description."}', '**''Each'' is singular** — the ''of the drones'' phrase can''t change that.', 'The plural noun sits right next to the verb and pulls it plural.', 'Indefinite pronouns each/either/neither/everyone are singular; ignore the ''of the ___'' phrase.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@641234d1808d41ec98477ba4961d06d7')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-05c2f2d2e7f2d1b1', 'act-english', 's-gram', 3, 'The kangaroo rat survives the harshest dunes by drawing moisture <u>not only from its seeds and also</u> from the metabolic water its own body produces.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"both from its seeds and also","letter":"B"},{"is_no_change":false,"label":"not only from its seeds but instead","letter":"C"},{"is_no_change":false,"label":"not only from its seeds but also","letter":"D"}]', 'D', '{"A":"Opens the pair with ''not only'' but closes it with ''and also,'' which is not the fixed partner of ''not only'' (correlative_mismatch).","B":"Pairs the starter ''both'' with a finishing ''also,'' mixing two different correlative sets (correlative_mismatch).","C":"''But instead'' signals replacement, yet the sentence keeps both moisture sources as true at once (correlative_wrong_logic).","D":"Correct: ''not only ... but also'' is the complete, matched correlative pair that adds a second true source."}', 'The correlative that begins with **not only** must be completed by its fixed partner **but also**.', '''And also'' sounds like a natural way to tack on a second idea, so students accept it as the second half of the pair.', '1) Spot the opening half of a paired connector (not only, both, either, neither, whether). 2) Recall its one fixed partner (but also, and, or, nor, or). 3) Check that the finishing word actually matches that partner. 4) Confirm the two halves signal the intended logic (adding, not replacing). 5) Re-read the whole pair to hear that it locks together.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0f3de86e4912a922', 'act-english', 's-gram', 3, 'When the biologist lifted the stone away from the sea star, <u>it was covered in tiny barnacles.</u>', 'Which choice most clearly identifies what was covered in barnacles?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"this was covered in tiny barnacles.","letter":"B"},{"is_no_change":false,"label":"the stone was covered in tiny barnacles.","letter":"C"},{"is_no_change":false,"label":"they were covered in tiny barnacles.","letter":"D"}]', 'C', '{"A":"The pronoun could refer to either the object or the sea star, leaving the reference ambiguous (ambiguous_pronoun).","B":"A demonstrative is an even vaguer pointer that still fails to name which item was covered.","C":"Correct: naming the object removes all doubt about which one bore the barnacles.","D":"''They'' is plural and matches no plural noun in the sentence, adding an agreement error to the vagueness."}', 'Replacing the pronoun with the **specific noun** eliminates the ambiguity between two singular candidates.', 'The original pronoun reads smoothly, so students assume the nearest noun is obviously the referent.', '1) Find each pronoun. 2) List every noun it could point to. 3) If more than one noun fits, replace the pronoun with the intended noun. 4) Confirm number agreement between pronoun and noun.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-126b4c3b66e6f5a1', 'act-english', 's-gram', 3, 'Early studio animators <u>prided themselves in</u> completing thousands of drawings a week without a single traced frame.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"prided themselves for","letter":"B"},{"is_no_change":false,"label":"prided themselves on","letter":"C"},{"is_no_change":false,"label":"prided themselves about","letter":"D"}]', 'C', '{"A":"''Prided themselves in'' borrows the preposition from ''take pride in,'' but the reflexive verb ''pride oneself'' does not take ''in.''","B":"''Prided themselves for'' imports the pattern of ''praised for''; ''for'' is not idiomatic with ''pride oneself.''","C":"''Prided themselves on'' uses the fixed preposition that the idiom ''pride oneself on'' requires.","D":"''Prided themselves about'' follows verbs like ''bragged about,'' but ''about'' is not the preposition this idiom takes."}', 'The reflexive idiom is **pride oneself on** — a fixed pairing that cannot be swapped.', 'Because ''take pride in'' is correct English, ''prided themselves in'' sounds right by association.', '1) Spot the verb + preposition combination. 2) Ask whether the verb belongs to a fixed idiom. 3) Recall the idiom in its own dictionary form, not a related phrase''s form. 4) Test each option in that frame and keep the conventional pairing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-12bb79b0de650b29', 'act-english', 's-gram', 3, 'The volunteer <u>which</u> organized the coat drive spoke at Friday''s assembly.', 'Which choice correctly refers to the volunteer?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"what","letter":"B"},{"is_no_change":false,"label":"whom","letter":"C"},{"is_no_change":false,"label":"who","letter":"D"}]', 'D', '{"A":"''Which'' refers to things, not people.","B":"''What'' can''t introduce a clause about a person.","C":"''Whom'' is the object form — but the volunteer is the one organizing.","D":"''Who'' refers to a person doing the action of the clause."}', 'People take **who/whom**; things take which/that.', '''Which'' feels formal enough to fit anywhere.', 'Person → who (subject) / whom (object); thing → which/that.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-13f74a449d00e771', 'act-english', 's-gram', 3, 'A foundry that lost <u>their</u> master matrices could not cast replacement type for its customers.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"they''re","letter":"B"},{"is_no_change":false,"label":"it''s","letter":"C"},{"is_no_change":false,"label":"its","letter":"D"}]', 'D', '{"A":"''Their'' is plural, but the antecedent ''a foundry'' is singular.","B":"''They''re'' is the contraction of ''they are,'' which makes no sense before a noun here and is also plural.","C":"''It''s'' means ''it is''; the sentence needs a possessive, not a contraction.","D":"''Its'' is the singular possessive that matches the singular antecedent ''a foundry.''"}', 'The singular antecedent **a foundry** requires the singular possessive form of the pronoun.', 'Students default to ''their'' because everyday speech uses it for any owner, singular or plural.', '1) Find the pronoun and ask what noun it stands for. 2) Decide whether that noun is singular or plural. 3) Match the pronoun''s number to the noun''s number. 4) If the pronoun shows ownership, expand any apostrophe form into two words and re-read to catch contraction traps. 5) Re-check the sentence with the matched pronoun.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-20265f333871eebb', 'act-english', 's-gram', 3, 'After the county fair edition came back smeared, the editor phoned the pressroom manager, and <u>she promised that</u> a corrected run would be delivered by noon.', 'Which choice makes the sentence''s meaning clearest?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the manager promised that","letter":"B"},{"is_no_change":false,"label":"the manager promises that","letter":"C"},{"is_no_change":false,"label":"she had promised that","letter":"D"}]', 'B', '{"A":"''She'' could be either the editor or the manager, so the reference is ambiguous.","B":"Correct: naming ''the manager'' gives the verb one unmistakable doer in a sentence with two possible referents.","C":"Names the speaker but shifts to present tense inside a past-tense narrative.","D":"Changes the tense while keeping the ambiguous pronoun, so the real problem survives."}', 'Replacing the pronoun with **the manager** gives the promise one unmistakable maker in a sentence containing two women.', 'The original tempts readers who assume a pronoun automatically points to the nearest or most recently mentioned person.', '1) Circle the pronoun. 2) List every earlier noun it could point to. 3) If more than one candidate fits, the pronoun is ambiguous — replace it with the intended noun. 4) Keep the verb tense consistent with the surrounding narrative. 5) Re-read to confirm one clear meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-213344a491f5ec53', 'act-english', 's-gram', 3, 'In her taped interview, my grandmother described <u>packing one trunk, hiding coins in its lining, and kissing the doorframe of the house</u> before the family walked to the station.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"packing one trunk, hiding coins in its lining, and to kiss the doorframe of the house","letter":"B"},{"is_no_change":false,"label":"packing one trunk, to hide coins in its lining, and kissing the doorframe of the house","letter":"C"},{"is_no_change":false,"label":"to pack one trunk, hiding coins in its lining, and kissed the doorframe of the house","letter":"D"}]', 'A', '{"A":"Correct: all three listed actions use the same gerund form, keeping the series parallel.","B":"Breaks parallelism by switching only the third item to an infinitive after two gerunds.","C":"Switches the middle item to an infinitive, breaking the gerund series where readers check least.","D":"Mixes an infinitive, a gerund, and a past-tense verb — three different forms in one list."}', 'All three items in the series keep the same **gerund** form, so the list is already parallel.', 'Choices that alter only one item are tempting because the ear relaxes after matching items and tolerates a quiet form shift.', '1) Bracket every item in the list. 2) Label each item''s opening verb form: gerund, infinitive, or finite verb. 3) Require identical labels across all items. 4) Confirm each item still attaches sensibly to the main verb (*described*). 5) If the original already passes, resist the urge to fix it.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-243881b01bcbf58b', 'act-english', 's-gram', 3, 'By the time the first network feed reached the valley in 1927, the Cole family <u>already owns</u> a six-tube console radio.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"already owning","letter":"B"},{"is_no_change":false,"label":"has already owned","letter":"C"},{"is_no_change":false,"label":"had already owned","letter":"D"}]', 'D', '{"A":"Present tense ''owns'' clashes with the past-time frame set by ''By the time the first network feed reached the valley in 1927.''","B":"The bare participle ''owning'' leaves the clause with no finite verb at all.","C":"Present perfect ''has owned'' anchors the action to the present moment, but the sentence needs an action completed before another past event.","D":"Correct: past perfect places the family''s ownership before the 1927 arrival of the network feed, the earlier of two past events."}', 'When one past event precedes another past event, the earlier one takes the **past perfect** (had + past participle).', 'The present perfect in ''has already owned'' feels safely ''past,'' so students miss that it ties the action to now instead of to 1927.', '1) Circle every time marker (here: ''By the time... in 1927''). 2) List the two events and decide which happened first. 3) Put the earlier past event in past perfect (had + past participle) and the later one in simple past. 4) Reread the sentence to confirm the sequence sounds finished before 1927.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2b9ae16d270c28ea', 'act-english', 's-gram', 3, 'The box of winter clothes <u>were</u> stored in the attic all summer.', 'Which choice makes the subject and verb agree?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have been","letter":"B"},{"is_no_change":false,"label":"was","letter":"C"},{"is_no_change":false,"label":"are","letter":"D"}]', 'C', '{"A":"''Were'' agrees with the nearby plural ''clothes'', but the subject is the singular ''box''.","B":"''Have been'' is also plural — same trap, plus a tense shift the sentence doesn''t need.","C":"The subject is ''box'' (singular); ''was'' agrees with it.","D":"''Are'' is plural AND present tense; the sentence describes the past summer."}', 'The verb agrees with the head noun **box**, not with the closer noun in the ''of'' phrase.', 'The plural ''clothes'' sits right next to the verb, luring the ear toward ''were''.', 'Strip the prepositional phrase to find the true subject before choosing the verb.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2cf0f2170a64085a', 'act-english', 's-gram', 3, 'Coach Rivera worried that the gym''s flickering fluorescent lights <u>would affect</u> the vision system''s ability to track the reflective targets.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"would effect","letter":"B"},{"is_no_change":false,"label":"would have an affect on","letter":"C"},{"is_no_change":false,"label":"would of affected","letter":"D"}]', 'A', '{"A":"Correct: ''affect'' is the verb meaning ''to influence,'' which is exactly what the helping verb ''would'' requires.","B":"Swaps in the homophone ''effect,'' which as a verb means ''to bring about,'' not ''to influence'' (confused_homophone).","C":"Uses the a-spelling in a noun slot after ''an,'' where the noun ''effect'' would be required (affect_as_noun).","D":"Writes the ear-spelling ''would of'' for ''would have,'' putting a preposition where a helping verb belongs (would_of_ear_spelling)."}', '**Affect** is the verb meaning ''to influence,'' exactly what the helping verb ''would'' calls for here.', 'Students often reach for ''effect'' because it appears so frequently in test-style sentences about results.', '1) Decide whether the word is acting as a verb or a noun. 2) If it is a verb meaning ''to influence,'' use affect. 3) If it is a noun meaning ''a result,'' use effect. 4) Reject ''would of'' on sight — it is an ear-spelling of ''would have.''', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2dcb620c868f41b3', 'act-english', 's-gram', 3, 'By the time the city inspector arrived in October, the volunteers <u>had already rebuilt</u> the leaning stretch of fence.', 'Which choice is most acceptable in standard written English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have already rebuilt","letter":"B"},{"is_no_change":false,"label":"will have already rebuilt","letter":"C"},{"is_no_change":false,"label":"already rebuild","letter":"D"}]', 'A', '{"A":"Correct: past perfect marks an action completed before another past event (''arrived''), exactly what ''By the time... arrived'' requires.","B":"Present perfect ties the action to the present moment, clashing with the past anchor ''arrived.''","C":"Future perfect projects completion before a future point, but the inspector''s visit already happened.","D":"Simple present cannot show an action finished before a past event."}', 'An action finished before another **past** event takes the past perfect, matching the anchor ''By the time the inspector arrived.''', 'Present perfect sounds polished and complete, so students accept it without checking that the sentence''s reference point sits in the past.', '1) Find every verb and locate the sentence''s anchor event on a timeline. 2) Ask which action happened first. 3) If one past action finished before another past action, give the earlier one the past perfect. 4) Reject any form (''will,'' present tense) that points away from the anchor''s time. 5) Reread the sequence to confirm it flows earlier-to-later.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2f932283fae13943', 'act-english', 's-gram', 3, 'Lena texted Aisha that <u>she</u> had left the spare motor controller in the practice-field pits, apologizing twice for the mix-up.', 'Which choice makes it clear who was responsible for the mix-up?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Lena","letter":"B"},{"is_no_change":false,"label":"Aisha","letter":"C"},{"is_no_change":false,"label":"they","letter":"D"}]', 'B', '{"A":"''She'' could refer to either girl, leaving the reader unsure who left the part behind (ambiguous_pronoun_reference).","B":"Correct: naming the texter matches the context clue that the person apologizing caused the mix-up.","C":"Picks the wrong antecedent — the recipient would not be the one the sender apologizes to for her own error (wrong_antecedent_choice).","D":"Substitutes a plural pronoun for a single actor, creating a number-agreement error (plural_for_singular)."}', 'Naming the **texter** resolves the ambiguity and matches the context clue that the apologizer caused the mix-up.', 'The original ''she'' reads smoothly aloud, so many students never notice that two people could own the pronoun.', '1) Find every person the pronoun could name. 2) If two or more candidates fit, use context clues (who apologizes, who erred) to pick the intended one. 3) Replace the pronoun with that person''s name.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2fddf2bbbfb1b061', 'act-english', 's-gram', 3, 'The results were consistent <u>to</u> the team''s hypothesis.', 'Which choice completes the idiom correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"with","letter":"B"},{"is_no_change":false,"label":"for","letter":"C"},{"is_no_change":false,"label":"about","letter":"D"}]', 'B', '{"A":"English pairs ''consistent'' with ''with'', never ''to''.","B":"''Consistent with'' is the standard idiom.","C":"''Consistent for'' is not an English idiom.","D":"''Consistent about'' describes a person''s habits, not agreement between findings and a hypothesis."}', 'Idioms are fixed pairings: **consistent with** is the only standard form here.', '''To'' feels connective, and many adjectives do take ''to'' (similar to, equal to).', 'Learn preposition pairings as fixed units — ''consistent with'', ''capable of'', ''preoccupied with''.', 'underlined-span-mc', 'picking ''to'' because it feels connective', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3e7ea6ef8570ad4a', 'act-english', 's-gram', 3, 'Last October, the honey vendor <u>arrived before dawn and stacked</u> her jars of wildflower honey into neat pyramids before the first customers wandered in.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"arrives before dawn and stacked","letter":"B"},{"is_no_change":false,"label":"arrived before dawn and stacks","letter":"C"},{"is_no_change":false,"label":"had arrived before dawn and had stacked","letter":"D"}]', 'A', '{"A":"Correct — ''Last October'' and the later verb ''wandered'' set a simple-past frame, and both underlined verbs stay inside it.","B":"Shifts the first verb to present tense while the rest of the sentence describes a finished past morning (tense_shift_present).","C":"Shifts the second verb to present tense, splitting two simultaneous past actions across time frames (tense_shift_present).","D":"Uses past perfect although the sentence sets up no earlier-than-past sequence (unneeded_past_perfect)."}', 'The opening time marker **Last October** anchors the sentence in the simple past, and both underlined verbs already match that frame.', 'The ''had'' forms sound formal and cautious, so students assume they make past events extra correct even without an earlier-past sequence.', '1) Circle the time markers (e.g., ''Last October''). 2) List every verb in the sentence and its tense. 3) Decide whether the events occupy one time frame or two. 4) One frame → keep every verb in the same simple tense; reserve ''had + verb'' for an action completed before another past action. 5) Re-test each option against that frame.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-42a0f73fda4c2917', 'act-english', 's-gram', 3, 'Passage II — The Science of Sourdough — Bread may seem simple, but sourdough is surprisingly complex. Unlike breads made with packaged yeast, sourdough rises using wild yeast and bacteria captured from the air. Bakers maintain a "starter," a mixture of flour and water that they feed regularly. The starter, it ferments over several days. During fermentation, the microbes produce carbon dioxide, which makes the dough rise. They also produce acids, giving sourdough its tangy flavor. <u>Because of these</u> reactions, no two starters taste exactly alike. Some bakers, claim that a starter''s flavor reflects the place where it was made. A San Francisco starter, for instance, may taste different from one in Paris. Whether or not that is true, sourdough remains a small marvel of biology and patience.', 'Which choice gives the idiomatic form of the underlined connective phrase?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Because, of these","letter":"B"},{"is_no_change":false,"label":"Because these","letter":"C"},{"is_no_change":false,"label":"Being of these","letter":"D"}]', 'C', '{"A":"This option leaves or introduces an error under the tested rule.","B":"This option leaves or introduces an error under the tested rule.","C":"\"Because these reactions…\" — \"Because of these\" needs a noun, but the sentence has a clause → \"Because these.\"","D":"This option leaves or introduces an error under the tested rule."}', '"Because these reactions…" — "Because of these" needs a noun, but the sentence has a clause → "Because these."', 'The original can read smoothly until you apply the rule.', 'Rule focus: Conventions (idiom/structure)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4438b91dfcac0257', 'act-english', 's-gram', 3, 'Volunteers at the teaching apiary spend their mornings <u>checking frames, refilling feeders, and recording queen activity</u>.', 'Which choice best maintains the pattern established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"checking frames, refilling feeders, and to record queen activity","letter":"B"},{"is_no_change":false,"label":"checking frames, to refill feeders, and recording queen activity","letter":"C"},{"is_no_change":false,"label":"to check frames, refilling feeders, and record queen activity","letter":"D"}]', 'A', '{"A":"Correct: all three items in the series are -ing forms, keeping the list perfectly parallel after ''spend their mornings.''","B":"Switches the final item to an infinitive, breaking the -ing pattern set by the first two items.","C":"Drops an infinitive into the middle of an otherwise -ing series, breaking parallelism and the ''spend time doing'' idiom.","D":"Mixes three different verb shapes — infinitive, gerund, and bare form — in a single series."}', 'A series must keep one grammatical form throughout, and the original gives three matched **-ing** forms.', 'The final list slot is where students most often drift to an infinitive, so the version ending ''and to record'' feels natural to the ear.', '1) Bracket every item in the series. 2) Label each item''s grammatical form (to-form, -ing form, bare verb). 3) Confirm every label matches the first item''s. 4) Also test each item alone after the lead-in (''spend their mornings ___'') to catch idiom breaks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-45cb88c727550efa', 'act-english', 's-gram', 3, 'Of the two routes up the mountain, the eastern trail is the <u>most</u> challenging.', 'Which choice is correct for comparing the two routes?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"very","letter":"B"},{"is_no_change":false,"label":"much","letter":"C"},{"is_no_change":false,"label":"more","letter":"D"}]', 'D', '{"A":"''Most'' is the superlative — it needs three or more routes to pick from.","B":"''Very challenging'' drops the comparison the sentence explicitly sets up.","C":"''The much challenging'' is not idiomatic before a bare adjective.","D":"Exactly two things compare with the comparative: the eastern trail is the MORE challenging of the two."}', 'Two items → **comparative** (''more''); three or more → superlative (''most'').', 'Superlatives are so common in speech that ''most challenging'' sounds natural even for a pair.', 'With exactly two things, use -er/''more''; save -est/''most'' for three or more.', 'underlined-span-mc', 'reaching for a superlative when a comparative fits', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4ca399f5ad7d4209', 'act-english', 's-gram', 3, 'By the time the final round began, the young challenger <u>studies</u> hundreds of her opponent''s earlier games.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had studied","letter":"B"},{"is_no_change":false,"label":"has studied","letter":"C"},{"is_no_change":false,"label":"will have studied","letter":"D"}]', 'B', '{"A":"Present tense ignores the past time marker ''By the time the final round began,'' which sets the whole sentence in the past.","B":"Past perfect correctly places the studying before another completed past event, the start of the final round.","C":"Present perfect anchors an action to the present moment, but the sentence''s reference point is a past event.","D":"Future perfect points the action forward toward a coming deadline, the opposite of the backward-looking sequence the sentence needs."}', 'The **past perfect** places the studying before another completed past event (''began'').', '''has studied'' sounds finished, so students miss that present perfect ties an action to now rather than to a moment in the past.', '1) Find the time marker (''By the time X began''). 2) Decide when the underlined action happened relative to that marker. 3) If the action finished before a past event, use had + past participle. 4) Reread the sentence with the marker to confirm the sequence of events.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4d1a54a2511efe8a', 'act-english', 's-gram', 3, 'The instructor''s checklist covered mixing the chemistry, setting the timer, and <u>labeling each tray with tape</u>.', 'Which choice is most consistent with the structure of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to label each tray with tape","letter":"B"},{"is_no_change":false,"label":"each tray should be labeled with tape","letter":"C"},{"is_no_change":false,"label":"how each tray gets labeled with tape","letter":"D"}]', 'A', '{"A":"Correct: ''labeling'' matches the gerund pattern set by ''mixing'' and ''setting,'' keeping the series parallel.","B":"Switches the final item to an infinitive (parallel_mixed_form), breaking the -ing pattern of the first two items.","C":"Drops a complete clause into the series (clause_in_series), which cannot hang from ''covered'' the way the other items do.","D":"Wraps the item in a ''how'' clause (noun_clause_padding), abandoning the parallel gerund shape and adding needless words."}', 'The series items ''mixing'' and ''setting'' establish a **gerund** pattern, and the original third item matches it exactly.', 'The infinitive version sounds complete and purposeful on its own, so students miss that it breaks the -ing rhythm of the list.', '1) Locate the series and list its items in a column. 2) Identify the grammatical shape of the first item. 3) Check each later item against that shape. 4) Test every item by hanging it directly off the shared verb (''covered ___''). 5) Choose the option matching the established shape.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4e1741df3df63363', 'act-english', 's-gram', 3, 'The exhibits team replaced the display case''s acrylic panel after <u>it</u> yellowed in the strong summer light.', 'Which choice most clearly identifies what yellowed?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the panel","letter":"B"},{"is_no_change":false,"label":"this","letter":"C"},{"is_no_change":false,"label":"they","letter":"D"}]', 'B', '{"A":"''It'' could refer to the case or to the part that was replaced, so the reference is ambiguous.","B":"Correct: naming the specific noun removes any doubt about what yellowed.","C":"''This'' standing alone is a vague demonstrative that points at nothing specific.","D":"''They'' is plural, and no plural antecedent exists in the sentence."}', 'Restating the **specific noun** is the only revision that leaves exactly one possible reading.', 'Because the part just mentioned feels like the obvious antecedent, ''it'' seems harmless even though the case also fits.', '1) Find the pronoun and list every noun before it that agrees in number. 2) More than one candidate means the reference is ambiguous. 3) Test each revision: does it point to exactly one noun? 4) Watch for vague demonstratives (''this,'' ''that'') with no noun attached and for pronouns whose number matches nothing. 5) Prefer the revision that repeats the intended noun.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-526c2fdb8b1ca734', 'act-english', 's-gram', 3, 'After the coffee grounds go in, the compost pile smells <u>surprisingly sweet</u> to anyone walking the path.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"surprisingly sweetly","letter":"B"},{"is_no_change":false,"label":"surprising sweet","letter":"C"},{"is_no_change":false,"label":"surprising sweetly","letter":"D"}]', 'A', '{"A":"Correct: ''smells'' is a linking (sense) verb, so the adjective ''sweet'' describes the pile, and the adverb ''surprisingly'' properly intensifies that adjective.","B":"Hypercorrection: adds -ly after a linking verb, wrongly treating the description of the pile as the manner of an action.","C":"Strips the -ly from the intensifier, but only an adverb can modify the adjective ''sweet.''","D":"Reverses both jobs: the intensifier loses its needed -ly while the description gains one it must not have."}', 'After the **linking** verb ''smells,'' an adjective (''sweet'') describes the subject, and the adverb ''surprisingly'' correctly modifies that adjective.', 'Students drilled on ''verbs take adverbs'' add -ly after ''smells'' without checking whether the verb is an action or a link to a description.', '1) Find the verb and classify it: action verb or linking/sense verb (smell, taste, look, seem, remain)? 2) After a linking verb, the word describes the subject, so use an adjective. 3) Any word that intensifies an adjective must be an adverb ending in -ly. 4) Reread the pair and confirm each word modifies the right target.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5e7ccc7316357f35', 'act-english', 's-gram', 3, 'After two rained-out attempts, the astronomy club finally found a hilltop <u>sight for</u> its annual star party, far from the glow of downtown.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"cite for","letter":"B"},{"is_no_change":false,"label":"sights for","letter":"C"},{"is_no_change":false,"label":"site for","letter":"D"}]', 'D', '{"A":"Confused homophone: ''sight'' names vision or something seen, not a physical location.","B":"''Cite'' is a verb meaning to quote or reference a source, so it cannot name a place.","C":"Pluralizing the wrong homophone keeps the vision meaning; the error is meaning, not number.","D":"Correct: ''site'' is the noun meaning a place or location, which the hilltop is."}', 'The sentence needs the homophone that means **a place or location**, since the hilltop is where the event will happen.', '''Sight'' tempts students because a scenic hilltop suggests something worth seeing, so the vision word feels natural.', '1) Spot the sound-alike set: sight / site / cite. 2) Define each: sight = vision or a thing seen; site = a place; cite = to quote a source (verb). 3) Ask what the sentence needs: a thing seen, a place, or an act of quoting? 4) Match the meaning, then double-check the part of speech fits the slot.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-601502fbfbd65097', 'act-english', 's-gram', 3, 'Working alongside university partners, researchers at the observatory have <u>began</u> lowering rugged gas sensors directly into the steaming crater.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"beginning","letter":"B"},{"is_no_change":false,"label":"begun","letter":"C"},{"is_no_change":false,"label":"begin","letter":"D"}]', 'C', '{"A":"Uses the simple past form where the helping verb ''have'' requires the past participle of this irregular verb.","B":"Pairs ''have'' with an -ing form, which would need a form of ''be'' (''are beginning''), not ''have.''","C":"Correct: ''have'' plus the past participle forms the present perfect.","D":"The bare base form cannot follow ''have'' to build a perfect tense."}', '**Have** must be followed by the past-participle form of the verb to build the present perfect.', 'The simple past form sounds natural on its own, so many students never test it against the helping verb *have*.', '1) Find the helping verb (have/has/had). 2) Ask whether the next verb is in its past-participle form. 3) For irregular verbs, recite the three principal parts (base, past, participle). 4) Keep only the participle after have/has/had, then re-read the verb phrase to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-680e0c3975fd0751', 'act-english', 's-gram', 3, 'In her follow-up story on the zoning dispute, the reporter <u>cited the mayor''s principal aide</u>, who confirmed that the variance had been granted without a public hearing.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"sited the mayor''s principal aide","letter":"B"},{"is_no_change":false,"label":"cited the mayor''s principle aide","letter":"C"},{"is_no_change":false,"label":"sited the mayor''s principle aide","letter":"D"}]', 'A', '{"A":"Correct: ''cited'' means quoted as a source, and ''principal'' means chief, so both spellings match their intended meanings.","B":"Swaps in ''sited,'' which means placed at a location — the site/cite homophone confusion.","C":"Swaps in ''principle,'' a noun meaning a rule or belief, for the adjective meaning chief — the principal/principle confusion.","D":"Commits both homophone errors at once, treating sound-alike spellings as interchangeable when their meanings differ."}', 'The sentence needs **cite** (to quote as a source) and **principal** (chief), and the original supplies exactly those spellings.', '''Principle'' attracts students because the two words sound identical and both feel formal in a news story.', '1) Circle each sound-alike word in the span. 2) Say what the sentence needs it to mean (quote? place? rule? chief?). 3) Match meaning to spelling: cite = quote, site = place; principal = chief or person in charge, principle = rule. 4) Re-read the sentence with those meanings substituted and keep only the pair that fits.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-68120232d7986a74', 'act-english', 's-gram', 3, 'After Fletcher Henderson hired Louis Armstrong away from King Oliver''s band in 1924, <u>he pushed</u> the New York orchestra toward a looser, hotter rhythmic feel.', 'Which choice most clearly identifies who changed the orchestra''s sound?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"they pushed","letter":"B"},{"is_no_change":false,"label":"it pushed","letter":"C"},{"is_no_change":false,"label":"Armstrong pushed","letter":"D"}]', 'D', '{"A":"ambiguous_pronoun: *he* could point to Henderson, Armstrong, or even Oliver, so the reader must guess.","B":"*They* falsely suggests the men acted jointly and still fails to identify a clear agent.","C":"*It* has no workable antecedent — the person hired away cannot be an *it*, and a band cannot push itself.","D":"Correct: naming the trumpeter removes every competing antecedent."}', 'With three men mentioned in the sentence, only a **name** pins down the actor.', 'Readers who already know the history mentally assign *he* to the newcomer and never notice the ambiguity.', '1) Circle every noun the pronoun could point to. 2) If more than one candidate matches in number and gender, the pronoun is ambiguous. 3) Replace the pronoun with the specific noun intended. 4) Reread to confirm one — and only one — reading survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-71fc27f0504e6dc1', 'act-english', 's-gram', 3, 'The revised zoning code rewards developers for planting street trees, widening sidewalks, and <u>to include ground-floor retail</u>.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"including ground-floor retail","letter":"B"},{"is_no_change":false,"label":"the inclusion of ground-floor retail","letter":"C"},{"is_no_change":false,"label":"they include ground-floor retail","letter":"D"}]', 'B', '{"A":"The infinitive ''to include'' breaks the pattern set by the gerunds ''planting'' and ''widening.''","B":"The gerund matches the two earlier ''-ing'' items, keeping the series parallel.","C":"A ''the ___ of'' noun phrase disrupts the ''-ing'' pattern — the misconception that any noun-like form counts as parallel.","D":"A full clause with its own subject cannot sit in a series of gerund phrases after the preposition ''for.''"}', 'Items in a series must share the same grammatical form — here, **gerunds**.', 'The infinitive sounds fine in isolation, so students miss that the series already established an ''-ing'' pattern.', '1) Find the list. 2) Label the form of each item (gerund, infinitive, noun phrase, clause). 3) Identify the pattern set by the first items. 4) Convert the odd one out to match. 5) Re-read the whole series.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7312cc7e1357f22f', 'act-english', 's-gram', 3, 'The <u>row of braided challahs on the top shelf glistens</u> under the display lights every Friday afternoon.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"row of braided challahs on the top shelf glisten","letter":"B"},{"is_no_change":false,"label":"row of braided challahs on the top shelf are glistening","letter":"C"},{"is_no_change":false,"label":"rows of braided challah on the top shelf glistens","letter":"D"}]', 'A', '{"A":"Correct — the subject is the singular ''row,'' so the singular verb ''glistens'' agrees; ''of braided challahs'' is only a prepositional phrase.","B":"Matches the verb to the nearest noun ''challahs'' instead of the true subject ''row'' (sv_nearest_noun).","C":"Commits the same attraction error with a plural helping verb ''are'' for a singular subject (sv_nearest_noun_aux).","D":"Switches the subject to plural ''rows'' but keeps a singular verb, creating a fresh mismatch (sv_flipped_number)."}', 'The true subject is the singular **row**, so it takes a singular verb no matter what plural nouns sit between subject and verb.', '''Challahs'' sits right next to the verb, so the plural verb form sounds correct to the ear.', '1) Find the verb. 2) Ask ''who or what is doing this?'' to find the subject. 3) Cross out prepositional phrases between subject and verb. 4) Match the verb to the remaining subject''s number. 5) Reread the stripped sentence to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-80c993e16eba65be', 'act-english', 's-gram', 3, 'After the milk is scalded and the yolks are whisked with sugar, <u>the custard base</u> must rest overnight before it is churned into ice cream.', 'Which choice makes the reference clearest for the reader?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"it","letter":"B"},{"is_no_change":false,"label":"this","letter":"C"},{"is_no_change":false,"label":"they","letter":"D"}]', 'A', '{"A":"Correct: with milk, yolks, and sugar all in play, only the specific noun makes the subject unmistakable.","B":"Ambiguous reference: ''it'' could point to the milk or to the sugar as easily as to the finished mixture.","C":"Vague demonstrative: a bare ''this'' after a clause full of nouns names nothing in particular.","D":"Wrong number and wrong referent: the plural seems to grab ''the yolks'' and misstates what actually rests and gets churned."}', 'With **three candidate nouns** in the opening clause, only the concrete noun phrase identifies what must rest overnight.', 'After a long opening clause, a short pronoun feels less repetitive and more graceful than restating a noun.', '1) Circle the pronoun or noun in question. 2) List every earlier noun it could point to. 3) If more than one noun could claim it, a pronoun is ambiguous. 4) Replace an ambiguous pronoun with the specific noun. 5) Reread as a first-time reader to confirm only one interpretation survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-816bd1e5aa05115c', 'act-english', 's-gram', 3, 'Hootenannies invited everyone in the room to join the singing. The <u>appeal of these gatherings were</u> plain to anyone who attended: strangers arrived as spectators and left as collaborators.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"appeal of these gatherings have been","letter":"B"},{"is_no_change":false,"label":"appeals of these gathering were","letter":"C"},{"is_no_change":false,"label":"appeal of these gatherings was","letter":"D"}]', 'D', '{"A":"''Were'' agrees with the nearby plural ''gatherings'' instead of the true singular subject ''appeal.''","B":"''Have been'' is plural and also shifts into present perfect, doubling the error.","C":"Pluralizing ''appeal'' and breaking ''these gathering'' distorts the meaning and creates a new agreement error.","D":"Correct: the singular subject ''appeal'' takes the singular past verb ''was.''"}', 'The subject is the singular noun **appeal** — the phrase ''of these gatherings'' is only a modifier — so the verb must be singular.', '''Gatherings were'' sounds natural because the plural noun sits right next to the verb, hiding the real subject.', '1) Find the verb. 2) Cross out every prepositional phrase in front of it (''of these gatherings''). 3) Whatever noun is left is the subject. 4) Match the verb''s number to that noun, then re-read the sentence with the phrases restored.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-81857f7ae5f6aa04', 'act-english', 's-gram', 3, 'Passage I — Learning to Sail — The summer I turned fourteen, my uncle teached me to sail. His old wooden boat, named the <em>Osprey</em>, had belonged to my grandfather. On our first morning out, the wind was calm, and we drifted lazily across the bay. However, by noon a stiff breeze had risen, and the <em>Osprey</em> leaned hard against it. My uncle showed me how to read the wind <u>by watching</u> the surface of the water. "Dark patches mean gusts," he said, "and you must be ready." At first I was nervous, gripping the lines too tightly. But after an hour, I begun to relax. By the end of the day, I could steer the boat myself. Although I still had much to learn, I felt a new confidence. Sailing, I realized, was not about controlling the wind but about working with it.', 'Which choice gives the idiomatic phrasing of the underlined verb-plus-preposition?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"by watch","letter":"B"},{"is_no_change":false,"label":"for watching","letter":"C"},{"is_no_change":false,"label":"to watching","letter":"D"}]', 'A', '{"A":"\"read the wind by watching\" — correct gerund form.","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', '"read the wind by watching" — correct gerund form.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Conventions (idiom)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-842a62e017e2bdd1', 'act-english', 's-gram', 3, 'Audiences in 1914 gasped as Gertie the Dinosaur lumbered across the screen; Winsor McCay <u>stands</u> beside the projection each night and pretended to command his hand-drawn creature.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stood","letter":"B"},{"is_no_change":false,"label":"had stood","letter":"C"},{"is_no_change":false,"label":"is standing","letter":"D"}]', 'B', '{"A":"The present-tense ''stands'' clashes with the past-tense narrative (''gasped,'' ''pretended'') and the 1914 setting.","B":"The simple past ''stood'' matches ''gasped'' and ''pretended,'' keeping the sentence in one consistent past time frame.","C":"Past perfect ''had stood'' wrongly signals the standing was completed before another past event, but no such later reference event exists.","D":"The present progressive ''is standing'' places the action in the present moment, contradicting the past-tense verbs around it."}', 'Simple past **matches the time frame** established by ''gasped'' and ''pretended.''', '''Had stood'' sounds appropriately ''past,'' so students reach for it even though no second, later past event requires past perfect.', '1) List every verb in the sentence and its tense. 2) Identify the controlling time frame from dates and the other verbs. 3) Make the underlined verb match that frame. 4) Use past perfect only if the action must be shown finished before another past action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-844ca9d715a5310a', 'act-english', 's-gram', 3, 'After wildlife officers trapped the raccoons on the museum roof, <u>they</u> were released beside the creek at the city''s edge.', 'Which choice makes the reference in this sentence clearest?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"they all","letter":"B"},{"is_no_change":false,"label":"the animals","letter":"C"},{"is_no_change":false,"label":"these","letter":"D"}]', 'C', '{"A":"''They'' could refer to the officers or the raccoons, both plural, leaving the reference ambiguous (ambiguous_pronoun).","B":"Adding ''all'' intensifies the pronoun but does nothing to settle which plural group it points to (intensifier_not_clarity).","C":"Correct: replacing the pronoun with a specific noun makes clear that the raccoons, not the officers, were released.","D":"A vague demonstrative still leaves two plural antecedents competing for the reference (vague_demonstrative)."}', 'With two plural nouns in the first clause, only a **specific noun** — not any pronoun — makes clear who was released.', '''They'' sounds natural because readers mentally assume the raccoons, so many students never notice that the officers are an equally grammatical antecedent.', '1) Circle the pronoun. 2) List every earlier noun that matches it in number. 3) If more than one noun could be the antecedent, the pronoun is ambiguous no matter how natural it sounds. 4) Fix ambiguity by naming the intended noun, not by decorating the pronoun. 5) Re-read to confirm only one reading survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8ffa002de0ef4392', 'act-english', 's-gram', 3, 'The bookmobile serves <u>not only the rural families who lack transportation but also the retirees</u> at the Riverbend senior center.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"not only the rural families who lack transportation but also serving the retirees","letter":"B"},{"is_no_change":false,"label":"not only the rural families who lack transportation and also the retirees","letter":"C"},{"is_no_change":false,"label":"neither the rural families who lack transportation but also the retirees","letter":"D"}]', 'A', '{"A":"Correct: ''not only … but also'' is the properly matched correlative pair, and each half introduces a parallel noun phrase.","B":"Breaks parallelism by pairing the noun phrase ''the rural families'' with the participial phrase ''serving the retirees.''","C":"Substitutes the non-standard pairing ''not only … and also'' for the required ''not only … but also.''","D":"Mixes two different correlative pairs: ''neither'' demands ''nor'' and reverses the sentence''s positive meaning."}', 'The **correlative pair** ''not only … but also'' is correctly matched, and both halves introduce parallel noun phrases.', '''And also'' sounds smoothly additive to the ear, so students accept it without checking that correlatives come in fixed partnerships.', '1) Find the first half of the correlative pair (not only, either, neither, both). 2) Recall its required partner (but also, or, nor, and). 3) Confirm that exact partner appears. 4) Read the words immediately after each half. 5) If both halves introduce the same grammatical form, the sentence is parallel; if not, revise.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9ef622c2e5bb0cac', 'act-english', 's-gram', 3, 'Last October, my grandmother and I drove to the hawk lookout before sunrise. While we waited on the ridge, she <u>scanned the horizon and pointed out</u> a kestrel hovering over the frosty field.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"scans the horizon and points out","letter":"B"},{"is_no_change":false,"label":"scanned the horizon and had pointed out","letter":"C"},{"is_no_change":false,"label":"was scanning the horizon and points out","letter":"D"}]', 'A', '{"A":"Correct: both verbs stay in simple past, matching the narrative frame set by ''drove'' and ''waited.''","B":"Shifts into the present tense mid-story, breaking consistency with the past-tense frame verbs.","C":"Past perfect ''had pointed out'' falsely signals that the pointing happened before the scanning, though the actions are simultaneous.","D":"Mixes a past progressive with a present-tense verb, splitting one moment into two conflicting time frames."}', 'The surrounding narrative is anchored in the **simple past** (''drove,'' ''waited''), so both underlined verbs must remain in that tense.', 'The vivid scene lures students into the historical present, making ''scans'' and ''points out'' feel immediate even though the frame is past.', '1) Find the un-underlined verbs that set the passage''s time frame. 2) Name their tense. 3) Make every underlined verb match that tense. 4) Allow a shift only if the meaning clearly requires a different time. 5) Reject options that mix time frames within one action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a0823c6d8027ced8', 'act-english', 's-gram', 3, 'The scout <u>whom the Owls hired last April</u> once pitched in a winter league in the Dominican Republic.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"who the Owls hired last April","letter":"B"},{"is_no_change":false,"label":"whom was hired by the Owls last April","letter":"C"},{"is_no_change":false,"label":"which the Owls hired last April","letter":"D"}]', 'A', '{"A":"Correct: inside the clause, the Owls did the hiring and the pronoun receives the action, so the object form is required.","B":"Uses the subject form even though the pronoun is the object of ''hired'' (who_in_object_position).","C":"Hypercorrection: the pronoun is the subject of ''was hired,'' so the object form cannot serve there (case_hypercorrect).","D":"Applies ''which'' to a person; standard English reserves ''which'' for things and animals (which_for_person)."}', 'The pronoun is the **object** of ''hired'' — the Owls hired *him* — so the object-case relative pronoun is exactly right as written.', 'Students who rarely hear ''whom'' in conversation assume the subject form is always the safe modern default.', '1) Isolate the relative clause. 2) Rewrite it as a plain sentence using ''he'' or ''him.'' 3) If ''him'' fits (the Owls hired him), use the object form; if ''he'' fits, use the subject form. 4) Separately confirm the pronoun type matches the antecedent: people take who/whom, things take which.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a17bedc26ebf08e6', 'act-english', 's-gram', 3, 'Of the two solvent gels the paintings lab tested this spring, the citrus-based formula lifted the grime <u>more gentle</u> from the varnished tabletop.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"more gently","letter":"B"},{"is_no_change":false,"label":"gentler","letter":"C"},{"is_no_change":false,"label":"most gently","letter":"D"}]', 'B', '{"A":"''More gentle'' is an adjective form, but the word must modify the verb ''lifted,'' which requires an adverb.","B":"Correct: an adverb is needed to modify ''lifted,'' and the comparative form fits a comparison of exactly two gels.","C":"''Gentler'' is still an adjective, so it cannot describe how the formula lifted the grime.","D":"This is an adverb, but the superlative form is wrong when only two things are being compared."}', 'A word modifying the verb ''lifted'' must be an **adverb**, and comparing exactly two gels calls for the **comparative** degree.', '''More gentle'' sounds natural in speech, so students miss that it describes a noun rather than an action.', '1) Find what the underlined word modifies: a noun or a verb? 2) If it modifies a verb, you need an adverb (usually the -ly form). 3) Count the things compared: two items take the comparative (-er / ''more''); three or more take the superlative (-est / ''most''). 4) Pick the option matching both the part of speech and the degree.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ad30d90d1169598b', 'act-english', 's-gram', 3, 'The volunteers, <u>many of whom</u> had never touched a telescope before training night, were soon aligning mirrors on their own.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"many of who","letter":"B"},{"is_no_change":false,"label":"many of which","letter":"C"},{"is_no_change":false,"label":"many of them","letter":"D"}]', 'A', '{"A":"Correct: ''whom'' is the object of the preposition ''of,'' so object case is required.","B":"Case error: ''who'' is subject case, but the pronoun follows the preposition ''of.''","C":"''Which'' refers to things; the antecedent ''volunteers'' is people.","D":"''Them'' turns the interrupter into an independent clause, creating a comma splice inside the sentence."}', 'After the preposition ''of,'' the relative pronoun must be in **object case**, and it must refer to people.', '''Many of who'' tempts students who treat the pronoun as the subject of ''had never touched'' and forget the preposition in front of it.', '1) Find the pronoun''s job: is it right after a preposition? 2) If yes, object case is required. 3) Run the swap test: ''many of they'' vs. ''many of them''—whichever sounds standard maps to the matching who/whom form. 4) Confirm the pronoun matches its antecedent: person pronouns for people, ''which'' for things. 5) Read the full sentence to be sure the clause still attaches grammatically.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ae3ecf3d0595b33c', 'act-english', 's-gram', 3, 'The guild honored the dyer <u>who they credited</u> with reviving indigo fermentation.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"who they had credited","letter":"B"},{"is_no_change":false,"label":"which they credited","letter":"C"},{"is_no_change":false,"label":"whom they credited","letter":"D"}]', 'D', '{"A":"''Who'' is subject case, but the pronoun is the object of ''credited'' (''they credited her'').","B":"Shifting to past perfect changes the tense but leaves the subject-case pronoun error untouched.","C":"''Which'' cannot refer to a person; the dyer requires a personal relative pronoun.","D":"Correct: the pronoun receives the crediting (''they credited her''), so object case is required."}', 'Because ''they'' is the clause''s subject and the pronoun is the **object** of ''credited,'' object case is required.', 'The original sounds natural because spoken English rarely uses the object form of this pronoun.', '1) Isolate the relative clause. 2) Rewrite it as a plain sentence using she/her. 3) If ''she'' fits, use subject case; if ''her'' fits, use object case. 4) Confirm the pronoun refers to a person, not a thing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c978198d2132eb1d', 'act-english', 's-gram', 3, 'Before cutting a single punch, a foundry apprentice spent years learning <u>to carving</u> letterforms in soft steel.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"carve","letter":"B"},{"is_no_change":false,"label":"to carve","letter":"C"},{"is_no_change":false,"label":"to have carved","letter":"D"}]', 'C', '{"A":"''Learning to carving'' mixes the infinitive marker ''to'' with an -ing form; after ''to,'' the base verb is required.","B":"''Learning carve'' drops the infinitive marker that ''learning'' needs before a following verb.","C":"''Learning to carve'' correctly pairs the verb ''learning'' with a to + base-verb infinitive.","D":"''To have carved'' adds a perfect form that wrongly places the carving before the years of learning."}', 'After **learning**, the following action takes a to + base-verb infinitive: ''learning to carve.''', '''To carving'' sounds plausible because -ing verbs legitimately follow many other verbs, such as ''enjoy carving.''', '1) Find the main verb and the second verb that follows it. 2) If the marker ''to'' is present, the next verb must be the base form. 3) Test the pair alone: ''to'' plus the base form should sound complete. 4) Reserve ''to have'' plus a past participle for actions finished before the main verb. 5) Re-read the sentence with the corrected form.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ccb0cbb911db934d', 'act-english', 's-gram', 3, 'Riders are prohibited <u>to bring</u> glass bottles onto the pool deck.', 'Which choice completes the expression idiomatically?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"of bringing","letter":"B"},{"is_no_change":false,"label":"from bringing","letter":"C"},{"is_no_change":false,"label":"against bring","letter":"D"}]', 'C', '{"A":"''Prohibited to bring'' crosses idioms — ''forbidden TO'' but ''prohibited FROM''.","B":"''Prohibited of'' isn''t an English pattern.","C":"''Prohibited from + -ing'' is the fixed pairing.","D":"''Against bring'' mangles both the preposition and the verb form."}', 'The idiom is **prohibited from doing**, not ''prohibited to do''.', 'The parallel idiom ''forbidden to do'' bleeds into this one.', 'Learn preposition idioms as units: prohibited from, forbidden to, capable of, insist on.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d6c59e93c9aa7df3', 'act-english', 's-gram', 3, 'By the time the researchers reached the shore at dawn, the highest pools <u>already dried</u> under the summer sun.', 'Which choice best fits the sequence of events in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"already dry","letter":"B"},{"is_no_change":false,"label":"had already dried","letter":"C"},{"is_no_change":false,"label":"have already dried","letter":"D"}]', 'C', '{"A":"Simple past does not show that the drying finished before the past arrival, so a past perfect is required (tense_sequence).","B":"This drops the verb entirely, turning the clause into an ungrammatical fragment.","C":"Correct: the past perfect shows the drying was completed before the past-tense arrival.","D":"Present perfect clashes with the clearly past verb ''reached.''"}', 'An action completed **before** another past action takes the past perfect (''had'' + past participle).', 'Both events are in the past, so students use simple past for both and miss the earlier-than relationship.', '1) Identify the two past events. 2) Decide which happened first. 3) Put the earlier one in past perfect (''had'' + participle). 4) Keep the later one in simple past.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-da018a1f425ae8c7', 'act-english', 's-gram', 3, 'The <u>lineup of food trucks parked along the market''s south fence changes</u> every Saturday, depending on which owners reserve a spot.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"lineup of food trucks parked along the market''s south fence change","letter":"B"},{"is_no_change":false,"label":"lineup of food trucks parked along the market''s south fence are changing","letter":"C"},{"is_no_change":false,"label":"lineups of food trucks parked along the market''s south fence changes","letter":"D"}]', 'A', '{"A":"Correct — the singular subject ''lineup'' takes the singular verb ''changes''; the intervening phrases don''t affect agreement.","B":"Matches the verb to the nearby plural nouns ''trucks'' and ''fence'' instead of the true subject (sv_nearest_noun).","C":"Pairs the singular head noun ''lineup'' with the plural auxiliary ''are'' (sv_plural_aux).","D":"Pluralizes the subject but keeps the singular verb, creating a new mismatch (sv_forced_plural)."}', 'The head noun **lineup** is singular, and prepositional phrases between subject and verb never change agreement.', 'The plural nouns ''trucks'' and ''fence'' sit right before the verb, so the plural form sounds natural to the ear.', '1) Find the verb. 2) Ask who or what performs it. 3) Cross out every prepositional and participial phrase between subject and verb. 4) Match the verb''s number to the bare subject that remains. 5) Re-test each option against that bare pairing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dc4472aefce116fe', 'act-english', 's-gram', 3, 'Rangers measuring Grinnell Glacier in Glacier National Park found that the ice <u>had shrank</u> to half of its 1966 footprint.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had shrinked","letter":"B"},{"is_no_change":false,"label":"has shrank","letter":"C"},{"is_no_change":false,"label":"had shrunk","letter":"D"}]', 'D', '{"A":"Uses the simple past ''shrank'' where the past-perfect helper ''had'' requires the past participle.","B":"Invents a regular ''-ed'' participle for a verb that is irregular in every form.","C":"Swaps the helper without fixing the form: ''shrank'' is still not a participle, and the present-perfect helper misstates an already-completed event.","D":"Correctly pairs the helper ''had'' with the past participle of the irregular verb."}', 'After the helping verb **had**, an irregular verb must appear in its past-participle form.', '''Had shrank'' sounds acceptable because the simple past form appears constantly in speech while the participle rarely does.', '1) Spot a helping verb (has/have/had) before the main verb. 2) Recite the verb''s three forms: base, simple past, past participle. 3) After has/have/had, use only the third form. 4) If the correct pairing sounds odd, trust the verb chart, not your ear.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ea7b624cd42ec31e', 'act-english', 's-gram', 3, 'The mural committee wanted a design that was not only colorful <u>but</u> durable enough for the north wall.', 'Which choice completes the paired conjunction correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"yet","letter":"B"},{"is_no_change":false,"label":"and also","letter":"C"},{"is_no_change":false,"label":"but also","letter":"D"}]', 'D', '{"A":"''Not only'' promises its full partner — bare ''but'' breaks the pair.","B":"''Yet'' signals contrast, and the pair still goes unfinished.","C":"''And also'' isn''t the partner ''not only'' takes.","D":"''Not only ... but also'' is the complete correlative pair."}', 'Correlative conjunctions come in **fixed pairs**: not only ... but also.', '''But'' alone carries most of the meaning, so the missing ''also'' is easy to drop.', 'Complete the pair: either/or, neither/nor, both/and, not only/but also.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-eec115160c96dacd', 'act-english', 's-gram', 3, 'The system of counterweights hidden inside the bascule bridge <u>allows</u> its massive deck to swing upward in under two minutes.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"allow","letter":"B"},{"is_no_change":false,"label":"are allowing","letter":"C"},{"is_no_change":false,"label":"have allowed","letter":"D"}]', 'A', '{"A":"The subject''s head noun ''system'' is singular, so the singular verb ''allows'' agrees with it.","B":"Matches the verb to the nearby plural noun ''counterweights'' instead of the true subject ''system'' (misconception: sv_nearest_noun).","C":"Uses a plural verb and a progressive form, doubling the error: the subject is singular and the capability is permanent, not in progress (misconception: sv_nearest_noun_progressive).","D":"Plural perfect ''have allowed'' agrees with the intervening noun rather than the singular head noun ''system'' (misconception: sv_nearest_noun_perfect)."}', 'The verb must agree with the **head noun** of the subject — ''system,'' which is singular — not with nouns inside the prepositional phrase.', 'The plural noun ''counterweights'' sits right before students'' eyes, so many match the verb to it instead of to the true subject.', '1) Find the verb. 2) Ask ''who or what is doing this?'' and locate the subject''s head noun. 3) Cross out every prepositional phrase between subject and verb. 4) Match the verb''s number to the head noun alone. 5) Reread the stripped-down sentence to confirm the match.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f07da4c61d9f2c33', 'act-english', 's-gram', 3, 'Each of Bryce Canyon''s horseback guides must renew <u>their</u> outfitter permit before the summer season begins.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"his or her","letter":"B"},{"is_no_change":false,"label":"its","letter":"C"},{"is_no_change":false,"label":"one''s","letter":"D"}]', 'B', '{"A":"Matches the plural noun ''guides'' inside the prepositional phrase instead of the true singular subject ''Each.''","B":"Agrees in number with the singular pronoun ''Each'' and correctly refers to people.","C":"Is singular but refers to things, not to human guides.","D":"Shifts to the impersonal ''one'' even though the sentence names specific guides."}', 'The subject is **Each**, a singular pronoun, so the possessive that follows must be singular and refer to people.', 'The plural noun ''guides'' sits closest to the pronoun, luring students into matching the nearest noun instead of the true antecedent.', '1) Find the pronoun and ask what noun it stands for. 2) Cross out any ''of the ...'' phrase after words like each, either, neither, every. 3) Match the pronoun''s number to what remains. 4) Confirm the pronoun''s type fits the antecedent (person vs. thing).', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f0f3698908251c91', 'act-english', 's-gram', 3, 'Each of the twelve solar-powered stations along the ridge transmits <u>their</u> readings to the observatory every ten seconds.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"it''s","letter":"B"},{"is_no_change":false,"label":"its","letter":"C"},{"is_no_change":false,"label":"they''re","letter":"D"}]', 'C', '{"A":"''Their'' is plural, but the true antecedent ''each'' is singular, so the pronoun disagrees in number.","B":"''It''s'' is the contraction of ''it is,'' not a possessive, so it cannot show ownership of the readings.","C":"Correct: a singular possessive pronoun matches the singular antecedent ''each.''","D":"''They''re'' means ''they are'' — a plural contraction, not a possessive of any kind."}', '**Each** is grammatically singular, so the possessive pronoun referring to it must be singular.', 'The plural noun *stations* sits right beside the pronoun''s slot, luring students into matching the nearest noun instead of the true antecedent *each*.', '1) Find the pronoun and ask what it stands for. 2) Trace back to the true antecedent — with ''each of the X,'' the antecedent is *each*, not X. 3) Decide singular or plural from that antecedent. 4) Separately test any apostrophe by expanding it (''it is'' / ''they are'') and re-reading the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f4cd185c2f8bd320', 'act-english', 's-gram', 3, 'By the time the maintenance crew reached the stadium lights last April, the monk parakeets <u>already rebuilt</u> the nest cleared away in March.', 'Which choice most logically fits the time relationship in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had already rebuilt","letter":"B"},{"is_no_change":false,"label":"have already rebuilt","letter":"C"},{"is_no_change":false,"label":"already rebuild","letter":"D"}]', 'B', '{"A":"Simple past leaves the order of the two past events unmarked after ''By the time,'' which demands the earlier action be flagged (simple_past_for_earlier_event).","B":"Correct: the rebuilding finished before the crew''s past-tense arrival, so the earlier event takes the past perfect.","C":"Present perfect ties the action to the present moment, clashing with the finished time frame of ''last April'' (present_perfect_in_past_frame).","D":"Present tense cannot describe an action completed before a past event (tense_shift_to_present)."}', '''By the time'' signals two sequenced past events, and the **earlier** one — the rebuilding — must take the past perfect.', 'Simple past sounds complete on its own, so students miss that ''By the time'' requires the earlier action to be explicitly marked as prior.', '1) Find every time cue (here: ''By the time,'' ''last April,'' ''in March''). 2) Identify the two events and decide which finished first. 3) Put the later event in simple past. 4) Mark the earlier event with ''had'' + past participle. 5) Re-read to confirm the order is unmistakable.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f5c6aff35511a39f', 'act-english', 's-gram', 3, 'In a classic beurre blanc, the sharpness of the reduced white wine <u>compliments</u> the sweetness of the slowly whisked butter.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"complements","letter":"B"},{"is_no_change":false,"label":"complimented","letter":"C"},{"is_no_change":false,"label":"complemented","letter":"D"}]', 'B', '{"A":"Confused homophone: the spelling with i means ''praises,'' but the flavors complete and enhance each other, so the praise word is wrong.","B":"Correct: the spelling with e means ''completes or enhances,'' the intended meaning, and the present tense matches the sentence''s timeless description.","C":"Doubles the error: it keeps the praise meaning and also shifts into past tense, clashing with the present-tense description.","D":"Right word, wrong tense: the past tense clashes with the sentence''s present-tense account of how the sauce always works."}', 'The verb meaning **completes or enhances** (spelled with an e) fits the flavor relationship, and its present tense matches the rest of the sentence.', 'The praise spelling with *i* is far more common in everyday writing, so it looks correct by sheer familiarity.', '1) Ask what the sentence means: is one thing praising another, or completing it? 2) If it means praise, use the spelling with *i* (as in ''I pay a compliment''). 3) If it means to complete or enhance, use the spelling with *e* (as in compl*e*te). 4) Finally, confirm the verb tense matches the surrounding sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0c1789eb6711c6f2', 'act-english', 's-gram', 4, 'The docent led us through the fossil hall, pointed out the juvenile triceratops, and <u>explains</u> how the dig team dated the site.', 'Which choice keeps the tour''s verbs consistent?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"explaining","letter":"B"},{"is_no_change":false,"label":"explained","letter":"C"},{"is_no_change":false,"label":"will explain","letter":"D"}]', 'C', '{"A":"Two past verbs then a present one — the last leg jumps time frames.","B":"''Explaining'' breaks the parallel finite-verb series.","C":"''Explained'' completes the past-tense series ''led ... pointed ... explained''.","D":"Future tense contradicts a tour already being narrated."}', 'Verbs in one narrated sequence stay in **one tense**.', 'The explanation feels ongoing, so present tense sneaks in.', 'Series of actions by one subject: keep every verb in the frame the first verbs set.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0dd81c2f4784d419', 'act-english', 's-gram', 4, 'In 1981, marine biologists on the Great Barrier Reef documented mass coral spawning for the first time; until that night, most researchers <u>have assumed</u> that corals released their eggs quietly throughout the year.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had assumed","letter":"B"},{"is_no_change":false,"label":"assume","letter":"C"},{"is_no_change":false,"label":"would have assumed","letter":"D"}]', 'B', '{"A":"Present perfect claims the assumption continues into the present, but ''until that night'' seals the belief in the past (misconception: present_perfect_for_completed_past).","B":"Past perfect correctly places the outdated belief before the 1981 documentation, matching the ''until that night'' cutoff.","C":"Present tense contradicts the passage''s past time frame set by the 1981 date (misconception: general_truth_present).","D":"''Would have'' injects a hypothetical condition the sentence never states; the belief really existed (misconception: would_have_for_real_past)."}', 'Past perfect marks a belief that ended **before** another past event — the 1981 documentation.', '''Have assumed'' sounds natural read aloud, but present perfect quietly claims the assumption still holds today.', '1) Find the time anchors in the sentence (here, a dated past event). 2) Ask whether the underlined action ended before, during, or after that anchor. 3) If it ended before another past event, use past perfect (had + past participle). 4) Reject any tense that drags the action into the present or adds a hypothetical the sentence never states.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1010bec9dae21ba6', 'act-english', 's-gram', 4, 'By the time Benny Goodman''s orchestra reached the Palomar Ballroom in August 1935, late-night radio broadcasts <u>already spread</u> its swing arrangements to West Coast listeners.', 'Which choice best fits the sequence of events in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have already spread","letter":"B"},{"is_no_change":false,"label":"already spreads","letter":"C"},{"is_no_change":false,"label":"had already spread","letter":"D"}]', 'D', '{"A":"tense_sequence: simple past *spread* fails to show that the broadcasts happened *before* the band''s arrival.","B":"Present perfect *have spread* anchors the action to the present, clashing with the 1935 time frame.","C":"Present-tense *spreads* drops the narration out of the past entirely and mismatches the plural subject.","D":"Correct: past perfect *had spread* marks the earlier of two past events signaled by *By the time*."}', '**Past perfect** marks the earlier of two completed past actions.', 'Because *spread* looks identical in present and past tense, the simple past feels adequate and the missing helper goes unnoticed.', '1) Find both events and put them on a timeline. 2) Spot a sequencing signal like *by the time*, *before*, or *after*. 3) Give the earlier event *had* plus the past participle. 4) Keep the later event in simple past. 5) Reread the timeline to confirm the order is audible.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1500034520149f4a', 'act-english', 's-gram', 4, 'When marine biologists tag great white sharks, <u>they</u> often travel hundreds of miles before returning to the same feeding grounds.', 'Which choice most clearly identifies who travels hundreds of miles?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"it","letter":"B"},{"is_no_change":false,"label":"the sharks","letter":"C"},{"is_no_change":false,"label":"the biologists","letter":"D"}]', 'C', '{"A":"''They'' could refer to either the biologists or the tagged animals, leaving the subject ambiguous (ambiguous_pronoun).","B":"''It'' is singular and cannot stand for a plural group, so it disagrees and stays unclear (pronoun_number).","C":"Correct: naming the animals removes the ambiguity and matches the intended meaning that the tagged animals travel.","D":"Names the wrong referent; the scientists are not the ones migrating hundreds of miles (wrong_referent)."}', 'Replacing the vague pronoun with a specific **noun** fixes which of the two plural groups actually travels.', '''They'' reads smoothly and students assume the nearest plausible noun is obvious, overlooking the second candidate.', '1) Find the pronoun and list every noun it could point to. 2) If more than one noun fits, the pronoun is ambiguous. 3) Replace it with the noun that logically performs the action. 4) Confirm the replacement agrees in number.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-21843d9d64d8ea6e', 'act-english', 's-gram', 4, 'The lineup of challengers seeking the three qualifying spots <u>have narrowed</u> steadily since the opening weekend.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has narrowed","letter":"B"},{"is_no_change":false,"label":"have been narrowing","letter":"C"},{"is_no_change":false,"label":"are narrowed","letter":"D"}]', 'B', '{"A":"The plural verb agrees with the nearby nouns ''challengers'' and ''spots'' instead of the true singular subject ''lineup.''","B":"The head subject is the singular ''lineup,'' so the singular verb is required despite the plural nouns packed in between.","C":"Switching to a progressive form does not fix the agreement error: the verb is still plural while the subject is singular.","D":"The passive construction misreads the sentence''s gradual, active shrinking and still pairs a plural verb with a singular subject."}', 'The subject is the singular **lineup**, so the verb must be singular.', '''challengers'' and ''spots'' sit right before the verb, luring the ear into plural agreement with the wrong noun.', '1) Find the verb. 2) Ask ''who or what does this?'' and cross out prepositional and participial phrases (''of challengers,'' ''seeking the three qualifying spots''). 3) Match the verb to that bare subject''s number. 4) Reread subject and verb alone to confirm they agree.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-49ef91abd4738e50', 'act-english', 's-gram', 4, 'Jordan texted Marcus every day while <u>he</u> was at wilderness camp.', 'Which choice makes clear who was away at camp?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"him","letter":"B"},{"is_no_change":false,"label":"Marcus","letter":"C"},{"is_no_change":false,"label":"himself","letter":"D"}]', 'C', '{"A":"''He'' could be Jordan or Marcus — the reader can''t tell who left.","B":"''Him'' is the wrong case for a subject and no clearer.","C":"Repeating the name removes the ambiguity.","D":"''Himself'' needs a matching subject in its own clause."}', 'When a pronoun could point at **either person**, use the name.', 'The writer knows who went to camp, so the pronoun feels clear.', 'A pronoun must have exactly ONE possible antecedent — otherwise name the person.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4da5835d6029dc50', 'act-english', 's-gram', 4, 'The field ecologist <u>who</u> the university had hired analyzed every water sample twice before recording her results.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"whom","letter":"B"},{"is_no_change":false,"label":"whose","letter":"C"},{"is_no_change":false,"label":"who''s","letter":"D"}]', 'B', '{"A":"Uses the subject form, but the pronoun is the object of ''had hired,'' which calls for the object form (case_subject_for_object).","B":"Correct: the pronoun is the direct object of ''had hired'' (''the university had hired her''), so the object form is required.","C":"A possessive form that would signal ownership the sentence never expresses (possessive_for_object).","D":"A contraction of ''who is,'' which cannot serve as the object of the verb (contraction_for_pronoun)."}', 'The pronoun functions as the **object** of ''had hired'' (the university hired her), so the objective case form is required.', 'The pronoun sits near the front of the clause where subjects usually appear, so it feels like a subject even though a later verb acts on it.', '1) Isolate the clause the pronoun belongs to. 2) Find that clause''s own subject and verb (here: ''the university had hired''). 3) Ask whether the pronoun does the action or receives it. 4) If it receives the action, use the object form; if it does the action, use the subject form. 5) Replace with ''he/him'' to test: ''him'' means use the object form.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4ebc4b2a334ed7ae', 'act-english', 's-gram', 4, 'Before raising the alert level, analysts confirm that tremor is intensifying, that the ground is swelling, and <u>gas output has risen</u>.', 'Which choice best completes the series in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gas output rising","letter":"B"},{"is_no_change":false,"label":"that gas output rising","letter":"C"},{"is_no_change":false,"label":"that gas output has risen","letter":"D"}]', 'D', '{"A":"Drops the ''that'' carried by the first two items in the series, breaking the parallel pattern of that-clauses.","B":"Substitutes an -ing phrase with no ''that'' and no finite verb, so it is doubly non-parallel.","C":"Restores ''that'' but leaves the clause without a complete finite verb, so it still cannot match the pattern.","D":"Correct: it matches the series exactly — ''that'' + subject + finite verb."}', 'The list is a series of **that**-clauses, so the final item must also be a *that*-clause with its own complete verb.', 'Dropping the final *that* sounds natural in casual speech, so the missing marker is easy to overlook after two long clauses.', '1) Find the series and read each item in isolation. 2) Write down the pattern the first item sets (here: that + subject + verb). 3) Test every later item against that pattern slot by slot. 4) Fix the item that deviates, then re-read the whole series.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-50b4dfc045bf65f3', 'act-english', 's-gram', 4, 'By the time the judges reached our booth, the glue <u>dried</u> and the bridge model held its full load.', 'Which choice shows the drying happened before the judges arrived?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had dried","letter":"B"},{"is_no_change":false,"label":"has dried","letter":"C"},{"is_no_change":false,"label":"was drying","letter":"D"}]', 'B', '{"A":"Plain past puts the drying and the arrival at the same moment.","B":"Past perfect ''had dried'' sets the drying BEFORE the past arrival.","C":"''Has dried'' ties the drying to the present, not to that past moment.","D":"''Was drying'' means the glue was still wet — the opposite of the point."}', '**Past perfect** (''had'' + participle) marks the earlier of two past events.', 'Simple past feels sufficient because both events are over.', '''By the time X happened, Y HAD happened'' — the earlier past takes ''had''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-54d1e04fc64fc59f', 'act-english', 's-gram', 4, 'The dense network of symbiotic algae packed inside a coral''s translucent tissues <u>supply</u> the animal with up to ninety percent of its energy.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"are supplying","letter":"B"},{"is_no_change":false,"label":"supplies","letter":"C"},{"is_no_change":false,"label":"have supplied","letter":"D"}]', 'C', '{"A":"The plural verb agrees with the nearby nouns ''algae'' and ''tissues'' instead of the true singular subject ''network'' (misconception: sv_nearest_noun).","B":"Still plural, and the progressive aspect is wrong for a standing biological fact (misconception: sv_nearest_noun plus needless progressive).","C":"The singular verb agrees with the head noun of the subject, ''network,'' once the prepositional phrases are stripped away.","D":"Plural again, and the perfect aspect wrongly treats an ongoing general truth as a completed past action (misconception: sv_nearest_noun plus tense shift)."}', 'The verb must agree with the **head noun** of the subject — the singular ''network'' — not with nouns inside prepositional phrases.', 'The plural nouns ''algae'' and ''tissues'' sit directly before the verb, luring the ear toward a plural form.', '1) Find the verb. 2) Cross out every prepositional phrase between the start of the subject and the verb. 3) The noun left standing is the true subject — mark it singular or plural. 4) Match the verb''s number to that noun. 5) Separately confirm the tense fits a general fact (simple present) rather than a finished or ongoing event.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-62b1c68bb839c79c', 'act-english', 's-gram', 4, 'By the time the 1900 hurricane reached the Texas coast, forecasters at the national office <u>have dismissed</u> the warnings that Cuban meteorologists had cabled days earlier.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"will have dismissed","letter":"B"},{"is_no_change":false,"label":"were dismissing","letter":"C"},{"is_no_change":false,"label":"had dismissed","letter":"D"}]', 'D', '{"A":"Present perfect ''have dismissed'' ties the action to the present moment, but the sentence is anchored to a past event in 1900 (misconception: present perfect for remote past).","B":"Future perfect ''will have dismissed'' points to completion before a future moment, yet every event here is past (misconception: any perfect form fits ''by the time'').","C":"Past progressive ''were dismissing'' portrays the action as ongoing at landfall, but ''days earlier'' shows it was already complete (misconception: progressive equals past-sounding vividness).","D":"Past perfect ''had dismissed'' correctly marks an action completed before another past event, the landfall."}', '**Past perfect** places the dismissal before the landfall, the sentence''s other past event.', '''Were dismissing'' sounds convincingly past, so students accept it without checking whether the action was already finished before landfall.', '1) Find the time anchor (''By the time X happened...''). 2) Ask: was the underlined action finished before that anchor? 3) If yes, use past perfect (had + past participle). 4) If it was ongoing at the anchor, use past progressive; if simultaneous, simple past. 5) Re-read the sentence to confirm the sequence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b3cb1466d4fe293', 'act-english', 's-gram', 4, 'The chorus of chickadees and nuthatches at the feeding station <u>grows</u> louder whenever fresh suet appears.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"grow","letter":"B"},{"is_no_change":false,"label":"are growing","letter":"C"},{"is_no_change":false,"label":"have grown","letter":"D"}]', 'A', '{"A":"Correct: the head noun ''chorus'' is singular, so the singular verb ''grows'' agrees with it.","B":"Matches the nearby plural nouns ''chickadees and nuthatches'' instead of the true subject, ''chorus.''","C":"Uses the plural ''are'' for a singular subject and adds a progressive form where ''whenever'' calls for a habitual simple verb.","D":"Uses plural ''have'' for the singular ''chorus'' and imposes a completed-action tense on a repeated habit."}', 'Strip away the prepositional phrases and the subject is **chorus** — singular — so it takes a singular verb.', 'The plural nouns ''chickadees and nuthatches'' sit right beside the verb, tempting students to match the nearest noun rather than the head noun.', '1) Find the verb. 2) Ask ''who or what does this?'' 3) Cross out every prepositional phrase (''of...'', ''at...'') between subject and verb. 4) Match the verb to the head noun that remains. 5) Ignore any noun inside the crossed-out phrases, no matter how close it sits to the verb.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6fae17a2143e9de6', 'act-english', 's-gram', 4, 'Neither of the cider barns, which have stood beside the packing shed since the 1920s, has lost <u>their roofs</u> to a winter storm.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"their roof","letter":"B"},{"is_no_change":false,"label":"they''re roofs","letter":"C"},{"is_no_change":false,"label":"its roof","letter":"D"}]', 'D', '{"A":"''Their roofs'' treats the singular subject ''neither'' as plural, matching the nearby plural ''barns'' instead.","B":"''Their'' still agrees with the nearest noun rather than with the singular pronoun ''neither.''","C":"''They''re'' is the contraction of ''they are,'' not a possessive, and the plural reference is wrong anyway.","D":"Correct: ''neither'' is singular, so the singular possessive ''its'' and singular ''roof'' agree with it."}', '**Neither** is grammatically singular, so the pronoun referring back to it must be singular.', 'The plural ''barns'' sits close to the pronoun, luring students into plural agreement with the wrong word.', '1) Find the pronoun''s true antecedent, not the nearest noun. 2) Cross out interrupting phrases (''of the...'', ''which...''). 3) Classify the antecedent as singular or plural (neither, either, each = singular). 4) Match the pronoun''s number, then confirm it is a true possessive rather than a contraction.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7070a01806030576', 'act-english', 's-gram', 4, 'By the time the research vessel reached the trench, the submersible <u>had already descended</u> two thousand meters into the dark water.', 'Which choice best maintains the logical sequence of events?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has already descended","letter":"B"},{"is_no_change":false,"label":"already descended","letter":"C"},{"is_no_change":false,"label":"was already descending","letter":"D"}]', 'A', '{"A":"Correct: the past perfect marks the descent as finished before the past event of the vessel arriving.","B":"Present perfect links a past action to the present, clashing with the all-past narrative anchored by ''reached'' (tense_shift).","C":"Simple past places both actions side by side, losing the order that the descent came first (lost_sequence).","D":"The progressive frames the descent as ongoing, but ''already'' signals it was completed (wrong_aspect)."}', 'When one past action finishes before another past action, the earlier one takes the **past perfect** (''had'' + past participle).', 'The simple past feels natural and students forget that ''by the time'' demands a marker for the earlier of two past events.', '1) Identify the two past events and which happened first. 2) Put the earlier, already-completed action in the past perfect (''had'' + participle). 3) Keep the later action in the simple past. 4) Check that ''by the time'' is paired with the past-perfect action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-76d4f54138f5b40d', 'act-english', 's-gram', 4, 'By the time the doors opened on Saturday morning, the volunteers <u>had already began sorting</u> a mountain of weekend donations.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have already begun sorting","letter":"B"},{"is_no_change":false,"label":"had already begun sorting","letter":"C"},{"is_no_change":false,"label":"had already began to sort","letter":"D"}]', 'C', '{"A":"Uses the simple past *began* where the past-perfect construction requires the past participle *begun*.","B":"Supplies the right participle but shifts to present perfect, which clashes with the past-time frame set by ''By the time the doors opened.''","C":"Correct: past perfect *had* plus the past participle *begun* places the sorting before the doors opened.","D":"Keeps the wrong participle *began* and swaps the natural gerund for an infinitive, so the verb form is still broken."}', 'After the helping verb *had*, the verb must take its **past participle** form, which for this verb is *begun*.', '*Began* sounds familiar as a past tense, so pairing it with *had* feels natural even though the participle is required.', '1) Find the helping verb (had/has/have). 2) A helping verb demands the past participle, not the simple past. 3) Recite the trio for the verb (begin-began-begun). 4) Check that the tense matches the sentence''s time frame. 5) Pick the option that satisfies both.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7cefc761af9cfd40', 'act-english', 's-gram', 4, 'Every one of the donated appliances is tested and tagged before <u>they are</u> placed on the sales floor.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"they were","letter":"B"},{"is_no_change":false,"label":"it is","letter":"C"},{"is_no_change":false,"label":"it was","letter":"D"}]', 'C', '{"A":"Matches the pronoun to the nearby plural *appliances* instead of the singular subject *Every one*.","B":"Doubles the error: plural pronoun plus a past-tense verb in a sentence describing a routine, present-time process.","C":"Correct: the antecedent *Every one* is singular, and the present tense matches the habitual testing routine.","D":"Gets the singular pronoun right but shifts to past tense, breaking the sentence''s present-time description."}', 'The true antecedent is the singular **Every one**, so the pronoun must be singular and stay in the present tense.', 'The plural noun *appliances* sits right before the pronoun, luring the ear toward a plural match.', '1) Find the pronoun. 2) Ask exactly which noun it stands for — not the closest noun, the logical one. 3) Strip prepositional phrases like ''of the donated appliances.'' 4) Match the pronoun''s number to that antecedent. 5) Confirm the verb tense matches the rest of the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-93356570e79e6da7', 'act-english', 's-gram', 4, 'New harbor regulations prohibit charter captains <u>to anchor</u> anywhere along the shallow reef flat, where a single dragged chain can shear off decades of growth.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"from anchoring","letter":"B"},{"is_no_change":false,"label":"in anchoring","letter":"C"},{"is_no_change":false,"label":"against anchoring","letter":"D"}]', 'B', '{"A":"The infinitive follows the pattern of ''forbid,'' but ''prohibit'' never takes an infinitive (misconception: idiom_pattern_transfer_forbid).","B":"Standard English fixes the idiom as ''prohibit someone from doing something.''","C":"''In'' belongs to verbs like ''succeed'' and ''persist,'' not ''prohibit'' (misconception: wrong_fixed_preposition).","D":"''Against'' transfers from warning verbs like ''warn'' and ''advise''; a legal ban uses a different fixed preposition (misconception: idiom_pattern_transfer_warn)."}', 'The verb ''prohibit'' is **idiomatically fixed**: it takes its own required preposition plus an ''-ing'' form, never an infinitive.', '''Forbid captains to anchor'' is standard, so students transfer that infinitive pattern onto the near-synonym ''prohibit.''', '1) Circle the verb and the word(s) that follow it. 2) Recall the verb''s fixed pattern by testing it in a simple sentence you trust. 3) Check whether near-synonyms (''forbid,'' ''warn'') use a different pattern — do not borrow theirs. 4) Choose the option matching the verb''s own idiom, not one built from logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-946487d7698b924e', 'act-english', 's-gram', 4, 'Composing a page by hand meant plucking each letter from its case, aligning it in the stick, and <u>to lock the finished lines</u> into a heavy iron chase.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"locking the finished lines","letter":"B"},{"is_no_change":false,"label":"the finished lines were locked","letter":"C"},{"is_no_change":false,"label":"to have locked the finished lines","letter":"D"}]', 'B', '{"A":"''To lock'' breaks the -ing pattern established by ''plucking'' and ''aligning.''","B":"''Locking'' matches the -ing form of the other two items in the series.","C":"This passive clause abandons the list structure altogether, leaving the series unbalanced.","D":"''To have locked'' is both a non-matching infinitive and a perfect form that misorders the actions."}', 'Items in a series must share one grammatical shape; the third action must **match** ''plucking'' and ''aligning.''', '''To lock'' tempts because infinitives often express purpose, and securing the chase feels like the goal of the whole process.', '1) Locate the series and list each item. 2) Label each item''s form: -ing, infinitive, or clause. 3) Identify the form the first items establish. 4) Rewrite the odd item to copy that form exactly. 5) Re-read the full series to confirm the rhythm matches.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-95b3cf2541e5b0b8', 'act-english', 's-gram', 4, 'After the hitting coach reviews video with each young slugger, <u>the coach</u> records the agreed-upon swing adjustments in a shared notebook.', 'Which choice makes the meaning of the sentence clearest?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"he","letter":"B"},{"is_no_change":false,"label":"they","letter":"C"},{"is_no_change":false,"label":"this","letter":"D"}]', 'A', '{"A":"Correct: with two possible people in the first clause, repeating the noun is the only way to make the recorder unmistakable.","B":"''He'' could refer to either the coach or the slugger, leaving the doer ambiguous (pronoun_two_referents).","C":"''They'' either invents a joint actor the sentence never establishes or leaves the recorder vague (vague_plural_pronoun).","D":"''This'' is a bare demonstrative with no noun to stand for, so the doer disappears entirely (demonstrative_no_antecedent)."}', 'With two candidates in the opening clause, only the **repeated noun** leaves zero doubt about who keeps the notebook.', 'Students trained to avoid repetition reach for ''he,'' overlooking that two males in the sentence make the pronoun ambiguous.', '1) Circle every person or thing named before the pronoun. 2) If more than one could grammatically be the referent, the pronoun is ambiguous. 3) Test each candidate in the pronoun''s slot; if two readings both make sense, replace the pronoun with the specific noun. 4) Re-read to confirm one, and only one, meaning survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9b3b4144fc30cdf2', 'act-english', 's-gram', 4, 'You can <u>either submit the form online or</u> mail it to the district office.', 'Which choice places the paired conjunction so the options match?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"submit either the form online or","letter":"B"},{"is_no_change":false,"label":"either submit the form online, or","letter":"C"},{"is_no_change":false,"label":"submit the form either online or","letter":"D"}]', 'D', '{"A":"''Either'' sits before the verb but ''or'' introduces only a place — the halves don''t match.","B":"''Either the form'' pairs a noun with a place — still lopsided.","C":"The mismatch stays, and the comma adds nothing.","D":"''Either online or [by] mail'' — both arms of the pair now offer the same kind of thing."}', 'Place correlatives so the words after each arm are **grammatically parallel**.', 'The sentence sounds fine aloud because the meaning is guessable.', 'Whatever follows ''either'' must mirror what follows ''or'' — noun/noun, verb/verb, place/place.', 'underlined-span-mc', 'the sentence sounds fine aloud because the meaning is guessable', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9b3cfa8ee7b5a117', 'act-english', 's-gram', 4, 'The archive of nitrate cels and pencil tests, stacked for decades in vaults beneath the old ink-and-paint building, <u>were finally digitized</u> last spring.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was finally digitized","letter":"B"},{"is_no_change":false,"label":"are finally digitized","letter":"C"},{"is_no_change":false,"label":"have finally been digitized","letter":"D"}]', 'B', '{"A":"''Were'' agrees with the nearby plurals ''cels,'' ''tests,'' and ''vaults'' instead of the singular head noun ''archive.''","B":"''Was'' correctly agrees with the singular subject ''archive,'' the head noun of the long subject phrase, and fits the past cue ''last spring.''","C":"''Are'' is both plural and present tense, failing the singular subject and the ''last spring'' time cue.","D":"''Have been'' is plural; the singular ''archive'' would require ''has been,'' and the simple past better fits a completed event ''last spring.''"}', 'The verb must agree with the **head noun** ''archive,'' which is singular, and match the past time cue ''last spring.''', 'The plural nouns stacked between subject and verb (''cels,'' ''tests,'' ''vaults'') pull students toward a plural verb.', '1) Find the verb. 2) Ask ''who or what does this?'' to find the subject. 3) Cross out every prepositional phrase and modifier between subject and verb. 4) Match the verb to the head noun in number. 5) Check time cues in the sentence for tense.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9d212201af9d0d3a', 'act-english', 's-gram', 4, 'The trail crew at Acadia spends early summer clearing drainage bars, rebuilding granite steps, and <u>they repaint</u> the faded blazes that mark the summit routes.', 'Which choice best maintains the pattern established earlier in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"repainting","letter":"B"},{"is_no_change":false,"label":"to repaint","letter":"C"},{"is_no_change":false,"label":"having repainted","letter":"D"}]', 'B', '{"A":"Breaks the list of ''-ing'' phrases by restarting with the subject ''they,'' turning the third item into a mismatched clause.","B":"Matches ''clearing'' and ''rebuilding,'' completing the series in the same grammatical form.","C":"Switches the third item to an infinitive, mismatching the two ''-ing'' items before it.","D":"Uses a perfect participle that wrongly signals completed prior action and still breaks the series'' form."}', 'Items in a series must share one grammatical form, and the first two items here are **-ing** phrases.', 'Adding ''they'' feels natural in speech, so students overlook that it snaps the list into a mismatched independent clause.', '1) Find the series and its conjunction. 2) Label the form of each item (noun, -ing phrase, infinitive, clause). 3) Make every item wear the same label as the first. 4) Re-read the list skipping the middle item to test the last against the first.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-aef13fb2e7641129', 'act-english', 's-gram', 4, 'Neither the faded schematics nor the original service manual <u>were</u> much help until Priya located the factory parts list.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have been","letter":"B"},{"is_no_change":false,"label":"was","letter":"C"},{"is_no_change":false,"label":"are","letter":"D"}]', 'C', '{"A":"''Were'' treats the neither/nor pair as a plural unit, but with neither/nor the verb agrees with the nearer subject, the singular ''manual.''","B":"''Have been'' is doubly wrong: plural agreement plus a perfect aspect that clashes with the past-tense narrative anchored by ''located.''","C":"Correct: the verb agrees with the nearer subject ''manual'' (singular) and stays in the simple past to match ''located.''","D":"''Are'' breaks both the past time frame of the narrative and the nearer-subject agreement rule."}', 'With **neither/nor**, the verb agrees with the subject *nearer* to it — here the singular ''manual'' — and must match the sentence''s past time frame.', 'Two items joined by ''neither...nor'' feel like a plural pair, so students default to a plural verb.', '1) Spot the pair marker (neither/nor, either/or). 2) Underline the noun closer to the verb. 3) Match the verb''s number to that noun alone. 4) Check the rest of the sentence for tense anchors and match them. 5) Reread with only the nearer subject: ''the manual ___ much help.''', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ba5da13ef71e6085', 'act-english', 's-gram', 4, 'Passage III — The Mapmaker''s Daughter — Marie Tharp was a geologist who helped change how we see the ocean floor. In the 1950s, working alongside her colleague Bruce Heezen, she plotted thousands of depth measurements <u>collected from</u> ships crossing the Atlantic. At the time, many scientists believed the ocean floor was mostly flat. Tharp''s maps revealed something remarkable, a vast underwater mountain range running down the middle of the Atlantic. This discovery, which supported the then-controversial theory of continental drift, was at first dismissed by Heezen as "girl talk." Eventually, the evidence became impossible to ignore. Tharp''s careful work helped establish the theory of plate tectonics. Today, her once-doubted maps are considered landmarks of earth science.', 'Which choice keeps the underlined verb consistent with the sentence''s other verbs?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"collecting from","letter":"B"},{"is_no_change":false,"label":"collects from","letter":"C"},{"is_no_change":false,"label":"which collected from","letter":"D"}]', 'A', '{"A":"''collected from ships'' is a past participle modifying ''measurements'' — consistent with the passage''s past narration.","B":"''collecting from'' is a present participle, wrongly making the measurements do the collecting.","C":"''collects from'' is present tense, clashing with the passage''s past-tense story.","D":"''which collected from'' turns the phrase into a clause whose subject illogically collects."}', 'The past participle **''collected from''** modifies ''measurements'' and matches the past-tense narration.', 'Each alternative changes the verb form just enough to sound plausible in isolation.', 'Rule focus: Conventions (verb form)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c0cae2becc3bf070', 'act-english', 's-gram', 4, 'When the registrar handed the conservator the ivory comb, <u>she noted a hairline crack</u> along its spine before either woman said a word.', 'Which choice makes the sentence clearest and most precise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the conservator noted a hairline crack","letter":"B"},{"is_no_change":false,"label":"she herself noted a hairline crack","letter":"C"},{"is_no_change":false,"label":"a hairline crack was noted by her","letter":"D"}]', 'B', '{"A":"''She'' has two possible antecedents — the registrar or the conservator — so the reader cannot tell who noticed the flaw.","B":"Correct: replacing the ambiguous pronoun with the specific noun makes the actor unmistakable.","C":"The intensive ''herself'' adds emphasis but does nothing to identify which of the two women ''she'' means.","D":"Passive voice merely relocates the ambiguity; ''her'' still could be either woman."}', 'When a pronoun could point to **two possible antecedents**, the fix is to restate the specific noun.', 'Many students assume ''she'' naturally refers to the nearer noun, so the original feels clear enough to keep.', '1) Underline the pronoun and list every earlier noun it could match in gender and number. 2) If the list has more than one entry, the pronoun is ambiguous. 3) Check whether the revision names one specific actor. 4) Reject fixes that keep any pronoun pointing at the same crowded list — emphasis words and voice changes do not shrink the list.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c55b74081234d6f0', 'act-english', 's-gram', 4, 'The station manager <u>insisted for the announcers to memorize</u> the sponsor''s script before every broadcast.', 'Which choice best conforms to the conventions of standard written English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"insisted on the announcers to memorize","letter":"B"},{"is_no_change":false,"label":"insisted the announcers to memorize","letter":"C"},{"is_no_change":false,"label":"insisted that the announcers memorize","letter":"D"}]', 'D', '{"A":"''Insisted for...to'' forces an unidiomatic for...to construction onto a verb that never takes it.","B":"''Insisted on'' is a real idiom, but it must be followed by a noun or gerund, never by a noun plus infinitive.","C":"Dropping the connective leaves a bare noun-plus-infinitive pattern that ''insist'' does not allow.","D":"Correct: ''insist'' reports a demand as a that-clause with the base-form (subjunctive) verb."}', '''Insist'' takes its demand as a **that-clause** with a base-form verb, not a for...to or noun-plus-infinitive construction.', '''Insisted on'' sounds familiar because it is a genuine idiom, so students accept it without noticing the infinitive stuck onto its object.', '1) Identify the reporting verb (''insisted''). 2) Recall the patterns it allows: insist on + noun/gerund, or insist + that-clause with a base verb. 3) Test the sentence against each allowed pattern. 4) Reject any option that mixes patterns or invents a for...to frame. 5) Reread the survivor aloud to confirm it sounds like edited prose.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c67b10fd632d6801', 'act-english', 's-gram', 4, 'Before 1869, news from California crawled east by stagecoach and steamer; when the two track crews met at Promontory Summit that May, telegraph operators <u>will flash</u> word of the final spike to both coasts within minutes.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have flashed","letter":"B"},{"is_no_change":false,"label":"flashes","letter":"C"},{"is_no_change":false,"label":"flashed","letter":"D"}]', 'D', '{"A":"The future ''will flash'' clashes with the past-time frame fixed by ''Before 1869'' and the dated meeting of the crews.","B":"The present perfect ''have flashed'' cannot attach to a completed event pinned to a definite past date.","C":"''Flashes'' is present tense and also fails to agree with the plural subject ''operators.''","D":"Correct: the simple past ''flashed'' matches the past-tense narrative established by ''crawled'' and ''met.''"}', 'The clause reports a completed, dated 1869 event, so the verb must stay in the **simple past** to match ''met.''', '''Have flashed'' tempts students who hear a finished action and reach for the perfect without checking the definite past date.', '1) Circle every time marker (dates, ''before,'' ''when''). 2) Find the tense of the other verbs in the same time frame. 3) Ask: is the action finished at a definite past time? If yes, use simple past. 4) Reject any tense that points to the future or to an unfinished span reaching the present.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d1f1f8fcdd24ef61', 'act-english', 's-gram', 4, 'When Amara showed her quilt to the museum''s curator, <u>she suggested</u> displaying it near the entrance.', 'Which choice makes the writer''s meaning clearest?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the curator suggested","letter":"B"},{"is_no_change":false,"label":"she then suggested","letter":"C"},{"is_no_change":false,"label":"it was suggested","letter":"D"}]', 'B', '{"A":"With two women in the sentence, ''she'' could point to either Amara or the museum staff member.","B":"Correct: naming the intended person removes the ambiguity the pronoun created.","C":"Adding ''then'' changes the timing but still leaves the pronoun pointing at two possible people.","D":"The passive hides the actor entirely, so readers still cannot tell who made the suggestion."}', 'A pronoun with **two possible antecedents** must be replaced by the specific noun intended.', '''She then suggested'' feels clearer because the added adverb implies sequence, but it never resolves which woman is meant.', '1) Circle every pronoun. 2) List every earlier noun it could match in gender and number. 3) If more than one candidate survives, replace the pronoun with the intended noun. 4) Reject fixes that only reword around the ambiguity.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e1fbf1ae7183e462', 'act-english', 's-gram', 4, 'When the club president phoned the planetarium director about the storm rolling in, <u>she</u> proposed moving the star party into the dome.', 'Which choice most clearly indicates who proposed moving the star party?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"she herself","letter":"B"},{"is_no_change":false,"label":"the president","letter":"C"},{"is_no_change":false,"label":"they","letter":"D"}]', 'C', '{"A":"Ambiguous reference: ''she'' could point to either of the two people named in the sentence.","B":"''Herself'' merely intensifies ''she''; it cannot pick out which of the two people acted.","C":"Correct: repeating the noun names the intended person and removes the ambiguity.","D":"''They'' is either still unclear or falsely implies a joint proposal by both people."}', 'When a pronoun has **two possible antecedents**, clarity requires naming the intended person outright.', '''She'' tempts readers because the sentence still sounds smooth aloud, masking the fact that two different people could be the proposer.', '1) Circle the pronoun. 2) List every noun before it that matches in gender and number. 3) If more than one noun qualifies, the reference is ambiguous. 4) Fix it by replacing the pronoun with the specific noun (or restructuring), not by adding emphasis. 5) Re-read to confirm exactly one reading survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f1be4f7a34c291a1', 'act-english', 's-gram', 4, 'The volunteer <u>whom</u> organized the food drive received an award.', 'Which pronoun is correct here?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"who","letter":"B"},{"is_no_change":false,"label":"which","letter":"C"},{"is_no_change":false,"label":"whose","letter":"D"}]', 'B', '{"A":"''Whom'' is an object pronoun, but this pronoun is the SUBJECT of ''organized''.","B":"The pronoun performs the verb ''organized'', so the subject form ''who'' is required.","C":"''Which'' refers to things; the volunteer is a person.","D":"''Whose'' shows possession — nothing is being possessed here."}', 'Subject of the verb → **who**; object of a verb or preposition → whom.', '''Whom'' sounds more formal, so it gets sprinkled in where ''who'' belongs.', 'Test with he/him: ''HE organized the drive'' → who; ''the drive was organized by HIM'' → whom.', 'underlined-span-mc', '''Whom'' sounds more formal, so it gets sprinkled in where ''who'' belongs', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f285ccce82cd567b', 'act-english', 's-gram', 4, 'Even after passing the written exam, many interpreting students stay committed <u>to master</u> the facial grammar that gives American Sign Language much of its meaning.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to mastering","letter":"B"},{"is_no_change":false,"label":"to have mastered","letter":"C"},{"is_no_change":false,"label":"at mastering","letter":"D"}]', 'B', '{"A":"Treats ''to'' as the start of an infinitive, but in the idiom ''committed to,'' the word ''to'' is a preposition and must be followed by a gerund.","B":"Correct — after the preposition ''to'' in ''committed to,'' the verb takes the gerund form.","C":"The perfect infinitive wrongly suggests the mastering was completed before the commitment and still misreads ''to'' as an infinitive marker.","D":"Swaps in a preposition that does not form a standard idiom with ''committed.''"}', 'In **committed to**, the word ''to'' is a preposition, so the verb that follows must be a gerund.', '''To master'' sounds natural because ''to + base verb'' is the most familiar verb pattern in English.', '1) Find the expression before the verb (here, *committed to*). 2) Test whether *to* is a preposition by placing a noun after it: *committed to excellence* works, so *to* is a preposition. 3) A preposition takes the noun form of a verb — the -ing form. 4) Reject any option that treats *to* as an infinitive marker or that swaps the idiom''s preposition.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f63165eb8a110b67', 'act-english', 's-gram', 4, 'At the Herrera family''s bakery, success depended <u>not only on the quality of the flour but also on</u> the patience of whoever tended the ovens.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"not only on the quality of the flour but also","letter":"B"},{"is_no_change":false,"label":"not only on the quality of the flour and also on","letter":"C"},{"is_no_change":false,"label":"not only on the quality of the flour as well as on","letter":"D"}]', 'A', '{"A":"Correct — ''not only on X but also on Y'' keeps the correlative pair intact and places ''on'' after both halves, so the two phrases stay parallel.","B":"Drops the second ''on,'' so the phrase after ''but also'' no longer matches the prepositional phrase after ''not only'' (parallel_dropped_prep).","C":"Pairs ''not only'' with ''and also,'' a mismatch; that opener must be completed by ''but also'' (correlative_mismatch_and).","D":"Pairs ''not only'' with ''as well as,'' another broken correlative pair (correlative_mismatch_aswellas)."}', 'The pair **not only … but also** is complete, and both halves begin with ''on,'' keeping the two phrases parallel.', 'Dropping the second ''on'' sounds natural in speech, so many students accept the unbalanced version without noticing the broken parallel.', '1) Find the first half of the correlative pair (e.g., *not only*). 2) Check that its partner is the exact required match. 3) Compare what follows each half — the two pieces must have the same grammatical shape. 4) If either the partner word or the shapes differ, revise.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fef10b2484a7f035', 'act-english', 's-gram', 4, 'By the time the credits rolled, we <u>watch</u> the entire trilogy in one sitting.', 'Which choice places the underlined action correctly in time?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"watches","letter":"B"},{"is_no_change":false,"label":"will watch","letter":"C"},{"is_no_change":false,"label":"had watched","letter":"D"}]', 'D', '{"A":"''Watch'' is present tense, clashing with the past-time frame ''by the time the credits rolled''.","B":"''Watches'' is present tense too, and doesn''t agree with ''we''.","C":"''Will watch'' points to the future, but the viewing already finished.","D":"''Had watched'' correctly marks an action completed before another past moment."}', 'An action finished **before** another past event takes the past perfect (''had watched'').', 'The present ''watch'' feels immediate, but the sentence''s time markers are all past.', '''By the time X happened, Y had happened'' — the earlier past action takes ''had''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-03b4e18d0b336929', 'act-english', 's-gram', 5, 'By the time the snow finally melted off the pass last June, the crew, working upward from the trailhead, <u>already cleared</u> two hundred downed lodgepoles from the lower switchbacks.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has already cleared","letter":"B"},{"is_no_change":false,"label":"had already cleared","letter":"C"},{"is_no_change":false,"label":"will have already cleared","letter":"D"}]', 'C', '{"A":"Simple past cannot show that the clearing was completed before another past event; the ''by the time'' frame demands the past perfect.","B":"Present perfect ties the action to the present moment, which clashes with the finished past time marker ''last June.''","C":"Correct: past perfect (*had* + participle) marks the earlier of two past events, exactly what ''by the time the snow melted'' requires.","D":"Future perfect points to a deadline that has not yet arrived, contradicting a sentence anchored entirely in the past."}', 'The **past perfect** is required because the clearing was finished *before* another completed past event, the June snowmelt.', 'The bare simple past sounds fine to the ear because casual speech routinely drops the perfect helper before ''already.''', '1) Put every event in the sentence on a timeline. 2) Find sequencing signals like ''by the time.'' 3) Mark the event completed first and give it the past perfect (had + past participle). 4) Keep the later past event in simple past. 5) Reject any form that reaches into the present or future.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-045e89834ca58dcb', 'act-english', 's-gram', 5, 'The manager credits the shop''s longevity to three habits: pricing donations the day they arrive, rotating window displays before shoppers tire of them, and <u>tracking which sections outsell the rest</u>.', 'Which choice best maintains the grammatical pattern of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to track which sections outsell the rest","letter":"B"},{"is_no_change":false,"label":"she tracks which sections outsell the rest","letter":"C"},{"is_no_change":false,"label":"the tracking of which sections outsell the rest","letter":"D"}]', 'A', '{"A":"Correct: the third habit stays a gerund phrase, matching *pricing* and *rotating*.","B":"Switches the final item to an infinitive, breaking the gerund pattern of the first two habits.","C":"Turns the final item into a full clause, which cannot sit in a list of gerund phrases.","D":"Swaps in a heavy noun phrase, abandoning the -ing pattern and adding clutter."}', 'Items in a series must share one grammatical form, and this list is built on **gerund** (-ing) phrases.', 'An infinitive feels like a natural way to name a habit, so the shift away from -ing is easy to miss at the end of a long list.', '1) Find the list. 2) Label the grammatical form of the first item. 3) Check that every later item wears the same form. 4) Reject any option that changes form, even if it sounds fine alone. 5) Prefer the version that keeps the pattern intact.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0be4ca9f5e8f578f', 'act-english', 's-gram', 5, 'The network of branch lines that once linked these mining villages to the coastal ports <u>was</u> abandoned in the 1960s, though hikers still trace its overgrown embankments today.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"were","letter":"B"},{"is_no_change":false,"label":"have been","letter":"C"},{"is_no_change":false,"label":"are","letter":"D"}]', 'A', '{"A":"Correct: the subject is the singular ''network,'' so ''was'' agrees despite the plural nouns stacked between subject and verb.","B":"''Were'' wrongly agrees with the nearby plurals ''lines,'' ''villages,'' and ''ports'' instead of the true subject.","C":"''Have been'' is both plural and present perfect, mismatching the singular subject and the dated past event.","D":"''Are'' is present tense and plural, failing both the time frame and the singular subject ''network.''"}', 'The head of the subject is the singular noun **network**, so the singular past ''was'' is required.', '''Were'' attracts anyone who matches the verb to ''ports,'' the plural noun sitting right beside it.', '1) Find the verb. 2) Ask ''who or what does this?'' and trace back to the head noun of the subject. 3) Cross out every prepositional phrase and relative clause between subject and verb. 4) Match the verb to the head noun''s number, then confirm the tense fits the time markers.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-34ac98ab287cd78a', 'act-english', 's-gram', 5, 'A seasoned theater interpreter spends the month before opening night analyzing the script for wordplay, <u>attends</u> rehearsals to absorb each actor''s timing, and building a signed translation that mirrors the production''s rhythm.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"attending","letter":"B"},{"is_no_change":false,"label":"to attend","letter":"C"},{"is_no_change":false,"label":"she attends","letter":"D"}]', 'B', '{"A":"''Attends'' is a finite verb, but the series pairs it with the -ing forms ''analyzing'' and ''building,'' breaking parallel structure.","B":"Correct — it matches the -ing forms ''analyzing'' and ''building,'' making all three items in the series parallel.","C":"The infinitive ''to attend'' is grammatical on its own but still fails to match the two -ing items in the series.","D":"Inserting ''she attends'' turns the second item into an independent clause, which cannot sit in a series of -ing phrases."}', 'All three items in the series must share the same **-ing** form, matching ''analyzing'' and ''building.''', '''Attends'' agrees with the subject ''interpreter,'' so it sounds fine until the whole list is read as a unit.', '1) Find the series and bracket each item. 2) Label the grammatical form of the items before and after the underlined one. 3) Force the underlined item into that same form. 4) Reread the whole list aloud to confirm every item now starts the same way.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-725c2513c059a420', 'act-english', 's-gram', 5, 'From the coach''s silence after tryouts, the players <u>implied</u> that the roster would shrink.', 'Which choice is the right verb for what the players did?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"applied","letter":"B"},{"is_no_change":false,"label":"implicated","letter":"C"},{"is_no_change":false,"label":"inferred","letter":"D"}]', 'D', '{"A":"Speakers imply; listeners infer. The players were on the receiving end.","B":"''Applied'' belongs to forms and ointments, not conclusions.","C":"''Implicated'' means shown to be involved in wrongdoing.","D":"Drawing a conclusion from evidence is ''inferring''."}', 'The sender **implies**; the receiver **infers**.', 'The two verbs describe the same conversation from opposite ends.', 'Imply = hint outward; infer = conclude inward. Ask which direction the meaning travels.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7ac43692a538ced7', 'act-english', 's-gram', 5, 'The mentor <u>who</u> Amara credits for her scholarship still teaches night classes.', 'Which choice is correct for the person Amara credits?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"whose","letter":"B"},{"is_no_change":false,"label":"which","letter":"C"},{"is_no_change":false,"label":"whom","letter":"D"}]', 'D', '{"A":"Inside the clause, Amara credits HIM — an object, so ''who'' is the wrong case.","B":"''Whose'' is possessive — nothing is owned here.","C":"''Which'' can''t refer to a person.","D":"''Whom'' is the object of ''credits'': Amara credits whom."}', 'Test with him/her: ''Amara credits HIM'' → **whom**.', '''Who'' sounds natural at the head of any clause about a person.', 'He/she fits → who; him/her fits → whom.', 'underlined-span-mc', '''Who'' sounds natural at the head of any clause about a person', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8026889d0496f2cc', 'act-english', 's-gram', 5, 'The array of sensors that ring the airfield, along with the ceilometer and the two anemometers installed last spring, <u>report</u> current conditions to the tower every sixty seconds.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have reported","letter":"B"},{"is_no_change":false,"label":"reports","letter":"C"},{"is_no_change":false,"label":"are reporting","letter":"D"}]', 'C', '{"A":"''Report'' is plural, but the subject ''array'' is singular; the writer matched the verb to the nearby plural nouns (misconception: agree with the nearest noun).","B":"''Have reported'' is both plural and present perfect, clashing with the singular subject and the recurring ''every sixty seconds'' routine (misconception: perfect form for habitual action).","C":"Correct: the singular subject ''array'' takes the singular present ''reports,'' regardless of the plural nouns in the intervening phrases.","D":"''Are reporting'' is plural and progressive; the subject is singular and the action is a repeated routine, not one in progress (misconception: plural pulled from attached phrases)."}', 'The verb must agree with the **singular subject** ''array,'' not the plural nouns stacked between subject and verb.', '''Sensors'' and ''anemometers'' sit right before the verb, luring students into nearest-noun agreement.', '1) Find the main verb. 2) Cross out prepositional phrases and relative clauses between the subject and the verb. 3) Identify the bare subject that remains. 4) Match the verb''s number to that subject. 5) Confirm the tense fits time cues like ''every sixty seconds.''', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-881833945ca3460c', 'act-english', 's-gram', 5, 'When the renovation crew finally met with the library board, <u>they</u> approved the plan to move the teen section upstairs.', 'Which choice provides the clearest sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the board members","letter":"B"},{"is_no_change":false,"label":"they themselves","letter":"C"},{"is_no_change":false,"label":"this group","letter":"D"}]', 'B', '{"A":"''They'' could point to either the renovation crew or the library board, so the reader cannot tell who approved the plan.","B":"Correct: naming the approving party outright removes the ambiguity created by two competing plural antecedents.","C":"''They themselves'' adds emphasis but leaves the same two-way ambiguity untouched.","D":"''This group'' is still ambiguous, since both the crew and the board qualify as groups."}', 'Replacing the pronoun with the specific noun eliminates the **ambiguous reference**, since two plural nouns compete to be its antecedent.', '''They'' sounds natural aloud because readers silently supply an antecedent that the sentence never actually pins down.', '1) Circle every pronoun. 2) List every earlier noun it could point to. 3) If more than one candidate is plausible, the pronoun is ambiguous. 4) Replace it with the specific noun, or rewrite, so only one reading survives. 5) Re-read to confirm a single clear meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9c0e79ff66cc8465', 'act-english', 's-gram', 5, 'When the scouting subteam compared spreadsheets with the drive-team members, <u>the scouts</u> concluded that two potential alliance partners had been badly undervalued.', 'Which choice most clearly identifies who reached the conclusion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"they","letter":"B"},{"is_no_change":false,"label":"some","letter":"C"},{"is_no_change":false,"label":"both groups","letter":"D"}]', 'A', '{"A":"Correct: repeating the noun is the only version that unambiguously names which of the two plural groups concluded.","B":"With two plural groups in the sentence, ''they'' could point to either one (pronoun_two_plural_antecedents).","C":"''Some'' hides both the number and the identity of the people concluding (vague_indefinite_pronoun).","D":"''Both groups'' invents an agreement between the two teams that the original sentence never asserts (meaning_shift_revision)."}', 'Repeating the noun is the only version that names the concluding group **unambiguously** when two plural groups are in play.', '''They'' feels smoother, but with two plural antecedents available, the pronoun could point to either group.', '1) List every noun the pronoun could refer to. 2) If more than one candidate matches in number and gender, the pronoun is ambiguous. 3) Replace it with the intended noun, even when that means repeating a word.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a5c4bc79eb059ac0', 'act-english', 's-gram', 5, 'Any questions about the field trip should go to Ms. Rivera or <u>myself</u> before Friday.', 'Which choice is correct for the second contact person?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"I","letter":"B"},{"is_no_change":false,"label":"me","letter":"C"},{"is_no_change":false,"label":"mine","letter":"D"}]', 'C', '{"A":"''Myself'' is reflexive — it needs ''I'' earlier in the clause to reflect.","B":"''I'' is the subject form in an object slot.","C":"Questions go TO someone: the object form ''me''.","D":"''Mine'' shows possession, which nothing here calls for."}', 'No earlier ''I'' to reflect → plain **me**, not ''myself''.', '''Myself'' sounds extra polite in requests and announcements.', 'Reflexives (-self) only echo a subject already in the clause: ''I hurt myself'', never ''contact myself''.', 'underlined-span-mc', '''Myself'' sounds extra polite in requests and announcements', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ab498b26b08a730b', 'act-english', 's-gram', 5, 'By the time the council approved the greenway plan in 2019, volunteers, working weekends with borrowed mowers, <u>will have cleared</u> nearly three miles of the abandoned rail corridor.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have cleared","letter":"B"},{"is_no_change":false,"label":"will clear","letter":"C"},{"is_no_change":false,"label":"had cleared","letter":"D"}]', 'D', '{"A":"Future perfect points forward from the present, but the reference point (''approved... in 2019'') is past — the misconception that ''by the time'' always triggers ''will have.''","B":"Present perfect ties a past action to right now, but the clearing must be anchored before a specific past event, not before the present.","C":"Simple future contradicts the past-tense reference point established in the opening clause.","D":"Past perfect correctly marks the clearing as completed before another past event, the 2019 approval."}', '**Past perfect** signals an action finished before another past event — here, before the 2019 approval.', '''By the time'' so often pairs with ''will have'' in speech that students apply future perfect without checking the anchor event''s tense.', '1) Find the time anchor (''by the time X happened''). 2) Note the anchor''s tense. 3) If the anchor is past, the earlier action takes past perfect; if the anchor is future or present, use future perfect. 4) Re-read with both events placed on a timeline.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b869a4b9b77c0061', 'act-english', 's-gram', 5, 'By the time the salt kiln finally reached cone ten last June, the studio''s resident potters <u>have monitored</u> its flame color for nearly eighteen hours, adjusting the dampers whenever the atmosphere inside shifted.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had monitored","letter":"B"},{"is_no_change":false,"label":"monitored","letter":"C"},{"is_no_change":false,"label":"will have monitored","letter":"D"}]', 'B', '{"A":"The present perfect ''have monitored'' ties the action to the present moment, clashing with the past-time frame set by ''reached'' and ''last June'' (present-perfect-for-past confusion).","B":"Correct: the eighteen hours of monitoring were completed before another past event (''reached cone ten''), so the past perfect is required.","C":"Simple past ''monitored'' treats the monitoring and the kiln''s arrival at cone ten as an undifferentiated past, failing to mark which happened first (ignores tense sequence).","D":"Future perfect ''will have monitored'' places completion at a future moment, contradicting ''last June'' (mistakes any perfect form for future time)."}', 'With **by the time** plus a past event, the earlier of the two past actions must take the past perfect.', 'The bare simple past sounds natural read aloud, so students never ask which of the two past events finished first.', '1) List every action in the sentence and note when each happens. 2) If two actions are both past, ask which one finished first. 3) Give the earlier action ''had'' + past participle. 4) Confirm with time cues like ''by the time'' and ''last June''. 5) Reread the sentence to check the sequence now reads clearly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dcfcdb4223eef909', 'act-english', 's-gram', 5, 'When one trains at altitude for a few weeks, <u>you</u> notice the difference at sea level immediately.', 'Which choice keeps the sentence''s point of view consistent?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"one notices","letter":"B"},{"is_no_change":false,"label":"they notice","letter":"C"},{"is_no_change":false,"label":"we noticed","letter":"D"}]', 'B', '{"A":"The sentence opens with ''one'' and then swerves to ''you''.","B":"''One ... one notices'' holds a single point of view.","C":"''They'' invents a third party the sentence never introduced.","D":"''We noticed'' changes both person and tense."}', 'Pick a person — ''one'' or ''you'' — and **stay in it**.', '''One'' and ''you'' both speak generally, so they feel interchangeable mid-sentence.', 'Don''t shift person (one → you → they) inside a sentence or passage.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-518721c8b8fb1534', 'act-english', 's-org', 1, 'The museum added a rooftop cafe last spring. <u>Also,</u> it now stays open until nine on Fridays, and it has doubled its evening attendance.', 'Which choice best introduces the sentence as another item in a running list of the museum''s additions?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In addition,","letter":"B"},{"is_no_change":false,"label":"Instead,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'B', '{"A":"''Also'' signals addition but is abrupt and informal at the head of a sentence opening a formal list.","B":"''In addition'' opens the sentence as the next entry in the list of additions, matching the passage''s register.","C":"''Instead'' signals replacement, but the late hours are added to the cafe, not a substitute for it.","D":"''For example'' promises an instance of the cafe, but longer hours are a separate addition, not an example."}', 'For the next item in a list, use a full **additive** opener (''in addition'') rather than the abrupt sentence-initial ''also''.', '''Also'' does mean addition, so it seems right until you weigh how it reads opening a listed sentence.', 'Match the transition to its POSITION and register: a sentence that adds a list item takes a full additive opener, not a bare ''also''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-04524a7acb0aa68a', 'act-english', 's-org', 2, 'Ticket presales for the fall play stayed sluggish through September. <u>Therefore,</u> the final weekend sold out within hours.', 'Which transition word or phrase is most logical in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example,","letter":"B"},{"is_no_change":false,"label":"In addition,","letter":"C"},{"is_no_change":false,"label":"However,","letter":"D"}]', 'D', '{"A":"''Therefore'' claims the slow presales caused the sellout, but the two facts oppose each other (transition_false_cause).","B":"''For example'' would make the sellout an illustration of sluggish sales, which it contradicts (transition_false_example).","C":"''In addition'' stacks the sellout onto the slow sales as if they point the same way (transition_false_addition).","D":"Correct: the sold-out weekend reverses the expectation set by sluggish presales, so a contrast transition is needed."}', 'The second sentence **contrasts** with the first — slow sales followed by a fast sellout — so a contrast transition is the only logical link.', 'Students pick the cause-effect transition because the two sentences describe the same ticket campaign in sequence, which feels like cause and result.', '1) State the first sentence''s idea in five words. 2) State the second sentence''s idea in five words. 3) Name the relationship: cause, example, addition, or reversal. 4) Match the transition to that relationship. 5) Reread both sentences with your choice to confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-08dfeed4155da2ed', 'act-english', 's-org', 2, 'First, soak the beans overnight. <u>In other words</u>, rinse them and set them to simmer.', 'Which transition fits the step-by-step sequence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For instance","letter":"B"},{"is_no_change":false,"label":"Next","letter":"C"},{"is_no_change":false,"label":"In contrast","letter":"D"}]', 'C', '{"A":"''In other words'' promises a restatement, but rinsing and simmering are NEW steps, not the soaking rephrased.","B":"''For instance'' promises an example of soaking — rinsing isn''t one.","C":"The passage is a sequence of steps; ''Next'' moves it to step two.","D":"''In contrast'' claims the steps oppose each other; they simply follow each other."}', 'Instructions advance step by step — the transition must mark **sequence**.', 'Restatement transitions sound explanatory, which feels helpful in instructions.', 'In a procedure, use sequence transitions (first, next, then, finally) between steps.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-099375b53649cbfb', 'act-english', 's-org', 2, 'Wool fibers are covered in microscopic scales that lock together when the fleece is rubbed in warm, soapy water. Felters exploit this property, rolling and pressing loose wool until it fuses into a dense, seamless cloth. Because the finished material has no threads to unravel, it can be cut freely for hats, boots, and sturdy bags.', 'The writer wants to begin the paragraph with a sentence that prepares readers for the discussion of how felt is formed. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Archaeologists have found ancient felt made from sheep fleece across Central Asia.","letter":"A"},{"is_no_change":false,"label":"Many crafters find felting a relaxing hobby, and felt can be made at home.","letter":"B"},{"is_no_change":false,"label":"Wool is one of several animal fibers used in textiles.","letter":"C"},{"is_no_change":false,"label":"Alone among familiar textiles, felt is made from fleece that has never been spun or woven.","letter":"D"}]', 'D', '{"A":"Opens with archaeology, steering readers toward history rather than the process the paragraph explains.","B":"Frames felting as a hobby experience, which the paragraph''s technical explanation never develops.","C":"So broad a claim about wool could open almost any textile paragraph; it does not forecast the process focus.","D":"Correct: it flags felt''s threadless nature, exactly the puzzle the paragraph''s process explanation goes on to resolve."}', 'An effective opener **forecasts** the paragraph''s focus — here, the unusual way felt comes into being.', 'The archaeology opener tempts because it is interesting and mentions felt, but the paragraph never returns to history.', '1) Read the paragraph without an opener and summarize its focus in five words. 2) Test each candidate: does it point directly at that focus? 3) Eliminate openers that promise history, opinion, or a broader topic the paragraph does not deliver. 4) Choose the one whose promise the paragraph keeps.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0f348f00c49c85ab', 'act-english', 's-org', 2, '_____ Certain anglerfish dangle a glowing lure to draw victims close, while some squid release clouds of luminous mucus to confuse predators. Even tiny dinoflagellates flash blue when the water around them is disturbed.', 'The writer wants an opening sentence that introduces the paragraph''s focus on how deep-sea creatures produce their own glow. Which choice best accomplishes this goal?', '[{"is_no_change":false,"label":"The deep sea is the largest habitat on Earth.","letter":"A"},{"is_no_change":false,"label":"In the sunless depths, many organisms create their own glow through chemical reactions.","letter":"B"},{"is_no_change":false,"label":"Anglerfish are among the strangest fish in the entire ocean.","letter":"C"},{"is_no_change":false,"label":"Sunlight cannot reach the deepest parts of the ocean.","letter":"D"}]', 'B', '{"A":"Makes a sweeping claim about ocean size that the examples never address, so it is too broad (intro_too_broad).","B":"Correct: it names the shared ability the following examples all illustrate, framing the paragraph.","C":"Spotlights only one of the several creatures listed, so it is too narrow to introduce them all (intro_too_narrow).","D":"Describes the dark setting but not the ability the examples demonstrate, so it fails to introduce the focus (intro_offtopic)."}', 'An effective opener previews the **specific idea** the supporting sentences develop — here, self-produced glow.', 'The single-creature sentence echoes the first example, so students mistake a narrow detail for a topic sentence.', '1) Read the supporting sentences and state their shared idea. 2) An opener should preview that exact idea. 3) Reject sentences that are broader than the idea, narrower than it, or off its topic. 4) Confirm the opener sets up every example that follows.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-18f81be3d73ede14', 'act-english', 's-org', 2, 'Blitz chess rewards instinct and nerve. <u>Therefore,</u> classical time controls give players hours to verify every idea.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example,","letter":"B"},{"is_no_change":false,"label":"Likewise,","letter":"C"},{"is_no_change":false,"label":"However,","letter":"D"}]', 'D', '{"A":"''Therefore'' claims the second sentence results from the first, but no cause-and-effect chain connects them.","B":"The second sentence is not an example of blitz rewarding instinct; it introduces an opposing format.","C":"''Likewise'' asserts similarity, but the two sentences describe opposite approaches to time and thought.","D":"The sentences oppose each other — speed and instinct versus hours of verification — so a contrast word is needed."}', 'The sentences **oppose** each other — instinct and speed versus hours of verification — so a contrast transition is required.', '''Likewise'' tempts because both sentences describe chess formats, and that surface similarity masks the reversal in meaning.', '1) Read the sentence before and the sentence after the transition. 2) State their relationship in your own words: cause, contrast, example, or restatement. 3) Match the transition word to that relationship. 4) Reread with your pick to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-359fb009d83b9c0a', 'act-english', 's-org', 2, 'Stoneware can survive the hottest chamber of the wood kiln without warping. <u>Similarly,</u> earthenware slumps and blisters if it is fired even slightly past its low maturing point.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In contrast,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"As a result,","letter":"D"}]', 'B', '{"A":"''Similarly'' claims the two clays behave alike, but one endures high heat and the other fails in it (likeness transition on opposing ideas).","B":"Correct: the sentences set the two clays'' behaviors against each other, so an opposition transition fits.","C":"The second sentence is not an instance of the first, so an example transition misfires (false-example).","D":"Stoneware''s toughness does not cause earthenware''s slumping, so a cause-effect transition is illogical (false-cause)."}', 'The two sentences describe **opposite** behaviors, so the transition must signal opposition.', 'Both sentences discuss firing clay, so the surface similarity of topic lures students toward a likeness transition.', '1) Restate each sentence in your own words. 2) Name the relationship between them: alike, opposed, example, cause, or sequence. 3) Match the transition to that named relationship. 4) Reread the pair with your choice inserted. 5) Confirm no other option names the relationship better.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4f1c908fd678e779', 'act-english', 's-org', 2, 'Patrons start by checking out up to five paper packets from a wooden card catalog near the garden window. After the growing season, they harvest seeds from their strongest plants and bring a portion back in labeled envelopes. Staff then sort the envelopes and restock the drawers for the next spring.', 'The writer wants to open the paragraph with a sentence that introduces its focus on how the library''s seed exchange operates. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Public libraries across the country have expanded far beyond lending books.","letter":"A"},{"is_no_change":false,"label":"The seed exchange at the Fairview branch runs on a simple borrow, grow, and return cycle.","letter":"B"},{"is_no_change":false,"label":"Tomato and zinnia seed packets disappear from the drawers faster than any others.","letter":"C"},{"is_no_change":false,"label":"Gardening and the seed exchange surged in popularity nationwide during the past decade.","letter":"D"}]', 'B', '{"A":"Too broad: it introduces libraries in general, while the paragraph explains one specific process.","B":"Correct: it names the program and previews the step-by-step process the following sentences describe.","C":"A narrow detail about popular packets that belongs mid-paragraph, not an introduction to the process.","D":"Background about national trends, which the paragraph never discusses."}', 'An effective opener must **preview** the paragraph''s actual content, and this one announces the exact process the sentences go on to detail.', 'The broad opening about libraries in general feels safe and essay-like, though the paragraph never supports a claim that wide.', '1) Read the paragraph and state its focus in one phrase. 2) Check each candidate opener''s scope against that focus. 3) Reject options that are broader, narrower, or about a different aspect. 4) Confirm the winner previews what the following sentences actually deliver.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5b62aae3d773b227', 'act-english', 's-org', 2, 'The science fair had three rounds. First came the written proposal, and next the judges toured each booth. <u>First,</u> the finalists presented to the whole auditorium.', 'Which transition correctly marks the final round in the sequence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Finally,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"In contrast,","letter":"D"}]', 'B', '{"A":"''First'' can''t introduce the third and last round; it contradicts the sequence.","B":"''Finally'' correctly signals the last step after ''first'' and ''next''.","C":"''For instance'' would introduce an example, not the closing step.","D":"''In contrast'' signals opposition, which the sequence doesn''t call for."}', 'In a step sequence, the last item takes a **closing transition** like ''finally''.', 'Repeating ''first'' echoes the paragraph''s opening word, which can feel intentional.', 'Sequence transitions must track order: first → next → finally, never two ''firsts''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5bdbf65db2d82245', 'act-english', 's-org', 2, '<i>[The writer will add an introductory sentence here.]</i> Hours before the gates open, he drags and waters the infield until the clay is uniform. Next he mows the outfield in alternating stripes and repaints the batter''s boxes. Finally, he walks the foul lines with a string level, checking for the slightest crown. By the national anthem, every surface has met his exacting standard.', 'The writer wants to open the paragraph with a sentence that introduces its main focus. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Corliss Park hosts more than sixty home games every season.","letter":"A"},{"is_no_change":false,"label":"Corliss Park''s infield grass is a hybrid variety bred to survive humid summers.","letter":"B"},{"is_no_change":false,"label":"Ray Delgado attended games at Corliss Park long before he worked there.","letter":"C"},{"is_no_change":false,"label":"Each home date at Corliss Park begins with the same demanding checklist for groundskeeper Ray Delgado.","letter":"D"}]', 'D', '{"A":"A schedule statistic never mentions the worker or his tasks, so it fails to preview the paragraph and leaves ''he'' unexplained (intro_too_broad).","B":"A turf-botany detail points the paragraph toward grass science rather than the worker''s pregame labor (intro_wrong_emphasis).","C":"Introduces the right person but frames his past as a fan, while the paragraph chronicles his present duties (intro_wrong_angle).","D":"Correct: it names the worker and previews the sequence of pregame tasks that every following sentence describes."}', 'An effective introduction must **preview** the paragraph''s content, and only this choice names the worker and sets up his pregame tasks.', 'The biography option mentions the right person, so students accept it without checking whether it sets up what the paragraph actually does.', '1) Read the body of the paragraph first and summarize its focus in five words. 2) Ask what a reader must know for sentence two to make sense. 3) Test each opener: does it name that focus and point forward to it? 4) Eliminate openers that are broader, narrower, or angled at a different subject. 5) Pick the one that forecasts the body.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-60e4dfda77001dec', 'act-english', 's-org', 2, 'By four in the morning, the mixers are already turning, and the first trays of rolls are proofing beside the warm ovens. An hour later, the pastry team pipes fillings and glazes fruit tarts. Only when the cases are full does anyone unlock the entrance.', 'The writer wants to open the paragraph with a sentence that establishes its focus on the tasks completed prior to opening time. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The bakery sells rolls, tarts, and several kinds of bread.","letter":"A"},{"is_no_change":false,"label":"Customers often ask why fresh bread costs more than supermarket loaves.","letter":"B"},{"is_no_change":false,"label":"The family bought its first commercial mixer in 1989.","letter":"C"},{"is_no_change":false,"label":"Most of the work at Solano & Sons is finished before the front door ever opens.","letter":"D"}]', 'D', '{"A":"Lists products, so it frames the paragraph as an inventory rather than a timeline of pre-opening tasks (intro_wrong_focus_inventory).","B":"Raises a pricing question the paragraph never answers, steering readers off the stated focus (intro_offtopic).","C":"Offers a historical fact about equipment, not a frame for the morning routine that follows (intro_wrong_focus_history).","D":"Correct — it announces that the labor happens early, exactly the idea the paragraph''s timeline of pre-opening tasks develops."}', 'It previews the paragraph''s controlling idea — the **pre-opening** labor — which every following sentence illustrates.', 'The product list feels connected because rolls and tarts appear later in the paragraph, but it promises an inventory the paragraph never delivers.', '1) Read the body sentences first and state their shared idea in one phrase. 2) Test each opener: does it promise exactly that idea? 3) Reject openers that promise a different topic, however related. 4) Confirm the winner by reading it straight into sentence two.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a772dc0e8d0906b', 'act-english', 's-org', 2, 'Organizers of the first Riverbend Folk Festival printed only five hundred tickets. <u>Similarly,</u> nearly four thousand people arrived at the gates.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"In other words,","letter":"D"}]', 'B', '{"A":"''Similarly'' signals likeness, but a tiny ticket printing and an enormous turnout are opposites, not parallels.","B":"Correct: the huge crowd defies the organizers'' small expectation, so a contrast word is needed.","C":"''For example'' promises an illustration of the first sentence, but the crowd is not an example of printing tickets.","D":"''In other words'' promises a restatement, but the second sentence adds a new, conflicting fact."}', 'The second sentence **contradicts** the expectation set by the first, so the transition must signal contrast.', '''In other words'' tempts students because both sentences discuss the same event, masking that the second reverses the first.', '1) Summarize the sentence before the transition in five words. 2) Summarize the sentence after it. 3) Name the relationship between them (contrast, cause, example, restatement). 4) Pick the transition that names that same relationship, then re-read the pair.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6fbd3c24ee333193', 'act-english', 's-org', 2, 'The forecast promised heavy rain through the morning. <u>Similarly,</u> the market manager moved every stall under the covered pavilion before opening.', 'Which transition is most logical here?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For instance,","letter":"B"},{"is_no_change":false,"label":"As a result,","letter":"C"},{"is_no_change":false,"label":"On the other hand,","letter":"D"}]', 'C', '{"A":"Signals similarity between two like things, but the second sentence responds to the first rather than resembling it (transition_wrong_logic).","B":"Promises an example of the previous statement, but no example follows (transition_false_example).","C":"Correct — moving the stalls indoors is a direct effect of the rainy forecast.","D":"Signals contrast where the two sentences actually align as cause and consequence (transition_false_contrast)."}', 'Moving the stalls indoors is a direct **effect** of the rainy forecast, so a cause-and-effect transition fits.', 'Both sentences concern the same rainy morning, so a similarity word feels loosely connected enough to keep.', '1) State sentence 1 in five words. 2) State sentence 2 in five words. 3) Name the logical relationship (cause→effect, contrast, example, addition, time). 4) Match the transition to that relationship. 5) Reread the pair with your candidate inserted to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-71d01781ee685ec2', 'act-english', 's-org', 2, 'Passage I — Learning to Sail — The summer I turned fourteen, my uncle teached me to sail. His old wooden boat, named the <em>Osprey</em>, had belonged to my grandfather. On our first morning out, the wind was calm, and we drifted lazily across the bay. <u>However,</u> by noon a stiff breeze had risen, and the <em>Osprey</em> leaned hard against it. My uncle showed me how to read the wind by watching the surface of the water. "Dark patches mean gusts," he said, "and you must be ready." At first I was nervous, gripping the lines too tightly. But after an hour, I begun to relax. By the end of the day, I could steer the boat myself. Although I still had much to learn, I felt a new confidence. Sailing, I realized, was not about controlling the wind but about working with it.', 'Which transition, in the underlined spot, best fits the shift from calm to a stiff breeze?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Similarly,","letter":"D"}]', 'A', '{"A":"Contrast: calm morning vs. breeze by noon → \"However.\"","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Contrast: calm morning vs. breeze by noon → "However."', 'The original can read smoothly until you apply the rule.', 'Rule focus: Knowledge of Language (transition)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-791e41888777d68d', 'act-english', 's-org', 2, 'The saguaro does far more than tower over the Sonoran Desert. Gila woodpeckers drill nest holes in its trunk, and when they abandon them, elf owls and purple martins take up residence. Insects tunnel through its pulp, and hawks perch on its crown to scan the flats for prey.', 'The writer wants to close the paragraph by emphasizing the saguaro''s role as a home for many different kinds of creatures. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"A mature saguaro can keep growing for more than two centuries before it finally topples.","letter":"A"},{"is_no_change":false,"label":"In this way a single saguaro becomes a crowded apartment tower, housing birds, insects, and mammals under one spiny roof.","letter":"B"},{"is_no_change":false,"label":"The Gila woodpecker, in particular, could not raise its young without the cactus.","letter":"C"},{"is_no_change":false,"label":"The saguaro also hoards enormous reserves of water inside its pleated trunk.","letter":"D"}]', 'B', '{"A":"Shifts to the plant''s lifespan, ignoring the requested emphasis on the many creatures it shelters (add_offtopic).","B":"Correct: it sums up the paragraph by stressing the wide variety of animals the cactus shelters at once.","C":"Narrows to a single species, undercutting the goal of stressing many different creatures (goal_too_narrow).","D":"Redirects to water storage, an emphasis the goal does not ask for (goal_wrong_emphasis)."}', 'The goal asks for a close that stresses **variety of inhabitants**, and only this option gathers birds, insects, and mammals together.', 'The water-storage line sounds impressively factual and stays on the saguaro, so students grab it even though it drops the habitat focus.', '1) Restate the stated goal in a few words (here: shelters many kinds of creatures). 2) Read each option and ask whether it delivers that exact emphasis. 3) Cross out any option that changes the topic, narrows to one case, or shifts the emphasis. 4) Keep the one that captures the full breadth named in the goal. 5) Re-read it against the goal to confirm the match.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-856f4ee35fa12607', 'act-english', 's-org', 2, '[1] _____ [2] First, the quilt is photographed and its fibers are examined under magnification. [3] Next, technicians vacuum both sides through a fine mesh screen. [4] Finally, the quilt is rolled onto a padded tube for long-term storage.', 'The writer wants an opening sentence that prepares readers for the paragraph''s step-by-step account of quilt treatment. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Quilt treatments have changed very little over the past two centuries.","letter":"A"},{"is_no_change":false,"label":"Every quilt that enters the textile lab moves through the same careful sequence of treatments.","letter":"B"},{"is_no_change":false,"label":"The textile lab also repairs tapestries, flags, and antique lace.","letter":"C"},{"is_no_change":false,"label":"Vacuuming through a screen is the most careful stage of every quilt treatment.","letter":"D"}]', 'B', '{"A":"A claim about historical continuity sets up a then-versus-now discussion, not the ordered procedure that follows.","B":"Correct: it announces an ordered series of treatments, exactly what sentences 2-4 then walk through.","C":"Listing other objects the lab handles points the paragraph away from quilts entirely.","D":"Spotlighting one stage is too narrow to introduce a paragraph that covers the whole process."}', 'An effective opener must **forecast the paragraph''s structure** — here, an ordered series of steps applied to every quilt.', 'The narrow option mentions details from the paragraph, so it feels connected even though it previews only one step.', '1) Read the body sentences and name their pattern (steps, examples, contrast, history). 2) Restate the stated goal in your own words. 3) Test each opener: does it promise exactly that pattern? 4) Eliminate openers that are broader, narrower, or about a different subject. 5) Confirm the survivor could be followed naturally by the first body sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9de6051bd7638d73', 'act-english', 's-org', 2, 'Early builders learned that unprotected wooden trusses rotted within a decade or two of exposure to rain and snow. A roof and siding shielded the structural timbers, extending a bridge''s life to a century or more.', 'The writer wants to open the paragraph with a sentence that introduces its focus on the practical reason covered bridges were built with roofs. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Covered bridges owe their famous roofs to a practical concern: keeping weather away from the timbers.","letter":"A"},{"is_no_change":false,"label":"Covered bridges appear on postcards and calendars all over New England.","letter":"B"},{"is_no_change":false,"label":"Wood has served as a building material for thousands of years.","letter":"C"},{"is_no_change":false,"label":"Several covered bridges still charge visitors a small toll.","letter":"D"}]', 'A', '{"A":"Names the paragraph''s exact focus — the protective, practical purpose of the roofs — which the next two sentences develop.","B":"Introduces scenic charm, a topic the paragraph never develops (misconception: intro_offtopic_appeal).","C":"Far broader than the paragraph, which concerns one specific design decision, not all wood construction (misconception: intro_too_broad).","D":"Raises tolls, an irrelevant detail disconnected from rot and protection (misconception: intro_irrelevant_detail)."}', 'An effective introduction must **preview** the paragraph''s actual content — here, the practical weather-protection purpose that both following sentences explain.', 'The postcard sentence feels like a friendly, engaging opener, so students pick it for style even though the paragraph never returns to scenery.', '1) Read the body sentences first and state their shared topic in one phrase. 2) Reread the stated goal in the stem. 3) Test each opener: does it forecast that exact topic? 4) Eliminate openers that are broader, narrower, or about something else. 5) Confirm the survivor flows into the first body sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9e755b47f4776e12', 'act-english', 's-org', 2, 'At first glance the saguaro seems utterly defenseless against thirsty grazers. <u>In addition,</u> its dense armor of spines turns away nearly every animal that might tear into its flesh for water.', 'Which transition provides the most logical connection between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"Therefore,","letter":"C"},{"is_no_change":false,"label":"For instance,","letter":"D"}]', 'B', '{"A":"''In addition'' signals another similar point, but the second sentence reverses the impression the first creates (transition_wrong_logic).","B":"Correct: the plant looks defenseless yet is actually well protected, so a contrast transition names the turn accurately.","C":"''Therefore'' claims the protection results from seeming defenseless, a false cause-and-effect link (transition_wrong_logic).","D":"''For instance'' promises an example of defenselessness, but the sentence gives evidence of the opposite (transition_false_example)."}', 'The second sentence **overturns the expectation** raised by ''seems defenseless,'' so only a contrast transition fits.', 'Both sentences discuss the saguaro''s defenses, so an adding transition feels safe even though the second sentence flips the first''s impression.', '1) Put each sentence into a plain claim. 2) Notice the first says ''appears defenseless'' and the second says ''is protected.'' 3) Name that relationship: it is a reversal, not an addition or a result. 4) Match the transition to a reversal. 5) Re-read the pair with your pick to confirm the turn sounds right.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9f7d2e846ac2bdc7', 'act-english', 's-org', 2, 'After a record-breaking winter of snowfall, the team expected the glacier to gain mass. <u>Accordingly,</u> the spring laser survey showed that the ice had thinned by nearly a meter.', 'Which transition word creates the most logical connection between these sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Consequently,","letter":"B"},{"is_no_change":false,"label":"However,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'C', '{"A":"''Accordingly'' signals that the second sentence follows naturally from the first, but the survey result defied the expectation (transition_wrong_logic).","B":"''Consequently'' makes the thinning a result of the team''s expectation, which reverses the logic (false cause-effect).","C":"The survey contradicted what the team expected, so a contrast transition is the logical link.","D":"''For example'' wrongly presents the thinning as an illustration of the expectation (illustration misread)."}', 'The second sentence **contradicts** the expectation set up in the first, so the transition must signal contrast.', '''Consequently'' tempts readers who see ''expected... showed'' as a cause-and-effect chain rather than a reversal.', '1) State sentence one''s idea in five words. 2) State sentence two''s idea in five words. 3) Name the relationship: same direction, opposite direction, cause, or illustration. 4) Pick the transition that names that exact relationship. 5) Reread with your pick to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a43493263bb793a1', 'act-english', 's-org', 2, 'The manifest of the S.S. Providence lists my great-grandfather''s occupation as ''farmer.'' <u>However,</u> the letters he mailed home during his first year describe twelve-hour shifts in a Rhode Island textile mill.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Similarly,","letter":"D"}]', 'A', '{"A":"Correct: the letters contradict the manifest''s record, so a contrast transition is the logical connector.","B":"Falsely marks the mill work as a result of the manifest''s farming label; no cause-effect link exists.","C":"Presents the mill shifts as an example of farming, though they conflict with that record.","D":"Claims the two records point the same way when they actually disagree."}', 'The letters **contradict** the manifest''s record, so a contrast transition is the logical connector.', '''Therefore'' attracts readers who assume the second sentence simply continues the first instead of testing the actual logical relationship.', '1) State sentence one''s claim in your own words. 2) State sentence two''s claim. 3) Name the relationship: contrast, cause-effect, example, or addition. 4) Match the transition word to that named relationship. 5) Re-read the pair with your choice to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ae1d260e0e7bb1fa', 'act-english', 's-org', 2, 'Many beginners assume the amber safelight is completely harmless to photographic paper. <u>Similarly,</u> a sheet left under the lamp for several minutes will slowly fog.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"However,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'C', '{"A":"Treats the two sentences as alike (transition_false_similarity), but the second sentence contradicts the beginners'' assumption rather than resembling it.","B":"Claims the fogging results from the assumption (transition_false_cause), though a belief cannot cause paper to fog.","C":"Correct: the second sentence reverses the expectation set up by the first, so a contrast word fits the logic.","D":"Presents the fogging as an illustration of the assumption (transition_false_example), when it actually disproves that assumption."}', 'The second sentence **contradicts** the beginners'' assumption, so the transition must signal contrast.', 'Both sentences mention the safelight and paper, so ''Similarly'' feels superficially right to students who match topics instead of logic.', '1) Restate each sentence in five plain words. 2) Name the relationship between them: same direction, contrast, cause-effect, or example. 3) Match the transition word to that named relationship. 4) Re-read the pair with your choice inserted to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-af28702318d403e6', 'act-english', 's-org', 2, 'Parrotfish grind mouthfuls of coral skeleton with fused, beak-like teeth, digesting the algae and excreting the leftover minerals as fine white grains. <u>However,</u> a single large parrotfish can generate hundreds of pounds of sand in a year.', 'Which transition word best expresses the relationship between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"As a result,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'B', '{"A":"''However'' signals contrast, but the second sentence follows from the first rather than opposing it (misconception: transition_wrong_logic_contrast).","B":"The sand production is the direct outcome of the grinding and excreting described first — a cause-and-effect link.","C":"''For example'' requires a general claim followed by an illustration; the first sentence makes no broad claim being illustrated (misconception: transition_false_example).","D":"''Meanwhile'' marks two events unfolding at the same time in different places, not a causal chain (misconception: transition_time_for_logic)."}', 'The second sentence states the **effect** of the grinding described in the first, so a cause-and-effect transition is required.', 'The surprising statistic feels contrast-worthy, so ''However'' seems to fit even though nothing is being opposed.', '1) Read the sentence before and the sentence after the transition. 2) Label the relationship in your own words: opposes, illustrates, follows from, or happens alongside. 3) Match that label to the transition''s job. 4) Reject any connector whose job doesn''t match your label, no matter how smooth it sounds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-afe670fa9d5179e5', 'act-english', 's-org', 2, 'Cast iron is strong under compression but brittle under tension. <u>As a result,</u> nineteenth-century designers limited it to short arch spans, where the metal stayed compressed.', 'Which choice provides the most logical transition between the sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example,","letter":"B"},{"is_no_change":false,"label":"In contrast,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'A', '{"A":"The designers'' caution is a direct consequence of the metal''s brittleness, so the cause-effect transition ''As a result'' fits.","B":"The second sentence is not an illustration of brittleness but an outcome of it (misconception: transition_example_for_effect).","C":"Signals opposition, but the second sentence follows logically from the first rather than opposing it (misconception: transition_false_contrast).","D":"Signals simultaneous events, but the sentences are linked by logic, not by timing (misconception: transition_time_for_logic)."}', 'The second sentence states the **consequence** of the first — brittleness led designers to restrict cast iron — so a cause-effect transition is correct.', 'Students see two different ideas (a property, then a practice) and reach for a contrast word instead of tracing the cause-effect link.', '1) Summarize sentence one in five words. 2) Summarize sentence two in five words. 3) Name the relationship: cause-effect, contrast, example, addition, or time. 4) Pick the transition that names that exact relationship. 5) Reread with the transition in place to confirm the logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b21513cab961e3f7', 'act-english', 's-org', 2, 'Ella trained all winter for the marathon. <u>In contrast</u>, she finished in her best time ever. Her coach had predicted exactly this payoff.', 'Which transition fits the logic connecting the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"As a result","letter":"B"},{"is_no_change":false,"label":"For instance","letter":"C"},{"is_no_change":false,"label":"On the other hand","letter":"D"}]', 'B', '{"A":"''In contrast'' promises opposition, but the best-ever finish FOLLOWS FROM the training.","B":"The record finish is the outcome of the winter of training — cause and effect.","C":"''For instance'' promises an example, not an outcome.","D":"''On the other hand'' signals the same false contrast as ''In contrast''."}', 'Read what the second sentence actually does to the first, then choose the transition whose promise matches that link — not one that merely reads smoothly.', 'Any transition reads smoothly if you don''t test the logic it claims.', 'Name the real relationship (cause, example, contrast, time) before picking a transition.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@641234d1808d41ec98477ba4961d06d7')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b2690aaa7c290c51', 'act-english', 's-org', 2, 'Cel animation dominated commercial studios for most of the twentieth century. <u>Therefore,</u> by the early 2000s, computer-generated imagery had replaced it almost entirely.', 'Which transition word or phrase is most logical in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Similarly,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"However,","letter":"D"}]', 'D', '{"A":"''Therefore'' claims the replacement of cel animation follows logically from its dominance, but the second sentence reverses the first.","B":"''Similarly'' promises a parallel idea, yet the second sentence contradicts rather than echoes the first.","C":"''For example'' would introduce an instance of cel animation''s dominance, not its downfall.","D":"''However'' correctly signals the contrast between decades of dominance and near-total replacement."}', 'The second sentence **reverses** the first, so a contrast transition is required.', 'The time gap (''for most of the century... by the early 2000s'') feels like a natural progression, luring students to a cause-and-effect word.', '1) Cover the transition. 2) Read both sentences and state their relationship in your own words (contrast, cause, example, addition, time). 3) Match that relationship to each option''s category. 4) Reject any transition whose category differs, no matter how smooth it sounds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b600f3a154d1520c', 'act-english', 's-org', 2, '______ Files ring against axe heads while pine pitch is scrubbed from the saw teeth. Handles are checked for cracks, and every edge is honed until it can shave a curl from a thumbnail. Only when each tool passes inspection does the crew rack it along the wall tent, ready for morning.', 'The writer wants to open the paragraph with a sentence that introduces its main focus. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Each evening at camp, the crew turns to the quiet ritual of caring for its tools.","letter":"A"},{"is_no_change":false,"label":"Dinner at a backcountry camp is usually cooked over a two-burner propane stove.","letter":"B"},{"is_no_change":false,"label":"Hand tools have been used on American trails for well over a century.","letter":"C"},{"is_no_change":false,"label":"By morning, the crew is back on the trail within an hour of sunrise.","letter":"D"}]', 'A', '{"A":"Correct: it previews exactly what follows — an evening routine of tool maintenance — matching the paragraph''s topic, scope, and moment.","B":"Off-topic: the paragraph never mentions food or cooking, so a dinner opener promises content the paragraph doesn''t deliver.","C":"Too broad: a century of tool history is a different essay; the paragraph zooms in on one nightly routine.","D":"Chronologically misplaced: it describes the morning after the routine, functioning as an aftermath rather than an introduction."}', 'An effective opener **previews the paragraph''s actual content** — here, the nightly tool-care routine every following detail describes.', 'The sweeping historical claim tempts students who equate ''sounds important'' with ''introduces the paragraph.''', '1) Read the paragraph without its opening sentence and summarize its actual content. 2) Ask what every detail has in common. 3) Pick the opener that promises exactly that content — same topic, same scope, same moment. 4) Reject openers that are off-topic, too broad, or chronologically misplaced.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b81cb48451a3ed1f', 'act-english', 's-org', 2, 'Last fall the team loaded its practice robot into a trailer nearly every weekend. Members ran driving demonstrations at the public library, let elementary students steer the robot through a cone slalom at the fall festival, and staffed a booth at the maker fair downtown. By December, the roster had grown from eleven students to twenty-six.', 'The writer wants to open the paragraph with a sentence that introduces its main focus. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Community outreach became the team''s most powerful recruiting tool.","letter":"A"},{"is_no_change":false,"label":"Trailers large enough to hold a competition robot are surprisingly expensive.","letter":"B"},{"is_no_change":false,"label":"The team''s robot uses a six-wheel drivetrain with treaded wheels.","letter":"C"},{"is_no_change":false,"label":"Fall festivals have been a local tradition for more than forty years.","letter":"D"}]', 'A', '{"A":"Correct: it frames both the public events and the roster growth that every following sentence supports.","B":"Fixates on a passing logistical detail — the trailer — that the paragraph never develops (opener_side_detail).","C":"Introduces hardware specifications, a topic no sentence in the paragraph addresses (opener_offtopic).","D":"Zooms in on background trivia about one venue instead of the paragraph''s subject (opener_background_trivia)."}', 'It names the paragraph''s real subject — public events that grew the team — which **every** following sentence supports.', 'The trailer option mentions equipment from the first sentence, so it feels connected to the paragraph.', '1) Read the whole paragraph first. 2) Summarize its content in one phrase. 3) Test each opener: does it predict most of the sentences, or only one detail? 4) Pick the opener that frames all of them.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ba3decc0ea40c8b9', 'act-english', 's-org', 2, '[1] The paragraph then explains how heat unravels those coils. [2] As the egg white climbs past sixty degrees Celsius, the proteins bond into a mesh that traps water and turns the liquid opaque and firm. [3] <u>________</u>', 'The writer wants a concluding sentence that captures the paragraph''s main idea about why egg whites set when cooked. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Egg whites, of course, have been used in kitchens for centuries in dishes far too numerous to list here.","letter":"A"},{"is_no_change":false,"label":"Sixty degrees Celsius is a temperature easily reached by most home stovetops within a minute or two.","letter":"B"},{"is_no_change":false,"label":"Chefs sometimes add a pinch of salt to egg whites, though opinions differ on whether it truly helps.","letter":"C"},{"is_no_change":false,"label":"In short, cooking sets an egg white by prompting its unraveled proteins to link into a solid, water-holding network.","letter":"D"}]', 'D', '{"A":"Off-topic conclusion: it drifts into the history of egg whites rather than summarizing the protein science just explained.","B":"Wrong focus: it seizes on a stray number instead of restating the paragraph''s central cause-and-effect idea.","C":"Adds a new tangent about salt that the paragraph never developed, so it fails to summarize the main point.","D":"Correct: it restates the paragraph''s core idea — heat links proteins into a firm, water-holding mesh — as a clean conclusion."}', 'A strong conclusion **restates the paragraph''s central point**, and only this option summarizes the heat-driven protein bonding the paragraph described.', 'The temperature detail was mentioned in the paragraph, so a sentence built around that number feels grounded in the text.', '1) State the paragraph''s single main idea in one sentence. 2) For each option, ask ''Does this echo that main idea, or introduce something new?'' 3) Eliminate any option that adds a fact the paragraph never developed. 4) Keep the option that summarizes the central point. 5) Confirm it would make sense as the last line a reader remembers.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d6f36f5e981a41ef', 'act-english', 's-org', 2, 'Crystal sets needed no batteries and cost almost nothing to operate. <u>Therefore,</u> they were too weak to drive a loudspeaker, so the whole family shared one pair of headphones.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"Likewise,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'B', '{"A":"''Therefore'' claims the weakness follows logically from being cheap and battery-free, but the second sentence is a drawback, not a conclusion.","B":"Correct: the second sentence cuts against the first sentence''s advantages, so a contrast transition is needed.","C":"''Likewise'' claims the second sentence parallels the first, but it actually opposes it.","D":"''For example'' promises an illustration of the first claim, but a limitation is not an example of low cost."}', 'The second sentence introduces a **drawback** that pushes against the first sentence''s praise, so the transition must signal contrast.', '''Therefore'' tempts students because the second sentence feels like it continues the description, but continuation is not the same as consequence.', '1) Summarize sentence one in five words. 2) Summarize sentence two in five words. 3) Name the relationship: cause, contrast, example, or addition. 4) Pick the transition that names that same relationship. 5) Reread both sentences with your pick to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-edeee013f8460122', 'act-english', 's-org', 2, 'Each week, Rosa Alvarez interviews the family of every person who has died in Harper County, asking about nicknames, recipes, and small kindnesses. The finished obituaries often run longer than the front-page stories. Readers say they clip and save them, and some families frame them.', 'The writer wants to open the paragraph with a sentence that introduces its main focus. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Newspapers have printed obituaries for hundreds of years.","letter":"A"},{"is_no_change":false,"label":"Rosa Alvarez has worked at the Ledger longer than any other employee.","letter":"B"},{"is_no_change":false,"label":"Harper County has been losing population for decades.","letter":"C"},{"is_no_change":false,"label":"At the Harper County Ledger, obituaries are treated as the paper''s most careful journalism.","letter":"D"}]', 'D', '{"A":"Too broad — it promises a history of obituaries in general, not this paper''s distinctive practice.","B":"Wrong emphasis — it narrows the paragraph to one employee''s tenure, which the details never discuss.","C":"Off-topic — population decline never appears anywhere in the paragraph.","D":"Correct: it names the paper and frames obituaries as its signature work, the idea every following sentence supports."}', 'It states the exact idea the details develop: this paper gives its obituaries **extraordinary care**, shown by the interviews, the length, and the readers who save them.', 'The tenure sentence tempts students because Rosa Alvarez stars in the paragraph''s first body sentence.', '1) Read the body sentences and state their shared subject in one phrase. 2) Ask what each opener promises the paragraph will discuss. 3) Eliminate openers broader or narrower than the shared subject. 4) Eliminate openers introducing facts the body never touches. 5) Keep the opener whose promise every body sentence helps keep.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f620550552bb122d', 'act-english', 's-org', 2, 'Satellite imagery shows forecasters where clouds are gathering. <u>However,</u> it cannot reveal how much rain those clouds will actually release.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Likewise,","letter":"D"}]', 'A', '{"A":"Correct: the second sentence limits what satellite imagery can do, so the contrast word fits.","B":"''Therefore'' claims the limitation follows logically from the strength, but the two ideas oppose each other (misconception: any connector between related sentences reads as cause-effect).","C":"''For example'' promises an instance of clouds being shown, but the second sentence is a limitation, not an example (misconception: example word for any elaboration).","D":"''Likewise'' asserts the two sentences run parallel, yet one states an ability and the other an inability (misconception: same topic means same direction)."}', 'The second sentence **contrasts** with the first — an ability set against a limitation — so the original connector is logical.', 'Because both sentences discuss what imagery does, ''Therefore'' feels like a natural continuation until the opposing direction is checked.', '1) Read the sentence before and after the transition. 2) State each sentence''s point in five words. 3) Name the relationship: contrast, cause, example, addition, or similarity. 4) Match the connector to that relationship. 5) Re-read with the connector in place to verify.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f74428e901551953', 'act-english', 's-org', 2, '________ Patrons check out the kit just as they would a novel, keep it for three weeks, and return it with a log of what they observed. Since the program started, the waiting list has never dropped below forty names.', 'The writer wants an opening sentence that introduces the paragraph''s specific focus. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"For more than a century, the public library has been a place to borrow books.","letter":"A"},{"is_no_change":false,"label":"Beginner telescopes can reveal craters, rings, and star clusters in crisp detail.","letter":"B"},{"is_no_change":false,"label":"The way people learn astronomy has changed since 2019.","letter":"C"},{"is_no_change":false,"label":"In 2019, the Ridgewood Public Library began lending telescopes the way it lends books.","letter":"D"}]', 'D', '{"A":"Too broad: a century of library history never points to the specific program the paragraph details.","B":"Off-focus: sky views and optics are never developed; the paragraph is about borrowing, not observing power.","C":"Too vague: a general claim about learning could open dozens of paragraphs and sets up none of these specifics.","D":"Correct: it names the exact program—the who, what, and when—that the following sentences develop."}', 'A strong opener matches the paragraph''s **scope**, naming the specific program that the checkout details and waiting list then develop.', 'The library-history opener tempts students because it mentions borrowing and libraries, but its scope is a century wide while the paragraph is about one program.', '1) Read the body sentences first and summarize their shared topic in one phrase. 2) Ask of each opener: does it name that topic at the same level of specificity? 3) Eliminate openers that are broader, narrower, or about a different subject. 4) Confirm the survivor makes the next sentence''s pronouns and details flow naturally.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-06baa147997a1869', 'act-english', 's-org', 3, '[1] Every printing session begins with the same quiet ritual. [2] The printer mixes fresh developer and brings each tray to the proper temperature. [3] Next, the paper safe is checked to make sure its lid is latched tight. [4] Finally, the overhead white light goes off and the amber safelight comes on. [5] A lid left open for a single minute can ruin fifty sheets of paper.', 'The writer wants the paragraph''s warning to reinforce the step it describes. For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 3.","letter":"C"},{"is_no_change":false,"label":"after Sentence 1.","letter":"D"}]', 'C', '{"A":"Leaves the lid warning after the lighting step (placement_stranded), two steps away from the paper safe it comments on.","B":"Opens the paragraph with a warning about a lid the reader has not yet met (placement_before_referent).","C":"Correct: the warning lands directly beside the latching step it reinforces, keeping the ritual''s order intact.","D":"Drops the warning after the opener, before the paper safe has been introduced (placement_premature)."}', 'The warning is about the **paper safe''s lid**, so it belongs immediately beside the latching step it reinforces.', 'Leaving the warning at the end feels safe because final sentences often summarize, but this one comments on a specific mid-paragraph step.', '1) Find the noun or idea the movable sentence points back to. 2) Locate where that referent is introduced. 3) Place the sentence immediately beside its referent. 4) Re-read the paragraph in the new order to confirm each step still flows.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0c2bb046dd65983d', 'act-english', 's-org', 3, 'Video relay services let Deaf callers conduct business by phone through an on-screen interpreter, and the connection takes only seconds to establish. <u>Likewise,</u> the system has limits: an interpreter unfamiliar with a caller''s regional signs can slow a conversation considerably.', 'Which transition provides the most logical connection between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"Consequently,","letter":"D"}]', 'B', '{"A":"''Likewise'' signals that a similar point is coming, but the second sentence pivots from the service''s strengths to its limits.","B":"Correct — the passage turns from praise to criticism, so a contrast word is needed.","C":"''For instance'' promises an example of the previous claim, but the sentence introduces an opposing point instead.","D":"''Consequently'' claims the limits result from the fast connection, a cause-effect link the passage never makes."}', 'The passage shifts from an advantage to a drawback, so the transition must signal **contrast**.', '''Consequently'' tempts readers who feel any flow between sentences must be cause and effect.', '1) State the point of the sentence before the transition in five words. 2) State the point of the sentence after it in five words. 3) Name the relationship: same-direction, contrast, example, or cause-effect. 4) Pick the transition that names that exact relationship, and reject any that name a different one.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0f15d7861ce7f6e9', 'act-english', 's-org', 3, '[1] Desert pavement is a mosaic of tightly packed pebbles that armors bare ground against the wind. [2] Beneath that stony crust lies a soft layer of fine, wind-blown silt. [3] Over many centuries the wind lifts loose grains away while heavier stones settle and lock together at the surface. [4] The finished crust can look almost as though a mason had paved it by hand.', 'The writer wants to add the sentence ''Each pebble presses against its neighbors like tiles set in a floor.'' To best develop the mosaic introduced at the start of the paragraph, where should this sentence be placed?', '[{"is_no_change":false,"label":"before Sentence 1","letter":"A"},{"is_no_change":false,"label":"after Sentence 1","letter":"B"},{"is_no_change":false,"label":"after Sentence 2","letter":"C"},{"is_no_change":false,"label":"after Sentence 3","letter":"D"}]', 'B', '{"A":"Placed first, the sentence describes a mosaic no reader has met yet, leaving ''each pebble'' without a referent (placement_no_antecedent).","B":"Correct: it elaborates the pebble mosaic named in Sentence 1, so it belongs immediately after that introduction.","C":"Dropping it here interrupts the shift to the buried silt layer that Sentence 2 opens (placement_breaks_flow).","D":"Placed here, it cuts into the step-by-step account of how the crust forms in Sentence 3 (placement_breaks_sequence)."}', 'The new sentence expands on the **pebble mosaic** first named in Sentence 1, so it reads best right after that sentence.', 'Sentence 3 also talks about stones locking together, so the pebble sentence seems to belong there rather than beside its true introduction.', '1) Identify what the movable sentence is about (packed pebbles). 2) Find where that idea is first introduced. 3) A detail sentence belongs right after the sentence it develops. 4) Check that no closer sentence interrupts a different train of thought. 5) Read the paragraph with the sentence inserted to confirm smooth flow.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0f25c8ba0ecfe9a5', 'act-english', 's-org', 3, '[1] In midwinter, a colony forms a tight cluster and shivers its flight muscles to generate heat. [2] The bees rotate from the cold outer shell of the cluster to the warm core, sharing the burden of staying warm. [3] A well-provisioned hive can hold its center near ninety degrees even when snow buries the entrance. [4] Spring brings an entirely different rhythm to the hive. [5] As days lengthen, the queen resumes laying, and foragers stream out after the first pollen. [6] Within weeks the colony''s population begins to climb toward its summer peak.', 'The writer wants to divide this passage into two paragraphs so that each paragraph covers a single season. The second paragraph should begin at which sentence?', '[{"is_no_change":false,"label":"Sentence 2","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 5","letter":"C"},{"is_no_change":false,"label":"Sentence 4","letter":"D"}]', 'D', '{"A":"Sentence 2 continues the midwinter clustering description, so a break here splits the winter material in two.","B":"Sentence 3 still describes the winter cluster''s temperature, keeping it inside the first season''s paragraph.","C":"Sentence 5 is already inside the spring discussion; starting the paragraph here strands the spring topic sentence in the winter paragraph.","D":"Correct: Sentence 4 announces the shift to spring, so it opens the second paragraph and keeps each season whole."}', 'A paragraph break belongs where the **topic shifts**, and the move from winter to spring is announced precisely at that sentence.', 'The vivid spring details in the next sentence read like a fresh start, so students break there and accidentally leave the spring topic sentence behind.', '1) Label each sentence with its subtopic (winter cluster / spring buildup). 2) Find the first sentence that switches to the new subtopic. 3) Begin the new paragraph at that switch sentence, not before or after it. 4) Check that neither resulting paragraph contains stray sentences from the other subtopic.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0f9f7cdec10478d3', 'act-english', 's-org', 3, 'Ten years ago, our district had two school chess clubs; today it has fourteen. Streaming broadcasts have introduced thousands of students to the game, and teachers report waiting lists for after-school boards. Local shops have even begun stocking tournament sets.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The district also plans to renovate several gymnasiums this year.","letter":"A"},{"is_no_change":false,"label":"Checkers clubs, by contrast, have not grown at all.","letter":"B"},{"is_no_change":false,"label":"In this district, chess has clearly moved from the margins to the mainstream.","letter":"C"},{"is_no_change":false,"label":"Chess pieces were once carved from bone and ivory.","letter":"D"}]', 'C', '{"A":"Renovated gymnasiums introduce an unrelated facilities topic instead of closing the paragraph''s account of the game''s growth.","B":"A pivot to a different game shifts the emphasis away from the paragraph''s subject, which never mentions other games.","C":"It restates the paragraph''s central point — the game''s rapid local growth — as a closing generalization.","D":"Historical trivia about antique pieces points backward in time and ignores the paragraph''s present-day claim."}', 'It restates the paragraph''s central point — the game''s rapid local **growth** — in a closing generalization.', 'The checkers comparison tempts because contrast can feel like a punchy ending, yet the paragraph never discusses other games.', '1) State the paragraph''s main idea in one phrase. 2) Test each candidate closer: does it restate or reinforce that idea? 3) Reject closers that open new topics, pivot to other subjects, or shrink to trivia. 4) Confirm the survivor echoes the paragraph''s opening claim.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-100a6574ce3d105d', 'act-english', 's-org', 3, '<p>[1] Coil building, among the oldest of ceramic techniques, requires no wheel at all. [2] The artist rolls long ropes of clay and stacks them in rings, blending each new layer into the one below. [3] With patience, a coiled vessel can rise taller than the potter who shapes it. [4] This spring, Harborview Clay Center devoted its entire gallery to such handbuilt work. [5] Twenty-eight artists contributed pieces ranging from thimble-sized bowls to a chimney-like urn that nearly grazed the ceiling. [6] By closing weekend, attendance had broken the gallery''s ten-year record.</p>', 'The writer wants to divide this paragraph into two in order to separate its two main ideas. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 4","letter":"A"},{"is_no_change":false,"label":"Sentence 5","letter":"B"},{"is_no_change":false,"label":"Sentence 3","letter":"C"},{"is_no_change":false,"label":"Sentence 2","letter":"D"}]', 'A', '{"A":"Correct: the paragraph pivots from explaining the technique to reporting the exhibition exactly here.","B":"Starts the split one sentence late, stranding the exhibition''s introduction with the technique material (break placed after the shift).","C":"Cuts the technique explanation in half, separating the stacking description from its payoff (break inside a topic).","D":"Orphans the opening definition from the explanation that depends on it (break inside a topic)."}', 'A paragraph break belongs at the **first sentence of the new topic** — the pivot from craft explanation to exhibition report.', 'The sentence naming twenty-eight artists feels like a fresh start, but the exhibition topic actually begins one sentence earlier.', '1) Label each sentence with its topic in one or two words. 2) Find where the labels change. 3) Place the break at the first sentence carrying the new label. 4) Check that each resulting paragraph reads as one complete idea. 5) Reject any split that leaves a topic''s opening sentence behind.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-180e5a4f37e4f8c7', 'act-english', 's-org', 3, '[1] The Okafor family opens its market stall with the same routine every Saturday. [2] First, Chidi stacks the sourdough boules into a pyramid at the center of the table. [3] Nneka then clips price cards to small stands beside each variety. [4] A cash box, a stack of paper bags, and a scale complete the setup.', 'The writer wants to add the following sentence: "Next, he fans the seeded batards in a half circle around that pyramid." For the sake of the logic and coherence of the paragraph, the sentence should be placed:', '[{"is_no_change":false,"label":"after Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 4.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'C', '{"A":"Placed there, ''that pyramid'' and ''Next'' point back to nothing, because the pyramid is not built until later (placement_no_antecedent).","B":"The setup is declared ''complete'' in Sentence 4, so adding another arranging step afterward contradicts the paragraph''s close (placement_after_close).","C":"Correct — ''he'' follows Chidi, ''Next'' follows ''First,'' and ''that pyramid'' points to the pyramid just built.","D":"After Sentence 3, ''he'' seems to follow Nneka and the sequence ''First … then … Next'' falls out of order (placement_pronoun_mismatch)."}', 'Every cue in the new sentence — ''Next,'' ''he,'' and ''that pyramid'' — hooks onto Sentence 2 and **nothing else**.', 'Placing it after Sentence 3 keeps it near the middle of the routine, which feels balanced even though the pronoun no longer matches its person.', '1) Circle the new sentence''s pointing words (pronouns, ''this/that'' phrases, sequence words). 2) Find the one sentence that supplies each pointer''s target. 3) Slot the new sentence immediately after that target. 4) Reread the paragraph in order to confirm the chain.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1a1c6b006cef8e63', 'act-english', 's-org', 3, '[1] Tomás arranges his cut flowers in the dark, a full hour before the market opens. [2] Dahlias and zinnias, his most delicate stems, fill the tall buckets at the front of the stand. [3] Sturdier flowers, such as sunflowers, need far less attention once they are set out. [4] Whatever remains at closing time is bundled and sold at half price.', 'The writer wants to add the following sentence to the paragraph: "Their petals must be misted every hour to survive the afternoon heat." To make the paragraph most logical and cohesive, the sentence should be placed:', '[{"is_no_change":false,"label":"before Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'C', '{"A":"Opens the paragraph with the pronoun ''Their,'' which would have no antecedent (pronoun_no_antecedent).","B":"Attaches the misting to all of Tomás''s flowers, contradicting Sentence 3''s claim that sturdier ones need little care (placement_wrong_referent).","C":"Correct — ''Their'' points to the delicate dahlias and zinnias, and the misting detail sets up Sentence 3''s contrast.","D":"Delivers care instructions after the flowers have already been bundled and sold (placement_bad_timeline)."}', '''Their'' must point to the **delicate** dahlias and zinnias, and the misting detail sets up the very next sentence''s contrast with lower-maintenance flowers.', 'The first sentence also mentions flowers, so students park the addition at the earliest available antecedent without testing the later contrast.', '1) Circle the added sentence''s pronouns and pointing words (''Their''). 2) Find the noun each must refer to. 3) Slot the sentence right after the sentence containing that noun. 4) Read the whole paragraph through, checking that contrasts and time order still work. 5) Confirm no other slot passes both tests.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1ceb581c2c4acc7d', 'act-english', 's-org', 3, '[1] The library converted an unused study room into a small recording booth. [2] Staff lined its walls with foam panels to muffle hallway noise. [3] Patrons can now reserve the booth to record interviews with elderly relatives. [4] The completed recordings join a growing oral-history collection kept at the reference desk.', 'The writer wants to add the following sentence to the paragraph: "They also installed a compact mixing console beside the microphone." To preserve the paragraph''s logical sequence, the sentence should be placed:', '[{"is_no_change":false,"label":"before Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'C', '{"A":"Before the paragraph begins, ''They'' has no antecedent and ''also'' has no earlier action to add to.","B":"After Sentence 1, ''They'' misreads as ''the library,'' and no first installation exists yet for ''also'' to echo.","C":"Correct: ''They'' picks up ''Staff'' and ''also'' adds a second setup action, keeping all preparation before patron use.","D":"Placing setup work after the collection description breaks chronology, since the console was installed before recording began."}', 'The pronoun and the word **also** both need Sentence 2''s staff action directly before them, and setup must precede patron use.', 'The spot right after the opening sentence attracts students because installation feels like part of the initial conversion.', '1) Circle backward-pointing words in the added sentence (pronouns, ''also,'' ''this''). 2) Find what each must refer to. 3) Place the sentence immediately after those referents. 4) Check the paragraph''s timeline — setup, use, results — still flows. 5) Re-read the paragraph with the sentence inserted.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1da502776d1fb0fd', 'act-english', 's-org', 3, '[1] Sashiko began in rural Japan as a way to strengthen and insulate worn work clothes. [2] Farming families layered pieces of old indigo cloth and joined the layers with rows of white running stitches. [3] Over generations, those practical rows developed into elaborate geometric patterns admired far beyond the farmhouse. [4] Today, designers borrow sashiko motifs for everything from sneakers to upholstery.', 'The writer wants to add the following sentence to the paragraph: "The rows of stitching did double duty, binding the layers together and trapping warm air between them." For the sake of logic and cohesion, the sentence should be placed:', '[{"is_no_change":false,"label":"after Sentence 1","letter":"A"},{"is_no_change":false,"label":"after Sentence 2","letter":"B"},{"is_no_change":false,"label":"after Sentence 3","letter":"C"},{"is_no_change":false,"label":"after Sentence 4","letter":"D"}]', 'B', '{"A":"''The layers'' would appear before any layers have been mentioned, leaving the reference unexplained.","B":"Correct: Sentence 2 introduces the layers and the stitches, so a sentence explaining what the stitching accomplished follows naturally.","C":"Sentence 3 has already moved from function to decoration; doubling back to warmth interrupts that progression.","D":"Placing it after the modern-design sentence strands a historical detail at the paragraph''s end."}', 'The new sentence''s phrase ''the layers'' needs an **antecedent**, which only Sentence 2 provides.', 'Placement after Sentence 3 tempts because both sentences discuss the rows of stitching, but the paragraph has already shifted from utility to artistry there.', '1) Underline every pointing phrase in the new sentence (the, those, them). 2) Find the earliest sentence that supplies each referent. 3) Place the sentence right after its referents appear. 4) Confirm the paragraph''s timeline still moves in one direction.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1dba393dc26628cf', 'act-english', 's-org', 3, '[1] A spotting scope changes what a mudflat can reveal. [2] Through binoculars, distant shorebirds blur into gray specks against the shine. [3] At thirty-power magnification, however, those specks resolve into dowitchers stitching the mud like sewing machines. [4] Most birders eventually save up for a scope for exactly this reason.', 'For the sake of the logic and cohesion of the paragraph, the best placement for Sentence 1 is:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 2.","letter":"B"},{"is_no_change":false,"label":"after Sentence 3.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'A', '{"A":"Correct: as the opening, it announces the claim that Sentences 2-4 then demonstrate and conclude.","B":"Inserted between the binocular problem and the scope payoff, it breaks the contrast that ''however'' completes.","C":"After the demonstration, it merely repeats what readers just saw and leaves the paragraph without an opening claim.","D":"Placed after the wrap-up, it trails the conclusion and strands the paragraph with a detail-first start."}', 'The sentence is a **topic claim** that the binoculars-versus-scope demonstration then proves, so it belongs at the paragraph''s head.', 'Because Sentence 1 seems to summarize the demonstration, students are tempted to move it after the dowitcher payoff as a wrap-up.', '1) Identify the sentence''s job: claim, evidence, or conclusion. 2) Find the sentences it must connect to (pointing words, contrast words). 3) Test each slot by reading the paragraph with the sentence there. 4) Keep the slot where every connector still points at its target.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-288ef204e430f47f', 'act-english', 's-org', 3, '[1] The first darkrooms were portable tents that traveled by wagon alongside photographers of the 1850s. [2] Wet-plate negatives had to be developed within minutes, so the tent went wherever the camera did. [3] A modern darkroom, by contrast, is a fixed room built around running water and total control of light. [4] Its walls are painted a deep matte black, and its door is sealed with a folding light trap. [5] A ventilation fan pulls chemical fumes up and away from the printing bench.', 'The writer wants to divide this paragraph into two paragraphs so that each one has a single focus. The most logical place to begin the new paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'B', '{"A":"Splits the tent history from its own explanation (divide_midtopic), since Sentence 2 still explains why the tents existed.","B":"Correct: the paragraph pivots from 1850s tents to the modern room exactly at the ''by contrast'' sentence.","C":"Breaks after the modern room has already been introduced (divide_late), stranding the topic sentence with the history.","D":"Leaves nearly all of the modern-room description in the first paragraph (divide_last_sentence), creating a one-sentence orphan."}', 'The topic **pivots** from historical tents to the modern room at the ''by contrast'' sentence, so the new paragraph begins there.', 'Sentence 4''s shift to physical details feels like a fresh start, but the modern-darkroom topic has already begun one sentence earlier.', '1) Label each sentence''s topic in two or three words. 2) Find where the labels change from one subject to another. 3) Start the new paragraph at the first sentence of the new subject. 4) Verify both resulting paragraphs read as single-focus units.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-28f1fd57373ad959', 'act-english', 's-org', 3, 'Cloud cover forced the club to cancel two star parties in March. <u>Nevertheless,</u> April''s session drew the largest crowd in the club''s history.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"Similarly,","letter":"C"},{"is_no_change":false,"label":"In other words,","letter":"D"}]', 'A', '{"A":"Correct: the record April crowd defies the expectation set by the March cancellations, a contrast relationship.","B":"Wrong logic: a result word claims the cancellations caused the record crowd, which the passage does not support.","C":"Wrong logic: a comparison word claims the two sentences describe alike outcomes, but they move in opposite directions.","D":"Wrong logic: a restatement word promises the same idea rephrased, yet the second sentence adds new, contrasting information."}', 'The second sentence **reverses the expectation** created by the first, so a contrast transition is the only logical fit.', '''Therefore'' tempts students who see two events in time order and assume the first caused the second.', '1) Read the sentence before and the sentence after the transition. 2) In one word, name their relationship: cause, contrast, comparison, restatement, or example. 3) Match the transition to that named relationship. 4) Plug it back in and re-read both sentences to confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2a738fef9a70d06e', 'act-english', 's-org', 3, 'Tide pools look calm and inviting. <u>Therefore</u>, the animals in them survive crashing waves, blazing sun, and long hours with no water at all.', 'Which choice best signals the relationship between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example","letter":"B"},{"is_no_change":false,"label":"However","letter":"C"},{"is_no_change":false,"label":"Likewise","letter":"D"}]', 'C', '{"A":"This claims the second sentence is a result of the first, but harsh survival is a contrast, not a consequence (transition_wrong_logic).","B":"This promises an illustration of calmness, yet the second sentence describes the opposite.","C":"Correct: the transition marks the contrast between the calm appearance and the harsh reality.","D":"This signals similarity, but the two sentences oppose rather than echo each other."}', 'The two sentences oppose each other, so a **contrast** transition is required.', 'The result word feels logical because one sentence follows another, and students read sequence as cause.', '1) State the idea in sentence one. 2) State the idea in sentence two. 3) Decide the logical link: add, contrast, cause, or example. 4) Pick the transition that names that exact link.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2c0e728b67c564a5', 'act-english', 's-org', 3, 'Cold rain washed out six home dates in April, and announced attendance sagged to a five-year low. <u>Therefore,</u> souvenir sales that month set a franchise record.', 'Which transition word or phrase is most logical in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Nevertheless,","letter":"B"},{"is_no_change":false,"label":"Consequently,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'B', '{"A":"''Therefore'' claims the sales record resulted from the attendance slump, reversing the actual logic (transition_wrong_logic).","B":"Correct: record sales despite a slump is a contrast, and this transition signals exactly that reversal.","C":"''Consequently'' makes the same cause-effect error in a different word: a slump would not produce record sales.","D":"''For example'' would require the sales record to illustrate the slump, but it contradicts it (transition_example_misfit)."}', 'The two sentences pull in opposite directions, so a **contrast** transition is the only logical bridge.', 'Students see two connected facts and default to a cause-effect word without testing whether the second fact actually follows from the first.', '1) State sentence one in your own words. 2) State sentence two. 3) Name the true relationship: cause, contrast, example, addition, or time. 4) Check that the transition on the page signals that same relationship. 5) If not, swap in one that does and re-read.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2d1e98b6a7604a53', 'act-english', 's-org', 3, '[1] On the first morning of training week, the volunteers learned to judge whether a boulder would sit stable in a staircase. [2] The crew leader then demonstrated how to seat a stone so that three points of contact carried its weight. [3] Each trainee practiced setting stones in a scrap pile well away from the trail. [4] As the week went on, the leader stepped back and let the volunteers catch their own mistakes.', 'The writer wants to add the following sentence to the paragraph: "By the fourth day, even the newest volunteer could seat a rock without a word of guidance." To make the paragraph most logical, the sentence should be placed:', '[{"is_no_change":false,"label":"before Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'D', '{"A":"Placing a day-four outcome before the paragraph begins announces the result before any of the training exists for the reader.","B":"After the first morning, the volunteers have only learned to judge stability; a claim of wordless mastery is not yet credible.","C":"At this point the leader has demonstrated but the trainees have not practiced independently, so ''without a word of guidance'' is unearned.","D":"Correct: after the leader steps back and the volunteers self-correct, the day-four mastery sentence is the natural payoff of the full arc."}', 'The added sentence reports a **result**, so it must follow every training stage that produces it — judging, demonstration, practice, and independence.', 'The slot after the demonstration tempts students who match ''seat a rock'' to the demonstration sentence instead of tracking the whole timeline.', '1) Find the time or logic markers in the sentence to be added. 2) Map the paragraph''s own sequence of stages. 3) Place the sentence where everything it presumes has already happened. 4) Reread the paragraph with the sentence inserted to confirm the flow.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2d5a0a9910f51336', 'act-english', 's-org', 3, '[1] ___ [2] A worker''s dance points nestmates toward a food source, encoding both the direction and the distance of the flowers. [3] The angle of the waggle run relative to vertical signals the direction; the length of the run signals how far to fly.', 'The writer wants an opening sentence that introduces the paragraph''s focus on how bees communicate the location of food. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The waggle dance is one of nature''s most precise systems for sharing directions.","letter":"A"},{"is_no_change":false,"label":"Honeybees have fascinated naturalists for many centuries.","letter":"B"},{"is_no_change":false,"label":"A single hive may contain tens of thousands of individual workers.","letter":"C"},{"is_no_change":false,"label":"Bees also communicate danger by releasing alarm pheromones.","letter":"D"}]', 'A', '{"A":"Correct: it names the dance and frames it as a system for sharing directions, previewing the exact topic the following sentences develop.","B":"Offers a broad historical remark that never mentions communicating food location, so it fails to set up the paragraph.","C":"States a colony-size fact unrelated to how bees signal a food source.","D":"Introduces a different communication channel — alarm — that the paragraph does not go on to discuss."}', 'A good opener names the paragraph''s **specific topic**, and only this sentence forecasts a system for sharing directions to food.', 'The broad ''fascinated naturalists'' opener sounds like a classic essay introduction, so students pick it for tone even though it misses the topic.', '1) Read the sentences that follow the blank and note their shared subject. 2) State that subject in a phrase (''how bees signal food location''). 3) Choose the opener that names that exact subject. 4) Reject openers that are broader, narrower, or about a different subject even if they sound essay-like.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-30ebb92a3c30f0db', 'act-english', 's-org', 3, '[1] Most stories at the Bugle begin with a call to the newsroom tip line. [2] A reporter first checks the caller''s claim against public records. [3] If the documents support it, the reporter schedules interviews with everyone involved. [4] Only after that groundwork does the editor assign the story a slot in an upcoming edition. [5] Those interviews often uncover details the records leave out.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now","letter":"A"},{"is_no_change":false,"label":"before Sentence 1","letter":"B"},{"is_no_change":false,"label":"after Sentence 2","letter":"C"},{"is_no_change":false,"label":"after Sentence 3","letter":"D"}]', 'D', '{"A":"Leaves ''Those interviews'' stranded after a sentence about the editor, two steps past its referent.","B":"Opens the paragraph with a pointing phrase that refers to nothing the reader has seen.","C":"Places the comment about interviews before any interviews have been mentioned.","D":"Correct: ''Those interviews'' directly follows the sentence that introduces the interviews."}', 'The sentence''s pointer phrase **''Those interviews''** must sit immediately after the step that introduces the interviews.', 'Leaving it in place tempts students because the sentence is true anywhere; only the dangling pointer reveals the problem.', '1) Find the moved sentence''s pointing words (''those,'' ''this,'' ''it''). 2) Locate the sentence that introduces what they point to. 3) Place the moved sentence immediately after that referent. 4) Re-read the paragraph to confirm each step still follows the last.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3477cd3c245cee92', 'act-english', 's-org', 3, '[1] For most of the nineteenth century, farmers judged the coming season by folklore: red skies, aching joints, and the thickness of caterpillars'' coats. [2] Almanacs bundled such signs into confident yearly predictions. [3] Tested against actual records, those predictions performed no better than chance. [4] Even so, the booklets sold briskly, offering a certainty nothing else claimed to provide. [5] The first government forecasts, issued by telegraph in the 1870s, took the opposite approach. [6] They predicted only a day ahead, drew on observations wired in from dozens of cities, and admitted their limits plainly.', 'The writer wants to divide this paragraph into two paragraphs in order to separate the discussion of folklore-based prediction from the discussion of early government forecasting. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 4","letter":"C"},{"is_no_change":false,"label":"Sentence 5","letter":"D"}]', 'D', '{"A":"Sentence 2 still describes folklore prediction — almanacs packaging the signs — so the break splits the first topic in half (misconception: break right after the opening sentence).","B":"Sentence 3 evaluates the almanac predictions and belongs with them (misconception: a negative turn signals a new topic).","C":"Sentence 4 opens with ''Even so,'' which reaches back to the failed predictions, chaining it to the almanac discussion (misconception: ignoring a backward-pointing transition).","D":"Correct: Sentence 5 introduces a new actor and era — government forecasts of the 1870s — which is where the topic actually shifts."}', 'The paragraph''s subject changes only when the **new actor** — government forecasting — first appears, so the break belongs there.', 'The verdict that almanac predictions failed feels like a turning point, so students mistake a shift in tone for a shift in topic.', '1) Label each sentence with its subject in two or three words. 2) Find where the label changes for good. 3) Check that the proposed first sentence of paragraph two stands alone, with no backward-pointing opener. 4) Check that everything before the break belongs to topic one. 5) Re-read both halves as separate paragraphs.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-34951293c4a24300', 'act-english', 's-org', 3, '[1] In 1962, a graduate student named Ellen Marsh drove through the Ozarks with a reel-to-reel recorder. [2] She stopped at churches, general stores, and kitchen tables, asking older residents to sing whatever they remembered. [3] The machine was heavy and temperamental, often jamming in humid weather. [4] Even so, by autumn she had captured more than two hundred songs. [5] Those informal settings, she believed, drew out verses that a studio would have silenced.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 1.","letter":"C"},{"is_no_change":false,"label":"after Sentence 2.","letter":"D"}]', 'D', '{"A":"At the end, ''those informal settings'' points back across two sentences about the machine and the song count, leaving the pronoun phrase stranded.","B":"Opening with ''those informal settings'' gives the phrase nothing at all to refer to.","C":"After Sentence 1, the only thing mentioned is the drive itself — no settings have been named yet.","D":"Correct: Sentence 2 lists the churches, stores, and kitchen tables that ''those informal settings'' refers to."}', '''Those informal settings'' must sit **immediately after** the sentence that names the settings — the churches, stores, and kitchen tables.', 'Leaving the sentence where it is tempts students because it reads as a reflective closing thought, even though its pointer word has lost its anchor.', '1) Find the pointing words in the movable sentence (''those,'' ''this,'' ''these,'' ''it''). 2) Ask what noun or list they must refer to. 3) Locate the sentence that supplies that referent. 4) Place the movable sentence directly after it, then re-read the paragraph for flow.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-34f2ce7325488d51', 'act-english', 's-org', 3, 'Synthetic dyes are cheaper and more colorfast than most natural pigments. <u>Similarly,</u> many hand-dyers still choose plant-based color for its subtle variation.', 'Which transition word or phrase is most logical here?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Nevertheless,","letter":"D"}]', 'D', '{"A":"''Similarly'' claims the second sentence resembles the first, but the two sentences pull in opposite directions.","B":"''Therefore'' treats the dyers'' preference as a result of synthetic advantages, reversing the actual logic.","C":"''For example'' would require the second sentence to illustrate the first, which it does not.","D":"Correct: the second sentence runs against the expectation set by the first, so a contrast transition is needed."}', 'The dyers'' preference runs **against** the advantages just listed, so the transition must signal contrast.', '''Therefore'' attracts students who expect cause and effect whenever a fact is followed by a behavior.', '1) Cover the transition. 2) State sentence one''s idea and sentence two''s idea in your own words. 3) Name the relationship: contrast, cause, example, or addition. 4) Pick the transition that announces exactly that relationship. 5) Re-read to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3c499f7d95ebbe30', 'act-english', 's-org', 3, 'Walt Disney''s studio unveiled the multiplane camera in 1937, mounting layers of painted glass at different distances from the lens. As the camera pushed forward, foreground trees slid past faster than distant hills, mimicking real parallax. Scenes gained a sense of dimension that flat cel setups had never achieved.', 'The writer wants to conclude the paragraph with a sentence that emphasizes the multiplane camera''s lasting influence on animation. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The camera itself weighed nearly a ton and required several technicians to operate its layered glass setups.","letter":"A"},{"is_no_change":false,"label":"Decades later, digital compositing programs would still imitate its parallax effects to convey depth.","letter":"B"},{"is_no_change":false,"label":"Disney also invested heavily in Technicolor processes during the same period.","letter":"C"},{"is_no_change":false,"label":"Audiences at the 1937 premiere applauded the effects and the sense of depth in the backgrounds.","letter":"D"}]', 'B', '{"A":"The camera''s weight and crew are production trivia; they say nothing about influence on later animation.","B":"It projects the camera''s technique forward in time, showing later tools copying it — exactly the lasting influence the goal demands.","C":"Technicolor is a different technology; this sentence changes the subject instead of concluding it.","D":"Premiere-night applause is an immediate reaction, not evidence of lasting influence."}', 'Only this sentence extends the camera''s technique **beyond its own era**, which is what ''lasting influence'' requires.', 'The applause detail stays on topic and feels like a satisfying ending, but it measures one night, not a legacy.', '1) Restate the stem''s goal in your own words. 2) For each option, ask: does it address the goal''s key idea (here, influence that persists)? 3) Eliminate options that are on-topic but answer a different question. 4) Pick the one that most directly performs the stated goal.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3c6ce9bedadd9abd', 'act-english', 's-org', 3, 'In the late 1950s, college-town coffeehouses became unlikely engines of the folk revival. Their tiny stages required no amplification, so beginners could perform without renting expensive equipment. Between sets, musicians and audience members traded verses, tunings, and addresses.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Many coffeehouses also served imported espresso, a novelty for audiences at the time.","letter":"A"},{"is_no_change":false,"label":"Folk music itself has roots stretching back centuries in many countries.","letter":"B"},{"is_no_change":false,"label":"In these cramped rooms, the revival steadily gained performers and loyal audiences.","letter":"C"},{"is_no_change":false,"label":"Eventually, television would carry revival performers to far larger audiences.","letter":"D"}]', 'C', '{"A":"The espresso detail is coffeehouse trivia that ignores the paragraph''s claim about the venues fueling the revival.","B":"A sweeping statement about the music''s ancient roots is far broader than this paragraph''s focus on one kind of venue.","C":"Correct: it returns to the opening claim, tying the venues directly to the movement''s growth.","D":"Jumping ahead to television abandons the coffeehouse focus instead of reinforcing it."}', 'It circles back to the paragraph''s **main idea** — that these venues powered the movement — and closes the loop opened by the first sentence.', 'The television option tempts students because it sounds like a natural ''what happened next,'' but forward motion is not reinforcement.', '1) Restate the paragraph''s main idea from its opening sentence. 2) For each option, ask: does this sentence echo that idea, or drift to a side detail, a broader topic, or a new time frame? 3) Eliminate any option whose subject is not the paragraph''s subject. 4) Choose the sentence that could double as a one-line summary of the paragraph.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3e14293085457237', 'act-english', 's-org', 3, '[1] For centuries, European paper was made one sheet at a time, as a vatman dipped a wire mold into a tub of beaten pulp. [2] Each sheet was then pressed, hung to dry, and inspected against the light. [3] The Fourdrinier machine, patented in 1806, replaced this rhythm with a continuous roll. [4] Pulp streamed onto a moving wire belt, shedding water as the belt traveled. [5] Within decades, a single machine could outproduce a hundred vatmen.', 'The writer wants to divide this paragraph into two paragraphs, the first on handmade paper and the second on machine-made paper. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 3.","letter":"A"},{"is_no_change":false,"label":"Sentence 2.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'A', '{"A":"Sentence 3 introduces the machine, so the shift in topic — and the new paragraph — begins there.","B":"Sentence 2 continues describing handwork; splitting there strands half of the handmade process.","C":"Sentence 4 explains the machine introduced in Sentence 3; dividing there separates the machine from its own description.","D":"Sentence 5 gives the machine era''s payoff; starting there leaves the machine''s debut buried in the handmade paragraph."}', 'A new paragraph begins exactly where the **topic shifts** — here, at the first sentence about the machine.', 'Sentence 4 tempts readers who take the patent date in Sentence 3 as historical backdrop rather than the machine topic''s true start.', '1) Label each sentence with its topic in one or two words. 2) Find the first sentence whose label switches to the second topic. 3) Begin the new paragraph at that exact sentence. 4) Check that everything before the break belongs to topic one and everything after to topic two. 5) Re-read both halves for completeness.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3e58a4486f7a42a3', 'act-english', 's-org', 3, 'A summit webcam records only what happens at the surface, in daylight and clear weather. <u>Similarly,</u> radar satellites can map a swelling flank through thick cloud and total darkness.', 'Which transition word or phrase is most logical in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example,","letter":"B"},{"is_no_change":false,"label":"In contrast,","letter":"C"},{"is_no_change":false,"label":"As a result,","letter":"D"}]', 'C', '{"A":"''Similarly'' claims the two tools work alike, but the second sentence stresses what the satellite can do that the webcam cannot.","B":"The satellite sentence is not an example or illustration of the webcam''s limits.","C":"Correct: the sentences set a limited tool against a more capable one, a relationship of difference.","D":"Nothing in the first sentence causes the satellite''s abilities, so a result transition is illogical."}', 'The second sentence **opposes** the first — limits versus capabilities — so the transition must signal difference.', 'Both sentences describe monitoring tools, and that surface similarity makes a likeness transition feel safe.', '1) State sentence 1''s idea in five words. 2) State sentence 2''s idea in five words. 3) Name the relationship: alike, example, cause, or opposed? 4) Match the transition to that named relationship, then re-read with your pick inserted.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-40df25703228cb8e', 'act-english', 's-org', 3, '[1] The Parkway Viaduct opened in 1954 as the city''s first limited-access highway. [2] At the time, engineers celebrated it for whisking suburban drivers over the crowded riverfront wards. [3] Within two decades, however, maintenance costs were climbing and the neighborhoods beneath it had emptied. [4] Today, a coalition of residents and business owners is campaigning to tear the viaduct down. [5] Their proposal would replace it with a surface boulevard, twelve acres of housing, and a riverfront trail. [6] City engineers are studying whether the boulevard could absorb the viaduct''s traffic.', 'The writer wants to divide this paragraph into two paragraphs, separating the viaduct''s history from the current campaign to remove it. The most logical place to begin the new paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'C', '{"A":"Sentence 2 continues the 1954 opening story; splitting there strands the history''s first detail.","B":"Sentence 3''s ''however'' marks a turn, but it still narrates the viaduct''s past decades — the misconception that any contrast word starts a new paragraph.","C":"Sentence 4''s ''Today'' shifts from the structure''s past to the present-day removal campaign, exactly the seam the writer wants.","D":"Sentence 5 elaborates the proposal introduced in Sentence 4; starting there separates a detail from its topic sentence."}', '**''Today''** pivots the paragraph from decades of history to the current campaign — the seam the writer asked for.', '''However'' in Sentence 3 feels like a hinge, but the contrast it marks happens within the historical narrative.', '1) Restate the two intended topics. 2) Label each sentence with the topic it serves. 3) Find where the labels switch. 4) Begin the new paragraph at the first sentence of the second topic. 5) Check that both halves stand alone.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4329634f2330aa34', 'act-english', 's-org', 3, 'For eleven years, Dr. Imai has returned to the same stretch of ice to remeasure a line of bamboo stakes. Each visit yields only a few numbers in a waterproof notebook. No single measurement says much on its own; the value grows with the column of figures.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main point about the slow accumulation of evidence in glacier research. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Bamboo is favored for stakes because it flexes without snapping in high winds.","letter":"A"},{"is_no_change":false,"label":"Dr. Imai also collaborates with colleagues who study permafrost in Alaska.","letter":"B"},{"is_no_change":false,"label":"Someday, satellites may make such repeated visits unnecessary.","letter":"C"},{"is_no_change":false,"label":"Only after a decade of these small entries does the glacier''s story become legible.","letter":"D"}]', 'D', '{"A":"Explains an equipment choice, shifting the closing focus from accumulating evidence to materials (add_offtopic).","B":"Introduces an unrelated collaboration instead of closing on the paragraph''s point (topic drift).","C":"Undercuts the paragraph by suggesting the patient method may soon be obsolete (goal_wrong_emphasis).","D":"Ties the years of tiny measurements to their payoff, restating the main point as a closing thought."}', 'It **circles back** to the paragraph''s central idea — that meaning emerges only from years of accumulated measurements.', 'The satellite option feels forward-looking and sophisticated, but it changes the subject rather than reinforcing the point.', '1) Write the paragraph''s main point in one short clause. 2) Test each closing sentence: does it restate or extend that point? 3) Eliminate any that add new topics, equipment trivia, or doubts about the method. 4) Keep the one that sends the reader off with the main idea.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-44472b51de9f9839', 'act-english', 's-org', 3, 'A test strip is a sliver of photographic paper exposed in timed bands. The printer covers the strip with a card, sliding it back every few seconds so each band receives more light than the one before. After development, the bands range from ghostly gray to nearly black.', 'The writer wants to conclude the paragraph with a sentence that emphasizes the test strip''s practical value to the printer. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Photographic paper is sold in boxes of twenty-five, fifty, or one hundred sheets.","letter":"A"},{"is_no_change":false,"label":"Reading those bands tells printers which exposure time to give the final print.","letter":"B"},{"is_no_change":false,"label":"Some printers save old strips for years, though few ever look at them again.","letter":"C"},{"is_no_change":false,"label":"A test strip needs the same developer, stop bath, and fixer as a full print.","letter":"D"}]', 'B', '{"A":"Introduces packaging trivia unrelated to the strip''s usefulness (add_offtopic), abandoning the stated goal.","B":"Correct: it converts the bands just described into the printer''s key decision, directly emphasizing practical value.","C":"Describes strips being kept but never used (goal_wrong_emphasis), which undercuts rather than emphasizes their value.","D":"States an accurate processing fact that shows no benefit to the printer (true_but_irrelevant), so it fails the goal."}', 'It ties the bands described in the paragraph to the **decision** they enable, which is exactly the practical value the goal demands.', 'The processing-steps sentence is factually true and on-topic, so students confuse accuracy with accomplishing the stated goal.', '1) Underline the goal words in the stem. 2) For each option, ask: does this sentence do that job, or is it merely true and related? 3) Eliminate options that add new topics, undercut the goal, or state inert facts. 4) Confirm the survivor links back to the paragraph''s content.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4608faf81ca8f750', 'act-english', 's-org', 3, '[1] Simultaneous exhibitions test a master''s stamina as much as her skill. [2] The master walks a ring of boards, pausing at each one just long enough to move. [3] Her opponents, meanwhile, enjoy the length of a full lap to plan a reply. [4] Some exhibitions stretch past six hours and cover more than forty boards. [5] At every stop, she has only seconds to read the position before circling on.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'C', '{"A":"Stranded after the statistics about hours and board counts, ''At every stop'' loses the walking scene it depends on.","B":"Placed before the paragraph describes the master walking a ring of boards, the phrase ''every stop'' has no referent.","C":"The sentence elaborates Sentence 2''s board-to-board pausing and sets up the contrast with the opponents'' full lap in Sentence 3.","D":"Placing it after the opponents'' full lap reverses the contrast that ''meanwhile'' is built on, forcing the reader backward."}', 'The sentence expands on the master''s **board-to-board pace** and must precede the contrasting note about her opponents'' full lap.', 'Leaving it where it is tempts because the sentence still makes literal sense at the end, hiding the broken link to the walking scene.', '1) Find the words in the movable sentence that depend on other sentences (''every stop,'' ''she,'' ''circling on''). 2) Locate the sentence that introduces those ideas. 3) Place the movable sentence immediately after its anchor. 4) Reread the paragraph to confirm each contrast lands in order.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4960358f79085373', 'act-english', 's-org', 3, '<p>[1] Every August, Kilnhouse Collective throws open its gates for the unbricking of its enormous wood-fired kiln. [2] Visitors begin lining up before dawn to watch the crew dismantle the kiln door brick by brick. [3] As each shelf emerges, volunteers ferry the still-warm pots to long tables on the lawn. [4] By noon, nearly every piece has been claimed by a collector or a curious first-timer.</p><p>The writer wants to add the following sentence to the paragraph:</p><p><em>The tradition began twelve years ago as a modest potluck for a dozen members.</em></p>', 'To make the paragraph most logical, the sentence should be placed after:', '[{"is_no_change":false,"label":"Sentence 1","letter":"A"},{"is_no_change":false,"label":"Sentence 2","letter":"B"},{"is_no_change":false,"label":"Sentence 3","letter":"C"},{"is_no_change":false,"label":"Sentence 4","letter":"D"}]', 'A', '{"A":"Correct: the origin backstory belongs right after the event is introduced, before the dawn-to-noon account begins.","B":"Interrupts the chronological account just as the crowd gathers and the door comes down (breaks the timeline).","C":"Wedges a twelve-year flashback between two tightly linked actions in the unloading sequence (severs linked actions).","D":"Dangles history after the paragraph''s closing image, leaving the story to trail off (backstory after the ending)."}', 'Background about an event belongs **where the event is introduced**, before the chronological narration starts.', 'Placing history at the very end feels like a graceful coda, but it strands the origin story after the day has already concluded.', '1) Identify what the added sentence does — here, it gives origin background. 2) Find where the paragraph introduces its subject in general terms. 3) Find where minute-by-minute narration begins. 4) Slot background between those two zones. 5) Reread to confirm the timeline flows unbroken.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4b308b7aeee39488', 'act-english', 's-org', 3, 'The bare chassis passed the weight check with nearly a pound to spare. <u>However,</u> the fully extended arm still pushed the robot two inches past the height limit.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Likewise,","letter":"D"}]', 'A', '{"A":"Correct: the transition signals the reversal from a passed weight check to a failed height limit.","B":"Treats the height failure as a result of passing the weight check, a false cause-effect link (transition_false_cause).","C":"Presents the height problem as an illustration of the first sentence, which it contradicts instead (transition_false_example).","D":"Claims the two inspection outcomes are similar when one is a success and the other a failure (transition_false_similarity)."}', 'The original transition correctly signals the **reversal** from a passed weight check to a failed height limit.', '''Therefore'' tempts students who read any two linked inspection facts as cause and effect.', '1) State the first sentence''s idea in five words. 2) State the second sentence''s idea. 3) Label the relationship: contrast, cause, example, or addition. 4) Match the transition word to that label and reject the rest.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-595df849946ff63e', 'act-english', 's-org', 3, 'The Gazette''s print circulation has fallen for nine straight years. <u>Similarly,</u> its free email newsletter now reaches three times as many readers as the printed paper did at its peak.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"In contrast,","letter":"D"}]', 'D', '{"A":"''Similarly'' claims the two facts run in the same direction, but decline and growth pull opposite ways.","B":"''Therefore'' invents a cause-effect link the sentences never state.","C":"''For example'' would make the newsletter''s growth an instance of print''s decline, which it is not.","D":"Correct: it signals the reversal between shrinking print readership and booming digital readership."}', 'Only this transition matches the **logical turn** from a shrinking print run to a growing digital readership.', '''Similarly'' tempts readers because both sentences describe the same newspaper''s audience, so they feel parallel.', '1) Summarize the sentence before the transition in five words. 2) Summarize the sentence after it. 3) Name the relationship: same direction, reversal, cause, or example. 4) Test the transition by reading both sentences with it. 5) Keep only the transition that matches the named relationship.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-597c46fcebdff180', 'act-english', 's-org', 3, '[1] The shop opened in a former hardware store whose original shelving still lines the walls. [2] Early volunteers sorted donations by lantern light during the building''s first drafty winter. [3] A kitchen fire in 1994 nearly ended the operation, but neighbors rebuilt the interior in a single summer. [4] Today, the main floor is divided into wings for clothing, housewares, and media. [5] Hand-painted signs guide shoppers from the register toward each wing.', 'The writer wants to divide this paragraph into two paragraphs, the first about the shop''s history and the second about its present-day layout. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'C', '{"A":"Splits the opening from the rest of the history, leaving Sentence 1 stranded and mixing eras in the second paragraph.","B":"Puts the 1994 fire — a historical event — at the head of the present-day paragraph.","C":"Correct: ''Today'' marks the pivot from decades of history to the current layout, so the new paragraph starts there.","D":"Separates the signs from the wings they point to, splitting the layout description in half."}', 'The word **Today** in Sentence 4 signals the shift from past events to the current layout, exactly where the stem says the second paragraph should begin.', 'The fire feels like a dramatic turning point, so starting a new paragraph at Sentence 3 seems natural even though the fire still belongs to the history.', '1) Label each numbered sentence as ''history'' or ''present layout.'' 2) Find where the labels flip. 3) Check for a time-shift signal word at that seam. 4) Start the new paragraph at the first sentence of the second label. 5) Confirm both halves read as unified paragraphs.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5a6cb4caa45e8765', 'act-english', 's-org', 3, 'The city promised new water spigots for the garden last spring. <u>Similarly,</u> the trenching work has been postponed twice.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"Therefore,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'B', '{"A":"Wrong logic: a similarity transition claims the second sentence mirrors the first, but repeated delays cut against the promise.","B":"Correct: the second sentence reverses the expectation set by the promise, which calls for a contrast transition.","C":"False cause: nothing about promising spigots produces the postponements.","D":"The delay is not an instance of the promise; it is evidence the promise is going unmet."}', 'The delays **contradict** the expectation created by the promise, so the sentences need a contrast transition.', 'Both sentences concern the same spigot project, so students mistake shared topic for shared direction and keep the similarity word.', '1) Restate each sentence in your own words. 2) Ask what the first sentence leads you to expect. 3) Decide whether the second sentence fulfills, reverses, causes, or illustrates that expectation. 4) Match the transition to that exact relationship. 5) Reread with the transition in place to confirm the logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5d41838271188fa8', 'act-english', 's-org', 3, '[1] Carlsbad Caverns began as a limestone reef beneath an ancient inland sea. [2] Over millions of years, acidic groundwater hollowed the reef into chambers of astonishing size. [3] Today, though, the park is famous less for its geology than for its bats. [4] On summer evenings, hundreds of thousands of Brazilian free-tailed bats spiral out of the natural entrance. [5] Rangers run an amphitheater program so visitors can watch the nightly exodus.', 'The writer wants to divide this paragraph into two paragraphs, each focused on a single subject. Beginning the second paragraph with which sentence best accomplishes that goal?', '[{"is_no_change":false,"label":"Sentence 2","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 4","letter":"C"},{"is_no_change":false,"label":"Sentence 5","letter":"D"}]', 'B', '{"A":"Splits the two geology sentences apart, stranding the opener as a one-sentence paragraph.","B":"Opens the new paragraph exactly where the topic pivots from geology to bats, with ''Today, though'' signaling the shift.","C":"Strands the pivot sentence with the geology material it explicitly turns away from.","D":"Separates the amphitheater detail from the bat flight it depends on."}', 'Sentence 3 carries the **topic-shift signal** (''Today, though...'') that turns from cave formation to bats.', 'Sentence 4 attracts students because it is the first sentence packed with bat imagery, but the pivot actually happens one sentence earlier.', '1) Label each sentence''s topic in one word. 2) Find where the label changes. 3) Check for a pivot cue (today, however, but) at that seam. 4) Start the new paragraph at the first sentence bearing the new label.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5f5c97e096de64cc', 'act-english', 's-org', 3, 'The main branch stays open until nine on weeknights. <u>Similarly,</u> the storefront branch in the mill district locks its doors at five.', 'Which transition word or phrase is most logical here?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In fact,","letter":"B"},{"is_no_change":false,"label":"As a result,","letter":"C"},{"is_no_change":false,"label":"By contrast,","letter":"D"}]', 'D', '{"A":"''Similarly'' claims the two branches behave alike, but staying open until nine and closing at five are opposites.","B":"''In fact'' intensifies or confirms the previous claim; it cannot signal that the second branch does the opposite.","C":"''As a result'' invents a cause-effect link — the storefront''s early closing is not caused by the main branch''s late hours.","D":"Correct: the two sentences present opposing facts, so an opposition transition is required."}', 'The sentences present **opposing** facts — late hours versus early closing — so the transition must signal opposition.', '''As a result'' tempts students who assume adjacent sentences must always be linked by cause and effect.', '1) Read the sentence before and the sentence after the transition. 2) State their relationship in your own words: agree, oppose, cause, example, or sequence. 3) Match the transition to that stated relationship. 4) Re-read with your choice inserted to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-60e48f57b7486906', 'act-english', 's-org', 3, '[1] According to family legend, my great-grandfather chose Minnesota because a steamship poster showed wheat fields that reminded him of home. [2] My grandmother swore the poster hung for years in a shop window in Bergen. [3] The documents, however, tell a less romantic story. [4] A labor contract preserved in the county archive shows that a railroad agent recruited him and paid his passage. [5] The contract bound him to two years of track work at a fixed wage. [6] Whatever drew him across the ocean, he stayed, and four generations of us have followed.', 'The writer wants to divide the paragraph into two paragraphs in order to separate the family legend from the documentary record. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'B', '{"A":"Splits the legend material in half, since the grandmother''s memory of the poster is still part of the legend.","B":"Correct: this sentence announces the pivot from legend to documents, so it should open the second paragraph.","C":"Starts with the first archival detail but strands the pivot sentence back with the legend.","D":"Breaks in the middle of the contract discussion, splitting the documentary record itself."}', 'Sentence 3 **announces the pivot** from legend to documents, so the second paragraph should open with it.', 'Sentence 4 attracts readers because it contains the first archival detail, but choosing it strands the pivot sentence with the legend.', '1) Label each sentence by topic: legend or record. 2) Find the boundary where the labels flip. 3) Look for a signpost sentence that announces the new topic — it belongs at the top of the new paragraph. 4) Verify each resulting paragraph is unified. 5) Choose that boundary sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6340c73cdc011285', 'act-english', 's-org', 3, 'Over the past decade, the city has converted more than thirty vacant lots into pocket parks. Most are no larger than a house lot, yet each has become a gathering spot, with benches, shade trees, and room for a food cart or two. Crime reports near the converted lots have declined, and adjacent storefronts report steadier foot traffic.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main point. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Public parks have been part of American city planning since the nineteenth century.","letter":"A"},{"is_no_change":false,"label":"Fencing and irrigation account for most of a pocket park''s start-up costs.","letter":"B"},{"is_no_change":false,"label":"In these modest plots, the city has discovered that a park''s impact does not depend on its acreage.","letter":"C"},{"is_no_change":false,"label":"The city''s next campaign will ask voters to approve a downtown convention center.","letter":"D"}]', 'C', '{"A":"This reaches for broad history the paragraph never discusses — the misconception that a sweeping statement makes a strong ending.","B":"This adds a stray cost detail instead of pulling the paragraph''s evidence together.","C":"This distills the paragraph''s evidence — small sites, big neighborhood gains — into a closing generalization.","D":"This swerves to an unrelated future project, abandoning the paragraph''s subject entirely."}', 'A strong conclusion **generalizes from the paragraph''s own evidence** — here, that tiny sites produced big gains.', 'The historical statement sounds authoritative and park-related, so its disconnection from this paragraph''s evidence is easy to miss.', '1) State the paragraph''s main point in one clause. 2) Cross out any option introducing information the paragraph never developed. 3) Cross out any option narrower than the main point. 4) Keep the option that restates the point using the paragraph''s own thrust. 5) Re-read the paragraph plus your ending.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a191c13331eade1', 'act-english', 's-org', 3, 'Baking soda is inert on its own and must borrow an acid from the batter before it can lift anything. <u>Likewise,</u> baking powder arrives with its own acid built in, needing only moisture and heat to fire.', 'Which transition most logically connects the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For instance,","letter":"B"},{"is_no_change":false,"label":"In contrast,","letter":"C"},{"is_no_change":false,"label":"As a result,","letter":"D"}]', 'C', '{"A":"Wrong-logic transition: ''Likewise'' promises similarity, but one leavener must borrow an acid while the other carries its own — a difference.","B":"Wrong-logic transition: the second sentence is not an example of the first claim; it presents an opposing design.","C":"Correct: the two sentences oppose each other on the key point — needing an outside acid versus carrying one built in.","D":"Wrong-logic transition: nothing in the sentences claims the first fact caused the second."}', 'The two leaveners **differ** on the crucial point — borrowed acid versus built-in acid — so the connector must signal opposition.', 'Both sentences describe leaveners and acids, so the surface similarity of topic makes a similarity word feel right.', '1) Summarize the sentence before the transition in five words. 2) Summarize the sentence after it in five words. 3) Name the true relationship: same direction, example, cause-effect, or opposition. 4) Check that the transition''s job matches that relationship. 5) If not, pick the connector whose job does.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6ebca3ed776d7561', 'act-english', 's-org', 3, '[1] Restorers begin by photographing the chassis from every angle before touching a single wire. [2] These photographs become the map they will follow during reassembly. [3] Only then do they pull the tubes, labeling each socket as they go. [4] Wax capacitors, the most frequent casualties of age, are replaced next. [5] Finally, the cabinet is cleaned and waxed with conservator-grade polish.', 'For the sake of the logic and cohesion of the paragraph, Sentence 2 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 3.","letter":"B"},{"is_no_change":false,"label":"after Sentence 4.","letter":"C"},{"is_no_change":false,"label":"after Sentence 5.","letter":"D"}]', 'A', '{"A":"Correct: ''These photographs'' must directly follow Sentence 1, which introduces the photographing, and the map idea sets up the ordered steps that follow.","B":"Moving the sentence after the tube-pulling step separates ''These photographs'' from its antecedent.","C":"Placing the purpose of the photographs after the capacitor stage strands the reference and interrupts the repair sequence.","D":"Putting a setup sentence after the job is finished leaves ''These'' with nothing nearby to point to and previews a step already completed."}', 'The pointer phrase **''These photographs''** must sit immediately after the sentence that creates the photographs, and its map idea frames the steps that follow.', 'Because reassembly happens late in a restoration, students are tempted to push the map sentence toward the end, forgetting that ''These'' needs its antecedent next door.', '1) Find pointer words in the movable sentence (''These,'' ''this,'' ''such''). 2) Locate the sentence that introduces what they point to. 3) Keep the pointer sentence immediately after that antecedent. 4) Check that the paragraph''s step order still reads first-to-last. 5) Reread the full paragraph to confirm cohesion.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-748983e9db5d8d25', 'act-english', 's-org', 3, 'Donations surge every January as households clear out their closets. <u>As a result,</u> the back room often overflows before the month is half over.', 'Which transition provides the most logical link between these sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'A', '{"A":"Correct: the overflowing back room is a direct consequence of the January surge, so a cause-effect transition fits.","B":"Signals contrast, but the second sentence follows from the first rather than opposing it.","C":"Promises an illustration, but the second sentence states an effect, not an example of the surge.","D":"Suggests two unrelated events unfolding at the same time, missing the causal link."}', 'The second sentence is the **effect** of the first, so the transition must signal cause and result.', 'Both sentences do happen in the same season, so a time-based connector can feel plausible at a glance.', '1) Read the sentence before and after the transition. 2) State the relationship in your own words (cause? opposite? example? time?). 3) Match that relationship to the transition''s job. 4) Reject any connector whose job doesn''t match. 5) Re-read with your pick inserted.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-78da321a18e5e6b8', 'act-english', 's-org', 3, 'For years, the letters my great-grandfather mailed from Buenos Aires sat in a shoebox labeled ''miscellaneous.'' Last spring, my mother and I scanned all ninety-four of them and tagged each with its date and postmark. As we worked, we watched his Spanish creep into his Yiddish sentences, one borrowed word at a time.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main point about what the letters reveal. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Scanning fragile letters requires patience and a steady flatbed scanner.","letter":"A"},{"is_no_change":false,"label":"Read in order, the letters trace a man slowly turning into someone new.","letter":"B"},{"is_no_change":false,"label":"Buenos Aires drew thousands of Eastern European immigrants into its port neighborhoods in the early twentieth century.","letter":"C"},{"is_no_change":false,"label":"My mother hopes to read and digitize our photo albums next winter.","letter":"D"}]', 'B', '{"A":"Ends on equipment and procedure, abandoning the paragraph''s point about what the letters reveal.","B":"Correct: it restates the paragraph''s discovery — a gradual transformation visible across the letters — in a closing image.","C":"Zooms out to a broad historical statistic, widening the lens far beyond this one family''s papers.","D":"Pivots to a future project, introducing material the paragraph never developed."}', 'It **restates the paragraph''s discovery** — the gradual transformation visible across the letters — in a single closing image.', 'The historical statistic feels weighty and on-theme for immigration, but it widens the lens far beyond what these letters reveal.', '1) Restate the paragraph''s main point in your own words. 2) Ask what the stem requires the final sentence to do. 3) Test each option: does it return to that point, or drift to process, background, or future plans? 4) Eliminate any sentence introducing material the paragraph never developed. 5) Choose the one that echoes the main point.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-79d1143c12112e03', 'act-english', 's-org', 3, 'Most plans schedule a cutback week every month because rest is what lets the body absorb hard training. <u>Similarly,</u> some runners skip these easier weeks, worried that backing off will cost them fitness.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example,","letter":"B"},{"is_no_change":false,"label":"Nevertheless,","letter":"C"},{"is_no_change":false,"label":"As a result,","letter":"D"}]', 'C', '{"A":"''Similarly'' promises a parallel idea, but the second sentence works against the first sentence''s logic (transition_false_parallel).","B":"''For example'' claims the second sentence illustrates the first, yet skipping rest weeks is the opposite of the practice described (transition_false_example).","C":"Correct: the runners act despite the reasoning in the first sentence, so a concessive contrast word fits the relationship.","D":"''As a result'' asserts that the plans'' reasoning caused the skipping, but the runners are defying that reasoning, not following it (transition_wrong_causation)."}', 'The second sentence describes runners acting **against** the logic of the first, so the transition must signal contrast or concession.', '''As a result'' tempts students who see any second sentence about runner behavior as an outcome of the first sentence''s claim.', '1) Restate each sentence in your own words. 2) Name the relationship: same direction, contrast, cause-effect, or example. 3) Check whether the second sentence follows the first''s logic or resists it. 4) Match the connector to that relationship. 5) Re-read both sentences with the connector in place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7b69ae0f83310c12', 'act-english', 's-org', 3, '<p>[1] The bleaching begins invisibly, with stressed corals expelling the colorful algae that both feed and tint them. [2] Within weeks the reef fades to a ghostly white, and if warm water lingers, the starved animals die. [3] Scientists once thought such events were rare, but severe bleaching now strikes many reefs several times a decade.</p>', 'The writer wants an opening sentence that introduces the paragraph''s focus on coral bleaching as a gradual, escalating process. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Coral reefs are among the most biologically diverse ecosystems on the planet.","letter":"A"},{"is_no_change":false,"label":"Warm water is only one of many threats that reefs face today.","letter":"B"},{"is_no_change":false,"label":"Divers often describe the eerie beauty of a freshly bleached reef.","letter":"C"},{"is_no_change":false,"label":"Coral bleaching unfolds in stages, each one pushing a reef closer to collapse.","letter":"D"}]', 'D', '{"A":"A generic praise of reef diversity ignores the paragraph''s specific focus on the stages of bleaching (misconception: intro_too_broad).","B":"It shifts attention to the range of threats rather than the single escalating process the paragraph traces (misconception: intro_wrong_focus).","C":"It fixes on divers'' aesthetic reactions, a side detail absent from the paragraph''s body (misconception: intro_offtopic_detail).","D":"It names bleaching as a staged, worsening process, framing the step-by-step description that follows."}', 'The paragraph traces bleaching **stage by stage**, so the opener must announce a gradual, escalating process.', 'The diversity sentence sounds like a natural reef-topic opener, but it never mentions bleaching or its progression.', '1) Read the whole paragraph and state its single controlling idea in one phrase. 2) List what the body sentences actually cover. 3) Choose the opener that both names that idea and sets up the body. 4) Reject openers that are broader than the paragraph, shift its focus, or fixate on a side detail.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7d69ceba7b0daba8', 'act-english', 's-org', 3, 'During the 1930s, Kansas City''s political bosses let nightclubs run until dawn, so paying work for musicians rarely dried up. <u>As a result,</u> players from across the Southwest settled in the city, and its after-hours jam sessions became a rigorous school for young soloists.', 'Which transition most logically connects the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"Meanwhile,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'A', '{"A":"Correct: the steady work described in sentence one *caused* the influx of players, so the causal transition fits.","B":"transition_wrong_logic: *However* signals contrast, but nothing in the second sentence opposes the first.","C":"*Meanwhile* implies two simultaneous, unrelated happenings, erasing the cause-effect link.","D":"*For example* promises an illustration, but the second sentence is a consequence, not an instance."}', 'The second sentence is the **effect** of the steady work described in the first.', '*Meanwhile* feels safe because both sentences describe the same decade, but it hides the causal link between them.', '1) Restate sentence one and sentence two in your own words. 2) Ask: is sentence two a consequence, a contrast, an example, or merely next in time? 3) Pick the transition that names that exact relationship. 4) Reread with your choice in place to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7e371a1d747a566f', 'act-english', 's-org', 3, '[1] When rotation appears on radar, the local forecast office weighs the signature against reports from trained spotters on the ground. [2] If the evidence is convincing, a warning goes out to phones, sirens, and broadcasters within minutes. [3] Residents in the storm''s path are urged to move to interior rooms on the lowest floor. [4] After the storm passes, survey teams examine the damage to confirm whether a tornado actually touched down.', 'The writer wants to add the following sentence to the paragraph:

*Spotters are especially valuable because radar cannot show what is happening at ground level.*

For the sake of the logic and cohesion of the paragraph, the sentence should be placed:', '[{"is_no_change":false,"label":"before Sentence 1","letter":"A"},{"is_no_change":false,"label":"after Sentence 1","letter":"B"},{"is_no_change":false,"label":"after Sentence 3","letter":"C"},{"is_no_change":false,"label":"after Sentence 4","letter":"D"}]', 'B', '{"A":"Placed first, the sentence praises spotters before either spotters or radar has been introduced (misconception: explanatory sentences belong up front).","B":"Correct: Sentence 1 introduces both radar and spotters, so the explanation of why spotters matter follows it naturally.","C":"Wedged after the safety instructions, the sentence interrupts the sequence from warning to sheltering (misconception: extra facts can go wherever space remains).","D":"At the end, the sentence trails the damage-survey step, which it has nothing to do with (misconception: added material defaults to the end)."}', 'The sentence explains ideas introduced in Sentence 1, so **cohesion** demands it sit immediately after that introduction.', 'Adding new material at the very end feels safe because nothing after it can be disrupted — but the sentence then dangles far from the ideas it explains.', '1) Circle the key nouns in the sentence to be added. 2) Find where those nouns first appear in the paragraph. 3) Place the new sentence just after the sentence that introduces them. 4) Re-read the paragraph to check no sequence is interrupted. 5) Confirm every pronoun and reference still points backward, never forward.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-81db0e75593e4843', 'act-english', 's-org', 3, '[1] The Riverbend Chess Society began in 1987 with six members and a borrowed classroom. [2] Its founder, a retired mail carrier, bought the club''s first clocks himself. [3] Meetings moved twice before the society settled into the old firehouse on Grant Street. [4] For years, the group''s only trophy was a hand-painted pawn. [5] Last season, Riverbend entered the state league for the first time. [6] Its top board won nine straight matches against far larger clubs. [7] The society now hosts the very qualifier it once only dreamed of attending.', 'The writer wants to divide this paragraph into two, with the first paragraph focusing on the society''s humble early years and the second on its recent rise. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'D', '{"A":"Splitting after the opening line severs the founder''s clock purchase from the founding story it belongs to.","B":"The move into the old firehouse is still part of the club''s scrappy early history, not its recent success.","C":"The hand-painted pawn is the clearest image of the humble era; breaking before it strands that detail in the wrong paragraph.","D":"''Last season'' pivots both the time frame and the topic, launching the account of the club''s recent breakthrough."}', '''Last season'' marks the spot where **time frame and topic shift together**, from humble origins to recent success.', 'The trophy sentence tempts as a break point because a trophy suggests success, but a hand-painted pawn actually epitomizes the modest years.', '1) Label each sentence by era and topic. 2) Find the seam where both the time frame and the subject change at once. 3) Begin the new paragraph at the first sentence of the new era. 4) Reread both halves to confirm each is unified.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-82027ca70f8392b1', 'act-english', 's-org', 3, 'Every December, dozens of volunteers fan out across our county for the annual winter bird count. Working in teams from dawn to dusk, they tally every cardinal, crow, and kinglet they can find. Scientists then compare the totals with decades of earlier tallies to detect population shifts.', 'The writer wants to conclude the paragraph with a sentence that emphasizes the lasting scientific value of the volunteers'' work. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Some volunteers bring thermoses of hot cocoa to share during the long day.","letter":"A"},{"is_no_change":false,"label":"Birds are also tallied during springtime surveys held throughout North America.","letter":"B"},{"is_no_change":false,"label":"The county''s first winter count was organized more than fifty years ago.","letter":"C"},{"is_no_change":false,"label":"In this way, a single Saturday of counting by amateurs becomes part of a scientific record spanning generations.","letter":"D"}]', 'D', '{"A":"A cozy sidelight about snacks ignores the stated goal of emphasizing lasting scientific value.","B":"Broadening to other surveys elsewhere drifts away from this count and these volunteers.","C":"A founding date supplies history but never connects the volunteers'' effort to ongoing science.","D":"Correct: it explicitly ties one day of volunteer effort to the long-term data scientists depend on."}', 'Only this sentence links the volunteers'' one-day effort to the **long-term scientific value** the stem demands.', 'The founding-date option feels weighty and historical, so students mistake age for scientific importance.', '1) Underline the goal stated in the stem. 2) For each option, ask: does it address that exact goal, or something merely related? 3) Eliminate options that are on-topic but off-goal. 4) Pick the sentence that names the goal''s key idea most directly.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-84bd26e843217d93', 'act-english', 's-org', 3, 'Our town''s farmers'' market started with four vendors in a parking lot. <u>In conclusion,</u> it now fills two blocks every Saturday with more than sixty stalls.', 'Which transition best fits the contrast between the market''s past and present?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Because of this,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Today,","letter":"D"}]', 'D', '{"A":"''In conclusion'' signals a summary, but this sentence contrasts then with now.","B":"''Because of this'' invents a cause-effect tie between the four vendors and the sixty stalls.","C":"''For example'' would need the second sentence to illustrate the first, not update it.","D":"''Today'' cleanly marks the shift from the market''s origins to its current size."}', 'The sentences contrast **past and present**, so a time-shift transition (''today'') is right.', 'The sentence sits at a paragraph''s end, so ''in conclusion'' feels structurally natural.', 'Position doesn''t dictate the transition — the logical relationship does.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-93dab2fe84ba3929', 'act-english', 's-org', 3, 'The vote passed by a wide margin. <u>Similarly,</u> a small group of residents has already filed an appeal.', 'Which transition best captures the relationship between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"Likewise,","letter":"C"},{"is_no_change":false,"label":"Still,","letter":"D"}]', 'D', '{"A":"''Similarly'' claims the appeal resembles the wide-margin vote; it actually opposes it.","B":"''Therefore'' implies the appeal results from the margin, which it doesn''t.","C":"''Likewise'' also signals similarity, the wrong direction.","D":"''Still'' concedes that, despite the wide margin, opposition remains — the true relationship."}', 'The second sentence **pushes against** the first, so a concessive transition (''still'') fits.', 'Both sentences describe reactions to the vote, so ''similarly'' feels plausible.', 'Decide whether sentence two agrees, opposes, or results — then match the transition to that.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-94e4cd714878ec71', 'act-english', 's-org', 3, '<p>[1] Coral polyps look deceptively simple, resembling tiny upside-down jellyfish anchored to a stony cup. [2] Each polyp secretes calcium carbonate around its base, and generation after generation cements new layers onto the old. [3] Over centuries these layers accumulate into the massive limestone ridges we call reefs. [4] A whole reef, then, is really the collective skeleton of billions of these minuscule builders. [5] Tourism built on reefs generates billions of dollars for coastal economies each year. [6] Dive operators, hotels, and restaurants all depend on the reefs staying healthy and vivid.</p>', 'The writer wants to divide this text into two paragraphs so that each has a single clear focus. The second paragraph should begin at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 6.","letter":"D"}]', 'C', '{"A":"Sentences 1 and 2 both describe the polyp''s structure and secretion, so splitting between them cuts one idea in half (misconception: divide_mid_topic).","B":"Sentence 3 continues the same reef-building process begun in Sentence 2, so the topic hasn''t shifted yet (misconception: divide_too_early).","C":"The focus turns from how reefs are built (1–4) to their economic value (5–6) exactly at Sentence 5.","D":"Sentences 5 and 6 both concern reef tourism, so dividing between them splits the new topic (misconception: divide_too_late)."}', 'The text shifts from the **biology of reef-building** (Sentences 1–4) to **reef economics** (Sentences 5–6) at Sentence 5.', 'Sentence 6 lists specific businesses, so it feels like a fresh start even though it merely extends the tourism idea introduced in Sentence 5.', '1) Give each sentence a one-word topic tag. 2) Scan the tags for the point where the topic clearly changes. 3) Start the new paragraph at the first sentence of the new topic. 4) Do not divide within a run of sentences sharing one topic, whether early or late.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-95a125eb80c9339a', 'act-english', 's-org', 3, 'Twice a day, at hundreds of stations around the world, technicians release weather balloons that climb until they burst high in the stratosphere. Each balloon carries a radiosonde, an instrument package that measures temperature, humidity, and pressure as it rises. The readings stream back to forecast centers within minutes.', 'The writer wants to conclude the paragraph with a sentence that emphasizes the global coordination of the balloon launches. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Radiosondes were first developed in the 1930s and have changed little since then.","letter":"A"},{"is_no_change":false,"label":"Some launches send balloons drifting a hundred miles before the instruments parachute back to earth.","letter":"B"},{"is_no_change":false,"label":"Forecasters also rely on satellites, radar, and surface stations to monitor the atmosphere.","letter":"C"},{"is_no_change":false,"label":"Together, these simultaneous launches give forecasters a snapshot of the entire atmosphere at the same instant.","letter":"D"}]', 'D', '{"A":"Shifts to the instrument''s design history, which says nothing about worldwide coordination (misconception: any related fact can close a paragraph).","B":"Follows a single balloon''s drift, a local detail that narrows the scope when the goal demands scale (misconception: vivid detail equals strong conclusion).","C":"Broadens to other observing tools, diluting the paragraph''s focus on balloon launches (misconception: a wider survey feels suitably ''global'').","D":"Correct: it names the shared timing of the launches and their worldwide payoff, exactly the coordination the goal requires."}', 'Only this choice states that the launches happen **worldwide on a shared schedule**, which is the coordination the goal names.', 'The option adding satellites and radar feels appropriately global, but it drifts from balloon launches to other tools entirely.', '1) Restate the stated goal in your own words. 2) Strike any option that changes the subject. 3) Strike any option that zooms in on a single case when the goal is scale. 4) Of what remains, pick the sentence whose main clause states the goal''s idea directly. 5) Re-read the paragraph with it in place to confirm the emphasis.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9bbf3af88d80724e', 'act-english', 's-org', 3, '<p>[NEW OPENING SENTENCE] Twice a month, members haul buckets of bone-dry scraps to the reclaim station, where the shards soak overnight in water. The softened slurry is then spread across plaster slabs until it stiffens. Finally, volunteers wedge the reclaimed clay into neat blocks and return it to the communal shelves. Last year the program put more than a ton of clay back into members'' hands.</p>', 'The writer wants to open the paragraph with a sentence that introduces its main focus. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Rather than discarding unusable clay, Millbrook Pottery runs a reclaim program that turns studio scraps back into fresh working material.","letter":"A"},{"is_no_change":false,"label":"Plaster slabs wear down over time and must be resurfaced every few years.","letter":"B"},{"is_no_change":false,"label":"People have shaped vessels from clay for more than twenty thousand years.","letter":"C"},{"is_no_change":false,"label":"Millbrook Pottery also hosts a popular series of weekend glaze-chemistry workshops.","letter":"D"}]', 'A', '{"A":"Correct: it names the reclaim program and previews the scrap-to-fresh-clay process the paragraph then details.","B":"Spotlights one minor prop from the middle of the paragraph, far too narrow to frame the whole process (too-narrow opener).","C":"Sweeps across twenty thousand years of history the paragraph never discusses (too-broad opener).","D":"Introduces a different program entirely, which nothing in the paragraph develops (off-topic opener)."}', 'A strong opener **previews the paragraph''s whole focus** — here, the studio''s process for turning scraps back into usable clay.', 'The broad history of ceramics sounds impressively essay-like, so students pick grandeur over fit.', '1) Read the paragraph and state its main focus in one phrase. 2) Test each opener: does it announce that exact focus? 3) Reject openers wider than the paragraph. 4) Reject openers that enlarge one small detail. 5) Reject openers about topics the paragraph never returns to.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a15393b9641a06c1', 'act-english', 's-org', 3, '[1] For most of the twentieth century, the observatory''s records lived on paper. [2] Scientists inked each day''s tremor onto smoked drums and filed the sheets in long rows of cabinets. [3] Retrieving a single week of records could swallow an entire afternoon. [4] Digital networks ended that era in the 1990s. [5] Today a researcher can pull up decades of waveforms in seconds and compare eruptions on opposite sides of the world.', 'The writer wants to divide this paragraph into two paragraphs in order to separate its two main ideas. The best place to begin the new paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 4.","letter":"D"}]', 'D', '{"A":"Splits the paper era right after its topic sentence, stranding the details that support it.","B":"Separates the retrieval frustration from the paper filing system it complains about.","C":"Cuts the digital era in half, divorcing ''Today...'' from the technological shift that produced it.","D":"Correct: the arrival of digital networks begins the paragraph''s second main idea."}', 'The paragraph''s subject **turns** at the arrival of digital networks, so the second paragraph should begin there.', '''Today'' sounds like a fresh start, tempting readers to break at the final sentence even though the digital era begins one sentence earlier.', '1) Label each sentence with its idea in two or three words. 2) Find where the labels change subject. 3) Begin the new paragraph at the first sentence of the new subject. 4) Check both halves: each should read as one unified topic.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a18f5d24955a1478', 'act-english', 's-org', 3, 'Most first-time visitors picture Congaree National Park as a gloomy swamp. <u>Similarly,</u> the park is a floodplain forest that drains and refills as its river rises and falls.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"In fact,","letter":"C"},{"is_no_change":false,"label":"For example,","letter":"D"}]', 'C', '{"A":"Signals similarity, but the second sentence corrects the first impression rather than resembling it.","B":"Claims the second sentence results from the first, yet no cause-effect link exists between an impression and the park''s hydrology.","C":"Signals that the second sentence sets the record straight, which matches the correction of a mistaken picture.","D":"Promises an illustration, but the second sentence reclassifies the park instead of giving an instance of the swamp idea."}', 'The second sentence **corrects** a common misconception, so the transition must signal contradiction-plus-clarification.', '''Therefore'' tempts readers who treat any logical connector as interchangeable glue between related sentences.', '1) State each sentence''s idea in five words. 2) Name the relationship: cause, contrast, example, addition, or correction. 3) Test the transition by substituting its plain meaning (''as a result,'' ''likewise,'' ''for instance''). 4) Keep only the transition whose meaning survives the substitution.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a332188fb950d162', 'act-english', 's-org', 3, 'The old ferry crossing took nearly an hour even in calm weather. <u>Similarly,</u> the new bridge carries commuters over the strait in about six minutes.', 'Which choice provides the most effective transition?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In fact,","letter":"B"},{"is_no_change":false,"label":"Consequently,","letter":"C"},{"is_no_change":false,"label":"By contrast,","letter":"D"}]', 'D', '{"A":"''Similarly'' claims the two crossings are alike, but an hour-long ferry ride and a six-minute drive are opposites (misconception: transition_likeness_for_opposition).","B":"''In fact'' intensifies or confirms the previous claim, but the second sentence reverses direction rather than strengthening it (misconception: transition_intensifier_misread).","C":"''Consequently'' asserts that the ferry''s slowness caused the bridge''s speed, a causal link the passage never makes (misconception: transition_false_cause).","D":"The sentences set a slow crossing against a fast one, so an opposition transition is the logical choice."}', 'The two sentences describe **opposite** experiences — an hour versus six minutes — so the transition must signal a reversal.', 'Both sentences describe crossing the same strait, so students latch onto the shared topic and choose a likeness word despite the opposing details.', '1) Identify the key detail in each sentence (here, the two travel times). 2) Ask whether the details agree, oppose, or cause one another. 3) Reject any transition that names a different relationship. 4) Insert the surviving transition and reread both sentences to confirm the logic flows.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a7ca7eb4c20f4acb', 'act-english', 's-org', 3, '[1] ______ [2] By six each Saturday, Marisol has already pulled forty sourdough loaves from her portable oven. [3] Customers begin lining up for her caraway rye before she finishes unloading. [4] By ten, only crumbs remain on the wooden boards.', 'The writer wants to open the paragraph with a sentence that introduces its main subject and prepares readers for the details that follow. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"A visit to Marisol''s bread stand rewards the market''s earliest risers.","letter":"A"},{"is_no_change":false,"label":"Farmers'' markets in this country date back to the colonial era.","letter":"B"},{"is_no_change":false,"label":"Sourdough bread rises with a starter made of fermented flour and water.","letter":"C"},{"is_no_change":false,"label":"Marisol also sells peach jam produced by a neighboring farm.","letter":"D"}]', 'A', '{"A":"Correct — it names the paragraph''s subject, Marisol''s stand, and its early-riser angle forecasts the timeline of details that follow.","B":"Opens with a scope far wider than one baker''s Saturday morning (broad_opener).","C":"Zooms in on a technical baking detail the paragraph never develops (narrow_offfocus).","D":"Introduces a side product that no later sentence mentions (add_offtopic)."}', 'It names the paragraph''s subject and **forecasts** the early-morning urgency that every following sentence develops.', 'The historical opener sounds authoritative and market-related, so students accept a scope far wider than one baker''s Saturday.', '1) Read the body sentences and list what they share (one baker, early hours, fast sellout). 2) Draft a one-line topic from that list. 3) Test each option: does it name that subject and match that scope? 4) Reject options that are broader, narrower, or about a different detail. 5) Confirm the survivor flows smoothly into the second sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a8e08bcdb07e4ea2', 'act-english', 's-org', 3, '[1] The club''s sidewalk astronomy nights begin wherever downtown foot traffic is heaviest. [2] Volunteers roll a telescope to a busy corner and aim it at whatever is bright that evening. [3] Within minutes, passersby who have never looked through an eyepiece are lining up for a turn. [4] By closing time, the chalkboard beside the tripod is covered with questions for next month.<br><br>The writer wants to add the following sentence to the paragraph:<br><em>A hand-lettered sign reading "Free—come look at the Moon" does the rest of the advertising.</em>', 'To make the paragraph most logical, the new sentence should be placed:', '[{"is_no_change":false,"label":"before Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'C', '{"A":"Before anything is set up, there is no scene, telescope, or ''rest'' for the sign''s advertising to complete.","B":"The telescope has not yet been rolled out, so the sign has nothing to stand beside and no first step to finish.","C":"Correct: once the telescope is out on the corner, the sign completes the setup and explains why passersby line up next.","D":"After the crowd has come and gone, a sentence about attracting people arrives too late to do its job."}', 'The sign belongs **between the setup and the crowd**: it completes the equipment scene and directly explains the line that forms in the next sentence.', 'Placing the sign after the opening sentence tempts students because advertising sounds like a first step, but the sign''s phrase ''the rest'' requires the telescope to be out already.', '1) Find the new sentence''s anchors: words that point backward (''the rest of the advertising'') and content that points forward (attracting people). 2) Locate the sentence that satisfies the backward anchor. 3) Check that the following sentence benefits from the forward content. 4) Test the placement by reading the three sentences in a row.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ab12f0a5a507e9ac', 'act-english', 's-org', 3, 'The club spent the fall repairing trail signs and clearing brush. By spring, hikers reported the easiest navigation in years. <u>Trail mix is a popular snack among hikers.</u>', 'Which choice best concludes the paragraph by tying its details together?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Some hikers prefer to explore without any map at all.","letter":"B"},{"is_no_change":false,"label":"The club''s steady work had clearly paid off.","letter":"C"},{"is_no_change":false,"label":"Brush can grow back quickly in a wet season.","letter":"D"}]', 'C', '{"A":"Trail mix has nothing to do with the club''s trail work — it''s irrelevant.","B":"Map-free hiking introduces a new, unrelated idea instead of concluding.","C":"It sums up the cause (the work) and the effect (easier navigation), closing the paragraph.","D":"This undercuts the paragraph''s point rather than wrapping it up."}', 'A conclusion should **draw the paragraph''s details to a close**, which ''paid off'' does.', 'Trail mix mentions hikers, the paragraph''s subject, so it feels loosely on-topic.', 'A concluding sentence gathers what came before — reject choices that add new or off-topic ideas.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ab16149cc40a4926', 'act-english', 's-org', 3, '[1] The camp''s routine begins before sunrise. [2] Technicians check the overnight radar files while the coffee brews. [3] Any anomalies are flagged for the morning briefing. [4] By the time the sun clears the ridge, the day''s drilling targets have already been chosen.', 'For the sake of the logic and cohesion of the paragraph, Sentence 4 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"before Sentence 2.","letter":"C"},{"is_no_change":false,"label":"before Sentence 3.","letter":"D"}]', 'A', '{"A":"The paragraph moves chronologically from pre-dawn to sunrise, and Sentence 4 completes that arc in its current position.","B":"Opening with the sun clearing the ridge would put the latest moment first and strand ''already been chosen'' without prior steps (time-order violation).","C":"Placing it right after the opener interrupts the sequence before the radar check that produces the targets (breaks the workflow chain).","D":"Inserting it before the flagging step reverses cause and effect: targets are chosen from flagged anomalies (cause-effect reversal)."}', 'The paragraph follows **time order**, and this sentence marks the latest moment of the morning, so it belongs at the end.', '''Before Sentence 3'' tempts readers who link ''targets'' to ''anomalies'' without noticing that the choosing must follow the flagging.', '1) Underline every time cue (''before sunrise,'' ''while the coffee brews,'' ''by the time the sun clears''). 2) Order the events on a mental clock. 3) Check cause-effect links between neighboring sentences. 4) Place the sentence where its time stamp and its logic both fit.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b149168609a7069d', 'act-english', 's-org', 3, 'The paragraph argues that city parks improve public health. <u>Downtown rents have risen sharply over the past decade.</u> Studies link green space to lower stress and more daily exercise.', 'The writer wants every sentence to support the paragraph''s point about parks and health. The underlined sentence should be:', '[{"is_no_change":false,"label":"KEPT, because it mentions the downtown area near the parks","letter":"A"},{"is_no_change":false,"label":"KEPT, because rising rents prove parks are valuable","letter":"B"},{"is_no_change":false,"label":"DELETED, because it introduces an unrelated point about rents","letter":"C"},{"is_no_change":false,"label":"DELETED, because it repeats the previous sentence","letter":"D"}]', 'C', '{"A":"A shared location doesn''t make rent relevant to a health argument.","B":"Rising rents don''t establish anything about health benefits; the link is invented.","C":"The sentence about rents is off the paragraph''s topic (parks and health) and should go.","D":"It isn''t a repeat — it''s a new, unrelated claim."}', 'Every sentence must serve the paragraph''s point; the rent sentence **strays off-topic**, so delete it.', '''Downtown'' overlaps with where parks are, making the sentence feel connected.', 'Test each sentence against the paragraph''s main claim; cut whatever doesn''t advance it.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bd8de98582eeb065', 'act-english', 's-org', 3, 'The trail was steep and poorly marked. <u>In fact</u>, the view from the summit repaid every step.', 'Which transition acknowledges the concession the passage makes?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example","letter":"B"},{"is_no_change":false,"label":"As a result","letter":"C"},{"is_no_change":false,"label":"Even so","letter":"D"}]', 'D', '{"A":"''In fact'' intensifies what came before; the second sentence pivots away from the complaint instead.","B":"''For example'' promises an instance of steepness; a rewarding view isn''t one.","C":"''As a result'' claims the great view was CAUSED by bad trail markings.","D":"''Even so'' concedes the hard climb, then asserts the reward despite it — exactly the move the passage makes."}', 'Hardship conceded, reward asserted anyway → a **concession** transition (''even so'', ''nevertheless'').', '''In fact'' is a common intensifier, and the sentence pair reads fine until the logic is tested.', 'When sentence two says ''despite that'', the transition must carry the concession.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c03b2eb630d29e75', 'act-english', 's-org', 3, '[1] The Pullman Company hired formerly enslaved men as sleeping-car porters soon after the Civil War. [2] Porters greeted passengers, converted seats into berths, and answered call bells at every hour of the night. [3] Despite that grueling load, the job offered steady wages and a rare chance to travel. [4] In 1925, porters organized the Brotherhood of Sleeping Car Porters, which became the first Black-led union to win a contract with a major American corporation.', 'The writer wants to add the following sentence: "A porter''s shifts could stretch to four hundred hours a month, with only brief naps snatched between stations." To preserve the logic and cohesion of the paragraph, where should the sentence be placed?', '[{"is_no_change":false,"label":"Before Sentence 1","letter":"A"},{"is_no_change":false,"label":"After Sentence 2","letter":"B"},{"is_no_change":false,"label":"After Sentence 3","letter":"C"},{"is_no_change":false,"label":"After Sentence 4","letter":"D"}]', 'B', '{"A":"Opening with shift lengths would dangle a detail before readers even know who porters were.","B":"Correct: the hours extend the list of duties in Sentence 2 and set up ''that grueling load'' in Sentence 3.","C":"After Sentence 3, the detail trails the phrase that summarizes it, weakening the ''despite'' contrast.","D":"Tacked on after the union milestone, the sentence yanks readers back in time and buries the paragraph''s climax."}', 'The sentence supplies the workload that Sentence 3''s phrase ''that grueling load'' points **back** to.', 'Placing it after Sentence 3 tempts readers because both discuss hardship, but the pointer phrase must follow its evidence, not precede it.', '1) Find pointer words in the paragraph (''that,'' ''this,'' ''despite''). 2) Ask what each pointer refers to. 3) Place the new sentence so every pointer still has its referent behind it. 4) Reread the paragraph start to finish to confirm the flow.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c046438906c06227', 'act-english', 's-org', 3, '______ Crews laid track across permafrost that heaved the rails each spring, ferried supplies over Lake Baikal when ice closed the shoreline route, and blasted tunnels through cliffs with hand drills. By the time the line opened end to end in 1916, the project had consumed more than two decades of labor.', 'The writer wants to open the paragraph with a sentence that introduces its focus on the physical obstacles the builders faced. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Building the Trans-Siberian Railway meant defeating some of the harshest terrain engineers had ever confronted.","letter":"A"},{"is_no_change":false,"label":"The Trans-Siberian Railway remains the longest single rail line in the world.","letter":"B"},{"is_no_change":false,"label":"Russian officials argued for years over which route the new railway should follow.","letter":"C"},{"is_no_change":false,"label":"Travelers today can cross the whole of Russia in about a week by rail.","letter":"D"}]', 'A', '{"A":"Correct: it names the railway and frames the paragraph''s list of terrain-related obstacles.","B":"A superlative about length previews nothing about construction hardships.","C":"Political debates over the route concern planning, not the physical obstacles the paragraph details.","D":"A fact about modern travel times looks past the construction story entirely."}', 'Only this opener points directly at the **obstacles** — terrain and hardship — that every following sentence illustrates.', 'The record-length fact feels impressively relevant because it is true and famous, though it sets up no sentence that follows.', '1) List what every body sentence has in common. 2) Write a one-line label for that common thread. 3) Test each opener: does it promise exactly that thread? 4) Reject openers that are merely true, interesting, or on the same general subject.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c6797b34eda0f224', 'act-english', 's-org', 3, '[1] In 2009, the Owls'' front office needed a cheap between-innings attraction. [2] An intern proposed a footrace in which staffers dressed as giant condiments would sprint from third base to home plate. [3] Fans began arriving early just to claim seats along the third-base line. [4] Local businesses soon paid to have their logos stitched onto the costumes. [5] Today the race has its own theme song and a highlight reel on the video board.', 'The writer wants to add the following sentence to the paragraph: <i>"The prize was nothing grander than a plastic trophy kept on a shelf in the press box."</i> To make the paragraph most logical, the sentence should be placed:', '[{"is_no_change":false,"label":"after Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 2.","letter":"B"},{"is_no_change":false,"label":"after Sentence 3.","letter":"C"},{"is_no_change":false,"label":"after Sentence 5.","letter":"D"}]', 'B', '{"A":"At that point no race has been described, so ''the prize'' has nothing to refer to (placement_before_referent).","B":"Correct: the humble-stakes detail belongs right after the race is described, before the paragraph turns to its growing popularity.","C":"Interrupts the string of popularity details with origin-era information, breaking the paragraph''s arc (placement_breaks_arc).","D":"Attaches an origin-era fact to the present-day conclusion, muddling the chronology (placement_wrong_era)."}', 'The trophy detail describes the race''s **original** humble stakes, so it must sit immediately after the race is introduced and before the growth story begins.', 'The end of the paragraph feels like a natural home for a leftover detail, so students park the sentence there without checking its time frame.', '1) Identify what the new sentence refers to (''the prize'' points to a contest). 2) Find where that referent first appears. 3) Note the paragraph''s arc — origin, growth, present. 4) Place the sentence in the era it describes, immediately after its referent. 5) Re-read the paragraph to confirm smooth chronology.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c814390d3db59cb0', 'act-english', 's-org', 3, 'Beeswax served for decades as the standard adhesive for lining torn canvases. <u>Therefore,</u> most studios now favor synthetic resins that can be reversed without heat.', 'Which choice provides the most logical transition between these two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For example,","letter":"B"},{"is_no_change":false,"label":"However,","letter":"C"},{"is_no_change":false,"label":"Likewise,","letter":"D"}]', 'C', '{"A":"''Therefore'' signals a cause-effect link, but the second sentence reverses the first rather than following from it.","B":"''For example'' promises an illustration of beeswax use, yet the second sentence abandons beeswax entirely.","C":"Correct: the passage shifts from the old standard to a new preference, a contrast this transition signals.","D":"''Likewise'' claims the second sentence resembles the first, but the practices described are opposites."}', 'The second sentence **contrasts** the new practice with the old standard, so a contrast transition is required.', 'Students see two statements about adhesives in time order and reach for a cause-effect word without testing the logic.', '1) Summarize each sentence in five words or fewer. 2) Name the relationship between them: cause, contrast, example, addition, or similarity. 3) Match the transition word to that named relationship. 4) Reread with your choice inserted and confirm no other relationship fits better.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d039a0abe6f1f7a1', 'act-english', 's-org', 3, 'Many jellyfish drift passively wherever ocean currents carry them. <u>However,</u> some species can pulse their bells to steer slowly toward drifting prey.', 'Which choice provides the most logical transition between the sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"For example,","letter":"C"},{"is_no_change":false,"label":"Likewise,","letter":"D"}]', 'A', '{"A":"Correct: the second sentence contrasts active steering with passive drifting, and a contrast transition fits.","B":"''Therefore'' signals a cause-and-effect result, but the second idea opposes the first rather than following from it (transition_wrong_logic).","C":"''For example'' promises an illustration of drifting, yet steering is the opposite behavior (transition_wrong_logic).","D":"''Likewise'' claims similarity, but the two behaviors are contrasting, not alike (transition_wrong_logic)."}', 'The sentences describe opposite behaviors, so a **contrast** transition is the logical link.', 'Students see two facts about jellyfish and reach for an additive or example transition without testing the logical relationship.', '1) State in your own words how the second sentence relates to the first (adds, contrasts, results, illustrates). 2) Match that relationship to the transition''s meaning. 3) Test the transition by reading both sentences together. 4) Reject any transition whose logic does not fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d29fbecdb416c570', 'act-english', 's-org', 3, 'At poster sizes, metal type was ruinously heavy and expensive to cast. <u>For example,</u> printers of the 1830s turned to letters sawn from close-grained wood.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"As a result,","letter":"B"},{"is_no_change":false,"label":"Similarly,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'B', '{"A":"''For example'' promises an illustration of metal''s heaviness or expense, but the second sentence gives an outcome instead.","B":"''As a result'' correctly signals that the switch to wood followed from metal''s cost and weight.","C":"''Similarly'' claims the two sentences make parallel points, but the second reacts to the first.","D":"''Meanwhile'' implies two simultaneous, unrelated events, not a problem followed by its solution."}', 'The second sentence is the **consequence** of the first, so a cause-and-effect transition is required.', '''For example'' attracts readers who see the specific 1830s detail as an illustration rather than an effect.', '1) State the first sentence''s idea in five words. 2) State the second sentence''s idea in five words. 3) Name the logical relationship between them: cause, contrast, example, addition, or time. 4) Match the transition to that relationship. 5) Re-read with the chosen transition to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d5cf1d16bc41eae4', 'act-english', 's-org', 3, '<u>Volcanic soil is rich in minerals.</u> Farmers on the island''s slopes harvest three crops a year, and their coffee sells at a premium overseas. Even the roadside wildflowers grow thick and bright.', 'Which choice is the most effective topic sentence for the paragraph?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Coffee is the island''s most valuable export.","letter":"B"},{"is_no_change":false,"label":"The island''s volcanic soil makes it remarkably fertile.","letter":"C"},{"is_no_change":false,"label":"Volcanoes can be dangerous to nearby communities.","letter":"D"}]', 'C', '{"A":"''Rich in minerals'' is true but narrower than the paragraph, which is about overall fertility.","B":"Coffee is only one detail; a topic sentence can''t hinge on a single example.","C":"''Remarkably fertile'' covers crops, coffee, and wildflowers alike — the whole paragraph.","D":"Danger is never mentioned in the body; this choice is off-topic."}', 'A topic sentence must **cover every detail** that follows — here, fertility does.', 'The mineral fact (A) opens the same subject, so it feels like a natural lead — but it''s too narrow.', 'Read the body first; the best topic sentence is the umbrella the details already argue for.', 'underlined-span-mc', 'the mineral fact (A) opens the same subject, so it feels like a natur…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e4f226c07cecdd16', 'act-english', 's-org', 3, 'Rosa spends every Sunday testing small adjustments to the croissant dough. <u>For instance,</u> last month she swapped half the butter for browned butter to deepen the flavor.', 'Which choice provides the most effective transition?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"In conclusion,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'A', '{"A":"Correct — the second sentence gives a specific instance of the ''small adjustments'' the first sentence describes.","B":"''However'' signals contrast, but the butter swap confirms rather than contradicts the first sentence (transition_false_contrast).","C":"''In conclusion'' signals a summary or ending, but the second sentence narrows to one example instead of wrapping up (transition_false_summary).","D":"''Meanwhile'' signals two things happening at the same time, but the sentences describe a general habit and one instance of it (transition_false_time)."}', 'The butter swap is a concrete **example** of the small adjustments, so an illustrating transition fits.', '''Meanwhile'' feels harmless because both sentences involve time words like ''Sunday'' and ''last month.''', '1) Blank out the transition. 2) Ask: is sentence two an example, a contrast, a result, a restatement, or a time shift relative to sentence one? 3) Choose the transition that matches your label. 4) Reread the pair to confirm the logic clicks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e5fa1c3af3cb2452', 'act-english', 's-org', 3, '[1] For decades, television news reached Deaf viewers only through captions typed minutes behind the broadcast. [2] Captions also flattened tone, rendering an anchor''s urgency and a weathercaster''s reassurance in identical block letters. [3] Emergency coverage suffered most, since evacuation orders scrolled past faster than many viewers could absorb them. [4] Complaints about the delays filled station mailrooms after every major storm. [5] In the 1990s, several stations began placing live interpreters in an on-screen box during emergencies. [6] The interpreters could match the urgency of the moment, and viewers finally received warnings in real time.', 'The writer wants to divide this paragraph into two paragraphs, so that the second paragraph focuses on the shift to on-screen interpreters. The best place to begin the new paragraph is at the start of Sentence:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'D', '{"A":"Sentence 2 continues describing captioning''s weaknesses, the first paragraph''s topic.","B":"Sentence 3 is still about captioned broadcasts and their delays, not about interpreters.","C":"Sentence 4 wraps up the complaints about captions, so it belongs with the first topic.","D":"Correct — Sentence 5 introduces the on-screen interpreters, the shift the second paragraph should feature."}', 'The break belongs where the topic turns — Sentence 5 is the **first** sentence about on-screen interpreters.', 'Sentence 4 tempts readers because the complaints feel like a new note, but they still concern captioning.', '1) Label each sentence with a two-word topic tag. 2) Find where the tags switch from the first subject to the second. 3) Start the new paragraph at the first sentence of the new subject. 4) Verify: everything before the break shares topic one; everything after shares topic two.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ec85fced0c9cb680', 'act-english', 's-org', 3, 'Live radio drama depended on improvised sound effects. A sheet of cellophane, crumpled near the microphone, became a crackling campfire; coconut shells clopped like horses on cobblestones; a knife driven into a cabbage stood in for grim business offstage. Technicians rehearsed these tricks as carefully as the actors rehearsed their lines.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main idea about the resourcefulness of sound-effects technicians. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Radio dramas eventually gave way to television in the 1950s.","letter":"A"},{"is_no_change":false,"label":"Many radio actors later found steady work in film and television.","letter":"B"},{"is_no_change":false,"label":"With nothing but everyday odds and ends, these artists could conjure a storm, a stampede, or a murder.","letter":"C"},{"is_no_change":false,"label":"Cellophane, patented years earlier, had dozens of uses outside the studio.","letter":"D"}]', 'C', '{"A":"Pivots to the medium''s later decline, abandoning the paragraph''s subject of ingenious effects work.","B":"Spotlights the actors'' future careers instead of the technicians the paragraph has been praising.","C":"Correct: it gathers the paragraph''s examples into a closing statement about what the technicians could create from humble materials.","D":"Burrows into trivia about one prop rather than widening back to the technicians'' inventiveness."}', 'A strong conclusion **circles back** to the paragraph''s governing idea — here, the technicians'' inventiveness with humble props — and generalizes it.', 'The historical note about television feels like a natural ''ending'' because it closes the era, but it abandons the paragraph''s actual subject.', '1) State the paragraph''s main idea in one clause. 2) Check each option: does it restate or extend that idea, or introduce a new subject? 3) Eliminate options about different people, later eras, or single details. 4) Pick the sentence that widens the examples back into the main idea. 5) Reread the paragraph with it in place.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f20650dd9beb2102', 'act-english', 's-org', 3, '[1] Kelp forests rank among the most productive ecosystems in the sea. [2] They shelter sea otters, fish, and countless invertebrates among their swaying fronds. [3] A single kelp plant can stretch more than a hundred feet from the seafloor to the surface. [4] This towering height depends on rapid, sunlight-fueled growth.', 'The writer wants to add the sentence "These giant algae can grow up to two feet in a single day." The sentence would most logically be placed:', '[{"is_no_change":false,"label":"before Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'D', '{"A":"Opening with ''These giant algae'' leaves the phrase with no prior noun to refer to (placement_no_referent).","B":"Dropping a growth-rate fact right after the productivity sentence interrupts before size is raised (placement_interrupts).","C":"Splits the sheltered-animals idea in Sentence 2 with an unrelated growth detail (placement_interrupts).","D":"Correct: the growth-rate detail bridges the size in Sentence 3 and the growth explanation in Sentence 4."}', 'A new detail belongs where it **connects** the ideas around it — here, between the plant''s length and its rapid growth.', 'Because Sentence 1 mentions productivity, students place the growth fact there without noticing that ''these giant algae'' needs an earlier anchor.', '1) Identify the new sentence''s key idea and any back-pointing words like ''these.'' 2) Find the sentence whose topic it extends. 3) Make sure any pronoun or ''these'' phrase has a noun already introduced before it. 4) Place it where it links naturally to both neighbors.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f76edda0d634fc05', 'act-english', 's-org', 3, '______ Apprentices begin by mending hems and replacing buttons on garments from the costume stock. By midyear, they are drafting patterns and cutting fabric for full ensembles. The most experienced seniors design an entire show on their own.', 'The writer wants to open the paragraph with a sentence that introduces its main idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The costume shop stores more than four hundred garments from past productions.","letter":"A"},{"is_no_change":false,"label":"Many students would rather perform onstage than sew in the costume shop.","letter":"B"},{"is_no_change":false,"label":"Sewing machines can be dangerous for anyone who has not been trained.","letter":"C"},{"is_no_change":false,"label":"In the school''s costume shop, student apprentices build skills in stages.","letter":"D"}]', 'D', '{"A":"An inventory statistic previews nothing about the progression the paragraph traces (intro_offtopic_detail).","B":"A claim about preferring performance points the paragraph toward a comparison it never makes (intro_wrong_emphasis).","C":"A safety warning promises a paragraph about hazards, which never materializes (intro_offtopic_detail).","D":"Correct: it previews the step-by-step growth — mending, then drafting, then designing — that every following sentence develops."}', 'A strong opener **forecasts** the paragraph''s throughline, and only this sentence previews the progression from simple mending to independent design.', 'The garment statistic tempts students because it mentions the same setting, even though no later sentence develops storage or inventory.', '1) Read the body sentences first. 2) Name the single thread that ties them together. 3) Test each opener: does the rest of the paragraph deliver what it promises? 4) Eliminate openers whose topic never returns. 5) Choose the sentence whose promise the paragraph keeps.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fc6915b0158b7b59', 'act-english', 's-org', 3, '[1] Building a pier in deep water begins with a watertight enclosure called a cofferdam. [2] Crews drive interlocking steel sheets into the riverbed to form the enclosure''s walls. [3] Pumps then drain the water trapped inside, exposing the riverbed. [4] With the site dry, workers pour the concrete footing. [5] Once the footing cures, the pier rises on top of it, course by course.', 'The writer wants Sentence 3 placed where the construction steps remain in logical order. Which placement best accomplishes that goal?', '[{"is_no_change":false,"label":"Where it is now (after Sentence 2)","letter":"A"},{"is_no_change":false,"label":"Before Sentence 1","letter":"B"},{"is_no_change":false,"label":"After Sentence 4","letter":"C"},{"is_no_change":false,"label":"After Sentence 5","letter":"D"}]', 'A', '{"A":"Draining logically follows building the walls (Sentence 2) and must precede pouring on a dry site (Sentence 4), so the current position is correct.","B":"Places the draining before the enclosure exists, leaving ''the water trapped inside'' with nothing to refer to (misconception: placement_ignores_reference).","C":"Puts the draining after Sentence 4, which already declares the site dry, reversing the process (misconception: placement_breaks_sequence).","D":"Delays the draining until the pier is finished, when the water would already have to be gone (misconception: placement_after_conclusion)."}', 'The steps must follow the **physical sequence** — walls built, water pumped out, footing poured — and Sentence 3 already sits exactly between its prerequisite and its consequence.', 'Students who skim past ''With the site dry'' in Sentence 4 miss that draining must already be finished, making later placements seem harmless.', '1) Number the real-world steps the paragraph describes. 2) Find what the movable sentence depends on (its prerequisite) and what depends on it (its consequence). 3) The sentence must sit after the prerequisite and before the consequence. 4) Test the winning slot by reading the paragraph straight through.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fcbd85172e22ac6b', 'act-english', 's-org', 3, '[1] Last year, the downtown alliance launched a pilot program to replace its confusing wayfinding signs. [2] Designers began by interviewing visitors who had gotten lost near the transit mall. [3] The interviews revealed that most people navigate by landmarks rather than by street names. [4] The new signs therefore feature bold icons of the clock tower, the river, and other familiar reference points. [5] That discovery surprised the design team, which had expected to build a map-heavy layout.', 'For the sake of the logic and cohesion of the paragraph, the writer wants to place Sentence 5 where it functions best. Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'D', '{"A":"Left at the end, ''That discovery'' sits far from the finding it names, and the surprise lands after the design it motivated has already been described.","B":"After Sentence 1 there is no discovery yet for the pronoun phrase to point to.","C":"After Sentence 2 the interviews have happened, but no finding has been stated for ''That discovery'' to name.","D":"Sentence 3 states the finding; Sentence 5''s ''That discovery'' points straight at it, and the team''s surprise then motivates the design in Sentence 4."}', '''That discovery'' must sit **immediately after the sentence that states the discovery**, and the team''s surprise then explains the design change.', 'The paragraph reads smoothly enough to the ear at first pass, so leaving the sentence where it is feels safe.', '1) Find pointing words in the movable sentence (''that,'' ''this,'' ''such''). 2) Identify what they must refer to. 3) Place the sentence right after its referent. 4) Re-read to confirm each sentence now leads logically to the next.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-02d1f590eca4d020', 'act-english', 's-org', 4, 'Duke Ellington rarely wrote for an anonymous trumpet or saxophone part. He composed ''Concerto for Cootie'' around Cootie Williams''s growling plunger mute, and he shaped ballads to ride the liquid glide of Johnny Hodges''s alto. When a musician left the band, Ellington often shelved the pieces built on that player''s sound rather than reassign them.', 'The writer wants a concluding sentence that reinforces the paragraph''s main idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Ellington''s orchestra crisscrossed the country for decades, outlasting most rival bands.","letter":"A"},{"is_no_change":false,"label":"Several musicians stayed in the orchestra with Ellington for twenty years or more.","letter":"B"},{"is_no_change":false,"label":"Ellington also composed film scores and, later, extended sacred concerts.","letter":"C"},{"is_no_change":false,"label":"The orchestra, Ellington understood, was itself the instrument he truly composed for.","letter":"D"}]', 'D', '{"A":"goal_offtopic: touring longevity says nothing about writing for individual voices.","B":"Long tenures are related trivia; the paragraph is about how Ellington composed, not how long players stayed.","C":"add_new_topic: film scores and sacred concerts open a new subject instead of closing this one.","D":"Correct: it distills the paragraph''s idea — the band''s specific voices were the medium he wrote for."}', 'It restates the paragraph''s **central idea** — composing for particular players — in a single closing image.', 'Long tenures feel connected to writing for specific players, but tenure is a side effect, not the paragraph''s point.', '1) State the paragraph''s main idea in one sentence. 2) Test each closer: does it restate or extend that idea? 3) Cross out any option that introduces new information or shifts topic. 4) Choose the option that could stand alone as a one-line summary of the paragraph.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-046d7e44c0371aa9', 'act-english', 's-org', 4, '[1] Grafting lets a grower duplicate a favorite tree rather than gamble on seedlings. [2] In late winter, she clips pencil-thick scions from the parent tree and stores them in a cold cellar. [3] When the rootstocks wake in early spring, she splices a chilled scion onto each one. [4] Tape holds each union tight while the two layers of living wood knit together. [5] By midsummer, a successful graft announces itself with a flush of new shoots.', 'The writer wants Sentence 3 placed where it best preserves the chronological order of the grafting process. For that purpose, Sentence 3 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 4.","letter":"C"},{"is_no_change":false,"label":"after Sentence 5.","letter":"D"}]', 'A', '{"A":"Correct: splicing happens after the winter scion harvest (Sentence 2) and before the taped union heals (Sentence 4), exactly where the sentence sits.","B":"Opening with the spring splice would put a mid-process step before the paragraph even defines grafting.","C":"Moving the splice after the taping would describe the union healing before it exists.","D":"Placing the splice after the midsummer shoots would put the cause after its final effect."}', 'The paragraph runs winter, then spring, then healing, then midsummer, and Sentence 3 already occupies the **spring** slot.', 'Sentence 4''s tape detail feels like setup for splicing, so some students want the splice to follow it.', '1) Assign each sentence a time stamp from its own clues (late winter, early spring, midsummer). 2) Order the stamps. 3) Slot the target sentence by its stamp. 4) Reread the paragraph in the new order to confirm each step causes the next.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0547a2126a9a3834', 'act-english', 's-org', 4, 'The essay claims that public libraries remain essential in the digital age. A strong body paragraph would most likely develop this claim by <u>listing the founding dates of several famous libraries.</u>', 'Which choice best develops the essay''s claim about libraries'' ongoing importance?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"explaining how printing presses worked in the fifteenth century.","letter":"B"},{"is_no_change":false,"label":"describing the free internet access and job-search help libraries now provide.","letter":"C"},{"is_no_change":false,"label":"recounting the architecture of a famous reading room.","letter":"D"}]', 'C', '{"A":"Founding dates speak to history, not present-day essentialness.","B":"Fifteenth-century printing is unrelated to the digital-age argument.","C":"Modern services like internet access and job help directly show why libraries still matter.","D":"Architecture is decorative detail that doesn''t support the claim of essentialness."}', 'Development must **advance the specific claim** — here, current relevance, which modern services demonstrate.', 'History and famous rooms feel ''library-related'', so they seem supportive.', 'Choose supporting detail that proves the exact point being argued, not merely the general topic.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-06bec29d5fae66ea', 'act-english', 's-org', 4, '<p>Tide pools are stacked in bands along the shore. Near the top, only the hardiest species endure long stretches of air and glaring sun. Farther down, where seawater lingers between tides, softer-bodied creatures flourish.</p>', 'The writer wants to conclude the paragraph by emphasizing that where a creature lives on the shore determines whether it can survive. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The best pools attract crowds of curious tourists each summer.","letter":"A"},{"is_no_change":false,"label":"The ocean supports an astonishing variety of living things.","letter":"B"},{"is_no_change":false,"label":"Thus a creature''s exact position on the shore, more than anything else, decides where it can hold on.","letter":"C"},{"is_no_change":false,"label":"Twice a day the rising tide covers and uncovers these bands.","letter":"D"}]', 'C', '{"A":"This detail about tourists is off-topic and ignores the paragraph''s biological point (add_offtopic).","B":"A sweeping claim about ocean diversity is too broad to cap a paragraph about shore zones (goal_too_broad).","C":"Correct: it ties survival directly to an organism''s location on the shore, matching the stated goal.","D":"This restates the tides'' motion rather than emphasizing how location governs survival (goal_wrong_emphasis)."}', 'Only this sentence links **location** to survival, which is exactly the emphasis the stem requests.', 'The tide sentence stays on the topic of bands, so it feels relevant even though it misses the survival-by-location point.', '1) Underline the goal''s key idea in the stem. 2) Check each option against that exact idea. 3) Reject options that are off-topic, too broad, or emphasize the wrong point. 4) Keep the one that states the requested idea directly.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-081bb011c8a70c64', 'act-english', 's-org', 4, '[1] Chimney swifts once nested in hollow trees across the river valley. [2] As the valley was logged and built over, the birds shifted to unused brick chimneys. [3] Modern chimneys, capped and lined with slick metal, offer the swifts no grip at all. [4] Conservation groups now build freestanding towers that mimic the rough interiors of the old flues. [5] That switch worked for nearly a century, until heating technology changed.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'C', '{"A":"At the end, ''That switch'' points back across three sentences and its ''until'' clause arrives after the consequence it should set up (placement_dangling_reference).","B":"Placed first, ''That switch'' precedes the switch itself, which has not yet been described (placement_before_antecedent).","C":"Correct: it directly follows the move to chimneys that ''That switch'' names, and its ''until'' clause sets up the modern-chimney problem in Sentence 3.","D":"Here the setup lands after its payoff — the changed heating technology is exactly what Sentence 3 already showed (placement_after_payoff)."}', 'Sentence 5''s phrase ''That switch'' must sit **immediately after** the switch to chimneys, and its ''until'' clause then launches the problem the next sentence details.', 'Leaving the sentence where it is feels safe because it reads as a wrap-up, so students overlook that its pointing phrase has drifted far from its antecedent.', '1) Find the movable sentence''s pointing words (here: ''That switch''). 2) Locate the sentence that contains what they point to. 3) Place the movable sentence right after that antecedent. 4) Check that any forward-looking clause (here: ''until...'') sets up what follows. 5) Re-read the whole paragraph in the new order.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-08c476a61ca9cce2', 'act-english', 's-org', 4, '[1] Designing the intake took the mechanical subteam most of October. [2] Early rollers pinched the foam cubes instead of pulling them in. [3] A wider roller spacing and softer compliant wheels finally solved the problem. [4] Programming the intake presented an entirely different set of challenges. [5] The code had to slow the rollers the instant a cube tripped the beam sensor. [6] Otherwise, cubes shot straight through the robot and out the back.', 'The writer wants to divide this paragraph into two paragraphs, one about building the intake and one about programming it. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 4.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 6.","letter":"D"}]', 'A', '{"A":"Correct: this sentence announces the shift from hardware to software, so the new paragraph starts there.","B":"Splits mid-topic — the roller-spacing solution still belongs to the building story (division_before_topic_ends).","C":"Strands the sentence that announces the second topic inside the first paragraph (division_after_topic_sentence).","D":"Opens a paragraph with ''Otherwise,'' a word that leans entirely on the sentence before it (division_dependent_opener)."}', 'Sentence 4 **announces** the shift from building to programming, so the new paragraph logically starts there.', 'Sentence 5 attracts students because it introduces the first concrete coding detail.', '1) Label each sentence by topic. 2) Find the first sentence with a new label. 3) Confirm it works as a topic sentence for everything after it. 4) Begin the new paragraph at that sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-08e8a56051228a3f', 'act-english', 's-org', 4, '<b>[Opening sentence]</b> In the older suburbs, red foxes dig earthworms from irrigated lawns; downtown, they patrol the dumpsters behind restaurants at closing time. One radio-collared vixen even learned the weekly rhythm of a farmers'' market, arriving each Saturday just as the vendors packed up.', 'The writer wants an opening sentence that introduces the paragraph''s focus on how red foxes have adapted their diets to city life. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"City foxes eat what the city provides, reshaping old hunting habits around human routines.","letter":"A"},{"is_no_change":false,"label":"Red foxes are found on four continents and in nearly every climate on Earth.","letter":"B"},{"is_no_change":false,"label":"Foxes have fascinated the writers of folklore and fable for many centuries.","letter":"C"},{"is_no_change":false,"label":"Farmers'' markets have become popular weekend attractions in many cities.","letter":"D"}]', 'A', '{"A":"Correct: it previews exactly what the examples deliver — urban feeding habits reorganized around human activity.","B":"A global-range fact frames a far broader topic than the paragraph''s urban-diet examples (intro_too_broad).","C":"Folklore and fable never appear in the paragraph, so this opener promises a topic the paragraph ignores (intro_offtopic).","D":"This inflates one closing detail into a frame that cannot cover the lawn and dumpster examples (intro_from_detail)."}', 'An effective introduction must **preview the whole paragraph**, and only this option spans lawns, dumpsters, and the market anecdote under one idea.', 'The four-continents fact sounds authoritative and encyclopedic, so students mistake impressive breadth for a fitting introduction.', '1) Read the paragraph body first and list what every sentence is about. 2) Write a one-line summary of that shared topic. 3) Test each opener against the summary: too broad, too narrow, or off-topic all fail. 4) Confirm the survivor''s promise is kept by every example. 5) Re-read the paragraph with the opener in place.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0ba308549c83a3b5', 'act-english', 's-org', 4, '____. During a full-day conference, an interpreter''s arms may repeat the same motions thousands of times, and researchers have measured injury rates comparable to those of assembly-line workers. To protect themselves, professionals work in pairs, trading the active role every twenty to thirty minutes. Many also follow stretching regimens borrowed from athletic trainers.', 'The writer wants an opening sentence that frames the paragraph''s focus on the occupational strain of interpreting. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Interpreting may look effortless from the seats, but it taxes the body like an athletic event.","letter":"A"},{"is_no_change":false,"label":"Interpreting requires years of coursework, mentorship, and supervised practice.","letter":"B"},{"is_no_change":false,"label":"Sign languages differ from country to country, and even from city to city.","letter":"C"},{"is_no_change":false,"label":"Conference interpreters usually earn more per hour than staff interpreters at schools.","letter":"D"}]', 'A', '{"A":"Correct — it names the physical toll directly, setting up the injury statistics, paired staffing, and stretching routines that follow.","B":"Focuses on training and credentials, which the paragraph never discusses.","C":"Raises language variation across regions, a topic unrelated to the paragraph''s details.","D":"Introduces pay differences, which none of the following sentences address."}', 'The opener must preview the paragraph''s actual content — **bodily strain** and how interpreters manage it.', 'The training option feels relevant because credentials often open essays about professions, but no later sentence supports it.', '1) Read every sentence after the blank and list their shared subject in two or three words. 2) Turn that subject into a promise an opening sentence should make. 3) Test each option against the promise: does the rest of the paragraph deliver it? 4) Eliminate any opener whose promise the paragraph never keeps.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-122d1a6427e041bb', 'act-english', 's-org', 4, 'Shoppers often assume that produce at the farmers'' market costs more than it does at the supermarket. <u>Therefore,</u> a July comparison of twelve stalls found that seasonal fruit at the market was frequently cheaper.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In fact,","letter":"B"},{"is_no_change":false,"label":"Likewise,","letter":"C"},{"is_no_change":false,"label":"In the meantime,","letter":"D"}]', 'B', '{"A":"Treats the finding as a conclusion drawn from the assumption, but the finding contradicts the assumption (transition_false_cause).","B":"Correct — it signals that reality counters the common assumption stated first.","C":"Claims similarity between an assumption and a finding that undercuts it (transition_wrong_logic).","D":"Imposes a time-based, simultaneous relationship that the sentences don''t have (transition_false_time)."}', 'The survey''s finding **contradicts** the shoppers'' assumption, so the transition must signal a correcting turn from belief to reality.', '''Therefore'' feels safe because the second sentence presents data that seems to follow from investigating the first sentence''s topic.', '1) Summarize sentence 1 (a common belief). 2) Summarize sentence 2 (what was found). 3) Ask: does the second confirm, contradict, exemplify, or merely follow the first in time? 4) Choose the transition matching that relationship. 5) Reread the pair with the candidate installed.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-130d46cb6e004cef', 'act-english', 's-org', 4, '<u>The bakery on Fifth Street sells excellent bread.</u> This essay will argue that small local businesses deserve tax incentives because they anchor neighborhoods, create jobs, and keep profits circulating in the community.', 'Which choice is the strongest thesis statement for the essay?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Tax policy is a complicated and often controversial subject.","letter":"B"},{"is_no_change":false,"label":"There are many small businesses in our town.","letter":"C"},{"is_no_change":false,"label":"Small local businesses deserve tax incentives because they strengthen neighborhoods, employ residents, and reinvest their earnings locally.","letter":"D"}]', 'D', '{"A":"One bakery''s bread is a narrow anecdote, not a thesis the essay can defend.","B":"Calling the topic ''complicated'' announces no stance at all.","C":"A bare fact about quantity takes no position and previews no argument.","D":"It states a clear claim (incentives) plus the three reasons the essay will develop."}', 'A thesis makes an **arguable claim and previews the support** — B names the claim and its three reasons.', 'The bakery sentence is concrete and vivid, which can masquerade as a strong opening.', 'A thesis states a debatable position and maps the essay''s reasons — not a fact or a vague topic label.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-13a120b7f1bf5f0e', 'act-english', 's-org', 4, 'Writing ink of the fifteenth century was water-based and flowed easily from a quill, but it beaded and smeared on metal type. Gutenberg''s workshop instead blended lampblack with linseed varnish, producing a paste sticky enough to cling to each letter. The mixture transferred cleanly under pressure and dried to a durable sheen.', 'The writer wants to add a sentence at the beginning of the paragraph that introduces its main idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Ink has been made from countless materials over the centuries.","letter":"A"},{"is_no_change":false,"label":"Lampblack is a fine soot gathered from burning oil or resin.","letter":"B"},{"is_no_change":false,"label":"Printing from metal type demanded an ink unlike any a scribe had ever used.","letter":"C"},{"is_no_change":false,"label":"Gutenberg borrowed the screw mechanism of his press from local wine makers.","letter":"D"}]', 'C', '{"A":"This sentence is far broader than the paragraph, which concerns one specific formulation problem.","B":"This zooms in on a single ingredient before the paragraph has established why a new recipe was needed.","C":"This states the paragraph''s controlling idea — a new craft required an entirely new ink — which every following sentence supports.","D":"The press''s mechanics are a different subject; the paragraph never discusses machinery."}', 'The best introduction previews the paragraph''s **controlling idea**, which each later sentence then develops.', 'The broad ink-history opener attracts students who equate ''introduction'' with ''general background.''', '1) Read the body sentences first and summarize their shared subject in one phrase. 2) Ask of each candidate: does it promise exactly that subject? 3) Reject candidates that are wider, narrower, or about something else. 4) Confirm the survivor lets the next sentence follow naturally. 5) Re-read the assembled paragraph from the top.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1512d27f3e7fe0b7', 'act-english', 's-org', 4, 'A bottle of stop bath costs less than a movie ticket and lasts for months on a darkroom shelf. <u>In other words,</u> some home printers skip it entirely, trusting a plain water rinse to halt development.', 'Which choice best expresses the relationship between these two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"As a result,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"Even so,","letter":"D"}]', 'D', '{"A":"Treats the second sentence as a restatement of the first (transition_false_restatement), but skipping a product is not another way of saying it is cheap.","B":"Claims cheapness causes printers to skip the product (transition_false_cause), the reverse of what low cost would predict.","C":"Offers the skipping as a specific case of the cheapness (transition_false_example), though it is a surprising departure, not an instance.","D":"Correct: the second sentence describes behavior that persists despite the first sentence''s facts, so a concessive transition fits."}', 'Printers skip the stop bath **despite** its low cost and long life, so the transition must concede the first sentence before pivoting.', '''As a result'' attracts students who see any two adjacent facts as cause and effect without testing whether the second actually follows from the first.', '1) Summarize sentence one and sentence two separately. 2) Ask: given sentence one, is sentence two expected or surprising? 3) If expected, consider cause-effect or continuation words; if surprising, use a concession word. 4) Plug in your choice and confirm the surprise or expectation reads correctly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1d4e482ea3cfd0d8', 'act-english', 's-org', 4, 'Nearly every glaze recipe at the Ashfield co-op circulates freely, photocopied and traded like family recipes. <u>For instance,</u> a few signature formulas remain locked in the private notebooks of the potters who perfected them.', 'Which transition word or phrase is most logical here?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In fact,","letter":"B"},{"is_no_change":false,"label":"Nevertheless,","letter":"C"},{"is_no_change":false,"label":"Consequently,","letter":"D"}]', 'C', '{"A":"The second sentence is an exception to the sharing culture, not an example of it (false-example transition).","B":"''In fact'' promises an even stronger restatement of the first claim, but this sentence pulls back from it (false-intensifier).","C":"Correct: the guarded formulas persist despite the open-sharing norm, so a concession transition fits.","D":"Free sharing does not cause the secrecy, so a cause-effect transition misstates the logic (false-cause)."}', 'The second sentence is a **concession** — an exception that stands despite the general rule just described.', '''In fact'' tempts students because the second sentence also discusses recipes, masking that it limits rather than intensifies the first claim.', '1) Summarize sentence one''s claim. 2) Ask what sentence two does to that claim: extend it, illustrate it, limit it, or result from it. 3) If sentence two limits or surprises, choose a concession connector. 4) Insert your choice and reread. 5) Verify no other option names the move more precisely.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2165f7fd9209f160', 'act-english', 's-org', 4, '[1] Installing a seismometer on an active volcano begins long before anyone climbs the mountain. [2] Technicians first assemble and test each station indoors at the observatory. [3] They then pack the electronics into padded crates for the helicopter flight to the summit. [4] Once on site, the crew levels the sensor, buries it, and checks the radio link back to the observatory. [5] Every cable and connector is inspected twice during this indoor stage.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'C', '{"A":"Leaves ''this indoor stage'' pointing at outdoor summit work, a mismatch the reader trips over.","B":"Places the pointer phrase before any indoor work has been described, so it has no referent yet.","C":"Correct: it follows the sentence describing indoor assembly and testing, giving ''this indoor stage'' a clear referent.","D":"Attaches the inspection to crate-packing and the flight rather than to the bench testing it describes."}', '''**This indoor stage**'' must directly follow the sentence that describes the indoor assembly and testing.', 'Packing can also happen indoors, so slotting the inspection after the packing sentence feels plausible until you ask when cables and connectors actually get checked.', '1) Find the pointer words in the movable sentence (''this indoor stage''). 2) Ask which earlier sentence those words must refer to. 3) Place the movable sentence immediately after its referent. 4) Re-read the paragraph in the new order to confirm the timeline still runs start to finish.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-216ff50000d1d8c9', 'act-english', 's-org', 4, '[1] Early jazz lived almost entirely in performance, reshaped nightly by the mood of the dancers and the stamina of the band. [2] Because no two renditions of a tune matched, a song was less a fixed text than a set of habits a band shared. [3] The spread of phonograph records upended that relationship. [4] A solo pressed into shellac could be slowed down, replayed, and memorized note for note. [5] Young musicians in towns with no jazz scene at all learned entire styles from a few worn discs. [6] What had been a local dialect became, within a decade, a national language.', 'The writer wants to divide this paragraph into two paragraphs. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 3","letter":"A"},{"is_no_change":false,"label":"Sentence 4","letter":"B"},{"is_no_change":false,"label":"Sentence 5","letter":"C"},{"is_no_change":false,"label":"Sentence 6","letter":"D"}]', 'A', '{"A":"Correct: Sentence 3 pivots from live-performance culture to the new world that records created.","B":"Sentence 4 belongs with Sentence 3 — it develops the change that 3 announces, so starting here strands the pivot in the old paragraph.","C":"Sentence 5 continues the record-driven examples begun in Sentence 4; breaking here splits parallel evidence.","D":"Sentence 6 is the paragraph''s conclusion; a one-sentence summary ''paragraph'' is not a real division."}', 'A new paragraph starts where the **topic shifts** — here, at the arrival of records.', 'Sentence 4''s vivid detail feels like a fresh start, but it only elaborates the shift the previous sentence already announced.', '1) Label each sentence''s topic in two words. 2) Find where the labels change for good. 3) The first sentence of the new topic starts the new paragraph. 4) Confirm the second half now opens with something that could stand as a topic sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-26b65ee2ba3d6de6', 'act-english', 's-org', 4, 'The report opens by describing the drought''s toll on the reservoir. It then details the new conservation rules. <u>Rainfall totals vary widely from year to year.</u>', 'Which choice best concludes the report by reinforcing its purpose?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"With these measures in place, the town hopes to weather the next dry spell.","letter":"B"},{"is_no_change":false,"label":"The reservoir was built more than fifty years ago.","letter":"C"},{"is_no_change":false,"label":"Many households own more than one car.","letter":"D"}]', 'B', '{"A":"A generic fact about rainfall variability doesn''t close the report''s argument.","B":"It ties the conservation rules to the goal of surviving future droughts, fulfilling the report''s purpose.","C":"The reservoir''s age is a stray detail unrelated to the conclusion.","D":"Car ownership has nothing to do with drought conservation."}', 'A purposeful conclusion **links the body''s content to the document''s goal** — surviving drought.', 'Rainfall variability is on-theme with drought, so it feels like a fitting close.', 'A conclusion should advance the piece''s purpose, not merely mention its subject.', 'underlined-span-mc', 'rainfall variability is on-theme with drought, so it feels like a fit…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-27a9d60cd4a367aa', 'act-english', 's-org', 4, 'Rotoscoping allowed animators to trace live-action footage one frame at a time. <u>As a result,</u> their characters moved with an eerily lifelike fluidity that hand-timed drawings rarely achieved.', 'Which transition word or phrase is most logical in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In contrast,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'A', '{"A":"''As a result'' correctly presents the lifelike movement as the consequence of tracing real footage.","B":"''In contrast'' asserts opposition, but the fluid motion follows from the tracing rather than opposing it.","C":"''For instance'' would make the second sentence an example of the first, yet it is an effect, not an illustration.","D":"''Meanwhile'' implies two separate simultaneous events, but the sentences describe a cause producing its effect."}', 'Tracing real footage **causes** the lifelike fluidity, so the cause-and-effect transition already in place is right.', '''Eerily'' feels faintly negative, tempting students to read the second sentence as a contrast with the technique''s promise.', '1) Cover the transition and read the two sentences bare. 2) Name their logical link in your own words. 3) Sort each option by category (contrast, example, time, result). 4) Keep the option whose category matches your named link — even if that means keeping what is already there.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2de182a5812c71c7', 'act-english', 's-org', 4, '[1] A sound marathon buildup adds mileage gradually, rarely more than ten percent per week. [2] Long runs stretch from ten miles toward twenty over several months. [3] Midweek sessions add tempo running and hills to build strength. [4] Race day, by contrast, rewards restraint rather than accumulation. [5] Veterans start a few seconds per mile slower than goal pace and settle in behind a pace group. [6] They save their push for the miles beyond twenty, where the race is truly decided.', 'The writer wants to divide this paragraph into two paragraphs, so that the first focuses on training and the second on race-day strategy. The second paragraph should begin with:', '[{"is_no_change":false,"label":"Sentence 2","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 4","letter":"C"},{"is_no_change":false,"label":"Sentence 5","letter":"D"}]', 'C', '{"A":"Breaks in the middle of the training discussion, splitting one topic across two paragraphs (divide_mid_topic).","B":"Sentence 3 still describes training workouts, so the strategy paragraph would open with buildup material (divide_one_early).","C":"Correct: Sentence 4 pivots with ''Race day, by contrast,'' announcing the shift from preparation to racing strategy.","D":"Starts one sentence too late, stranding the pivot sentence with the training material it turns away from (divide_one_late)."}', 'The new paragraph must begin at the **topic shift**, and Sentence 4''s ''Race day, by contrast'' is the exact sentence that turns from training to racing.', 'Starting with the veterans'' pacing tempts students because it is the first concrete strategy detail, but it leaves the transition sentence behind with the wrong topic.', '1) Label each sentence with its topic in one or two words. 2) Find where the labels change. 3) Check for a signpost phrase (such as a contrast marker) confirming the shift. 4) Begin the new paragraph at the first sentence of the new topic. 5) Re-read both halves to confirm each is unified.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-30418aa306a1be55', 'act-english', 's-org', 4, '<p>[1] Reaching a good tide pool takes patience. [2] Printed tide charts tell visitors the hours when the ocean will pull back. [3] A careful walker waits at the edge as the final waves slide away. [4] Crabs and snails then edge out from their hidden cracks.</p>', 'The writer wants to add the sentence ''Only then does the shallow water settle enough to explore safely.'' Where would it best be placed?', '[{"is_no_change":false,"label":"After Sentence 1","letter":"A"},{"is_no_change":false,"label":"After Sentence 2","letter":"B"},{"is_no_change":false,"label":"After Sentence 3","letter":"C"},{"is_no_change":false,"label":"After Sentence 4","letter":"D"}]', 'C', '{"A":"Placed here, ''only then'' has no prior event to point back to, so the reference dangles (order_illogical).","B":"After the charts, the settling has not yet been set up by the waves sliding away.","C":"Correct: the water settles right after the final waves slide away, so the sentence follows Sentence 3.","D":"By Sentence 4 the creatures are already out, so noting the water can now be explored arrives too late."}', '''Only then'' must follow the event it refers to — the waves sliding away — which is **Sentence 3**.', 'Sentence 4 also describes the calm aftermath, so the added line seems to fit alongside it.', '1) Find the pointing words in the new sentence (''only then''). 2) Identify the event they refer to. 3) Place the sentence immediately after that event. 4) Check the flow before and after the new spot.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-355264c7a73172e5', 'act-english', 's-org', 4, '[1] New carriers at the Bugle spend their first Saturday riding the delivery route with manager Dot Pruitt. [2] By their third week, most can finish the route alone in under two hours. [3] She points out which porches flood, which dogs only bluff, and which subscribers want the paper tucked inside the storm door. [4] Veterans say that single morning teaches more than the carrier handbook ever could. [5] Perhaps that is why the Bugle has not missed a delivery day in forty years.', 'For the sake of the logic and cohesion of the paragraph, Sentence 3 should be placed:', '[{"is_no_change":false,"label":"where it is now","letter":"A"},{"is_no_change":false,"label":"after Sentence 1","letter":"B"},{"is_no_change":false,"label":"after Sentence 4","letter":"C"},{"is_no_change":false,"label":"before Sentence 1","letter":"D"}]', 'B', '{"A":"Rewinds the paragraph''s clock: carriers are already working alone in week three when the first-morning details suddenly return.","B":"Correct: the first-Saturday details follow the sentence that introduces the ride-along, and ''She'' sits next to Pruitt.","C":"Files the tour''s details after veterans have already delivered their verdict on the morning''s value.","D":"Opens the paragraph with ''She'' before Pruitt has been named."}', 'Placing the tour details right after the ride-along is introduced keeps the **chronology** intact and puts ''She'' beside its antecedent, Dot Pruitt.', 'The current spot tempts students because the sentence still reads grammatically there; only the timeline jump gives it away.', '1) Find the sentence''s time cues and pronouns. 2) Match the pronoun to its antecedent and keep them close. 3) Order events by the paragraph''s clock: first morning before third week. 4) Re-read the whole paragraph to confirm time moves forward.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3d75a81048059e7b', 'act-english', 's-org', 4, 'Requeening usually calms an aggressive colony. <u>Even so,</u> the hive''s temperament may take six weeks to soften, because the old queen''s defensive daughters must live out their lifespans first.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Consequently,","letter":"B"},{"is_no_change":false,"label":"In other words,","letter":"C"},{"is_no_change":false,"label":"For instance,","letter":"D"}]', 'A', '{"A":"Correct: the second sentence concedes a lingering complication that qualifies the calming claim, exactly the yes-but relationship ''Even so'' signals.","B":"''Consequently'' would present the six-week delay as flowing naturally from the calming claim, but the delay tempers that claim rather than resulting from it.","C":"''In other words'' signals a paraphrase, yet the second sentence adds new, qualifying information instead of restating the first.","D":"''For instance'' would require the delay to be an example of requeening''s calming effect, but it is a caveat working against that effect."}', 'The second sentence attaches a **concession** — the fix works, but slowly — so a yes-but transition fits the logic.', 'Because requeening does eventually calm the hive, students read the delay as a consequence of the fix and pick ''Consequently.''', '1) Summarize sentence one''s claim. 2) Ask what sentence two does to that claim: extends it, restates it, illustrates it, or qualifies it. 3) If sentence two admits a complication while leaving the claim standing, choose a concessive transition. 4) Confirm by reading the pair with a plain ''but still'' in the slot — if that works, the concession reading is right.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4026afc5e8d79eba', 'act-english', 's-org', 4, 'The article traces the comeback of the peregrine falcon: a pesticide ban in the 1970s, captive-breeding programs in the 1980s, and <u>the invention of the modern telescope.</u>', 'Which choice best continues the article''s line of argument about the falcon''s recovery?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the protection of nesting sites on city skyscrapers.","letter":"B"},{"is_no_change":false,"label":"the popularity of birdwatching as a hobby.","letter":"C"},{"is_no_change":false,"label":"the history of falconry in medieval Europe.","letter":"D"}]', 'B', '{"A":"Telescopes have no bearing on why falcon populations recovered.","B":"Protecting nesting sites is a genuine recovery cause, continuing the article''s chain of factors.","C":"Birdwatching''s popularity is a side effect, not a cause of the comeback.","D":"Medieval falconry is unrelated to the modern recovery being traced."}', 'Argument-tracing requires the next item to be **another cause in the same chain** — nesting-site protection is.', 'Options C and D both mention birds, so they feel connected to the falcon topic.', 'When a passage builds a causal list, each addition must belong to that same causal thread.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4eb2ec6cd8080dac', 'act-english', 's-org', 4, '____ When earthquakes multiply beneath the summit, the designation moves from green to yellow. If tremor becomes continuous and the flanks begin to swell, orange follows. Red is reserved for an eruption that is underway or expected within hours.', 'The writer wants to open the paragraph with a sentence that introduces its main subject. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Observatories rank a volcano''s restlessness on a four-color scale.","letter":"A"},{"is_no_change":false,"label":"A four-color scale can never capture every nuance of a volcano''s restlessness.","letter":"B"},{"is_no_change":false,"label":"Observatories around the world watch volcanoes with a growing array of instruments.","letter":"C"},{"is_no_change":false,"label":"Pilots depend on timely warnings whenever ash begins to rise.","letter":"D"}]', 'A', '{"A":"Correct: it names the color-coded ranking that the body then walks through level by level.","B":"Adopts a critical stance toward the scale that the explanatory paragraph never takes.","C":"Too broad — it gestures at monitoring in general and never mentions the ranking system.","D":"Previews only one late detail (aviation danger at the highest level) rather than the whole system."}', 'The body explains a **four-color ranking** step by step, and only this opener names that exact subject.', 'An opener about observatories and instruments sounds on-topic, but it never previews the ranking the paragraph actually explains.', '1) Read the paragraph without its opener and name its subject in one phrase. 2) Check each candidate: does it name that subject? 3) Reject openers that argue a stance the body never takes, zoom out too far, or spotlight one detail. 4) Confirm the survivor lets every following sentence feel like an expansion of it.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4ecc052dd5da1972', 'act-english', 's-org', 4, '[1] A tartan''s identity lies in its sett, the precise sequence of colored stripes repeated in both directions. [2] Weavers record each sett as a short string of color codes and thread counts. [3] Decades after a design is first woven, mills can therefore match it thread for thread. [4] Some Scottish families guard their setts as closely as heirloom recipes. [5] From that compact notation, a loom anywhere in the world can be threaded to recreate the cloth.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now","letter":"A"},{"is_no_change":false,"label":"after Sentence 1","letter":"B"},{"is_no_change":false,"label":"after Sentence 2","letter":"C"},{"is_no_change":false,"label":"after Sentence 3","letter":"D"}]', 'C', '{"A":"At the end, ''that compact notation'' sits far from the recording it describes, with the family-secrets sentence intervening.","B":"After Sentence 1, no notation has been mentioned yet, so ''that compact notation'' has nothing to point to.","C":"Correct: Sentence 2 introduces the recorded string, ''that compact notation'' refers to it, and Sentence 3''s ''therefore'' then follows logically.","D":"After Sentence 3, the conclusion drawn by ''therefore'' would come before the fact that justifies it."}', 'Sentence 5''s pointer ''that compact notation'' must directly follow the notation''s introduction, and Sentence 3''s ''**therefore**'' depends on it.', 'Leaving the sentence where it is tempts because it reads like a sweeping conclusion, but its pointer phrase loses its referent across the gap.', '1) Circle demonstratives (''that,'' ''this'') in the movable sentence. 2) Find the sentence that supplies the referent. 3) Test the slot immediately after it. 4) Re-read the whole paragraph checking that every ''therefore'' still has its cause in place.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-545e646d68ef68ad', 'act-english', 's-org', 4, '<u>Honey has been harvested for thousands of years.</u> Bees pollinate roughly a third of the crops humans eat, and almond growers truck hives across entire states each spring. Without managed colonies, many orchards would produce almost nothing.', 'Which choice provides the best topic sentence for the paragraph?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Beekeepers wear protective suits for good reason.","letter":"B"},{"is_no_change":false,"label":"Honey comes in many colors and flavors.","letter":"C"},{"is_no_change":false,"label":"Bees are essential partners in modern agriculture.","letter":"D"}]', 'D', '{"A":"The paragraph is about pollination and farming, not the history of honey harvesting.","B":"Protective suits never come up — the body is about crops and orchards.","C":"Honey varieties are irrelevant to pollination statistics and trucked hives.","D":"Every body sentence — the crop share, the trucked hives, the barren orchards — supports bees as agricultural partners."}', 'A topic sentence must be the claim **every body sentence supports**.', 'Honey feels on-topic because bees make it — adjacency masquerades as relevance.', 'Read the body first; the right topic sentence is the one the details already argue for.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5b95e976687d1ff2', 'act-english', 's-org', 4, 'Volunteers sort windfall fruit by headlamp, and the earliest crates reach the press before seven. By noon the barn smells of crushed Gravensteins, and families with empty jugs line the loading dock. When the tanks are finally full, the crew hoses down the floor by lantern light.', 'The writer wants to open the paragraph with a sentence that establishes its focus on the nonstop pace of a single pressing day. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Cider making has a long history in this part of the valley.","letter":"A"},{"is_no_change":false,"label":"Gravensteins ripen earlier than most other apples grown in the valley.","letter":"B"},{"is_no_change":false,"label":"On the orchard''s first pressing day of the season, the work starts in the dark and ends in the dark.","letter":"C"},{"is_no_change":false,"label":"Freshly pressed cider must be chilled quickly so that it stays sweet.","letter":"D"}]', 'C', '{"A":"A broad historical claim sets up a heritage paragraph, not an account of one frantic day''s schedule.","B":"A fact about ripening times previews a paragraph on varieties, not on the pace of the day''s labor.","C":"Correct: it names the specific day and frames its dawn-to-night span, which the paragraph then details hour by hour.","D":"A detail about chilling cider belongs mid-paragraph; it cannot frame the whole day''s timeline."}', 'The opener must **preview** the paragraph''s dawn-to-night timeline, which this sentence does explicitly.', 'The history opener sounds authoritative and on-topic, so students accept it without matching it to the paragraph''s actual content.', '1) Read the paragraph and state its focus in one phrase. 2) Ask what an opener must promise for that focus. 3) Eliminate options that are broader, narrower, or about a different aspect. 4) Confirm the survivor is developed by every following sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-67dc80c4ddf0db4d', 'act-english', 's-org', 4, 'The refuge closes its main trail during nesting season. <u>Even so,</u> visitors can still watch the herons from the observation deck across the channel.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"In other words,","letter":"C"},{"is_no_change":false,"label":"Likewise,","letter":"D"}]', 'A', '{"A":"Correct: the second sentence offers what remains possible despite the closure — a concessive relationship.","B":"The closure does not cause the deck viewing; the viewing persists in spite of the closure, so a causal word misstates the logic.","C":"The second sentence adds new, contrasting information rather than restating the closure in different words.","D":"The sentences are not parallel similar facts; the second pushes back against the limitation in the first."}', 'The second sentence tells what is still possible **despite** the closure, so a concessive transition is the logical link.', '''Therefore'' attracts students who assume any two connected facts must be cause and effect.', '1) Summarize each sentence in five words or fewer. 2) Ask: does the second sentence result from the first, restate it, resemble it, or push against it? 3) Select the transition class that matches. 4) Reinsert your choice and confirm the paragraph''s logic survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-68db340db7989caf', 'act-english', 's-org', 4, '[1] The pricing team meets at a long table in the back room every Tuesday. [2] Each member specializes in one category, from costume jewelry to small appliances. [3] Disagreements are settled with a quick auction-site search and a show of hands. [4] The system looks casual, but it keeps prices consistent from one week to the next.', 'For the sake of the logic and coherence of the paragraph, Sentence 3 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 1.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'A', '{"A":"Correct: disagreements arise from the specialists described in Sentence 2, and Sentence 4''s verdict on ''the system'' must follow the full description.","B":"Opens the paragraph with ''Disagreements,'' which have no context before the team or its members are introduced.","C":"Places the dispute-settling before readers learn who the specializing members are, breaking the chain of reference.","D":"Strands the detail after Sentence 4''s summary, which reads as the paragraph''s wrap-up of the whole system."}', 'Sentence 3 depends on Sentence 2''s specialists for context and must precede Sentence 4''s **summary** of the system.', 'Moving Sentence 3 right after the opening feels tidy because both mention team logistics, but the reference to disputes needs Sentence 2 first.', '1) Underline backward-pointing words in the movable sentence (here, ''Disagreements''). 2) Find the earlier sentence that creates those disagreements. 3) Place the sentence after its setup. 4) Check that any summary sentence still comes last. 5) Re-read the paragraph in the new order.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b2266deb8b16ad1', 'act-english', 's-org', 4, '______. During the final three weeks before a marathon, weekly mileage may drop by half or more. Muscles restock their fuel, small tears heal, and lost sleep is repaid. By race morning, a well-tapered runner stands on fresher legs than at any point in the buildup.', 'The writer wants to open the paragraph with a sentence that introduces its central idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Tapering, the planned reduction of training before a race, gives the body time to repair itself.","letter":"A"},{"is_no_change":false,"label":"Choosing the right race-morning breakfast can make or break a marathon.","letter":"B"},{"is_no_change":false,"label":"Glycogen is a form of carbohydrate stored in the muscles and the liver.","letter":"C"},{"is_no_change":false,"label":"Preparing for a marathon requires months of discipline and careful planning.","letter":"D"}]', 'A', '{"A":"Correct: it names the paragraph''s subject — reduced pre-race training — and forecasts the repair details every following sentence develops.","B":"Promises a nutrition discussion the paragraph never delivers (intro_offtopic).","C":"Defines one technical term touched by a single clause, far too narrow to introduce the whole paragraph (intro_too_narrow).","D":"Covers the entire months-long training process, far broader than this paragraph''s focus on the final three weeks (intro_too_broad)."}', 'A strong opener must **forecast** the paragraph, and only this sentence names the pre-race cutback and the bodily repair the following sentences describe.', 'The broad statement about months of preparation tempts students because it is true and marathon-related, even though the paragraph never discusses the full buildup.', '1) Read the paragraph without the opener. 2) State its central idea in one phrase. 3) Test each candidate: does it name that idea? 4) Reject candidates that are off-topic, narrower than the paragraph, or broader than the paragraph. 5) Confirm the survivor forecasts every following sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-74f1c740341e8597', 'act-english', 's-org', 4, 'For decades, my aunt repeated the story that an impatient clerk at Ellis Island shortened our surname. <u>Likewise,</u> the manifest we finally located shows the abbreviated spelling in my great-grandfather''s own handwriting, recorded before the ship ever left Genoa.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Consequently,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"In fact,","letter":"D"}]', 'D', '{"A":"''Likewise'' signals similarity, but the manifest disproves the aunt''s story rather than paralleling it.","B":"''Consequently'' invents a causal chain; the retold story did not produce the handwriting on the manifest.","C":"''For instance'' would make the manifest an example of the clerk legend, when it is evidence against it.","D":"Correct: the manifest corrects the long-held assumption, and this transition signals that corrective turn."}', 'The manifest **corrects** the family''s assumption, so the transition must signal reality overturning the story.', '''Consequently'' tempts readers who see ''finally located'' as the outcome of decades of retelling rather than checking what the manifest does to the story''s truth.', '1) Summarize the first sentence: a belief held for decades. 2) Summarize the second: evidence that disproves it. 3) Name that move — a correction of an assumption. 4) Test each transition against the pattern ''belief, then corrective reality.'' 5) Choose the one that signals the correction.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-760551a885397fc2', 'act-english', 's-org', 4, '[1] The forty-foot footbridge over Marten Creek took the crew most of July to build. [2] Stringers were felled upstream, floated down to the crossing, and winched onto stone abutments laid the summer before. [3] Trail tradition, meanwhile, marks every finished bridge in the district. [4] The oldest member of the crew drives the final spike. [5] Each worker then signs the underside of a deck plank in carpenter''s pencil. [6] Hikers never see the signatures, but the crew knows they are there.', 'The writer wants to divide this paragraph into two paragraphs. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 3.","letter":"A"},{"is_no_change":false,"label":"Sentence 4.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 6.","letter":"D"}]', 'A', '{"A":"Correct: Sentences 1–2 cover the bridge''s construction, and Sentence 3 pivots to finishing traditions, so the seam falls exactly there.","B":"Breaking here strands the tradition topic sentence at the bottom of the construction paragraph, cutting it off from the rituals it introduces.","C":"This split separates two rituals that belong together — the spike and the signatures — instead of falling at the real topic shift.","D":"Starting the new paragraph at the final sentence isolates a closing reflection and leaves all the tradition material in the construction paragraph."}', 'A paragraph break belongs at the **seam between topics** — here, where the passage turns from building the bridge to the traditions that mark its completion.', 'The slot before the spike-driving detail tempts students who break where the action changes rather than where the subject changes.', '1) Label each sentence''s topic in two or three words. 2) Find where the labels change from one subject to another. 3) Begin the new paragraph at the first sentence of the new subject. 4) Check that neither half loses its topic sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-769ad46a228fe241', 'act-english', 's-org', 4, '[1] Mallards were the first ducks to colonize the canal district. [2] They arrived within a year of the water-quality project''s completion. [3] By last spring, mallard broods were paddling past the coffee shops every morning. [4] Wood ducks, by contrast, needed far more persuading. [5] Only after volunteers mounted nesting boxes under the footbridges did the first wood duck pairs appear. [6] Even now, they keep to the quietest stretch of the canal.', 'The writer wants to divide this paragraph into two paragraphs in order to separate its two main ideas. The most logical place to begin the new paragraph is at:', '[{"is_no_change":false,"label":"Sentence 4","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 5","letter":"C"},{"is_no_change":false,"label":"Sentence 2","letter":"D"}]', 'A', '{"A":"Correct: Sentence 4 is where the topic pivots from mallards to wood ducks, so the break separates the two ideas cleanly.","B":"Sentence 3 still develops the mallard story, so breaking there splits the first idea in half (break_splits_idea).","C":"Breaking at Sentence 5 strands the wood ducks'' introduction at the end of the mallard paragraph (break_after_shift).","D":"Sentence 2 elaborates the opening claim, so breaking there orphans the support from its topic sentence (break_too_early)."}', 'A paragraph break belongs at the **topic shift**, and the pivot from mallards to wood ducks happens exactly at Sentence 4.', 'Sentence 5''s volunteer project feels like a fresh scene, so students break there and fail to notice the species shift began one sentence earlier.', '1) Label each sentence with its subject. 2) Group consecutive sentences that share a subject. 3) The new paragraph begins at the first sentence of the second group. 4) Verify the first sentence after the break could serve as a topic sentence. 5) Re-read both halves to confirm each is unified.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-794003a35433056a', 'act-english', 's-org', 4, '[1] Once a year, entire coral colonies release their eggs and sperm in a single synchronized burst. [2] The precise timing is triggered by the lunar cycle and by rising water temperature. [3] Millions of tiny bundles then drift upward, tinting the surface a faint pink. [4] Fertilized eggs develop into larvae that eventually settle onto bare rock.', 'The writer wants to add the sentence "Only a tiny fraction of these larvae will survive to adulthood." The sentence would most logically be placed:', '[{"is_no_change":false,"label":"after Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 2.","letter":"B"},{"is_no_change":false,"label":"after Sentence 3.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'D', '{"A":"At this point no larvae have been mentioned, so ''these larvae'' has no referent (placement_no_referent).","B":"The timing-triggers idea is unrelated to larval survival, and larvae are still unnamed (placement_interrupts).","C":"Drifting bundles are described, but the larvae themselves have not yet been introduced (placement_no_referent).","D":"Correct: only after Sentence 4 introduces the larvae does the survival detail have a clear referent and logical home."}', 'A sentence that refers back to ''these larvae'' must follow the sentence that first **introduces** the larvae.', 'The dramatic spawning burst in Sentence 1 tempts students to attach the survival fact early, before larvae are named.', '1) Locate any back-pointing phrase in the new sentence (''these larvae''). 2) Find where that noun is first introduced. 3) Place the new sentence only after that introduction. 4) Confirm the addition follows logically from the neighboring sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-79a26cd5de7d60c8', 'act-english', 's-org', 4, '[1] Zion''s shuttle system did not exist before 2000. [2] Back then, cars idled bumper to bumper along the canyon''s only road, and overflow parking crushed fragile streamside ground. [3] Park managers responded by banning most private vehicles and running quiet propane buses instead. [4] Today, birdsong rather than engine noise fills the canyon. [5] The ban met fierce resistance from local businesses at first.', 'The writer wants Sentence 5 placed where it will best preserve the paragraph''s logical sequence of events. Where should Sentence 5 appear?', '[{"is_no_change":false,"label":"Where it is now","letter":"A"},{"is_no_change":false,"label":"After Sentence 1","letter":"B"},{"is_no_change":false,"label":"After Sentence 2","letter":"C"},{"is_no_change":false,"label":"After Sentence 3","letter":"D"}]', 'D', '{"A":"Leaves the initial resistance dangling after the present-day payoff, scrambling the timeline.","B":"Inserts the reaction before either the problem or the ban has been described.","C":"Places resistance to a ban that has not yet been announced.","D":"Puts the reaction immediately after the ban it responds to and before the present-day result."}', '''At first'' marks the sentence as the **immediate reaction to the ban**, so it belongs right after the ban is introduced.', 'Leaving the sentence where it is feels safe because it reads grammatically, even though the chronology breaks.', '1) Find the moving sentence''s time cues and pointing words (''the ban,'' ''at first''). 2) Locate the sentence that introduces what those cues point to. 3) Place the mover directly after that anchor. 4) Re-read the paragraph in order to confirm the timeline runs one direction.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7f5ded389e427d7c', 'act-english', 's-org', 4, 'When the mill closed in 2009, Harper''s Bend lost its only department store. The thrift shop that moved into the empty storefront now hosts a repair caf&eacute; on Saturdays, and retirees teach teenagers to patch jeans and rewire lamps. Neighbors linger in the aisles long after their purchases are rung up.', 'The writer wants a concluding sentence that reinforces the paragraph''s main idea about what the shop provides for Harper''s Bend. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The mill''s machinery was eventually sold to a factory two states away.","letter":"A"},{"is_no_change":false,"label":"Thrift shopping has grown steadily more popular across the country in recent years.","letter":"B"},{"is_no_change":false,"label":"The shop also sells used furniture at reasonable prices.","letter":"C"},{"is_no_change":false,"label":"In a town that lost its only department store, the shop has become a gathering place as much as a business.","letter":"D"}]', 'D', '{"A":"Follows the mill''s equipment rather than the shop, ending the paragraph off-topic.","B":"Zooms out to a national trend, abandoning the paragraph''s focus on one community.","C":"Adds a narrow sales detail instead of capturing the shop''s social role.","D":"Correct: it gathers the paragraph''s details — the vanished store, the caf&eacute;, the lingering neighbors — into one closing statement of the shop''s community role."}', 'A strong conclusion **synthesizes** the paragraph''s specifics into a final statement of its central idea, here the shop''s social role in the community.', 'The furniture detail stays on the subject of the shop, so it feels connected even though it ignores the paragraph''s real point.', '1) State the paragraph''s main idea in one sentence. 2) List what each option emphasizes. 3) Eliminate options that drift off-topic, zoom too wide, or shrink to a stray detail. 4) Keep the option that echoes the main idea using the paragraph''s own threads. 5) Read the paragraph with it appended to confirm the landing.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-81f314a00abb14f1', 'act-english', 's-org', 4, '<p>[1] Every November, members gather for the garden''s final workday of the season. [2] The first task is draining the rain barrels before a hard freeze can crack them. [3] Crews then spread shredded leaves over the emptied beds. [4] By dusk, the whole site is tucked in for winter. [5] Once drained, each barrel is tipped upside down and strapped to the fence so it cannot refill with snowmelt.</p>', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'C', '{"A":"Leaving it here reopens the barrel task after Sentence 4 has already closed the entire workday.","B":"''Once drained'' would lean on a draining that has not yet been mentioned.","C":"Correct: the sentence continues the barrel task begun in Sentence 2, keeping both steps of that chore adjacent and the day in order.","D":"This placement wedges a bed-related sentence between the two barrel steps, splitting one chore in half."}', 'The opener ''Once drained'' must **immediately follow** the sentence that describes the draining, keeping both steps of the barrel chore together.', 'The barrel-flipping detail reads like a closing safeguard, so students leave it at the end without noticing it reopens a chore the paragraph already wrapped up.', '1) Find the misplaced sentence''s anchor — a phrase like ''Once drained'' that depends on an earlier action. 2) Locate the sentence describing that action. 3) Place the sentence immediately after its anchor so steps of one task stay adjacent. 4) Reread the paragraph in the new order and confirm the timeline runs start to finish without backtracking.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-86bfefb5e687eb62', 'act-english', 's-org', 4, 'Great Smoky Mountains National Park receives more visitors than any other national park, yet its maintenance budget is among the leanest per guest. Volunteer crews clear storm-downed trees, staff the visitor desks, and monitor backcountry campsites. Last year, these crews donated more than 400,000 hours of work.', 'The writer wants to conclude the paragraph with a sentence that reinforces its main idea. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The park''s synchronous fireflies draw thousands of spectators every June.","letter":"A"},{"is_no_change":false,"label":"Many national parks were established in the early twentieth century.","letter":"B"},{"is_no_change":false,"label":"Such unpaid labor keeps the nation''s busiest park running.","letter":"C"},{"is_no_change":false,"label":"Visitors to the park should always pack rain gear before hiking.","letter":"D"}]', 'C', '{"A":"Introduces a new attraction instead of returning to the volunteers-versus-budget point.","B":"Zooms out to unrelated park-system history, abandoning the paragraph''s focus entirely.","C":"Ties the volunteer hours back to the gap between heavy visitation and a thin budget—the paragraph''s central idea.","D":"Offers practical advice that no sentence in the paragraph prepared."}', 'A strong conclusion **restates the paragraph''s central tension**—huge crowds, small budget, volunteers filling the gap.', 'The firefly sentence stays inside the same park and sounds vivid, so students mistake topical proximity for relevance.', '1) Write the paragraph''s main idea in one clause. 2) Test each closer: does it circle back to that clause? 3) Reject closers that add new topics, zoom too far out, or give unprepared advice. 4) Pick the one that echoes the opening tension.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8f419a733dbba475', 'act-english', 's-org', 4, 'Passage II — The Science of Sourdough — Bread may seem simple, but sourdough is surprisingly complex. Unlike breads made with packaged yeast, sourdough rises using wild yeast and bacteria captured from the air. Bakers maintain a "starter," a mixture of flour and water that they feed regularly. The starter, it ferments over several days. During fermentation, the microbes produce carbon dioxide, which makes the dough rise. They also produce acids, giving sourdough its tangy flavor. Because of these reactions, no two starters taste exactly alike. Some bakers, claim that a starter''s flavor reflects the place where it was made. A San Francisco starter, for instance, may taste different from one in Paris. Whether or not that is true, sourdough remains a small marvel of biology and patience.', 'Should the sentence about San Francisco and Paris be kept or deleted, and why?', '[{"is_no_change":false,"label":"Kept, because it gives a concrete example illustrating the preceding claim.","letter":"A"},{"is_no_change":false,"label":"Kept, because it explains the chemistry of fermentation.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it repeats the essay''s opening.","letter":"C"},{"is_no_change":false,"label":"Deleted, because it introduces an unrelated topic.","letter":"D"}]', 'A', '{"A":"The example illustrates the claim → keep.","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'The example illustrates the claim → keep.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Production (keep/delete w/ reasoning)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a5959a46e41ed1a0', 'act-english', 's-org', 4, '[1] In the 1910s, New Orleans musicians began leaving home in growing numbers. [2] King Oliver''s Creole Jazz Band soon packed Lincoln Gardens on Chicago''s South Side. [3] In 1922, Oliver sent for his young prot&eacute;g&eacute;, Louis Armstrong, to join him there. [4] The band''s twin-cornet breaks, worked out by the two men onstage, became the talk of the city''s musicians. [5] Direct rail lines from Louisiana made Chicago the most natural destination for these departing players.', 'For the sake of the logic and cohesion of the paragraph, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now","letter":"A"},{"is_no_change":false,"label":"after Sentence 1","letter":"B"},{"is_no_change":false,"label":"after Sentence 2","letter":"C"},{"is_no_change":false,"label":"after Sentence 3","letter":"D"}]', 'B', '{"A":"misplaced_afterthought: at the end, the rail-line explanation dangles after the story has moved on to onstage cornet breaks.","B":"Correct: it explains *why* the departing players of Sentence 1 headed to Chicago, setting up Sentence 2.","C":"Placed after Sentence 2, it interrupts the Oliver narrative that Sentences 2 through 4 build.","D":"Placed after Sentence 3, it splits the prot&eacute;g&eacute;''s arrival from the duet breaks that resulted."}', 'The sentence answers the question Sentence 1 raises — where the leavers went and **why** — and hands off smoothly to Sentence 2.', 'Leaving it where it is feels harmless because the fact is true throughout, but a paragraph''s final slot should carry a payoff, not a stray explanation.', '1) Identify what the movable sentence explains or introduces. 2) Find the sentence that raises that exact question. 3) Place the movable sentence immediately after it. 4) Reread the whole paragraph to confirm no chain of events is interrupted.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a888122286709656', 'act-english', 's-org', 4, '[1] Marisol''s marathon morning follows a script refined over five races. [2] Three hours before the start, she eats oatmeal and a banana in her hotel room. [3] At the staging area, she jogs ten easy minutes and runs four short strides. [4] She then sheds her throwaway sweatshirt and files into the corral. [5] An hour before leaving the hotel, she tapes her ankles and pins on her bib.', 'The writer wants Sentence 5 placed where it best preserves the paragraph''s chronological order. Where should Sentence 5 be placed?', '[{"is_no_change":false,"label":"Where it is now","letter":"A"},{"is_no_change":false,"label":"Before Sentence 1","letter":"B"},{"is_no_change":false,"label":"After Sentence 1","letter":"C"},{"is_no_change":false,"label":"After Sentence 2","letter":"D"}]', 'D', '{"A":"Leaves a hotel-room task after Marisol has already entered the corral, breaking the timeline (placement_ignores_time_cue).","B":"Puts a mid-routine detail ahead of the sentence that introduces the routine, stranding it without context (placement_before_frame).","C":"Puts the final hotel tasks before the breakfast eaten three hours out, reversing the clock (placement_wrong_slot).","D":"Correct: taping and pinning happen in the last hour at the hotel, after the early breakfast and before she reaches the staging area."}', 'The time cue ''an hour before leaving the hotel'' slots the sentence **between** the early hotel breakfast and the arrival at the staging area.', 'Leaving the sentence where it is tempts students who read it as a wrap-up detail rather than checking its time stamp against the sequence.', '1) Underline the time or place cue in the movable sentence. 2) List the paragraph''s events in order with their cues. 3) Find the two events the movable sentence falls between. 4) Place it in that gap. 5) Re-read the paragraph to confirm the clock never runs backward.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-aea09ec9bd70e1a8', 'act-english', 's-org', 4, '[1] In 1886, the <i>New-York Tribune</i> installed the first commercial Linotype machine. [2] Each keystroke released a small brass mold, called a matrix, from a magazine overhead. [3] When a line of molds was complete, the machine cast it in molten metal as a single fresh slug. [4] Finished slugs were then locked into page frames and hurried to the press.', 'The writer wants to add the following true sentence to the paragraph: <i>Its keyboard resembled a typewriter''s, but each key summoned a mold rather than striking a letter onto paper.</i> For the sake of the logic and cohesion of the paragraph, the sentence should be placed:', '[{"is_no_change":false,"label":"before Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 3.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'B', '{"A":"Placed first, ''Its keyboard'' has no machine to refer back to, leaving the pronoun stranded.","B":"After Sentence 1, ''Its'' clearly refers to the newly introduced machine, and the keyboard description sets up the keystroke in Sentence 2.","C":"By Sentence 3 the paragraph has moved on to casting; doubling back to the keyboard breaks the process order.","D":"At the end, the keyboard detail trails the finished slugs, far from the keystroke it explains."}', 'The sentence must sit where its pronoun finds its noun and where it **sets up** the keystroke that follows.', 'The end position tempts students who treat added sentences as afterthoughts rather than links in a step-by-step process.', '1) Find every pointer in the new sentence — pronouns, time words, repeated terms. 2) Locate the sentence each pointer needs to follow. 3) Locate the sentence the new material must come before, based on what it sets up. 4) The slot between those anchors is the placement. 5) Re-read the paragraph with the sentence inserted to confirm the chain of steps.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-af530f347820d781', 'act-english', 's-org', 4, 'Paragraph 2 explains how the tide pools form at low water. Paragraph 3 lists the animals that shelter there. <u>Meanwhile,</u> the guide leads visitors from the parking lot down to the rocks.', 'Which choice best opens a sentence that should logically come between paragraphs 2 and 3?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Once the water recedes, a whole community of creatures emerges.","letter":"B"},{"is_no_change":false,"label":"The parking lot fills quickly on summer weekends.","letter":"C"},{"is_no_change":false,"label":"Tides are caused by the pull of the moon and sun.","letter":"D"}]', 'B', '{"A":"''Meanwhile'' plus a parking-lot detail doesn''t bridge how pools form to which animals live there.","B":"It links the low-tide formation (para 2) to the sheltering animals (para 3) — a true bridge.","C":"The parking lot is unrelated to the pools-to-animals transition.","D":"Restating what causes tides steps backward instead of moving toward the animals."}', 'A bridging sentence must **connect the idea before it to the idea after it** — formation to inhabitants.', '''Meanwhile'' signals a transition, so option A looks structurally correct at a glance.', 'A transition sentence should echo the prior paragraph and point toward the next one.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b2392096e8e1a23a', 'act-english', 's-org', 4, '<p>_____ Ten years ago, a member could claim a plot the same week she applied. Today, applicants wait an average of three growing seasons, and the board caps each household at a single bed. The rules for keeping a plot have tightened, too: miss two scheduled workdays, and your renewal drops to the bottom of the list.</p>', 'The writer wants to open the paragraph with a sentence that introduces its main point. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"As the garden''s popularity has soared, its once-casual plot policies have hardened into a strict system.","letter":"A"},{"is_no_change":false,"label":"Community gardens have existed in American cities for well over a century.","letter":"B"},{"is_no_change":false,"label":"The board reviews plot applications on the first Tuesday of every month.","letter":"C"},{"is_no_change":false,"label":"Patience has always been the most important virtue a gardener can practice.","letter":"D"}]', 'A', '{"A":"Correct: it previews exactly what the paragraph develops — a shift from casual to strict plot policies driven by demand.","B":"Too broad: a century of national history promises a survey the paragraph never delivers.","C":"Too narrow: one committee''s meeting schedule is a supporting detail, not the paragraph''s umbrella idea.","D":"Off focus: a maxim about personal temperament points away from the paragraph''s real subject, tightening policies."}', 'An effective introduction **previews** the paragraph''s actual content, and this one forecasts both the growing demand and the hardening rules that the details develop.', 'The sweeping historical opener sounds authoritative, so students pick it without testing whether the paragraph ever discusses that history.', '1) Read the paragraph''s body and list what its sentences actually cover. 2) State the shared main idea in one line. 3) Test each opener: does it forecast that idea at the same scope — not broader, not narrower, not sideways? 4) Eliminate any opener promising content the paragraph never provides. 5) Confirm the survivor connects smoothly to the very next sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b6756539046236ca', 'act-english', 's-org', 4, 'Shallow-water corals starve without sunlight, since the algae in their tissues must photosynthesize to feed their hosts. <u>Likewise,</u> the cold-water corals of the deep North Atlantic build sprawling mounds in total darkness, snaring drifting plankton with their tentacles.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"By contrast,","letter":"B"},{"is_no_change":false,"label":"As a result,","letter":"C"},{"is_no_change":false,"label":"In other words,","letter":"D"}]', 'B', '{"A":"''Likewise'' claims the second sentence parallels the first, but sunlight-dependence and life in total darkness are opposing conditions (misconception: transition_false_similarity).","B":"The two sentences set opposite feeding strategies against each other, so an opposition transition is correct.","C":"Nothing about shallow corals'' need for light causes deep corals to trap plankton; there is no causal chain (misconception: transition_false_cause).","D":"''In other words'' promises a restatement, but the second sentence introduces new, opposing information about a different group (misconception: transition_false_restatement)."}', 'The sentences **oppose** each other — light-dependent feeding versus feeding in total darkness — so the connector must flag a difference.', 'Both sentences describe corals feeding, so the surface similarity of topic makes a likeness transition feel right even though the two strategies clash.', '1) Summarize each sentence in five words or fewer. 2) Ask: does the second echo, oppose, follow from, or restate the first? 3) Ignore shared topic words — judge the logic, not the vocabulary. 4) Pick the transition whose job matches the logic you identified.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b75c3d69855612ea', 'act-english', 's-org', 4, 'Critics at the major newspapers dismissed the revival as a passing fad, and most radio programmers agreed. <u>As a result,</u> small labels kept pressing folk records, betting that an audience the critics could not see was quietly growing.', 'Which choice most logically connects this sentence to the one before it?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For instance,","letter":"B"},{"is_no_change":false,"label":"In the same way,","letter":"C"},{"is_no_change":false,"label":"Nevertheless,","letter":"D"}]', 'D', '{"A":"''As a result'' claims the dismissal caused the labels to keep pressing records, but their persistence happened in spite of it, not because of it.","B":"''For instance'' would make the labels'' persistence an example of critics'' dismissal, which it plainly is not.","C":"''In the same way'' claims the labels acted like the critics, when they did the opposite.","D":"Correct: the labels pressed on despite the critics'' dismissal, a concessive relationship."}', 'The labels acted **in spite of** the critics'' dismissal, so the transition must concede opposition rather than assert cause.', '''As a result'' tempts students because the second sentence does follow the first in time, and sequence is easily mistaken for causation.', '1) State what the first sentence predicts should happen next. 2) Check whether the second sentence fulfills that prediction or defies it. 3) If it defies it, you need a concession word; if it fulfills it, a cause-effect word. 4) Re-read with your choice to confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b76fdeb9c3cce36e', 'act-english', 's-org', 4, '[1] A daguerreotype''s image rests on a mirror-polished silver plate that a single fingerprint can ruin forever. [2] For that reason, conservators pick up the plates only by their edges, and only with gloved hands. [3] Even breath can bloom into tarnish, so masks are standard at the bench. [4] Housing the plates poses a different challenge. [5] Their original cases were made of leather and wood, materials that slowly release acids. [6] Many museums therefore rehouse each plate in a sealed archival sleeve.', 'The writer wants to divide this paragraph into two, so that the first paragraph focuses on handling the plates and the second on storing them. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 4","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 5","letter":"C"},{"is_no_change":false,"label":"Sentence 6","letter":"D"}]', 'A', '{"A":"Correct: Sentence 4 explicitly pivots to ''a different challenge,'' and everything after it concerns storage.","B":"Sentence 3 is still about handling precautions at the bench, so splitting there strands a handling detail in the storage paragraph.","C":"Starting at Sentence 5 orphans the pivot sentence, leaving the first paragraph to end on a topic it never develops.","D":"Starting at Sentence 6 puts the case-materials problem in the handling paragraph and opens the second with ''therefore,'' a conclusion cut off from its cause."}', 'A new paragraph should begin at the **topic pivot** — the sentence that announces the shift from handling to housing.', 'Students often split right before the first concrete storage detail rather than at the transition sentence that introduces the new topic.', '1) Label each sentence with its topic in one or two words. 2) Find where the labels switch for good. 3) The new paragraph begins at the first sentence of the new topic — usually a transition or announcement sentence. 4) Check both halves: each should open on its own topic and contain no sentences from the other. 5) Confirm no paragraph starts with a dangling connector like ''therefore.''', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b83ed2d808eacaca', 'act-english', 's-org', 4, 'Planners braced for the road diet to slow fire-truck response times along Cedar Avenue. <u>Therefore,</u> engines reached calls faster once double-parking disappeared from the corridor.', 'Which choice provides the most logical transition?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Consequently,","letter":"B"},{"is_no_change":false,"label":"In fact,","letter":"C"},{"is_no_change":false,"label":"Likewise,","letter":"D"}]', 'C', '{"A":"''Therefore'' treats faster responses as the expected result of the planners'' worry, but the outcome defied the expectation.","B":"''Consequently'' repeats the same false cause-effect link as ''Therefore.''","C":"''In fact'' signals that reality contradicted or outstripped the expectation, which is exactly the relationship here.","D":"''Likewise'' claims similarity, but the sentences set up an expectation and then overturn it."}', 'The second sentence **overturns the expectation** set up in the first — the precise job of this corrective transition.', 'Students see a setup sentence followed by an outcome and reflexively reach for a cause-effect word like ''Therefore.''', '1) Ask what the first sentence predicts or expects. 2) Ask whether the second sentence fulfills that expectation or defies it. 3) Fulfilled: use a result word. Defied: use a correction or contrast word. Parallel: use a likeness word. 4) Re-read with your choice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c75ca08ec9cc519e', 'act-english', 's-org', 4, '[1] Big-league clubs routinely send injured stars to minor-league affiliates to sharpen their timing. [2] Last June, the Owls hosted all-star pitcher Dana Whitfield for two rehab starts. [3] Ticket demand tripled within hours of the announcement. [4] Whitfield threw four scoreless innings in her opening outing and signed autographs afterward. [5] The windfall from those ticket sales paid for a fresh coat of paint on the aging concourse.', 'The writer wants to improve the logic and cohesion of the paragraph. To accomplish that goal, Sentence 5 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 3.","letter":"D"}]', 'D', '{"A":"Leaves ''those ticket sales'' stranded two sentences from its referent, implying the pitching performance produced the money (placement_far_referent).","B":"Mentions a windfall before Whitfield''s visit or any demand exists, so the reference has no antecedent (placement_before_cause).","C":"At that point the paragraph has not yet described any surge in tickets, so ''those ticket sales'' still points at nothing (placement_before_cause).","D":"Correct: the revenue sentence directly follows the demand spike that generated it, keeping cause and result adjacent."}', '''Those ticket sales'' points back to the demand spike, so **cause and result** must sit side by side.', 'The sentence reads like a wrap-up, so students leave it at the end even though its pointer word reaches back past an unrelated sentence.', '1) Find pointer words in the movable sentence (''those,'' ''this,'' ''such''). 2) Locate the exact sentence they refer to. 3) Place the movable sentence immediately after that referent. 4) Confirm nothing between cause and result changes the meaning. 5) Re-read the paragraph for flow.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ca5c5f1ac3e4e4f3', 'act-english', 's-org', 4, '[1] For most of the twentieth century, the orchard sold every bushel to a wholesale packer in the city. [2] Prices were set by the packer, and in lean years the checks barely covered the picking crew''s wages. [3] The arrangement finally collapsed when the packer closed its warehouse in 1998. [4] That fall, the family opened a small stand at the end of the driveway. [5] Word spread, and weekend customers soon asked for tours, doughnuts, and pick-your-own hours. [6] Today, retail sales at the stand bring in more than the wholesale contracts ever did.', 'The writer wants to divide the paragraph into two paragraphs, the first focusing on the orchard''s wholesale era and the second on its shift to selling directly to customers. The best place to begin the second paragraph is with:', '[{"is_no_change":false,"label":"Sentence 4.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 6.","letter":"D"}]', 'A', '{"A":"Correct: Sentence 4 is the first sentence about direct retail, so the break cleanly separates the wholesale story from the stand''s story.","B":"Sentence 3 still narrates the wholesale arrangement — its collapse belongs with the era it concludes.","C":"Starting at Sentence 5 strands the stand''s opening, the retail story''s first event, in the wholesale paragraph.","D":"Starting at Sentence 6 leaves nearly the whole retail story attached to the wholesale era."}', 'A paragraph break belongs at the **first** sentence of the new topic, and the driveway stand is the retail story''s first event.', 'Sentence 3 mentions the dramatic 1998 turning point, so students split at the exciting moment instead of at the topic change.', '1) Label each sentence with its topic in two or three words. 2) Find where the labels switch for good. 3) Begin the new paragraph at the first sentence carrying the new label. 4) Check that each resulting paragraph reads as one unified story.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d0fd712b934dddbe', 'act-english', 's-org', 4, '<p>[1] In 2022, the garden set aside its sunniest corner for a pollinator bed. [2] Members debated the plant list for weeks before settling on natives: milkweed, bee balm, and three kinds of aster. [3] A nursery across town donated the first fifty plugs. [4] A Saturday crew planted every one of them in a single morning. [5] The following June, the corner hummed with life. [6] Monarchs, bumblebees, and even a hummingbird moth worked the blossoms from first light until dusk.</p>', 'The writer wants to divide this paragraph into two paragraphs. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'D', '{"A":"Breaks mid-stage: the plant-list debate still belongs to the story of creating the bed.","B":"The donation supplies the very plants the earlier sentences were preparing for; it continues the establishment stage.","C":"The planting morning completes the construction phase, so a break here separates a stage from its final step.","D":"Correct: ''The following June'' jumps ahead in time and shifts the focus from building the bed to what it produced."}', 'The paragraph should split where **time and topic shift together** — from constructing the bed to observing its results the next summer.', 'The donation from an outside nursery feels like new subject matter, so students break there even though it advances the same establishment story.', '1) Read the paragraph and label each sentence''s stage or topic. 2) Find the seam where the time frame, place, or purpose genuinely changes. 3) Confirm every sentence before the seam belongs to stage one and every sentence after belongs to stage two. 4) Start the new paragraph at the first sentence of the second stage. 5) Reread both halves to check each stands as a unified unit.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d3cf3c10bd50870d', 'act-english', 's-org', 4, 'Arbiters rarely rule on a touch-move dispute without first hearing both players. <u>In addition,</u> at last spring''s open, the chief arbiter questioned four witnesses before deciding the fate of a single knight.', 'Which choice provides the most logical transition?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Nevertheless,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"In other words,","letter":"D"}]', 'C', '{"A":"''In addition'' treats the anecdote as a brand-new coordinate point, but it actually illustrates the general claim just made.","B":"''Nevertheless'' signals contradiction, yet the arbiter''s careful questioning confirms, rather than opposes, the first sentence.","C":"The second sentence gives one specific case of the general habit described in the first, so an illustration transition fits.","D":"''In other words'' promises a restatement, but the anecdote adds a concrete new scene rather than paraphrasing the claim."}', 'The second sentence offers a **specific case** that illustrates the general claim in the first.', '''In addition'' tempts because the anecdote does feel like more information, masking that it illustrates rather than adds a new point.', '1) Label the first sentence: general claim or specific detail? 2) Label the second sentence the same way. 3) General followed by specific calls for an illustration transition; general followed by a new general point calls for an addition word. 4) Reread with your choice and check the logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d6b04a12aa2e2970', 'act-english', 's-org', 4, 'The improv troupe never performs from a script. <u>Similarly,</u> its members spend weeks drilling the same structured warm-up games before every show.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Therefore,","letter":"B"},{"is_no_change":false,"label":"In fact,","letter":"C"},{"is_no_change":false,"label":"Nevertheless,","letter":"D"}]', 'D', '{"A":"''Similarly'' claims the disciplined drilling parallels going scriptless, but the structure actually cuts against the free-form image (transition_false_similarity).","B":"''Therefore'' asserts that skipping scripts causes the weeks of drills, a causal chain the sentences never establish (transition_false_cause).","C":"''In fact'' should intensify the first claim, yet the drilling complicates rather than sharpens the unscripted picture (transition_false_intensifier).","D":"Correct: heavy structured practice is a surprising concession alongside unscripted performance, so a concessive transition fits."}', 'The second sentence **concedes** something surprising — rigid, repeated structure inside a supposedly spontaneous group — so a concession transition is required.', '''In fact'' tempts students because both sentences describe the troupe''s habits, making the second feel like an emphatic elaboration rather than a twist.', '1) Summarize sentence one in your own words. 2) Summarize sentence two. 3) Ask: does the second echo, cause, intensify, or push against the first? 4) If it pushes against expectations while both remain true, choose a concessive connector. 5) Reread the pair to confirm the tension is acknowledged.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-db074f133596ee0a', 'act-english', 's-org', 4, '[1] The district ordered twelve thousand pairs of eclipse glasses months before the event. [2] Teachers rehearsed safe-viewing procedures with every class during the final week. [3] On eclipse morning, students filed onto the field in small groups. [4] Each pair was checked for scratches and pinholes before being added to the inventory. [5] By the time the Moon took its first bite of the Sun, every student was equipped and ready.', 'For the sake of the logic and cohesion of the paragraph, Sentence 4 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 5.","letter":"D"}]', 'B', '{"A":"Where it is now, an inventory check of arriving pairs interrupts eclipse-morning action and jumps backward in time.","B":"Correct: inspecting pairs ''before being added to the inventory'' belongs to the receiving stage, right after the order is placed.","C":"After the rehearsal week is still later than the step it describes—the arrival and stocking of the shipment.","D":"After the climactic moment, an inventory check sends the timeline backward at the paragraph''s close."}', 'The clue ''before being added to the **inventory**'' ties the inspection to the shipment''s arrival, which immediately follows the ordering step.', 'Leaving the sentence where it is tempts students who read ''each pair was checked'' as part of handing out glasses on eclipse morning rather than stocking them months earlier.', '1) Underline the movable sentence''s time clues (''before being added to the inventory''). 2) Map each sentence in the paragraph to a stage: ordering, training, event day, climax. 3) Assign the movable sentence to its stage using the clues. 4) Place it at that stage and re-read the paragraph to confirm the chronology never reverses.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f120c175300d0710', 'act-english', 's-org', 4, 'For decades, packers shipped live cattle east in slatted cars, absorbing the weight the animals lost along the way. <u>For example,</u> the refrigerated car let them ship only dressed beef, and freight bills fell by nearly half.', 'Which choice provides the most logical transition from the preceding sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Likewise,","letter":"B"},{"is_no_change":false,"label":"In short,","letter":"C"},{"is_no_change":false,"label":"Instead,","letter":"D"}]', 'D', '{"A":"''For example'' would make the refrigerated car an instance of shipping live cattle, which it is not.","B":"''Likewise'' treats the new method as more of the same, but it replaced the old practice.","C":"''In short'' announces a summary, yet the second sentence introduces new information rather than condensing the first.","D":"Correct: the refrigerated car supplanted the live-cattle system, so a replacement transition captures the logic."}', 'Sentence two describes what packers did **in place of** the old practice, so the transition must mark a substitution.', '''Likewise'' tempts readers who notice both sentences discuss shipping and miss that the second method displaced the first.', '1) Restate sentence one and sentence two in plain words. 2) Ask: does idea two continue, illustrate, summarize, or replace idea one? 3) Match the transition to that exact function. 4) Reread the pair; if the connector implies the old practice continued, reject it.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f6e7b7c95218c29b', 'act-english', 's-org', 4, '[1] Gray whales undertake one of the longest migrations of any mammal. [2] Each autumn they leave the cold, food-rich waters of the Arctic. [3] Swimming south along the coast, they cover roughly six thousand miles. [4] Their destination is a chain of warm, shallow lagoons off the coast of Mexico. [5] There, females give birth to calves in water safe from most predators.', 'The writer wants to divide this passage into two paragraphs. The best place to begin the new paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'C', '{"A":"Sentence 2 continues the same journey idea begun in Sentence 1, so a break there splits one thought (division_midtopic).","B":"Sentence 3 still describes the outbound trip, not a new subject (division_midtopic).","C":"Correct: the focus turns from the journey to the destination and breeding, so the new paragraph begins here.","D":"The destination focus already starts at Sentence 4, so beginning at Sentence 5 strands its opening sentence (division_late)."}', 'A new paragraph should start where the passage''s **focus shifts** — here, from the migration to the destination.', 'The vivid distance figure in Sentence 3 feels like a turning point, so students break there instead of at the true topic change.', '1) Summarize each sentence in a few words. 2) Find the first sentence that turns to a new subtopic. 3) Begin the new paragraph at that sentence, not one before or after. 4) Check that each resulting paragraph holds together around one idea.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fb11364152acf6d3', 'act-english', 's-org', 4, 'The two most trusted models now disagree sharply about the storm''s likely track. <u>In other words,</u> the hurricane center has widened its cone of uncertainty on the latest advisory.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Nevertheless,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"As a result,","letter":"D"}]', 'D', '{"A":"''In other words'' promises a restatement, but widening the cone is a new action caused by the disagreement (misconception: restatement word for any follow-up).","B":"''Nevertheless'' signals the second sentence happens despite the first, yet the widening happens because of it (misconception: formal-sounding contrast fits anywhere).","C":"''For instance'' would introduce an example of models disagreeing, but the sentence reports the center''s response instead (misconception: example word for consequences).","D":"Correct: the widened cone is the direct consequence of the models'' disagreement, which this connector signals."}', 'The second sentence is the **consequence** of the first, so a cause-and-effect connector is required.', 'The second sentence does re-describe the situation in new terms, making a restatement connector feel plausible until the action-versus-rephrasing distinction is checked.', '1) Summarize the first sentence and the second sentence separately. 2) Ask: does sentence two repeat, oppose, illustrate, or follow from sentence one? 3) Pick the connector class matching that answer. 4) Test by reading the pair with a plain word like ''so'' or ''but.'' 5) Choose the option in that class.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0ec8f45b9028b6c6', 'act-english', 's-org', 5, 'A late frost destroyed half the orchard''s trees<u>; consequently,</u> the annual cider festival went on as planned.', 'Which transition matches the relationship between the frost and the festival?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; for example,","letter":"B"},{"is_no_change":false,"label":"; nevertheless,","letter":"C"},{"is_no_change":false,"label":"; in addition,","letter":"D"}]', 'C', '{"A":"''Consequently'' claims the festival happened BECAUSE of the frost — the frost worked against it.","B":"''For example'' would make the festival an instance of frost damage, which it isn''t.","C":"The festival proceeded DESPITE the destruction — ''nevertheless'' carries exactly that defiance.","D":"''In addition'' stacks the festival on top of the frost as more of the same; they pull opposite ways."}', 'Setback + outcome-despite-it = **nevertheless**, not a cause-effect transition.', '''Consequently'' sounds authoritative, and both sentences do describe real events in order.', 'Ask whether the second clause happens because of, despite, or alongside the first — then pick the transition that says so.', 'underlined-span-mc', '''Consequently'' sounds authoritative, and both sentences do describe r…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-117c48a1e211290f', 'act-english', 's-org', 5, 'Peregrine falcons treat high-rise ledges much as their ancestors treated sea cliffs. <u>Indeed,</u> several downtown pairs now fledge more chicks each season than pairs nesting on natural rock.', 'Which choice provides the most logical transition from the preceding sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In contrast,","letter":"B"},{"is_no_change":false,"label":"Otherwise,","letter":"C"},{"is_no_change":false,"label":"Meanwhile,","letter":"D"}]', 'A', '{"A":"Correct: the second sentence intensifies and confirms the first claim with striking evidence, exactly the job of ''Indeed.''","B":"''In contrast'' asserts opposition, but the chick data supports rather than opposes the ledges-as-cliffs claim (transition_false_contrast).","C":"''Otherwise'' sets up a what-if alternative, yet the second sentence describes what actually happens (transition_false_condition).","D":"''Meanwhile'' juxtaposes simultaneous scenes, but these sentences form a claim followed by its supporting evidence (transition_false_time)."}', 'The second sentence **confirms and amplifies** the first with evidence, which is precisely the relationship ''Indeed'' announces.', 'Because the second sentence compares city pairs with cliff pairs, many students misread the comparison as a contrast and reach for an opposition word.', '1) Summarize sentence one''s claim in your own words. 2) Ask what sentence two does to that claim: oppose it, result from it, illustrate it, or intensify it. 3) Match the transition to that exact function. 4) Beware of surface comparisons that are actually support. 5) Re-read the pair with your transition to confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1e22163f8445836f', 'act-english', 's-org', 5, 'The essay''s introduction promises to explain ''why the bridge failed and how the city rebuilt trust.'' The first body paragraph covers the engineering flaw. <u>The mayor enjoys sailing on weekends.</u>', 'Which choice best begins the second body paragraph so it fulfills the introduction''s promise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"To restore public confidence, the city held open hearings and published every inspection report.","letter":"B"},{"is_no_change":false,"label":"The bridge''s steel came from three different suppliers.","letter":"C"},{"is_no_change":false,"label":"Engineering degrees take four years to complete.","letter":"D"}]', 'B', '{"A":"The mayor''s hobby is irrelevant to both halves of the essay''s promise.","B":"Rebuilding trust through hearings and transparency delivers the second promised topic.","C":"Steel suppliers extend the engineering-flaw topic, not the trust half.","D":"How long degrees take is unrelated to either promised subject."}', 'The introduction promised two topics; body two must cover the **second one — rebuilding trust**.', 'Option C stays on bridges, so it feels on-topic even though it repeats paragraph one''s theme.', 'Track the essay''s stated plan; each paragraph must deliver the part it''s responsible for.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-30f0b4f327b5648a', 'act-english', 's-org', 5, '[1] Sourdough rises without commercial yeast because wild microbes colonize the flour-and-water starter. [2] Lactic acid bacteria and native yeasts settle in, feeding on sugars and releasing gas and tangy acids. [3] Feeding the starter daily keeps this community balanced and vigorous. [4] Shaping the dough is a separate craft altogether. [5] The baker folds and tensions the loaf to build a skin that traps the gas the microbes produce. [6] A well-shaped loaf holds its dome instead of spreading flat.', 'The writer wants to divide this passage into two paragraphs so that each covers a distinct stage. Where should the new paragraph begin?', '[{"is_no_change":false,"label":"At sentence 3","letter":"A"},{"is_no_change":false,"label":"At sentence 4","letter":"B"},{"is_no_change":false,"label":"At sentence 5","letter":"C"},{"is_no_change":false,"label":"At sentence 6","letter":"D"}]', 'B', '{"A":"Premature break: sentence 3 still concerns the microbial starter, so splitting here divides one topic in two.","B":"Correct: sentences 1–3 cover the living starter, while sentence 4 explicitly turns to shaping, a distinct stage — the natural fault line.","C":"Late break: sentence 4 already announces the shift to shaping, so beginning the new paragraph at 5 orphans that topic sentence.","D":"Too late: sentence 6 merely concludes the shaping discussion, leaving the shaping topic sentence stranded above the break."}', 'A new paragraph should start where the **topic changes**, and sentence 4 openly pivots from the microbial starter to the craft of shaping.', 'Sentence 5 gives the vivid, concrete details of shaping, so it feels like where the ''real'' new topic begins.', '1) Label each sentence with its subtopic. 2) Find the exact sentence where the subtopic first changes. 3) The new paragraph begins with that pivoting sentence, not the one after it. 4) Confirm the sentence before the break still fits the first subtopic. 5) Confirm the break does not separate a topic sentence from its supporting details.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-337c5aa0576af6c9', 'act-english', 's-org', 5, '[1] Auditions for the spring musical draw students from every grade. [2] Each hopeful sings sixteen bars and reads a short scene with a partner. [3] The cast list appears on the callboard the following Friday. [4] Directors also note how quickly performers adjust when given new directions mid-scene. [5] By first bell that morning, a crowd has already gathered around the posting.', 'The writer wants Sentence 4 to appear where it will most logically support the paragraph''s account of the audition process. Sentence 4 should be placed:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"before Sentence 1.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 5.","letter":"D"}]', 'C', '{"A":"In its current spot the sentence rewinds from results day back to the tryout, splitting the callboard narrative (placement_interrupts_sequence).","B":"''Also'' signals an added observation, so the sentence cannot lead before any first observation exists (placement_also_first).","C":"Correct: the sentence describes what directors watch during auditions, so it belongs with the audition activities, right after the singing and scene reading.","D":"Ending with it strands an audition-day detail after the results are posted, forcing the timeline backward at the close (placement_after_resolution)."}', 'The word **''also''** marks the sentence as a companion to the audition activities, so it must sit beside the singing and scene-reading it extends, before the results appear.', 'Leaving the sentence where it is tempts students because ''Directors'' seems to follow naturally from the cast list they create, masking the backward jump in time.', '1) Split the paragraph into phases (here: the tryout, then the posting). 2) Decide which phase the movable sentence describes. 3) Check its signal words (''also'') for what must come before it. 4) Try each slot and reread for time jumps. 5) Keep the slot where the timeline never runs backward.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3b8c3beb27d37e48', 'act-english', 's-org', 5, '[1] In the summer of 1940, the deck of the Tacoma Narrows Bridge rippled so visibly in the wind that locals nicknamed it Galloping Gertie. [2] Engineers of the era judged the rolling motion harmless. [3] On November 7, a steady forty-mile-per-hour wind twisted the deck until it tore apart. [4] Drivers had reported feeling seasick as they crossed the undulating span. [5] After the collapse, wind-tunnel testing became a standard step in long-span design.', 'The writer wants Sentence 4 placed so that the paragraph''s account unfolds in logical order. Which placement best accomplishes that goal?', '[{"is_no_change":false,"label":"Where it is now","letter":"A"},{"is_no_change":false,"label":"After Sentence 1","letter":"B"},{"is_no_change":false,"label":"Before Sentence 1","letter":"C"},{"is_no_change":false,"label":"After Sentence 5","letter":"D"}]', 'B', '{"A":"Leaves a pre-collapse anecdote wedged between the collapse and its aftermath, forcing readers to jump backward in time (misconception: placement_ignores_flashback).","B":"The drivers'' seasickness belongs with the description of the rippling deck, before engineers dismiss the motion and long before the failure.","C":"The phrase ''the undulating span'' and the past-perfect ''had reported'' both require the bridge and its motion to be introduced first (misconception: placement_before_referent).","D":"Ends the paragraph on a stray pre-collapse detail after the account has already reached its industry-wide conclusion (misconception: placement_after_conclusion)."}', 'The **past-perfect** ''had reported'' marks an event from the rippling period, so the sentence must sit with the description of the deck''s motion, before the engineers'' judgment and the failure.', 'The current position feels acceptable because ''had reported'' technically signals earlier time, so students assume the flashback is intentional rather than disruptive.', '1) Time-stamp every sentence: before the failure or after it. 2) Note pointing phrases (like ''the undulating span'') that need earlier referents. 3) Place the movable sentence after its referents appear and within its own time period. 4) Reread the paragraph start to finish to confirm no backward jumps remain.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3c14c7963f66bad2', 'act-english', 's-org', 5, 'The seed library lends out more than four hundred packets every spring, trusting borrowers to grow the plants and return fresh seed in the fall. <u>Accordingly,</u> fewer than sixty packets typically come back.', 'Which choice best expresses the relationship between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In the same way,","letter":"B"},{"is_no_change":false,"label":"Nevertheless,","letter":"C"},{"is_no_change":false,"label":"For instance,","letter":"D"}]', 'C', '{"A":"False cause: ''Accordingly'' treats the meager returns as the natural result of lending on trust, when they actually defeat the expectation that trust creates.","B":"Wrong direction: the second sentence punctures the generous picture in the first rather than extending it.","C":"Correct: the library trusts borrowers to return seed, yet very little comes back — a concessive contrast.","D":"The low return count is not an example of lending four hundred packets; it is the disappointing aftermath."}', 'The first sentence builds an expectation of returned seed that the second sentence **defeats**, so a concessive contrast word is required.', 'Because both sentences track the same lend-and-return cycle, students read the second as a logical outcome of the first and accept the causal connector.', '1) Paraphrase sentence one and name the expectation it sets up. 2) Paraphrase sentence two and ask: does it fulfill that expectation, defeat it, cause it, or illustrate it? 3) Pick the transition family that matches — result, similarity, concession, or example. 4) Reread both sentences with your pick inserted and confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-43413fcd8a956d76', 'act-english', 's-org', 5, '[1] Corliss Park opened in 1951 as the summer home of the Ridgeline Miners. [2] Its hand-painted outfield signs advertise businesses that closed decades ago. [3] Generations of fans learned to keep score in its shaded grandstand. [4] Even the park''s oddities, like the flagpole standing in fair territory, became beloved. [5] Next spring, contractors will begin a two-year modernization of the property. [6] The flagpole will be relocated beyond a rebuilt outfield wall, and the signs will be preserved behind glass. [7] Club officials insist the grandstand''s character will survive the upgrade.', 'The writer wants to divide this paragraph into two paragraphs, the first about the park''s past and the second about its future. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2.","letter":"A"},{"is_no_change":false,"label":"Sentence 3.","letter":"B"},{"is_no_change":false,"label":"Sentence 4.","letter":"C"},{"is_no_change":false,"label":"Sentence 5.","letter":"D"}]', 'D', '{"A":"Breaks after a single opening fact, stranding the rest of the history in the future-focused paragraph (division_too_early).","B":"Fan memories in the grandstand are still past-focused, so a break there splits the history in two (division_mid_topic).","C":"Sentence 4 continues cataloging cherished old features; ''Even'' extends the list rather than pivoting (division_false_pivot).","D":"Correct: ''Next spring'' is the first look ahead, so the future-focused paragraph begins there."}', 'The **time frame** flips from past to future exactly at ''Next spring,'' making that sentence the natural start of the second paragraph.', 'The word ''Even'' at Sentence 4 feels like a rhetorical turn, so students mistake an extension of the list for a change of topic.', '1) Label each sentence with its time frame or subtopic. 2) Find the first sentence whose label differs from everything preceding it. 3) Confirm every sentence past that point shares the new label. 4) Begin the new paragraph at that sentence. 5) Re-read both halves to verify each is unified.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-53251f8e8ebc6fea', 'act-english', 's-org', 5, 'Elite marathoners rarely race the full distance more than twice a year. <u>Indeed,</u> some champions space their marathons a year or more apart, treating each buildup as its own season.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"However,","letter":"B"},{"is_no_change":false,"label":"In the meantime,","letter":"C"},{"is_no_change":false,"label":"On the other hand,","letter":"D"}]', 'A', '{"A":"Correct: ''Indeed'' signals intensification, and the second sentence strengthens the first claim with an even more extreme case.","B":"''However'' announces a reversal, but the second sentence confirms rather than contradicts the first (contrast_for_intensifier).","C":"''In the meantime'' marks simultaneous events in some interval, a time relationship that does not exist between these sentences (temporal_misfit).","D":"''On the other hand'' sets up an opposing alternative, yet the champions'' scheduling is a stronger version of the same point (false_opposition)."}', 'The second sentence **amplifies** the first with a more extreme example, exactly the move an intensifying transition signals.', '''However'' tempts students who read ''a year or more apart'' as differing from ''twice a year'' instead of exceeding it in the same direction.', '1) Summarize sentence one. 2) Summarize sentence two. 3) Ask: does the second sentence oppose the first, exemplify it, follow it in time, or push it further? 4) Pick the connector class that matches that move. 5) Re-read the pair; if the second sentence is a stronger case of the first, an intensifier fits.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-56613d5d0dccbfa1', 'act-english', 's-org', 5, 'For three weeks, every instrument pointed to an eruption from the summit crater, and the observatory said so publicly. <u>Therefore,</u> the outbreak, when it finally came, tore open a fissure far down the volcano''s northern flank.', 'Which transition word best expresses the relationship between these two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Similarly,","letter":"B"},{"is_no_change":false,"label":"In other words,","letter":"C"},{"is_no_change":false,"label":"Nevertheless,","letter":"D"}]', 'D', '{"A":"''Therefore'' treats the flank eruption as the predicted outcome, but the eruption defied the summit forecast.","B":"The actual outbreak is not similar to the forecast; it departs from it.","C":"The second sentence does not restate the forecast in different words — it contradicts it.","D":"Correct: despite the confident forecast, the eruption broke the expectation, which calls for a concession."}', 'The eruption **defied** the forecast, so the transition must concede that the expected outcome failed to occur.', 'The first sentence builds a strong forecast, so a conclusion word feels like the natural payoff — until you notice the eruption happened in the wrong place.', '1) Ask what the first sentence leads the reader to expect. 2) Ask whether the second sentence fulfills or breaks that expectation. 3) Fulfilled → result word; broken → concession word; restated → clarification word. 4) Insert your choice and re-read for logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5fb24f294d04e4ec', 'act-english', 's-org', 5, '[1] The library''s newspaper archive stretches back to 1902. [2] For decades, its only copies existed on brittle rolls of microfilm. [3] A single balky reader machine offered the only way to view them. [4] Researchers can now search a century of headlines from home. [5] Last spring, a grant funded a high-speed scanner that converted every roll into searchable digital files.', 'The writer wants Sentence 4 placed so that the paragraph unfolds in logical order, with each development following the event that made it possible. The best placement for Sentence 4 is:', '[{"is_no_change":false,"label":"where it is now.","letter":"A"},{"is_no_change":false,"label":"after Sentence 5.","letter":"B"},{"is_no_change":false,"label":"after Sentence 1.","letter":"C"},{"is_no_change":false,"label":"before Sentence 1.","letter":"D"}]', 'B', '{"A":"In its current spot, the home-searching outcome appears before the scanning project that made it possible.","B":"Correct: the outcome logically follows the grant-funded digitization that produced it, closing the paragraph''s problem-to-solution arc.","C":"Moving it even earlier detaches ''now'' from both the old limitations and the change that explains it.","D":"Opening with the outcome strands ''now'' with no earlier situation to improve upon."}', 'An **effect must follow its cause**: remote searching only makes sense after the scanner has converted the microfilm.', 'Leaving the sentence where it is tempts students because it sits beside other sentences about access, masking the cause-effect reversal.', '1) Label each sentence as background, problem, change, or result. 2) Find the sentence that causes the moved sentence to be true. 3) Place the result directly after its cause. 4) Check that words like ''now'' have a clear before-picture earlier in the paragraph. 5) Re-read the paragraph in the new order.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6d5ecfc37274f748', 'act-english', 's-org', 5, 'A hand compositor who spotted a wrong letter could pluck it from the set line and drop in the correct sort within seconds. <u>Likewise,</u> a Linotype operator who caught an error had to melt down and recast the entire slug.', 'Which transition word or phrase best fits at this point in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"By contrast,","letter":"B"},{"is_no_change":false,"label":"In fact,","letter":"C"},{"is_no_change":false,"label":"As a result,","letter":"D"}]', 'B', '{"A":"''Likewise'' asserts the two workflows match, but one fix takes seconds while the other requires recasting an entire line.","B":"''By contrast'' correctly frames the Linotype''s laborious correction against the compositor''s quick swap.","C":"''In fact'' intensifies or confirms a prior claim, but the second sentence does not restate or sharpen the first.","D":"''As a result'' invents causation; the operator''s burden was not caused by the compositor''s ease."}', 'The sentences describe **opposite** correction workflows, so an opposition transition is required.', '''Likewise'' lures readers who notice the parallel structure — two workers spotting errors — and miss that the outcomes diverge.', '1) Identify the topic both sentences share. 2) Note what each sentence says about that topic. 3) Ask: same direction, opposite direction, cause, or emphasis? 4) Discard any transition whose direction disagrees with your answer. 5) Re-read the pair with the survivor to confirm the turn feels natural.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7ff7597c5ccd5c5b', 'act-english', 's-org', 5, 'The shop''s vintage denim sells within hours of reaching the rack. <u>Therefore,</u> the board games can sit untouched for a year.', 'Which transition best fits the logic of these sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Likewise,","letter":"B"},{"is_no_change":false,"label":"In other words,","letter":"C"},{"is_no_change":false,"label":"By contrast,","letter":"D"}]', 'D', '{"A":"Treats the second sentence as a conclusion drawn from the first, but slow-selling games do not follow logically from fast-selling denim.","B":"Signals similarity, yet the two sentences describe opposite sales fates.","C":"Claims the second sentence restates the first, but it introduces entirely new, opposing information.","D":"Correct: the sentences set fast-moving denim against stagnant board games, a relationship of direct opposition."}', 'The sentences pit one item''s quick sales against another''s slow sales, so the transition must signal **opposition**.', 'Both sentences discuss how merchandise sells, and that surface continuity makes a cause-effect or similarity word feel harmless.', '1) Summarize each sentence in five words. 2) Ask whether the second continues, opposes, restates, or results from the first. 3) Name the job of each transition option. 4) Keep only the option whose job matches your step-2 answer. 5) Re-read the pair to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8038162300faff8f', 'act-english', 's-org', 5, '[1] Five years ago, the market began accepting SNAP benefits through a token system. [2] Shoppers swipe a card at the information booth and receive wooden tokens to spend at any stall. [3] Vendors turn in the tokens for cash at the close of each market day. [4] At first, only a handful of farmers agreed to participate. [5] Today, every produce stand at the market accepts the tokens.', 'The writer wants to add the following sentence: "That hesitation faded once the first season''s sales figures were shared at a vendors'' meeting." To make the paragraph most logical, the sentence should be placed:', '[{"is_no_change":false,"label":"after Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 2.","letter":"B"},{"is_no_change":false,"label":"after Sentence 3.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'D', '{"A":"''That hesitation'' has nothing to refer to right after the program''s launch is announced (pointer_no_referent).","B":"Sentence 2 describes shoppers'' mechanics, not any reluctance the pointer phrase could name (placement_wrong_section).","C":"Tempting because it mentions vendors and money, but Sentence 3 describes routine redemption, not doubt (placement_word_match).","D":"Correct — ''That hesitation'' points to the handful of reluctant farmers, and its fading explains the final sentence''s turnaround."}', '''That hesitation'' needs a just-named reluctance — the **handful** of reluctant farmers — and its fading bridges directly to the paragraph''s final turnaround.', 'The redemption sentence mentions vendors and cash, which looks like a vocabulary match for a sentence about vendors'' sales figures.', '1) Circle the added sentence''s backward-pointing phrase (''That hesitation''). 2) Find the sentence that names a hesitation. 3) Place the addition immediately after it. 4) Check the forward link: does the next sentence continue the change? 5) Reject slots where the pointer has no referent, even if vocabulary overlaps.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-89f99a85aa3177e1', 'act-english', 's-org', 5, '[1] The Granville Public Library opened in 1908 with funds from a Carnegie grant. [2] Its limestone facade and oak reading tables made it the grandest building in the county. [3] Generations of farm families rode into town on Saturdays just to climb its wide front steps. [4] This year, a careful renovation is preparing the old building for its second century. [5] Crews are restoring the original skylights while adding ramps, elevators, and charging stations. [6] The county has promised that the reading tables, sanded and resealed, will remain exactly where they have always stood.', 'The writer wants to divide this paragraph into two paragraphs, the first focused on the library''s early history and the second on its current renovation. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 3.","letter":"A"},{"is_no_change":false,"label":"Sentence 4.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 6.","letter":"D"}]', 'B', '{"A":"Sentence 3 still narrates the library''s early decades, so cutting there drags history into the renovation paragraph.","B":"Correct: ''This year'' pivots the paragraph from past grandeur to the present-day project, so the shift begins there.","C":"Sentence 5 continues renovation details begun in Sentence 4, so cutting there strands the pivot with the history.","D":"Sentence 6 is the renovation discussion''s closing promise; starting there leaves most of the project in the history paragraph."}', 'A paragraph break belongs at the **first sentence of the new topic**, and the ''This year'' sentence is where the time period shifts.', 'The sentence about crews and skylights sounds like fresh action, so students cut there even though the pivot was announced one sentence earlier.', '1) Label each sentence with its topic or time period. 2) Find where the labels switch. 3) Begin the new paragraph at the first sentence carrying the new label. 4) Verify each resulting paragraph is single-topic. 5) Re-read both paragraphs to confirm neither strands a sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-98e39f81c158b40a', 'act-english', 's-org', 5, '[1] Ikat weavers dye their patterns into the threads before any cloth exists. [2] Bundles of warp yarn are bound tightly with resist ties, dipped in dye, and rebound for each additional color. [3] When the finished threads are finally stretched on the loom, the design emerges with the softly blurred edges that mark true ikat. [4] Selling those textiles fairly is a separate struggle. [5] Because the process is slow, genuine ikat costs far more than the printed imitations that crowd souvenir stalls. [6] Cooperatives in Uzbekistan now attach certification tags so that buyers can tell dyed thread from surface printing.', 'The writer wants to divide this paragraph into two paragraphs, the first describing the ikat dyeing process and the second addressing the challenge of selling ikat honestly. The best place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 3","letter":"A"},{"is_no_change":false,"label":"Sentence 4","letter":"B"},{"is_no_change":false,"label":"Sentence 5","letter":"C"},{"is_no_change":false,"label":"Sentence 6","letter":"D"}]', 'B', '{"A":"Sentence 3 completes the process description; splitting there severs the loom step from the dyeing it depends on.","B":"Correct: Sentence 4 pivots from how ikat is made to how it is sold, announcing the second topic.","C":"Starting at Sentence 5 strands the pivot sentence about selling at the end of the process paragraph.","D":"Sentence 6 continues the market discussion already underway, so a break there splits the second topic in half."}', 'Sentence 4 is the **pivot**: it closes the process topic and explicitly opens the marketplace topic.', 'Sentence 5 tempts because it starts with ''Because'' and sounds like a fresh explanation, but the market topic actually opens one sentence earlier.', '1) Label each sentence with its topic in one or two words. 2) Find where the labels change. 3) Begin the new paragraph at the first sentence of the new topic. 4) Check that neither resulting paragraph contains a sentence belonging to the other topic.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-993e51faa7a5ba14', 'act-english', 's-org', 5, 'The essay opens with the image of the lighthouse dark and boarded up. It then recounts the two-year volunteer restoration. <u>Fundraising for the restoration ended in June.</u>', 'The writer wants a conclusion that returns to the essay''s opening image of the lighthouse. Which choice accomplishes this?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Many coastal towns face similar budget shortfalls.","letter":"B"},{"is_no_change":false,"label":"Today the restored beacon sweeps the bay each night, just as it did in 1902.","letter":"C"},{"is_no_change":false,"label":"The preservation committee will meet again next spring.","letter":"D"}]', 'C', '{"A":"A fundraising date is administrative housekeeping — it never looks back at the lighthouse.","B":"Other towns'' budgets point AWAY from this essay''s subject entirely.","C":"The lit beacon sweeping the bay answers the opening''s dark, boarded-up tower — the frame closes.","D":"A future meeting is logistics, not imagery."}', 'A framing conclusion must **revisit the opening image** — dark tower then, lit beacon now.', 'Factually true closers feel legitimate even when they ignore the stated goal.', 'When the stem names the writer''s goal, eliminate every choice that doesn''t perform it — truth alone doesn''t qualify.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9ecce8513dec92cc', 'act-english', 's-org', 5, 'Throughout the memoir, the author returns to the image of her mother''s hands kneading dough. The final chapter should, the writer decides, close on that same image. <u>The author later moved to a different city for work.</u>', 'Which choice best ends the memoir by returning to its central image?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Her mother had always wanted her to attend college.","letter":"B"},{"is_no_change":false,"label":"Now, flouring her own counter at dawn, she feels her mother''s hands guiding hers.","letter":"C"},{"is_no_change":false,"label":"The old family recipes were written on index cards.","letter":"D"}]', 'C', '{"A":"Moving cities for work drops the kneading-hands image entirely.","B":"College is a new topic, not a return to the central image.","C":"It revisits the mother''s hands and the dough, closing the memoir on its recurring image.","D":"Index cards touch on recipes but abandon the hands-kneading-dough motif."}', 'When the goal is to **return to a central image**, choose the option that revives it — the hands and dough.', 'Recipe cards (D) sit near the cooking theme, so they feel like a callback.', 'A callback conclusion must reawaken the specific image named, not merely the general subject.', 'underlined-span-mc', 'recipe cards (D) sit near the cooking theme, so they feel like a call…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9f104eddac2ff7ae', 'act-english', 's-org', 5, 'The op-ed argues that the city should fund after-school programs. It cites falling test scores, rising afternoon crime, and working parents'' scheduling struggles. <u>The stadium''s new scoreboard cost eight million dollars.</u>', 'The writer wants each piece of evidence to support the case for after-school funding. The underlined sentence should be:', '[{"is_no_change":false,"label":"KEPT, because it shows the city has money to spend","letter":"A"},{"is_no_change":false,"label":"KEPT, because stadiums are popular with students","letter":"B"},{"is_no_change":false,"label":"DELETED, because it does not support the case for after-school programs","letter":"C"},{"is_no_change":false,"label":"DELETED, because it belongs in the introduction instead","letter":"D"}]', 'C', '{"A":"The scoreboard''s cost is a budgeting aside; it doesn''t argue that after-school programs are needed.","B":"Stadium popularity says nothing about the need for after-school programs.","C":"The sentence drifts from the op-ed''s evidence chain (scores, crime, schedules) and should be cut.","D":"Moving an irrelevant sentence to the introduction doesn''t make it relevant."}', 'Evidence must **support the specific claim**; the scoreboard cost doesn''t, so delete it.', '''The city has money'' feels like a supporting point, but it''s a separate spending debate.', 'Keep only evidence that advances the exact argument; cut tangents even if loosely budget-related.', 'underlined-span-mc', '''The city has money'' feels like a supporting point, but it''s a separa…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-cbd3325cb0fd4832', 'act-english', 's-org', 5, 'Sentence 1: The renovation preserved the theater''s original plaster ceiling. Sentence 2: Crews reinforced it with hidden steel before the reopening gala. The writer wants to add: ''The ornate medallions had survived a century of leaks.'' <u>This sentence would best be placed after sentence 2.</u>', 'Where should the new sentence about the surviving medallions be placed?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Before sentence 1","letter":"B"},{"is_no_change":false,"label":"Between sentences 1 and 2","letter":"C"},{"is_no_change":false,"label":"The sentence should not be added at all.","letter":"D"}]', 'C', '{"A":"After sentence 2, the medallion detail interrupts the jump from reinforcement to the gala.","B":"Before sentence 1, the medallions are mentioned before the ceiling they belong to is introduced.","C":"Between 1 and 2, the medallion detail elaborates the just-named ceiling before crews reinforce it.","D":"The detail is relevant and vivid, so it should be added, not dropped."}', 'A supporting detail belongs **right after the idea it elaborates** — the ceiling in sentence 1.', 'Placing new information last feels safe, but here it breaks the ceiling-to-reinforcement flow.', 'Insert a detail next to the sentence it develops, keeping the paragraph''s logical order intact.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d4b63e84b9c4b074', 'act-english', 's-org', 5, '[1] For years, the observatory''s monthly open houses drew the same small circle of hobbyists. [2] Attendance rarely topped thirty, even on the clearest nights. [3] Most visitors already owned telescopes and came mainly to compare eyepieces. [4] In 2022, the hiring of a full-time outreach coordinator changed the audience almost overnight. [5] School groups began booking weekday tours, and family attendance tripled within a year. [6] Last October, a single open house drew more visitors than the entire previous season had.', 'The writer wants to divide this paragraph into two, so that the first paragraph describes the open houses'' past and the second describes their recent transformation. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 3.","letter":"A"},{"is_no_change":false,"label":"Sentence 4.","letter":"B"},{"is_no_change":false,"label":"Sentence 5.","letter":"C"},{"is_no_change":false,"label":"Sentence 6.","letter":"D"}]', 'B', '{"A":"Sentence 3 still gives evidence about the old, small audience, so breaking there splits the ''past'' material in two.","B":"Correct: Sentence 4 announces the turning point—the 2022 hire—so the second paragraph opens exactly where the transformation begins.","C":"Sentence 5 reports results of the change; starting there strands the pivotal cause at the bottom of the first paragraph.","D":"Sentence 6 is the culminating example of the transformation, not a new topic, and would leave a one-sentence paragraph."}', 'A paragraph break belongs at the **topic shift**, and the shift from the old era to the transformation happens when the new hire is announced.', 'Starting at the tripled attendance tempts students because it sounds like the ''new era,'' but that sentence gives effects whose cause would be stranded in the first paragraph.', '1) Label each sentence ''old situation'' or ''new situation.'' 2) Find the first sentence labeled ''new''—usually the one announcing a change, date, or cause. 3) Break immediately before it. 4) Verify both halves: the first should be complete about the old situation, and the second should begin with the turn, not with its aftermath.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e13d59b84ad97892', 'act-english', 's-org', 5, 'Bebop''s architects wrote angular themes at tempos far too fast for a comfortable dance step, and their long solos ignored the tidy formulas that had kept ballroom crowds happy. <u>Similarly,</u> many ballroom operators trimmed their live bookings, complaining that the new style left dance floors empty.', 'Which choice provides the most logical transition between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Nevertheless,","letter":"B"},{"is_no_change":false,"label":"For instance,","letter":"C"},{"is_no_change":false,"label":"Consequently,","letter":"D"}]', 'D', '{"A":"transition_false_parallel: *Similarly* claims the operators'' retreat resembles the musicians'' innovations, but the sentences are cause and effect, not parallel cases.","B":"*Nevertheless* would mean operators cut bookings despite the undanceable music — the opposite of the actual logic.","C":"*For instance* misfiles the booking cuts as an example of bebop''s musical traits rather than a reaction to them.","D":"Correct: the booking cuts followed directly from the music''s turn away from dancers."}', 'The operators'' retreat is the direct **effect** of the music abandoning danceability.', 'Both sentences describe rejections of the old ballroom order, so *Similarly* feels superficially apt even though the logic is causal.', '1) Summarize each sentence in five words. 2) Ask which single question the second sentence answers about the first: So what happened? Despite that? Such as what? Just like what? 3) Match the transition to that question. 4) Plug it in and test the logic aloud.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e2ed6e786b2cbac1', 'act-english', 's-org', 5, '[1] Urban peregrine falcons treat skyscrapers as substitute cliffs. [2] A window ledge forty stories up mimics the rocky shelf where the species has always nested. [3] Pigeons, abundant in every downtown, supply the hunters with a steady food source. [4] City biologists, delighted by the arrangement, band dozens of falcon chicks on office towers each spring.', 'The writer wants to add the following sentence to the paragraph: ''These city menus differ little from the pigeon-heavy diets of wild falcons on remote cliffs.'' For the sake of logic and cohesion, the sentence should be placed:', '[{"is_no_change":false,"label":"after Sentence 1.","letter":"A"},{"is_no_change":false,"label":"after Sentence 3.","letter":"B"},{"is_no_change":false,"label":"after Sentence 2.","letter":"C"},{"is_no_change":false,"label":"after Sentence 4.","letter":"D"}]', 'B', '{"A":"''These city menus'' has nothing to point back to — no food has been mentioned after the opening claim.","B":"Correct: it directly follows the pigeon sentence, so ''these city menus'' clearly refers to the food source just named.","C":"After the ledge sentence, the diet comparison interrupts the nesting discussion and precedes any mention of food.","D":"Parked after the banding sentence, the comparison trails the paragraph''s shift to fieldwork and sits far from the food idea it develops."}', 'The pointer phrase **''these city menus''** must immediately follow the sentence that introduces the pigeons as food.', 'The added sentence also mentions cliffs, tempting students to attach it to the cliff-and-ledge sentences early in the paragraph.', '1) Circle pointing words in the added sentence (''these,'' ''this,'' ''such''). 2) Find what they must refer back to. 3) Place the sentence immediately after that referent. 4) Re-read the paragraph to confirm no other idea is interrupted.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e91c9d6062a1cef1', 'act-english', 's-org', 5, '[1] For sixty years, the Ledger''s press run ended with a ritual: the night foreman inked his thumb and pressed it beside the masthead of the first copy off the press. [2] The smudged copies were never sold; they went onto a nail in the pressroom wall. [3] By the time the paper moved out, more than three thousand hung there in yellowing rows. [4] The building''s new owners planned to gut the pressroom for loft apartments. [5] When word spread, former carriers and pressmen drove in from three states to claim a thumbprinted copy. [6] Startled by the turnout, the developers agreed to frame two hundred of them in the lobby instead.', 'The writer wants to divide this paragraph into two paragraphs, separating the account of the pressroom ritual from the account of what happened after the paper moved out. The most logical place to begin the second paragraph is at:', '[{"is_no_change":false,"label":"Sentence 2","letter":"A"},{"is_no_change":false,"label":"Sentence 3","letter":"B"},{"is_no_change":false,"label":"Sentence 4","letter":"C"},{"is_no_change":false,"label":"Sentence 5","letter":"D"}]', 'C', '{"A":"Splits the ritual from its immediate result, stranding the thumbprinted copies one sentence into a new paragraph.","B":"Tempting because it mentions the move, but Sentence 3 still describes the collection''s growth — the ritual''s own story.","C":"Correct: Sentence 4 introduces the new owners and their plan, the first sentence that belongs wholly to the aftermath.","D":"Leaves the owners'' demolition plan attached to the ritual half, though it launches the aftermath."}', 'The topic genuinely **turns** when the new owners and their demolition plan enter; everything before that still portrays the tradition.', 'Sentence 3 tempts students because its opening time phrase mentions the move, even though its main clause still describes the tradition''s scale.', '1) State each half''s job from the stem. 2) Label every sentence with the half it serves, judging by its main clause. 3) Find where the labels flip and stay flipped. 4) Begin the new paragraph at the first sentence of the second job. 5) Re-read both halves to confirm each is self-contained.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f245ad8cc1e1c748', 'act-english', 's-org', 5, 'Silent-era film clubs recorded dozens of Deaf lecturers so that distant audiences could watch celebrated signers. <u>Indeed,</u> several regional signs from the 1910s survive today only because those reels were preserved in university archives.', 'Which choice provides the most logical transition in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"On the other hand,","letter":"B"},{"is_no_change":false,"label":"In the meantime,","letter":"C"},{"is_no_change":false,"label":"Granted,","letter":"D"}]', 'A', '{"A":"Correct — the second sentence intensifies and confirms the first, exactly the emphasis ''indeed'' signals.","B":"''On the other hand'' announces a contrast, but the second sentence extends the first rather than opposing it.","C":"''In the meantime'' imposes a simultaneous-time frame the sentences do not share; the second spans a century of preservation.","D":"''Granted'' concedes a point to an opposing argument, but no counterargument follows."}', 'The second sentence **reinforces** the first with a stronger, more specific claim, which is what ''indeed'' signals.', '''Granted'' attracts readers who sense the second sentence qualifies the first, though it actually amplifies it.', '1) Compress each sentence to its core claim. 2) Ask whether the second claim opposes, exemplifies, results from, or intensifies the first. 3) Match the transition to that relationship. 4) Confirm by deleting the transition: the surviving logic should equal the relationship you named.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-34265d79953a3867', 'act-english', 's-punc', 1, 'The camping checklist included a tent<u> a lantern matches</u> and a first-aid kit.', 'Which choice punctuates the items in the series correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; a lantern; matches;","letter":"B"},{"is_no_change":false,"label":", a lantern matches,","letter":"C"},{"is_no_change":false,"label":", a lantern, matches,","letter":"D"}]', 'D', '{"A":"With no commas, four separate supplies blur into one unreadable run.","B":"Semicolons separate series items only when the items already contain commas.","C":"This leaves ''a lantern matches'' fused into one item — a lantern isn''t a kind of match.","D":"Commas separate each item in the series of four supplies."}', 'Commas separate **every item** in a simple series.', 'Short items read fast aloud, so the missing commas are easy to skate past.', 'In a series of three or more, put a comma after each item except the last.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-48ea13424888c8b4', 'act-english', 's-punc', 1, 'My grandparents moved to Tucson<u> Arizona on March 4 1998</u> after the bakery closed.', 'Which choice punctuates the place and date correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", Arizona, on March 4, 1998,","letter":"B"},{"is_no_change":false,"label":", Arizona on March 4, 1998","letter":"C"},{"is_no_change":false,"label":", Arizona, on March 4 1998,","letter":"D"}]', 'B', '{"A":"City-state pairs and day-year pairs both need commas to stay readable.","B":"Commas set off the state and the year on both sides — the full convention.","C":"The state needs a comma on BOTH sides, and the year needs its closing comma too.","D":"The state is handled, but the day and year are left fused."}', 'State names and years act like interrupters: **commas on both sides**.', 'The single comma before ''Arizona'' looks like it is already doing the job.', 'City, State, ... and Month Day, Year, ... — the state and the year each take a closing comma.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7298364b2f453526', 'act-english', 's-punc', 1, '<u>Fiddles, banjos, and dulcimers</u> crowded the little stage before the first workshop of the weekend began.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Fiddles banjos, and dulcimers","letter":"B"},{"is_no_change":false,"label":"Fiddles, banjos and, dulcimers","letter":"C"},{"is_no_change":false,"label":"Fiddles, banjos, and, dulcimers","letter":"D"}]', 'A', '{"A":"Correct: a three-item series takes a comma after each item before the conjunction, exactly as written.","B":"Dropping the comma between the first two items fuses them into one unpunctuated pair.","C":"Sliding the comma after ''and'' splits the conjunction from the item it introduces.","D":"Adding a comma after ''and'' inserts punctuation where nothing needs separating."}', 'A simple **series** of three items is punctuated item-comma-item-comma-conjunction-item, which is what the original does.', '''Banjos and, dulcimers'' tempts students who feel a pause near the conjunction but misplace where the comma belongs.', '1) Count the items in the list. 2) Place a comma after each item except the last. 3) Keep the conjunction immediately before the final item with no comma after it. 4) Read the list aloud, pausing only at the commas, to confirm each item stays whole.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7d51b02b86f703a3', 'act-english', 's-punc', 1, 'Dozens of families showed up for the lunar eclipse, and the <u>visitors'' questions</u> kept both astronomers busy until well past midnight.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"visitor''s questions","letter":"B"},{"is_no_change":false,"label":"visitors questions","letter":"C"},{"is_no_change":false,"label":"visitors''s questions","letter":"D"}]', 'A', '{"A":"Correct: the questions belong to many visitors, so the plural possessive—apostrophe after the s—is right.","B":"Singular possessive contradicts the context, which describes dozens of families asking questions.","C":"Omitting the apostrophe leaves a bare plural jammed against a noun with no possessive relationship.","D":"Adding -''s to a plural that already ends in s doubles the possessive marking, which is nonstandard."}', 'With **many owners**, form the plural first (''visitors'') and then add only an apostrophe after the s.', 'The apostrophe-before-s version tempts students who apply the familiar singular pattern without counting the owners.', '1) Ask: can the phrase be rephrased as ''the ___ of the ___''? If yes, a possessive is needed. 2) Count the owners using context. 3) Write the correct singular or plural noun first. 4) Singular: add ''s. Plural ending in s: add only the apostrophe. 5) Re-read to confirm the mark matches the count.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97b889df000bce17', 'act-english', 's-punc', 1, 'To restore the stone arch, the crew ordered <u>granite blocks steel pins, and oak scaffolding</u> from suppliers across the state.', 'Which choice makes the sentence conform to standard punctuation conventions?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"granite blocks, steel pins and, oak scaffolding","letter":"B"},{"is_no_change":false,"label":"granite blocks, steel pins, and oak scaffolding","letter":"C"},{"is_no_change":false,"label":"granite blocks steel pins and oak scaffolding","letter":"D"}]', 'C', '{"A":"Omits the comma between the first two items, fusing ''granite blocks steel pins'' into one garbled item (misconception: series_missing_first_comma).","B":"Places a comma after ''and'' instead of before it, splitting the conjunction from its item (misconception: series_comma_after_conjunction).","C":"Separates all three items with commas, with the final comma correctly before ''and.''","D":"Drops all series commas, leaving readers to guess where each material ends (misconception: series_no_commas)."}', 'A series of three items needs a **comma after each item**, with the last comma placed before the conjunction.', 'The original looks nearly right because it has one correct comma, so students skim past the missing separator between the first two items.', '1) Count the items in the list. 2) If there are three or more, place a comma after each item except the last. 3) Check that the final comma sits before the conjunction, never after it. 4) Read each item alone to confirm none have fused together.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b030b960435cbfc8', 'act-english', 's-punc', 1, 'Every Saturday the display case fills with trays of <u>lemon bars, almond croissants, and, cinnamon knots</u> before the first customers arrive.', 'Which choice provides the most effective punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"lemon bars almond croissants and cinnamon knots","letter":"B"},{"is_no_change":false,"label":"lemon bars, almond croissants and, cinnamon knots","letter":"C"},{"is_no_change":false,"label":"lemon bars, almond croissants, and cinnamon knots","letter":"D"}]', 'D', '{"A":"Places a comma after ''and,'' splitting the conjunction from the final item (comma_after_and).","B":"Runs the three items together with no separating commas at all (series_no_commas).","C":"Drops the comma before ''and'' and inserts one after it, misplacing the pause (comma_misplaced_and).","D":"Correct — commas separate the items, with the final comma placed before ''and,'' not after it."}', 'In a series, commas go **between** items — including one just before the conjunction — never after ''and.''', 'Students who hear a pause around ''and'' sometimes attach the comma to the wrong side of the conjunction.', '1) Count the items in the list. 2) Place a comma after each item except the last. 3) Keep the final comma before the conjunction. 4) Make sure no comma follows ''and'' itself. 5) Reread the list rhythm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bc7a20df8a0aa75d', 'act-english', 's-punc', 1, 'The shaded oasis sheltered <u>date palms tall reeds and</u> restless flocks of migrating songbirds.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"date palms, tall reeds and","letter":"B"},{"is_no_change":false,"label":"date palms tall reeds, and","letter":"C"},{"is_no_change":false,"label":"date palms, tall reeds, and","letter":"D"}]', 'D', '{"A":"Runs three list items together with no commas at all (missing_series_commas).","B":"Separates the first two items but drops the comma before ''and,'' leaving the series incomplete (missing_serial_comma).","C":"Places a single comma before ''and'' but fails to divide the first two items (misplaced_series_comma).","D":"Correct: commas separate all three items of the series, including the one before ''and.''"}', 'A list of three or more items needs a **comma between each item**, including before the final ''and.''', 'The version with a comma only before ''and'' looks tidy, so students accept it even though the first two items still run together.', '1) Count the items in the list (here: palms, reeds, songbirds). 2) If three or more, put a comma after every item except the last. 3) Include the comma before the closing ''and.'' 4) Make sure no two items are jammed together without a comma. 5) Re-read the series to hear each item stand apart.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bcdaec35e37af3f0', 'act-english', 's-punc', 1, 'The pastry chef sharpened all of her <u>knive''s</u> before the dinner service began.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"knifes","letter":"B"},{"is_no_change":false,"label":"knifes''","letter":"C"},{"is_no_change":false,"label":"knives","letter":"D"}]', 'D', '{"A":"Apostrophe error: the word is a simple plural, not a possessive, so no apostrophe belongs.","B":"Wrong plural form: ''knife'' pluralizes to ''knives,'' not ''knifes.''","C":"Double error: it uses the wrong plural stem and adds a possessive apostrophe the sentence does not need.","D":"Correct: the sentence needs the plain plural of ''knife,'' which is ''knives,'' with no apostrophe."}', 'The chef sharpened more than one knife — a **plain plural** — so the correct form is ''knives'' with no apostrophe.', 'Writers often reach for an apostrophe whenever a word ends in -s, mistaking every -s ending for a possessive.', '1) Ask whether the word shows ownership or just names more than one thing. 2) If it merely counts more than one, use a plain plural with no apostrophe. 3) For nouns ending in -fe, change the ending to -ves. 4) Reserve the apostrophe for possession or contraction. 5) Reread to confirm nothing is being owned.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d06343fd36d5d21f', 'act-english', 's-punc', 1, 'Before the house opens, ushers <u>stack programs, check the aisle lights, and prop</u> open the lobby doors.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stack programs check the aisle lights and prop","letter":"B"},{"is_no_change":false,"label":"stack programs, check the aisle lights and, prop","letter":"C"},{"is_no_change":false,"label":"stack programs; check the aisle lights; and prop","letter":"D"}]', 'A', '{"A":"Correct: a series of three actions takes commas between the items, including one before the conjunction.","B":"Removing all commas fuses three separate tasks into one unreadable string (series_no_commas).","C":"A comma placed after ''and'' splits the conjunction from the final item it introduces (comma_after_conjunction).","D":"Semicolons separate list items only when the items themselves contain commas, which these simple phrases do not (semicolon_simple_series)."}', 'A **series** of three or more actions takes commas between its items, exactly as the original punctuates them.', 'The semicolon version tempts students who believe stronger punctuation is always more formal, even though semicolons are reserved for items with internal commas.', '1) Count the actions or items in the list. 2) If there are three or more, place a comma after each item except the last. 3) Keep the comma before the conjunction, never after it. 4) Upgrade to semicolons only if the items themselves contain commas. 5) Reread to confirm each item stays distinct.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0411455b80be2a03', 'act-english', 's-punc', 2, 'The station''s chief meteorologist<u>, a veteran of twenty storm seasons</u> rarely raises her voice on air, even when the radar map turns solid red.', 'Which choice correctly punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a veteran of twenty storm seasons","letter":"B"},{"is_no_change":false,"label":", a veteran of twenty storm seasons,","letter":"C"},{"is_no_change":false,"label":"a veteran of twenty storm seasons,","letter":"D"}]', 'C', '{"A":"Opens the aside with a comma but never closes it, leaving the interrupter half-fenced (misconception: one comma is enough for an aside).","B":"Removes both commas, welding the appositive onto the main clause as if ''meteorologist a veteran'' were one noun (misconception: short asides need no commas).","C":"Correct: the appositive is extra, droppable information, so it takes a comma on each side.","D":"Fences only the back end of the aside (misconception: commas placed by pause rather than by structure)."}', 'A nonrestrictive appositive needs **paired commas** — one before it and one after it.', 'The single opening comma matches where readers naturally pause, so the missing closing comma slips past unnoticed.', '1) Find the phrase that renames the noun. 2) Test: can you lift it out and still have a full sentence? 3) If yes, it is extra information. 4) Fence extra information with a comma on both sides — never just one. 5) Re-read the sentence without the phrase to confirm it still works.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-22e120fbf3a3059e', 'act-english', 's-punc', 2, 'By eight in the morning, shoppers were filling their baskets with <u>peaches, plums, and early apples</u> from the orchard stands.', 'Which choice is correctly punctuated?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"peaches, plums and, early apples","letter":"B"},{"is_no_change":false,"label":"peaches plums, and early apples","letter":"C"},{"is_no_change":false,"label":"peaches, plums, and, early apples","letter":"D"}]', 'A', '{"A":"Correct — the three items are separated by commas, with the conjunction attached to the final item.","B":"Shifts a comma to follow the conjunction, splitting ''and'' from the item it introduces (comma_after_conjunction).","C":"Omits the comma between the first two items, fusing them together (series_missing_comma).","D":"Adds an extra comma after the conjunction where no boundary exists (series_extra_comma)."}', 'Items in a **series** take a comma after each item, with the conjunction staying attached to the final item.', 'Keeping a comma near ''and'' looks balanced, so students accept the version that pauses just after the conjunction.', '1) Count the items in the list. 2) Mark the boundary between each pair of items. 3) Put one comma at each boundary, before the conjunction. 4) Never put a comma directly after the conjunction. 5) Reread to confirm each item stands cleanly apart.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-26837f2de0130a64', 'act-english', 's-punc', 2, 'Loading film onto a steel reel takes real <u>practice; most</u> students fumble their first roll inside the changing bag.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"practice, most","letter":"B"},{"is_no_change":false,"label":"practice; although most","letter":"C"},{"is_no_change":false,"label":"practice, therefore most","letter":"D"}]', 'A', '{"A":"Correct: a semicolon legally joins the two independent clauses on either side of it.","B":"Joins two independent clauses with only a comma (comma_splice).","C":"Puts a dependent clause after the semicolon (semicolon_fragment), since ''although'' demotes the second clause.","D":"Uses a conjunctive adverb after a bare comma (comma_conjunctive_adverb_splice), which still leaves the clauses unjoined."}', 'Both halves are **independent clauses**, and a semicolon is a legal junction between two independent clauses.', 'The comma version matches the light pause students hear when reading, so the splice slips past anyone who trusts the ear over the clause test.', '1) Read each side of the mark alone and label it independent or dependent. 2) If both sides are independent, require a junction rated for that: strong stop or comma plus coordinating conjunction. 3) If a subordinating word appears, re-test the demoted side. 4) Reject any junction that leaves two independent clauses held by a comma alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2c480696c9673ed1', 'act-english', 's-punc', 2, 'The gas kiln finally hit cone ten just before <u>midnight; the</u> bleary-eyed crew celebrated with cocoa while the burners hissed down to silence.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"midnight, the","letter":"B"},{"is_no_change":false,"label":"midnight; and the","letter":"C"},{"is_no_change":false,"label":"midnight the","letter":"D"}]', 'A', '{"A":"Correct: a semicolon legally joins these two independent clauses.","B":"A comma alone between two independent clauses creates a comma splice.","C":"Stacking a semicolon with a coordinating conjunction doubles the connector at one seam (redundant joining).","D":"No punctuation at all fuses the two clauses into a run-on."}', 'A **semicolon** is a full-strength weld between two independent clauses.', 'The comma feels natural because the clauses are short and closely related, which is exactly how splices sneak past the ear.', '1) Test each half: could it stand alone as a sentence? 2) If both halves pass, the seam needs a period, a semicolon, or a comma plus a coordinating conjunction. 3) Reject a lone comma. 4) Reject a bare gap. 5) Reject doubled connectors doing the same job twice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3a1b53fce3a96f39', 'act-english', 's-punc', 2, 'After three straight weekends of tryouts and scrimmages<u> the</u> coach finally posted the roster.', 'Which choice punctuates the sentence''s opening correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":": the","letter":"B"},{"is_no_change":false,"label":"; the","letter":"C"},{"is_no_change":false,"label":", the","letter":"D"}]', 'D', '{"A":"A long opening phrase runs straight into the main clause without a marked boundary.","B":"A colon needs a complete statement before it, and the opener isn''t one.","C":"A semicolon needs a complete clause on its left — the opener has no verb.","D":"A comma after the long introductory phrase shows where the main clause begins."}', 'A **long introductory phrase** takes a comma before the main clause begins.', 'Openers without verbs feel too small to deserve punctuation.', 'After a long opening phrase (four-plus words), set the main clause off with a comma.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-41fc759996b6afc0', 'act-english', 's-punc', 2, 'My grandfather stepped off the train in Chicago with twelve <u>dollars, he</u> spent half of it on a warm coat before nightfall.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"dollars, he then","letter":"B"},{"is_no_change":false,"label":"dollars; he","letter":"C"},{"is_no_change":false,"label":"dollars; because he","letter":"D"}]', 'C', '{"A":"Joins two independent clauses with only a comma — a comma splice.","B":"Adds the adverb ''then,'' which supplies timing but no grammatical connection, so the splice remains.","C":"Correct: a semicolon legally joins the two independent clauses.","D":"Puts a dependent ''because'' clause after a semicolon, which requires an independent clause on each side."}', 'A **semicolon** legally joins the two independent clauses that the comma alone spliced together.', 'Adding ''then'' feels like it links the actions in time, but an adverb has no power to join two complete sentences.', '1) Test each side of the mark: subject + verb + complete thought? 2) If both sides are independent, a bare comma is illegal. 3) Legal joins: period, semicolon, or comma + coordinating conjunction. 4) If a subordinator is added, confirm the logic is real and the punctuation still matches. 5) Pick the option using a legal join with sensible meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-60de89b4cdac5979', 'act-english', 's-punc', 2, 'Among the thousands of anemones scattered across the reef, a clownfish will settle only in the one <u>which</u> matches the chemical scent it memorized as a drifting larva.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"which,","letter":"B"},{"is_no_change":false,"label":", that","letter":"C"},{"is_no_change":false,"label":"that","letter":"D"}]', 'D', '{"A":"''Which'' introduces the clause here, but standard usage reserves ''which'' for nonrestrictive, extra-information clauses (misconception: which_for_restrictive).","B":"A comma after the relative pronoun severs it from its verb ''matches'' (misconception: comma_splits_pronoun_verb).","C":"The comma wrongly sets off a clause that is essential to identify which anemone (misconception: comma_before_restrictive).","D":"The essential clause pins down which single anemone the clownfish chooses, so it is restrictive and takes ''that'' with no comma."}', 'An essential clause that identifies **which** anemone is restrictive, so it uses ''that'' and no comma.', '''Which'' feels interchangeable with ''that,'' so students keep it even when the clause is essential.', '1) Decide whether the clause is needed to identify the noun. 2) If removing it would blur which thing is meant, the clause is restrictive. 3) Restrictive clauses take ''that'' and no comma. 4) Reserve ''which'' — and its comma — for clauses that merely add extra detail.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-624805558434ba37', 'act-english', 's-punc', 2, '<u>After the rain stopped birders, gathered</u> at the marsh boardwalk to look for rails.', 'Which choice correctly punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"After the rain, stopped birders gathered","letter":"B"},{"is_no_change":false,"label":"After the rain stopped, birders, gathered","letter":"C"},{"is_no_change":false,"label":"After the rain stopped, birders gathered","letter":"D"}]', 'D', '{"A":"Omits the comma after the introductory clause and inserts an intrusive one between subject and verb.","B":"Cuts the introductory clause short, turning ''stopped'' into a strange adjective describing the birders.","C":"Adds the needed boundary comma but keeps the intruder splitting ''birders'' from ''gathered.''","D":"Correct: one comma closes the introductory clause, and nothing separates the subject from its verb."}', 'An **introductory dependent clause** takes a comma at its end, and no comma may split a subject from its verb.', 'Students who fix the missing boundary comma often overlook the second error — the stray comma after ''birders.''', '1) Find where the introductory clause truly ends. 2) Place one comma there. 3) Locate the main subject and verb. 4) Confirm no comma stands between them. 5) Reject options that fix one error but keep the other.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-672a3f19592fcd6a', 'act-english', 's-punc', 2, 'The burrowing owl <u>nests, in</u> tunnels that prairie dogs have long since abandoned.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"nests in","letter":"B"},{"is_no_change":false,"label":"nests in,","letter":"C"},{"is_no_change":false,"label":"nests; in","letter":"D"}]', 'B', '{"A":"Drops a comma between the verb and the prepositional phrase it needs, breaking the flow for no reason (intrusive_comma).","B":"Correct: no punctuation belongs between the verb and the phrase that completes it.","C":"Moves the stray comma after ''in,'' still separating the phrase from the noun it introduces (intrusive_comma).","D":"A semicolon cannot join a verb to a prepositional phrase; it links independent clauses (semicolon_misuse)."}', 'Nothing should separate a verb from the **prepositional phrase** that completes its meaning, so no mark belongs here.', 'A brief pause seems natural after the verb, so students insert a comma even though the phrase attaches tightly to it.', '1) Identify the verb and the phrase right after it. 2) Ask whether that phrase completes the verb''s meaning. 3) If it does, do not separate them with any mark. 4) Reject commas or semicolons dropped between tightly linked words. 5) Re-read to confirm the verb and phrase flow together.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a7ae7090e4e0325', 'act-english', 's-punc', 2, '<u>After the last chime faded the</u> engineer cued the national anthem and signed off for the night.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"After the last chime faded, the","letter":"B"},{"is_no_change":false,"label":"After the last chime, faded the","letter":"C"},{"is_no_change":false,"label":"After, the last chime faded the","letter":"D"}]', 'B', '{"A":"With no comma, the introductory clause crashes into the main clause and readers momentarily parse ''faded the engineer.''","B":"Correct: an introductory dependent clause is set off with a comma before the main clause begins.","C":"The comma lands inside the introductory clause, cutting it off from its own verb.","D":"A comma directly after ''After'' severs the subordinating word from the clause it introduces."}', 'An **introductory dependent clause** takes a comma at its end, right before the main clause begins.', 'The original reads smoothly at a glance, so students skip the misreading trap where ''faded'' momentarily grabs ''the engineer.''', '1) Find the opening subordinating word. 2) Read forward to where that clause''s own subject and verb end. 3) Place one comma there. 4) Confirm the main clause after the comma can stand alone. 5) Reread to check no comma sits inside either clause.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6af713b67368333e', 'act-english', 's-punc', 2, 'Buoys anchored far offshore record wave heights every hour<u>; the</u> readings reach forecasters ashore by satellite link.', 'Which choice best conforms to the conventions of standard English punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", the","letter":"B"},{"is_no_change":false,"label":"; and the","letter":"C"},{"is_no_change":false,"label":"the","letter":"D"}]', 'A', '{"A":"Correct: complete statements sit on either side, and a semicolon may join two independent clauses.","B":"A comma alone between two complete statements creates a comma splice (misconception: a comma can join independent clauses).","C":"The semicolon does the joining by itself, so adding ''and'' after it doubles the connector (misconception: a semicolon works like a comma before a conjunction).","D":"With no punctuation, the two statements fuse into a run-on (misconception: closely related ideas may run together)."}', 'A **semicolon** legally joins the two independent clauses on either side of the break.', 'The comma feels natural because the second clause continues the same topic so smoothly.', '1) Cover the punctuation and read each side alone. 2) Ask: could each side stand as its own sentence? 3) If both could, join them with a period, a semicolon, or a comma plus a coordinating conjunction — never a comma alone or nothing. 4) Reject doubled connectors. 5) Re-read the joined sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6f9c0becf3f197f0', 'act-english', 's-punc', 2, 'Passage V — A Brief Note on Commas (usage-focused) — Many writers struggle with commas , they are among the trickiest marks of punctuation. A comma can separate items in a list, set off an introductory phrase, or join two clauses with a conjunction. <u>Misusing them, however</u> can confuse a reader. Consider the difference between "Let''s eat, Grandma" and "Let''s eat Grandma." The first invites Grandma to dinner; the second is alarming. Such examples remind us that punctuation, though small, carries real meaning.', 'Which choice correctly punctuates the underlined conjunctive adverb?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Misusing them, however,","letter":"B"},{"is_no_change":false,"label":"Misusing them however","letter":"C"},{"is_no_change":false,"label":"Misusing them; however","letter":"D"}]', 'B', '{"A":"NO CHANGE has only the leading comma; ''however'' needs one on each side.","B":"Commas on both sides correctly set off the interrupting ''however''.","C":"No commas at all leaves the conjunctive adverb unpunctuated.","D":"A semicolon wrongly breaks a single clause that has no second independent clause."}', 'A mid-clause **''however''** is an interrupter — commas on **both** sides: ''Misusing them, however, can confuse.''', 'The single leading comma looks finished, so the missing second comma is easy to miss.', 'Rule focus: Conventions (interrupter punctuation)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-85e2987f63fb5449', 'act-english', 's-punc', 2, 'Passage III — The Mapmaker''s Daughter — Marie Tharp was a geologist who helped change how we see the ocean floor. In the 1950s, working alongside her colleague Bruce Heezen, she plotted thousands of depth measurements collected from ships crossing the Atlantic. At the time, many scientists believed the ocean floor was mostly flat. Tharp''s maps revealed something remarkable, a vast underwater mountain range running down the middle of the Atlantic. This discovery, which supported the then-controversial theory of continental drift, was at first dismissed by Heezen as "girl talk." <u>Eventually,</u> the evidence became impossible to ignore. Tharp''s careful work helped establish the theory of plate tectonics. Today, her once-doubted maps are considered landmarks of earth science.', 'Which choice correctly punctuates the underlined introductory word?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Eventually","letter":"B"},{"is_no_change":false,"label":"Eventually;","letter":"C"},{"is_no_change":false,"label":"Eventually but","letter":"D"}]', 'B', '{"A":"This option leaves or introduces an error under the tested rule.","B":"\"Eventually\" as a one-word intro takes a comma only if needed; here \"Eventually the evidence…\" is acceptable without — but B (no semicolon, no comma error) is cleanest.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', '"Eventually" as a one-word intro takes a comma only if needed; here "Eventually the evidence…" is acceptable without — but B (no semicolon, no comma error) is cleanest.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Conventions (transition punctuation)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8bd6dbd180c9fcab', 'act-english', 's-punc', 2, 'The visiting <u>players'' lockers</u> line a narrow hallway behind the third-base dugout.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"players lockers","letter":"B"},{"is_no_change":false,"label":"player''s lockers","letter":"C"},{"is_no_change":false,"label":"players lockers''","letter":"D"}]', 'A', '{"A":"Correct: the lockers belong to multiple visiting players, so the plural possessive with the apostrophe after the s is right.","B":"Drops the apostrophe entirely, leaving two stacked nouns with no ownership marked (apostrophe_omitted).","C":"Claims a single owner, but a whole visiting roster shares the hallway of lockers (singular_for_plural_owner).","D":"Puts the apostrophe on the owned noun instead of the owners (apostrophe_wrong_noun)."}', 'Many players own the lockers, so the **plural possessive** — apostrophe after the s — is exactly right as written.', 'Students who memorize "apostrophe-s shows possession" default to the singular form without asking how many owners there are.', '1) Ask: who owns what? 2) Decide whether the owner is singular or plural. 3) Write the owner in its correct number first (player vs. players). 4) Add the possessive mark: apostrophe-s for singular, apostrophe after the s for regular plurals. 5) Confirm the apostrophe sits on the owner, never the thing owned.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-94e1f8044bd59460', 'act-english', 's-punc', 2, 'Because the storm had knocked out power across the valley<u> the</u> town meeting moved to the fire hall.', 'Which choice correctly punctuates the boundary after the opening clause?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"valley, the","letter":"B"},{"is_no_change":false,"label":"valley; the","letter":"C"},{"is_no_change":false,"label":"valley. The","letter":"D"}]', 'B', '{"A":"A full dependent clause opens this sentence — running it straight into the main clause hides where one ends and the other begins.","B":"A comma after an introductory dependent clause marks the boundary the reader needs.","C":"A semicolon needs independent clauses on BOTH sides; ''Because ... valley'' cannot stand alone.","D":"A period strands ''Because the storm had knocked out power across the valley'' as a fragment."}', 'An introductory dependent clause is set off from the main clause with a **comma**.', 'Read quickly aloud, the sentence seems to flow fine without any pause.', 'A dependent clause that OPENS the sentence takes a comma before the main clause — ''Because X happened, Y followed.''', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9eca0310cad953f4', 'act-english', 's-punc', 2, 'Some of the <u>songs, dated</u> back to the eighteenth century and had crossed the Atlantic in the memories of emigrants.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"songs dated","letter":"B"},{"is_no_change":false,"label":"songs; dated","letter":"C"},{"is_no_change":false,"label":"songs: dated","letter":"D"}]', 'B', '{"A":"The comma splits the subject ''songs'' from its own verb ''dated,'' a pause with no grammatical job.","B":"Correct: no punctuation belongs between a subject and its verb.","C":"A semicolon must join two independent clauses, but ''dated back...'' cannot stand alone.","D":"A colon must follow a complete statement, and ''Some of the songs'' is not one."}', 'A subject flows directly into its verb, so **no mark** belongs between ''songs'' and ''dated.''', 'The comma tempts students who hear a breath after the subject and assume every pause earns punctuation.', '1) Find the subject and its verb. 2) Check whether any mark stands between them. 3) Unless a complete paired interruption sits there, delete the mark. 4) For any semicolon or colon, test the words on each side against that mark''s requirements. 5) Re-read the cleaned sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a1d8621b5094130a', 'act-english', 's-punc', 2, 'Fresh murals now brighten the <u>childrens'' section</u> on the library''s ground floor.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"childrens section","letter":"B"},{"is_no_change":false,"label":"children''s section","letter":"C"},{"is_no_change":false,"label":"children section","letter":"D"}]', 'C', '{"A":"Places the apostrophe after an -s that the irregular plural ''children'' never takes.","B":"Drops the apostrophe entirely, leaving a possessive unmarked and a nonexistent word.","C":"Correct: ''children'' is an irregular plural, so its possessive is formed with apostrophe + s.","D":"Omits the possessive marker altogether, leaving an ungrammatical noun stack."}', 'Because ''children'' is an **irregular plural** with no plural -s, its possessive is formed by adding apostrophe + s.', 'Students overapply the ''plural possessives end in s-apostrophe'' rule without checking whether the plural was formed with -s at all.', '1) Ask who owns or is associated with the noun. 2) Write the owner word in full. 3) If the owner is a plural ending in -s, add just an apostrophe. 4) If the owner is any other word — including irregular plurals like children, women, men — add apostrophe + s. 5) Re-read to confirm the owner word is spelled normally.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c06011f4e642c4d6', 'act-english', 's-punc', 2, 'The reef''s night shift includes hunting moray eels, tentacled feather stars, and <u>brittle stars, which</u> unfurl their arms to sift the current for food.', 'Which choice best conforms to the conventions of standard English punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"brittle stars which","letter":"B"},{"is_no_change":false,"label":"brittle stars, which,","letter":"C"},{"is_no_change":false,"label":"brittle stars which,","letter":"D"}]', 'A', '{"A":"The comma correctly closes the series and sets off the nonrestrictive ''which'' clause describing brittle stars.","B":"Dropping the comma before a nonrestrictive ''which'' clause fuses the description onto the noun (misconception: missing_nonrestrictive_comma).","C":"The extra comma after ''which'' wrongly separates the relative pronoun from its own verb (misconception: comma_splits_subject_verb).","D":"The comma after ''which'' interrupts the clause while omitting the needed comma before it (misconception: comma_misplaced_in_clause)."}', 'A nonrestrictive ''which'' clause takes a comma **before** it and no comma splitting the pronoun from its verb.', 'The clause feels like a natural pause point, tempting an extra comma after ''which'' that actually severs subject from verb.', '1) Confirm the ''which'' clause adds extra, nonessential information — if so, it needs a comma before it. 2) Read from ''which'' to its verb; never drop a comma between them. 3) Check that the comma sits before ''which,'' not after it. 4) Keep the series comma that separates the final list item.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c400f21dbc48fa04', 'act-english', 's-punc', 2, 'Amara and Dele wrote down every recipe they perfected, and the <u>sisters'' battered recipe box</u> now sits on a shelf above the proofing cabinet.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"sister''s battered recipe box","letter":"B"},{"is_no_change":false,"label":"sisters battered recipe box","letter":"C"},{"is_no_change":false,"label":"sisters''s battered recipe box","letter":"D"}]', 'A', '{"A":"Correct — the box belongs to both sisters, so the plural ''sisters'' takes an apostrophe after the final s.","B":"Uses the singular possessive even though the sentence names two owners (possessive_singular_for_plural).","C":"Omits the apostrophe entirely, leaving a plural noun with no possession marked (possessive_missing_apostrophe).","D":"Adds ''s to a regular plural already ending in s, an over-marked form (possessive_double_s)."}', 'Two owners make **sisters** plural, and a regular plural shows possession with an apostrophe alone after the s.', 'The apostrophe-before-s pattern is so common that the singular possessive looks right at a glance.', '1) Ask who owns it — one owner or more? 2) Write the owner noun in the correct number. 3) If the plural ends in s, add just an apostrophe; otherwise add ''s. 4) Reread to check the owner count matches the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d1f59c7066de0693', 'act-english', 's-punc', 2, 'The starter kit<u>—motors, wheels, and a battery,</u> arrived two weeks before the season officially began.', 'Which choice correctly punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"—motors, wheels, and a battery","letter":"B"},{"is_no_change":false,"label":", motors, wheels, and a battery—","letter":"C"},{"is_no_change":false,"label":"—motors, wheels, and a battery—","letter":"D"}]', 'D', '{"A":"Opens the interrupter with a dash but closes it with a comma, mixing mark types (paired_punct_mismatch).","B":"Never closes the interrupting list, letting it crash into the main verb (paired_punct_unclosed).","C":"Reverses the mismatch, opening with a comma and closing with a dash (paired_punct_mismatch_reversed).","D":"Correct: the parenthetical list is framed by a matched pair of dashes."}', 'A parenthetical list opened with a dash must be **closed with a dash**, making the pair symmetrical.', 'The dash-then-comma original satisfies ear-readers because both marks create a similar pause.', '1) Identify the interrupting material. 2) Note the mark that opens it. 3) Require the identical mark where it closes. 4) Reject any option that mixes mark types or forgets the closer.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d79b7be26ed8021b', 'act-english', 's-punc', 2, 'A fennec <u>foxs</u> oversized ears radiate body heat into the cool night air, cooling the animal without a drop of sweat.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"fox''s","letter":"B"},{"is_no_change":false,"label":"foxes''","letter":"C"},{"is_no_change":false,"label":"foxes","letter":"D"}]', 'B', '{"A":"Adds no apostrophe, so it is neither a valid possessive nor a correct plural (missing_apostrophe).","B":"Correct: one fennec owns the ears, so the singular possessive with apostrophe-s is required.","C":"The plural possessive implies many animals, but the sentence names a single one (wrong_number_possessive).","D":"A plain plural shows more than one animal and no ownership at all (plural_for_possessive)."}', 'The ears belong to one animal, so the **singular possessive** form is required before ''oversized ears.''', 'The plural-looking spelling seems to match ''ears,'' so students make the possessive plural to agree with the thing owned.', '1) Ask whether the underlined word owns the noun that follows it. 2) If it does, decide how many owners there are. 3) One owner takes apostrophe-s. 4) More than one owner ending in s takes an apostrophe after the s. 5) Re-read to confirm the number of owners matches the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d95bebf3d748e2bd', 'act-english', 's-punc', 2, 'Under his grandmother''s eye, Tomas <u>learned to fold the pastry dough</u> in thirds without tearing a single layer.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"learned, to fold the pastry dough","letter":"B"},{"is_no_change":false,"label":"learned to fold, the pastry dough","letter":"C"},{"is_no_change":false,"label":"learned to fold the pastry dough,","letter":"D"}]', 'A', '{"A":"Correct — the verb, its infinitive, and its object flow without interruption, so no internal punctuation is needed.","B":"Splits the verb ''learned'' from the infinitive that completes it (comma_verb_complement).","C":"Separates ''fold'' from its direct object, ''the pastry dough'' (comma_verb_object).","D":"Inserts a comma before the essential phrase ''in thirds,'' severing how the folding is done from the folding itself (comma_before_essential)."}', 'No rule calls for a comma here — the chain **verb → infinitive → object → essential phrase** should run unbroken.', 'Students who add commas wherever a speaker might breathe often insert one before ''in thirds.''', '1) For each comma, name the rule that requires it (series, intro element, interrupter, joining clauses). 2) If no rule fits, the comma is intrusive — remove it. 3) Never separate a verb from its object or its complement. 4) Reread the stripped sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dcc6d8a90143401e', 'act-english', 's-punc', 2, '<u>After the storyboard was approved animators</u> began timing each scene to the prerecorded soundtrack.', 'Which choice most effectively punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"After, the storyboard was approved animators","letter":"B"},{"is_no_change":false,"label":"After the storyboard was approved animators,","letter":"C"},{"is_no_change":false,"label":"After the storyboard was approved, animators","letter":"D"}]', 'D', '{"A":"With no comma, the introductory clause runs into the main clause, inviting the misreading ''approved animators.''","B":"A comma directly after ''After'' severs the subordinator from the clause it introduces.","C":"This comma falls between the subject ''animators'' and its verb ''began'' while leaving the clause boundary unmarked.","D":"The comma after ''approved'' correctly closes the introductory dependent clause before the main clause begins."}', 'An **introductory clause** is set off with a comma at its end, just before the main clause''s subject.', 'Students who place commas by pause often stop after ''animators,'' hearing the whole opening chunk as one breath.', '1) Find where the sentence''s main subject-verb pair begins. 2) Everything before it that starts with a subordinator is the introduction. 3) Put one comma at the introduction''s end. 4) Confirm no comma splits the subject from its verb.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-df0fe0c126bbe20c', 'act-english', 's-punc', 2, 'Passage II — The Science of Sourdough — Bread may seem simple, but sourdough is surprisingly complex. Unlike breads made with packaged yeast, sourdough rises using wild yeast and bacteria captured from the air. Bakers maintain a "starter," a mixture of flour and water that they feed regularly. <u>The starter, it ferments</u> over several days. During fermentation, the microbes produce carbon dioxide, which makes the dough rise. They also produce acids, giving sourdough its tangy flavor. Because of these reactions, no two starters taste exactly alike. Some bakers, claim that a starter''s flavor reflects the place where it was made. A San Francisco starter, for instance, may taste different from one in Paris. Whether or not that is true, sourdough remains a small marvel of biology and patience.', 'Which choice best repairs the underlined clause boundary?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The starter ferments","letter":"B"},{"is_no_change":false,"label":"The starter, ferments","letter":"C"},{"is_no_change":false,"label":"The starter; it ferments","letter":"D"}]', 'B', '{"A":"This option leaves or introduces an error under the tested rule.","B":"\"The starter ferments\" removes the comma-splice \"it.\"","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', '"The starter ferments" removes the comma-splice "it."', 'The original can read smoothly until you apply the rule.', 'Rule focus: Production (no comma splice/redundant pronoun)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e607be55f3d95316', 'act-english', 's-punc', 2, 'The <u>museums collection</u> of antique lace includes a christening gown stitched in 1810.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"museum''s collection","letter":"B"},{"is_no_change":false,"label":"museums'' collection","letter":"C"},{"is_no_change":false,"label":"museums collection''s","letter":"D"}]', 'B', '{"A":"The museum owns the collection, so a possessive apostrophe is required and none appears.","B":"Correct: one museum possesses the collection, so the apostrophe goes before the s.","C":"An apostrophe after the s signals several museums, but the sentence concerns only one.","D":"The apostrophe lands on the possessed noun rather than on the owner."}', 'A **singular owner** takes apostrophe + s: the museum owns the collection.', 'The plural-possessive version tempts students who remember that apostrophes can follow the s but forget that placement encodes the owner''s number.', '1) Ask who owns what. 2) Rewrite the owner as a phrase: ''of the museum.'' 3) Singular owner: apostrophe before s; plural owner: after s. 4) Attach the apostrophe to the owner, never the thing owned. 5) Re-read to confirm number.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fe2f7f256bd7a854', 'act-english', 's-punc', 2, 'Three humble ingredients <u>flour, water, and salt)</u> become bread once wild yeast and time go to work.', 'Which choice makes the sentence''s punctuation correct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"(flour, water, and salt)","letter":"B"},{"is_no_change":false,"label":"flour, water, and salt)","letter":"C"},{"is_no_change":false,"label":"(flour, water, and salt","letter":"D"}]', 'B', '{"A":"Unpaired mark: a closing parenthesis appears with no opening one, so the aside is not enclosed.","B":"Correct: paired parentheses open and close the parenthetical list, enclosing it cleanly.","C":"Same flaw as the original: only the closing parenthesis is present, leaving the opener missing.","D":"Opposite half-pair: it supplies the opening parenthesis but drops the closer, so the aside never ends."}', 'Parentheses are **paired punctuation**: an enclosed aside needs both an opening and a closing mark.', 'Because the closing parenthesis already sits in the sentence, adding nothing feels like leaving well enough alone.', '1) Spot any parenthesis, dash, or bracket used to set off an aside. 2) Confirm it comes as a matched pair — one to open, one to close. 3) If only one mark appears, add its partner or delete it. 4) Check that the sentence still reads correctly if the aside is removed. 5) Reread to confirm the enclosure is complete.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-141e8c43a47691bd', 'act-english', 's-punc', 3, 'The shop''s most contested treasures <u>are: vintage</u> cameras, first-edition paperbacks, and hand-stitched quilts.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"are; vintage","letter":"B"},{"is_no_change":false,"label":"are vintage","letter":"C"},{"is_no_change":false,"label":"are, vintage","letter":"D"}]', 'C', '{"A":"Drops a colon right after the verb, interrupting the clause before it is complete.","B":"Uses a semicolon where no second independent clause follows, stranding the list.","C":"Correct: the verb *are* flows directly into its complements, and no punctuation is needed.","D":"Inserts a comma between the verb and the first item it introduces, splitting the clause''s core."}', 'A colon may follow only a **complete** independent clause; after the verb *are*, the sentence must run straight into the list.', 'Lists feel like they deserve an introductory colon, so students reach for one even mid-clause.', '1) Cover everything after the possible colon. 2) Ask: is what remains a complete sentence? 3) If not, no colon (and no semicolon or comma) may interrupt. 4) Only insert a colon after a clause that could take a period. 5) Re-read the sentence without any mark to see if it flows.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-18c6280ee7c7b261', 'act-english', 's-punc', 3, 'The <u>Zestar, an early-ripening variety</u> opens the picking season each August.', 'Which choice provides the most effective punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Zestar, an early-ripening variety,","letter":"B"},{"is_no_change":false,"label":"Zestar an early-ripening variety","letter":"C"},{"is_no_change":false,"label":"Zestar, an early-ripening variety;","letter":"D"}]', 'B', '{"A":"The appositive opens with a comma but never closes, splicing the extra phrase into the main clause.","B":"Correct: ''an early-ripening variety'' is a nonessential appositive, so it needs a comma on both sides.","C":"Dropping both commas fuses the renaming phrase to the sentence as if it were essential.","D":"A semicolon cannot close an appositive; it must separate independent clauses, and what follows is not one."}', 'A **nonessential** appositive is set off by a pair of commas — one before and one after.', 'The opening comma sounds sufficient when reading quickly, so the missing closing comma goes unnoticed.', '1) Find the interrupting phrase and test-delete it. 2) If the sentence still works, the phrase is nonessential. 3) Fence a nonessential phrase with matching punctuation on both sides. 4) Never mix a comma on one side with different punctuation on the other.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-21bc8b58f3951351', 'act-english', 's-punc', 3, 'The stakes <u>planted along the centerline reveal</u> how unevenly the glacier is thinning.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"planted along the centerline, reveal","letter":"B"},{"is_no_change":false,"label":"planted, along the centerline reveal","letter":"C"},{"is_no_change":false,"label":"planted along the centerline: reveal","letter":"D"}]', 'A', '{"A":"''Planted along the centerline'' is an essential identifying phrase, and no punctuation should separate the subject from its verb.","B":"The comma splits the subject ''stakes planted along the centerline'' from its verb (subject-verb comma).","C":"The comma cuts into the middle of the identifying phrase itself (intrusive comma inside a unit).","D":"A colon may appear only after a complete statement, not between a subject and its verb (colon_midclause)."}', 'Nothing here is nonessential, so **no internal punctuation** belongs between the subject and its verb.', 'The long subject makes readers want a breathing comma before the verb, a pause the rules do not permit.', '1) Find the subject and its verb. 2) Ask whether anything between them could be lifted out without changing which stakes are meant. 3) If the phrase is essential, use no commas. 4) Never let a single comma or a colon stand between subject and verb. 5) Reread the bare sentence to confirm it flows.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-36426c705fc791cf', 'act-english', 's-punc', 3, 'Every printing session depends on three trays lined up in order: <u>developer, stop bath and, fixer</u>, each one mixed fresh that morning.', 'Which choice best punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"developer stop bath, and fixer","letter":"B"},{"is_no_change":false,"label":"developer, stop, bath, and fixer","letter":"C"},{"is_no_change":false,"label":"developer, stop bath, and fixer","letter":"D"}]', 'D', '{"A":"Places a comma after the conjunction instead of before it (comma_after_conjunction), splitting ''and'' from the item it introduces.","B":"Omits the divider after the first series item (missing_series_comma), letting ''developer'' and ''stop bath'' run together.","C":"Cuts the two-word chemical name in half (comma_inside_item), inventing a fourth item that does not exist.","D":"Correct: commas separate the three whole items, with the final comma before ''and.''"}', 'A three-item series needs a comma **between items** — after the first and second — with none trailing the conjunction.', 'The original keeps the right number of commas, so students who count commas instead of checking their positions accept it.', '1) Count the items in the series by naming each one aloud. 2) Keep multi-word items whole — no comma inside a single name. 3) Place a comma after each item except the last. 4) Check that no comma directly follows the conjunction.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-37b6b1a3fa1e8377', 'act-english', 's-punc', 3, '<u>Her coach a former Olympic trials qualifier reviews</u> every split from the weekend long run.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Her coach, a former Olympic trials qualifier reviews","letter":"B"},{"is_no_change":false,"label":"Her coach, a former Olympic trials qualifier, reviews","letter":"C"},{"is_no_change":false,"label":"Her coach a former Olympic trials qualifier, reviews","letter":"D"}]', 'C', '{"A":"Omits both commas, fusing the nonessential appositive into the main clause (appositive_no_commas).","B":"Opens the appositive with a comma but never closes it, crashing the description into the verb (paired_comma_half_open).","C":"Correct: the appositive ''a former Olympic trials qualifier'' is extra information and must be set off by commas on both sides.","D":"Marks only the end of the appositive, leaving its start unfenced and cutting the subject off from its verb (paired_comma_half_close)."}', 'A nonessential appositive must be **fenced** by commas on both sides because the sentence works without it.', 'The single opening comma tempts students who hear the first pause clearly but do not track where the interruption ends.', '1) Find the descriptive phrase inside the sentence. 2) Lift it out: does the sentence still work? 3) If yes, it is nonessential and needs punctuation on both sides. 4) Mark where it begins and where it ends. 5) Re-read to confirm subject and verb reconnect cleanly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-37bd8706ce13fdbf', 'act-english', 's-punc', 3, 'The Marsh Street depot, <u>a brick landmark completed in 1911,</u> will anchor the new transit plaza.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a brick landmark completed in 1911","letter":"B"},{"is_no_change":false,"label":"a brick landmark, completed in 1911,","letter":"C"},{"is_no_change":false,"label":"a brick landmark completed in 1911;","letter":"D"}]', 'A', '{"A":"The appositive is nonessential, so the paired commas around it are correct as written.","B":"Dropping the closing comma leaves the appositive half-fenced, welding it onto the verb — the misconception that one comma is enough.","C":"The extra comma after ''landmark'' chops the appositive itself in two for no grammatical reason.","D":"A semicolon cannot close an appositive; it needs an independent clause on each side."}', 'A **nonessential appositive** takes a comma on both sides, and the original supplies both.', 'The comma-heavy look of the original makes students want to delete one, especially the closing comma.', '1) Find the interrupter. 2) Test: can the sentence stand without it? 3) If yes, fence it with a comma at the start AND the end. 4) Never use stronger marks like semicolons unless both sides are full clauses. 5) Re-read the sentence, skipping the interrupter.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3afe53bbd07a0e82', 'act-english', 's-punc', 3, 'During the preshow check, the sound-board operator <u>tests, every wireless microphone</u> clipped to a costume.', 'Which choice makes the sentence most acceptable in standard written English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"tests: every wireless microphone","letter":"B"},{"is_no_change":false,"label":"tests every wireless microphone","letter":"C"},{"is_no_change":false,"label":"tests—every wireless microphone","letter":"D"}]', 'C', '{"A":"The comma needlessly separates the verb from its direct object (comma_verb_object).","B":"A colon may follow only a complete independent clause, not a bare verb mid-thought (colon_midclause).","C":"Correct: no punctuation belongs between a verb and its object, so the clause should flow unbroken.","D":"The dash sets off the object as if it were an aside, but the object is the essential core of the clause (dash_essential_element)."}', 'No mark may **separate** a verb from its direct object, so the underlined portion needs no punctuation at all.', 'The colon version tempts students who see a list-like noun phrase coming and assume a colon should introduce it, forgetting the clause before a colon must be complete.', '1) Find the verb and ask ''tests what?'' to locate its object. 2) Check whether any mark falls between them. 3) Remove punctuation that splits verb from object. 4) For a colon or dash, require a complete clause before it or a true aside after it. 5) Reread the clause to confirm it flows without interruption.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3eb5738a961ab620', 'act-english', 's-punc', 3, 'At the fall festival, judges score every entry in the pie contest on <u>three qualities, crust</u>, filling, and balance.', 'Which choice provides the most effective punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"three qualities; crust","letter":"B"},{"is_no_change":false,"label":"three qualities: crust","letter":"C"},{"is_no_change":false,"label":"three qualities, such as crust","letter":"D"}]', 'C', '{"A":"A comma after ''qualities'' muddles the announcement into the list, reading like a four-item series.","B":"A semicolon must separate independent clauses, and the list that follows is not a clause.","C":"Correct: a colon follows the complete statement to introduce the list it promises.","D":"''Such as'' signals a partial sample, but the sentence then names all three qualities."}', 'A **colon** after an independent clause formally introduces the list the clause announces.', 'A comma feels like the natural pause before a list, so the four-item muddle it creates goes unnoticed.', '1) Check that the words before the mark form a complete sentence. 2) Confirm the words after it are the promised list or explanation. 3) If both hold, use a colon. 4) Reject commas that blur the announcement into the list and semicolons that lack a second clause.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-41a327b178de5592', 'act-english', 's-punc', 3, 'The library''s oldest <u>treasure&mdash;a hand-drawn 1911 map of the harbor&mdash;hangs</u> behind glass in the local-history room.', 'Which punctuation choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"treasure&mdash;a hand-drawn 1911 map of the harbor, hangs","letter":"B"},{"is_no_change":false,"label":"treasure, a hand-drawn 1911 map of the harbor&mdash;hangs","letter":"C"},{"is_no_change":false,"label":"treasure&mdash;a hand-drawn 1911 map of the harbor; hangs","letter":"D"}]', 'A', '{"A":"Correct: the appositive is enclosed by a matched pair of dashes, and the sentence reads cleanly without it.","B":"Opens the interruption with a dash but closes it with a comma, mismatching the pair.","C":"Opens with a comma and closes with a dash — the same mismatch reversed.","D":"A semicolon must join two independent clauses, but what follows here is only the sentence''s verb phrase."}', 'An interrupting appositive must be sealed by a **matched pair** of marks, and here both boundaries use dashes.', 'Mixed comma-dash pairs sound fine when read aloud, so students miss that the opening and closing marks disagree.', '1) Find the interrupter and read the sentence without it. 2) If the sentence still works, the interrupter must be enclosed by a matched pair: two commas, two dashes, or parentheses. 3) Check that the opening and closing marks are the same type. 4) Reject any mark, like a semicolon, whose job is different. 5) Re-read the full sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-48ebd8c087d04821', 'act-english', 's-punc', 3, 'Whiskers meowed until Maya filled the <u>cats</u> bowl.', 'Which choice punctuates the possessive correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"cats''","letter":"B"},{"is_no_change":false,"label":"cat''s","letter":"C"},{"is_no_change":false,"label":"cats''s","letter":"D"}]', 'C', '{"A":"Without an apostrophe, ''cats'' is just a plural — nothing shows the bowl belongs to the cat.","B":"The apostrophe after the s claims several cats own the bowl, but only Whiskers is in the sentence.","C":"One cat — Whiskers — owns the bowl, so the singular possessive ''cat''s'' is correct.","D":"''cats''s'' is not a standard English form."}', 'One owner → apostrophe **before** the s: *cat''s*.', 'Plural ''cats'' and possessive ''cat''s'' sound identical aloud, so the missing apostrophe is easy to overlook.', 'Singular owner → ''s; plural owners ending in s → s''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4b7180373e14dd42', 'act-english', 's-punc', 3, 'A smart taper <u>includes: fewer</u> miles, extra sleep, and familiar meals.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"includes; fewer","letter":"B"},{"is_no_change":false,"label":"includes fewer","letter":"C"},{"is_no_change":false,"label":"includes, fewer","letter":"D"}]', 'C', '{"A":"Places a colon between a verb and its objects, but a colon may follow only a complete independent clause (colon_midclause).","B":"A semicolon requires an independent clause on each side, and ''fewer miles, extra sleep, and familiar meals'' is not a clause (semicolon_before_list).","C":"Correct: the verb flows directly into the items it governs, so no punctuation belongs after ''includes.''","D":"Inserts an unnecessary comma between the verb and its object list (comma_verb_object)."}', 'A list introduced directly by a verb takes **no** punctuation before it, because the items are the verb''s objects.', 'The colon tempts students who learned ''colon before a list'' without the requirement that a complete sentence come first.', '1) Look at the words before the mark. 2) Ask: could they stand alone as a complete sentence? 3) If yes, a colon may introduce the list. 4) If no — if the verb still needs its objects — use no mark at all. 5) Re-read to confirm the verb connects straight to its list.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5cb6fe89ebd9267e', 'act-english', 's-punc', 3, 'The two <u>glaciers''s</u> shared meltwater basin feeds a chain of turquoise lakes.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"glacier''s","letter":"B"},{"is_no_change":false,"label":"glaciers''","letter":"C"},{"is_no_change":false,"label":"glaciers","letter":"D"}]', 'C', '{"A":"''Glaciers''s'' double-marks possession; a plural ending in -s never adds another -s after the apostrophe (double-marked possessive).","B":"''Glacier''s'' is a singular possessive, but the sentence specifies two glaciers (singular_possessive_for_plural).","C":"A plural noun ending in -s shows possession with the apostrophe alone, matching ''the two.''","D":"''Glaciers'' shows no possession at all, though the basin belongs to them (missing possessive)."}', 'A **plural ending in -s** takes only an apostrophe after the s to show possession.', 'The singular possessive looks tidy and familiar, so students forget the word must stay plural to match ''the two.''', '1) Ask: who owns it? 2) Write the owner as a plain noun first (two of them → plural). 3) If the plural ends in -s, add the apostrophe after the s and stop. 4) If it does not end in -s, add apostrophe + s. 5) Reread to confirm both number and ownership survive.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-68d690bbc1763d4a', 'act-english', 's-punc', 3, 'The preservation board must review alterations to <u>buildings, which stand</u> within the historic district; owners elsewhere may renovate freely.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"buildings that stand","letter":"B"},{"is_no_change":false,"label":"buildings, that stand","letter":"C"},{"is_no_change":false,"label":"buildings which stands","letter":"D"}]', 'B', '{"A":"The comma plus ''which'' marks the clause as nonessential, implying the board reviews all buildings — but the second half of the sentence shows only district buildings are covered.","B":"''That'' with no comma makes the clause restrictive, correctly limiting review to buildings inside the district.","C":"''That'' introduces restrictive clauses, which never take a comma before them — the misconception that a pause always earns a comma.","D":"Dropping the comma helps, but the singular verb ''stands'' clashes with the plural ''buildings.''"}', 'The clause **limits** which buildings need review, so it must be restrictive: ''that'' with no comma.', 'The comma-plus-''which'' construction looks polished and formal, so students miss that it quietly changes the sentence''s meaning.', '1) Ask: does the clause limit which nouns you mean, or just add bonus detail? 2) If it limits, use the restrictive pronoun with no comma. 3) If it''s bonus detail, use a comma plus ''which.'' 4) Check the rest of the sentence for evidence of which meaning is intended. 5) Confirm the clause''s verb agrees with the noun it describes.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-69f03ecfdcb74b85', 'act-english', 's-punc', 3, 'Animators who mastered the new <u>xerographic process found</u> steady work at studios scrambling to cut inking costs.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"xerographic process, found","letter":"B"},{"is_no_change":false,"label":"xerographic process: found","letter":"C"},{"is_no_change":false,"label":"xerographic, process found","letter":"D"}]', 'A', '{"A":"No punctuation is needed: the long subject flows directly into its verb ''found.''","B":"This comma splits the subject from its verb, a pause-based error common after long subjects.","C":"A colon may follow only a complete independent clause; here it interrupts mid-clause before the verb.","D":"This comma severs the adjective ''xerographic'' from the noun ''process'' it modifies."}', 'No mark belongs between a subject and its verb, **however long the subject is**.', 'After the lengthy ''Animators who mastered the new xerographic process,'' students hear a breath and insert a comma.', '1) Identify the subject (with all its modifiers) and its verb. 2) Check that nothing but a full paired interrupter stands between them. 3) Test any colon: could the words before it end with a period? 4) If every mark fails a rule, the span may need none at all.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b26db45b515df51', 'act-english', 's-punc', 3, 'Every new member receives<u>: a</u> water key, a plot map, and a compost card at orientation.', 'Which choice correctly punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"receives; a","letter":"B"},{"is_no_change":false,"label":"receives a","letter":"C"},{"is_no_change":false,"label":"receives, a","letter":"D"}]', 'C', '{"A":"Colon misuse: a colon may follow only a complete independent clause, and here it interrupts the verb and its objects.","B":"A semicolon must sit between two independent clauses; a list of objects is not a clause.","C":"Correct: the verb flows directly into its objects, so no punctuation belongs at this joint.","D":"A comma may never separate a verb from its direct object."}', 'No mark belongs between a verb and its objects; a colon could introduce this list **only after a complete independent clause**, which ''Every new member receives'' is not.', 'Students learn ''a colon introduces a list'' and apply it before every series without testing whether the words before the colon form a complete statement.', '1) Find the mark before the list. 2) Cover the list and read only what comes before the mark: could it end with a period and stand alone? 3) If yes, a colon is allowed; if no, remove the mark entirely. 4) Never let any comma or stronger mark separate a verb from its objects. 5) Reread the sentence without pausing at the joint.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-79e23eca45d07dfe', 'act-english', 's-punc', 3, 'The jam vendor''s best-selling <u>flavor, is</u> a strawberry rhubarb that usually sells out by nine.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"flavor; is","letter":"B"},{"is_no_change":false,"label":"flavor: is","letter":"C"},{"is_no_change":false,"label":"flavor is","letter":"D"}]', 'D', '{"A":"A lone comma illegally splits the subject from its verb (comma_subject_verb).","B":"A semicolon must join two independent clauses; the words before it are only a subject (semicolon_fragment).","C":"A colon must follow a complete statement, not interrupt a clause midway (colon_midclause).","D":"Correct — no punctuation belongs between a subject and its verb."}', 'A subject and its verb form one unit, so **no punctuation** may divide them.', 'The long, modified subject invites a spoken pause before the verb, and students translate that pause into a comma.', '1) Find the subject and its verb. 2) Ask whether any complete grammatical structure (a clause, an interrupter needing two marks) sits between them. 3) If not, remove every mark between subject and verb. 4) Test semicolons by requiring full clauses on both sides. 5) Test colons by requiring a complete statement before them.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7af5b55ac852cf7a', 'act-english', 's-punc', 3, 'Marisol''s first <u>teapot a lopsided vessel with a drippy spout still</u> greets visitors from the studio''s welcome shelf.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"teapot, a lopsided vessel, with a drippy spout still","letter":"B"},{"is_no_change":false,"label":"teapot a lopsided vessel with a drippy spout, still","letter":"C"},{"is_no_change":false,"label":"teapot, a lopsided vessel with a drippy spout, still","letter":"D"}]', 'D', '{"A":"With no punctuation, the nonessential appositive crashes into the sentence''s subject and verb (missing both commas).","B":"Slices the appositive apart, fencing off its own prepositional phrase and leaving part of the aside unmarked (comma dropped inside the unit).","C":"Closes an interruption that was never opened, so readers cannot tell where the aside began (missing the opening comma).","D":"Correct: the nonessential appositive describing the teapot is framed by a comma on each side."}', 'A **nonessential appositive** must be enclosed by a matched pair of commas.', 'The single closing comma sounds right aloud because the voice drops there, so students forget the interruption also needs an entrance marker.', '1) Cover the descriptive phrase and confirm the sentence still stands. 2) If it does, the phrase is nonessential. 3) Mark where the phrase begins and where it ends. 4) Place one comma at each boundary — never just one, never inside the phrase. 5) Reread to confirm subject meets verb cleanly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-82cdf27b1013b389', 'act-english', 's-punc', 3, 'The <u>starter—a sour, bubbling culture the family has fed daily since 1972, lives</u> in a ceramic crock behind the register.', 'Which choice provides the most effective punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"starter, a sour, bubbling culture the family has fed daily since 1972—lives","letter":"B"},{"is_no_change":false,"label":"starter—a sour, bubbling culture the family has fed daily since 1972 lives","letter":"C"},{"is_no_change":false,"label":"starter—a sour, bubbling culture the family has fed daily since 1972—lives","letter":"D"}]', 'D', '{"A":"Opens the interrupter with a dash but closes it with a comma; paired punctuation cannot be mixed (paired_dash_comma_mix).","B":"Reverses the mismatch, opening with a comma and closing with a dash (paired_comma_dash_mix).","C":"Opens with a dash and never closes the interrupter, letting it crash into the main verb (paired_unclosed).","D":"Correct — matching dashes fence off the interrupting description on both sides."}', 'An interrupter must be enclosed by a **matching pair** — dash with dash — so the main clause ''The starter … lives'' reads cleanly.', 'The opening dash is so noticeable that the quiet comma at the other end slips by unchecked.', '1) Find the interrupting chunk and read the sentence without it. 2) Check the mark before the chunk and the mark after it. 3) Make the two marks match (both commas, both dashes, or parentheses). 4) Reread with the chunk removed to confirm the frame.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9677115a9a7bc409', 'act-english', 's-punc', 3, 'Founded by thirty area farms, the <u>growers'' cooperative</u> votes on booth fees each spring.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"grower''s cooperative","letter":"B"},{"is_no_change":false,"label":"growers cooperative","letter":"C"},{"is_no_change":false,"label":"growers''s cooperative","letter":"D"}]', 'A', '{"A":"Correct — the cooperative belongs to many growers (thirty farms), so the plural possessive puts the apostrophe after the s.","B":"The singular possessive implies one grower owns the cooperative, contradicting ''thirty area farms'' (possessive_wrong_number).","C":"Drops the apostrophe entirely, erasing the ownership relationship (possessive_missing_apostrophe).","D":"Adds a nonstandard extra s to a plural that already ends in s (possessive_double_s)."}', 'Thirty farms own the cooperative, so the **plural possessive** — s followed by an apostrophe — is required.', 'The apostrophe-before-s form is the possessive students write most often, so it looks right by habit.', '1) Ask: who owns it, and how many of them are there? 2) Look for a number clue elsewhere in the sentence. 3) One owner → apostrophe + s. 4) Multiple owners whose plural ends in s → s + apostrophe only. 5) Confirm some apostrophe appears whenever ownership is meant.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a37fbfd95df2caef', 'act-english', 's-punc', 3, 'Our biology teacher<u>, Mr. Alvarez,</u> keeps a terrarium of hissing cockroaches behind his desk.', 'Which choice punctuates the teacher''s name correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", Mr. Alvarez","letter":"B"},{"is_no_change":false,"label":"Mr. Alvarez,","letter":"C"},{"is_no_change":false,"label":"Mr. Alvarez","letter":"D"}]', 'A', '{"A":"The name merely renames ''our biology teacher'', so a PAIR of commas sets it off.","B":"An interrupter needs commas on both sides — opening one without closing it splices the name into the verb.","C":"Closing the interrupter without opening it makes the comma look like it belongs to the verb phrase.","D":"With no commas the name reads as restrictive — as if several biology teachers had to be told apart."}', 'A renaming appositive is set off by a **pair of commas** — both sides or neither.', 'Only one pause is easy to hear aloud, so a single comma feels sufficient.', 'A nonrestrictive appositive takes commas on BOTH sides; drop both only when the name truly restricts.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a76732e69d259db0', 'act-english', 's-punc', 3, 'The roadrunner<u>—a swift, ground-dwelling bird,</u> rarely takes to the air, sprinting after lizards on foot instead.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"(a swift, ground-dwelling bird—","letter":"B"},{"is_no_change":false,"label":"—a swift, ground-dwelling bird—","letter":"C"},{"is_no_change":false,"label":", a swift, ground-dwelling bird—","letter":"D"}]', 'C', '{"A":"Opens the interrupter with a dash but closes it with a comma, so the paired marks do not match (mismatched_pair).","B":"Opens with a parenthesis and closes with a dash, mixing two different enclosing marks (mismatched_pair).","C":"Correct: a dash before and a dash after enclose the interrupting phrase with matching marks.","D":"Opens with a comma and closes with a dash, again failing to match the two enclosing marks (mismatched_pair)."}', 'An interrupting phrase must be enclosed by a **matching pair** of marks — a dash on each side.', 'A dash paired with a comma looks acceptable because both marks can set off phrases, so students overlook that the two ends must match.', '1) Find the phrase that interrupts the main sentence. 2) Note the mark that opens it. 3) The mark that closes it must be the same kind (dash-dash or paren-paren). 4) Reject any version that opens with one mark and closes with another. 5) Re-read the sentence to confirm the pair matches.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c7c854704a3bc944', 'act-english', 's-punc', 3, 'Refuge biologists <u>estimate, that nearly</u> half of the mallard ducklings hatched along the dike survive their first summer.', 'Which choice correctly punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"estimate: that nearly","letter":"B"},{"is_no_change":false,"label":"estimate that nearly","letter":"C"},{"is_no_change":false,"label":"estimate, that, nearly","letter":"D"}]', 'C', '{"A":"The comma intrudes between the verb and the clause that serves as its object.","B":"A colon may only follow a complete statement; ''Refuge biologists estimate'' is an unfinished thought.","C":"Correct: the reporting verb flows straight into its object clause with no punctuation.","D":"Doubles the intrusion, wrapping the essential connector in commas as if it were an aside."}', 'A verb runs **directly** into the clause that acts as its object; no punctuation belongs at that seam.', 'Students hear a spoken pause after ''estimate'' and translate it into a comma, though grammar allows nothing there.', '1) Ask what the verb needs to feel complete. 2) If the following clause answers ''estimate what?'', it is the object. 3) Remove any punctuation between verb and object clause. 4) Reserve colons for after statements that could stand alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c86b66726f6339df', 'act-english', 's-punc', 3, 'Rex pulled hard, and the <u>dogs''</u> leash slipped from Maya''s hand.', 'Which choice makes the possessive correct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"dog''s","letter":"B"},{"is_no_change":false,"label":"dogs","letter":"C"},{"is_no_change":false,"label":"dogss''","letter":"D"}]', 'B', '{"A":"The apostrophe after the s marks a plural possessive, but only one dog — Rex — is in the sentence.","B":"One dog owns the leash, so the singular possessive ''dog''s'' is correct.","C":"Without an apostrophe there is no possessive at all — the leash must belong to the dog.","D":"''dogss'''' is not a word form in English."}', 'One owner → apostrophe **before** the s: *dog''s*.', 'Plural and possessive forms sound identical aloud, so the written apostrophe placement is easy to miss.', 'Singular owner → ''s; plural owners ending in s → s''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c8cb2e2356976a1b', 'act-english', 's-punc', 3, 'A compositor''s case held everything a line of verse required<u>: letters, spacers, and tied ligatures</u> sorted into little compartments.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; letters, spacers, and tied ligatures","letter":"B"},{"is_no_change":false,"label":": letters, spacers, and, tied ligatures","letter":"C"},{"is_no_change":false,"label":", such as: letters, spacers, and tied ligatures","letter":"D"}]', 'A', '{"A":"A complete statement precedes the list, so the colon properly introduces it.","B":"A semicolon cannot introduce a list; it joins two complete statements.","C":"The comma after ''and'' interrupts the final list item; no comma follows the conjunction in a series.","D":"''Such as'' already introduces examples, so a colon after it is redundant and interrupts the phrase''s flow."}', 'A colon may introduce a list only after a **complete** statement, which ''the case held everything a line of verse required'' is.', 'The semicolon version tempts students who treat semicolons and colons as interchangeable ''strong'' marks.', '1) Read the words before the mark and ask whether they form a complete statement. 2) If yes, a colon may introduce the list that follows. 3) If the lead-in ends with a phrase like ''such as'' or ''including,'' use no mark at all. 4) Scan the list itself: commas between items, none after the final conjunction. 5) Re-read the whole sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d65c1d28ca1c8325', 'act-english', 's-punc', 3, 'The pool teemed with life<u>; a</u> single square foot of rock held hundreds of creatures.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", a","letter":"B"},{"is_no_change":false,"label":"a","letter":"C"},{"is_no_change":false,"label":": a","letter":"D"}]', 'A', '{"A":"Correct: the semicolon links two complete, closely related independent clauses.","B":"A comma between two independent clauses creates a comma splice (comma_splice).","C":"Dropping punctuation fuses the two independent clauses into a run-on.","D":"A colon should follow a clause that sets up a list or explanation, not simply join two equal statements."}', 'A **semicolon** correctly joins two independent clauses that could each stand alone.', 'The second clause explains the first, so a colon feels justified even though the clauses are equal statements.', '1) Check that both sides are complete sentences. 2) If they are and are closely related, a semicolon joins them. 3) A comma alone cannot join two sentences. 4) Use a colon only when the first part introduces the second.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dd334863edd745d7', 'act-english', 's-punc', 3, 'Magma does not rise quietly<u>; it</u> cracks the surrounding rock and rattles distant sensors as it forces a path toward the surface.', 'Which choice best conforms to the conventions of standard English punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", it","letter":"B"},{"is_no_change":false,"label":". Because it","letter":"C"},{"is_no_change":false,"label":"it","letter":"D"}]', 'A', '{"A":"Correct: a semicolon may join two closely related independent clauses.","B":"A comma alone between two independent clauses creates a comma splice.","C":"''Because'' turns the second statement into a subordinate clause left standing alone — a fragment.","D":"Removing all punctuation fuses two complete sentences into a run-on."}', 'A **semicolon** legally joins two related independent clauses, and both halves here can stand alone.', 'The clauses are short and tightly linked, so a comma feels sufficient — but brevity never licenses a splice.', '1) Cover the punctuation and read each side: can both stand alone as sentences? 2) Two independent clauses need a period, a semicolon, or a comma plus a coordinating conjunction. 3) A comma alone = splice; nothing = fused. 4) If a subordinator is added, make sure the clause still attaches to a complete sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e780bc98b4b28c09', 'act-english', 's-punc', 3, 'Every gig bag she packs for an assignment holds <u>three essentials, a</u> water bottle, plain dark clothing, and a backup pair of glasses.', 'Which choice provides the most effective punctuation of the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"three essentials: a","letter":"B"},{"is_no_change":false,"label":"three essentials; a","letter":"C"},{"is_no_change":false,"label":"three essentials such as: a","letter":"D"}]', 'B', '{"A":"A comma after ''essentials'' buries the list in a string of commas, hiding where the announcement ends and the list begins.","B":"Correct — ''Every gig bag ... holds three essentials'' is a complete clause, so a colon may introduce the list it announces.","C":"A semicolon must join two independent clauses; ''a water bottle...'' is a list, not a clause.","D":"''Such as'' flows into its examples and never takes a colon; the phrase also clashes with the exact count ''three.''"}', 'A **colon** may introduce a list only after a complete independent clause, which ''Every gig bag she packs ... holds three essentials'' is.', 'The semicolon looks like a strong list-introducer, but its job is joining clauses, not announcing items.', '1) Read the words before the candidate mark: do they form a complete sentence? 2) If yes and a list or explanation follows, a colon fits. 3) Reject a semicolon unless a full clause follows too. 4) Never place a colon after ''such as,'' ''including,'' or a verb that flows directly into the list.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-eeb2b7c4a9e39f80', 'act-english', 's-punc', 3, 'The robotics club renamed <u>it''s</u> entry an hour before the qualifying round.', 'Which choice is correct before ''entry''?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"it is","letter":"B"},{"is_no_change":false,"label":"its''","letter":"C"},{"is_no_change":false,"label":"its","letter":"D"}]', 'D', '{"A":"''It''s'' means ''it is'' — and ''renamed it is entry'' collapses.","B":"Expanding the contraction proves it wrong: ''renamed it is entry''.","C":"''Its'''' is not a word in any position.","D":"''Its'' is the possessive form, written with no apostrophe."}', 'Possessive ''its'' takes **no apostrophe** — the apostrophe version always means ''it is''.', 'Most possessives DO take apostrophes, so ''it''s'' looks right.', 'Test by expanding: if ''it is'' fails in the slot, write ''its''.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ef7c83c59dea8738', 'act-english', 's-punc', 3, 'She pulled on a <u>warm wool</u> sweater and stepped into the sleet.', 'Which choice handles the adjectives before ''sweater'' correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"warm, wool","letter":"B"},{"is_no_change":false,"label":"warm, wool,","letter":"C"},{"is_no_change":false,"label":"warm and wool","letter":"D"}]', 'A', '{"A":"''Warm'' describes the wool sweater as a unit — stacked (cumulative) adjectives take no comma.","B":"The swap test fails (''wool warm sweater''?) — these adjectives aren''t coordinate, so no comma.","C":"A comma between the last adjective and its noun is never correct.","D":"''And'' only joins adjectives that could trade places — these can''t."}', 'These adjectives **stack**: ''warm'' modifies ''wool sweater'' as a whole, so no comma.', 'Two adjectives in a row look like the comma-separated kind at a glance.', 'Comma only between adjectives that pass the swap/''and'' test; cumulative adjectives take none.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-018889691813266d', 'act-english', 's-punc', 4, '<u>Sea stars which can regrow lost arms are</u> among the most resilient hunters in the pool.', 'Which choice correctly punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Sea stars, which can regrow lost arms are","letter":"B"},{"is_no_change":false,"label":"Sea stars which can regrow lost arms, are","letter":"C"},{"is_no_change":false,"label":"Sea stars, which can regrow lost arms, are","letter":"D"}]', 'D', '{"A":"The nonrestrictive clause needs commas on both sides; leaving them out runs the modifier into the sentence (missing_nonrestrictive_commas).","B":"This opens the clause with a comma but never closes it, so the modifier bleeds into the verb.","C":"This closes the clause but never opens it, misplacing a single comma before the verb.","D":"Correct: paired commas set off the nonrestrictive clause ''which can regrow lost arms.''"}', 'A nonrestrictive ''which'' clause must be **enclosed by a pair of commas**.', 'The single-comma version looks balanced enough that students accept just one.', '1) Find the extra-information clause. 2) Test whether the sentence still makes sense without it. 3) If yes, it is nonrestrictive and needs a comma before and after. 4) Make sure both commas are present.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-03e62278de100d28', 'act-english', 's-punc', 4, 'The blue-ringed <u>octopus which is no larger than a golf ball, carries</u> venom potent enough to kill an adult human.', 'Which choice correctly punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"octopus, which is no larger than a golf ball, carries","letter":"B"},{"is_no_change":false,"label":"octopus, which is no larger than a golf ball carries","letter":"C"},{"is_no_change":false,"label":"octopus which is no larger than a golf ball carries","letter":"D"}]', 'B', '{"A":"Marks only the end of the nonrestrictive clause, leaving its opening boundary without a comma (nonrestrictive_half).","B":"Correct: the extra ''which'' clause is set off by a comma on both sides.","C":"Opens the clause with a comma but never closes it before the main clause resumes (nonrestrictive_half).","D":"Uses no commas at all, so the nonessential clause is not set off (nonrestrictive_missing)."}', 'A **nonrestrictive** clause that adds extra information must be enclosed by a comma at both its start and its finish.', 'The single comma already present makes the sentence look punctuated, so students overlook the missing opening comma.', '1) Test whether the clause can be lifted out without changing the core meaning. 2) If yes, it is nonrestrictive and needs commas on both ends. 3) Check that a comma marks where the clause begins and where it ends. 4) Re-read the main clause without the interruption to confirm it stands.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0871498e14f92745', 'act-english', 's-punc', 4, 'Marcus finished the marathon<u>, his</u> sister cheered from the finish line.', 'Which choice best joins the two independent clauses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":": his","letter":"B"},{"is_no_change":false,"label":"; and, his","letter":"C"},{"is_no_change":false,"label":"; his","letter":"D"}]', 'D', '{"A":"A comma alone between two independent clauses is a comma splice.","B":"A colon promises that the second clause explains or expands the first; the sister''s cheering is a separate event, not an explanation.","C":"A semicolon plus ''and,'' piles two joiners (and a stray comma) where one is needed.","D":"A semicolon is the standard way to join two closely related independent clauses."}', 'Two related independent clauses join with a **semicolon** when no conjunction is used.', 'The comma splice reads smoothly aloud, so the error hides in plain sight.', 'Independent clause + independent clause → semicolon, or comma + coordinating conjunction — never a comma alone.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-08cfb045497c4c57', 'act-english', 's-punc', 4, 'The survey team compared several <u>species'' recovery rates</u> after the storm, noting that the fastest-growing corals had also suffered the heaviest breakage.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"species recovery rates","letter":"B"},{"is_no_change":false,"label":"species''s recovery rates","letter":"C"},{"is_no_change":false,"label":"specie''s recovery rates","letter":"D"}]', 'A', '{"A":"''Species'' is both singular and plural; here it is the plural possessor, so a plural possessive apostrophe after the final ''s'' is correct.","B":"Omitting the apostrophe drops the possession the sentence needs — the rates belong to the species (misconception: missing_possessive_apostrophe).","C":"Adding ''s after a word already ending in ''s'' overworks the possessive for this plural form (misconception: double_s_possessive).","D":"''Specie'' means coined money, not an organism; the singular of the biological term is still ''species'' (misconception: false_singular_backformation)."}', '''Species'' spelled the same in singular and plural takes a **plural possessive** apostrophe after its final ''s'' when several species possess the rates.', 'Because ''species'' looks singular, students reach for ''s or invent ''specie,'' not realizing the word is already plural here.', '1) Decide whether the possessor is singular or plural in meaning. 2) Note that ''species'' keeps the same spelling for both. 3) For a plural possessor ending in ''s,'' add only an apostrophe after that ''s.'' 4) Never invent a new singular (''specie'') or double the ''s'' for a word already ending in one.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-157d08701824d9f0', 'act-english', 's-punc', 4, 'The Ledger''s oldest <u>machine, a 1948 flatbed press that once printed ration books,</u> still turns out the holiday edition every December.', 'Which choice best conforms to the conventions of standard English punctuation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"machine, a 1948 flatbed press that once printed ration books","letter":"B"},{"is_no_change":false,"label":"machine a 1948 flatbed press that once printed ration books,","letter":"C"},{"is_no_change":false,"label":"machine, a 1948 flatbed press, that once printed ration books,","letter":"D"}]', 'A', '{"A":"Correct: the nonessential appositive is set off by a matched pair of commas, and the restrictive ''that'' clause stays glued to ''press.''","B":"Opens the appositive but never closes it before the main clause resumes at ''still.''","C":"Closes an interruption that was never opened, leaving ''machine a 1948 flatbed press'' run together.","D":"Adds an extra comma that severs the restrictive ''that'' clause from the noun it defines."}', 'A nonessential appositive needs **paired commas** — one at its entrance, one at its exit — with no comma inside splitting the ''that'' clause from ''press.''', 'Dropping the second comma tempts students because the pause feels finished once the description ends.', '1) Find the interrupting description. 2) Test it: delete the phrase — if the sentence still works, it is nonessential. 3) Give a nonessential interrupter punctuation on BOTH sides. 4) Check that no comma separates a noun from a ''that'' clause that defines it. 5) Re-read with the phrase removed to confirm the frame is matched.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1a827341845d348b', 'act-english', 's-punc', 4, 'Applicants for the Courier''s summer internship <u>must bring:</u> a notebook, two clippings of their own writing, and a pen that works.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"must bring;","letter":"B"},{"is_no_change":false,"label":"must bring,","letter":"C"},{"is_no_change":false,"label":"must bring","letter":"D"}]', 'D', '{"A":"Places a colon between a verb and its objects; a colon requires a complete statement before it.","B":"Uses a semicolon to introduce a list, but semicolons join independent clauses.","C":"Inserts an unnecessary comma between the verb and the items it governs.","D":"Correct: the list completes the verb ''bring,'' so no punctuation belongs at that spot."}', 'The list is the **direct object** of ''bring,'' so the verb should flow straight into it with no mark at all.', 'The colon tempts students trained to put a colon before every list, whether or not a complete clause precedes it.', '1) Cover everything after the possible colon spot. 2) Ask: is what remains a complete, standalone statement? 3) If yes, a colon may introduce the list; if no, use no mark. 4) Never let any mark separate a verb from its objects. 5) Re-read the sentence straight through to confirm the flow.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1c660fa8c556af93', 'act-english', 's-punc', 4, 'Black-crowned night herons<u>, a species once nearly absent from the harbor</u> now hunt beside the ferry slips after dark.', 'Which choice best punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":" a species once nearly absent from the harbor","letter":"B"},{"is_no_change":false,"label":", a species, once nearly absent from the harbor,","letter":"C"},{"is_no_change":false,"label":", a species once nearly absent from the harbor,","letter":"D"}]', 'D', '{"A":"Opens the nonessential appositive with a comma but never closes it before the main verb (unpaired_comma).","B":"Runs the appositive straight into the subject with no punctuation, treating removable background as if it were essential (missing_appositive_commas).","C":"An extra comma after ''species'' chops one appositive phrase into two pieces (comma_inside_appositive).","D":"Correct: the removable renaming phrase is fenced by a matching pair of commas."}', 'A nonessential appositive must be set off by a **pair** of commas — one at each boundary of the phrase.', 'The original already has one comma, so the sentence sounds punctuated and students never check for the closing partner.', '1) Cover the phrase between the subject and the main verb. 2) If the sentence still works, the phrase is nonessential. 3) Nonessential phrases take commas at both edges — count them. 4) Make sure no comma lands inside the phrase itself. 5) Re-read with the phrase removed and again with it included.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1d0c1fcd1b81f638', 'act-english', 's-punc', 4, 'Our faculty adviser<u> a retired machinist from the aerospace plant</u> inspects every weld on the frame before the robot leaves the shop.', 'Which choice correctly punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", a retired machinist from the aerospace plant","letter":"B"},{"is_no_change":false,"label":", a retired machinist from the aerospace plant,","letter":"C"},{"is_no_change":false,"label":", a retired machinist, from the aerospace plant","letter":"D"}]', 'C', '{"A":"Runs the appositive straight into the subject with no punctuation at all (appositive_unmarked).","B":"Opens the appositive with a comma but never closes it before the verb (comma_half_paired).","C":"Correct: paired commas set off the entire nonessential appositive at both of its boundaries.","D":"Drops a comma inside the phrase, splitting one description in half (comma_inside_phrase)."}', 'The appositive is nonessential, so it needs **paired commas** at both of its outer boundaries.', 'The single-comma version tempts readers who feel a pause going into the phrase but not coming out.', '1) Lift the phrase out; if the sentence still works, the phrase is nonessential. 2) Mark the phrase''s exact start and end. 3) Place matching commas at both edges — never inside the phrase.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1d49f68414cb95b8', 'act-english', 's-punc', 4, 'The incoming condition report lists three separate concerns<u>: flaking paint,</u> a warped panel, and mold along the frame''s lower edge.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; flaking paint,","letter":"B"},{"is_no_change":false,"label":", flaking paint,","letter":"C"},{"is_no_change":false,"label":": flaking paint;","letter":"D"}]', 'A', '{"A":"Correct: a complete clause precedes the list, so a colon properly introduces the three items, which commas then separate.","B":"A semicolon joins two independent clauses; a list of noun phrases is not a clause.","C":"A comma here makes the sentence read as a four-item series, blurring the announced three concerns into the list itself.","D":"Mixing a semicolon after the first item with a comma later makes the separators inconsistent for simple items."}', 'A **colon after a complete clause** is the standard way to introduce a list, with commas separating simple items.', 'Students often ''downgrade'' a correct colon to a semicolon because both look formal, forgetting the semicolon''s clause-joining job.', '1) Check the words before the mark: do they form a complete sentence? 2) If yes and a list or explanation follows, a colon is the introducing mark. 3) Semicolons are reserved for joining independent clauses or separating list items that themselves contain commas. 4) Keep item separators consistent: all commas for simple items. 5) If the original already satisfies these tests, leave it alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-24344ba26513cfcf', 'act-english', 's-punc', 4, 'Rehearsal ran long<u>, however,</u> nobody left before the final scene was blocked.', 'Which choice punctuates ''however'' between the two statements correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; however,","letter":"B"},{"is_no_change":false,"label":"; however","letter":"C"},{"is_no_change":false,"label":", however;","letter":"D"}]', 'B', '{"A":"''However'' between commas can''t hold two clauses together — that''s still a splice.","B":"Semicolon before and comma after is how ''however'' bridges two clauses.","C":"The comma ''however'' takes after itself is missing.","D":"The marks are reversed — the heavy mark goes before the bridge word."}', 'Clause **; however,** clause — semicolon before, comma after.', '''However'' feels like ''but'', which really does take just a comma.', 'Conjunctive adverbs (however, therefore, meanwhile) joining clauses take '';'' before and '','' after.', 'underlined-span-mc', '''However'' feels like ''but'', which really does take just a comma', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-293fb888d3a5d2c5', 'act-english', 's-punc', 4, 'Silver tarnishes rapidly in open air<u>, consequently, the medals</u> in the trophy case are stored with strips of anti-tarnish paper.', 'Which choice punctuates the underlined portion correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; consequently, the medals","letter":"B"},{"is_no_change":false,"label":"; consequently; the medals","letter":"C"},{"is_no_change":false,"label":": consequently, the medals","letter":"D"}]', 'B', '{"A":"Two independent clauses joined by a conjunctive adverb with only commas form a comma splice.","B":"Correct: a semicolon joins the two independent clauses, and a comma follows the conjunctive adverb.","C":"The second semicolon wrongly cuts the conjunctive adverb off from its own clause.","D":"A colon introduces an explanation or list; it cannot substitute for the clause-joining mark before a conjunctive adverb."}', 'Words like ''consequently'' are **conjunctive adverbs**, not conjunctions, so the clauses they link need a semicolon before the adverb and a comma after it.', 'Because ''consequently'' feels like a connector, students believe a comma before it is enough to join the clauses.', '1) Test each side of the connector: can it stand alone as a sentence? 2) If both sides are independent, a comma alone cannot join them. 3) Conjunctive adverbs (however, therefore, consequently) take a semicolon BEFORE and a comma AFTER. 4) Reject any option that puts the heavy mark after the adverb or swaps in a mark that introduces rather than joins.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2ef3017dbd5bc21b', 'act-english', 's-punc', 4, '<u>The ballads — many collected in remote mountain towns, were</u> entirely new to the city audiences who first heard them on reissued records.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The ballads, many collected in remote mountain towns — were","letter":"B"},{"is_no_change":false,"label":"The ballads — many collected in remote mountain towns were","letter":"C"},{"is_no_change":false,"label":"The ballads — many collected in remote mountain towns — were","letter":"D"}]', 'D', '{"A":"Opening the interruption with a dash but closing it with a comma mismatches the pair.","B":"Opening with a comma and closing with a dash is the same mismatch in reverse.","C":"The dash opens the aside, but nothing ever closes it, so the interruption bleeds into the main clause.","D":"Correct: a parenthetical interruption opened with a dash must be closed with a matching dash."}', 'An interrupting phrase inside a sentence needs **matching punctuation** on both ends — dash with dash.', 'The dash-comma hybrid tempts students because each mark alone can set off an aside, and the mismatch is easy to miss mid-sentence.', '1) Bracket the interrupting phrase with your fingers and read the sentence without it — it should still work. 2) Look at the mark before the interruption. 3) Look at the mark after it. 4) Make the two marks match (both dashes, both commas, or both parentheses). 5) Re-read with the aside included.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-31665b0a1bd7961d', 'act-english', 's-punc', 4, 'The trail''s last water source <u>(a spring that runs dry by August</u> sits two miles below the summit.', 'Which choice handles the parenthetical about the spring correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"(a spring that runs dry by August)","letter":"B"},{"is_no_change":false,"label":"a spring that runs dry by August)","letter":"C"},{"is_no_change":false,"label":"(a spring that runs dry by August,","letter":"D"}]', 'B', '{"A":"The opening parenthesis never closes.","B":"Parentheses close what they open — the aside is sealed on both ends.","C":"This closes an aside that never opened.","D":"A comma can''t stand in for the closing parenthesis."}', '**Parentheses travel in pairs** — every opener needs its closer.', 'By the end of a long aside it''s easy to forget the bracket is still open.', 'Whatever opens an aside (comma, dash, parenthesis) must be matched at its close.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3f067badd58987d9', 'act-english', 's-punc', 4, 'The storm knocked out the scoreboard<u>, the</u> referees kept score on a clipboard.', 'Which choice repairs the join between the two statements?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":" so the","letter":"B"},{"is_no_change":false,"label":" the","letter":"C"},{"is_no_change":false,"label":"; the","letter":"D"}]', 'D', '{"A":"A comma alone can''t hold two complete thoughts together.","B":"''So'' would need a comma before it; bare, it just smears the join.","C":"Removing the comma fuses the sentences outright.","D":"A semicolon joins the two closely related independent clauses."}', 'Two independent clauses with no conjunction take a **semicolon**.', 'The clauses are so tightly related that a comma feels sufficient.', 'Comma-splice fixes: semicolon, period, or comma + FANBOYS — never a comma alone.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-417d928a249d4bec', 'act-english', 's-punc', 4, 'The quota system <u>which</u> limits raft launches on the Colorado River each day protects the canyon''s famous quiet.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", which","letter":"B"},{"is_no_change":false,"label":"who","letter":"C"},{"is_no_change":false,"label":"that","letter":"D"}]', 'D', '{"A":"Uses ''which'' without commas for a clause the sentence needs to identify its subject—restrictive clauses take ''that.''","B":"Adds one comma as if the clause were a removable aside, but the sentence needs the clause to say which system is meant, and the aside is never closed.","C":"Applies a pronoun reserved for people to a system.","D":"Introduces the identifying (restrictive) clause with ''that'' and no comma, exactly as required."}', 'The clause **defines which system** is meant, so it is restrictive and takes ''that'' with no comma.', '''Which'' sounds more formal than ''that,'' so students upgrade to it even where the clause is essential.', '1) Delete the clause and re-read. 2) If the sentence loses its meaning or the noun turns vague, the clause is essential. 3) Essential clause: use ''that'' with no commas. 4) Nonessential clause: use comma + ''which'' + comma.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-49679201bbbf2fb9', 'act-english', 's-punc', 4, 'The lighthouse<u> built in 1902 by a crew of eleven</u> still guides boats through the narrows.', 'Which choice sets off the phrase about the lighthouse''s construction correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", built in 1902 by a crew of eleven","letter":"B"},{"is_no_change":false,"label":", built in 1902 by a crew of eleven,","letter":"C"},{"is_no_change":false,"label":" that was built in 1902 by a crew of eleven,","letter":"D"}]', 'C', '{"A":"Extra history about an already-identified lighthouse needs to be set off.","B":"The interrupter opens with a comma but never closes.","C":"Paired commas mark the phrase as droppable background detail.","D":"''That'' frames the detail as restrictive — and still leaves one stray comma."}', 'The phrase adds droppable background about one specific lighthouse → **paired commas**.', 'The phrase sits so close to its noun that it feels built in.', 'Nonrestrictive (extra) modifiers take commas on both sides; restrictive ones take none.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-581a7c98b2ac9090', 'act-english', 's-punc', 4, 'The recipe calls for three <u>ingredients flour</u>, sugar, and butter.', 'Which choice correctly punctuates the introduction of the list?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"ingredients; flour","letter":"B"},{"is_no_change":false,"label":"ingredients: flour","letter":"C"},{"is_no_change":false,"label":"ingredients'', flour","letter":"D"}]', 'C', '{"A":"With no punctuation, the list runs into the noun it names — readers can''t tell where ''ingredients'' ends and the list begins.","B":"A semicolon separates two independent clauses; it cannot introduce a list.","C":"A colon after a complete statement introduces the list it promises: three ingredients — then names them.","D":"''ingredients'''' adds a possessive apostrophe nothing in the sentence calls for."}', 'A **colon** follows a complete statement to introduce the list it announces.', 'The sentence reads smoothly aloud, so the missing punctuation is easy to skate past.', 'Use a colon — never a semicolon — after a complete clause to introduce a list.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a3080de4ef5c33a', 'act-english', 's-punc', 4, 'A pair of bald eagles has rebuilt the same nest each winter for a decade. By late March of this year, the <u>eagles nest</u> on the river bluff had grown to nearly a ton of stacked branches.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"eagle''s nests","letter":"B"},{"is_no_change":false,"label":"eagles''s nest","letter":"C"},{"is_no_change":false,"label":"eagles'' nest","letter":"D"}]', 'D', '{"A":"With no apostrophe, ''eagles nest'' reads as a plural noun plus a verb rather than as ownership.","B":"Places the apostrophe for a single owner and wrongly pluralizes the nest, though the passage describes two birds sharing one nest.","C":"Plural nouns already ending in s take only an apostrophe, not an added apostrophe-s.","D":"Correct: the plural owners (the pair) take an apostrophe after the s, and the single nest stays singular."}', 'Two owners and one owned thing call for the **plural possessive** — apostrophe after the s, singular noun following.', 'The apostrophe-before-s habit is so automatic that students apply the singular pattern even when the passage clearly names a pair.', '1) Rephrase as ''the ___ of the ___'' to confirm possession. 2) Count the owners. 3) One owner: apostrophe before s. 4) Plural owners ending in s: apostrophe after s, nothing added. 5) Check that the owned noun keeps its true number.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6e8ee0e1f7c800f7', 'act-english', 's-punc', 4, 'Ravenswood''s head beekeeper<u>, Tomas Rivera checks</u> the hives every Sunday morning before the gates open.', 'Which choice correctly punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", Tomas Rivera, checks","letter":"B"},{"is_no_change":false,"label":"Tomas Rivera, checks","letter":"C"},{"is_no_change":false,"label":", Tomas Rivera, checks,","letter":"D"}]', 'B', '{"A":"Half a frame: the appositive opens with a comma but never closes, stranding the subject from its verb.","B":"Correct: paired commas fully enclose the nonessential name, leaving the main clause intact.","C":"A lone comma after the name slices between the sentence''s subject and its verb.","D":"The pair around the name is right, but the third comma splits the verb from its object."}', 'A nonessential appositive must be enclosed by a **pair** of commas — one before the name and one after — with no extra mark beyond the pair.', 'The single opening comma in the original sounds like a natural pause, so students never check whether the interrupter was closed off.', '1) Identify the interrupting element — here, the name renaming the subject. 2) Test removability: read the sentence without it; if the sentence still works, the element is nonessential. 3) Enclose a nonessential element with commas on both sides. 4) Then sweep the rest of the clause: no comma may separate subject from verb or verb from object. 5) Reread the punctuated sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7e0b194c1e8733c7', 'act-english', 's-punc', 4, 'Mr. Okafor<u>, he is the school''s athletic trainer,</u> keeps a scrapbook of every season since 1998.', 'Which choice correctly folds the trainer detail into the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", the school''s athletic trainer,","letter":"B"},{"is_no_change":false,"label":" the school''s athletic trainer","letter":"C"},{"is_no_change":false,"label":", he, the school''s athletic trainer,","letter":"D"}]', 'B', '{"A":"''Mr. Okafor, he is ...'' jams a whole clause where an appositive belongs.","B":"The bare noun phrase renames him cleanly between commas.","C":"Without commas, the phrase collides with the name it renames.","D":"Doubling the subject doubles the clutter."}', 'To tuck a fact inside a sentence, use an **appositive phrase**, not a full clause.', 'The original clause is perfectly grammatical — just not inside another sentence.', 'Rename with a comma-wrapped phrase; save ''he is'' for a separate sentence.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-85a7f2259e04e208', 'act-english', 's-punc', 4, 'The main cable<u>&mdash;a bundle of thousands of pencil-thin wires,</u> was spun in place high above the water.', 'Which choice best punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", a bundle of thousands of pencil-thin wires—","letter":"B"},{"is_no_change":false,"label":"—a bundle of thousands of pencil-thin wires","letter":"C"},{"is_no_change":false,"label":"—a bundle of thousands of pencil-thin wires—","letter":"D"}]', 'D', '{"A":"Opens the appositive with a dash but closes it with a comma, mixing two styles around one interrupter (misconception: paired_punct_mismatch_open).","B":"Reverses the same mismatch, entering with a comma and exiting with a dash (misconception: paired_punct_mismatch_close).","C":"Never closes the interrupter, so the appositive runs straight into the verb and garbles the main clause (misconception: paired_punct_unclosed).","D":"Encloses the appositive in matching dashes, letting the main clause reconnect cleanly on both sides."}', 'Paired punctuation must **match**: whatever mark opens an interrupting appositive must also close it.', 'The unclosed version reads smoothly aloud, so students miss that the verb has been swallowed into the description of the wires.', '1) Bracket the interrupting phrase from its first word to its last. 2) Read the sentence without it — the remainder must be complete. 3) Check the mark at the entrance and the mark at the exit. 4) If they differ or one is missing, fix them to match. 5) Reread with the interrupter restored.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-900e65a3457eb2b4', 'act-english', 's-punc', 4, 'Every August the Harris family hosts a swap meet for collectors, and folding tables of Bakelite sets crowd <u>the Harris'' lawn</u> from dawn until dusk.', 'Which choice correctly punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the Harris''s lawn","letter":"B"},{"is_no_change":false,"label":"the Harrises lawn","letter":"C"},{"is_no_change":false,"label":"the Harrises'' lawn","letter":"D"}]', 'D', '{"A":"''Harris'''' marks possession on the singular name with a bare apostrophe, but the owners are the whole family, so the name must be pluralized first.","B":"''Harris''s'' is a correct singular possessive, but the sentence credits the entire family, not one person.","C":"''Harrises'' pluralizes the family but includes no apostrophe, so it never shows ownership of the lawn.","D":"Correct: pluralize the name to ''Harrises,'' then add the apostrophe after the s to mark plural possession."}', 'For a family name, **pluralize first, then mark possession**: Harris → Harrises → Harrises''.', 'The bare-apostrophe form looks like the familiar rule for words ending in s, so students apply it to the singular name without ever pluralizing.', '1) Ask who owns the thing: one person or the whole family? 2) Write the correct plural of the name if the family owns it (add -es to names ending in s). 3) Add the possessive mark to that form (apostrophe after the plural s). 4) Reread to confirm both number and ownership are visible.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-926e040affb783e5', 'act-english', 's-punc', 4, '<u>Maya and Jonah''s</u> podcast about minor-league mascots just passed a hundred episodes.', 'Which choice is correct for the podcast the two friends share?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Maya''s and Jonah''s","letter":"B"},{"is_no_change":false,"label":"Maya''s and Jonah","letter":"C"},{"is_no_change":false,"label":"Maya and Jonahs''","letter":"D"}]', 'A', '{"A":"One shared podcast → the apostrophe hangs on the LAST owner only.","B":"Separate apostrophes would signal two separate podcasts.","C":"This marks the first owner and strands the second entirely.","D":"''Jonahs'''' treats the name as a plural that doesn''t exist."}', 'Joint ownership hangs ONE apostrophe on the **final owner**.', 'Two owners feel like they deserve two apostrophes.', 'Shared thing → apostrophe on the last name; separate things → apostrophe on each name.', 'underlined-span-mc', 'two owners feel like they deserve two apostrophes', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9f76fd7997542cc1', 'act-english', 's-punc', 4, 'By late August the tread below the spring had washed out entirely<u>, the crew</u> spent three days rebuilding it with crushed granite.', 'Which choice is most acceptable in standard written English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; the crew","letter":"B"},{"is_no_change":false,"label":" the crew","letter":"C"},{"is_no_change":false,"label":", consequently the crew","letter":"D"}]', 'B', '{"A":"Comma splice: two independent clauses are joined by only a comma, which is too weak to separate complete thoughts.","B":"Correct: a semicolon legally joins two closely related independent clauses without a conjunction.","C":"Fused sentence: removing all punctuation runs the two complete statements together with no boundary at all.","D":"A conjunctive adverb preceded by only a comma still leaves the clauses spliced; ''consequently'' is not a conjunction."}', 'Two related independent clauses may be joined by a **semicolon**, which supplies the full-stop-strength boundary a comma cannot.', 'The ''consequently'' version tempts students who believe adding any linking adverb licenses a comma between complete clauses.', '1) Cover each side of the punctuation and test whether each side is a complete sentence. 2) If both sides are complete, a comma alone is illegal. 3) Join them with a semicolon, a period, or a comma plus a FANBOYS conjunction. 4) Remember that words like ''however'' and ''consequently'' are adverbs, not conjunctions, and cannot glue clauses with a comma.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a519014ae187ac76', 'act-english', 's-punc', 4, 'Passage III — The Mapmaker''s Daughter — Marie Tharp was a geologist who helped change how we see the ocean floor. In the 1950s, working alongside her colleague Bruce Heezen, she plotted thousands of depth measurements collected from ships crossing the Atlantic. At the time, many scientists believed the ocean floor was mostly flat. Tharp''s maps revealed something remarkable, a vast underwater mountain range running down the middle of the Atlantic. <u>This discovery, which supported the then-controversial theory of continental drift,</u> was at first dismissed by Heezen as "girl talk." Eventually, the evidence became impossible to ignore. Tharp''s careful work helped establish the theory of plate tectonics. Today, her once-doubted maps are considered landmarks of earth science.', 'Which choice best handles the underlined parenthetical about the discovery?', '[{"is_no_change":false,"label":"This discovery, which supported the then-controversial theory of continental drift,","letter":"A"},{"is_no_change":false,"label":"This discovery which supported the then-controversial theory of continental drift","letter":"B"},{"is_no_change":false,"label":"This discovery, which supported the then-controversial theory of continental drift","letter":"C"},{"is_no_change":false,"label":"This discovery; which supported the then-controversial theory of continental drift,","letter":"D"}]', 'A', '{"A":"The nonrestrictive clause is correctly set off by a comma on BOTH sides.","B":"With no commas at all, the added detail runs into the sentence unpunctuated.","C":"A leading comma with no closing comma leaves the interrupter half-punctuated.","D":"A semicolon can''t attach a dependent ''which'' clause; it needs an independent clause."}', 'A nonrestrictive **''which''** clause is an interrupter — a comma on each side: ''..., which supported ..., was ...''.', 'The single leading comma looks like enough, so the missing closing comma slips by.', 'Rule focus: Knowledge of Language (NOT-acceptable)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-aea0ef8c35a6d105', 'act-english', 's-punc', 4, 'The trophy that the state <u>federation awards, goes</u> to the highest scorer under eighteen.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"federation awards; goes","letter":"B"},{"is_no_change":false,"label":"federation, awards goes","letter":"C"},{"is_no_change":false,"label":"federation awards goes","letter":"D"}]', 'D', '{"A":"The comma severs the subject ''The trophy that the state federation awards'' from its verb ''goes,'' a break no single comma may make.","B":"A semicolon must join two independent clauses, and ''goes to the highest scorer under eighteen'' cannot stand alone.","C":"This comma slices the inner clause''s subject from its verb, mangling the identifying clause.","D":"No punctuation belongs anywhere in this stretch: the subject flows directly into its verb."}', 'No punctuation may separate a subject from its verb, so the stretch must run **unbroken**.', 'The original comma tempts because the long identifying clause creates a natural spoken pause right before the verb.', '1) Find the main verb. 2) Trace back to the full subject, including any identifying clause attached to it. 3) Confirm no comma or semicolon stands between subject and verb. 4) Reread the sentence without pausing to verify it flows as one clause.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-af86c1bda07ec259', 'act-english', 's-punc', 4, 'The final stretch of the relay<u> the part everyone dreads </u>is a hill with no shade.', 'Which choice sets off the aside about the relay correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", the part everyone dreads — ","letter":"B"},{"is_no_change":false,"label":" — the part everyone dreads, ","letter":"C"},{"is_no_change":false,"label":" — the part everyone dreads — ","letter":"D"}]', 'D', '{"A":"The aside needs marks to lift it out of the main sentence.","B":"A comma that opens can''t be closed by a dash.","C":"A dash that opens can''t be closed by a comma.","D":"Matched dashes frame the interruption on both sides."}', 'An abrupt aside takes **matched dashes** — the same mark on both sides.', 'One dash feels dramatic enough, and the closing partner gets forgotten.', 'Interrupters pair their marks: two commas, two dashes, or two parentheses — never a mix.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b748115fcfa77e33', 'act-english', 's-punc', 4, 'Early jazz drummers assembled their kits from whatever novelties they could <u>find: such as</u> woodblocks, cowbells, and toy whistles.', 'Which choice is most acceptable for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"find, such as","letter":"B"},{"is_no_change":false,"label":"find; such as","letter":"C"},{"is_no_change":false,"label":"find. Such as","letter":"D"}]', 'B', '{"A":"colon_double_introducer: a colon already means ''namely,'' so stacking it on *such as* doubles the list-introducing job.","B":"Correct: *such as* introduces the examples and takes only a comma before it.","C":"A semicolon must join two independent clauses, and the *such as* phrase is not a clause.","D":"A period strands the *such as* phrase as a fragment."}', '**Such as** already introduces the examples, so only a comma belongs before it.', 'Students learn ''colon = list coming'' and apply it even when an introducing phrase is already doing that job.', '1) Find the words that introduce the list. 2) If *such as*, *including*, or *like* is present, put a comma before it and nothing after it. 3) Use a colon only when the examples follow the introducing clause *directly*, with no such phrase. 4) Reread both ways to hear the difference.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bf0eeaf4adb7ca27', 'act-english', 's-punc', 4, 'One backstage rule<u>—never touch another actor''s prop, is</u> drilled into the crew at every rehearsal.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"—never touch another actor''s prop) is","letter":"B"},{"is_no_change":false,"label":"—never touch another actor''s prop is","letter":"C"},{"is_no_change":false,"label":"—never touch another actor''s prop—is","letter":"D"}]', 'D', '{"A":"Opening the interrupter with a dash but closing it with a comma mismatches the pair (paired_punct_mismatch).","B":"A dash cannot be closed by a parenthesis; the two marks never pair with each other (paired_punct_mixed).","C":"With no closing mark at all, the aside crashes into the main verb and the sentence loses its frame (paired_punct_unclosed).","D":"Correct: an interrupter opened with a dash must be closed with a matching dash."}', 'Interrupting phrases require **matching** punctuation on both ends, so a dash must be paired with a dash.', 'The dash-comma version tempts students because both marks can set off extra information, so mixing them feels harmless mid-sentence.', '1) Locate where the interruption begins and where the main clause resumes. 2) Identify the opening mark. 3) Require the identical mark at the close — dashes with dashes, parentheses with parentheses. 4) Cover the interrupter and confirm the remaining sentence stands alone. 5) Reread with the matched pair in place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bf5d1ae235ddd90d', 'act-english', 's-punc', 4, 'Sea otters lack the insulating <u>blubber, they rely</u> on unusually dense fur to stay warm in frigid water.', 'Which choice most effectively joins the two clauses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"blubber; they rely","letter":"B"},{"is_no_change":false,"label":"blubber they rely","letter":"C"},{"is_no_change":false,"label":"blubber; and they rely","letter":"D"}]', 'B', '{"A":"Joins two independent clauses with only a comma, creating a comma splice (comma_splice).","B":"Correct: a semicolon properly links two closely related independent clauses.","C":"Runs the two independent clauses together with no punctuation, a fused sentence (fused_sentence).","D":"Adds a coordinating conjunction after a semicolon, which is redundant (semicolon_plus_conjunction)."}', 'Two related **independent clauses** can be joined by a semicolon without any conjunction.', 'The comma-spliced original reads smoothly, so students accept the too-weak comma between full sentences.', '1) Check whether each side of the punctuation is a complete sentence. 2) If both are, a comma alone is too weak. 3) Use a semicolon (no conjunction) or a comma plus a conjunction, not a mix. 4) Re-read to confirm the join is clean.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c11dd3fb614958a4', 'act-english', 's-punc', 4, 'At noon on November 18, 1883, dispatchers across the country <u>reset their clocks to the new standard time</u> that the railroads had agreed upon.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"reset their clocks, to the new standard time","letter":"B"},{"is_no_change":false,"label":"reset, their clocks to the new standard time","letter":"C"},{"is_no_change":false,"label":"reset their clocks to the new, standard time","letter":"D"}]', 'A', '{"A":"Correct: the verb, its object, and the completing phrase form one unbroken unit that needs no internal punctuation.","B":"The comma severs the verb phrase from the prepositional phrase that completes its meaning.","C":"A comma between the verb ''reset'' and its object ''their clocks'' interrupts the sentence''s core.","D":"''Standard time'' is a fixed unit that ''new'' modifies as a whole, so no comma can split the adjectives."}', 'No punctuation belongs anywhere in this span, because verb, object, and completing phrase form **one continuous unit**.', 'The comma before ''to the new standard time'' mimics a natural breath pause, which many students mistake for a required comma.', '1) Locate the verb, its object, and any phrase completing the verb''s meaning. 2) For each comma a choice adds, name the two parts it separates. 3) If it splits verb from object, verb from complement, or an adjective from a fixed noun unit, reject it. 4) Keep punctuation only where a true grammatical boundary exists.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d00c88eb04925f05', 'act-english', 's-punc', 4, 'Thousands of crows funnel into the courthouse plaza at <u>dusk, the</u> roost has occupied the same three blocks for decades.', 'Which of the following choices punctuates the sentence correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"dusk the","letter":"B"},{"is_no_change":false,"label":"dusk; the","letter":"C"},{"is_no_change":false,"label":"dusk; although the","letter":"D"}]', 'C', '{"A":"Joins two independent clauses with only a comma, producing a comma splice (comma_splice).","B":"Removes even the comma, fusing the two independent clauses together (fused_sentence).","C":"Correct: a semicolon legally joins two closely related independent clauses.","D":"The subordinator turns the second half into a dependent clause, which cannot follow a semicolon (semicolon_before_dependent)."}', 'Both halves are **independent clauses**, and a semicolon is a legal join for two related independent clauses.', 'The comma splice sounds fine read aloud because the pause feels natural, so students never test whether each half could stand alone.', '1) Read up to the junction and ask: complete statement? 2) Read after the junction and ask the same. 3) If both halves are independent, join them with a period, a semicolon, or a comma plus a coordinating conjunction — never a comma alone. 4) If one half is dependent, a semicolon is illegal there. 5) Re-read your repaired sentence both ways.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d8e4df4cf9b21bd0', 'act-english', 's-punc', 4, 'When the rapid tiebreak finally ended, the arbiter collected both <u>grandmaster''s scoresheets</u> for the federation archive.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"grandmasters scoresheets","letter":"B"},{"is_no_change":false,"label":"grandmasters'' scoresheets","letter":"C"},{"is_no_change":false,"label":"grandmasters'' scoresheet''s","letter":"D"}]', 'C', '{"A":"The apostrophe before the s marks a single owner, but ''both'' tells us two players own the scoresheets.","B":"With no apostrophe at all, nothing signals that the scoresheets belong to the players.","C":"Two owners require the plural possessive: the apostrophe follows the plural -s of the owners, and the owned noun stays a plain plural.","D":"The owned noun ''scoresheets'' possesses nothing, so it takes no apostrophe of its own."}', 'With two owners, the **plural possessive** places the apostrophe after the plural -s.', 'The singular possessive tempts because ''grandmaster''s'' looks routine and the word ''both'' sits far enough away to be overlooked.', '1) Count the owners (the word ''both'' says two). 2) Write the owners'' plural form first. 3) Add the apostrophe after the plural -s. 4) Check the owned noun: if it owns nothing, leave it a plain plural.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-db9840afb1179d6e', 'act-english', 's-punc', 4, 'The aquarium''s newest exhibit features three apex <u>predators; a great white shark, a tiger shark, and a mako.</u>', 'Which choice correctly punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"predators, a great white shark, a tiger shark, and a mako.","letter":"B"},{"is_no_change":false,"label":"predators: a great white shark, a tiger shark, and a mako.","letter":"C"},{"is_no_change":false,"label":"predators, including: a great white shark, a tiger shark, and a mako.","letter":"D"}]', 'C', '{"A":"Uses a semicolon, which joins two independent clauses, but what follows is a list, not a clause (semicolon_for_list).","B":"A comma is too weak to introduce a list after a complete clause (comma_for_list).","C":"Correct: a colon follows a complete independent clause to introduce the list.","D":"Places a colon after ''including,'' breaking a phrase that is not yet complete (colon_midphrase)."}', 'A **colon** introduces a list only when a complete independent clause comes before it.', 'The semicolon looks formal and students associate it with ''serious'' punctuation, misapplying it to a list.', '1) Check that the words before the punctuation form a complete sentence. 2) If a list follows, introduce it with a colon. 3) Do not use a semicolon (for clauses) or a bare comma (too weak). 4) Never put a colon in the middle of an unfinished phrase.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dfeec7883fdaf678', 'act-english', 's-punc', 4, 'By 1900, the <u>companys</u> flagship express was covering the run from London to Edinburgh in under nine hours.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"company''s","letter":"B"},{"is_no_change":false,"label":"companies","letter":"C"},{"is_no_change":false,"label":"companies''","letter":"D"}]', 'B', '{"A":"''Companys'' is not a word; a possessive requires an apostrophe.","B":"Correct: one company owns the flagship express, so the singular possessive with the apostrophe before the s is right.","C":"''Companies'' is a simple plural and shows no ownership of the express.","D":"''Companies'''' marks possession by several companies, but the sentence describes a single owner''s flagship."}', 'One owner plus ownership demands the **singular possessive**: apostrophe before the s.', 'The plural possessive lures students who see an s and assume more than one owner without checking the sentence''s logic.', '1) Ask: does the noun own the thing that follows? 2) If yes, count the owners. 3) One owner: add apostrophe + s to the singular. 4) Multiple owners: form the plural first, then add the apostrophe. 5) Reread to confirm the number matches the sentence''s meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e8c3c5c0ab46de38', 'act-english', 's-punc', 4, 'A June thunderstorm overwhelmed the rain <u>barrels, water</u> pooled ankle-deep along the gravel paths by morning.', 'Which choice correctly joins the two parts of this sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"barrels; water","letter":"B"},{"is_no_change":false,"label":"barrels; and water","letter":"C"},{"is_no_change":false,"label":"barrels water","letter":"D"}]', 'B', '{"A":"Comma splice: a comma alone cannot join two independent clauses.","B":"Correct: a semicolon legally joins two closely related independent clauses.","C":"Mixed strategy: the semicolon already joins the clauses, so tacking on a coordinating conjunction doubles the connector.","D":"Fused sentence: two independent clauses run together with no boundary at all."}', 'Two related independent clauses may be joined by a **semicolon** standing alone between them.', 'The comma splice sounds like a natural breath, so students accept it without testing whether each half could stand alone as a sentence.', '1) Cover everything after the underlined joint and ask: could the first half stand alone as a sentence? 2) Do the same for the second half. 3) If both stand alone, join them with a period, a semicolon, or a comma plus a coordinating conjunction — never a comma alone, never nothing. 4) Use exactly one joining strategy, not a mix. 5) Reread the joined sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ec2124e42f09a80c', 'act-english', 's-punc', 4, 'Every camper packs the same three essentials<u>;</u> water, sun protection, and a whistle.', 'Which punctuation mark belongs before the list of essentials?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":".","letter":"B"},{"is_no_change":false,"label":",","letter":"C"},{"is_no_change":false,"label":":","letter":"D"}]', 'D', '{"A":"A semicolon needs a complete clause on each side — a list isn''t one.","B":"A period strands the list as a fragment.","C":"A comma tangles the list into the clause that announces it.","D":"The complete statement hands off to its promised list with a colon."}', 'Complete statement + list → **colon** delivers the items the sentence promised.', 'Semicolons and colons blur together as ''formal marks before lists''.', 'A colon introduces a list only after a complete statement; a semicolon never introduces a list.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ed156bac158d1855', 'act-english', 's-punc', 4, 'The thermal drill<u>&mdash;a two-ton rig flown in by helicopter,</u> melted its way toward the bedrock at four meters an hour.', 'Which choice provides the best punctuation for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", a two-ton rig flown in by helicopter—","letter":"B"},{"is_no_change":false,"label":"—a two-ton rig flown in by helicopter—","letter":"C"},{"is_no_change":false,"label":", a two-ton rig flown in by helicopter","letter":"D"}]', 'C', '{"A":"The aside opens with a dash but closes with a comma; paired punctuation must match (mismatched pair).","B":"This version reverses the mismatch, opening with a comma and closing with a dash (mismatched pair, mirrored).","C":"The interrupter opens and closes with the same mark — a matched pair of dashes — so it is correctly fenced.","D":"A comma opens the aside, but nothing closes it before the verb, leaving the interrupter unfenced (missing closing mark)."}', 'An interrupting appositive must be enclosed by a **matched pair** — dash with dash or comma with comma, never mixed.', 'Readers register that some punctuation frames the aside and overlook that the opening and closing marks disagree.', '1) Bracket the interrupter with your fingers. 2) Identify the mark at its entrance. 3) Identify the mark at its exit. 4) If they differ, the pair is broken: make both the same mark. 5) Confirm the sentence reads cleanly with the aside deleted.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f353d63071548ccf', 'act-english', 's-punc', 4, 'The <u>dancers costumes</u> hung along the mirror wall, each tagged with a scene number.', 'Which choice shows that the costumes belong to the dancers?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"dancers'' costumes","letter":"B"},{"is_no_change":false,"label":"dancer''s costumes","letter":"C"},{"is_no_change":false,"label":"dancers''s costumes","letter":"D"}]', 'B', '{"A":"Two plain nouns in a row leave the ownership unmarked.","B":"A plural owner ending in s takes its apostrophe after the s.","C":"This puts every costume in the hands of a single dancer.","D":"Adding ''s after a plural s (''dancers''s'') is never correct."}', 'Plural owners that already end in s add **just the apostrophe**.', 'The singular ''s pattern is so common it gets pasted onto plurals.', 'Singular owner → ''s; plural owners ending in s → s'' (apostrophe alone).', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f50e13875a30e4dd', 'act-english', 's-punc', 4, 'A well-stocked spice drawer rewards the patient cook with one essential <u>virtue: freshness,</u> since ground spices surrender their aroma within months.', 'Which choice uses punctuation correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"virtue; freshness,","letter":"B"},{"is_no_change":false,"label":"virtue: freshness","letter":"C"},{"is_no_change":false,"label":"virtue, freshness,","letter":"D"}]', 'C', '{"A":"Extra comma: the colon correctly introduces ''freshness,'' but the trailing comma wrongly splits it from the clause that explains it.","B":"Wrong mark: a semicolon must join two independent clauses, yet ''freshness'' is a single word, not a clause.","C":"Correct: a complete clause precedes the colon, and the colon introduces the single item ''freshness'' with no stray comma to break the flow.","D":"Weak substitute: a comma cannot do the announcing work the colon does before a spotlighted term, and the second comma compounds the choppiness."}', 'A colon follows a **complete clause** to spotlight what comes next, and ''freshness'' should flow straight into its explanation with no extra comma.', 'The trailing comma looks like a natural breath before the ''since'' clause, so the original punctuation seems balanced.', '1) Confirm the words before the colon form a complete sentence. 2) Confirm the colon introduces a list, term, or explanation. 3) Do not drop a comma between the introduced term and the clause that modifies it unless grammar demands one. 4) Reserve semicolons for joining two independent clauses. 5) Reread to hear whether the spotlighted term flows into its explanation.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f5f46cf813260d1a', 'act-english', 's-punc', 4, 'Before first light the packer loaded the string with<u>: sacks of grain, boxed rations, and a bundle of new pick handles</u> for the week at the high camp.', 'Which choice best punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"; sacks of grain, boxed rations, and a bundle of new pick handles","letter":"B"},{"is_no_change":false,"label":": sacks of grain, boxed rations and a bundle of new pick handles","letter":"C"},{"is_no_change":false,"label":" sacks of grain, boxed rations, and a bundle of new pick handles","letter":"D"}]', 'D', '{"A":"A colon may introduce a list only after a complete clause; here it interrupts the preposition ''with'' and its objects mid-stream.","B":"A semicolon joins independent clauses or separates complex list items; it cannot introduce a simple list mid-clause.","C":"Keeps the illegal mid-clause colon and also drops the comma before the final list item, stacking a second problem on the first.","D":"Correct: the list flows directly from the preposition, so no introductory punctuation is needed at all."}', 'A list that flows directly from a verb or preposition takes **no introductory punctuation** — the colon requires a complete clause before it.', 'The original tempts students taught that a colon ''introduces lists,'' a half-rule that skips the complete-clause requirement.', '1) Cover everything from the introductory mark onward. 2) If what remains is not a complete sentence, a colon is illegal there. 3) When a list flows directly from a verb or preposition, use no introductory punctuation. 4) Keep the serial comma consistent within the list.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-00d5603f1e869633', 'act-english', 's-punc', 5, 'Passengers<u>, who checked bags,</u> should proceed to carousel four.', 'Which choice tells only the right passengers to go to carousel four?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", which checked bags,","letter":"B"},{"is_no_change":false,"label":" who checked bags","letter":"C"},{"is_no_change":false,"label":" checking bags,","letter":"D"}]', 'C', '{"A":"The commas make the clause apply to ALL passengers — everyone gets sent to the carousel.","B":"''Which'' can''t refer to people, and the commas still over-include.","C":"The restrictive clause limits the instruction to passengers who checked bags.","D":"The half-converted participle drags a stray comma with it."}', 'Dropping the commas makes the clause **restrictive** — only those passengers.', 'Commas feel harmless, but here they change who is being addressed.', 'Commas around the clause = applies to all; no commas = only those. Punctuate the MEANING.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0a01c442026aad79', 'act-english', 's-punc', 5, 'The market''s oldest vendor<u>—a fourth-generation orchardist,</u> still climbs the ladders in his orchard at eighty-two.', 'Which choice is correctly punctuated?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"—a fourth-generation orchardist","letter":"B"},{"is_no_change":false,"label":"(a fourth-generation orchardist,","letter":"C"},{"is_no_change":false,"label":"—a fourth-generation orchardist—","letter":"D"}]', 'D', '{"A":"Opens the interrupter with a dash but closes it with a comma — a mismatched pair (dash_comma_mismatch).","B":"Never closes the interrupter, so the aside collides with the main verb (interrupter_unclosed).","C":"Opens with a parenthesis but closes with a comma, another mismatched frame (paren_comma_mismatch).","D":"Correct — the interrupter opens and closes with the same mark, and the frame sentence reads whole without it."}', 'A mid-sentence interrupter must be **enclosed** by a matched pair of marks — here, a dash on each side.', 'The comma after ''orchardist'' supplies a pause, so the mismatched dash-and-comma frame sounds fine when read aloud.', '1) Bracket the phrase you could lift out of the sentence. 2) Note the mark that opens it. 3) Require the identical mark to close it. 4) Delete the interrupter mentally and confirm the remaining sentence still reads whole. 5) Eliminate any option whose opening and closing marks differ.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-293a6839500a18f6', 'act-english', 's-punc', 5, 'The debate team traveled to Austin<u>, Texas, Portland,</u> Oregon, and Boise, Idaho for the spring circuit.', 'Which choice keeps the three city-state pairs distinct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", Texas: Portland,","letter":"B"},{"is_no_change":false,"label":"; Texas, Portland;","letter":"C"},{"is_no_change":false,"label":", Texas; Portland,","letter":"D"}]', 'D', '{"A":"All-commas makes ''Texas'' and ''Portland'' read as two separate stops.","B":"A colon can''t separate items in a series.","C":"This splits a city from its own state.","D":"Semicolons separate series items that already contain commas."}', 'When series items contain commas, **semicolons** separate the items.', 'Plain commas are the series habit even after the items grow internal commas.', 'Upgrade series separators to semicolons once any item has an internal comma.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-587deb3bbea41fa8', 'act-english', 's-punc', 5, 'It was the current<u> not the wind</u> that pushed the raft off course.', 'Which choice punctuates the contrast correctly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", not the wind,","letter":"B"},{"is_no_change":false,"label":", not the wind","letter":"C"},{"is_no_change":false,"label":"— not the wind","letter":"D"}]', 'B', '{"A":"The ''not X'' contrast is an interrupter and can''t run bare into the sentence.","B":"Antithetical phrases are set off by commas on BOTH sides.","C":"Dropping the closing comma splices the contrast into ''that''.","D":"An opening dash with no closing partner leaves the frame unmatched."}', 'An antithetical phrase (''not the wind'') is set off by a **pair of commas**.', 'The sentence reads smoothly with only the first comma''s pause.', 'Contrastive ''not X'' interrupters take commas before AND after.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b1982b311bbf5fd', 'act-english', 's-punc', 5, 'The bookbinding workshop <u>includes: cleaning</u> leather covers, re-sewing loose bindings, and pressing warped boards.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"includes; cleaning","letter":"B"},{"is_no_change":false,"label":"includes, cleaning","letter":"C"},{"is_no_change":false,"label":"includes cleaning","letter":"D"}]', 'D', '{"A":"A colon may follow only a complete independent clause, and ''The bookbinding workshop includes'' is incomplete without its objects.","B":"A semicolon here severs the verb from its objects; semicolons join two independent clauses.","C":"A comma between a verb and its object list is unnecessary punctuation.","D":"Correct: no mark may separate the verb from the objects it governs."}', 'No punctuation may separate a **verb from its objects**, and the words before the mark do not form a complete clause.', 'Lists feel like they deserve a colon, so students insert one without testing whether the words before it can stand alone.', '1) Find the mark before the list. 2) Read only the words before the mark. 3) If they form a complete stand-alone sentence, a colon is allowed. 4) If they end in a verb or preposition that needs the list to finish the thought, use no punctuation at all. 5) Never separate a verb from its objects with any mark.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-88873e730bb625d7', 'act-english', 's-punc', 5, 'Two of the printers jammed before first period<u>,</u> the third ran out of toner by lunch.', 'Which mark correctly separates the two printer problems?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", moreover","letter":"B"},{"is_no_change":false,"label":":","letter":"C"},{"is_no_change":false,"label":";","letter":"D"}]', 'D', '{"A":"A comma alone splices two complete statements.","B":"''Moreover'' after a comma is still a splice; it would need a semicolon in front.","C":"A colon promises that the second clause explains the first — it only adds a parallel mishap.","D":"A semicolon pairs the two related, parallel failures."}', 'Related complete statements joined without a conjunction take a **semicolon**.', 'The clauses are short and parallel, so the comma feels light and quick.', 'Semicolon = related independent clauses, no conjunction; colon = only when the second part explains the first.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8d400afa766befd4', 'act-english', 's-punc', 5, 'The <u>zoetrope—a spinning drum lined with sequential drawings,</u> delighted parlor audiences decades before cinema existed.', 'Which choice most effectively punctuates the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"zoetrope, a spinning drum lined with sequential drawings—","letter":"B"},{"is_no_change":false,"label":"zoetrope—a spinning drum lined with sequential drawings—","letter":"C"},{"is_no_change":false,"label":"zoetrope a spinning drum lined with sequential drawings,","letter":"D"}]', 'C', '{"A":"The appositive opens with a dash but closes with a comma — mismatched bookends.","B":"Opening with a comma and closing with a dash mixes the two systems in the other direction.","C":"Matching dashes set off the appositive on both sides, and the remaining sentence reads cleanly without it.","D":"The appositive''s start is unmarked, so readers get no signal that the main sentence has been interrupted."}', 'Paired interrupters must use **matching punctuation** on both ends — dash with dash.', 'The dash-then-comma original sounds fine aloud because both marks create pauses, hiding the mismatch on the page.', '1) Bracket the insertable phrase and remove it; the sentence must still work. 2) Look at the mark before it and the mark after it. 3) Make both marks the same kind (two commas, two dashes, or parentheses). 4) Reject any mixed pair or missing side.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a8faee19068a0769', 'act-english', 's-punc', 5, 'The judges compared <u>Priya and Marcus''s</u> essays before choosing a winner.', 'Which choice is correct for essays each student wrote separately?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Priya''s and Marcus''s","letter":"B"},{"is_no_change":false,"label":"Priya and Marcus''","letter":"C"},{"is_no_change":false,"label":"Priya''s and Marcus","letter":"D"}]', 'B', '{"A":"A single apostrophe on the last name claims one co-written set of essays.","B":"Separately owned essays give EACH owner an apostrophe.","C":"Still one owner marked — and ''Marcus'''' drops the s his singular name needs.","D":"The second owner is left with no possessive at all."}', 'Separately owned things give **each owner** an apostrophe.', 'The joint-ownership pattern (last name only) gets over-applied to every pair.', 'Ask shared-or-separate: shared → last owner only; separate → every owner marked.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a9fe78e59aae3959', 'act-english', 's-punc', 5, 'After the blackout, the theater made one change<u>; battery-powered</u> exit signs in every stairwell.', 'Which choice correctly introduces what the change was?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":": battery-powered","letter":"B"},{"is_no_change":false,"label":", it added battery-powered","letter":"C"},{"is_no_change":false,"label":" battery-powered","letter":"D"}]', 'B', '{"A":"A semicolon requires an independent clause on both sides — the right side is a phrase.","B":"The colon presents the change the clause just promised.","C":"''It added ...'' after only a comma splices two clauses.","D":"Fusing leaves ''change battery-powered exit signs'' unreadable."}', 'A complete clause announcing something hands off with a **colon** — even to a phrase.', 'Semicolon and colon look interchangeable at the pivot of a sentence.', 'Colon: complete clause before, anything after. Semicolon: complete clauses on BOTH sides.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b848acac3943750d', 'act-english', 's-punc', 5, 'The <u>childrens''</u> mural stretches down the hallway outside the art room.', 'Which choice is the correct possessive for the young artists?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"children","letter":"B"},{"is_no_change":false,"label":"childrens","letter":"C"},{"is_no_change":false,"label":"children''s","letter":"D"}]', 'D', '{"A":"''Childrens'' isn''t a word — the apostrophe lands after a fake plural.","B":"The bare plural drops the ownership the sentence asserts.","C":"No apostrophe means no possession, and the fake plural remains.","D":"Irregular plurals form possessives with ''s, just like singulars."}', 'Irregular plurals (children, women, mice) form possessives with **''s**, not s''.', 'The plural-ends-in-s rule (s'') gets forced onto plurals that never end in s.', 'If the plural doesn''t end in s, add ''s: children''s, women''s, geese''s.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c8008fbede6fb545', 'act-english', 's-punc', 5, 'A well-stocked dye garden <u>supplies: madder</u> for reds, woad for blues, and weld for yellows.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"supplies, madder","letter":"B"},{"is_no_change":false,"label":"supplies; madder","letter":"C"},{"is_no_change":false,"label":"supplies madder","letter":"D"}]', 'D', '{"A":"The colon interrupts the verb and its objects; a colon may follow only a complete statement.","B":"A comma between a verb and its first object separates parts that belong together.","C":"A semicolon cannot split a verb from its object list; it joins independent clauses.","D":"Correct: the list is the direct object of ''supplies,'' so nothing should intervene."}', 'A colon may introduce a list only after an **independent clause**; here the verb flows directly into its objects.', 'The colon tempts because lists so often follow colons — but only when the words before the colon already form a complete sentence.', '1) Cover everything after the suspect mark. 2) Ask: is what remains a complete sentence? 3) If yes, a colon may introduce the list. 4) If no — as when a verb still awaits its objects — use no mark at all. 5) Re-read the full sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0113496a8c005fe7', 'act-english', 's-rhet', 2, 'For eleven years, the Maple Street branch has run a delivery route for patrons who cannot travel to the building. Twice a month, a librarian loads crates of requested novels, audiobooks, and large-print mysteries into a small van. At each stop, she collects finished books, takes new requests, and often stays a few minutes to chat about what to read next. Riders who once felt cut off from the library now plan their calendars around her visits.', 'Suppose the writer''s goal had been to show how one public library serves patrons who cannot visit in person. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it lists every outreach service the library system offers.","letter":"A"},{"is_no_change":false,"label":"Yes, because it describes the branch''s delivery route and its effect on the patrons it reaches.","letter":"B"},{"is_no_change":false,"label":"No, because it centers on the library''s annual budget negotiations.","letter":"C"},{"is_no_change":false,"label":"No, because it mentions patrons only in its final sentence.","letter":"D"}]', 'B', '{"A":"Right verdict, wrong reason — the essay follows one program closely rather than cataloging every service.","B":"Correct: the essay details exactly how one branch brings books to homebound readers and how those readers respond.","C":"Budgets, funding, and negotiations never appear anywhere in the essay.","D":"The homebound readers are present from the opening sentence onward, not just at the end."}', 'The essay''s every sentence develops **one program for homebound readers**, which is precisely what the supposed goal requires.', 'The ''yes'' option claiming a full list of services tempts students who match the verdict without checking whether the reason describes the essay.', '1) Restate the supposed goal in your own words. 2) Summarize what the essay actually spends its sentences on. 3) Decide yes or no by comparing the two. 4) Then verify the chosen reason is factually true of the essay. 5) Eliminate any option whose reason misstates the essay, even when its verdict matches yours.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-023e29cfc2225660', 'act-english', 's-rhet', 2, 'The crew''s real enemy on the mountain is not rock but water. Left alone, runoff follows the packed path downhill, picking up speed and soil with every yard. Most of the season is therefore spent on drainage, and the crew builds features designed to push water off the path before it can dig in.', 'The writer wants to add a sentence that gives a specific example of the drainage work described in the paragraph. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Crew members often debate which brand of shovel stands up best to rocky soil.","letter":"A"},{"is_no_change":false,"label":"Runoff is also a problem on gravel roads throughout the national forest.","letter":"B"},{"is_no_change":false,"label":"Every fifty feet of steep grade, the crew carves a shallow channel across the tread to shed runoff.","letter":"C"},{"is_no_change":false,"label":"The tread is raked smooth at the end of each season so the trail photographs well.","letter":"D"}]', 'C', '{"A":"Off-topic: a debate about shovel brands is equipment chatter, not an example of water being managed.","B":"Wrong scope: it wanders to roads elsewhere in the forest instead of showing this crew''s drainage work on the trail.","C":"Correct: it names a specific, concrete drainage feature the crew builds, directly illustrating the paragraph''s focus.","D":"Wrong purpose: raking for photographs is an aesthetic detail; no water is being controlled."}', 'The paragraph''s focus is moving water off the path, and only this sentence gives a **specific instance** of the crew doing exactly that.', 'The gravel-roads sentence tempts students because it mentions the same problem, even though it abandons the crew and the trail entirely.', '1) State the paragraph''s focus in one phrase. 2) State the stem''s goal. 3) Test each candidate: does it give a specific instance of that focus, in the right place, by the right people? 4) Reject details that are off-topic, out of scope, or serving a different purpose.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-03e773990429bfd9', 'act-english', 's-rhet', 2, 'Day and night, the heavy surf <u>hit</u> the rocks at the mouth of the cove.', 'Which choice most vividly conveys the force of the surf?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"pounded","letter":"B"},{"is_no_change":false,"label":"touched","letter":"C"},{"is_no_change":false,"label":"was near","letter":"D"}]', 'B', '{"A":"The original verb is accurate but flat, missing the chance to convey relentless force (weak_word_choice).","B":"Correct: this verb captures the heavy, repeated force of the surf.","C":"This verb suggests gentleness, the opposite of the intended force.","D":"This phrase describes position, not action, and conveys no force at all."}', 'The chosen verb supplies the **forceful, repeated impact** the stem asks the writer to convey.', 'The original is technically correct and unremarkable, so students leave it rather than seek a stronger verb.', '1) Read the goal in the stem. 2) Rank each verb by how strongly it conveys that quality. 3) Reject verbs that are too weak or off-meaning. 4) Choose the verb that best matches the requested effect.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-086013df3cc9c3f6', 'act-english', 's-rhet', 2, 'Every Saturday at dawn, the Riverbend Running Club gathers in a bakery parking lot for its group long run. Conversation makes the miles pass, and pace groups shuffle so that nobody runs alone. Afterward, members linger over coffee, trading advice about shoes and sore calves.', 'The writer wants this paragraph to stay focused on the club''s group runs. Given that goal, should the writer add the following sentence after the second sentence? "The club''s treasurer also files the group''s tax paperwork every spring."', '[{"is_no_change":false,"label":"Yes, because it shows that the club manages its money responsibly.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why members trust the club''s volunteer leaders.","letter":"B"},{"is_no_change":false,"label":"No, because it shifts attention to a detail unconnected to the group runs the paragraph describes.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats a detail about the group runs given earlier in the paragraph.","letter":"D"}]', 'C', '{"A":"Endorses the addition for being flattering, but a true, admirable fact still derails a paragraph about the runs (add_true_but_offtopic).","B":"Invents a purpose — building trust in leaders — that the paragraph never raises (add_invented_purpose).","C":"Correct: tax paperwork belongs to club administration, not to the Saturday-run scene the paragraph develops.","D":"Reaches the right verdict with a false reason, since the paperwork detail appears nowhere else (delete_wrong_reason)."}', 'The addition fails the **relevance** test: springtime paperwork does nothing to develop the paragraph''s portrait of the weekly run.', 'The repetition reason tempts students because it also rejects the sentence, and a matching verdict can feel like a matching justification.', '1) State the paragraph''s focus in one phrase. 2) Ask whether the proposed sentence develops that focus. 3) If not, lean toward rejecting it. 4) Then vet the reason: is it factually true of the paragraph? 5) Choose the verdict-plus-reason pair in which both halves hold up.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-12cdb0d806b359e8', 'act-english', 's-rhet', 2, 'Rosa Delgado wound her first warp at fourteen, guiding threads onto the beam under her grandmother''s eye. Within a decade, her rebozos were winning prizes at regional fairs. Now she trains apprentices in her Oaxaca studio, urging them to treat every warp as a signature.', 'Suppose the writer''s goal had been to explain, step by step, how weavers prepare a warp. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because the essay mentions Rosa winding a warp and guiding threads onto the beam.","letter":"A"},{"is_no_change":false,"label":"No, because the essay traces an artist''s growth rather than explaining each stage of the task.","letter":"B"},{"is_no_change":false,"label":"No, because explaining warping step by step would be too technical for general readers.","letter":"C"},{"is_no_change":false,"label":"Yes, because the essay names each tool weavers use to prepare a warp.","letter":"D"}]', 'B', '{"A":"A single mention of winding a warp is biographical color, not the sequence of instructions the goal requires.","B":"Correct: the essay is a profile of Rosa''s development, and no part of it walks through the warping procedure.","C":"This rejects the goal for an invented reason about audience; the essay simply never attempts the explanation.","D":"The essay names almost no tools, and naming tools would not amount to step-by-step instruction anyway."}', 'Purpose questions compare the essay''s actual **genre and content** to the supposed goal — a profile is not a procedure.', 'The ''yes'' about winding the warp tempts because the essay does touch the topic — but touching a topic is not explaining it.', '1) Summarize what the essay actually does in one sentence. 2) Restate the hypothetical goal. 3) Ask whether the essay''s content would satisfy a reader seeking that goal. 4) Choose the yes/no whose reason accurately describes the essay.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-183846efac1a1f3b', 'act-english', 's-rhet', 2, '<p>Each November, Glazed Harvest Pottery hosts an Empty Bowls dinner to fight hunger in its county. Members spend October throwing hundreds of simple soup bowls, and local restaurants donate pots of soup and fresh bread. Guests choose a handmade bowl, share a modest meal, and take the bowl home as a reminder that someone''s bowl is often empty.</p><p>The writer is considering adding the following sentence after the final sentence of the paragraph:</p><p><em>Last year the dinner raised more than four thousand dollars for the county food pantry.</em></p>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains how the members make the bowls.","letter":"A"},{"is_no_change":false,"label":"Yes, because it gives concrete evidence of the dinner''s impact.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information stated earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts attention away from the dinner itself.","letter":"D"}]', 'B', '{"A":"The sentence says nothing about bowl-making, so this ''yes'' rests on a misdescription of the sentence (right verdict, wrong reason).","B":"Correct: a dollar total for the food pantry documents what the event achieves, strengthening the paragraph''s close.","C":"No earlier sentence mentions money or the pantry, so nothing is repeated (phantom repetition).","D":"The total is the outcome of the dinner itself, so attention stays exactly where the paragraph put it (false off-topic call)."}', 'The addition supplies a **specific, verifiable result** that supports the paragraph''s account of the event.', 'Students often accept a correct verdict paired with a reason that misdescribes what the sentence actually contains.', '1) Read the proposed sentence and state what it contains. 2) Decide whether that content serves the paragraph''s purpose. 3) Pick the verdict (add or not). 4) Then test each stated reason against the sentence''s actual content. 5) Accept only the verdict whose reason accurately describes the sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-185eb6b953ffb250', 'act-english', 's-rhet', 2, 'The dampened sheets were <u>whisper-thin</u>, so pressmen lifted each one with wooden tongs to keep it whole.', 'The writer wants to emphasize how fragile the dampened paper was. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"fairly thin","letter":"B"},{"is_no_change":false,"label":"not very thick","letter":"C"},{"is_no_change":false,"label":"inexpensive to produce","letter":"D"}]', 'A', '{"A":"''Whisper-thin'' evokes near-weightless delicacy, directly serving the goal of emphasizing fragility.","B":"''Fairly thin'' is a mild hedge that reports thickness without conveying fragility.","C":"''Not very thick'' states a negative measurement and carries no sense of delicacy.","D":"''Inexpensive to produce'' abandons the goal entirely, describing cost rather than fragility."}', 'The vivid compound most strongly conveys **fragility**, which is the writer''s stated goal.', '''Fairly thin'' tempts because it is factually consistent with the sentence, though it fails the emphasis goal.', '1) Restate the writer''s goal in your own words. 2) Test each candidate only against that goal, not against grammar. 3) Discard candidates that are merely accurate but flat. 4) Discard candidates that change the subject. 5) Keep the one that delivers the goal most forcefully, then re-read the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1ccb9491aa1dcd5a', 'act-english', 's-rhet', 2, 'Mid-race fueling can decide the final miles of a marathon. Nutritionists suggest thirty to sixty grams of carbohydrate per hour once the race begins, and runners who wait until they feel depleted have usually waited too long.', 'The writer wants to add a sentence that develops the paragraph''s point about fueling during the race. Which choice would most effectively accomplish that goal?', '[{"is_no_change":false,"label":"Some runners choose shoes with carbon plates to save energy late in the race.","letter":"A"},{"is_no_change":false,"label":"Some runners celebrate with a big pasta dinner the night after they finish.","letter":"B"},{"is_no_change":false,"label":"Some runners program a watch alert as a reminder for a gel every forty minutes.","letter":"C"},{"is_no_change":false,"label":"Some runners eat extra pasta at every dinner in the two days before the race.","letter":"D"}]', 'C', '{"A":"Shoe technology belongs to a gear discussion, not to the paragraph''s nutrition focus (add_offtopic_gear).","B":"A celebration meal happens after the finish, outside the in-race window the paragraph examines (add_wrong_time_after).","C":"Correct: it shows a concrete strategy for taking in fuel on schedule while the race is under way, extending the paragraph''s point.","D":"Pre-race carb-loading is preparation, a near-miss that addresses the wrong phase of the event (add_wrong_time_before)."}', 'Only this choice adds a detail about fuel intake **during** the race itself, which is the paragraph''s declared subject.', 'The carb-loading detail tempts students because it is also about eating for the marathon, hiding that it happens before the gun rather than after it.', '1) State the paragraph''s focus, including its time window. 2) For each choice, name its topic and when it happens. 3) Eliminate choices on a different topic. 4) Eliminate same-topic choices set in the wrong phase. 5) Keep the choice that matches both topic and timing.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-27aeb246e0dddc95', 'act-english', 's-rhet', 2, 'The field report observed that the anemone''s sting, though harmless to people, <u>totally wrecks</u> the tiny shrimp that drift too close.', 'Which choice best maintains the passage''s formal, scientific tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"does a number on","letter":"B"},{"is_no_change":false,"label":"majorly messes up","letter":"C"},{"is_no_change":false,"label":"readily immobilizes","letter":"D"}]', 'D', '{"A":"The original is casual slang out of place in a scientific report (informal_register).","B":"This is a colloquial idiom unsuitable for formal writing.","C":"This is slangy and imprecise for a research context.","D":"Correct: this phrase is precise and matches the report''s formal register."}', 'The passage is a scientific report, so a **formal, precise verb** fits its register.', 'The original vividly conveys damage, so students keep it for its punch despite the clash in tone.', '1) Identify the passage''s register from its surrounding words. 2) Label each option as formal or casual. 3) Eliminate slang and idioms in a formal context. 4) Keep the precise, register-matching choice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2933cc16891131c2', 'act-english', 's-rhet', 2, 'Jelly Roll Morton''s 1926 Red Hot Peppers sessions balanced written arrangement with open improvisation, a blend that <u>was a totally awesome thing for</u> composers in the decades that followed.', 'Which choice best maintains the tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was super important for","letter":"B"},{"is_no_change":false,"label":"became a touchstone for","letter":"C"},{"is_no_change":false,"label":"was the coolest deal ever for","letter":"D"}]', 'C', '{"A":"register_colloquial: *totally awesome* is slang, clashing with the essay''s formal, historical register.","B":"*Super important* is casual intensifier talk, still beneath the passage''s register.","C":"Correct: the phrasing is precise and matches the formal, analytical tone.","D":"*Coolest deal ever* is the most conversational option of all."}', 'The winning phrase keeps the essay''s **formal** register while stating the influence precisely.', '*Super important* feels tamer than the other slang, so it masquerades as acceptable.', '1) Read two neighboring sentences and name the register: formal, neutral, or casual. 2) Flag any option containing slang, hedges, or chatty intensifiers. 3) Eliminate every flagged option. 4) Choose the remaining phrase that states the idea most precisely.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-366d8fd0b3e5f104', 'act-english', 's-rhet', 2, 'Inside the controlled-atmosphere cooler, the workers'' breath <u>hung in pale clouds</u> above the sorting line.', 'The writer wants to emphasize the cooler''s deep chill with a vivid visual image. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was noticeable","letter":"B"},{"is_no_change":false,"label":"could occasionally be seen","letter":"C"},{"is_no_change":false,"label":"was affected by the cold","letter":"D"}]', 'A', '{"A":"Correct: ''hung in pale clouds'' turns the cold into a concrete picture the reader can see.","B":"''Was noticeable'' states that breath was visible without painting any image of the chill.","C":"''Could occasionally be seen'' hedges the detail and offers no picture at all.","D":"''Was affected by the cold'' is vague and abstract, telling rather than showing."}', 'The goal demands a **vivid visual** image, and only the original renders the cold as a picture.', '''Was noticeable'' is clean and factual, so students mistake plain accuracy for the requested vividness.', '1) Restate the writer''s goal in your own words. 2) For each option, ask: can I picture this? 3) Cross out options that merely report or hedge. 4) Keep the one that makes the goal''s quality visible on the page.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-379bc994649a4c66', 'act-english', 's-rhet', 2, 'The orchard sells fruit in every season, but the business truly runs on six autumn weekends. Hayrides, the doughnut counter, and pick-your-own tickets draw crowds the quiet farm never sees in July.', 'The writer wants to add a sentence that directly supports the paragraph''s point that autumn visitors provide most of the orchard''s income. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The driveway was repaved with crushed gravel two summers ago.","letter":"A"},{"is_no_change":false,"label":"Receipts from those October weekends alone cover the orchard''s property taxes for the year.","letter":"B"},{"is_no_change":false,"label":"Some visitors drive more than an hour to walk rows their grandparents once picked.","letter":"C"},{"is_no_change":false,"label":"Apple trees need deep, infrequent watering during dry stretches in August.","letter":"D"}]', 'B', '{"A":"A paving update says nothing about where the orchard''s money comes from.","B":"Correct: it quantifies autumn revenue against a major expense, directly proving the income point.","C":"Devoted visitors suggest loyalty, but distance traveled is not evidence about income.","D":"Watering needs concern horticulture, not the source of the business''s revenue."}', 'The goal asks for support about **income**, and only this option ties the autumn crowds to money.', 'The hour-long drive shows how much visitors care, so students mistake enthusiasm for financial evidence.', '1) Underline the claim to be supported. 2) For each option, ask: does this give evidence for that exact claim? 3) Discard options that are merely on-topic or heartwarming. 4) Keep the one that would convince a skeptic of the claim.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3b087ff10d6b4c60', 'act-english', 's-rhet', 2, 'The abandoned pier stretched into the fog, its planks <u>old</u> and silvered by decades of salt spray.', 'The writer wants a word that reinforces the eerie, weathered mood. Which choice best does so?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"used","letter":"B"},{"is_no_change":false,"label":"weather-beaten","letter":"C"},{"is_no_change":false,"label":"aged","letter":"D"}]', 'C', '{"A":"''Old'' states age plainly without any atmosphere.","B":"''Used'' suggests wear from handling, not weathering, and adds no mood.","C":"''Weather-beaten'' evokes exposure to the elements, deepening the eerie, storm-worn image.","D":"''Aged'' is a small step up from ''old'' but still neutral about mood."}', 'The goal is **mood**, and ''weather-beaten'' carries the imagery of long exposure to sea and storm.', '''Aged'' feels more descriptive than ''old'', so it seems like enough of an upgrade.', 'When the stem asks for a mood or image, pick the word whose connotation paints that picture.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3c69e2378d85c8bd', 'act-english', 's-rhet', 2, 'The researchers concluded that rising ocean temperatures <u>are totally wrecking</u> coral reefs across the tropics.', 'Which choice best maintains the formal, scientific tone of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"are messing up","letter":"B"},{"is_no_change":false,"label":"are severely damaging","letter":"C"},{"is_no_change":false,"label":"are bumming out","letter":"D"}]', 'C', '{"A":"''Totally wrecking'' is conversational slang that clashes with the passage''s scientific register (tone_colloquial).","B":"''Messing up'' is everyday informal language, breaking the academic tone (tone_colloquial).","C":"Correct: it is formal and precise, matching the register of a research finding.","D":"''Bumming out'' is slang about emotions, so it is both too casual and illogical for reefs (tone_colloquial)."}', 'In a scientific passage the wording must keep a **formal register**, so a measured phrase fits.', 'Casual phrases feel forceful and emphatic, tempting students who want to stress the harm.', '1) Identify the passage''s register by scanning the surrounding sentences. 2) Test each option against that register. 3) Reject slang and casual idioms. 4) Choose the phrasing that a formal writer would use.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3cab5fc019af6872', 'act-english', 's-rhet', 2, 'Saguaro cactuses grow with almost comic slowness. A ten-year-old saguaro may stand barely two inches tall. At this point, the writer is considering adding the following sentence: <em>Even at fifty, most have yet to sprout their first arm.</em>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it extends the paragraph''s point about slow growth with a second vivid benchmark.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why saguaros grow so slowly.","letter":"B"},{"is_no_change":false,"label":"No, because it contradicts the claim made in the preceding sentence.","letter":"C"},{"is_no_change":false,"label":"No, because the paragraph focuses on desert animals rather than plants.","letter":"D"}]', 'A', '{"A":"Correctly identifies both the right decision and the right reason—the sentence adds a second age-based illustration of slowness.","B":"Reaches the right decision for a wrong reason: the sentence gives another example, not a cause.","C":"Misreads the sentence, which reinforces rather than contradicts the two-inch example.","D":"Misstates the paragraph''s topic, which is plainly the cactus itself."}', 'The proposed sentence supplies a **second concrete benchmark** of slow growth, directly supporting the paragraph''s point.', 'The ''explains why'' justification tempts students who treat any added information as an explanation.', '1) State the paragraph''s point. 2) Ask whether the new sentence supports, contradicts, or ignores it. 3) Decide add or don''t add. 4) Then vet the *reason*: it must describe what the sentence actually does, not merely reach the right verdict.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-40bef648412a1989', 'act-english', 's-rhet', 2, 'As the derecho crossed the county line, a wall of dust <u>moved</u> across the dry fields toward town.', 'The writer wants to convey the storm''s speed and force as vividly as possible. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"barreled","letter":"B"},{"is_no_change":false,"label":"traveled","letter":"C"},{"is_no_change":false,"label":"appeared","letter":"D"}]', 'B', '{"A":"''Moved'' is grammatical but generic, conveying no speed or force (misconception: the original stands if nothing is wrong with it).","B":"Correct: it depicts fast, heavy, unstoppable motion, delivering both speed and force.","C":"''Traveled'' is as neutral as ''moved,'' adding distance but no violence (misconception: any synonym counts as a revision).","D":"''Appeared'' removes motion altogether, freezing the image (misconception: a dramatic-sounding word equals dramatic meaning)."}', 'The key verb packs **speed and force** into the image itself, exactly what the goal demands.', '''Traveled'' feels slightly more specific than ''moved,'' so it masquerades as the vivid upgrade.', '1) Underline the goal words in the stem. 2) For each option, ask: does this verb by itself show that quality? 3) Cut options that are merely grammatical. 4) Cut options that add a different quality than the goal names. 5) Pick the one that shows the goal''s quality without extra help.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-48ed4ba18f05609d', 'act-english', 's-rhet', 2, 'After the flood, neighbors <u>helped</u> one another haul ruined furniture to the curb for weeks.', 'The writer wants to stress how tirelessly the neighbors worked. Which choice best achieves that?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"assisted","letter":"B"},{"is_no_change":false,"label":"were there for","letter":"C"},{"is_no_change":false,"label":"labored alongside","letter":"D"}]', 'D', '{"A":"''Helped'' is accurate but flat — it conveys nothing about effort or endurance.","B":"''Assisted'' is even more neutral and formal than ''helped''.","C":"''Were there for'' emphasizes emotional support, not hard work.","D":"''Labored alongside'' foregrounds sustained, physical effort, exactly the tirelessness the stem asks for."}', 'The goal is to convey **effort**, and ''labored'' names hard, sustained work directly.', 'Every option is grammatically fine, so the flat synonym ''assisted'' looks safe.', 'For a goal question, grade each choice only against the stated purpose — grammar alone never decides it.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-49debf8f72962e7b', 'act-english', 's-rhet', 2, 'Each October, thousands of warblers cross the city after midnight. Downtown towers left blazing overnight pull the birds off course, and window strikes spike on foggy nights. <b>[New sentence]</b>', 'The writer wants to add a sentence that is most relevant to the paragraph''s focus on how artificial light disrupts migrating songbirds. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"During one lights-out trial, collisions at the convention center dropped by more than half.","letter":"A"},{"is_no_change":false,"label":"Warblers weigh about as much as a small handful of paper clips.","letter":"B"},{"is_no_change":false,"label":"The convention center hosts trade shows nearly every month of the year.","letter":"C"},{"is_no_change":false,"label":"Some songbirds migrate by day, navigating by the position of the sun.","letter":"D"}]', 'A', '{"A":"Correct: the lights-out result ties lighting directly to collisions, advancing the paragraph''s exact focus.","B":"Charming trivia about weight that says nothing about light or collisions (add_offtopic_trivia).","C":"Shares a building with the paragraph but not a topic — scheduling is irrelevant to birds and light (add_location_only).","D":"On-species but off-focus: daytime sun navigation sits outside the nighttime-lighting problem (add_wrong_scenario)."}', 'Relevance means serving the paragraph''s **specific focus** — light disrupting migrating birds — and only this sentence connects lighting to bird collisions.', 'The daytime-migration fact tempts students because it is genuinely about songbird navigation, masking that it addresses the wrong time of day and the wrong problem.', '1) Write the paragraph''s focus as a one-line question (here: how does artificial light harm migrating birds?). 2) Test each option: does it help answer that question? 3) Discard options that merely share a species, a place, or a general theme. 4) Prefer the option that adds evidence or consequence for the focus. 5) Re-read the paragraph with the addition to confirm the thread holds.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4b220c8ea4c43178', 'act-english', 's-rhet', 2, 'Passage II — The Science of Sourdough — Bread may seem simple, but sourdough is surprisingly complex. Unlike breads made with packaged yeast, sourdough rises using wild yeast and bacteria captured from the air. Bakers maintain a "starter," <u>a mixture of flour and water that they feed regularly.</u> The starter, it ferments over several days. During fermentation, the microbes produce carbon dioxide, which makes the dough rise. They also produce acids, giving sourdough its tangy flavor. Because of these reactions, no two starters taste exactly alike. Some bakers, claim that a starter''s flavor reflects the place where it was made. A San Francisco starter, for instance, may taste different from one in Paris. Whether or not that is true, sourdough remains a small marvel of biology and patience.', 'Which underlined choice conveys the definition most clearly for a general reader?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a mixture, of flour and water, that they feed on a regular and repeating basis.","letter":"B"},{"is_no_change":false,"label":"a mixture made of both flour and also water, fed regularly by them.","letter":"C"},{"is_no_change":false,"label":"a mixture of flour and water, which is something they feed regularly and often.","letter":"D"}]', 'A', '{"A":"Original is the most concise; others are wordy/redundant.","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Original is the most concise; others are wordy/redundant.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Knowledge of Language (concision)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4faaadf6c2ec8d16', 'act-english', 's-rhet', 2, '[1] This essay walks through a single day in a fermentation lab, from the morning pH readings to the evening taste tests. [2] It follows the technicians as they nudge temperature and salt to steer colonies of bacteria toward the flavors a client ordered. [3] By closing time, a batch of miso has deepened a shade and gained a savory edge that no recipe could have promised in advance.', 'Suppose the writer''s goal had been to argue that home fermentation is safer than most people fear. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"No, because the essay documents a day of professional lab work rather than making a case about home-fermentation safety.","letter":"A"},{"is_no_change":false,"label":"No, because the essay focuses on the taste of miso instead of on bacteria.","letter":"B"},{"is_no_change":false,"label":"Yes, because the essay shows technicians controlling bacteria without any accidents.","letter":"C"},{"is_no_change":false,"label":"Yes, because the essay proves that fermentation is a widespread and ancient practice.","letter":"D"}]', 'A', '{"A":"Correct: the essay is a descriptive account of a professional lab day, never arguing anything about home safety, so it misses the proposed goal.","B":"Wrong reason: the essay covers far more than miso''s taste, and taste focus is not why it fails the safety goal.","C":"Overreach: an accident-free description of experts is not an argument that home fermentation is safe.","D":"False claim: the essay never addresses fermentation''s history or prevalence at all."}', 'The essay is **descriptive, not argumentative**, and says nothing about home safety, so it cannot accomplish a persuasive safety goal.', 'Because the technicians handle bacteria smoothly with no mishaps, it can seem to imply that fermentation is safe.', '1) State the proposed goal in your own words. 2) Identify what the essay actually does — describe, argue, or narrate. 3) Match the essay''s real purpose against the goal. 4) Answer yes only if the essay genuinely pursues that goal. 5) Then choose the reason that accurately describes the mismatch or match.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-503edab8eb283dbe', 'act-english', 's-rhet', 2, 'To outlast months without rain, desert animals have evolved striking ways to hold on to water. The kangaroo rat manufactures moisture inside its own body and never sweats a drop. The camel packs fat, not water, into its hump and can cross weeks of dune country between drinks. Even the plodding desert tortoise carries a reservoir of stored water it slowly reabsorbs through a dry spell.', 'Suppose the writer''s goal had been to explain several ways that desert animals hold on to water. Does this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it lays out the specific water-saving methods of more than one animal.","letter":"A"},{"is_no_change":false,"label":"Yes, because it proves that the desert is the harshest habitat on the planet.","letter":"B"},{"is_no_change":false,"label":"No, because it only tells readers where these animals happen to live.","letter":"C"},{"is_no_change":false,"label":"No, because it never explains how the animals end up losing water in the first place.","letter":"D"}]', 'A', '{"A":"Correct: the essay walks through the distinct water-holding strategies of the kangaroo rat, camel, and tortoise, exactly matching the goal.","B":"Judges the essay against a claim it never makes about the desert being the harshest habitat (false_justification).","C":"Denies success on the false grounds that the essay only gives locations, which it does not (false_premise).","D":"Faults the essay for omitting water loss, a topic the goal never asked it to cover (goal_wrong_standard)."}', 'The goal asks for **several methods**, and the essay supplies a distinct strategy for each of three animals.', 'The water-loss answer sounds rigorous because it demands more information, tempting students who assume a fuller essay is always better.', '1) Restate the writer''s goal precisely (show several ways animals hold water). 2) Skim the essay for whether it delivers that. 3) Match the yes/no verdict to what the essay actually does. 4) Reject any reason that misstates the essay''s content or judges it by a standard the goal never set. 5) Pick the verdict whose reason is both true and on point.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-537699139b6391f1', 'act-english', 's-rhet', 2, 'When I joined the robotics team as a sophomore, I could not tell a hex key from a screwdriver. Over one season I learned to read a match schedule, to lose gracefully, and to ask older students for help without embarrassment. By the banquet in April, the trophy case mattered far less to me than the people I had built things with.', 'Suppose the writer''s goal had been to provide a technical guide explaining how to construct a competition robot. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because the essay refers to technical tools such as hex keys and screwdrivers.","letter":"A"},{"is_no_change":false,"label":"Yes, because the narrator describes an entire season from joining the team to the banquet.","letter":"B"},{"is_no_change":false,"label":"No, because the essay is a personal narrative about a single season rather than a technical guide.","letter":"C"},{"is_no_change":false,"label":"No, because a technical guide would need to mention trophies and match schedules.","letter":"D"}]', 'C', '{"A":"Mistakes a passing mention of tools for actual instruction (purpose_stray_vocabulary).","B":"Confuses complete time coverage with coverage of the required topic (purpose_scope_confusion).","C":"Correct: the essay recounts one student''s growth and never explains construction, so it fails the goal for this reason.","D":"Reaches the right verdict with a nonsensical requirement about trophies (purpose_wrong_reason)."}', 'The essay is a first-person account of growth over one season and **never explains construction**, so it fails the stated goal for exactly that reason.', 'The hex-key option tempts students who equate mentioning tools with explaining their use.', '1) Restate the hypothetical goal. 2) Summarize what the essay actually does. 3) Compare: match or mismatch? 4) Among same-verdict options, pick the reason that accurately describes the essay.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-57efe90d0b8d00a1', 'act-english', 's-rhet', 2, 'Sweaters <u>spill in bright tangles</u> from every shelf of the clothing annex.', 'The writer wants to emphasize the cheerful abundance of the sweater display. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"are stored","letter":"B"},{"is_no_change":false,"label":"can be seen","letter":"C"},{"is_no_change":false,"label":"remain","letter":"D"}]', 'A', '{"A":"Correct: ''spill in bright tangles'' conveys both overflowing quantity and cheerful color.","B":"Reduces the scene to flat warehouse language with no sense of abundance or cheer.","C":"Merely notes visibility, giving no impression of quantity or color.","D":"Says only that the sweaters stay put, with no image of plenty at all."}', 'Only the original wording delivers concrete images of **overflow and color** that match the stated goal.', '''Can be seen'' feels safely descriptive, but a goal question rewards vivid specificity, not neutral reporting.', '1) Restate the writer''s goal in your own words. 2) For each option, list what a reader can actually picture. 3) Cross out options that could describe any object anywhere. 4) Keep the option whose images match the goal''s key qualities. 5) Confirm it fits the sentence grammatically.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-58fc8111a396d077', 'act-english', 's-rhet', 2, 'Each spring, the Riverside Night Market fills two blocks of Dock Street with food stalls, craft tables, and live music. Vendors pay a modest fee that funds trash pickup and off-duty police patrols. The market has become the district''s most reliable draw for weekend visitors.', 'The writer is considering adding the following true statement after the second sentence: "Last year those fees covered every cleanup and security bill, so the market needed no money from the city." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it demonstrates that the fee arrangement described in the previous sentence works.","letter":"A"},{"is_no_change":false,"label":"Yes, because it reveals how much each vendor pays under the fee arrangement.","letter":"B"},{"is_no_change":false,"label":"No, because the previous sentence already describes what the fees pay for.","letter":"C"},{"is_no_change":false,"label":"No, because budget details distract from the paragraph''s point about weekend visitors.","letter":"D"}]', 'A', '{"A":"The new sentence proves the fee system actually covered its costs, directly extending the point of the sentence it follows.","B":"The proposed sentence never states any individual vendor''s payment — this reason misdescribes its content.","C":"Purpose and outcome are different facts: the paragraph says what the fees are for, not whether they sufficed — the misconception that shared topic equals repetition.","D":"The paragraph portrays a well-run market, so a sentence showing the market pays its own way supports rather than distracts."}', 'The addition supplies the **outcome** of the fee system the previous sentence set up, strengthening the paragraph''s portrait.', 'The proposed sentence and the one before it both mention fees, so the addition can look like mere repetition.', '1) State what the proposed sentence adds that the paragraph lacks. 2) Ask whether that addition supports the paragraph''s focus. 3) If yes, the winning ''Yes'' reason must accurately restate the sentence''s content; if no, the winning ''No'' reason must, too. 4) Reject any reason that misdescribes the sentence or the paragraph. 5) Choose the verdict-plus-reason pair that survives.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5bc2c600f3d366c4', 'act-english', 's-rhet', 2, 'Using bamboo tongs, the printer <u>moves</u> the dripping print from the developer tray into the stop bath.', 'The writer wants to emphasize the delicate care the printer takes with the wet print. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shoves","letter":"B"},{"is_no_change":false,"label":"eases","letter":"C"},{"is_no_change":false,"label":"transfers","letter":"D"}]', 'C', '{"A":"''Moves'' is accurate but neutral (goal_neutral_verb), conveying no special care.","B":"''Shoves'' signals rough force (goal_opposite_connotation), the reverse of the stated goal.","C":"Correct: ''eases'' pictures a slow, careful motion, directly conveying delicate handling.","D":"''Transfers'' is clinical and procedural (goal_flat_technical), emphasizing logistics rather than care."}', 'The goal asks for **care**, and only a verb that pictures slow, gentle motion delivers it.', '''Transfers'' sounds precise and writerly, so students pick polish over the connotation the goal demands.', '1) Underline the goal words in the stem. 2) For each verb, name its connotation in one word (rough, neutral, careful, clinical). 3) Eliminate any verb whose connotation misses the goal, even if it is accurate. 4) Pick the verb whose picture matches the goal exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5d38ccd23f75673a', 'act-english', 's-rhet', 2, 'When the ferry docked at last, my grandmother <u>walked</u> down the gangway toward the crowd of strangers on the pier, her documents pinned inside her coat.', 'The writer wants to emphasize the grandmother''s hesitation as she left the ship. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"strolled","letter":"B"},{"is_no_change":false,"label":"edged","letter":"C"},{"is_no_change":false,"label":"hurried","letter":"D"}]', 'C', '{"A":"''Walked'' reports motion neutrally and conveys none of the hesitation the writer wants to emphasize.","B":"''Strolled'' suggests leisure and ease, the opposite of a nervous arrival.","C":"Correct: ''edged'' conveys slow, cautious, reluctant movement, matching the stated goal.","D":"''Hurried'' signals eagerness or urgency rather than hesitation."}', 'Only this verb''s **connotation** of slow, wary movement delivers the hesitation the stem requires.', '''Walked'' tempts students because it is unobjectionable, but a goal question rewards the verb that accomplishes the stated emphasis, not merely a grammatical one.', '1) Underline the goal stated in the stem. 2) For each verb, name its connotation in one word (neutral, relaxed, cautious, rushed). 3) Match the connotations against the goal. 4) Reject grammatical options that miss the emphasis. 5) Choose the verb whose picture fits the goal exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-61d5a840d7d8291c', 'act-english', 's-rhet', 2, 'Educational interpreters do more than translate lectures. They place themselves so a student can watch the teacher''s demonstrations and the signed message in a single glance. During a chemistry lab, an interpreter may even stand beside the fume hood so the student never looks away from a live reaction.', 'The writer is considering adding the following sentence after the second sentence: "In one middle school, an interpreter moved her stool six times in a single class period to stay inside the student''s sight line." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why schools began hiring interpreters with special training.","letter":"A"},{"is_no_change":false,"label":"Yes, because it gives a specific example of an interpreter adjusting her position for a student.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats the chemistry-lab example in the very next sentence.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts attention away from the student and onto the interpreter.","letter":"D"}]', 'B', '{"A":"The anecdote says nothing about hiring or training; it depicts positioning during a single class.","B":"Correct — it supplies a vivid, concrete case of the positioning strategy the previous sentence describes in general terms.","C":"The stool anecdote and the chemistry-lab sentence describe different settings and details, so nothing is repeated.","D":"The anecdote exists to show the interpreter serving the student''s sight line, so the student remains the focus."}', 'The sentence turns a general claim about positioning into a **concrete case**, which strengthens the paragraph.', 'Readers who see two examples of similar behavior often cry repetition, though the anecdotes differ in setting and detail.', '1) State the paragraph''s claim at the insertion point. 2) Ask: does the new sentence support, repeat, or derail that claim? 3) Supporting details add new specifics; repetition adds none. 4) Accept the addition only when the option''s ''because'' clause accurately describes what the sentence does.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-630536b6545d348a', 'act-english', 's-rhet', 2, 'The town paper''s report on the ceremony noted that the mayor''s speech <u>wrapped up</u> with a call for volunteers.', 'Which choice best suits the article''s formal register?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"finished off","letter":"B"},{"is_no_change":false,"label":"was done","letter":"C"},{"is_no_change":false,"label":"concluded","letter":"D"}]', 'D', '{"A":"''Wrapped up'' is conversational — out of register in a newspaper report.","B":"''Finished off'' is just as casual, with a violent shading besides.","C":"''Was done'' is flat and informal, and weakens the sentence''s structure.","D":"''Concluded'' states the same fact in the neutral, formal register a news report uses."}', 'Match the diction to the **register** of the surrounding text — formal reporting takes ''concluded''.', 'The informal options are exactly how the sentence would be spoken aloud.', 'Identify the passage''s register first; then pick the word that belongs to it.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-64359f73534783a5', 'act-english', 's-rhet', 2, 'Every price at Second Chance Goods reflects a simple formula. The manager checks what similar items sold for online, subtracts a third, and rounds down to the nearest dollar. She reviews the formula each quarter to be sure the shop stays cheaper than its competitors.', 'The writer is considering adding the following sentence after the final sentence of the paragraph: ''The manager also enjoys hiking with her sister on her days off.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it helps readers picture the manager as a well-rounded person.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why the shop closes early on weekends.","letter":"B"},{"is_no_change":false,"label":"No, because it contradicts the paragraph''s earlier description of the manager.","letter":"C"},{"is_no_change":false,"label":"No, because it introduces a personal detail unrelated to the paragraph''s focus on pricing.","letter":"D"}]', 'D', '{"A":"Humanizing the manager is not the paragraph''s job; the addition would blur its single topic.","B":"Invents a justification the sentence does not provide — hiking says nothing about store hours.","C":"Reaches the right verdict for a false reason; nothing in the sentence conflicts with earlier statements.","D":"Correct: the paragraph is a tight explanation of how prices are set, and an off-duty hobby has no bearing on that."}', 'An added sentence must serve the paragraph''s **single controlling idea**, and this one veers into the manager''s off-duty life.', 'The manager appears in every sentence, so a fact about her feels on-topic even though the paragraph is really about her formula.', '1) State the paragraph''s controlling idea in one phrase. 2) Ask what the proposed sentence contributes to that idea. 3) If it contributes nothing, the answer is no. 4) Then vet the reason: it must describe the actual relationship, not an invented one. 5) Pick the verdict-plus-reason pair that matches your analysis.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-67270efc6d33b462', 'act-english', 's-rhet', 2, 'Porcelain is unforgiving at the trimming stage: one heavy-handed pass of the tool can <u>slice through a wall the potter has spent hours thinning</u>.', 'The writer wants to stress how quickly a single mistake can undo hours of careful work. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"have an unfortunate effect on the piece","letter":"B"},{"is_no_change":false,"label":"make the pot slightly less even than before","letter":"C"},{"is_no_change":false,"label":"mess the whole thing up big-time","letter":"D"}]', 'A', '{"A":"Correct: slicing through a wall thinned over hours makes both the speed of the error and the scale of the loss vivid.","B":"''An unfortunate effect'' is so vague it conveys neither speed nor loss (goal-vague wording).","C":"''Slightly less even'' shrinks a catastrophe to a cosmetic flaw, muting the stakes (understates the goal).","D":"''Big-time'' injects slang that clashes with the passage''s register even as it gestures at severity (tone violation)."}', 'The goal needs wording that makes the **sudden destruction of long labor** visible, not vague or minimized.', 'The mild phrasing about evenness sounds appropriately modest and technical, so students miss that it erases the drama the goal demands.', '1) Underline the key words of the stated goal. 2) Test each option against those exact words. 3) Reject options too vague to show the goal''s idea. 4) Reject options that shrink or exaggerate the stakes. 5) Reject options whose tone clashes with the passage, then pick what remains.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6fee13e7f68d08ea', 'act-english', 's-rhet', 2, 'In her thank-you note to the scholarship committee, Dana wrote that their support had <u>meant a ton</u> to her family.', 'Which choice best fits the sincere yet respectful tone of a thank-you note?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"meant loads","letter":"B"},{"is_no_change":false,"label":"been a big deal","letter":"C"},{"is_no_change":false,"label":"meant a great deal","letter":"D"}]', 'D', '{"A":"''Meant a ton'' is casual and a touch flippant for a formal thank-you.","B":"''Meant loads'' is informal and better suited to a text than a note to a committee.","C":"''Been a big deal'' is conversational and slightly slangy.","D":"''Meant a great deal'' is warm and appropriately respectful."}', 'A thank-you note to a committee wants **respectful warmth**, which ''meant a great deal'' delivers.', '''Meant a ton'' sounds heartfelt, but its casualness undercuts the formal courtesy.', 'Match the phrasing to both the emotion and the formality the situation calls for.', 'underlined-span-mc', '''Meant a ton'' sounds heartfelt, but its casualness undercuts the form…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7821c626ada9559b', 'act-english', 's-rhet', 2, '<p>A mussel stays put in the pounding surf by spinning dozens of tough fibers called byssal threads. It reaches out with its muscular foot and lays down each strand one at a time until it is firmly moored.</p>', 'Given that all the choices are true, which one best supports the paragraph''s focus on how a mussel anchors itself?', '[{"is_no_change":false,"label":"Mussels are a popular seafood in many coastal countries.","letter":"A"},{"is_no_change":false,"label":"Each strand ends in a natural cement that grips even slick, wet surfaces.","letter":"B"},{"is_no_change":false,"label":"Mussels draw in and filter large volumes of seawater as they feed.","letter":"C"},{"is_no_change":false,"label":"A mussel''s shell is built from two hinged halves.","letter":"D"}]', 'B', '{"A":"The seafood fact is true but unrelated to how the mussel holds on (add_offtopic).","B":"Correct: it explains a feature of the strands that lets the mussel grip its spot, supporting the anchoring focus.","C":"Feeding by filtering is true but concerns nutrition, not attachment.","D":"The shell''s structure is true but says nothing about how the animal stays anchored."}', 'Only this detail advances the paragraph''s focus on **how the mussel attaches** to its surface.', 'The filtering fact is a familiar mussel trait, so it feels relevant even though it misses the anchoring point.', '1) State the paragraph''s focus from the stem. 2) Test each true detail against that focus. 3) Discard details about other traits. 4) Keep the one that develops the stated focus.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-793bf9f8a6a81446', 'act-english', 's-rhet', 2, 'For sixteen weeks, the training log <u>chronicled every mile</u> of her preparation, from the first hesitant jog to the final twenty-miler.', 'Which choice best maintains the tone established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"kept tabs on pretty much every mile","letter":"B"},{"is_no_change":false,"label":"was basically a receipt for every mile","letter":"C"},{"is_no_change":false,"label":"jotted down the whole saga of","letter":"D"}]', 'A', '{"A":"Correct: the measured, reflective verb matches the sentence''s earnest register.","B":"''Kept tabs'' and ''pretty much'' are conversational idioms that clash with the surrounding formality (register_slang).","C":"The hedge ''basically'' and the flip ''receipt'' metaphor undercut the sentence''s sincere tone (register_flip_metaphor).","D":"''Jotted down'' sounds offhand and ''whole saga'' winks at the reader, breaking the steady register (register_casual_hyperbole)."}', 'The sentence''s diction is measured and **reflective**, and only the original phrasing stays at that level.', '''Kept tabs on pretty much every mile'' tempts students because it sounds natural and friendly, masking its drop into conversational register.', '1) Read the whole sentence and label its register: formal, neutral, or casual. 2) Read each option inside the sentence. 3) Flag idioms, hedges, and slang that sit at a different level. 4) Eliminate any option that shifts the register up or down. 5) Keep the option whose diction blends with the rest.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-817ba58c49d9e63e', 'act-english', 's-rhet', 2, 'Prices at the shop routinely undercut even discount retailers. Because <u>the shop has certain advantages</u>, and because volunteers keep labor costs near zero, markdowns can go deeper than any chain could match.', 'Given that all the choices are accurate, which one most effectively supports the paragraph''s explanation of why the shop can keep prices low?', '[{"is_no_change":false,"label":"the shop opened back in 1987","letter":"A"},{"is_no_change":false,"label":"the shop''s sign was repainted by a local artist","letter":"B"},{"is_no_change":false,"label":"its merchandise arrives free, as donations","letter":"C"},{"is_no_change":false,"label":"donations arrive in unpredictable waves","letter":"D"}]', 'C', '{"A":"The founding year is background trivia with no bearing on low prices.","B":"The sign''s artwork is decorative detail irrelevant to cost.","C":"Correct: goods that cost the shop nothing directly explain how prices can stay below competitors''.","D":"Mentions donations but emphasizes their timing, which doesn''t explain cheapness."}', 'The paragraph explains **why prices stay low**, and only the cost-free supply of goods feeds that explanation directly.', 'The option about unpredictable donation waves mentions the same subject — donations — so it feels connected despite explaining nothing about price.', '1) Name the paragraph''s specific claim (not just its topic). 2) For each option, ask: does this fact help prove that claim? 3) Beware options that share the topic but not the point. 4) Eliminate decoration and background. 5) Keep the option that plugs directly into the paragraph''s logic.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8549a9bc03954200', 'act-english', 's-rhet', 2, 'Within minutes of the first blast, the ash column <u>went</u> ten kilometers into the sky, forcing controllers to reroute every flight in the region.', 'The writer wants to emphasize how fast the ash column climbed. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"rocketed","letter":"B"},{"is_no_change":false,"label":"drifted","letter":"C"},{"is_no_change":false,"label":"extended","letter":"D"}]', 'B', '{"A":"''Went'' states motion without any sense of speed, so it cannot emphasize a rapid climb.","B":"Correct: it conveys explosive upward speed, exactly the quality the writer wants stressed.","C":"''Drifted'' implies slow, aimless motion — the opposite of the stated goal.","D":"''Extended'' is neutral and gradual, adding no urgency to the climb."}', 'Only this verb''s **connotation** of explosive speed accomplishes the writer''s stated goal.', 'The original verb is grammatically fine, tempting students who forget that the question is about the stated goal, not correctness.', '1) Restate the writer''s goal in your own words. 2) Ask of each verb: does it, by itself, carry that quality? 3) Eliminate verbs that are merely correct but neutral, then verbs that contradict the goal. 4) Keep the one whose connotation does the goal''s work.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8dd5c9bb949b5a79', 'act-english', 's-rhet', 2, 'In its written appraisal, the auction house concluded that the donated violin was <u>a super cool find</u> worth far more than its two-dollar price sticker.', 'Which choice best maintains the formal tone established by the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a remarkable discovery","letter":"B"},{"is_no_change":false,"label":"an insanely great score","letter":"C"},{"is_no_change":false,"label":"a seriously awesome pickup","letter":"D"}]', 'B', '{"A":"''Super cool'' is casual slang that clashes with the formal register of a written appraisal.","B":"Correct: elevated, precise diction that matches the professional context.","C":"Intensifier-plus-slang phrasing even more casual than the original.","D":"Conversational slang (''awesome pickup'') unsuited to a formal document."}', 'The sentence''s professional context calls for **formal** diction, and only one option avoids slang.', '''Insanely great'' sounds enthusiastic and vivid, so students mistake energy for appropriateness.', '1) Identify the passage''s register from clues like ''written appraisal.'' 2) Read each option aloud and ask: would a professional write this in a report? 3) Flag slang, intensifiers, and chatty idioms. 4) Eliminate every flagged option. 5) Confirm the survivor fits the sentence''s meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-93c3110ac84b6bf6', 'act-english', 's-rhet', 2, '<p>Each Saturday during harvest season, volunteers weigh every crate bound for the food bank and log the totals on a whiteboard. At the season''s end, the totals are added up and reported to members at the fall potluck.</p><p>The writer is considering adding the following sentence after the first sentence: <em>Rosa, one of the weigh-station volunteers, spent her vacation last year hiking in Peru.</em></p>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it shows how dedicated the weigh-station volunteers are.","letter":"A"},{"is_no_change":false,"label":"Yes, because it adds a personal voice to the paragraph.","letter":"B"},{"is_no_change":false,"label":"No, because it interrupts the description of how the harvest totals are kept.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats details about the harvest totals given earlier in the paragraph.","letter":"D"}]', 'C', '{"A":"The stated reason is false: a hiking vacation demonstrates nothing about dedication at the weigh station.","B":"Personal color helps only when it serves the paragraph''s purpose, and this aside derails the explanation of the tally routine.","C":"Correct: the sentence derails the paragraph''s step-by-step explanation of the weighing and reporting process.","D":"Right verdict, wrong reason: the sentence adds brand-new, irrelevant material rather than repeating anything."}', 'The vacation anecdote is **irrelevant** to the paragraph''s single job — explaining the weighing-and-reporting routine — so adding it would break the paragraph''s focus.', 'Students who correctly sense the sentence should be cut often grab the other ''No'' reason without verifying that any repetition actually exists.', '1) State the paragraph''s job in one line. 2) Ask whether the proposed sentence advances that job. 3) Decide yes or no on that basis alone. 4) Then audit the reason attached to your verdict: is its claim about the sentence literally true? 5) Choose the verdict-plus-reason pair where both halves check out.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9618901deacb2b53', 'act-english', 's-rhet', 2, 'As the valedictorian''s speech sped up, the interpreter''s hands <u>darted</u> through the fingerspelled names of a dozen scholarship donors.', 'The writer wants to emphasize the quickness of the interpreter''s movements. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"moved","letter":"B"},{"is_no_change":false,"label":"worked","letter":"C"},{"is_no_change":false,"label":"proceeded","letter":"D"}]', 'A', '{"A":"Correct — ''darted'' conveys quick, agile motion, matching the speeding speech.","B":"''Moved'' is generic and conveys no speed at all.","C":"''Worked'' suggests effort, not quickness.","D":"''Proceeded'' sounds slow and formal, the opposite of the intended emphasis."}', '''**Darted**'' is the only option whose core meaning contains speed and agility.', '''Worked'' tempts readers because the hands are indeed working hard, but effort is not the stated goal.', '1) Restate the writer''s stated goal in one word (here: speed). 2) Test each option: does its dictionary meaning contain that idea? 3) Cut every option that is merely neutral or generic. 4) Keep the choice whose connotation delivers the goal on its own, without help from context.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-98597c95afd267a6', 'act-english', 's-rhet', 2, 'Buckwheat honey has a dark, <u>strong</u> flavor that many bakers prize for their winter gingerbread.', 'Which choice most precisely conveys a rich, full-bodied flavor?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"big","letter":"B"},{"is_no_change":false,"label":"robust","letter":"C"},{"is_no_change":false,"label":"loud","letter":"D"}]', 'C', '{"A":"''Strong'' is serviceable but generic; it names intensity without capturing the full-bodied richness the sentence sets up.","B":"''Big'' is a colloquial, imprecise word for describing flavor and lowers the register of the sentence.","C":"Correct: ''robust'' names a rich, full-bodied intensity in a register that fits the descriptive sentence.","D":"''Loud'' is figurative slang for flavor and clashes with the descriptive, measured tone of the passage."}', 'The most **precise** word names full-bodied richness exactly, which is what distinguishes the best option from merely intense-sounding ones.', '''Strong'' already reads as intense, so students accept it without asking whether a more exact word captures the fullness of the flavor.', '1) Name the exact quality the sentence is reaching for (here, rich fullness, not just power). 2) Test each option against that quality and against the sentence''s register. 3) Eliminate words that are merely vague, too casual, or figurative slang. 4) Keep the one word that matches both meaning and tone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-add134b6fe11490b', 'act-english', 's-rhet', 2, 'After each day''s run, printers scrubbed their type with lye to strip away the sticky ink, then rinsed the letters in a trough. Type left dirty printed smudges instead of crisp strokes. Careful washing kept a font sharp through thousands of impressions.', 'The writer is considering adding the following sentence after the first sentence: <i>Lye was also prized by launderers for whitening linen shirts.</i> Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why printers preferred lye to gentler cleansers.","letter":"A"},{"is_no_change":false,"label":"Yes, because it offers a vivid glimpse of daily life inside a print shop.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information provided elsewhere in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it strays from the paragraph''s focus on keeping type clean.","letter":"D"}]', 'D', '{"A":"The proposed sentence says nothing about why lye suited printers; it describes a different trade''s use.","B":"The glimpse it offers is of laundry work, not of life inside a print shop.","C":"Nothing in the paragraph mentions launderers or shirts, so no repetition occurs.","D":"The sentence veers to laundry, an unrelated use of lye, so it does not belong in a paragraph about type upkeep."}', 'The addition fails the **relevance** test: it develops laundry, not the paragraph''s subject.', 'The ''vivid detail'' justification tempts because the image is concrete — but it is concrete about the wrong topic.', '1) State the paragraph''s subject in one phrase. 2) Ask whether the proposed sentence develops that subject. 3) If yes, pick the ''yes'' reason that names its actual contribution. 4) If no, pick the ''no'' reason that names its actual flaw. 5) Verify the chosen justification matches what the sentence really does.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b639fca628d708bf', 'act-english', 's-rhet', 2, 'Honeybees visit the orchard for only a few weeks each spring, but those weeks decide the entire harvest. A blossom pollinated within a day of opening sets fruit with more seeds, and heavily seeded apples grow larger and hold to the branch. For that reason, the family rents twelve hives and places one at the center of every third row.', 'The writer is considering adding the following sentence after the second sentence: ''The orchard''s tractor, a 1974 model, still starts on the first try most mornings.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it shows that the family maintains its equipment carefully.","letter":"A"},{"is_no_change":false,"label":"Yes, because it adds a colorful detail about daily life on the farm.","letter":"B"},{"is_no_change":false,"label":"No, because it interrupts the paragraph''s explanation of how spring pollination determines the harvest.","letter":"C"},{"is_no_change":false,"label":"No, because the sentence never identifies who drives the tractor.","letter":"D"}]', 'C', '{"A":"Careful maintenance may be true, but the paragraph is about bees and fruit set, not equipment.","B":"Color is not relevance; a charming detail still derails a paragraph focused on bees.","C":"Correct: the tractor sentence breaks the logical chain from bee visits to fruit size that the paragraph is building.","D":"The problem is the sentence''s irrelevance to the topic, not any missing detail about the driver."}', 'Additions must serve the paragraph''s **focus**, and this one severs its bee-to-fruit logic.', 'The tractor detail is vivid and farm-flavored, so ''colorful detail about daily life'' feels like a legitimate reason to add it.', '1) State the paragraph''s focus in one phrase. 2) Ask whether the proposed sentence advances that focus. 3) If yes, verify the stated reason matches what the sentence actually does. 4) If no, reject it even when it is interesting or true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b990a55d7b776c96', 'act-english', 's-rhet', 2, 'In the final interval, Jonah <u>surged</u> up the hill, arms pumping and breath ragged.', 'The writer wants to convey the intensity of Jonah''s effort in the final interval. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"went","letter":"B"},{"is_no_change":false,"label":"continued","letter":"C"},{"is_no_change":false,"label":"traveled","letter":"D"}]', 'A', '{"A":"Correct: the vivid verb conveys explosive, strenuous effort, matching the pumping arms and ragged breath.","B":"''Went'' records bare motion with no sense of strain or speed (verb_colorless).","C":"''Continued'' emphasizes persistence rather than intensity, missing the stated goal (goal_wrong_emphasis).","D":"''Traveled'' is neutral and itinerary-like, flattening the moment the writer wants to dramatize (verb_too_neutral)."}', 'The stated goal is **intensity**, and only the original verb carries the force that matches the sentence''s straining details.', '''Continued'' tempts students because the final interval does continue, but persisting is not the same as pushing hard.', '1) Restate the writer''s goal in one word. 2) Read each verb inside the full sentence. 3) Ask what each verb makes you picture. 4) Eliminate verbs that report motion without conveying the goal quality. 5) Keep the one whose image matches the goal and the surrounding details.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bf29386cecb39137', 'act-english', 's-rhet', 2, 'The coach told the rookies that a missed free throw was <u>a bad thing</u> only if they refused to learn from it.', 'Which choice best fits the coach''s encouraging, mentor-like tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a disaster","letter":"B"},{"is_no_change":false,"label":"a setback","letter":"C"},{"is_no_change":false,"label":"a catastrophe","letter":"D"}]', 'C', '{"A":"''A bad thing'' is vague and childish, undercutting the mentor''s measured tone.","B":"''Disaster'' overstates a single miss and clashes with the reassuring message.","C":"''Setback'' frames the miss as temporary and surmountable — the encouraging note the coach wants.","D":"''Catastrophe'' is hyperbolic, the opposite of the calm reassurance intended."}', 'The tone is **encouraging**, and ''setback'' names a problem while implying it can be overcome.', '''Disaster'' and ''catastrophe'' feel vivid, but their intensity fights the sentence''s reassurance.', 'Match the word''s emotional weight to the speaker''s intent — don''t reach for the most dramatic option.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c0937fb20774edec', 'act-english', 's-rhet', 2, 'The Owls measure their success in more than wins. Each spring, players visit every elementary school in the county to hand out reading challenges, and the club stocks a downtown food pantry with unsold concessions. Season-ticket holders vote on which neighborhood league receives the team''s annual equipment donation, and the stadium''s community garden supplies its own concession stand.', 'Suppose the writer''s goal had been to write a brief passage showing how one minor-league team builds ties with its community. Would this passage accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it lists the corporate sponsors that fund the Owls'' promotions.","letter":"A"},{"is_no_change":false,"label":"Yes, because it details the club''s ongoing partnerships with schools, charities, and neighborhood groups.","letter":"B"},{"is_no_change":false,"label":"No, because it focuses mainly on the team''s win-loss record.","letter":"C"},{"is_no_change":false,"label":"No, because it describes outreach programs run by teams across several leagues.","letter":"D"}]', 'B', '{"A":"Right verdict, false reason: no sponsor is named anywhere in the passage (right_verdict_wrong_reason).","B":"Correct: the passage catalogs one club''s community programs, so both the verdict and the reason match the text.","C":"The passage explicitly sets winning aside in its first sentence and never tallies results (misreads_focus).","D":"Every program named belongs to the Owls alone, so the scope claim is false (wrong_scope)."}', 'The passage stays on one club''s community programs, so a yes-verdict is right only when its **reason** matches that content.', 'Students verify only the yes-or-no verdict and grab the first ''Yes'' option without fact-checking its stated reason.', '1) Restate the proposed goal in your own words. 2) Summarize what the passage actually covers. 3) Decide yes or no by comparing the two. 4) Treat each option''s reason as a factual claim and verify it against the text. 5) Choose the option where verdict and reason are both accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d4796cfe1fc23b1a', 'act-english', 's-rhet', 2, 'After the long walk between the rows, visitors say, the first cup of fresh cider tastes <u>totally awesome</u>.', 'Which choice best maintains the essay''s measured, descriptive tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"ineffably transcendent","letter":"B"},{"is_no_change":false,"label":"crisp and bright","letter":"C"},{"is_no_change":false,"label":"pretty amazing, honestly","letter":"D"}]', 'C', '{"A":"''Totally awesome'' is slangy exclamation that breaks the essay''s measured register.","B":"''Ineffably transcendent'' overshoots into lofty, purple diction that is just as out of place.","C":"Correct: ''crisp and bright'' describes the taste in plain, evocative words that match the essay''s register.","D":"''Pretty amazing, honestly'' keeps the casual, conversational register the essay avoids."}', 'Tone questions reward the option matching the passage''s **register** — here, plain but descriptive.', '''Ineffably transcendent'' sounds impressively formal, so students equate fancier with more appropriate.', '1) Identify the passage''s register from its other sentences (formal, neutral, casual). 2) Rate each option''s register. 3) Eliminate both the too-casual and the too-lofty extremes. 4) Choose the one that could blend invisibly into the surrounding prose.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-da6e001ecbd7d2fd', 'act-english', 's-rhet', 2, 'Gas sensors on the crater rim sample the volcano''s breath around the clock. Rising magma releases dissolved gases long before it reaches the surface, so a shift in the plume''s chemistry can be the earliest sign of trouble.', 'The writer is considering adding the following sentence after the last sentence of the paragraph: "At one closely watched volcano, sulfur dioxide output tripled in the week before fresh lava appeared." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it supplies a specific case of the early warning the paragraph describes.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains how the gas sensors were installed on the rim.","letter":"B"},{"is_no_change":false,"label":"No, because the paragraph has already given a specific case of a chemical warning.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus from gas chemistry to lava hazards.","letter":"D"}]', 'A', '{"A":"Correct: the sentence grounds the paragraph''s general claim in one concrete, striking instance.","B":"Reaches the right verdict for a false reason — the sentence says nothing about installation.","C":"False — the paragraph so far speaks only in general terms, with no concrete instance.","D":"False — lava appears only as the endpoint proving the chemical warning came early."}', 'The sentence **illustrates** the paragraph''s claim that chemistry shifts warn early, so it belongs — and this reason names that contribution accurately.', 'The word ''lava'' makes the sentence look off-topic at a glance, so the focus-shift objection attracts hasty readers.', '1) State the paragraph''s claim in one line. 2) Ask what the proposed sentence contributes: proof, illustration, digression, or repetition? 3) Match the yes/no verdict to that contribution. 4) Then vet the stated reason: it must describe the sentence accurately, not just reach the right verdict.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dfd75410d01e1797', 'act-english', 's-rhet', 2, 'The lifeguard <u>swam</u> toward the struggling swimmer.', 'The writer wants to emphasize the speed of the rescue. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"sprinted through the surf","letter":"B"},{"is_no_change":false,"label":"made her way","letter":"C"},{"is_no_change":false,"label":"eventually paddled","letter":"D"}]', 'B', '{"A":"''Swam'' is accurate but neutral — it says nothing about speed.","B":"''Sprinted through the surf'' is vivid and fast — exactly the urgency the writer wants.","C":"''Made her way'' is leisurely, the opposite of urgent.","D":"''Eventually paddled'' makes the rescue sound slow and reluctant."}', 'When the stem states the writer''s goal, pick the choice that **delivers that goal** most strongly.', 'Accurate-but-bland options like ''swam'' feel safe because nothing is wrong with them grammatically.', 'Goal questions are not grammar questions — grade each choice against the stated purpose alone.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e35b639a0ec356e0', 'act-english', 's-rhet', 2, 'During rush hour, Route 9 buses <u>move</u> along the new bus-only lane while car traffic idles beside them.', 'The writer wants to emphasize how fast the buses travel in the new lane compared with the cars beside them. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"proceed","letter":"B"},{"is_no_change":false,"label":"streak","letter":"C"},{"is_no_change":false,"label":"crawl","letter":"D"}]', 'C', '{"A":"''Move'' states motion without any sense of pace, so it does nothing for the stated goal.","B":"''Proceed'' sounds more formal but is just as neutral about speed — the misconception that elevated diction equals effectiveness.","C":"''Streak'' builds rapid motion into the verb itself, sharpening the contrast with the idling cars.","D":"''Crawl'' emphasizes slowness — the opposite of the writer''s stated goal."}', 'Only this verb carries **speed** in its own meaning, achieving the writer''s stated emphasis.', '''Proceed'' sounds official and polished, so students mistake formality for accomplishing the goal.', '1) Restate the writer''s goal in your own words. 2) Test each verb alone: does it carry the target quality without help from other words? 3) Eliminate neutral verbs, then verbs suggesting the opposite quality. 4) Keep the verb whose built-in picture matches the goal. 5) Re-read the sentence to confirm the contrast lands.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e75cd1d4cd194073', 'act-english', 's-rhet', 2, 'The essay recounts how a volunteer astronomy club runs free star parties in city parks, lends telescopes through the public library, and visits classrooms with a portable planetarium.', 'Suppose the writer''s goal had been to show how a volunteer organization makes astronomy accessible to the general public. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because the essay details the club''s free public programs and community events.","letter":"A"},{"is_no_change":false,"label":"Yes, because the essay details the physics that lets telescopes magnify faint, distant objects.","letter":"B"},{"is_no_change":false,"label":"No, because the essay is a history of professional astronomy, not of community outreach.","letter":"C"},{"is_no_change":false,"label":"No, because the essay focuses on the club''s fundraising rather than on its public programs.","letter":"D"}]', 'A', '{"A":"Correct: the essay''s content—parks, library loans, classroom visits—is exactly public-facing accessibility.","B":"Right verdict, wrong evidence: the essay never explains optics or magnification.","C":"Mischaracterizes the essay, which follows a present-day volunteer club, not the history of a profession.","D":"False premise: fundraising never appears in the essay."}', 'The verdict and the **reason** must both fit: the essay''s actual content is a catalog of ways the club brings astronomy to the public.', 'The optics-based ''yes'' tempts students because its verdict matches their instinct, so they skip checking whether the reason describes the essay.', '1) Restate the proposed goal in your own words. 2) List what the essay actually covers. 3) Decide yes/no by comparing the two lists. 4) Then audit the reason attached to your verdict: it must describe content that is really in the essay. 5) Reject any pairing where the reason is untrue, even if the verdict feels right.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e7e1833dfbf515e1', 'act-english', 's-rhet', 2, 'Ella Fitzgerald''s scat choruses were not random syllables; they were improvised melodies built with a horn player''s logic. Onstage, she treated her voice as one instrument among the band''s many.', 'Given that all the choices are true, which one, if added after the last sentence, would provide the detail most relevant to the paragraph''s focus on Fitzgerald''s voice working like an instrument?', '[{"is_no_change":false,"label":"She won an amateur-night contest at the Apollo Theater in 1934 as a teenager.","letter":"A"},{"is_no_change":false,"label":"Her songbook albums of the 1950s sold steadily for decades after their release.","letter":"B"},{"is_no_change":false,"label":"She traded four-bar exchanges with the trumpeters, mirroring every figure they threw at her.","letter":"C"},{"is_no_change":false,"label":"She toured internationally with the Jazz at the Philharmonic troupe for many seasons.","letter":"D"}]', 'C', '{"A":"add_offtopic_bio: the contest is career trivia, not evidence of instrument-like singing.","B":"Sales measure popularity, not musicianship, so the detail misses the paragraph''s claim.","C":"Correct: matching the horns phrase for phrase directly shows her voice functioning as an instrument.","D":"Touring shows fame and stamina, not the vocal-instrument idea."}', 'It gives a concrete onstage scene of the voice doing an **instrument''s** job alongside the horns.', 'The Apollo story is famous and feels essential to any Fitzgerald paragraph, but fame is not this paragraph''s focus.', '1) Write the paragraph''s focus as a short phrase. 2) For every option ask: does this show that phrase in action? 3) Discard details that are true and interesting but show something else. 4) Keep the one that could serve as evidence for the paragraph''s claim.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ea7d2862984dd53c', 'act-english', 's-rhet', 2, 'The children''s picture book explained that when winter comes, the little bear <u>enters a state of dormancy</u> until spring.', 'Which choice best matches the picture book''s audience of young children?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"undergoes seasonal torpor","letter":"B"},{"is_no_change":false,"label":"curls up and sleeps","letter":"C"},{"is_no_change":false,"label":"reduces its metabolic rate","letter":"D"}]', 'C', '{"A":"''Enters a state of dormancy'' is technical language a small child won''t understand.","B":"''Undergoes seasonal torpor'' is even more clinical.","C":"''Curls up and sleeps'' is simple, warm, and perfect for young readers.","D":"''Reduces its metabolic rate'' is scientific jargon, wrong for the audience."}', 'A picture book for children needs **simple, concrete language** like ''curls up and sleeps''.', 'The precise scientific phrasings seem ''more correct'', but they miss the young audience entirely.', 'Register follows audience — for children, choose plain, vivid words over technical accuracy.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-eddb33388adf6eda', 'act-english', 's-rhet', 2, '<p>The tool-lending shed anchors the garden''s thrifty culture. Inside, members can borrow spades, hoses, wheelbarrows, and even a gas-powered tiller.</p>', 'At this point, the writer wants to add a true statement that emphasizes how much money the shed saves members. Which choice best accomplishes the writer''s goal?', '[{"is_no_change":false,"label":"The shed''s pegboard was donated by a hardware store on Fulton Avenue.","letter":"A"},{"is_no_change":false,"label":"Members must sign each tool out and return it within three days.","letter":"B"},{"is_no_change":false,"label":"Checking out the tiller saves members the forty-dollar daily rate that rental shops charge.","letter":"C"},{"is_no_change":false,"label":"Rental shops in town also carry gas-powered tillers.","letter":"D"}]', 'C', '{"A":"About the shed''s furnishings and history, not about any money members avoid spending.","B":"A procedural rule about borrowing; it contains no financial content at all.","C":"Correct: it names a specific amount members avoid paying, making the financial benefit explicit.","D":"Mentions related businesses but states no comparison or benefit, leaving the savings unexpressed."}', 'Only this choice makes the financial advantage **explicit**, quantifying exactly what members avoid paying.', 'The mention of rental shops feels money-adjacent, so students pick it even though it never states any benefit to members.', '1) Underline the goal''s key idea in the stem — here, money kept in members'' pockets. 2) Test each statement: does it name or clearly imply that benefit? 3) Discard details that are merely related to the topic without delivering the goal. 4) Prefer the statement that makes the benefit concrete and specific. 5) Reread the paragraph with the addition to confirm the emphasis lands.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ee7803c1eff72c92', 'act-english', 's-rhet', 2, 'Among seahorses, it is the father, not the mother, who nurtures the next generation. _____ After several weeks, he releases dozens of fully formed young into the open water.', 'The writer wants to add a detail that supports the paragraph''s focus on the father seahorse''s role in reproduction. Which choice best accomplishes this goal?', '[{"is_no_change":false,"label":"Seahorses are found in shallow tropical waters all around the world.","letter":"A"},{"is_no_change":false,"label":"He carries the developing eggs in a protective pouch on his belly until they hatch.","letter":"B"},{"is_no_change":false,"label":"Seahorses swim upright and are, in fact, remarkably poor swimmers.","letter":"C"},{"is_no_change":false,"label":"A seahorse''s two eyes can swivel independently of each other.","letter":"D"}]', 'B', '{"A":"Gives habitat information, unrelated to the parental role the goal specifies (detail_offtopic).","B":"Correct: it describes exactly how the father carries and protects the young, supporting the stated focus.","C":"Describes swimming ability, not the reproductive role in focus (detail_offtopic).","D":"An anatomy fact about eyesight, unrelated to the parenting focus (detail_offtopic)."}', 'A relevant detail must directly develop the paragraph''s stated **focus** — the father''s part in raising the young.', 'The off-topic facts are all true and interesting about seahorses, so students pick a trivia item over a focused one.', '1) Restate the paragraph''s focus from the goal. 2) For each option, ask whether it develops that exact focus. 3) Discard true-but-off-topic facts. 4) Choose the detail that advances the stated point.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f431005ec80cd809', 'act-english', 's-rhet', 2, 'After developing a roll of film, many photographers make a contact sheet before printing anything at full size. The negatives are laid directly on a sheet of photographic paper and exposed, producing a page of frame-sized images. Studying these tiny previews, the photographer circles the frames worth enlarging with a grease pencil.', 'The writer is considering adding the following sentence at the end of the paragraph: "The grease pencil''s waxy marks wipe off with a soft cloth, so no selection is ever permanent." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it demonstrates that grease pencils outperform every other marking tool.","letter":"A"},{"is_no_change":false,"label":"Yes, because it adds a relevant detail about the marking tool described in the final sentence.","letter":"B"},{"is_no_change":false,"label":"No, because it introduces information about a tool unrelated to reviewing the contact sheet.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats a detail already stated earlier in the paragraph.","letter":"D"}]', 'B', '{"A":"Reaches the right verdict for a wrong reason (yes_overclaim): the new sentence compares the pencil to nothing, so it cannot show superiority.","B":"Correct: the sentence extends the grease-pencil detail just introduced, explaining why circling frames is a low-stakes step.","C":"Misreads the sentence''s subject (no_false_irrelevance): the pencil is exactly the tool the paragraph''s last sentence puts in the photographer''s hand.","D":"Claims repetition that never occurred (no_false_repetition): erasability appears nowhere earlier in the paragraph."}', 'The new sentence **builds on** the grease-pencil detail that immediately precedes it, so it belongs.', 'Students who skim past the last sentence assume the pencil is new, off-topic equipment and reject the addition as irrelevant.', '1) Find what the proposed sentence is about. 2) Locate that subject in the paragraph — is it present, and where? 3) If present and adjacent, the sentence likely belongs; if absent, it likely does not. 4) Then audit the stated reason: accept an option only when both its verdict and its reason are true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f5935917bf02bf12', 'act-english', 's-rhet', 2, 'The grant application stated that the clinic''s waiting room was <u>super cramped</u> and needed expansion.', 'Which choice best matches the formal register of a grant application?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"way too small","letter":"B"},{"is_no_change":false,"label":"overcrowded","letter":"C"},{"is_no_change":false,"label":"a total squeeze","letter":"D"}]', 'C', '{"A":"''Super cramped'' is casual slang, out of place in a formal application.","B":"''Way too small'' is equally colloquial.","C":"''Overcrowded'' is precise and formal, fitting the document''s register.","D":"''A total squeeze'' is idiomatic and informal."}', 'A grant application requires **formal diction**, and ''overcrowded'' is the neutral, professional term.', 'The casual options feel expressive, but expressiveness isn''t what a formal document rewards.', 'Name the passage''s register first, then choose the word that belongs to it.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f88cc99560c2f6f7', 'act-english', 's-rhet', 2, 'By noon in July, the salt flats of Death Valley <u>get warm</u> beneath a cloudless sky.', 'The writer wants to emphasize the extreme intensity of the desert heat. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"bake","letter":"B"},{"is_no_change":false,"label":"warm up steadily","letter":"C"},{"is_no_change":false,"label":"sit in the sunshine","letter":"D"}]', 'B', '{"A":"''Get warm'' describes mild, pleasant heat, undercutting the intended extremity.","B":"Evokes oven-level heat in a single vivid verb, matching the writer''s goal.","C":"Adds a pace but keeps the temperature mild.","D":"Abandons temperature altogether for a neutral image."}', 'The goal is **intensity**, and only one verb conveys punishing, oven-like heat.', '''Warm up steadily'' feels more descriptive than the original, so students credit added words instead of added heat.', '1) Restate the writer''s stated goal in one word. 2) Rate each option against that word only. 3) Ignore which option sounds fanciest or longest. 4) Pick the option scoring highest on the goal, provided it stays grammatical.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fb75daad8cec3c8b', 'act-english', 's-rhet', 2, 'Predicting snowfall totals for a single town is among the hardest jobs in forecasting. A thirty-mile shift in a storm''s track can turn a dusting into a foot of snow. Temperature differences too small for most instruments to flag can decide whether roads stay merely wet or glaze over with ice.', 'The writer is considering adding the following sentence:

*Because school superintendents must often decide on closings by 5 a.m., they depend on these hair-thin margins hours before the first flake falls.*

Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it illustrates a real-world stake that depends on the fine distinctions the paragraph describes.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why storm tracks shift as storms approach a town.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information given earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus to debates over school policy.","letter":"D"}]', 'A', '{"A":"Correct: the sentence shows who must act on the paragraph''s tiny margins, adding a concrete stake without changing the subject.","B":"The sentence says nothing about why tracks shift, so this reason misdescribes what the addition does (misconception: right verdict paired with an unexamined reason).","C":"Nothing earlier mentions superintendents or deadlines, so the sentence repeats nothing (misconception: same general topic equals repetition).","D":"One sentence about a decision deadline does not open a policy debate; the emphasis stays on forecasting''s fine margins (misconception: any new actor equals a new focus)."}', 'The addition supplies a **concrete consequence** of the forecasting difficulty the paragraph details, and the reason accurately says so.', 'The ''No'' option about shifting focus tempts readers who see a new character — a superintendent — and assume the topic changed with it.', '1) Decide the verdict first: does the sentence serve the paragraph''s purpose? 2) Then audit the reason: does it accurately describe what the sentence does? 3) Reject right verdicts with wrong reasons. 4) Reject wrong verdicts however plausible the reason sounds. 5) Keep the pairing where verdict and reason are both true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fbc9347b1ec967a8', 'act-english', 's-rhet', 2, 'Volunteers have logged every bat that passes the river gauge since 2019. The counts rise sharply in the week after the streetlights along the levee are dimmed for turtle nesting season.', 'At this point, the writer is considering adding the following sentence: "Last July, a single dimmed week produced the highest one-night count in the project''s history." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it supports the paragraph''s point with a specific, striking data point.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why the streetlights along the levee are dimmed each summer.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats the information about turtle nesting season.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus from bats to streetlight technology.","letter":"D"}]', 'A', '{"A":"Correct: the record-setting count is concrete evidence for the trend the previous sentence describes.","B":"Right verdict, wrong reason: the dimming''s purpose is already stated, and the new sentence never explains it (add_right_verdict_wrong_reason).","C":"False premise: the proposed sentence contains no nesting-season material to repeat (add_false_repetition).","D":"False premise: the sentence is about a bat count; streetlights appear only as background (add_false_shift)."}', 'The sentence adds a **specific supporting example** of the exact trend the paragraph just asserted, so both the verdict and the reason fit.', 'The wrong-reason ''Yes'' tempts students who feel the sentence belongs but grab the first justification without checking it against the sentence''s actual content.', '1) Decide the verdict first: does the sentence serve the paragraph''s focus? 2) Then audit the reason: does it accurately describe what the sentence contains? 3) Reject any option whose reason misdescribes the sentence, even if its verdict feels right. 4) Reject any verdict built on a false premise. 5) Keep the option where verdict and reason both check out.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fdb11968b08ef02b', 'act-english', 's-rhet', 2, 'After twelve-hour shifts at the cannery, my grandfather walked to English classes held in a church basement. His notebook, which my mother still keeps, shows column after column of vocabulary words copied in careful script. Within two years, he was translating letters for neighbors up and down the block.', 'The writer is considering adding the following sentence after the second sentence: ''Classmates later remembered that he stayed after each lesson to practice conversation with the volunteer teacher.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why the cannery demanded such long shifts.","letter":"A"},{"is_no_change":false,"label":"Yes, because it offers further evidence of the grandfather''s commitment to learning English.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information the paragraph has already provided about the notebook.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts attention from the grandfather''s studying to the volunteer teacher.","letter":"D"}]', 'B', '{"A":"The addition is justified, but not for this reason — the sentence says nothing about the cannery''s schedule.","B":"Correct: the detail extends the paragraph''s picture of the grandfather working doggedly at English.","C":"The proposed sentence adds spoken practice, a new fact, not a repetition of the written notebook detail.","D":"The grandfather remains the subject and focus; the teacher is incidental background."}', 'The sentence adds a **supporting** detail that deepens the paragraph''s single focus on the grandfather''s determination.', 'The repetition objection tempts students because the notebook and the after-class practice both involve studying, though they are different facts.', '1) State the paragraph''s focus in one phrase. 2) Ask whether the proposed sentence develops that focus, repeats it, or derails it. 3) Decide add or omit. 4) Then vet the stated reason: it must match what the sentence actually does. 5) Reject right verdicts wearing wrong reasons.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ff453e5783b1bca1', 'act-english', 's-rhet', 2, 'The Deer Creek Bugle once printed twice a week; now it prints only on Thursdays. Yet the paper''s newsroom is busier than ever. Last fall, its two reporters began recording a weekly podcast in the old darkroom, answering listener questions about county government. The Bugle''s website now posts game scores the same night they happen, and its email edition follows readers who moved away decades ago.', 'Suppose the writer''s goal had been to show how a small-town newspaper is adapting to a changing media landscape. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it argues that print is superior to new media like podcasts.","letter":"A"},{"is_no_change":false,"label":"No, because it describes the specific efforts of only one paper rather than the whole industry.","letter":"B"},{"is_no_change":false,"label":"Yes, because it describes specific changes the Bugle has made to reach new audiences.","letter":"C"},{"is_no_change":false,"label":"No, because it never explains why the Bugle made these changes to its operations.","letter":"D"}]', 'C', '{"A":"Misreads the essay — it never compares print''s merits to any other medium, let alone argues superiority.","B":"Over-demands: a goal about ''a small-town newspaper'' is satisfied by one paper''s story.","C":"Correct: the podcast, same-night scores, and email edition are exactly the adaptations the stated goal asks for.","D":"Invents a requirement; the goal concerns how the paper is adapting, not why it cut a print day."}', 'The essay catalogs concrete **adaptations** — podcast, instant scores, email edition — which is precisely what the supposed goal requests.', 'The one-paper objection tempts students who assume a broad-sounding goal requires industry-wide evidence.', '1) Restate the supposed goal precisely, noting its scope (''a small-town newspaper,'' singular). 2) List what the essay actually does, sentence by sentence. 3) Match: does the essay''s content fit the goal''s scope and subject? 4) Check each option''s stated warrant against both the goal and the essay. 5) Keep the option whose verdict and warrant are both accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0276d7482d99c6c4', 'act-english', 's-rhet', 3, 'Loyal readers often say they subscribe to the Sentinel mainly for its community calendar. The calendar lists every gathering in the county, from pancake breakfasts to school-board meetings, and it appears in the same spot on page three each week.', 'The writer wants to add a sentence that most strongly supports the paragraph''s claim that the calendar keeps subscribers loyal. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The Sentinel''s calendar has been edited by the same staff member for eleven years.","letter":"A"},{"is_no_change":false,"label":"In a recent survey, half of the Sentinel''s subscribers named the calendar as the top reason they renew.","letter":"B"},{"is_no_change":false,"label":"Subscribers can renew by mail, by phone, or at the newspaper''s front counter.","letter":"C"},{"is_no_change":false,"label":"One recent addition to the calendar is a listing of library story hours.","letter":"D"}]', 'B', '{"A":"Describes the calendar''s staffing, which says nothing about why subscribers stay.","B":"Correct: it gives direct evidence tying the calendar to subscribers'' decisions to renew.","C":"Lists renewal methods, not motives — the calendar never enters the sentence.","D":"Adds calendar content but draws no link to subscriber loyalty."}', 'It is the only option that **links both ends** of the claim — the calendar and subscribers'' decisions to stay.', 'The staffing detail tempts students because an editor''s longevity feels like proof of quality, which they mistake for proof of loyalty.', '1) Underline the claim to be supported (''the calendar keeps subscribers loyal''). 2) For each option, ask: does it connect the calendar to subscribers'' staying? 3) Discard sentences about the calendar alone or about subscribing alone. 4) Prefer concrete evidence of the link over adjacent facts. 5) Re-read the paragraph with the winner inserted.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-04f53a60dbd93cf5', 'act-english', 's-rhet', 3, 'Many desert plants seem to sense a coming storm before the first drop falls. Ocotillo, leafless for months, unfurl fresh green within hours of a downpour. Certain seeds break their long dormancy only after a soaking heavy enough to rinse away the chemicals that keep them asleep.', 'At this point the writer is considering adding the following sentence: ''The nearest paved highway runs some forty miles to the west.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it helps readers picture how remote this stretch of desert is.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains how the plants sense that a storm is coming.","letter":"B"},{"is_no_change":false,"label":"No, because the essay has already described the region''s roads earlier.","letter":"C"},{"is_no_change":false,"label":"No, because it adds information unrelated to the paragraph''s subject of how plants react to moisture.","letter":"D"}]', 'D', '{"A":"Endorses adding an off-topic geographic fact for a reason the paragraph never pursues (add_offtopic).","B":"Claims the highway sentence explains the plants'' sensing, which it plainly does not (false_justification).","C":"Rejects the sentence for a reason the passage does not support, since no roads were mentioned before (false_premise).","D":"Correct: the highway''s distance has nothing to do with the paragraph''s subject of plants reacting to moisture, so it should be left out."}', 'The proposed sentence introduces a fact **irrelevant** to the paragraph''s subject, so it should not be added.', 'The remoteness reason sounds plausible because vivid setting details often enrich writing, so students accept it without testing relevance.', '1) State the paragraph''s single subject (how plants react to moisture). 2) Read the proposed sentence and ask whether it advances that subject. 3) If it does not, the sentence should be cut regardless of how interesting it is. 4) Then check that the reason given matches the true problem. 5) Choose the yes/no answer whose reason is both correct and accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-094d179f9d24a600', 'act-english', 's-rhet', 3, 'As the weaver worked, the shuttle <u>moved</u> across the warp, trailing its thin line of weft.', 'The writer wants to emphasize the shuttle''s speed and lightness as it crosses the loom. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"darted","letter":"B"},{"is_no_change":false,"label":"was carried","letter":"C"},{"is_no_change":false,"label":"inched","letter":"D"}]', 'B', '{"A":"''Moved'' is grammatically fine but generic; it conveys no speed or lightness at all.","B":"Correct: the verb evokes a quick, light, arrow-like crossing, exactly the stated emphasis.","C":"The passive drains the shuttle of agency and suggests slow, deliberate handling.","D":"The verb signals painstaking slowness — the opposite of the stated goal."}', 'The chosen verb must **enact** the stated goal — quickness and lightness — not merely describe motion.', 'The original tempts because it is safe and correct, but goal questions reward the precise verb, not the neutral one.', '1) Restate the writer''s goal in two words. 2) For each option, list the qualities the word actually conveys. 3) Strike options that are neutral, contrary, or off-key. 4) Choose the one whose connotations match the goal exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0965ed6ac4c30558', 'act-english', 's-rhet', 3, 'The company''s press release announced that after the merger, some employees would <u>get the axe</u> before the end of the quarter.', 'Which choice best matches the measured, professional tone of a press release?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"be shown the door","letter":"B"},{"is_no_change":false,"label":"be let go","letter":"C"},{"is_no_change":false,"label":"get canned","letter":"D"}]', 'C', '{"A":"''Get the axe'' is a harsh idiom unsuited to an official statement.","B":"''Be shown the door'' is equally colloquial and blunt.","C":"''Be let go'' is the standard, tactful, professional phrasing.","D":"''Get canned'' is slang, the least formal option."}', 'A press release keeps a **professional, tactful register**, which ''be let go'' provides.', 'The idioms are vivid, but vividness reads as unprofessional in a corporate statement.', 'For official communications, choose the neutral, diplomatic wording over colorful idioms.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0cb092a65d8ea4cc', 'act-english', 's-rhet', 3, 'The lab notebook describes the emulsion precisely: as oil is added drop by drop, lecithin molecules coat each droplet and <u>prevent the fat and water from separating</u>.', 'Which choice best maintains the passage''s measured, scientific tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stop the greasy mess from splitting apart","letter":"B"},{"is_no_change":false,"label":"keep everything from totally falling to pieces","letter":"C"},{"is_no_change":false,"label":"boss the fat and water into behaving","letter":"D"}]', 'A', '{"A":"Correct: the neutral, precise wording matches the notebook''s measured scientific register.","B":"Register clash: ''greasy mess'' is colloquial and dismissive, breaking the clinical tone.","C":"Too loose: ''totally falling to pieces'' is casual hyperbole out of place in a lab notebook.","D":"Figurative slang: ''boss ... into behaving'' personifies the molecules in a jokey, informal way."}', 'The passage keeps a **measured scientific register**, and only the neutral, precise phrasing sustains it.', 'The livelier phrasings feel more engaging, and students often assume vivid always beats plain, even in a technical context.', '1) Name the passage''s established tone — here, precise and scientific. 2) Read each option and flag any slang, hyperbole, or joking figure. 3) Eliminate options whose register clashes with the passage. 4) Keep the wording that blends in seamlessly. 5) Reread the full sentence to confirm the tone holds steady.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-130f47f21c8bbf5f', 'act-english', 's-rhet', 3, 'The essay recounts Saturday mornings in the author''s childhood kitchen, where a green enamel radio sat above the stove. The author describes her grandmother humming along to border-station ballads, the smell of toast, and the static that arrived with every thunderstorm. The essay closes with the author finding the same model radio at an estate sale decades later and carrying it home.', 'Suppose the writer''s goal had been to trace how radio receiver design advanced from the 1920s through the 1950s. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it mentions a radio manufactured decades before the author found it.","letter":"A"},{"is_no_change":false,"label":"Yes, because it shows the radio remained useful across two generations.","letter":"B"},{"is_no_change":false,"label":"No, because it centers on personal memories rather than on changes in receiver design.","letter":"C"},{"is_no_change":false,"label":"No, because it never gives the radio''s model year or other design details.","letter":"D"}]', 'C', '{"A":"A single old radio appearing in an essay is a passing mention, not sustained coverage of design history.","B":"Durability across generations is a different claim from tracing how designs evolved.","C":"Correct: the essay is a family reminiscence, so its subject matter never engages the stated technical goal.","D":"Right verdict, wrong reason: adding a model year would not turn a reminiscence into a survey of design history."}', 'Judging a purpose question means matching the essay''s **actual subject** to the stated goal, and this essay''s subject is family life, not engineering.', 'The no-verdict about missing product details tempts students because it is factually true of the essay, even though it misdiagnoses why the goal fails.', '1) Restate the hypothetical goal in your own words. 2) Summarize what the essay actually spends its space on. 3) Decide yes/no by comparing the two subjects. 4) Then audit the reason: it must name the real match or mismatch, not an incidental fact. 5) Reject true-but-irrelevant reasons.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-18d3f2f346c7004c', 'act-english', 's-rhet', 3, 'The council''s audit of the paving contract, released Tuesday and summarized on the Sentinel''s front page, <u>was a total train wreck for</u> the mayor''s downtown plan.', 'Which choice best maintains the formal, reportorial tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"raised serious doubts about","letter":"B"},{"is_no_change":false,"label":"was kind of a bummer for","letter":"C"},{"is_no_change":false,"label":"catastrophically annihilated","letter":"D"}]', 'B', '{"A":"''Total train wreck'' is casual slang that clashes with the measured news-report register.","B":"Correct: measured and precise, matching the passage''s reportorial diction.","C":"''Kind of a bummer'' is even more conversational than the original.","D":"Grammatical but melodramatic — editorializing overstatement rather than neutral reporting."}', 'It keeps the sentence in the passage''s **measured, reportorial register** while still conveying that the audit hurt the plan.', 'The melodramatic option tempts students because its forcefulness sounds impressively decisive.', '1) Sample the passage''s diction from the non-underlined parts. 2) Label the register: formal report, casual talk, or dramatic commentary. 3) Read each option in the sentence and label its register the same way. 4) Reject any option whose label differs from the passage''s. 5) Keep the one that blends in.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1a6312d5d2dbefdb', 'act-english', 's-rhet', 3, 'At the May plant sale, every flat of heirloom tomato seedlings <u>sold</u> before the volunteers finished setting up the second table.', 'The writer wants to convey how eagerly shoppers bought up the seedlings. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was snapped up","letter":"B"},{"is_no_change":false,"label":"was accounted for","letter":"C"},{"is_no_change":false,"label":"was reasonably priced","letter":"D"}]', 'B', '{"A":"Grammatical but neutral: ''sold'' reports the transaction without any of the eagerness the writer wants.","B":"Correct: the vivid phrasing shows buyers seizing the flats quickly, directly conveying eagerness.","C":"Bookkeeping connotation: it makes the sale sound administrative rather than enthusiastic.","D":"Off goal: a comment on pricing may explain the sales but does not show eager shoppers."}', 'The goal demands a phrase that **dramatizes** shoppers'' eagerness, and only the vivid grabbing image shows buyers rushing for the flats.', 'The original verb is correct and familiar, so students keep it without noticing it fails the specific goal the stem announces.', '1) Underline the goal stated in the stem — here, conveying shoppers'' eagerness. 2) Test each phrasing only against that goal, not against grammar alone. 3) Discard any version that is neutral, off-topic, or focused elsewhere, however correct it sounds. 4) Pick the one whose imagery delivers the goal. 5) Reread the sentence to confirm tone and grammar still hold.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1d1287067e8530e5', 'act-english', 's-rhet', 3, 'To persuade the school board, the petition stressed that <u>some people think</u> the crossing is dangerous.', 'Which choice best strengthens the petition''s persuasive appeal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"three documented accidents this year show","letter":"B"},{"is_no_change":false,"label":"it kind of seems like","letter":"C"},{"is_no_change":false,"label":"a lot of folks feel","letter":"D"}]', 'B', '{"A":"''Some people think'' is vague opinion that gives the board little reason to act.","B":"Concrete evidence — ''three documented accidents this year'' — makes the strongest case.","C":"''It kind of seems like'' is tentative and undercuts persuasion.","D":"''A lot of folks feel'' is still unsupported opinion, just more casual."}', 'Persuasion is strongest with **specific evidence** (logos), not vague opinion.', 'The opinion phrasings feel safe and inoffensive, but they don''t move a decision-maker.', 'To persuade, prefer verifiable facts and figures over hedged ''some people think'' claims.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1d51ac11e1e5086f', 'act-english', 's-rhet', 3, 'The greenroom''s north wall carries the signature of every cast member since 1998. On each opening night, the current cast gathers there before curtain to add their names in silver ink. The writer is considering adding the following sentence after this description: <i>"Alumni often return years later and search the wall until they find their own names among the hundreds."</i>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it demonstrates the enduring value of the signing custom for former cast members.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains how the crew repaints the greenroom wall each season.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats details about the signing custom already given in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus to the school''s fundraising efforts.","letter":"D"}]', 'A', '{"A":"Correct: the addition extends the tradition''s story into later years, showing it still matters to those who once signed.","B":"The proposed sentence never mentions repainting or maintenance, so this reason misdescribes it (reason_misreads_addition).","C":"The paragraph has said nothing about what happens years later, so the sentence adds new information rather than repeating any (reason_false_repetition).","D":"Nothing in the sentence involves money or donations, so the claimed focus-shift is invented (reason_invented_shift)."}', 'The addition is **relevant** because it deepens the paragraph''s account of the tradition by showing its lasting pull on those who signed long ago.', 'The repetition-based rejection tempts students because the new sentence revisits the same wall, making it feel like old information at a glance.', '1) Restate the paragraph''s focus in one phrase. 2) Restate what the proposed sentence literally says. 3) Decide whether it develops the focus, repeats it, or departs from it. 4) Check each reason against both the sentence''s content and the paragraph''s content. 5) Accept only a verdict whose reason is factually true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-267f4e47085f4240', 'act-english', 's-rhet', 3, '[1] In the hour before each match, the drive team follows a strict routine. [2] The operator recalibrates the arm presets while the driver walks the field to note any new wear in the carpet. [3] Our school''s cafeteria began offering a vegetarian lunch line this year. [4] Finally, the coach reviews the opposing alliance''s scouting data and assigns defensive priorities.', 'The writer wants this paragraph to stay focused on how the drive team prepares before each match. Which sentence should be deleted to preserve that focus?', '[{"is_no_change":false,"label":"Sentence 1.","letter":"A"},{"is_no_change":false,"label":"Sentence 2.","letter":"B"},{"is_no_change":false,"label":"Sentence 3.","letter":"C"},{"is_no_change":false,"label":"Sentence 4.","letter":"D"}]', 'C', '{"A":"Deletes the topic sentence that frames every step in the routine (delete_topic_sentence).","B":"Removes a direct example of pre-match preparation, weakening the focus (delete_on_topic_support).","C":"Correct: the cafeteria news has no connection to pre-match preparation.","D":"Cuts an on-topic preparation step because it appears last and adds new names (delete_final_support)."}', 'The cafeteria news has **no connection** to pre-match preparation, so deleting it preserves the paragraph''s focus.', 'Some students target the final sentence because it introduces new people and data at the end.', '1) Write the paragraph''s focus in one phrase. 2) Test each sentence: does it show that focus? 3) Delete the one sentence that fails the test — never the topic sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2b40164f6604f583', 'act-english', 's-rhet', 3, 'Each morning at the drill site follows the same sequence. The crew flushes the borehole, lowers the barrel, and brings up a meter of ice before noon. Every core is measured, sleeved, and logged within an hour of surfacing.', 'The writer is considering adding the following sentence after the second sentence: "The camp cook, meanwhile, is famous for his sourdough pancakes." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it shows that camp life involves more than drilling.","letter":"A"},{"is_no_change":false,"label":"Yes, because it adds a vivid detail about the drilling camp.","letter":"B"},{"is_no_change":false,"label":"No, because it interrupts the focused description of the drilling procedure.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats information about the camp cook given earlier.","letter":"D"}]', 'C', '{"A":"Broadening the picture of camp life is not this paragraph''s job, which is to trace one work sequence (add_offtopic justification).","B":"Vividness alone cannot justify a detail that pulls away from the paragraph''s single subject (color over relevance).","C":"The paragraph traces one tightly ordered work routine, and the pancake sentence breaks that thread.","D":"The reason is factually wrong — the cook has not been mentioned anywhere (false-premise reason)."}', 'The paragraph has a **single focus** — the morning drilling routine — and the proposed sentence departs from it.', '''A vivid detail'' sounds like good writing advice, so students accept color without checking relevance.', '1) State the paragraph''s focus in one clause. 2) Ask whether the proposed sentence advances that focus. 3) If yes, add it; if no, keep it out. 4) Then check the stated reason: it must be both true of the passage and about relevance. 5) Reject reasons that are factually false, even when the yes/no feels right.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2bc8d0bf9ceb096b', 'act-english', 's-rhet', 3, 'Every Saturday morning, three certified therapy dogs settle onto quilts in the story room, where beginning readers take turns reading aloud to them. The dogs never correct a mispronounced word or sigh at a slow page, so children who freeze up in class often relax within minutes. Parents report that the sessions have changed how their kids feel about books.', 'The writer wants to add a sentence giving a specific example of the confidence the sessions build in young readers. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Golden retrievers were first bred in Scotland during the nineteenth century.","letter":"A"},{"is_no_change":false,"label":"The story room''s carpet was replaced shortly after the sessions began.","letter":"B"},{"is_no_change":false,"label":"Nationwide, roughly two-thirds of households own at least one pet.","letter":"C"},{"is_no_change":false,"label":"After four Saturday visits, one second grader who once whispered every word now reads to the spaniel in a clear, steady voice.","letter":"D"}]', 'D', '{"A":"Dog-breed history is trivia about the animals, not evidence of a child''s growing confidence.","B":"Facility upkeep has nothing to do with the goal of illustrating a young reader''s progress.","C":"National pet-ownership data is off-goal background that says nothing about these children.","D":"Correct: it shows one named child''s measurable change, exactly the specific illustration the goal requests."}', 'The goal demands a **specific example** of a child''s growing confidence, and only this sentence shows an individual reader''s change.', 'The pet-ownership figure sounds authoritative and on-topic about animals, so students mistake broad data for a specific example.', '1) Underline the goal''s key requirements (here: specific, an example, about young readers'' confidence). 2) Test each option against every requirement, one at a time. 3) Eliminate options that are about something else, however true. 4) Eliminate broad data when a single case is requested. 5) Confirm the survivor satisfies all requirements at the same time.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2c0c03f708b7f556', 'act-english', 's-rhet', 3, 'Strain gauges glued to the girders send readings to a monitoring station every fifteen minutes. When a reading drifts outside the expected range, engineers dispatch a climbing team to inspect the joint firsthand. This constant stream of data lets the county repair small problems before they grow dangerous.', 'The writer is considering adding the following sentence to the paragraph: "The river below the span is popular with kayakers throughout the summer." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it shows that the bridge''s health matters to the local community.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why engineers monitor the span so closely.","letter":"B"},{"is_no_change":false,"label":"No, because it contradicts details given earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it pulls the paragraph away from its focus on monitoring the bridge''s health.","letter":"D"}]', 'D', '{"A":"Kayakers say nothing about sensors, readings, or repairs; community appeal is not the paragraph''s subject (misconception: add_offtopic_justified).","B":"The sentence offers a recreational aside, not an explanation of the inspection program''s purpose (misconception: add_false_explanation).","C":"Right verdict, wrong reason: nothing in the paragraph conflicts with summer kayaking (misconception: reject_wrong_reason_contradiction).","D":"Correctly rejects the sentence for irrelevance: the paragraph is a tight account of sensor-driven upkeep, and the detail develops none of it."}', 'A sentence earns its place only by developing the paragraph''s **central subject** — the sensor-based inspection system — which this recreational detail does not.', 'The contradiction option tempts students who sense the sentence does not belong but grab the first ''no'' reasoning without checking whether it is accurate.', '1) State the paragraph''s central subject in five words. 2) Ask whether the proposed sentence develops that subject. 3) If yes, verify the stated reason matches what the sentence actually does. 4) If no, choose the rejection whose reason names the real flaw. 5) Reread the paragraph to confirm the verdict.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-35b6cd8c1ad92d20', 'act-english', 's-rhet', 3, 'The engineering notebook reflects the team''s discipline: after each test, members <u>recorded the trial conditions and quantified every result</u> before proposing modifications.', 'Which choice best maintains the formal, technical tone established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"jotted down whatever seemed important","letter":"B"},{"is_no_change":false,"label":"totally geeked out over the numbers","letter":"C"},{"is_no_change":false,"label":"scribbled some quick notes on stuff","letter":"D"}]', 'A', '{"A":"Correct: the precise, technical diction matches the notebook''s formal register.","B":"Vague and offhand, clashing with the precise language around it (tone_casual_vague).","C":"Injects slang into measured technical prose (tone_slang).","D":"Suggests haste and carelessness, contradicting the discipline the sentence asserts (tone_careless_informal)."}', 'The original phrase''s precise, technical diction **matches** the notebook''s formal register.', 'The friendly, natural sound of the casual options is easily mistaken for good style.', '1) Identify the passage''s register from surrounding word choices. 2) Rate each option: slang, casual, neutral, or formal. 3) Keep the option matching the passage''s rating, regardless of which sounds most natural alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-36e71e7d7b966175', 'act-english', 's-rhet', 3, 'To validate the autonomous routine, the programmers ran the robot from the same starting position forty times in a single afternoon. They logged each run''s final coordinates and flagged any trial that ended more than five centimeters from the target. After adjusting one turning constant, the routine hit its mark in nineteen of the final twenty runs.', 'The writer is considering adding the following sentence after the second sentence of the paragraph: ''The team''s spring bake sale had raised almost four hundred dollars for new batteries.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it shows that the team succeeds at more than just engineering.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains how the team paid for its testing equipment.","letter":"B"},{"is_no_change":false,"label":"No, because it fails to say which students organized the bake sale.","letter":"C"},{"is_no_change":false,"label":"No, because it interrupts the account of the testing process with an unrelated fundraising detail.","letter":"D"}]', 'D', '{"A":"Approves the addition for boosting the team''s image, which is not the paragraph''s job (add_flattering_but_offtopic).","B":"Invents a funding question the paragraph never raises (add_false_relevance).","C":"Rejects the sentence for missing trivia rather than for being off-topic (delete_wrong_reason).","D":"Correct: the sentence breaks the step-by-step testing narrative with an off-topic fact."}', 'The bake-sale sentence **breaks** the step-by-step testing narrative with an off-topic fact, so it should not be added.', 'The battery connection in one ''yes'' option sounds logical because the tests really do use batteries.', '1) State the paragraph''s job in one sentence. 2) Ask whether the proposed sentence advances that job. 3) If not, choose ''no'' — then verify the stated reason targets relevance, not a trivial flaw.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-37e641442920347a', 'act-english', 's-rhet', 3, 'The tool-lending counter at the Dockside branch has become one of the library''s busiest services. Wait lists for ladders and hedge trimmers stretch weeks into the season, and staff field calls about cordless drills before the doors even open.', 'The writer is considering adding the following sentence after the last sentence of the paragraph: "A single post-hole digger was checked out forty-one times last summer." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it supplies a concrete statistic that supports the paragraph''s point about the counter''s popularity.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why the library first decided to lend tools.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information given earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it introduces a level of detail inconsistent with the paragraph''s general overview.","letter":"D"}]', 'A', '{"A":"Correct: the hard number is new, specific evidence that reinforces the paragraph''s claim about heavy demand.","B":"Right verdict, wrong reason — the sentence documents usage and says nothing about the program''s origins.","C":"The checkout figure appears nowhere earlier, so nothing is repeated.","D":"The paragraph is already built on specifics like wait lists and morning calls, so one more figure fits the established pattern."}', 'The sentence adds fresh, specific **evidence** for exactly the idea the paragraph is developing — the counter''s heavy use.', 'The ''yes'' option with the origin-story reason attracts students who judge only the verdict and never test whether the reason describes the sentence.', '1) State the paragraph''s main idea in one phrase. 2) State what the proposed sentence actually does — not what the reasons claim. 3) Decide add or omit based on whether it advances the main idea. 4) Then check that the chosen reason accurately describes the sentence. 5) Reject any option whose reason misdescribes it, even if the verdict matches yours.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3a4bd2a19334278e', 'act-english', 's-rhet', 3, 'At either end of the suspension bridge, a block of concrete the size of an apartment building sits buried in bedrock. Each anchorage <u>holds back the pull</u> of the main cables.', 'The writer wants to emphasize the enormous force the anchorages must resist. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"counters the pull","letter":"B"},{"is_no_change":false,"label":"strains against the colossal, sixty-thousand-ton pull","letter":"C"},{"is_no_change":false,"label":"is connected to the ends","letter":"D"}]', 'C', '{"A":"Reports the anchorage''s job in neutral terms without conveying scale (misconception: goal_neutral_wording).","B":"Swaps one plain verb for a synonym, leaving the emphasis unchanged (misconception: goal_synonym_no_emphasis).","C":"Dramatizes the force with a vivid verb and a staggering specific figure, directly serving the stated goal.","D":"Abandons the idea of force entirely, describing mere attachment (misconception: goal_drops_key_idea)."}', 'The stated goal is **emphasis on enormous force**, and only this wording quantifies the load and dramatizes the struggle to resist it.', 'The synonym swap feels like an improvement because it is a fresher verb, but changing the word without adding magnitude leaves the goal unmet.', '1) Restate the writer''s goal in your own words. 2) For each option, ask: does it convey that exact quality (here, sheer magnitude)? 3) Reject options that are merely grammatical, merely different, or off the goal. 4) Prefer wording with vivid, specific detail that makes the goal unmistakable. 5) Reread the sentence with the winner in place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3a6a71bdac491e70', 'act-english', 's-rhet', 3, '[1] Each February, the club invites residents to count the stars they can see inside Orion''s outline and to submit their tallies online. [2] Scientists use the counts to map how light pollution varies from neighborhood to neighborhood.<br><br>The writer is considering adding the following sentence after Sentence 1:<br><em>Orion is easy to locate on winter evenings, since its three-star belt stands out even under bright suburban skies.</em>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it proves that suburban neighborhoods have more light pollution than rural ones.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why the constellation is a workable choice for inexperienced observers.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information about the belt given elsewhere in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus from counting stars to constellation mythology.","letter":"D"}]', 'B', '{"A":"Wrong reason: the sentence notes visibility; it proves nothing about which neighborhoods are more polluted.","B":"Correct: the sentence justifies the project''s design by showing that beginners anywhere can find the target.","C":"False premise: no other sentence mentions the belt or its visibility, so nothing is repeated.","D":"False premise: the sentence says nothing about mythology; it stays on practical visibility."}', 'The addition is relevant because it **justifies the design choice** at the heart of the paragraph: a target that any resident can find.', 'The proof-based ''yes'' tempts students because it also endorses adding the sentence, but its stated reason misdescribes what the sentence actually does.', '1) State what the proposed sentence literally says. 2) State the paragraph''s focus in one phrase. 3) Decide yes/no: does the sentence support that focus? 4) Then vet the reason: it must accurately describe the sentence''s content and function—reject any verdict whose reason misstates either.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3ba00e89f0a27d0d', 'act-english', 's-rhet', 3, 'Conservators handled the embroidered kimono with practiced restraint, noting in their report that its silk cranes were <u>a pretty big deal</u> in Edo-period symbolism.', 'Which choice best maintains the formal, professional tone established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a really huge thing","letter":"B"},{"is_no_change":false,"label":"of considerable significance","letter":"C"},{"is_no_change":false,"label":"the most stupendously momentous emblems imaginable","letter":"D"}]', 'C', '{"A":"The casual idiom clashes with the measured, professional register of a conservators'' report.","B":"This phrasing is even more conversational, compounding the register clash.","C":"Correct: measured and precise, it matches the restrained professional voice of the sentence.","D":"The stacked superlatives tip into breathless exaggeration, overshooting formality into parody."}', 'Tone questions ask for a **match**: the measured phrase suits the report''s restrained professional voice.', 'The ornate option tempts students who equate formality with big words, but inflated diction breaks tone as surely as slang.', '1) Read the surrounding sentence and name its register in one word (clinical, casual, lyrical). 2) Label each option''s register the same way. 3) Eliminate mismatches in both directions — too loose and too grand. 4) Pick the option that could pass unnoticed in the original voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-446ca0792129f3a7', 'act-english', 's-rhet', 3, 'The forager''s stand draws one of the market''s most curious crowds. Each week she sets out whatever the woods have offered: golden chanterelles, shaggy manes, and blue-gray oyster mushrooms. A laminated card beside each basket explains where the species grows and how to cook it.', 'The writer is considering adding the following sentence at the end of the paragraph: "She also fields questions about telling edible mushrooms apart from their toxic look-alikes." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why shoppers find the mushrooms difficult to identify.","letter":"A"},{"is_no_change":false,"label":"Yes, because it extends the paragraph''s description of how the stand informs shoppers.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats the description of the laminated cards.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts attention away from the mushrooms the stand sells.","letter":"D"}]', 'B', '{"A":"Right verdict, wrong reason — the sentence shows the forager helping with identification, not explaining why it is hard (reason_misdescribes).","B":"Correct — the cards already educate visitors, and answering safety questions continues that educational thread.","C":"Answering live questions about toxic look-alikes is new information, not a repeat of the cards'' habitat and cooking notes (false_redundancy).","D":"The sentence stays squarely on the stand and its mushrooms, so no shift occurs (false_offtopic)."}', 'The paragraph already shows the stand teaching visitors through the cards, and the new sentence **continues** that educational thread.', 'The laminated cards and the safety questions both involve mushroom information, so the new sentence can look like a repeat of what the cards do.', '1) State the paragraph''s focus in one line. 2) Ask whether the proposed sentence develops that focus, repeats it, or derails it. 3) Decide add or don''t add. 4) Then vet the stated reason: it must match what the sentence actually does. 5) Reject right-verdict options whose reasons misdescribe the sentence.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-46061398175bf91d', 'act-english', 's-rhet', 3, 'When my uncle began birding in the 1970s, he carried a dog-eared field guide and a pocket notebook. Today, an app on my phone identifies a song in seconds and uploads each sighting to a global database. Researchers mine millions of these records to map migration in real time. What was once a solitary pastime has become a worldwide collaboration.', 'Suppose the writer''s goal had been to show how new technology has transformed a long-standing pastime. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because the essay contrasts earlier birding tools with the digital methods that reshaped the hobby.","letter":"A"},{"is_no_change":false,"label":"Yes, because the essay demonstrates that smartphone apps identify birds more accurately than human experts can.","letter":"B"},{"is_no_change":false,"label":"No, because the essay focuses on one family''s memories rather than on any form of technology.","letter":"C"},{"is_no_change":false,"label":"No, because the essay argues that printed field guides remain superior to newer alternatives.","letter":"D"}]', 'A', '{"A":"Correct: the essay moves from 1970s gear to app-and-database practice, directly showing the transformation.","B":"Right verdict, unsupported reason — the essay never compares app accuracy with expert accuracy.","C":"The family anecdote frames the essay, but technology''s effect on the pastime is its through line.","D":"The essay celebrates the change; it never defends the old guides as superior."}', 'The essay''s **then-versus-now structure** — notebook era to database era — is exactly the transformation the goal describes.', 'The accuracy claim sounds plausible because the app is praised, so students accept a ''yes'' whose reason the essay never actually supports.', '1) Restate the proposed goal. 2) Ask whether the essay as a whole pursues it. 3) Then verify each option''s reason against specific sentences. 4) Reject any option whose verdict is right but whose reason misstates the passage.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-493de89a864e3994', 'act-english', 's-rhet', 3, 'In the school''s stagecraft course, students frame platforms, wire practical lamps, and draft budgets for each set they build. Over a semester, every student rotates through carpentry, electrics, and cost planning. By spring, most can take a set from sketch to strike without an adult stepping in.', 'Suppose the writer''s goal had been to show how a school course builds practical, real-world abilities. Would this passage accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it praises students for winning festival awards.","letter":"A"},{"is_no_change":false,"label":"Yes, because it details the hands-on training students receive in stagecraft class.","letter":"B"},{"is_no_change":false,"label":"No, because it focuses on professional theaters rather than a school course.","letter":"C"},{"is_no_change":false,"label":"No, because it mainly reviews a single evening''s performance.","letter":"D"}]', 'B', '{"A":"The passage never mentions awards or festivals, so this reason is untrue even though its verdict is right (reason_invented_evidence).","B":"Correct: the passage catalogs carpentry, electrics, and budgeting work that students master over a semester — exactly the practical growth the goal names.","C":"The passage explicitly describes a school course and its students, not professional venues (reason_contradicts_text).","D":"No performance is reviewed; the passage traces a semester-long process, not one evening (reason_wrong_scope)."}', 'The passage **fulfills** the goal by documenting concrete, escalating tasks students learn to do independently over a semester.', 'The single-performance rejection tempts students because theater passages often review shows, so they assume this one does without checking its actual scope.', '1) Restate the proposed goal in your own words. 2) List what the passage actually contains. 3) Decide yes or no by comparing the two lists. 4) Then vet the reason: is its claim about the passage factually true? 5) Accept only the verdict-reason pair where both parts check out.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4e10c6a53f80b435', 'act-english', 's-rhet', 3, 'During the closing chorus of ''Sing, Sing, Sing'' at Carnegie Hall in 1938, Gene Krupa <u>pounded</u> his tom-toms until the floorboards under the front rows trembled.', 'The writer wants to emphasize the sheer physical force of Krupa''s playing. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"played","letter":"B"},{"is_no_change":false,"label":"patted","letter":"C"},{"is_no_change":false,"label":"handled","letter":"D"}]', 'A', '{"A":"Correct: the original verb delivers the force the writer wants, matching the trembling floorboards.","B":"goal_neutral_verb: *played* is accurate but colorless — it conveys no force at all.","C":"*Patted* implies gentleness, the opposite of the stated goal.","D":"*Handled* suggests careful management, not power."}', 'Only the original verb''s connotation matches the stated goal of **physical force**.', '*Played* feels safe because it is always technically true — but the stem asks for emphasis, not mere accuracy.', '1) Restate the writer''s goal in one word (here: force). 2) Rate each verb''s connotation against that word. 3) Eliminate neutral verbs even if they are accurate. 4) Confirm the survivor fits the surrounding imagery.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-51dabb91f4950f88', 'act-english', 's-rhet', 3, 'In her formal field report, the geologist characterized the canyon''s layered walls as <u>a meticulous record</u> of nearly ten million years of seasonal flooding.', 'Which choice best maintains the tone established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a totally awesome scrapbook","letter":"B"},{"is_no_change":false,"label":"a neat old photo album","letter":"C"},{"is_no_change":false,"label":"a pretty cool wall calendar","letter":"D"}]', 'A', '{"A":"Correct: the precise, formal phrasing matches the scientific register of a field report.","B":"''Totally awesome scrapbook'' drops into slang that clashes with the report''s formal tone (register_too_casual).","C":"''Neat old photo album'' uses casual, conversational diction out of keeping with the passage (register_too_casual).","D":"''Pretty cool wall calendar'' mixes slang and a trivial image, breaking the formal register (register_too_casual)."}', 'A formal field report calls for **precise, elevated diction**, which the original phrasing supplies.', 'The casual comparisons feel friendly and concrete, so students pick them for vividness without checking the passage''s formal tone.', '1) Identify the passage''s register from its context (a formal field report). 2) Read each option and label its tone: formal or casual. 3) Reject any option whose diction is slangy or conversational. 4) Keep the phrasing that matches the established register. 5) Re-read the full sentence to confirm the tone stays consistent.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-538802099d1f84a6', 'act-english', 's-rhet', 3, 'No two batches of naturally dyed yarn match exactly. Water minerals, harvest timing, and even the age of the dye pot all nudge the final shade. Hand-dyers plan for this drift, alternating skeins every few rows so slight differences blend across a finished shawl.', 'The writer wants to add a sentence that most directly supports the paragraph''s point that naturally dyed colors resist standardization. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Indigo leaves harvested in a rainy week can yield a noticeably grayer blue than leaves picked from the same plants days later.","letter":"A"},{"is_no_change":false,"label":"Indigo has been cultivated on several continents for thousands of years.","letter":"B"},{"is_no_change":false,"label":"Some hand-dyers sell their yarn at regional fiber festivals each autumn.","letter":"C"},{"is_no_change":false,"label":"Synthetic indigo, patented in the 1890s, replaced natural indigo in most denim factories.","letter":"D"}]', 'A', '{"A":"Correct: it shows the same crop producing different shades under different conditions, directly illustrating unpredictability.","B":"The dye''s long global history says nothing about whether its colors vary.","C":"Where dyers sell yarn is a marketing detail, not evidence about color consistency.","D":"The industrial shift to synthetics concerns commerce, not the variability of natural shades."}', 'The best support is a **specific instance** of the claim: identical sources, shifting conditions, visibly different color.', 'The synthetic-indigo fact tempts because it implies factories wanted consistency, but the paragraph''s claim needs direct evidence of natural variation, not an inference about industry.', '1) Restate the claim to be supported. 2) For each candidate, ask: does this show that claim happening? 3) Reject facts that are merely about the same topic. 4) Choose the sentence a skeptic of the claim would find hardest to dismiss.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-546df543c4e6f9ca', 'act-english', 's-rhet', 3, 'During the last week before the robot had to be sealed in its bag, students <u>swarmed</u> the workshop from the final bell until the custodians shut off the lights.', 'The writer wants to emphasize how crowded and frantic the workshop became during the final week. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"went to","letter":"B"},{"is_no_change":false,"label":"attended","letter":"C"},{"is_no_change":false,"label":"stopped by","letter":"D"}]', 'A', '{"A":"Correct: the verb vividly conveys dense, urgent crowding, matching the writer''s stated emphasis.","B":"States neutral motion with no sense of crowding or urgency (goal_neutral_verb).","C":"Suggests polite, orderly presence, nearly the opposite of frantic (goal_wrong_connotation).","D":"Implies brief, casual visits, contradicting the dawn-to-dusk intensity (goal_minimizing_verb)."}', 'The original verb vividly conveys **dense, urgent crowding**, exactly the emphasis the writer requests.', 'The neutral options are accurate statements of fact, so literal-minded readers accept them.', '1) Restate the writer''s stated goal in your own words. 2) For each verb, describe the picture it creates. 3) Eliminate neutral or mismatched pictures. 4) Keep the verb whose connotation matches the goal exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5e0889d5d81741e6', 'act-english', 's-rhet', 3, 'Every October, my grandmother and I walk the length of the harbor bridge at dawn. She points out gulls balancing on the railing and tells me stories about crossing it as a schoolgirl. By the time we reach the far tower, the sun has turned the water gold, and neither of us is in any hurry to turn back.', 'Suppose the writer''s goal had been to explain the technical challenges of anchoring a long bridge in deep water. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it mentions the bridge''s far tower, which stands in the harbor''s deepest water.","letter":"A"},{"is_no_change":false,"label":"Yes, because the walk shows that the bridge is safe enough for pedestrians.","letter":"B"},{"is_no_change":false,"label":"No, because it describes only one bridge rather than comparing several.","letter":"C"},{"is_no_change":false,"label":"No, because it is a personal reflection that never discusses how the bridge was engineered.","letter":"D"}]', 'D', '{"A":"A passing scenic mention of a tower explains nothing about construction in deep water (misconception: purpose_single_mention_suffices).","B":"Pedestrian safety is a different subject from construction challenges, and the essay proves neither (misconception: purpose_wrong_inference).","C":"Right verdict, wrong reason: an essay about a single bridge could still explain deep-water anchoring fully (misconception: reject_wrong_reason_scope).","D":"Correctly identifies the mismatch: the essay is a memory piece with no technical content at all."}', 'Judging purpose means comparing the essay''s **actual content** — memories and imagery — against the stated goal of technical explanation, which it never attempts.', 'The single-bridge option tempts students who correctly sense failure but accept a plausible-sounding reason without testing whether it is the true cause.', '1) Restate the supposed goal in your own words. 2) Summarize what the essay actually does in one sentence. 3) Compare the two: match or mismatch? 4) Among options with the right verdict, keep only the one whose reason describes the essay accurately. 5) Double-check that reason against specific lines.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-605d23980de3a83e', 'act-english', 's-rhet', 3, 'Just before dawn, a bobcat <u>went</u> across the empty golf course and slipped beneath the perimeter fence.', 'The writer wants to emphasize how silently the bobcat moved through the sleeping neighborhood. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"drifted","letter":"B"},{"is_no_change":false,"label":"crashed","letter":"C"},{"is_no_change":false,"label":"hurried","letter":"D"}]', 'B', '{"A":"''Went'' is acoustically neutral — it reports motion but conveys nothing about silence (goal_neutral_verb).","B":"Correct: the verb evokes soundless, almost weightless movement, directly serving the stated goal.","C":"''Crashed'' maximizes noise, the exact opposite of the writer''s stated emphasis (goal_opposite_effect).","D":"''Hurried'' emphasizes speed rather than quietness, answering a goal the writer did not state (goal_wrong_emphasis)."}', 'The stated goal is **silence**, and only this verb''s core image is noiseless motion.', '''Hurried'' feels vivid and stealthy because sneaking animals move fast, so students substitute speed for the silence the stem actually demands.', '1) Underline the goal word in the stem (here: silently). 2) For each option, name the single quality its verb most strongly conveys. 3) Eliminate any verb whose quality is neutral, opposite, or merely adjacent to the goal. 4) Choose the verb whose core meaning matches the goal itself. 5) Re-read the sentence to confirm the effect lands.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-61ecab38e15ca3d3', 'act-english', 's-rhet', 3, 'Called up from rookie ball only two days earlier, Marcus <u>walked</u> toward the mound for his first professional start.', 'The writer wants to suggest that Marcus is nervous as he approaches the mound. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"inched","letter":"B"},{"is_no_change":false,"label":"strode","letter":"C"},{"is_no_change":false,"label":"bounded","letter":"D"}]', 'B', '{"A":"''Walked'' is emotionally neutral and conveys nothing about nerves (goal_neutral_word).","B":"Correct: halting, reluctant movement is exactly the connotation the stated goal requires.","C":"''Strode'' connotes confidence and command — the opposite of the goal (goal_opposite_emphasis).","D":"''Bounded'' radiates eager energy, not anxiety (goal_wrong_emotion)."}', 'The goal is nervousness, and only a verb connoting **hesitant, reluctant** movement delivers that feeling.', '''Strode'' sounds vivid and athletic, so students pick the most impressive verb instead of the one matching the stated emotion.', '1) Restate the writer''s goal in one word (here: nervousness). 2) For each verb, name the emotion it radiates. 3) Eliminate neutral verbs — no emotion means no goal met. 4) Eliminate verbs radiating a different or opposite emotion. 5) Choose the verb whose connotation matches the goal word.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6320e41e5627b12e', 'act-english', 's-rhet', 3, 'The nature documentary''s narrator called the eagle''s dive <u>fast</u>, a plunge that ends in a blur the eye can barely track.', 'The writer wants to emphasize how astonishing the dive''s speed is. Which choice works best?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"quick","letter":"B"},{"is_no_change":false,"label":"breathtaking","letter":"C"},{"is_no_change":false,"label":"rapid","letter":"D"}]', 'C', '{"A":"''Fast'' is plain and does nothing to convey astonishment.","B":"''Quick'' is if anything weaker than ''fast''.","C":"''Breathtaking'' pairs speed with wonder, matching ''a blur the eye can barely track''.","D":"''Rapid'' is a formal synonym for fast but still emotionally flat."}', 'The goal is **astonishment**, and ''breathtaking'' fuses the speed with awe.', '''Rapid'' sounds more sophisticated than ''fast'', so it feels like the intended upgrade.', 'When the aim is to impress or awe, choose the word that adds feeling, not just a fancier synonym.', 'underlined-span-mc', '''Rapid'' sounds more sophisticated than ''fast'', so it feels like the i…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-65f170e3fd80257f', 'act-english', 's-rhet', 3, 'This spring, the Millbrook Courier began scanning a century of back issues, some so brittle they crumble at a touch. The project''s biggest obstacle is not equipment but labor: each page must be flattened, photographed, and labeled by hand. The editor hopes the archive will be searchable online within two years.', 'The writer is considering adding the following sentence after the second sentence: "Last month, twelve volunteers from the historical society began labeling pages every weekend." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains what the project''s equipment costs.","letter":"A"},{"is_no_change":false,"label":"Yes, because it shows how the project''s main obstacle is being addressed.","letter":"B"},{"is_no_change":false,"label":"No, because it shifts the main focus away from the editor.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats the paragraph''s earlier description of the obstacle.","letter":"D"}]', 'B', '{"A":"Right verdict, wrong warrant — the new sentence says nothing about equipment or costs.","B":"Correct: the paragraph names labor as the bottleneck, and the volunteer crew answers exactly that problem.","C":"The paragraph''s focus is the scanning project, not the editor, so no shift occurs.","D":"The sentence adds new information — who is now doing the labeling — rather than repeating anything."}', 'The paragraph names hand labor as the project''s bottleneck, and the added sentence supplies **direct progress** on that exact problem.', 'The equipment-costs option tempts students because its ''yes'' verdict feels right and they skim past the stated justification.', '1) Decide the verdict: does the new sentence serve the paragraph''s focus? 2) Then audit the justification: does it describe what the sentence actually does? 3) Reject any option whose justification misstates the sentence''s content, even if its verdict matches yours. 4) Confirm the surviving justification names the real connection.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-677ff69d6de2856f', 'act-english', 's-rhet', 3, 'Harbor Lantern Records, a two-room label founded in 1959, built its roster without ever placing an advertisement or holding a formal audition.', 'The writer wants to add a sentence that supports the paragraph''s focus on how the label found its new artists. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The label''s founder spent years collecting antique radios and old song sheets for the office.","letter":"A"},{"is_no_change":false,"label":"The era''s largest pressing plants often ran double shifts before the holidays.","letter":"B"},{"is_no_change":false,"label":"The label''s office sat above a bakery whose ovens warmed the building on winter nights.","letter":"C"},{"is_no_change":false,"label":"Its founder spent weekend nights at neighborhood song contests, noting which performers drew crowds.","letter":"D"}]', 'D', '{"A":"The founder''s collecting hobby decorates the office but says nothing about recruiting artists.","B":"Industry-wide manufacturing schedules have no connection to this label''s talent search.","C":"The bakery is scene-setting charm, irrelevant to how the roster was built.","D":"Correct: it describes the actual scouting method, directly supporting the stated focus."}', 'It is the only option that explains the **recruiting method** — exactly the focus the stem names.', 'The founder''s collecting habit tempts students because it involves the same person and a musical flavor, though it never touches recruiting.', '1) Copy the stated focus into a question (''How did the label find artists?''). 2) Test each option: does it answer that question? 3) Discard options that merely share a character, setting, or era with the paragraph. 4) Choose the one sentence that answers the focus question directly.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-684c0ed65fba577b', 'act-english', 's-rhet', 3, 'The essay recounts the narrator''s first season at a high-altitude drill camp: learning to sleep through wind, budgeting fuel for the stove, and celebrating a birthday with canned peaches. Ice cores appear mainly as heavy boxes the narrator hauls to the weighing tent.', 'Suppose the writer''s goal had been to explain to general readers what ice cores reveal about past climates. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it explains what the cores reveal about ancient climates.","letter":"A"},{"is_no_change":false,"label":"Yes, because the narrator''s descriptions of the field season show scientific work.","letter":"B"},{"is_no_change":false,"label":"No, because it dwells on the narrator''s experience rather than on what the cores reveal.","letter":"C"},{"is_no_change":false,"label":"No, because the essay is too short to accomplish any scientific goal.","letter":"D"}]', 'C', '{"A":"The reason misstates the essay, which treats cores as luggage, not as climate evidence (false-premise yes).","B":"Scenes of camp life show the setting of science without explaining any findings (setting mistaken for substance).","C":"The essay is a personal narrative and never explains what cores tell us about climate, so it fails the stated goal.","D":"Length is not the test; a short essay could still explain core science, and this one simply does not try (wrong criterion)."}', 'Judge purpose questions by **what the essay actually does**, and this one narrates camp life without explaining core science.', 'Because the narrator is clearly doing science, students credit the essay with explaining science it only gestures at.', '1) Restate the proposed goal precisely. 2) List what the essay actually spends its sentences on. 3) Compare: does the content deliver the goal, not merely touch its topic? 4) Pick the yes/no that matches, then verify the reason is true of the essay. 5) Discard options with false or irrelevant reasons.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-772a95a16672dc57', 'act-english', 's-rhet', 3, 'All July, a single male rufous hummingbird ruled our back garden. He perched on the same bare twig between patrols, swooping at any rival that dared approach the bee balm. Watching his dives became the highlight of my mornings.', 'The writer is considering adding the following sentence after the second sentence: ''Hummingbird feeders should be rinsed with a vinegar solution every few days in hot weather.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why the hummingbird returned to the garden each day.","letter":"A"},{"is_no_change":false,"label":"Yes, because it gives readers practical advice they can apply at home.","letter":"B"},{"is_no_change":false,"label":"No, because it interrupts a descriptive account with unrelated how-to instructions.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats details stated earlier in the paragraph.","letter":"D"}]', 'C', '{"A":"The maintenance tip says nothing about the bird''s motivation — the bee balm explains the visits.","B":"Usefulness elsewhere cannot justify a sentence that abandons this paragraph''s descriptive purpose.","C":"Correct: the paragraph paints one bird''s behavior, and a care tip derails that portrait.","D":"Feeder cleaning appears nowhere else in the paragraph, so the sentence cannot be repetitive."}', 'The paragraph is a **portrait of one bird''s behavior**, and a maintenance tip breaks that focus entirely.', 'The advice is genuinely useful, so students reason that helpful information must be worth adding regardless of the paragraph''s purpose.', '1) State the paragraph''s purpose in one phrase. 2) Ask whether the proposed sentence serves that purpose. 3) Check each option''s reason for factual accuracy against the passage. 4) Choose the verdict whose reason is both true and decisive.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7b2b77e71f4c8e3f', 'act-english', 's-rhet', 3, 'When Priya Anand took over her parents'' bakery, she kept the notebook of recipes her mother had written out by hand. She still measures cardamom with the brass spoon her grandfather carried from Surat, and she teaches her daughter the same lamination folds she learned at twelve. Even the shop''s opening ritual—lighting a small lamp by the register—has passed unchanged through three generations.', 'Suppose the writer''s goal had been to show how a family business keeps its traditions alive across generations. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it details specific practices that have been handed down and are still in use.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains how the bakery has stayed profitable in a changing market.","letter":"B"},{"is_no_change":false,"label":"No, because it concentrates on a single recipe rather than on the family''s habits.","letter":"C"},{"is_no_change":false,"label":"No, because it is mainly about the technique of laminating dough.","letter":"D"}]', 'A', '{"A":"Correct — the recipes, spoon, folds, and lamp ritual are inherited practices shown continuing across three generations.","B":"Reaches the right verdict for a reason the essay never supports; profit and markets are never discussed (purpose_yes_wrong_reason).","C":"Misreads the scope — the essay surveys several inherited habits, not one recipe (purpose_false_narrow).","D":"Mistakes one detail for the main subject; lamination is a single example among many (purpose_detail_as_main)."}', 'Every sentence supplies an inherited, still-living practice — exactly what the stated goal requires — and the **reason** cites that evidence.', 'The profitability answer matches the correct verdict, so students grab it without checking whether its reason appears anywhere in the essay.', '1) Restate the hypothetical goal. 2) List what the essay actually does, sentence by sentence. 3) Judge the verdict (yes/no) against that list. 4) Then verify the reason — it must describe the essay accurately. 5) Reject any option whose verdict or reason fails.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7e2ab8cb05566f13', 'act-english', 's-rhet', 3, 'Transporting the fresco fragments demanded weeks of planning: the nine-hundred-year-old plaster was <u>seriously iffy</u> and could crumble at the slightest jolt.', 'Which choice best maintains the formal tone established elsewhere in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a total wreck","letter":"B"},{"is_no_change":false,"label":"dangerously fragile","letter":"C"},{"is_no_change":false,"label":"kind of unstable","letter":"D"}]', 'C', '{"A":"''Seriously iffy'' is slangy hedging that clashes with the passage''s formal register.","B":"''A total wreck'' is casual exaggeration, trading precision for conversational drama.","C":"Correct: this phrase is precise and formal, matching the measured register of the surrounding prose.","D":"''Kind of unstable'' softens the claim with a colloquial hedge that undercuts the formal tone."}', 'Tone questions demand a phrase whose **register matches the passage** — here, formal and precise rather than slangy or hedged.', 'Casual phrases feel vivid and familiar, so students mistake conversational energy for good style.', '1) Sample the passage''s register from its other sentences: formal, neutral, or casual? 2) Read each option aloud and label its register the same way. 3) Strike options that hedge (''kind of''), exaggerate, or use slang if the passage is formal. 4) Pick the option whose label matches the passage, then confirm it keeps the sentence''s meaning intact.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-825d7eb858c5e8c4', 'act-english', 's-rhet', 3, 'Written in protest of lynching, ''Strange Fruit'' closed Billie Holiday''s sets at Caf&eacute; Society in 1939: waiters stopped serving, the room went dark except for a single spotlight, and no encore followed. The song unsettled listeners accustomed to romantic ballads, and some radio stations declined to program it.', 'The writer is considering adding the following true sentence after the last sentence of the paragraph: ''Columbia, Holiday''s own label, refused to record the song, so she released it through the small Commodore imprint.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it extends the paragraph''s account of the resistance the song met.","letter":"A"},{"is_no_change":false,"label":"Yes, because it identifies the record labels Holiday worked with during her career.","letter":"B"},{"is_no_change":false,"label":"No, because it shifts the focus away from the staging of her nightclub performances.","letter":"C"},{"is_no_change":false,"label":"No, because the paragraph already explains why radio stations declined the song.","letter":"D"}]', 'A', '{"A":"Correct: the label''s refusal is one more instance of the institutional resistance the paragraph documents.","B":"right_action_wrong_reason: naming labels is trivia; the sentence earns its place by extending the resistance theme, not by listing companies.","C":"The paragraph''s focus is the song''s reception broadly, not only the staging, so the sentence does not derail it.","D":"The paragraph never explains the stations'' reasoning, so nothing would be repeated."}', 'The new sentence continues the paragraph''s pattern: institutions **resisting** the song.', 'The staging objection tempts readers who anchor on the vivid spotlight details and mistake them for the paragraph''s whole focus.', '1) State the paragraph''s controlling idea. 2) Ask: does the new sentence add a fresh instance of that idea? 3) If yes, add it — then check that the stated reason actually names that connection. 4) Reject reasons that are true but beside the point.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-877a39fb3e4eb82b', 'act-english', 's-rhet', 3, 'During the planetarium''s deep-sky show, the presenter reminds the audience that the light now reaching their eyes left the Andromeda galaxy <u>before the first humans walked the Earth</u>.', 'The writer wants to emphasize how staggeringly long the galaxy''s light has been traveling. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a very long time ago","letter":"B"},{"is_no_change":false,"label":"at some point in the distant past","letter":"C"},{"is_no_change":false,"label":"quite a while before tonight''s show","letter":"D"}]', 'A', '{"A":"Correct: anchoring the light''s departure to a benchmark before human existence dramatizes the vast time span.","B":"Generic intensity: ''very long'' asserts scale without giving the reader anything to picture.","C":"Vague: ''the distant past'' could mean decades or millennia, so the staggering scale disappears.","D":"Casual and minimizing: ''quite a while'' shrinks the timescale and breaks the show''s register."}', 'A **concrete benchmark**—light older than humanity itself—makes the span vivid, which is exactly the stated goal.', '''A very long time ago'' tempts students because it sounds emphatic, but stacking intensifiers asserts scale without dramatizing it.', '1) Restate the writer''s goal in your own words. 2) For each version, ask: does it give a specific, picturable anchor for the idea? 3) Strike versions that rely on bare intensifiers (''very'') or vague spans (''distant past''). 4) Strike versions whose register clashes with the passage. 5) Keep the one that makes the goal concrete.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-882e189eb5d38d67', 'act-english', 's-rhet', 3, 'Dr. Okafor became <u>notorious</u> for her groundbreaking vaccine research.', 'Which word carries the connotation the sentence needs?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"infamous","letter":"B"},{"is_no_change":false,"label":"renowned","letter":"C"},{"is_no_change":false,"label":"suspected","letter":"D"}]', 'C', '{"A":"''Notorious'' means famous for something BAD — it slanders the research it means to praise.","B":"''Infamous'' has the same negative charge as ''notorious''.","C":"''Renowned'' is fame with a positive glow — right for groundbreaking research.","D":"''Suspected'' implies wrongdoing that the sentence never mentions."}', 'Denotation is ''famous''; the needed **connotation** is positive → *renowned*.', '''Notorious'' sounds impressive and vaguely means ''well-known''.', 'Check a word''s emotional charge, not just its dictionary meaning, against the sentence''s intent.', 'underlined-span-mc', '''Notorious'' sounds impressive and vaguely means ''well-known''', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-891b167eea2e757f', 'act-english', 's-rhet', 3, 'Plastic waste is now found in every ocean on Earth. Because most plastics do not biodegrade, the debris lingers for decades, harming wildlife that mistakes the fragments for food.', 'At this point the writer is considering adding the sentence "A single plastic bag can take up to twenty years to break down in seawater." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains how sea turtles reproduce.","letter":"A"},{"is_no_change":false,"label":"Yes, because it gives a concrete example of how long ocean debris lasts.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information already stated earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it contradicts the passage''s main argument.","letter":"D"}]', 'B', '{"A":"The added sentence says nothing about turtle reproduction, so this reason misdescribes it (add_wrong_reason).","B":"Correct: a specific timeframe illustrates the paragraph''s point about how long the debris lasts.","C":"The exact timeframe is new, not a repeat of any earlier sentence (add_false_redundant).","D":"The detail agrees with the paragraph''s message rather than opposing it (add_false_contradiction)."}', 'A good addition is justified by how it **supports** the paragraph''s actual point — here, the debris''s persistence.', 'Students who sense the sentence ''fits'' may grab a Yes answer without checking that the stated reason matches its content.', '1) Read the proposed sentence and state what it actually contributes. 2) Read each justification and test it against that content. 3) Reject reasons that misname the content, claim false repetition, or invent a contradiction. 4) Keep the reason that matches both the sentence and the paragraph''s focus.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8b41ed68ca64cc04', 'act-english', 's-rhet', 3, 'The peer-reviewed study reported that the treatment group <u>did way better than</u> the control group across every measure.', 'Which choice best suits the objective tone of a scientific study?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"outperformed","letter":"B"},{"is_no_change":false,"label":"totally crushed","letter":"C"},{"is_no_change":false,"label":"beat out","letter":"D"}]', 'B', '{"A":"''Did way better than'' is casual and imprecise for a research report.","B":"''Outperformed'' is precise, neutral, and appropriately formal.","C":"''Totally crushed'' is slangy and injects unwanted emotion.","D":"''Beat out'' is conversational and less exact than ''outperformed''."}', 'A scientific study favors **objective, precise diction**, and ''outperformed'' states the result cleanly.', '''Beat out'' is shorter and idiomatic, so it can pass as neutral until you weigh the register.', 'In objective/academic writing, pick the exact, unemotional verb.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8ec4bb6984514267', 'act-english', 's-rhet', 3, 'The paragraph explains why bread staling is not simply drying out. As a loaf cools, its starch molecules slowly recrystallize, hardening the crumb even inside a sealed bag. ________ A quick warm-up in the oven can reverse the process by melting those crystals back into softness.', 'Which sentence, if inserted at the blank, best supports the paragraph''s focus on the chemistry of staling?', '[{"is_no_change":false,"label":"Many bakeries sell day-old loaves at a discount to avoid throwing them away.","letter":"A"},{"is_no_change":false,"label":"This recrystallization, called retrogradation, continues even in humid conditions where drying cannot be the cause.","letter":"B"},{"is_no_change":false,"label":"Sourdough has become a popular hobby among people who bake at home on weekends.","letter":"C"},{"is_no_change":false,"label":"Some cooks prefer to slice bread thin so that each piece toasts more evenly.","letter":"D"}]', 'B', '{"A":"Off-focus: bakery pricing is a business detail, not part of the staling chemistry.","B":"Correct: it names and reinforces the recrystallization mechanism, tying directly to the paragraph''s chemical focus.","C":"Off-focus: the popularity of a hobby has nothing to do with the molecular process.","D":"Off-focus: slicing and toasting is a serving preference, unrelated to why bread stales."}', 'The paragraph is about the **chemistry of staling**, and only this sentence extends that mechanism by naming the recrystallization process.', 'The other options are all true statements about bread, so they feel relevant even though they drop the chemical thread.', '1) Name the paragraph''s specific focus in a phrase. 2) For each option, ask whether it advances that exact focus. 3) Reject any sentence that is merely about the same broad topic. 4) Keep the sentence that deepens the stated focus. 5) Reread with the insertion to confirm the thread stays unbroken.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8ef6b9f998359112', 'act-english', 's-rhet', 3, 'The club has redesigned its star parties so that visitors with limited mobility can take part fully. Paved paths now lead to every observing pad, and each event includes at least one seated observing station.', 'The writer wants to add one more detail supporting the paragraph''s focus on serving visitors with limited mobility. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The club recruits new volunteers at every public star party.","letter":"A"},{"is_no_change":false,"label":"Many guests say the view of Saturn through the large telescopes is unforgettable.","letter":"B"},{"is_no_change":false,"label":"One longtime volunteer drives an hour to reach the darkest sky in the county.","letter":"C"},{"is_no_change":false,"label":"Volunteers attach video eyepieces to the telescopes so that guests in wheelchairs can watch the sky on a large screen.","letter":"D"}]', 'D', '{"A":"Off-focus: recruiting volunteers is club business, not an accessibility measure for guests.","B":"Appealing but irrelevant: praise for the views says nothing about how guests with limited mobility take part.","C":"Off-focus: one member''s commute describes dedication, not an adaptation for visitors.","D":"Correct: it names a concrete adaptation that lets seated guests observe, directly serving the stated focus."}', 'The only detail that survives the **focus test** is the one describing an actual accommodation guests with limited mobility can use.', 'The Saturn detail tempts students because it is vivid and positive, but emotional appeal is not the same as relevance to the stated focus.', '1) Copy the paragraph''s stated focus from the stem into your own words. 2) For each candidate detail, ask: does it show the club serving that specific group? 3) Discard details about club operations, general praise, or individual members. 4) Keep the one that adds a new, concrete support for the focus.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8f7f2bbc3fc8fffc', 'act-english', 's-rhet', 3, 'Writing for an audience of first-time gardeners, the author explained that <u>photosynthetic efficiency governs</u> how fast a seedling grows.', 'Which choice best suits the beginner audience the passage addresses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the plant''s ability to turn sunlight into food controls","letter":"B"},{"is_no_change":false,"label":"chlorophyll-mediated carbon fixation determines","letter":"C"},{"is_no_change":false,"label":"the rate of photosynthate accumulation dictates","letter":"D"}]', 'B', '{"A":"''Photosynthetic efficiency governs'' is jargon that first-time gardeners won''t follow.","B":"Plain phrasing — ''turn sunlight into food'' — explains the idea in terms a beginner grasps.","C":"''Chlorophyll-mediated carbon fixation'' is even more technical than the original.","D":"''Photosynthate accumulation'' is specialist vocabulary, wrong for novices."}', 'The stem names a **beginner audience**, so the plainest accurate wording wins.', 'The technical options sound authoritative, which can seem ''more correct'' on a test.', 'Fit the diction to the stated audience — for novices, prefer clarity over technical precision.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-92dd1a24a08daec6', 'act-english', 's-rhet', 3, 'In the two weeks before the winter holidays, the Vachon family runs its bakery like a relay team. Orders are logged on a whiteboard the moment they arrive, and each night the next day''s bake list is sorted by oven temperature. Pickup times are staggered in fifteen-minute blocks so the small front room never overflows.', 'The writer is considering adding the following sentence to the paragraph: "The bakery''s building was once a hardware store owned by an unrelated family." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains how the family adapted the building for holiday baking.","letter":"A"},{"is_no_change":false,"label":"Yes, because it provides historical background about the bakery''s location.","letter":"B"},{"is_no_change":false,"label":"No, because the paragraph has already described the building''s past.","letter":"C"},{"is_no_change":false,"label":"No, because it strays from the paragraph''s focus on how the family manages the holiday rush.","letter":"D"}]', 'D', '{"A":"Says yes with a justification the sentence cannot support — it never mentions adaptation or baking (add_yes_false_reason).","B":"Correctly labels the sentence as background but wrongly assumes background automatically belongs (add_yes_background_fallacy).","C":"Rejects the sentence for a false reason — the paragraph says nothing about the building''s past (add_no_false_reason).","D":"Correct — the sentence is off-topic trivia that would interrupt the paragraph''s account of the family''s holiday system."}', 'The paragraph is tightly about the family''s **holiday workflow**, and a stray fact about the building''s previous owner serves none of it.', '''Historical background'' sounds enriching, so students accept the addition without checking whether it serves this particular paragraph.', '1) State the paragraph''s main idea in one phrase. 2) Ask whether the proposed sentence advances that idea. 3) Then check the reason: even a correct yes/no fails if its justification misdescribes the sentence or the paragraph. 4) Pick the option whose verdict AND reason are both true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-949378b918123353', 'act-english', 's-rhet', 3, 'In the lab report''s discussion section, the experiment''s results were <u>super weird</u>, prompting a full review of the method.', 'Which choice best matches the passage''s formal tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"unexpected","letter":"B"},{"is_no_change":false,"label":"totally bizarre","letter":"C"},{"is_no_change":false,"label":"kind of strange","letter":"D"}]', 'B', '{"A":"''Super weird'' is casual slang — jarring inside a formal lab report.","B":"''Unexpected'' states the same fact in the register a lab report uses.","C":"''Totally bizarre'' swaps one informality for another.","D":"''Kind of strange'' keeps the conversational hedge the context forbids."}', 'Word choice must match the **register** of the surrounding passage — formal here.', 'The informal options are vivid and natural in speech.', 'Check the passage''s tone before judging a word: formal context → formal diction.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-96e5eb02fe15b049', 'act-english', 's-rhet', 3, 'In its year-end assessment, the district office praised the masonry team''s granite staircase on Cascade Pass, reporting that the crew <u>totally crushed it</u> and predicting the steps would serve hikers for a century.', 'Which choice best maintains the formal tone established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"did an awesome job","letter":"B"},{"is_no_change":false,"label":"knocked it out of the park","letter":"C"},{"is_no_change":false,"label":"displayed exemplary craftsmanship","letter":"D"}]', 'D', '{"A":"Slang: ''totally crushed it'' collides with the bureaucratic register of ''year-end assessment'' and ''predicting.''","B":"Conversational: ''awesome'' is casual praise that still clashes with the document''s measured, official language.","C":"A sports idiom whose informal origin breaks the voice of a formal district report.","D":"Correct: this phrasing matches the professional register of an official assessment quoted in the sentence."}', 'The sentence''s frame is **formal report language**, so the quoted praise must hold that same professional register.', 'The ''awesome'' version tempts students who notice the slang problem but settle for wording that is merely less casual instead of actually formal.', '1) Identify the passage''s register from its frame words (here: ''assessment,'' ''reporting,'' ''predicting''). 2) Rate each version''s formality level. 3) Eliminate every version whose register clashes with the frame. 4) Confirm the survivor sounds like the same author as the rest of the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-987b6c5934ae5294', 'act-english', 's-rhet', 3, 'Nothing baked at Ferraro''s goes to waste, and the neighborhood knows it. Each evening, unsold loaves are marked down during the final hour of business, and whatever remains is packed up for donation.', 'The writer wants to add a sentence here that supports the paragraph''s focus on how the bakery''s leftover bread benefits the surrounding neighborhood. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The family also sells branded tote bags near the register.","letter":"A"},{"is_no_change":false,"label":"A volunteer from the food pantry two blocks away collects the boxes at closing each evening.","letter":"B"},{"is_no_change":false,"label":"Day-old loaves can become croutons, panzanella, or bread pudding.","letter":"C"},{"is_no_change":false,"label":"The bakery''s ovens are switched off by seven each evening.","letter":"D"}]', 'B', '{"A":"Tote bags are merchandise, unrelated to leftover bread or neighborhood benefit (detail_offtopic_merch).","B":"Correct — it shows the donated loaves actually reaching a nearby neighborhood organization, completing the paragraph''s point.","C":"Recipe ideas describe uses for old bread in general, not this bakery''s effect on its neighbors (detail_generic_not_local).","D":"An operations fact about oven schedules, with no link to leftover bread helping anyone (detail_irrelevant_ops)."}', 'It extends the donation detail to a concrete **neighborhood** recipient, which is precisely the paragraph''s stated focus.', 'The recipe option stays on the topic of day-old bread, so it feels relevant even though it drops the neighborhood angle entirely.', '1) Write down the paragraph''s focus as ''topic + angle'' (here: leftover bread + helping neighbors). 2) Test each option against BOTH parts. 3) Reject options that hit the topic but miss the angle, or vice versa. 4) Choose the option serving both.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9a230c753eef51da', 'act-english', 's-rhet', 3, 'When she reached the final chorus, her voice <u>went</u> through the crowded hall.', 'The writer wants to convey the overwhelming power of the singer''s voice. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"carried","letter":"B"},{"is_no_change":false,"label":"was audible","letter":"C"},{"is_no_change":false,"label":"thundered","letter":"D"}]', 'D', '{"A":"''Went'' is a colorless verb of motion that conveys no force at all.","B":"''Carried'' says the voice reached the room but gives no sense of its might.","C":"''Was audible'' reduces the voice to the bare minimum — merely hearable.","D":"Correct: it delivers the storm-like force the writer explicitly wants."}', 'It is the only verb whose connotation delivers **overwhelming power**, which is the writer''s stated goal.', '''Carried'' tempts students because it is a genuine improvement in vividness over the original — just not an improvement toward the stated goal.', '1) Restate the writer''s goal in one word (here: force). 2) For each verb, name the image or intensity it evokes. 3) Eliminate any verb that is merely accurate without delivering the goal''s quality. 4) Choose the verb whose connotation scores highest on the stated goal, then re-read the sentence for fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a23f2ca5bbd0089c', 'act-english', 's-rhet', 3, 'The Cedar Hollow Folk Festival began in 1961 with a single flatbed stage and a borrowed sound system. Within five years it filled the county fairgrounds, and by 1970 its weekend attendance rivaled the town''s own population. Local motels booked out months in advance, and the festival committee hired its first full-time staff.', 'The writer is considering adding the following sentence to the paragraph: "The town also hosts a well-attended quilt fair each October." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it shows that the town''s growth extended beyond music.","letter":"A"},{"is_no_change":false,"label":"Yes, because it sharpens the paragraph''s focus on community gatherings.","letter":"B"},{"is_no_change":false,"label":"No, because the paragraph already includes a similar detail about the festival''s early years.","letter":"C"},{"is_no_change":false,"label":"No, because it introduces a detail unrelated to the paragraph''s focus on the festival''s growth.","letter":"D"}]', 'D', '{"A":"The paragraph never discusses the town''s overall growth, so the sentence cannot extend a point that was never made.","B":"The paragraph''s focus is one festival''s expansion, not community gatherings in general, so the sentence blurs the focus rather than sharpening it.","C":"Rejects the sentence for a false reason — nothing in the paragraph resembles a quilt fair.","D":"Correct: the quilt fair has no bearing on the festival''s expansion, the paragraph''s single subject."}', 'The paragraph documents one festival''s expansion, and a quilt fair is **off-topic** — so the sentence should be rejected for exactly that reason.', 'The ''community gatherings'' option tempts students because both events are local gatherings, inviting a topic broader than the paragraph actually has.', '1) State the paragraph''s focus in one phrase. 2) Ask whether the proposed sentence advances that focus. 3) Decide yes/no on that basis alone. 4) Then vet the stated reason: a right verdict with a wrong reason is still a wrong option. 5) Pick the choice whose verdict and reason both check out.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a26b586e6c8fff7b', 'act-english', 's-rhet', 3, 'Colleagues describe the retiring reference librarian as a calm, methodical researcher who was <u>super pumped about</u> the library''s new atlas collection.', 'Which choice best maintains the sentence''s measured, professional tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"totally stoked about","letter":"B"},{"is_no_change":false,"label":"crazy about","letter":"C"},{"is_no_change":false,"label":"genuinely enthusiastic about","letter":"D"}]', 'D', '{"A":"''Super pumped'' is gym-class slang that clashes with the sentence''s formal description of a methodical researcher.","B":"''Totally stoked'' swaps one slang phrase for another, leaving the register broken.","C":"''Crazy about'' is milder but still a conversational idiom, not professional prose.","D":"Correct: it expresses the same excitement in diction that matches the sentence''s measured, professional voice."}', 'A sentence must keep one **register** throughout, and only this phrasing matches the formal diction of ''calm, methodical researcher.''', '''Crazy about'' feels tame compared with the original slang, so students accept it without testing it against the sentence''s formal frame.', '1) Identify the passage''s register from surrounding word choices. 2) Flag any underlined words that feel like casual speech. 3) Test each option by asking whether it could appear in a formal written profile. 4) Reject every option with slang or conversational idioms. 5) Confirm the survivor preserves the original meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a3edaa10151f4fdd', 'act-english', 's-rhet', 3, 'Life in the low minors is defined less by the games than by the miles between them. The Owls log more than eleven thousand bus miles each season, often rolling into town at dawn on the day of a game. Players nap in luggage racks, eat gas-station dinners, and learn to stretch in a moving aisle.', 'The writer is considering adding the following sentence at the end of the paragraph: <i>"After one fourteen-hour ride last August, the team took batting practice without having slept at all."</i> Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it offers a vivid specific incident that supports the paragraph''s picture of grueling travel.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why the league schedules so many road games.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information already provided earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it introduces a topic unrelated to the paragraph''s discussion of travel.","letter":"D"}]', 'A', '{"A":"Correct: a single dramatic episode makes the paragraph''s general hardships concrete, so both verdict and reason hold.","B":"The sentence never touches scheduling decisions, so this justification is false even though its verdict matches (right_verdict_wrong_reason).","C":"The paragraph states hardships generally; this dated episode is new material, not repetition (mislabels_new_as_repeat).","D":"A sleepless team stumbling from a long bus ride sits squarely on the travel topic (misjudges_relevance)."}', 'The new sentence turns the paragraph''s general hardship into one **concrete** episode, which is exactly what a reason for adding must claim.', 'Students skim for repetition, see ''dawn arrivals'' mentioned generally, and conclude the anecdote merely restates it.', '1) Summarize the paragraph''s focus in a phrase. 2) Ask whether the new sentence advances that focus. 3) Decide yes or no on that basis alone. 4) Then test each stated reason as a factual claim about the sentence and paragraph. 5) Select the option whose verdict AND reason are both true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a66ffaa6114e62b5', 'act-english', 's-rhet', 3, 'Storage rooms at the museum are inspected on the first Monday of every month. Sticky traps along the baseboards are collected, and their contents are identified under a loupe. Even a single carpet-beetle larva triggers a deep cleaning of the entire aisle.', 'The writer is considering adding the following sentence after the second sentence: "The head of security, who oversees the inspections, recently celebrated twenty years at the museum." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it adds a personal detail that makes the museum''s staff more relatable.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains who ensures that pest-prevention procedures are followed.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats a detail about the inspections that appears earlier in the paragraph''s opening.","letter":"C"},{"is_no_change":false,"label":"No, because it introduces information unrelated to the paragraph''s focus on pest prevention.","letter":"D"}]', 'D', '{"A":"Relatability is not the paragraph''s aim; a staff anniversary does nothing for a paragraph about inspection procedure.","B":"The sentence names an overseer, but the anniversary detail — the sentence''s real content — explains nothing about procedure.","C":"Correctly says no but for a false reason: no earlier sentence mentions the anniversary or the security chief.","D":"Correct: the work anniversary is off-topic for a paragraph devoted to how infestations are caught and handled."}', 'Add/delete decisions hinge on **relevance to the paragraph''s specific job** — a staff milestone contributes nothing to an account of inspection procedure.', 'Because the proposed sentence mentions the inspections, students assume any topical overlap makes it worth adding.', '1) State the paragraph''s job in one sentence. 2) Ask what the proposed sentence''s main point is — not what it mentions in passing. 3) Keep it only if that main point advances the paragraph''s job. 4) Then vet the stated reason: a yes/no verdict is only correct when its because-clause is factually true of the passage. 5) Reject right verdicts attached to wrong reasons.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-aaa3f99b3a59d0f7', 'act-english', 's-rhet', 3, 'The folk revival of the late 1950s and 1960s spread through many channels at once. Campus concerts introduced ballads to students, while reissued records let city listeners hear rural voices from decades earlier. Coffeehouses, festivals, and late-night radio programs each carried the music to a different audience, and by the mid-1960s dozens of performers had built national careers on songs once sung on porches.', 'Suppose the writer''s goal had been to write a brief essay profiling a single influential figure of the folk revival. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it shows how performers built national careers during the movement.","letter":"A"},{"is_no_change":false,"label":"Yes, because it follows one figure of the revival from childhood to fame.","letter":"B"},{"is_no_change":false,"label":"No, because it surveys the whole movement rather than examining one figure in depth.","letter":"C"},{"is_no_change":false,"label":"No, because it focuses on venues and recordings rather than on any performers.","letter":"D"}]', 'C', '{"A":"Mentioning that careers were built is not a profile of any individual, so the goal remains unmet.","B":"Misreads the essay — no individual is named, let alone traced from childhood to fame.","C":"Correct: the essay is a panorama of channels and audiences, never narrowing to one person.","D":"The right verdict with a false reason — performers are mentioned; they simply are not profiled individually."}', 'A profile requires sustained attention to **one person**, and this essay pans across channels, audiences, and unnamed performers instead.', 'The other ''No'' option tempts students because its verdict is right, and verifying the attached reason takes an extra reading step.', '1) Restate the hypothetical goal precisely (here: profile one individual). 2) Ask what the essay actually does, citing its sentences. 3) Match verdict first: does the essay meet the goal? 4) Then audit each option''s reason against the text. 5) Keep only the option whose verdict and reason are both true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b52d60459d7d385c', 'act-english', 's-rhet', 3, 'When the flood cut off the east side of town, volunteers <u>hauled</u> bundles of the emergency edition across the railroad bridge on foot.', 'The writer wants to emphasize the physical effort the volunteers'' task required. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"took","letter":"B"},{"is_no_change":false,"label":"moved","letter":"C"},{"is_no_change":false,"label":"transported","letter":"D"}]', 'A', '{"A":"Correct: the verb connotes dragging heavy weight, putting the volunteers'' exertion front and center.","B":"''Took'' is colorless and says nothing about strain.","C":"''Moved'' records only a change of place, not the labor involved.","D":"''Transported'' is precise but clinical — logistics language, not sweat."}', 'The original verb builds **strain and weight** into its very meaning, exactly the emphasis the stated goal demands.', '''Transported'' tempts students who equate the most formal-sounding word with the best word.', '1) Restate the writer''s stated goal in your own words. 2) For each verb, ask what a reader pictures. 3) Score each verb against the goal, not against formality. 4) Eliminate verbs that are neutral about the goal''s key quality. 5) Pick the one whose connotation delivers the goal.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c42986d0102d9d7d', 'act-english', 's-rhet', 3, 'The poem describes the harvest moon as <u>a large orange circle</u> resting on the shoulders of the hills.', 'The writer wants a vivid figure of speech consistent with the poem''s imagery. Which choice is best?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"an orange-colored sphere","letter":"B"},{"is_no_change":false,"label":"a big round shape","letter":"C"},{"is_no_change":false,"label":"a brass coin","letter":"D"}]', 'D', '{"A":"''A large orange circle'' is literal and flat — no figurative image.","B":"''An orange-colored sphere'' is merely a scientific restatement, not a figure of speech.","C":"''A big round shape'' is vaguer than the original, not more vivid.","D":"''A brass coin'' is a metaphor whose color and sheen match a harvest moon, extending the poem''s imagery."}', 'The stem asks for a **figure of speech**, and the metaphor ''a brass coin'' paints the moon vividly.', '''Orange-colored sphere'' sounds precise, but precision isn''t imagery.', 'When the goal is figurative vividness, choose the metaphor or simile, not a literal description.', 'underlined-span-mc', '''Orange-colored sphere'' sounds precise, but precision isn''t imagery', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c661ba07e7a563b6', 'act-english', 's-rhet', 3, 'In this essay, the writer recounts attending a weekend retrospective of stop-motion films, describing the handcrafted puppets displayed in the lobby and her conversations with a restoration archivist about the challenges of preserving fragile, decades-old sets.', 'Suppose the writer''s goal had been to explain the technical steps involved in producing a stop-motion film. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because the essay describes the handcrafted puppets and sets from a personal visit.","letter":"A"},{"is_no_change":false,"label":"Yes, because preservation efforts require step-by-step production knowledge.","letter":"B"},{"is_no_change":false,"label":"No, because the essay focuses on early features rather than on recent methods.","letter":"C"},{"is_no_change":false,"label":"No, because the essay centers on a personal visit and preservation efforts rather than on production methods.","letter":"D"}]', 'D', '{"A":"Describing puppets and sets shows the essay''s subject matter, not a step-by-step production process.","B":"Whatever the archivist knows offstage, the essay itself never conveys production steps to the reader.","C":"The verdict is right, but era is irrelevant: the goal never demanded recent methods.","D":"Correct verdict and reason: the essay is a personal account of a retrospective and preservation work, not an explanation of production technique."}', 'Purpose questions test what the essay **actually delivers**, and this one delivers a visit narrative, not a how-to.', 'Because puppets and sets are production equipment, mentioning them feels like technical coverage.', '1) Restate the hypothetical goal precisely. 2) Summarize what the essay actually does in one sentence. 3) Compare: does the essay''s content match the goal''s requirement? 4) Pick the verdict whose reason accurately describes both the essay and the goal.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c7093901b40c78e2', 'act-english', 's-rhet', 3, 'When the sear hit the ribeye, the surface <u>changed</u> from dull red to a lacquered mahogany crust in seconds.', 'The writer wants to emphasize how dramatic and rapid the transformation looked. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"erupted","letter":"B"},{"is_no_change":false,"label":"shifted","letter":"C"},{"is_no_change":false,"label":"was different","letter":"D"}]', 'B', '{"A":"Too flat: ''changed'' is accurate but neutral, conveying no drama or speed.","B":"Correct: ''erupted'' delivers the sudden, vivid intensity the writer wants to emphasize.","C":"Too mild: ''shifted'' suggests a gentle, gradual move, the opposite of a dramatic burst.","D":"Weakest: ''was different'' is static and vague, capturing neither drama nor motion."}', 'The goal is **drama and speed**, and ''erupted'' carries explosive suddenness that a neutral verb cannot.', '''Changed'' is perfectly accurate and grammatical, so it feels safe even though it conveys none of the requested intensity.', '1) Underline the goal words in the stem — here, dramatic and rapid. 2) Rank each option for intensity and speed. 3) Discard verbs that are neutral or gradual. 4) Keep the word that most vividly matches the stated goal. 5) Reread the sentence to confirm the chosen word delivers the intended punch.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d0caa0dcd1ef208c', 'act-english', 's-rhet', 3, 'Using a cotton swab no larger than a pencil eraser, the conservator <u>removed</u> the yellowed varnish from the portrait over a span of six weeks.', 'The writer wants to emphasize how slow and painstaking the varnish removal was. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stripped","letter":"B"},{"is_no_change":false,"label":"coaxed away","letter":"C"},{"is_no_change":false,"label":"took off","letter":"D"}]', 'C', '{"A":"''Removed'' is accurate but neutral; it conveys nothing about pace or care.","B":"''Stripped'' suggests speed and force — the opposite of the painstaking effort the writer wants to stress.","C":"Correct: this phrasing implies gentle, patient persuasion of the varnish, matching the stated goal.","D":"''Took off'' is casual and, like the original, carries no sense of slowness or care."}', 'The goal is **emphasis on slow, careful effort**, so the verb itself must carry connotations of gentleness and patience.', 'The original verb is grammatically flawless, so students keep it without checking it against the writer''s stated goal.', '1) Restate the writer''s goal in your own words. 2) For each option, list the connotation the verb adds: fast or slow, forceful or gentle, formal or casual. 3) Eliminate options whose connotations contradict or ignore the goal. 4) Choose the option whose added shading matches the goal, even if others are grammatically fine.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d29f59f623388e3a', 'act-english', 's-rhet', 3, 'As dusk settled over the valley, the dry evening wind <u>moved</u> the fine sand in slow, curling ribbons across the crest of the dune.', 'Which choice best suggests the sand''s gentle, unhurried motion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"hurled","letter":"B"},{"is_no_change":false,"label":"drifted","letter":"C"},{"is_no_change":false,"label":"slammed","letter":"D"}]', 'C', '{"A":"''Moved'' is accurate but flat, conveying none of the gentle, unhurried quality the goal asks for (word_too_neutral).","B":"''Hurled'' implies sudden, forceful motion that contradicts the calm image the goal wants (word_wrong_connotation).","C":"Correct: it evokes the soft, continuous, unhurried motion the goal calls for.","D":"''Slammed'' suggests abrupt violence, the opposite of the gentle movement described (word_wrong_connotation)."}', 'The goal asks for words that convey **gentle, continuous motion**, and only this verb carries that soft connotation.', 'The forceful verb sounds vivid and energetic, so students who equate vividness with strength pick it despite its harsh connotation.', '1) Read the goal and name the exact feeling wanted (gentle, unhurried). 2) List the connotation of each option: neutral, forceful, or soft. 3) Cross out any verb whose feeling clashes with the goal. 4) Keep the one whose connotation matches. 5) Re-read the sentence to confirm the tone fits.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d3c2330f9d1740ee', 'act-english', 's-rhet', 3, 'Wearing white cotton gloves, the conservation technician <u>yanked</u> each brittle letter from its protective sleeve.', 'The writer wants to emphasize the technician''s careful, unhurried handling of the fragile letters. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gently eased","letter":"B"},{"is_no_change":false,"label":"carefully snatched","letter":"C"},{"is_no_change":false,"label":"deliberately grabbed","letter":"D"}]', 'B', '{"A":"''Yanked'' conveys sudden force — the opposite of the careful handling the writer wants to stress.","B":"Correct: both the adverb and the verb depict slow, protective handling, fully serving the stated goal.","C":"''Carefully'' gestures at the goal, but ''snatched'' still describes a quick, rough grab.","D":"''Deliberately'' suggests intent, yet ''grabbed'' remains abrupt and forceful."}', 'Both words must serve the goal, and this pairing makes the **entire action** slow and protective rather than patching a rough verb with a soft adverb.', 'The adverb ''carefully'' seems to satisfy the goal even though the verb it modifies contradicts it.', '1) Restate the writer''s stated goal in your own words. 2) Test the verb first: does its core action match the goal? 3) Then test the modifier: does it reinforce or fight the verb? 4) Reject any option in which either word contradicts the goal. 5) Pick the option where verb and modifier both serve it.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d7e302fc92609309', 'act-english', 's-rhet', 3, 'Steel expands in summer heat and contracts in winter cold. To absorb that movement, designers fit the roadway with toothed expansion joints. Without the joints, the deck would buckle or crack as the seasons changed.', 'The writer wants to add a sentence that reinforces the paragraph''s point about how temperature changes affect the bridge. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"The joints are manufactured by several firms in three different states.","letter":"A"},{"is_no_change":false,"label":"On a hot July afternoon, the main span can grow longer by more than a foot.","letter":"B"},{"is_no_change":false,"label":"Painters often use the joints as convenient boundaries between work zones.","letter":"C"},{"is_no_change":false,"label":"Similar joints appear in elevated highways and parking garages.","letter":"D"}]', 'B', '{"A":"A supplier detail concerns commerce, not thermal movement, so it reinforces nothing (misconception: add_related_but_offpoint).","B":"Gives concrete, measurable proof of heat physically changing the deck, directly reinforcing the paragraph''s claim.","C":"A workplace convenience that would exist even if temperature never changed (misconception: add_incidental_detail).","D":"Widens the topic to other structures without adding evidence about this bridge (misconception: add_broadens_scope)."}', 'Reinforcement means **concrete evidence** for the paragraph''s own claim — here, a vivid measurement of temperature physically moving the deck.', 'The elevated-highways option mentions the joints and sounds informative, so students accept topical overlap as support even though it proves nothing about temperature.', '1) State the paragraph''s claim in one sentence. 2) For each option, ask: does this give evidence for that exact claim? 3) Discard details that are merely about the same objects. 4) Prefer specific, measurable support over general association. 5) Reread the paragraph with the addition to confirm it strengthens the point.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dd0e929d10c612be', 'act-english', 's-rhet', 3, 'The history textbook noted that the treaty''s terms were <u>a real slap in the face</u> to the smaller nations at the table.', 'Which choice best fits the neutral, expository tone of a textbook?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a bum deal for","letter":"B"},{"is_no_change":false,"label":"deeply unfavorable to","letter":"C"},{"is_no_change":false,"label":"a raw deal for","letter":"D"}]', 'C', '{"A":"''A real slap in the face'' is a heated idiom that breaks the textbook''s neutral tone.","B":"''A bum deal for'' is slangy and dismissive.","C":"''Deeply unfavorable to'' is measured and expository, matching the register.","D":"''A raw deal for'' is idiomatic and informal."}', 'A textbook aims for **neutral exposition**, so ''deeply unfavorable to'' fits where idioms don''t.', 'The idioms convey the unfairness forcefully, but force isn''t the textbook''s job.', 'Expository writing stays neutral — replace charged idioms with plain descriptive phrasing.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e28d0bc59d5c215e', 'act-english', 's-rhet', 3, 'Before the family bought a spiral mixer, Etta <u>fought the stiff bagel dough with both fists, bracing her heels against the floor tiles</u>.', 'The writer wants to emphasize the physical strain of mixing bagel dough by hand. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"mixed the bagel dough by hand each morning","letter":"B"},{"is_no_change":false,"label":"prepared the bagel dough in the traditional manner","letter":"C"},{"is_no_change":false,"label":"handled dough that many bakers find difficult","letter":"D"}]', 'A', '{"A":"Correct — ''fought,'' ''both fists,'' and ''bracing her heels'' render the bodily effort in concrete, muscular detail.","B":"States the fact of hand-mixing and its schedule but conveys no effort (goal_states_fact_no_emphasis).","C":"Gestures at tradition, shifting emphasis from strain to heritage (goal_wrong_emphasis_tradition).","D":"Reports other bakers'' opinion of the dough instead of showing Etta''s exertion (goal_secondhand_opinion)."}', 'Vivid physical verbs and body details — fists, braced heels — **show** the strain the writer wants to stress.', 'The plain hand-mixing statement mentions ''by hand,'' which echoes the goal''s wording without delivering any actual strain.', '1) Restate the writer''s goal in your own words. 2) For each option, underline the words that directly serve that goal. 3) Discard options whose words serve a different idea (schedule, tradition, reputation). 4) Pick the option with the most goal-serving detail.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ea3d8da03b17a17d', 'act-english', 's-rhet', 3, 'As the pod of dolphins spotted the research boat, they <u>went</u> through the choppy waves to reach it.', 'Which choice most vividly conveys the dolphins'' energetic speed?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"moved","letter":"B"},{"is_no_change":false,"label":"surged","letter":"C"},{"is_no_change":false,"label":"wandered","letter":"D"}]', 'C', '{"A":"''Went'' is a flat, all-purpose verb that conveys no speed or energy (weak_verb).","B":"''Moved'' is neutral and could describe any pace, so it adds no intensity (weak_verb).","C":"Correct: it conveys powerful, quick forward motion, matching the goal of showing energy.","D":"''Wandered'' implies slow, aimless motion, the opposite of energetic speed (wrong_connotation)."}', 'The goal calls for a verb whose **connotation** stresses forceful, rapid motion.', '''Moved'' is grammatically fine and safe, so students settle for it without weighing its blandness against the goal.', '1) Restate the goal (here, energetic speed). 2) Judge each verb by the image it creates, not just its correctness. 3) Reject verbs that are neutral or carry the wrong feel. 4) Choose the verb whose connotation best matches the goal.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ed095fcf1979657e', 'act-english', 's-rhet', 3, 'Sixteen-year-old Mira Adeyemi wakes at five to review endgame flashcards before school. Afternoons belong to her coach, who drills one opening line until Mira can recite its traps blindfolded. In the final month before the national championship, she plays practice matches against partners chosen to mimic her likely opponents. By the eve of the event, she says, the work is done; all that remains is to sleep well.', 'Suppose the writer''s goal had been to outline how a single young competitor prepares for a major tournament. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because the essay describes the training habits of several rival champions.","letter":"A"},{"is_no_change":false,"label":"Yes, because the essay concentrates on a single competitor''s training methods.","letter":"B"},{"is_no_change":false,"label":"No, because the essay never explains how chess ratings are calculated.","letter":"C"},{"is_no_change":false,"label":"No, because the essay focuses on a single player rather than covering many.","letter":"D"}]', 'B', '{"A":"The verdict is right, but the reason misdescribes the essay, which follows only Mira, not several rivals.","B":"The essay tracks one young player''s preparation step by step, exactly matching the stated goal.","C":"Rating math is a side topic the goal never asks for; its absence is irrelevant to whether the goal is met.","D":"This reason faults the essay for doing precisely what the goal requests: profiling one player''s preparation."}', 'The essay does exactly what the goal asks: it **profiles one player''s preparation** from dawn drills to the eve of the event.', 'The single-player objection tempts because narrow scope often sounds like a flaw, even when the goal explicitly asks for that narrow scope.', '1) Restate the hypothetical goal in your own words, noting its scope. 2) Summarize what the essay actually does. 3) Compare the two: match means yes, mismatch means no. 4) Then verify the winning option''s reason accurately describes the essay itself.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ee066093eaaed416', 'act-english', 's-rhet', 3, 'The weed crew works the trail corridor every July, digging out spotted knapweed wherever it appears. Crew members flag even a single plant growing beside the tread and return to the same spot for several seasons afterward. To a passing hiker, that persistence over one scraggly stem can look like overkill.', 'The writer is considering adding the following sentence after the last sentence of the paragraph: "A single knapweed plant, however, can release more than a thousand seeds in one season." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why the crew treats even one plant as a serious threat.","letter":"A"},{"is_no_change":false,"label":"Yes, because it demonstrates that the crew knows more about botany than most hikers do.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information stated earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus from the weed crew to the hikers.","letter":"D"}]', 'A', '{"A":"Correct: the seed count answers the ''overkill'' skepticism by revealing the hidden stakes of one plant, justifying the crew''s persistence.","B":"Right verdict, wrong reason: the sentence justifies the crew''s persistence; it is not a comparison of anyone''s botany knowledge.","C":"Nothing earlier mentions seeds or the plant''s reproductive threat, so the sentence adds information rather than repeating any.","D":"The sentence is about the plant and its danger, keeping the spotlight exactly where the paragraph already has it."}', 'The sentence should be added because it supplies the **missing justification** — the hidden threat that makes the crew''s persistence rational, answering the hiker''s skepticism.', 'The botany-knowledge reason tempts students who accept any ''Yes'' rationale once they sense the sentence belongs, without checking what the sentence actually does.', '1) Restate the paragraph''s focus. 2) State what the proposed sentence adds. 3) Decide add or don''t-add by whether it serves that focus. 4) Then vet the reason: it must describe the sentence''s actual function, not merely reach the right verdict.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f0ae554f91d8c5bf', 'act-english', 's-rhet', 3, 'When the city tore up Main Street last spring, the Riverbend farmers'' market seemed doomed. Instead, its manager negotiated a temporary lease on a school parking lot two blocks away, printed detour maps for regular customers, and persuaded a local radio station to announce the new location every Friday. Attendance dipped for a month and then rebounded past the previous year''s numbers.', 'Suppose the writer''s goal had been to show how one farmers'' market adapted to a disruptive construction season. Would this passage accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it lists every vendor who agreed to move to the school parking lot.","letter":"A"},{"is_no_change":false,"label":"Yes, because it recounts the manager''s responses to the disruption and the outcome.","letter":"B"},{"is_no_change":false,"label":"No, because it dwells on the radio station''s schedule rather than on the market.","letter":"C"},{"is_no_change":false,"label":"No, because it never identifies the reason the city planned the construction.","letter":"D"}]', 'B', '{"A":"Right verdict, wrong reason — the passage names no individual vendors, so this justification misdescribes the text (reason_misdescribes).","B":"Correct — the passage narrates specific adaptive steps and their result, exactly matching the stated goal.","C":"The radio station appears in a single supporting detail; the market''s adjustment stays the focus (false_focus_shift).","D":"The construction''s cause is irrelevant to whether the passage shows adaptation (irrelevant_criterion)."}', 'The passage narrates the specific adaptive moves — new site, detour maps, radio announcements — and their **result**, which is precisely what the supposed goal requires.', 'Because the passage never explains the construction project itself, students conclude it fails a goal that never demanded that background.', '1) Restate the supposed goal in your own words. 2) Ask: does the passage as written do that? Fix your verdict. 3) Discard options whose verdict disagrees with yours. 4) Among matching verdicts, verify the reason against the text line by line. 5) Choose the option whose reason describes what the passage actually contains.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f42903f54fb3d4b9', 'act-english', 's-rhet', 3, 'The senator''s memoir describes her rivals as <u>determined</u> operators who would say anything to win.', 'Which word best conveys the memoir''s clearly critical view of the rivals?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"dedicated","letter":"B"},{"is_no_change":false,"label":"scheming","letter":"C"},{"is_no_change":false,"label":"spirited","letter":"D"}]', 'C', '{"A":"''Determined'' is neutral-to-positive and doesn''t match ''say anything to win''.","B":"''Dedicated'' is admiring, the wrong direction entirely.","C":"''Scheming'' carries a distinctly negative charge that fits the critical portrait.","D":"''Spirited'' is lively and positive, clashing with the disapproving context."}', 'The stem signals **criticism**, so choose the word whose connotation is negative — ''scheming''.', '''Determined'' pairs with ''operators'' naturally, hiding that it praises rather than criticizes.', 'Read the surrounding clues for the writer''s stance, then match the word''s charge (positive/negative) to it.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f72616bf39de9009', 'act-english', 's-rhet', 3, 'Preparation for a fireworks night begins the moment the schedule is printed. The operations staff files permits with the city, hires a licensed pyrotechnics vendor, and briefs the grounds crew on postgame cleanup.', 'The writer wants to add one more sentence with information most relevant to the paragraph''s focus on how the ballpark prepares for fireworks nights. Given that all the choices are true, which one should the writer add?', '[{"is_no_change":false,"label":"The Owls'' mascot costume was redesigned by a local art student in 2018.","letter":"A"},{"is_no_change":false,"label":"Crews rope off a landing zone in the outfield and soak the warning track before the first pitch.","letter":"B"},{"is_no_change":false,"label":"Fireworks were invented in China well over a thousand years ago.","letter":"C"},{"is_no_change":false,"label":"Many fans prefer afternoon games during the chilly early weeks of April.","letter":"D"}]', 'B', '{"A":"A mascot''s makeover is trivia unconnected to show-night readiness (detail_offtopic).","B":"Correct: it adds another concrete preparation task, matching the paragraph''s list of readiness steps.","C":"Ancient origins are background trivia, not a preparation step (detail_trivia).","D":"Fan seating preferences describe atmosphere, not the staff''s readiness work (detail_wrong_focus)."}', 'The paragraph is a list of **preparation tasks**, and only this choice adds another task to that list.', 'The historical fact is genuinely interesting, so students confuse an engaging fact with a relevant one.', '1) Name the paragraph''s focus in five words or fewer. 2) For each option, ask: does this perform the same job the other sentences perform? 3) Reject options that add background, trivia, or a different subject, however true. 4) Keep the one that extends the paragraph''s specific work. 5) Re-read the paragraph with it inserted.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f7486bd8d5968914', 'act-english', 's-rhet', 3, '[1] Blanching vegetables briefly in boiling water, then plunging them into ice, locks in their bright color. [2] The quick heat deactivates the enzymes that would otherwise dull the green, while the ice bath halts cooking before the texture goes soft. [3] Cooks use this two-step trick before freezing produce for the winter.', 'The writer is considering adding the following sentence after sentence 2: ''The shock of the ice bath is what preserves the crispness that freezing alone would ruin.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it introduces the new topic of freezing that the paragraph goes on to develop.","letter":"A"},{"is_no_change":false,"label":"Yes, because without it the paragraph never explains why blanching is done at all.","letter":"B"},{"is_no_change":false,"label":"No, because it contradicts the earlier claim that the ice bath halts cooking.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats the point sentence 2 already makes about the ice bath protecting texture.","letter":"D"}]', 'D', '{"A":"False justification: the sentence dwells on the ice bath and crispness, not on freezing as a new topic.","B":"False justification: sentence 2 already explains the purpose, so this reason misreads the paragraph.","C":"Misreads the logic: the new sentence agrees with sentence 2 rather than contradicting it.","D":"Correct: sentence 2 already states the ice bath protects texture, so the addition is redundant."}', 'The addition merely **restates** sentence 2''s point that the ice bath preserves texture, so it should be left out as redundant.', 'The sentence sounds informative and on-topic, and its mention of freezing seems to tie neatly to the last sentence.', '1) Read the proposed sentence and state its single point. 2) Scan the paragraph for any sentence already making that point. 3) If the point is already present, the addition is redundant and should be cut. 4) If the point is new and relevant, keep it. 5) Match your yes/no to a reason that survives a careful reread.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-faccf9915a4ef928', 'act-english', 's-rhet', 3, 'The roadrunner ranks among the desert''s most capable predators. Fast and endlessly alert, it patrols open ground on foot from first light until the midday heat drives it into shade. Few small creatures that wander across its path survive once the bird locks them in its gaze.', 'Which detail, if added to the paragraph, would most clearly support its focus on the roadrunner''s skill as a hunter?', '[{"is_no_change":false,"label":"Its mottled brown feathers and long tail make it hard to spot against the brush.","letter":"A"},{"is_no_change":false,"label":"The bird ranges across open country from Kansas down into central Mexico.","letter":"B"},{"is_no_change":false,"label":"With lightning jabs of its beak, it can seize a fleeing lizard and even kill a young rattlesnake.","letter":"C"},{"is_no_change":false,"label":"Cartoon versions of the bird made it famous long before most viewers saw a real one.","letter":"D"}]', 'C', '{"A":"Describes camouflage rather than the paragraph''s focus on how the bird catches prey (add_offtopic).","B":"Gives geographic range, which does not develop the point about hunting skill (add_offtopic).","C":"Correct: it shows the bird''s speed and lethal precision in taking prey, directly supporting the hunting focus.","D":"Adds a pop-culture aside unrelated to the bird''s abilities as a predator (add_offtopic)."}', 'Only this detail demonstrates the roadrunner''s **prey-catching ability**, which is the paragraph''s stated focus.', 'The camouflage detail feels connected because it also concerns survival, so students accept it without checking that the focus is hunting, not hiding.', '1) Pin down the paragraph''s focus (the roadrunner as a skilled hunter). 2) Read each candidate detail and ask whether it develops that exact focus. 3) Discard details about looks, range, or fame, however interesting. 4) Keep the one that shows the bird actually catching prey. 5) Re-read the paragraph with it added to confirm the focus tightens.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fc229fdb36c8cba5', 'act-english', 's-rhet', 3, 'The galleries'' climate system holds humidity within a narrow band all year. Wood responds to moisture like a sponge, swelling in damp weather and shrinking in dry spells. _____', 'The writer wants to conclude the paragraph with a detail that directly supports its point that swings in humidity damage wooden artifacts. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Repeated swelling and shrinking can split a carved chest along its glue seams.","letter":"A"},{"is_no_change":false,"label":"Some carved chests in the collection date to the seventeenth century.","letter":"B"},{"is_no_change":false,"label":"The climate system was installed by a local engineering firm in 2019.","letter":"C"},{"is_no_change":false,"label":"Visitors often remark on how comfortable the galleries feel.","letter":"D"}]', 'A', '{"A":"Correct: it names a concrete consequence of the moisture cycle, tying the mechanism directly to damage.","B":"An artifact''s age says nothing about how humidity harms it.","C":"Who installed the equipment is background trivia, not evidence of damage.","D":"Visitor comfort is irrelevant to the paragraph''s point about harm to objects."}', 'The best detail **completes the causal chain** — from moisture cycling to visible harm — that the paragraph sets up.', 'Details that mention the collection or the climate system feel on-topic even when they never touch the damage the stem requires.', '1) Restate the paragraph''s point as a cause-and-effect claim. 2) For each option, ask: does it show the effect the claim predicts? 3) Cut options that merely share a noun with the paragraph (the system, the objects) without advancing the claim. 4) Choose the detail that a skeptical reader would accept as evidence of the stated harm.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fd1e25efa798e903', 'act-english', 's-rhet', 3, 'For ten hours a day, the crew <u>shouldered ninety-pound bags of gravel up the narrow switchbacks</u>, pausing only long enough to refill water bottles at the spring.', 'The writer wants to emphasize the physical demands of the crew''s work. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"carried supplies up the trail","letter":"B"},{"is_no_change":false,"label":"moved gravel to where it was needed","letter":"C"},{"is_no_change":false,"label":"took in sweeping views of the valley on the way up the switchbacks","letter":"D"}]', 'A', '{"A":"Correct: the concrete weight, the body-strain verb, and the narrow climb make the labor physically vivid, serving the stated goal.","B":"Generic: ''carried supplies up the trail'' could describe a light daypack and conveys no strain at all.","C":"Logistical: it reports what got moved where, treating the task as planning rather than physical effort.","D":"Off-goal: scenery makes the climb sound pleasant, working against the emphasis on toil the writer wants."}', 'The original wording delivers **concrete, muscle-level detail** — exact weight, effortful verb, punishing terrain — which is what emphasizing physical demands requires.', 'The vaguer ''carried supplies'' version tempts students who judge options by smoothness instead of testing them against the stated goal.', '1) Restate the writer''s goal in your own words. 2) Cross out any version that contradicts the goal. 3) Among the rest, keep the version with the most concrete, specific detail serving the goal. 4) Confirm the winner actually creates the impression the stem names.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-01d759ebba334377', 'act-english', 's-rhet', 4, 'To raise the studio''s tallest planters, Imani <u>works with</u> nearly twenty pounds of clay at a time, coaxing the walls upward through a dozen slow pulls.', 'The writer wants to emphasize the physical effort that throwing large forms demands. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shapes","letter":"B"},{"is_no_change":false,"label":"wrestles","letter":"C"},{"is_no_change":false,"label":"manages","letter":"D"}]', 'C', '{"A":"''Works with'' is neutral about exertion, fitting light tasks as easily as heavy ones (goal-neutral verb).","B":"''Shapes'' emphasizes artistry and skill rather than the muscle the goal demands (wrong emphasis).","C":"Correct: ''wrestles'' turns the clay into a physical opponent, foregrounding strenuous bodily effort.","D":"''Manages'' suggests calm competence at a distance, understating physical labor (weak emphasis)."}', 'Only a verb that conveys **strenuous bodily struggle** fulfills the stated goal of emphasizing physical effort.', '''Shapes'' feels apt because the sentence is about pottery, but it spotlights craftsmanship instead of the exertion the goal names.', '1) Restate the writer''s goal in one word (here: effort). 2) Ask of each verb: what does it emphasize? 3) Eliminate verbs that are neutral about the goal''s idea. 4) Eliminate verbs that emphasize a different quality. 5) Keep the verb whose core meaning is the goal itself.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-04b3df88a3e00997', 'act-english', 's-rhet', 4, 'Compared with the first draft''s plain claim that the city was busy, the final essay called downtown <u>a place with a lot going on</u>, drums of traffic and voices layered like a live recording.', 'The writer wants figurative language that outshines the plain first-draft phrasing. Which choice best does that?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"an active area","letter":"B"},{"is_no_change":false,"label":"a restless orchestra","letter":"C"},{"is_no_change":false,"label":"a very lively spot","letter":"D"}]', 'C', '{"A":"''A place with a lot going on'' is as plain as the first draft it''s meant to surpass.","B":"''An active area'' is flat, generic, and less vivid, not more.","C":"''A restless orchestra'' is a metaphor that matches ''drums of traffic and voices layered like a live recording''.","D":"''A very lively spot'' just adds an intensifier without figurative force."}', 'The stem demands **figurative language**, and ''a restless orchestra'' extends the essay''s sound imagery.', '''A very lively spot'' feels like an upgrade because of ''very'', but an intensifier isn''t imagery.', 'To surpass plain phrasing, reach for a metaphor tied to the passage''s imagery, not a stronger adjective.', 'underlined-span-mc', '''A very lively spot'' feels like an upgrade because of ''very'', but an…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0772e0e8c8a61690', 'act-english', 's-rhet', 4, 'On the morning of her naturalization ceremony, my grandmother pressed the navy dress she had sewn from a pattern her sister mailed from Krakow. At the courthouse, she repeated the oath in careful English, her accent softening the vowels. Afterward, my grandfather photographed her on the steps, certificate held against the wind. She kept the dress, the photograph, and the flag pin in one box for the rest of her life.', 'Suppose the writer''s goal had been to provide a step-by-step account of how immigrants obtained citizenship in the 1930s. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it describes the day the grandmother completed her naturalization.","letter":"A"},{"is_no_change":false,"label":"Yes, because the oath mentioned in the essay was a legal requirement for citizenship.","letter":"B"},{"is_no_change":false,"label":"No, because the essay is a personal portrait of a single celebration, not an explanation of legal procedures.","letter":"C"},{"is_no_change":false,"label":"No, because the essay focuses mainly on the courthouse rather than on the grandmother.","letter":"D"}]', 'C', '{"A":"Describing the ceremony day narrates an outcome; it does not lay out the legal steps the supposed goal requires.","B":"One glancing reference to the oath cannot stand in for a step-by-step account of the whole process.","C":"Correct: the essay is an intimate family scene, not an explanation of how citizenship was legally obtained.","D":"The essay centers on the grandmother throughout; the courthouse is only a setting."}', 'The essay''s scope is a **family memory**, so it cannot serve a goal that demands a procedural account.', 'The oath detail tempts students to answer yes because it is genuinely legal, but one step is not a whole process.', '1) Restate the hypothetical goal precisely. 2) Summarize what the essay actually does in one sentence. 3) Compare scope: process account versus intimate scene. 4) Give the yes/no verdict. 5) Then screen the reasons: keep only the one that describes the essay accurately.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0864ccfba2951a85', 'act-english', 's-rhet', 4, '<p>At Foxglove Pottery, apprentices spend their first season mixing glazes and loading kilns before they ever sit at a wheel. In their second season, they throw the studio''s standard forms — mugs, bowls, plates — until each piece matches the house template within a few grams. Only in the third season do apprentices design work of their own, which the studio sells alongside its established line. By the time they leave, most can run every station in the building.</p>', 'Suppose the writer''s goal had been to describe how one pottery studio trains its apprentices. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it explains why handmade pottery costs more than factory ware.","letter":"A"},{"is_no_change":false,"label":"Yes, because it traces the stages of training an apprentice completes at one studio.","letter":"B"},{"is_no_change":false,"label":"No, because it does not compare that training with programs at other studios.","letter":"C"},{"is_no_change":false,"label":"No, because it follows one apprentice through a single day rather than describing the training.","letter":"D"}]', 'B', '{"A":"The passage never mentions cost or factory production, so this reason has no textual basis (yes-with-fabricated-reason).","B":"Correct: the essay moves season by season through Foxglove''s training, exactly matching the stated goal.","C":"The goal never asks for comparison with other programs, so their absence is no failure (demands-unrequested-content).","D":"The essay covers years of training for apprentices in general, not one person''s day (misreads the passage''s scope)."}', 'The essay''s season-by-season structure **matches the stated goal** of describing one studio''s apprentice training.', 'Students often reject a passage for lacking comparisons or context the stated goal never demanded.', '1) Restate the supposed goal in your own words. 2) Summarize what the passage actually does. 3) Judge only whether the two match — nothing more. 4) Reject reasons that describe content the passage doesn''t contain. 5) Reject reasons that demand content the goal never required.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0916a90628a634c7', 'act-english', 's-rhet', 4, '[1] Shadow interpreting places the interpreter onstage, moving in step with the actor she voices. [2] The approach demands weeks of blocking rehearsals so that the interpreter never masks a key gesture. [3] Directors who have staged it this way report that Deaf patrons follow plot twists without ever glancing away from the action. [4] Traditional placement, by contrast, parks the interpreter at the stage''s edge beneath a small spotlight.', 'The writer is considering deleting Sentence 3. Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it names the directors who first staged a shadow-interpreted production.","letter":"A"},{"is_no_change":false,"label":"Kept, because it reports a payoff of the technique for the Deaf patrons it is intended to reach.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it interrupts the paragraph''s account of rehearsal schedules.","letter":"C"},{"is_no_change":false,"label":"Deleted, because the reactions of Deaf patrons have little to do with the technique being described.","letter":"D"}]', 'B', '{"A":"Sentence 3 mentions unnamed directors'' observations; it never identifies who pioneered the staging.","B":"Correct — it supplies the paragraph''s only proof that shadow staging achieves its purpose for Deaf theatergoers.","C":"Only Sentence 2 concerns rehearsals; Sentence 3 turns to results, so nothing about schedules is interrupted.","D":"How Deaf patrons experience the show is the whole point of the staging, not a side issue."}', 'Sentence 3 is the paragraph''s only **support** showing the staging works, so cutting it would leave the claim unproven.', 'The rehearsal option tempts readers who assume any sentence between two related sentences must be an interruption.', '1) State the paragraph''s main claim. 2) Ask what the target sentence contributes: proof, detail, or detour? 3) If it is the only support for the claim, keep it. 4) Accept a keep/delete option only when its ''because'' reason matches that contribution exactly.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0ab57baedfac421e', 'act-english', 's-rhet', 4, 'Waiting in the wings, Dana <u>locked her eyes on the stage manager''s cue light</u> and mouthed her first line again and again.', 'The writer wants to convey the intensity of Dana''s concentration in the moments before her entrance. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"glanced now and then at the cue light","letter":"B"},{"is_no_change":false,"label":"stood somewhere near the cue light","letter":"C"},{"is_no_change":false,"label":"figured the cue light would come on soon","letter":"D"}]', 'A', '{"A":"Correct: the fixed, unbroken gaze dramatizes exactly the intense concentration the writer wants.","B":"Occasional glances suggest drifting, divided attention — the opposite of intensity (goal_weakened_action).","C":"A statement of physical position says nothing about her mental state (goal_no_emphasis).","D":"A casual prediction about timing conveys detachment rather than focus (goal_wrong_emphasis)."}', 'The original phrase shows attention **riveted** to a single point, which is precisely the intensity the stem demands.', 'The glancing version tempts students because it keeps Dana watching the cue light, even though intermittent checking undercuts the required intensity.', '1) Restate the writer''s goal in your own words. 2) For each option, name the image or feeling its verb creates. 3) Eliminate options that merely relate to the topic without delivering the goal. 4) Compare the survivors for strength of effect. 5) Choose the one whose action itself embodies the goal.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0b9f10d3a8d17637', 'act-english', 's-rhet', 4, 'When the ice face finally gave way, a slab the size of a cathedral <u>dropped</u> into the fjord.', 'The writer wants to emphasize the overwhelming sound of the calving event. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"plunged","letter":"B"},{"is_no_change":false,"label":"thundered","letter":"C"},{"is_no_change":false,"label":"tumbled","letter":"D"}]', 'C', '{"A":"''Dropped'' reports the motion neutrally and says nothing about sound (goal ignored).","B":"''Plunged'' adds speed and drama but appeals to the eye, not the ear (goal_wrong_emphasis).","C":"This verb makes the slab''s descent audible, directly serving the stated goal.","D":"''Tumbled'' suggests chaotic motion yet stays silent about the noise (wrong sense)."}', 'Only this verb carries an **auditory** charge, matching the writer''s stated goal of emphasizing sound.', '''Plunged'' feels vivid and forceful, so students choose drama in general instead of the specific sense the stem demands.', '1) Underline the goal word in the stem (here, sound). 2) For each verb, name the sense it appeals to: sight, sound, or motion. 3) Eliminate every option serving a different sense, however vivid. 4) Choose the one aimed at the stated goal. 5) Reread the stem to confirm the match.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-118aaf2b04d45814', 'act-english', 's-rhet', 4, 'Railway Post Office clerks sorted letters in a swaying car while the train ran, pigeonholing mail for towns the line would not reach for hours. Each clerk memorized hundreds of local routes and passed a yearly sorting exam at better than ninety percent accuracy. At small stations the train never even slowed; a steel catcher arm snatched the waiting mail pouch at forty miles an hour.', 'The writer is considering adding the following sentence after the first sentence: "The first adhesive postage stamp had been issued in Britain in 1840." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why so much mail traveled by train.","letter":"A"},{"is_no_change":false,"label":"Yes, because it establishes when the clerks'' profession began.","letter":"B"},{"is_no_change":false,"label":"No, because it shifts attention from the clerks'' work aboard the train to the broader history of postage.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats information given earlier in the paragraph.","letter":"D"}]', 'C', '{"A":"The stamp''s debut explains nothing about mail volume on trains, so the offered reason fails.","B":"The 1840 stamp dates postal prehistory, not the founding of the sorting clerks'' profession.","C":"Correct: the paragraph profiles the clerks'' onboard duties, and a British stamp fact pulls readers away from that focus.","D":"The rejection is right but the reason is false: no earlier sentence mentions stamps or 1840."}', 'The detail is **off-focus**: every sentence serves the clerks'' onboard routine, and the stamp fact serves none of it.', 'The ''repeats information'' option tempts students who sense the sentence doesn''t belong but grab the first ''No'' reason without checking it.', '1) State the paragraph''s focus in one line. 2) Ask whether the proposed sentence advances that focus. 3) If not, lean ''No'' — then verify the stated reason describes what the sentence actually does. 4) Reject any option whose reason is factually wrong, even when its verdict is right.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1e5df7fa8604fa2c', 'act-english', 's-rhet', 4, '<p>Charles Darwin proposed that a ring-shaped atoll begins as a reef fringing a volcanic island. As the island slowly subsides beneath the sea, the coral keeps building upward toward the sunlight, until the drowned peak leaves only a circle of reef around a central lagoon. For decades the idea remained an elegant guess.</p>', 'The writer wants to add a sentence that best supports the paragraph''s point that Darwin''s idea was eventually put to the test. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Darwin first developed the theory during his voyage aboard the Beagle.","letter":"A"},{"is_no_change":false,"label":"In the twentieth century, geologists bored deep into a Pacific atoll and struck volcanic rock beneath thick layers of coral, exactly as the theory required.","letter":"B"},{"is_no_change":false,"label":"Atolls are among the most photographed formations in tropical seas.","letter":"C"},{"is_no_change":false,"label":"Coral polyps can survive only within a narrow range of water temperatures.","letter":"D"}]', 'B', '{"A":"Where the theory came from doesn''t show it was tested; it only gives background (misconception: relevance_background_not_support).","B":"This physical evidence directly confirms the prediction, supporting the paragraph''s point that the idea was tested.","C":"How photogenic atolls are is irrelevant to whether the theory was verified (misconception: relevance_offtopic_appeal).","D":"A fact about temperature tolerance is true but does nothing to test the subsidence theory (misconception: relevance_true_but_irrelevant)."}', 'Only the boring evidence **confirms** the prediction, which is exactly the point the paragraph is building toward.', 'The Beagle detail is famous and on-subject about Darwin, so it feels supportive even though it never tests the theory.', '1) Pin down the paragraph''s point (here, that the theory was finally tested). 2) For each candidate, ask whether it advances that specific point or merely touches the general topic. 3) Keep the detail that provides evidence for the point. 4) Discard details that are background, decorative, or true-but-unrelated.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1f564c307449ff41', 'act-english', 's-rhet', 4, 'Since 2017, the Everglades python elimination program has paid contractors to hunt invasive Burmese pythons. The snakes have devastated native mammals; marsh rabbits have all but vanished from parts of the park. <em>One veteran contractor also competes in bass-fishing tournaments on weekends.</em> Together, the hunters have removed more than 11,000 pythons. The writer is considering deleting the sentence in italics.', 'Should the sentence in italics be kept or deleted?', '[{"is_no_change":false,"label":"Deleted, because it repeats information stated earlier in the paragraph.","letter":"A"},{"is_no_change":false,"label":"Deleted, because it shifts attention away from the program''s results.","letter":"B"},{"is_no_change":false,"label":"Kept, because it provides essential background on python biology.","letter":"C"},{"is_no_change":false,"label":"Kept, because it creates a smooth transition to the removal total that follows.","letter":"D"}]', 'B', '{"A":"Reaches the right verdict with a false reason—no earlier sentence mentions the contractor''s hobby.","B":"Correctly deletes and correctly explains: the hobby detail interrupts the line from problem to outcome.","C":"Misdescribes the sentence, which says nothing about python biology.","D":"Claims a transition, but weekend fishing has no logical link to the 11,000-python total."}', 'The italicized sentence is a **tangent**—it breaks the paragraph''s thread from invasion problem to removal outcome.', 'The ''transition'' justification tempts students because the sentence sits physically between two others, and position gets mistaken for function.', '1) State the paragraph''s through-line. 2) Ask what the target sentence contributes to it. 3) If nothing, delete. 4) Vet the stated reason: it must match what the sentence actually does or fails to do.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-20d5190700e7e6c2', 'act-english', 's-rhet', 4, 'The library''s folk-song archive follows strict conservation protocols. Staff members <u>routinely inspect</u> each wax cylinder for hairline cracks before it is approved for playback.', 'Which choice best maintains the formal tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"are always poking at","letter":"B"},{"is_no_change":false,"label":"keep tabs on","letter":"C"},{"is_no_change":false,"label":"lovingly fuss over","letter":"D"}]', 'A', '{"A":"Correct: the measured, professional phrasing matches ''strict conservation protocols.''","B":"''Poking at'' is casual and even implies careless handling, clashing with the passage''s precision.","C":"''Keep tabs on'' is conversational idiom, too breezy for institutional prose.","D":"''Lovingly fuss over'' is sentimental and fussy, trading professional distance for cuteness."}', 'The underlined phrase already matches the passage''s **formal, institutional register**, so it should stand.', '''Keep tabs on'' tempts students because it is common in everyday speech and feels natural, masking its casual register.', '1) Sample the passage''s register from its other sentences (formal, neutral, or casual?). 2) Read each option and label its register the same way. 3) Discard options that would sound out of place in the surrounding prose. 4) Confirm the survivor also preserves the sentence''s exact meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-225a988bdbe48711', 'act-english', 's-rhet', 4, 'Passage II — The Science of Sourdough — Bread may seem simple, <u>but sourdough is surprisingly complex.</u> Unlike breads made with packaged yeast, sourdough rises using wild yeast and bacteria captured from the air. Bakers maintain a "starter," a mixture of flour and water that they feed regularly. The starter, it ferments over several days. During fermentation, the microbes produce carbon dioxide, which makes the dough rise. They also produce acids, giving sourdough its tangy flavor. Because of these reactions, no two starters taste exactly alike. Some bakers, claim that a starter''s flavor reflects the place where it was made. A San Francisco starter, for instance, may taste different from one in Paris. Whether or not that is true, sourdough remains a small marvel of biology and patience.', 'Which underlined choice best concludes the essay by returning to its opening idea?', '[{"is_no_change":false,"label":"NO CHANGE (sourdough remains a small marvel of biology and patience.)","letter":"A"},{"is_no_change":false,"label":"sourdough is sold in stores.","letter":"B"},{"is_no_change":false,"label":"people have made bread for centuries.","letter":"C"},{"is_no_change":false,"label":"flour is a common ingredient.","letter":"D"}]', 'A', '{"A":"Only A echoes \"may seem simple\" with the \"small marvel\" idea.","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Only A echoes "may seem simple" with the "small marvel" idea.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Production (conclusion tie-back)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-279404aa336ecda4', 'act-english', 's-rhet', 4, 'Volunteering at the shop has become an informal job-training program. Teenagers who start by folding sweaters learn to schedule shifts, balance a register drawer, and negotiate with donors. One former volunteer, Dara Okafor, parlayed three summers at the register into a bookkeeping job at a regional bank.', 'The writer is considering deleting the final sentence of the paragraph. Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it offers a concrete example of a volunteer gaining the job skills the paragraph describes.","letter":"A"},{"is_no_change":false,"label":"Kept, because it explains how the shop recruits new volunteers each summer.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it repeats information stated earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"Deleted, because it shifts the paragraph''s attention away from volunteer training.","letter":"D"}]', 'A', '{"A":"Correct: Dara''s bookkeeping job is a specific case proving the paragraph''s claim that volunteering builds job skills.","B":"Right verdict, wrong reason — the sentence says nothing about recruiting.","C":"The example adds a new, specific outcome; nothing earlier mentions Dara or the bank.","D":"The sentence is the payoff of the training idea, not a departure from it."}', 'The sentence supplies a **specific example** that proves the paragraph''s general claim, the strongest reason to keep it.', 'Because the sentence names one person while the rest of the paragraph generalizes, it can look like a digression rather than evidence.', '1) State the paragraph''s claim. 2) Ask what the target sentence does for that claim (proves it, repeats it, or ignores it). 3) Keep sentences that prove or develop; cut ones that repeat or stray. 4) Then check the option''s stated reason against your step-2 answer. 5) Select the verdict-plus-reason pair that matches.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-286e73cd5a881051', 'act-english', 's-rhet', 4, 'Hurricane hunter crews fly directly into a storm''s eyewall to collect measurements no satellite can supply. Dropsondes released from the aircraft fall through the storm, radioing back pressure and wind readings every few seconds. Those readings often revise the official intensity estimate within the hour. The plane itself is heavily reinforced, with instruments bolted to nearly every exterior surface.', 'The writer is considering deleting the final sentence of the paragraph. Should the sentence be deleted?', '[{"is_no_change":false,"label":"No, because it explains how the plane''s reinforced frame lets crews survive the eyewall.","letter":"A"},{"is_no_change":false,"label":"No, because it is the only sentence that describes the instruments used on the flights.","letter":"B"},{"is_no_change":false,"label":"Yes, because it shifts attention from the data the flights gather to the plane''s construction.","letter":"C"},{"is_no_change":false,"label":"Yes, because it contradicts the earlier claim that satellites cannot supply such data.","letter":"D"}]', 'C', '{"A":"The sentence never connects reinforcement to crew survival, and the paragraph''s purpose is the measurements, not the airframe (misconception: invented relevance rescues a detail).","B":"Being the only sentence on a side topic is a reason to cut it, not keep it, when the paragraph is about what the readings accomplish (misconception: unique information is automatically valuable).","C":"Correct: the paragraph tracks how the flights'' measurements improve intensity estimates, and a closing description of the airframe strays from that thread.","D":"Nothing in the sentence contradicts the satellite claim; the deletion verdict is right but this reason is false (misconception: right verdict, wrong reason)."}', 'The paragraph''s through-line is the **measurements** and their effect on forecasts, and the final sentence departs from it to describe hardware.', 'The survival explanation feels reasonable — reinforcement must be for safety — but the sentence itself never says so, and safety is not the paragraph''s point.', '1) State the paragraph''s main job in one clause. 2) Ask what the candidate sentence contributes to that job. 3) If it serves a different job, lean toward deletion. 4) Then vet each option''s reason: is it factually true of the sentence? 5) Choose the option whose verdict and reason are both accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2ec3664d2b4e817b', 'act-english', 's-rhet', 4, 'The legal memo advised the client that signing the waiver would <u>pretty much tie your hands</u> in any future dispute.', 'Which choice best matches the precise, formal tone appropriate to a legal memo?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"seriously limit your options","letter":"B"},{"is_no_change":false,"label":"restrict your legal recourse","letter":"C"},{"is_no_change":false,"label":"leave you stuck","letter":"D"}]', 'C', '{"A":"''Pretty much tie your hands'' mixes a hedge (''pretty much'') with an idiom, both too casual for a memo.","B":"''Seriously limit your options'' is clearer but still colloquial in ''seriously''.","C":"''Restrict your legal recourse'' is precise, formal, and uses the exact legal register.","D":"''Leave you stuck'' is informal and vague."}', 'A legal memo demands **precise, formal terminology**, and ''restrict your legal recourse'' supplies it.', '''Seriously limit your options'' feels professional enough, but ''seriously'' still lowers the register.', 'In technical or legal writing, choose the exact domain term over an idiom or hedge.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2f8a3b0ea5b592d1', 'act-english', 's-rhet', 4, 'After the final bow, the cast lingered onstage beneath the dim work lights, none of them ready to leave. For the crew who had built the set piece by piece, striking it the next morning <u>was a total bummer</u>.', 'Which choice best maintains the tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was a real gut-punch","letter":"B"},{"is_no_change":false,"label":"occasioned a profound episode of lamentation","letter":"C"},{"is_no_change":false,"label":"was a quiet loss","letter":"D"}]', 'D', '{"A":"Casual slang deflates the passage''s subdued, wistful mood at its most reflective moment (tone_too_casual).","B":"The violent physical-impact idiom spikes the intensity far past the passage''s gentle register (tone_overwrought_colloquial).","C":"The stiff, Latinate phrasing is more formal and ornate than the passage''s plain reflective voice (tone_too_formal).","D":"Correct: the understated phrasing matches the muted, lingering sadness the passage has established."}', 'Tone must stay **consistent**, and only this phrasing keeps the passage''s subdued, reflective register.', 'The gut-punch idiom tempts students because it sounds vivid and emotional, but its jolting force clashes with the passage''s gentleness.', '1) Read the sentences around the blank and label their mood in two words. 2) Label each option''s register: slangy, violent, ornate, or plain. 3) Eliminate options that miss the mood in either direction — too casual or too stiff. 4) Read the survivor back into the paragraph aloud. 5) Keep the phrasing that sounds like the same writer throughout.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-35223e1d03fbc7ef', 'act-english', 's-rhet', 4, 'At a mid-century animation studio, no scene belonged to a single artist. Story artists pitched gags, layout crews staged the action, and animators passed rough scenes to assistants for cleanup. A finished shot might carry the fingerprints of forty people.', 'The writer wants to add a sentence that further emphasizes the paragraph''s focus on teamwork across the studio''s departments. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Some directors kept private sketchbooks that no colleague ever saw.","letter":"A"},{"is_no_change":false,"label":"The cafeteria, even at peak production, served lunch in three daily shifts.","letter":"B"},{"is_no_change":false,"label":"Even the music staff joined early story meetings, matching tunes to unfinished scenes.","letter":"C"},{"is_no_change":false,"label":"One animator skipped story meetings and drew his most famous scenes alone over a single weekend.","letter":"D"}]', 'C', '{"A":"Private sketchbooks illustrate secrecy, undercutting the teamwork theme.","B":"Cafeteria logistics show the studio''s size, not collaboration on the work itself.","C":"Another department pitching in on story work is one more instance of cross-department teamwork — exactly what the goal asks for.","D":"A solo triumph contradicts the paragraph''s claim that no scene belonged to one artist."}', 'The addition must supply **more evidence of the stated focus** — cooperation across departments — and only this detail does.', 'The cafeteria detail is set inside the studio, so it feels on-topic even though it says nothing about shared work.', '1) Name the paragraph''s focus in a phrase. 2) For each candidate, ask: does it add another example of that focus? 3) Strike details that are merely nearby in setting or that cut against the focus. 4) Choose the remaining example.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3b4257249a96ea7b', 'act-english', 's-rhet', 4, 'A blanket of rockfall debris does strange things to the ice beneath it. A thin dusting of grit darkens the surface and speeds melting. A thick rubble layer, by contrast, works like insulation and shields the ice from the sun.', 'The writer wants to add a sentence that develops the paragraph''s focus on how debris depth changes the way glaciers melt. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Debris-covered glaciers are especially common in the Himalaya, where trekkers often cross them.","letter":"A"},{"is_no_change":false,"label":"Between those extremes lies a critical thickness at which the debris neither hastens nor slows the loss of ice.","letter":"B"},{"is_no_change":false,"label":"Rockfall has also been known to crush monitoring gear anchored to the ice.","letter":"C"},{"is_no_change":false,"label":"Some debris layers contain pollen that helps scientists date past avalanches.","letter":"D"}]', 'B', '{"A":"Geographic trivia about where such glaciers occur ignores the depth-and-melt relationship (shared topic, wrong question).","B":"It completes the spectrum the paragraph sets up, adding the pivot point where the thin and thick effects cancel.","C":"Damaged equipment is a hazard story, not a point about how depth changes melting (add_offtopic).","D":"Pollen dating serves a different scientific question and drops the melt thread entirely (interesting but irrelevant)."}', 'It **extends the paragraph''s own contrast** — thin speeds melt, thick shields it — by supplying the pivot point in the middle.', 'The Himalaya sentence stays on the topic of debris-covered glaciers, so it feels relevant even though it abandons the melt question.', '1) Name the paragraph''s focus as a question it is answering (how does debris depth change melting?). 2) For each option, ask: does it answer that same question? 3) Strike options that merely share vocabulary or setting. 4) Keep the one that pushes the paragraph''s specific line of thought forward.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3baac6ac30fcb3f6', 'act-english', 's-rhet', 4, '[1] On logging railroads, geared locomotives crept up grades twice as steep as any main line would allow. [2] Instead of driving the wheels directly, their pistons spun a shaft that geared the power down, trading speed for grip. [3] Lumber camps of that era also kept teams of oxen, which dragged felled trunks to the loading decks. [4] Because every axle was powered, a geared engine could crawl over rough temporary track that would have derailed an ordinary locomotive.', 'The writer wants the paragraph to stay focused on how geared locomotives mastered steep, rough track. Which sentence should be deleted because it strays from that focus?', '[{"is_no_change":false,"label":"Sentence 1","letter":"A"},{"is_no_change":false,"label":"Sentence 2","letter":"B"},{"is_no_change":false,"label":"Sentence 3","letter":"C"},{"is_no_change":false,"label":"Sentence 4","letter":"D"}]', 'C', '{"A":"Sentence 1 announces the exact focus — geared engines on steep grades — so it must stay.","B":"Sentence 2 explains the gearing that makes the climbing possible, directly serving the focus.","C":"Correct: oxen dragging trunks concern camp logistics, not how the locomotives handled difficult track.","D":"Sentence 4 shows the engines conquering rough track, the second half of the stated focus."}', 'Only the oxen sentence abandons the **locomotives** for an unrelated camp activity.', 'Sentence 4 tempts readers who feel the paragraph is complete once the mechanism is explained, though it extends the stated focus.', '1) Write the stated focus at the top. 2) For each sentence, note its subject in three words. 3) Mark any sentence whose subject is not the focus. 4) Confirm the paragraph still flows once the marked sentence is removed.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3ca9375e04c8d719', 'act-english', 's-rhet', 4, 'At the cheese maker''s stand, wheels of aged gouda <u>perfume the aisle with a nutty, caramel-like sweetness</u> that stops shoppers mid-stride.', 'The writer wants to emphasize the sensory experience of walking past the cheese maker''s stand. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"are offered for purchase in several convenient sizes","letter":"B"},{"is_no_change":false,"label":"have been aged in the shop''s cellar for at least twelve months","letter":"C"},{"is_no_change":false,"label":"tend to be quite popular with regular customers","letter":"D"}]', 'A', '{"A":"Correct — smell-and-taste imagery delivers exactly the sensory emphasis the writer wants.","B":"Supplies retail logistics with no appeal to any sense (goal_wrong_emphasis).","C":"Gives specific production background, but facts about aging inform rather than immerse (goal_factual_not_sensory).","D":"Offers vague general approval with no perceivable detail (goal_vague_praise)."}', 'Only this version puts a **sense impression** — an aroma a passerby can experience — on the page.', 'The cellar-aging detail sounds atmospheric and specific, so students mistake concrete information for sensory description.', '1) Restate the writer''s goal in your own words (make the reader smell, taste, hear, see, or feel). 2) For each option, name the sense it engages, if any. 3) Strike options that inform, evaluate, or advertise without engaging a sense. 4) Choose the option with genuine sensory detail. 5) Confirm it still fits the sentence grammatically.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3d2bc20b01541d50', 'act-english', 's-rhet', 4, 'Down to her final five minutes, Anaya <u>watched</u> the tangled position, hunting for the one move that might save her.', 'The writer wants to emphasize how intensely Anaya searched the position for a saving idea. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"examined","letter":"B"},{"is_no_change":false,"label":"scrutinized","letter":"C"},{"is_no_change":false,"label":"observed","letter":"D"}]', 'C', '{"A":"''watched'' is emotionally flat, reporting mere looking rather than the strained, effortful search the goal demands.","B":"''examined'' is studious but temperate — a calm, clinical word that misses the intensity the writer wants.","C":"It conveys close, critical, effortful inspection, matching the stated goal of emphasizing intensity.","D":"''observed'' casts Anaya as a detached bystander, the opposite of a player straining for a save."}', 'The goal demands the verb conveying the most **intense**, effortful inspection of the position.', '''examined'' tempts because it sounds appropriately studious, yet it stays clinical and calm rather than intense.', '1) Restate the writer''s goal in one word (here: intensity). 2) Rank each verb by how strongly it conveys that quality. 3) Eliminate verbs that are neutral, detached, or merely accurate. 4) Pick the survivor and reread the sentence to confirm the emphasis lands.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3ebc86cba59b2d34', 'act-english', 's-rhet', 4, 'In 1934, the new stainless-steel streamliner <u>hurtled</u> across the prairie, holding a pace no steam-hauled schedule had ever sustained.', 'The writer wants to emphasize the startling speed of the streamliner as vividly as possible. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"moved","letter":"B"},{"is_no_change":false,"label":"proceeded","letter":"C"},{"is_no_change":false,"label":"made its way","letter":"D"}]', 'A', '{"A":"Correct: the verb delivers force and velocity, giving the reader a vivid sense of startling speed.","B":"''Moved'' is grammatical but generic, conveying no particular speed at all.","C":"''Proceeded'' sounds procedural and unhurried, working against the stated goal.","D":"''Made its way'' suggests slow, careful progress — the opposite of startling speed."}', 'Only the original verb carries the **vivid, forceful motion** the writer''s goal demands.', '''Proceeded'' feels appropriately formal for historical writing, so students choose polish over the stated goal.', '1) Underline the goal words in the stem. 2) For each option, name the mental picture the verb paints. 3) Eliminate any verb that is neutral, slower, or calmer than the goal requires. 4) Choose the option whose connotation matches the goal exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4151975170ae8031', 'act-english', 's-rhet', 4, 'Collectors often find hairline cracks spidering across the once-glossy cabinets of 1930s table radios. The damage rarely comes from rough handling; even sets stored carefully in closets for decades develop the same fine fractures. The explanation lies in the material itself.', 'The writer wants to add a sentence here that explains why Bakelite cabinets crack even when carefully stored. Which choice provides information most relevant to that purpose?', '[{"is_no_change":false,"label":"Bakelite was named for Leo Baekeland, the Belgian-born chemist who patented it in 1909.","letter":"A"},{"is_no_change":false,"label":"Some collectors prefer wooden cabinets, which can be refinished with ordinary tools.","letter":"B"},{"is_no_change":false,"label":"As Bakelite ages, it keeps curing, and the slow shrinkage stresses its molded corners.","letter":"C"},{"is_no_change":false,"label":"Bakelite also turned up in telephone housings, costume jewelry, and billiard balls.","letter":"D"}]', 'C', '{"A":"Origin trivia about the inventor answers a history question, not the promised why.","B":"A preference for wooden cabinets swaps the subject and explains nothing about the plastic''s behavior.","C":"Correct: it supplies the internal mechanism that produces cracks even in carefully stored sets.","D":"A catalog of other products shows versatility but gives no cause for the fractures."}', 'The paragraph promises a cause inside the material, so the relevant addition is the one that supplies that **mechanism**.', 'The inventor fact feels authoritative and on-brand, so students mistake background information for explanation.', '1) Read the sentence before the insertion point and name the question it raises. 2) Demand that the added sentence answer exactly that question. 3) Eliminate options that give history, comparisons, or lists of uses. 4) Keep the option describing what physically happens. 5) Reread the paragraph to confirm the promise is paid off.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-49ef4a599004b6c4', 'act-english', 's-rhet', 4, 'The eulogy remembered how, in a crowded room, her laughter had always been <u>loud</u>, the first sound anyone noticed and the last they forgot.', 'The writer wants a description that is affectionate rather than critical. Which choice is best?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"blaring","letter":"B"},{"is_no_change":false,"label":"unmistakable","letter":"C"},{"is_no_change":false,"label":"noisy","letter":"D"}]', 'C', '{"A":"''Loud'' is neutral-to-negative and can read as a complaint in a tribute.","B":"''Blaring'' is harshly negative, the opposite of affection.","C":"''Unmistakable'' turns the volume into something distinctive and cherished — affectionate, as intended.","D":"''Noisy'' carries an annoyed connotation."}', 'The goal is **affection**, and ''unmistakable'' recasts the loudness as a beloved, singular trait.', '''Loud'' is literally accurate, so it seems safe — but in a eulogy it risks sounding like criticism.', 'Match connotation to the intended feeling; in a tribute, choose the warmly positive word.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4a9121cc56208e8a', 'act-english', 's-rhet', 4, 'Some marathoners deliberately train in the hottest part of the day to prepare for warm-weather races. During one August buildup, Keiko ran her midday miles in a long-sleeve shirt to mimic race-day humidity. Coaches caution, though, that heat sessions should stay short and be followed by careful rehydration.', 'The writer is considering deleting the second sentence. The writer wants the paragraph''s opening claim to be supported rather than merely stated. Given that goal, should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it supplies a transition into the paragraph''s closing warning.","letter":"A"},{"is_no_change":false,"label":"Kept, because it illustrates the heat training named in the opening claim.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it contradicts the paragraph''s warning about heat training.","letter":"C"},{"is_no_change":false,"label":"Deleted, because it repeats information named in the opening claim.","letter":"D"}]', 'B', '{"A":"Right verdict, wrong function: the closing caution follows from the opening practice directly, not from Keiko''s story (keep_wrong_function).","B":"Correct: Keiko''s midday, long-sleeve miles are the concrete case that supports the opening generalization, exactly what the writer wants.","C":"Claims a conflict that does not exist; one runner''s heat session is compatible with advice to keep such sessions short (delete_false_contradiction).","D":"Mistakes support for repetition; the sentence adds new particulars — August, midday miles, the shirt — found nowhere in the opening (delete_sees_redundancy)."}', 'The sentence turns a general claim into a **supported** one by supplying a concrete case, which is precisely the writer''s stated goal.', 'The repetition reason tempts students because the sentence restates the same practice in more detail, which can feel like saying it twice.', '1) State the writer''s goal for the paragraph. 2) Identify what the sentence in question actually does: evidence, transition, repetition, or digression. 3) Test each reason against the text — could you point to proof? 4) Match verdict and reason: keep only if the true function serves the goal. 5) Pick the pair in which both halves are accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4ad4aa07b74f635b', 'act-english', 's-rhet', 4, 'Film scholars once treated cartoons as disposable entertainment; today, most <u>think animation is a pretty big deal</u> and analyze it alongside live-action classics.', 'Which choice best maintains the tone established in the rest of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"regard animation as a serious subject of study","letter":"B"},{"is_no_change":false,"label":"are totally obsessed with animation","letter":"C"},{"is_no_change":false,"label":"figure animation is worth a look","letter":"D"}]', 'B', '{"A":"''A pretty big deal'' is conversational slang that clashes with the sentence''s academic diction.","B":"This phrasing matches the formal, scholarly register of ''disposable entertainment'' and ''analyze ... classics.''","C":"''Totally obsessed'' is hyperbolic fan-speak, not a description of scholars'' professional stance.","D":"''Figure'' and ''worth a look'' are breezy colloquialisms that deflate the sentence''s formality."}', 'The sentence''s scholarly frame demands **formal register**, which only this option sustains.', '''A pretty big deal'' states the right idea, so students keep it despite the register clash.', '1) Sample the passage''s diction: list two or three of its formal (or informal) words. 2) Label each option''s register. 3) Discard options whose register differs from the sample, even if the meaning fits. 4) Confirm the survivor also preserves the intended meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4b2651a209bf761f', 'act-english', 's-rhet', 4, 'The travel essay lingered on the market at dawn, where vendors <u>put out</u> pyramids of saffron, mint, and blood oranges under striped awnings.', 'The writer wants a verb that makes the vendors'' display feel vivid and deliberate. Which choice is best?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"arranged","letter":"B"},{"is_no_change":false,"label":"had","letter":"C"},{"is_no_change":false,"label":"set down","letter":"D"}]', 'B', '{"A":"''Put out'' is bland and suggests no care or artistry.","B":"''Arranged'' implies deliberate, artful placement, matching the vivid pyramids of produce.","C":"''Had'' is the flattest possible verb and conveys nothing about the display.","D":"''Set down'' suggests dropping items casually, the opposite of a careful display."}', 'The goal is a sense of **deliberate artistry**, and ''arranged'' names purposeful placement.', '''Set down'' is more specific than ''put out'', so it looks like the vivid choice — but it implies carelessness.', 'Pick the verb whose connotation supplies the exact impression the stem requests.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-598646ae60d50d80', 'act-english', 's-rhet', 4, 'When the red light blinked on, the announcer leaned toward the microphone and <u>let each syllable land like a struck bell</u>.', 'The writer wants to convey the announcer''s vocal precision through a vivid, concrete image. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"spoke with a great deal of clarity and self-control","letter":"B"},{"is_no_change":false,"label":"pronounced his words in an impressively professional manner","letter":"C"},{"is_no_change":false,"label":"made sure everything he said could be clearly understood by all","letter":"D"}]', 'A', '{"A":"Correct: the simile gives a concrete, audible image of each syllable''s precision.","B":"Abstract nouns name the announcer''s virtues without letting the reader see or hear anything.","C":"''Impressively professional'' is an evaluation that tells rather than shows.","D":"This wordy option shifts to the audience''s comprehension and carries no image of the delivery itself."}', 'The original simile is the only option that renders precision as a **sensory image** rather than a label or a judgment.', '''Clarity and self-control'' sounds accurate and mature, so students mistake naming the quality for depicting it.', '1) Restate the stem''s goal in your own words (a vivid, concrete picture of precision). 2) For each option, ask: can I see or hear something specific? 3) Strike options that only evaluate, summarize, or describe effects on others. 4) Keep the option that plants a sensory image. 5) Reread it in context to confirm fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5e7da4df3df864a4', 'act-english', 's-rhet', 4, 'During a population explosion, a swarm of crown-of-thorns starfish can <u>eat</u> a healthy reef faster than it can regrow, leaving bleached skeletons where vivid coral stood only weeks before.', 'The writer wants to emphasize how voraciously and destructively the starfish consume the reef. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"consume","letter":"B"},{"is_no_change":false,"label":"devour","letter":"C"},{"is_no_change":false,"label":"nibble","letter":"D"}]', 'C', '{"A":"''Eat'' is accurate but flat, conveying none of the destructive intensity the writer wants to stress (misconception: neutral_word_misses_goal).","B":"''Consume'' is precise but clinical, adding no sense of ferocity or speed (misconception: formal_but_flat).","C":"''Devour'' carries the greedy, rapid destruction the writer wants to emphasize.","D":"''Nibble'' suggests dainty, harmless eating — the opposite of the intended emphasis (misconception: opposite_connotation)."}', 'The chosen verb must carry a connotation of **greedy, rapid** eating that matches the goal of stressing destruction.', '''Eat'' is the plain, safe verb, so students keep it without weighing the emphasis the stem asks for.', '1) Reread the stated goal and name the exact impression the word must create. 2) For each option, describe its connotation, not just its dictionary meaning. 3) Discard words that are neutral, clinical, or opposite in feeling. 4) Keep the word whose connotation matches the goal most vividly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-64359f35eb3a32c2', 'act-english', 's-rhet', 4, 'The obituary honored the volunteer firefighter, noting that for thirty years he had <u>done stuff</u> for a town that never once had to ask.', 'Which choice best matches the dignified, respectful tone the passage calls for?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"given of himself","letter":"B"},{"is_no_change":false,"label":"pitched in","letter":"C"},{"is_no_change":false,"label":"lent a hand","letter":"D"}]', 'B', '{"A":"''Done stuff'' is casual to the point of disrespect in an obituary.","B":"''Given of himself'' is elevated and reverent, fitting a tribute to decades of service.","C":"''Pitched in'' is warm but too colloquial for the solemn register.","D":"''Lent a hand'' is friendly and informal, again below the required dignity."}', 'The context is an **obituary**, whose reverent register demands elevated diction like ''given of himself''.', '''Pitched in'' and ''lent a hand'' are positive, so they feel appropriate until you weigh the solemn setting.', 'Let the genre set the register — a tribute or eulogy calls for formal, dignified wording.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-65b84fa6f34a103c', 'act-english', 's-rhet', 4, 'Every Saturday, a small stage near the market''s entrance hosts local musicians. The market pays each act a modest stipend funded by vendor dues. Regulars say the live music is what separates a morning at the market from an errand at the grocery store.', 'The writer wants to add a sentence that maintains the paragraph''s focus on the market''s live-music program. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"A chalkboard near the entrance lists each day''s produce prices.","letter":"A"},{"is_no_change":false,"label":"Stipends are also common in industries such as publishing.","letter":"B"},{"is_no_change":false,"label":"One of the musicians recently moved to the area from out of state.","letter":"C"},{"is_no_change":false,"label":"This season, student musicians will join the Saturday lineup for a second afternoon set.","letter":"D"}]', 'D', '{"A":"Shares a location with the stage but concerns prices, not music (add_shared_scenery).","B":"Chases the word ''stipend'' into unrelated industries, abandoning the topic (add_word_association).","C":"Mentions a musician but offers personal biography rather than the program (add_biographical_drift).","D":"Correct — it develops the music program itself with a planned expansion of its performances."}', 'Only this sentence **develops** the music program itself — its performers and its schedule — rather than a nearby object, a stray word, or a personal story.', 'The musician''s relocation mentions a performer, so students accept biography as if it were information about the program.', '1) Name the paragraph''s declared focus in a short phrase. 2) For each option, ask: does this sentence give new information about that focus? 3) Reject options linked only by location, by a repeated word, or by a person''s unrelated life details. 4) Choose the option that advances the focus. 5) Reread the paragraph with it inserted to confirm cohesion.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-66ffedcdd57fec1a', 'act-english', 's-rhet', 4, 'Passage I — Learning to Sail — The summer I turned fourteen, my uncle teached me to sail. His old wooden boat, named the <em>Osprey</em>, had belonged to my grandfather. On our first morning out, the wind was calm, and we drifted lazily across the bay. However, by noon a stiff breeze had risen, and the <em>Osprey</em> leaned hard against it. My uncle showed me how to read the wind by watching the surface of the water. "Dark patches mean gusts," he said, <u>"and you must be ready."</u> At first I was nervous, gripping the lines too tightly. But after an hour, I begun to relax. By the end of the day, I could steer the boat myself. Although I still had much to learn, I felt a new confidence. Sailing, I realized, was not about controlling the wind but about working with it.', 'Which underlined choice best supports the uncle''s warning about sudden gusts?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"\"and the ocean is very large.\"","letter":"B"},{"is_no_change":false,"label":"\"and sailing is a popular hobby.\"","letter":"C"},{"is_no_change":false,"label":"\"and boats are made of wood.\"","letter":"D"}]', 'A', '{"A":"Original keeps the practical, instructive voice; others are off-topic. (Form-805 tone item.)","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Original keeps the practical, instructive voice; others are off-topic. (Form-805 tone item.)', 'The original can read smoothly until you apply the rule.', 'Rule focus: Production (tone/style)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b31e314476e3a2c', 'act-english', 's-rhet', 4, 'My grandfather kept the bakery''s ledgers in a careful, slanting hand, noting each day''s sales beside remarks on the weather. When the entries thinned during the drought years, <u>he got pretty worked up about</u> the sugar orders.', 'Which choice best maintains the essay''s tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"he was devastated beyond all consolation by","letter":"B"},{"is_no_change":false,"label":"he stressed out over","letter":"C"},{"is_no_change":false,"label":"he grew anxious about","letter":"D"}]', 'D', '{"A":"''Got pretty worked up'' is conversational slang that clashes with the essay''s measured, reflective voice (tone_colloquial).","B":"''Devastated beyond all consolation'' is melodramatic overstatement, exceeding the essay''s quiet restraint (tone_overwrought).","C":"''Stressed out over'' is casual idiom, too informal for the reflective register (tone_casual_idiom).","D":"Correct — plain, restrained wording that matches the essay''s careful, understated voice."}', 'The essay''s voice is quiet and precise, so the revision must stay **measured** — concerned but neither slangy nor theatrical.', 'The melodramatic option sounds ''formal'' because of its elevated vocabulary, which masks its excess.', '1) Read two or three surrounding sentences and label the voice (formal? conversational? restrained? playful?). 2) Label each option''s register the same way. 3) Eliminate options that are more casual OR more dramatic than the passage. 4) Choose the register twin.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7264298ec2d1ce19', 'act-english', 's-rhet', 4, 'The market commission''s annual report praised vendors for their professionalism and cleanliness; it noted, however, that weekend parking <u>was a total mess</u> and recommended hiring a lot attendant.', 'Which choice best maintains the tone established elsewhere in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had gotten seriously out of hand","letter":"B"},{"is_no_change":false,"label":"was, frankly, a headache for everybody","letter":"C"},{"is_no_change":false,"label":"remained disorganized","letter":"D"}]', 'D', '{"A":"The slangy intensifier ''total mess'' clashes with the report''s formal register (tone_slang).","B":"''Out of hand'' is a conversational idiom that undercuts official prose (tone_colloquial_idiom).","C":"The chatty aside ''frankly'' and informal ''headache'' address readers personally, unlike a formal report (tone_chatty_interjection).","D":"Correct — measured, formal diction consistent with an official commission report."}', 'An official report calls for **measured**, formal diction, which this even-toned phrasing supplies.', '''A total mess'' states the problem vividly and briefly, so it feels efficient rather than slangy.', '1) Identify the document type and its register from surrounding wording (''annual report,'' ''recommended''). 2) Label each option''s register: formal, neutral, conversational, slang. 3) Strike options with idioms, slang, or chatty asides. 4) Choose the option matching the established register. 5) Reread the full sentence to confirm one consistent voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7314e4b5cd3b3b70', 'act-english', 's-rhet', 4, 'Aldus Manutius introduced italic type in 1501 so that more words could fit on a small page. His pocket-sized editions of the classics sold briskly across Europe. Within two years, a rival Lyonnaise workshop was counterfeiting the slanted letters so faithfully that Aldus petitioned the Venetian senate for protection.', 'The writer is considering deleting the final sentence. Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it shows that italic type quickly spread to readers in other countries.","letter":"A"},{"is_no_change":false,"label":"Kept, because the rival''s counterfeiting demonstrates how commercially valuable the new type had become.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it repeats the earlier point that the pocket editions sold briskly.","letter":"C"},{"is_no_change":false,"label":"Deleted, because it interrupts the paragraph''s account of how italic letters were designed.","letter":"D"}]', 'B', '{"A":"The rival was indeed abroad, but the sentence''s point is imitation, not geographic spread — the previous sentence already covers sales across Europe.","B":"Counterfeiting is costly to attempt, so the rival''s effort — and Aldus''s plea for protection — proves the invention''s commercial worth.","C":"Brisk sales and criminal imitation are different evidence; the sentence adds escalation, not repetition.","D":"The paragraph traces the invention''s fortunes, not its design process, so no such account is interrupted."}', 'The final sentence supplies **evidence of worth** — imitation and a plea for protection — that no earlier sentence provides.', 'The ''spread to other countries'' reading tempts because Lyon is indeed abroad, but that mistakes a detail of the sentence for its purpose.', '1) State what the sentence in question uniquely contributes. 2) Ask whether any other sentence already does that job. 3) If the contribution is unique and on-topic, keep it. 4) Match your verdict to the justification that names the sentence''s actual role. 5) Re-read the paragraph both with and without the sentence to confirm.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7d2252f983ef231b', 'act-english', 's-rhet', 4, 'In her morning forecast discussion, the meteorologist <u>conceded</u> that the overnight model runs had diverged, then laid out why she still favored the colder solution.', 'The writer wants to show that the meteorologist honestly acknowledged a point that weakened her own forecast. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"announced","letter":"B"},{"is_no_change":false,"label":"noted","letter":"C"},{"is_no_change":false,"label":"lamented","letter":"D"}]', 'A', '{"A":"Correct: the original verb means admitting something reluctantly true that cuts against one''s own position — precisely the stated goal.","B":"''Announced'' is a neutral public statement, carrying no sense that the point works against her (misconception: formal tone equals the right nuance).","C":"''Noted'' records the fact without any admission against interest (misconception: any verb of saying will do).","D":"''Lamented'' adds grief, overshooting honesty into mourning (misconception: stronger emotion means stronger writing)."}', 'The original verb uniquely carries **admission against one''s own position**, matching every part of the goal.', '''Noted'' sounds appropriately calm and professional, hiding that it drops the crucial sense of admitting a weakness.', '1) Turn the goal into a checklist (here: honest + acknowledges + hurts her own case). 2) Test each verb against every box, not just one. 3) Reject verbs that are neutral reports. 4) Reject verbs that add feelings the goal never mentioned. 5) Keep the verb that checks every box with nothing extra.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7f4bfe1e8bc14bfd', 'act-english', 's-rhet', 4, '[1] Each February, commercial beekeepers truck millions of hives to California''s almond orchards. [2] The trees bloom for only a few weeks, and every blossom must be visited by a bee to set a nut. [3] Growers pay rental fees that now form a major share of many beekeepers'' yearly income.', 'The writer is considering adding the following sentence after Sentence 2: "Wild pollinators alone are far too few to service orchards that stretch for miles." Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it explains why growers depend on rented hives rather than on native bees.","letter":"A"},{"is_no_change":false,"label":"Yes, because it adds data about the growers'' rental income.","letter":"B"},{"is_no_change":false,"label":"No, because it merely restates the need to rent colonies mentioned elsewhere.","letter":"C"},{"is_no_change":false,"label":"No, because the length of the bloom is not relevant to the paragraph.","letter":"D"}]', 'A', '{"A":"Correct: it supplies the missing reason the orchards depend on trucked-in hives, connecting the bloom''s demand to the rental market described in Sentence 3.","B":"The proposed sentence offers no numbers or figures, so it adds no data at all.","C":"The paragraph never states why wild bees fall short, so the sentence adds a reason rather than repeating one.","D":"The short bloom is exactly what makes rented hives necessary, so it is central to the paragraph, not irrelevant."}', 'A sentence earns a place when it fills a **logical gap**, and this one explains why paid pollination is needed at all.', 'Because the paragraph flows without it, students assume the sentence is optional and overlook the causal link it supplies between the bloom and the rental market.', '1) Trace the paragraph''s logic and look for a step that is assumed but never stated. 2) Ask whether the proposed sentence supplies that missing step. 3) If it fills a real gap in reasoning, adding it strengthens the paragraph. 4) Match the reason to what the sentence actually contributes, not to a fact it lacks.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-81ca6aaf052401ea', 'act-english', 's-rhet', 4, 'The commission''s report praised the county''s rigorous maintenance program. Crews repaint the steel span every seven years, a schedule that <u>totally shuts down rust before it can mess up</u> the load-bearing plates.', 'Which choice is most consistent with the tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"prevents corrosion from weakening","letter":"B"},{"is_no_change":false,"label":"kicks rust to the curb before it wrecks","letter":"C"},{"is_no_change":false,"label":"is super effective at stopping rust on","letter":"D"}]', 'B', '{"A":"''Totally'' and ''mess up'' are casual conversation, clashing with the formal report language around them (misconception: tone_casual_kept).","B":"Uses measured, technical diction that matches ''commission,'' ''rigorous,'' and ''maintenance program.''","C":"A street idiom is even more colloquial than the original (misconception: tone_idiom_swap).","D":"''Super'' is a chatty intensifier and ''stopping rust on'' is vague, so the register still fails (misconception: tone_partial_fix)."}', 'Tone must stay **consistent**: a passage built on formal report language needs a precise, professional description of the rust problem.', 'The ''super effective'' version drops the most glaring slang, so students accept it without noticing the casual intensifier that remains.', '1) Sample the passage''s diction and label its register (formal, neutral, casual). 2) Read each option and flag slang, idioms, and chatty intensifiers. 3) Eliminate every option whose register differs from the passage. 4) Confirm the survivor also keeps the sentence''s exact meaning. 5) Reread the paragraph with the choice inserted.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-85de6737719eec34', 'act-english', 's-rhet', 4, 'In its annual report, the advisory panel reviewed the projected costs of relocating the field station and <u>was seriously bummed out by</u> the figures.', 'Which choice best maintains the formal style established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was troubled by","letter":"B"},{"is_no_change":false,"label":"was sort of down about","letter":"C"},{"is_no_change":false,"label":"could not even deal with","letter":"D"}]', 'B', '{"A":"''Bummed out'' is slang, jarring against ''annual report'' and ''projected costs'' (register clash).","B":"A measured, formal verb phrase that matches the report''s register.","C":"''Sort of down about'' is casual hedging that deflates the formal context (colloquial hedge).","D":"''Could not even deal with'' imports conversational exaggeration into a formal report (spoken-register idiom)."}', 'The sentence''s **formal register** (''annual report,'' ''advisory panel'') requires equally formal diction.', '''Bummed out'' conveys the right meaning, so students who check meaning but not register keep it.', '1) Scan the sentence for register clues (titles, documents, technical terms). 2) Label the passage formal or casual. 3) Label each option the same way. 4) Eliminate every mismatch, even if the meaning fits. 5) Choose the option whose register matches the clues.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8d93d05c6965bbd2', 'act-english', 's-rhet', 4, 'Weeknight traffic on the largest chess servers now peaks just as American high schools let out. In a survey of one large district, half the varsity roster reported playing at least ten online blitz games a day.', 'The writer wants to add a sentence that supports the paragraph''s focus on why online blitz appeals to teenagers. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"A full game fits into the gap between homework assignments, and a rematch is always one tap away.","letter":"A"},{"is_no_change":false,"label":"Several veteran grandmasters have publicly refused to play blitz online.","letter":"B"},{"is_no_change":false,"label":"The same servers also offer correspondence games that unfold over several weeks.","letter":"C"},{"is_no_change":false,"label":"Blitz thrived in city parks and coffeehouses long before the internet existed.","letter":"D"}]', 'A', '{"A":"It supplies concrete reasons for the appeal — speed and instant rematches — directly supporting the paragraph''s focus.","B":"Grandmasters opting out says nothing about teenagers and, if anything, points away from the appeal.","C":"A slower format on the same servers is a catalog detail that never explains why fast games attract teens.","D":"Pre-internet history is on-topic but answers no question about what draws today''s students."}', 'It gives a concrete **reason for the appeal** — games that fit teenagers'' pockets of free time — which is exactly what the focus needs.', 'The historical note tempts because it is genuinely about blitz, hiding that it explains nothing about modern teenagers'' attraction to it.', '1) Write the paragraph''s focus as a question (''Why does online blitz appeal to teens?''). 2) Test each option: does it answer that exact question? 3) Reject details that are merely on the same topic without answering the question. 4) Confirm the survivor adds a reason, not just a fact.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-901a1947651f5a8e', 'act-english', 's-rhet', 4, 'In the hour before dawn, the marsh holds its breath. Then a lone sedge wren begins to sing, and one by one the reeds <u>get noisy with</u> answering voices.', 'Which choice best maintains the tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"crank up with","letter":"B"},{"is_no_change":false,"label":"come alive with","letter":"C"},{"is_no_change":false,"label":"commence vocalization with","letter":"D"}]', 'C', '{"A":"''Get noisy with'' is flat and faintly negative, clashing with the hushed, lyrical mood.","B":"''Crank up with'' is slangy and mechanical, breaking the quiet reverence of the scene.","C":"Correct: it extends the passage''s gentle personification, matching ''the marsh holds its breath.''","D":"Stiff, clinical phrasing trades the passage''s lyricism for lab-report language."}', 'The passage personifies the marsh tenderly, so the phrase must carry the same **lyrical** warmth.', '''Commence vocalization with'' sounds elevated, and students often equate formality with good style even when it clashes with a poetic voice.', '1) Name the passage''s tone from its strongest image. 2) Test each option''s register: slang, neutral, clinical, or lyrical. 3) Eliminate anything that breaks the spell in either direction — too casual or too technical. 4) Keep the phrase that sounds like the same writer throughout.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-91118e4e586e7999', 'act-english', 's-rhet', 4, 'For twenty years after the tannery closed, Grafton Pier sat behind a chain-link fence while the city argued over its future. Preservationists wanted the timber warehouse restored; the parks department wanted open lawn to the waterline; a hotel group promised tax revenue. The compromise that finally passed a citywide vote — a public promenade wrapping a smaller, restored warehouse — satisfied no faction completely, which several council members now cite as proof it was the right call.', 'Suppose the writer''s goal had been to describe the engineering challenges of building on an aging pier. Would this paragraph accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it explains how the restored warehouse was anchored to the pier.","letter":"A"},{"is_no_change":false,"label":"Yes, because the promenade it describes was built out over the water.","letter":"B"},{"is_no_change":false,"label":"No, because it focuses on the community''s fight over the site rather than on how anything was built.","letter":"C"},{"is_no_change":false,"label":"No, because the paragraph discusses a warehouse rather than a pier.","letter":"D"}]', 'C', '{"A":"The paragraph never explains any anchoring or construction method — this reason invents content.","B":"A structure''s location over water does not mean the paragraph covers the difficulties of building there — the misconception that a surface link satisfies the goal.","C":"Every sentence concerns the political contest over the pier''s future, not technical challenges, so the paragraph fails the supposed goal.","D":"The verdict is right but the reason misreads the passage: the pier and its redevelopment are the paragraph''s clear subject."}', 'The paragraph''s content is **political, not technical**, so it cannot serve an engineering-focused purpose.', 'Because the setting involves water and construction, the reason about building over the water feels plausible without checking what the sentences actually develop.', '1) Restate the supposed goal precisely. 2) List what each sentence of the paragraph actually develops. 3) Judge the verdict: does the content match the goal? 4) Among options with the correct verdict, keep only the reason that accurately describes the paragraph. 5) Reject reasons that invent, misread, or rely on surface connections.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-94a96370062ca532', 'act-english', 's-rhet', 4, 'For its first full-length feature, the studio''s artists <u>produced</u> well over a million preliminary sketches before a single cel was painted.', 'The writer wants to emphasize the painstaking care the artists invested in the drawings. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"meticulously refined","letter":"B"},{"is_no_change":false,"label":"cranked out","letter":"C"},{"is_no_change":false,"label":"eventually completed","letter":"D"}]', 'B', '{"A":"''Produced'' is accurate but neutral; it records output without conveying any care.","B":"''Meticulously refined'' dramatizes deliberate, careful craftsmanship, directly serving the stated goal.","C":"''Cranked out'' implies fast, mechanical output — the opposite of painstaking care.","D":"''Eventually completed'' stresses elapsed time, not the quality of attention."}', 'The goal asks for **care**, and only this wording builds carefulness into the verb phrase itself.', '''Eventually completed'' hints at a long effort, which students mistake for an image of careful work.', '1) Underline the key quality in the stated goal. 2) For each option, name the connotation its verb carries. 3) Eliminate options whose connotation is neutral, opposite, or about a different quality. 4) Choose the one that embodies the goal''s exact quality.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97de1c161b9626b0', 'act-english', 's-rhet', 4, 'Fixer makes a photographic image permanent, but any fixer left behind in the paper will slowly bleach it. Prints are therefore washed for up to an hour in gently running water. Some museums store their finest prints in climate-controlled vaults. A residue test at the end of the wash confirms that the last traces of the chemical are gone.', 'The writer is considering deleting the sentence "Some museums store their finest prints in climate-controlled vaults." Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it emphasizes how valuable a fully washed print can become.","letter":"A"},{"is_no_change":false,"label":"Deleted, because it shifts the focus away from removing fixer from the print.","letter":"B"},{"is_no_change":false,"label":"Kept, because it supplies a step that belongs between the fixer wash and the residue test.","letter":"C"},{"is_no_change":false,"label":"Deleted, because the essay never explains what fixer is made of.","letter":"D"}]', 'B', '{"A":"Keeps the sentence for an unearned payoff (kept_false_implication): the paragraph never links washing to museum value, so the sentence cannot emphasize it.","B":"Correct: the paragraph traces fixer from threat to wash to residue test, and the museum aside breaks that chain.","C":"Invents a procedural role (kept_false_step): storing prints in vaults is not a stage between washing and testing.","D":"Reaches the right verdict with an irrelevant reason (deleted_wrong_reason): the paragraph''s job is removal, not chemistry, so the missing formula is beside the point."}', 'The paragraph follows one thread — getting fixer **out** of the print and proving it is gone — and the museum sentence stands outside that thread.', 'The museum sentence flatters the paragraph''s subject, so students keep it for its pleasant association with permanence and value.', '1) State the paragraph''s job in one sentence. 2) Test the candidate sentence: does it advance that job or merely sit near it? 3) If it does not advance the job, lean toward deletion. 4) Then vet the reason attached to your verdict — both the decision and its justification must be true of the text.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9879e8c22aac3eca', 'act-english', 's-rhet', 4, 'The editorial warned that ignoring the levee''s cracks was <u>not a good idea</u>, a gamble the city could not afford after two near-floods.', 'Which choice best conveys the editorial''s urgent, cautionary stance?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"reckless","letter":"B"},{"is_no_change":false,"label":"less than ideal","letter":"C"},{"is_no_change":false,"label":"unwise","letter":"D"}]', 'B', '{"A":"''Not a good idea'' is mild and conversational, far too weak for a warning.","B":"''Reckless'' conveys real danger and blame, matching the urgent ''gamble the city could not afford''.","C":"''Less than ideal'' understates the risk almost comically.","D":"''Unwise'' is a step up but still restrained for the alarm the passage sounds."}', 'The stance is **urgent warning**, and ''reckless'' carries the force of real, blameworthy danger.', '''Unwise'' sounds more formal than the original, so it feels sufficient — but it lacks the alarm.', 'Calibrate intensity to the writer''s stance; a cautionary editorial needs a word that signals genuine risk.', 'underlined-span-mc', '''Unwise'' sounds more formal than the original, so it feels sufficient…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a0058c52245d7aea', 'act-english', 's-rhet', 4, 'Acoustic flow monitors stand watch along the river valleys that drain the volcano''s upper slopes. When a lahar — a fast-moving slurry of ash and meltwater — sweeps down a channel, its ground vibrations trigger an automatic alarm. One member of the team also leads popular weekend birdwatching hikes in the lower valley. Sirens in the towns below then give residents precious minutes to reach higher ground.', 'The writer is considering deleting the sentence about weekend birdwatching hikes. Should the sentence be deleted?', '[{"is_no_change":false,"label":"No, because it offers a detail that supports the paragraph''s claim about the alarm''s reliability.","letter":"A"},{"is_no_change":false,"label":"No, because it provides a transition between the alarm and the sirens.","letter":"B"},{"is_no_change":false,"label":"Yes, because it interrupts the description of the warning system with a detail unrelated to it.","letter":"C"},{"is_no_change":false,"label":"Yes, because the description of the warning system belongs earlier in the essay.","letter":"D"}]', 'C', '{"A":"False — a colleague''s weekend hobby says nothing about whether the alarm works.","B":"False — the sentence touches neither the alarm before it nor the sirens after it, so it bridges nothing.","C":"Correct: the hobby detail breaks the vibration-alarm-siren chain and serves no purpose in it.","D":"Votes to delete for a false reason — the problem is relevance, not the placement of the system description."}', 'The sentence is a **digression**: it halts the vibration-alarm-siren sequence with material that serves no purpose in the paragraph.', 'One wrong option also votes to delete, so students who sense the problem may grab it without vetting whether its reason describes the actual flaw.', '1) Summarize the paragraph''s through-line in one phrase. 2) Ask whether the sentence advances that line. 3) If not, it should go — but 4) verify the stated reason: it must accurately name what the sentence does to the paragraph.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a0a7e318d236dfe3', 'act-english', 's-rhet', 4, 'Hired by a major eastern railroad in 1920 as its first female engineer, Olive Dennis rode thousands of miles in ordinary coaches to study what passengers endured. She designed reclining seats, dimmable ceiling lights, and window vents that let travelers draw fresh air without a blast of cinders. Features she sketched for one railroad spread through the industry, quietly resetting what a coach ticket promised.', 'Suppose the writer''s goal had been to show how one engineer''s work changed the experience of ordinary train passengers. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it lists the official titles Dennis held during her long career.","letter":"A"},{"is_no_change":false,"label":"Yes, because it connects specific innovations Dennis designed to the comfort of everyday riders.","letter":"B"},{"is_no_change":false,"label":"No, because it concentrates on freight operations rather than on passenger service.","letter":"C"},{"is_no_change":false,"label":"No, because it describes the reactions of railroad executives instead of those of travelers.","letter":"D"}]', 'B', '{"A":"The essay succeeds, but not by listing titles — it names only one position.","B":"Correct: the essay ties Dennis''s seat, lighting, and ventilation designs directly to what passengers experienced.","C":"Freight never appears in the passage, so this reason misdescribes the essay.","D":"No executive reactions are given; the essay follows what travelers gained."}', 'The essay pairs each of Dennis''s **designs** with a passenger benefit, exactly matching the stated goal.', 'The titles option tempts readers who remember the impressive opening about her hiring and mistake it for the essay''s method.', '1) Restate the proposed goal in your own words. 2) Decide from the passage alone whether it achieves that goal — verdict first. 3) Audit each option''s reason against specific sentences. 4) Eliminate any option whose reason describes content the passage does not contain.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a18815d6d3a54b67', 'act-english', 's-rhet', 4, 'For decades, tournament games ended in frantic scrambles, players slamming pieces and punching clocks as their final seconds drained away. Digital clocks changed that by granting a small time bonus after every completed move. At this point, the writer is considering adding the following sentence: <em>"Even a player down to two seconds can survive indefinitely by moving quickly enough."</em>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it clarifies how the bonus eliminates the scrambles described earlier.","letter":"A"},{"is_no_change":false,"label":"Yes, because it proves digital clocks cost less than the analog clocks they replaced.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats a point already made earlier in the paragraph.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the paragraph''s focus to the etiquette of casual games.","letter":"D"}]', 'A', '{"A":"The sentence shows concretely how the time bonus ends the frantic scrambles, directly extending the paragraph''s point.","B":"The verdict is right, but the reason invents a price comparison the paragraph never makes.","C":"The two-second scenario is new information; nothing earlier explains what happens to a player almost out of time.","D":"The sentence stays squarely on tournament timekeeping; it mentions nothing about etiquette or casual play."}', 'The sentence **clarifies the mechanism** — how the bonus ends the scrambles — so both the verdict and the reason fit the paragraph.', 'The repetition claim tempts because the sentence circles back to the scramble idea, disguising that its two-second detail is entirely new.', '1) Decide independently whether the proposed sentence helps the paragraph''s point. 2) Check each option''s verdict against your decision. 3) Then check each reason against the passage: is it factually true, and does it describe what the sentence actually does? 4) Keep only the option where verdict and reason are both accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a24ae4a3320904d1', 'act-english', 's-rhet', 4, '<p>As the ocean absorbs more of the carbon dioxide humans release, its surface water grows slightly more acidic. That shift makes the carbonate minerals corals need for their skeletons harder to pull from the water, so corals must burn extra energy just to grow at their normal pace. With less energy to spare, they reproduce and heal more slowly.</p>', 'At this point the writer is considering adding the following sentence: ''Carbon dioxide is also the gas people breathe out with every exhale.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it reminds readers where the ocean''s carbon dioxide originally came from.","letter":"A"},{"is_no_change":false,"label":"Yes, because relating the gas to the reader''s own breathing makes the science feel more personal.","letter":"B"},{"is_no_change":false,"label":"No, because the sentence introduces an off-topic fact that strays from the paragraph''s focus on acidification.","letter":"C"},{"is_no_change":false,"label":"No, because the paragraph has already told readers how carbon dioxide enters the ocean.","letter":"D"}]', 'C', '{"A":"The added sentence doesn''t actually explain where the ocean''s carbon comes from; it just states a biological trivium, so this justification misreads it (misconception: add_false_justification).","B":"A personal connection can''t rescue a detail that derails the paragraph''s scientific argument (misconception: add_relevance_overridden_by_interest).","C":"The exhale detail is a tangent that pulls attention from the paragraph''s explanation of how acidification harms corals, so it should be left out.","D":"The paragraph never explains how carbon dioxide enters the ocean, so this reason is factually wrong (misconception: add_misreads_passage)."}', 'A sentence belongs only if it serves the paragraph''s point; this tangent **distracts** from the acidification argument.', 'The exhale fact is true and vaguely on-theme, so it feels like a friendly way to hook the reader.', '1) State the paragraph''s single controlling point. 2) Ask whether the candidate sentence advances that point or merely relates to the topic loosely. 3) If it pulls attention elsewhere, keep it out — interest alone is not relevance. 4) Reject any justification that misdescribes what the sentence or paragraph actually says.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a8fbe29dd5d591ce', 'act-english', 's-rhet', 4, 'As the fog thinned, a bittern <u>stood</u> at the edge of the reeds, bill tilted skyward, until it seemed to dissolve among the pale stems.', 'The writer wants to emphasize how completely motionless the bittern remained. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"waited","letter":"B"},{"is_no_change":false,"label":"froze","letter":"C"},{"is_no_change":false,"label":"appeared","letter":"D"}]', 'C', '{"A":"''Stood'' states the bird''s position but places no special stress on stillness.","B":"''Waited'' stresses passing time and expectation rather than absolute stillness.","C":"Correct: it pictures the bird locked mid-motion — the strongest possible image of immobility.","D":"''Appeared'' describes becoming visible, saying nothing about holding still and even implying movement into view."}', 'The goal is maximum **immobility**, and only this verb depicts the bird halted utterly in place.', '''Waited'' tempts students because waiting implies standing in one spot for a long time, which feels close to stillness.', '1) Restate the stem''s goal in one word. 2) For each verb, ask what it emphasizes most: position, time, visibility, or stillness. 3) Cut every option whose core meaning misses the goal. 4) Choose the verb whose image delivers the goal hardest.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b5082b6b6b708d6c', 'act-english', 's-rhet', 4, '<p>Slip trailing turns liquid clay into raised lines of surface ornament. Nadia fills a rubber bulb with slip about the consistency of cake batter, then squeezes steady beads of it across a leather-hard platter. Because the trailed lines sit above the surface, they catch the glaze during firing and emerge a shade darker than the ground beneath them.</p><p>The writer is considering adding the following sentence after the second sentence of the paragraph:</p><p><em>Nadia also teaches a beginners'' wheel class on Tuesday evenings.</em></p>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it establishes that Nadia is an experienced teacher.","letter":"A"},{"is_no_change":false,"label":"Yes, because it adds another example of Nadia''s skill with clay.","letter":"B"},{"is_no_change":false,"label":"No, because the paragraph''s description of the process is already detailed enough.","letter":"C"},{"is_no_change":false,"label":"No, because it strays from the paragraph''s focus on a single decorating process.","letter":"D"}]', 'D', '{"A":"Nadia''s teaching credentials are beside the point in a walkthrough of one technique (irrelevant-but-true lure).","B":"A wheel class involves a different skill entirely, not an example of slip trailing (false-example).","C":"Length is not the issue; the sentence fails on relevance, not on the explanation''s completeness (right verdict, wrong reason).","D":"Correct: the sentence veers away from the paragraph''s one subject, the slip-trailing technique."}', 'Every sentence in a paragraph must serve its **one controlling subject**; the proposed sentence belongs to a different topic.', 'The near-miss ''no'' tempts students because its verdict is right, and only its stated reason fails to match why the sentence doesn''t belong.', '1) State the paragraph''s subject in a short phrase. 2) State what the proposed sentence is about. 3) If the two don''t match, the verdict is no. 4) Among matching verdicts, test each reason against the sentence''s actual flaw. 5) Choose the verdict-plus-reason pair that is accurate on both counts.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b65fb50a8af5ae1e', 'act-english', 's-rhet', 4, 'By final dress rehearsal, the lighting crew has programmed more than two hundred cues into the board. ______ Operators then run the entire show twice using only the stage manager''s calls, never glancing at the script.', 'The writer wants to add a sentence that will keep the paragraph focused on the lighting crew''s preparation for opening night. Which choice best accomplishes that goal?', '[{"is_no_change":false,"label":"Each cue is checked against the designer''s paperwork and rehearsed until the timing is automatic.","letter":"A"},{"is_no_change":false,"label":"The auditorium''s seats were reupholstered in a deep blue fabric last spring.","letter":"B"},{"is_no_change":false,"label":"Several well-known lighting designers began their careers at small high schools.","letter":"C"},{"is_no_change":false,"label":"Ticket prices this year include a small fee that helps maintain the building.","letter":"D"}]', 'A', '{"A":"Correct: verifying and drilling the cues develops exactly what the paragraph tracks — the crew''s run-up to opening night.","B":"Upholstery describes the building, not the crew''s preparation (detail_offtopic).","C":"Famous designers'' origins are lighting-related but say nothing about this crew''s readiness (detail_ontopic_offfocus).","D":"A budgeting fee answers a question the paragraph never asks (detail_offtopic)."}', 'The added sentence must **develop** the paragraph''s focus — the crew''s preparation — and only the cue-verification detail does that work.', 'The famous-designers option tempts students because it stays inside the world of lighting, masking that it abandons this crew''s preparation story.', '1) Name the paragraph''s focus in one phrase. 2) For each option, ask: does this advance that focus or a different topic? 3) Watch for details that share the theme but not the focus. 4) Eliminate anything the surrounding sentences never pick up. 5) Choose the sentence that pushes the paragraph''s own story forward.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b6618554d7d674e1', 'act-english', 's-rhet', 4, '[1] When the city legalized backyard cottages in 2021, planners predicted a construction boom. [2] Instead, only forty permits were issued in the first year. [3] Interviews with homeowners traced the shortfall to a single rule: each cottage required an off-street parking space, which many small lots cannot fit. [4] This spring, the council voted to drop that requirement.', 'The writer is considering deleting Sentence 3. If the writer were to delete this sentence, the paragraph would primarily lose:', '[{"is_no_change":false,"label":"the explanation that connects the weak permit numbers to the council''s vote.","letter":"A"},{"is_no_change":false,"label":"evidence that homeowners opposed the cottage program from the start.","letter":"B"},{"is_no_change":false,"label":"the statistic that shows how slowly the program began.","letter":"C"},{"is_no_change":false,"label":"a transition between the planners'' prediction and the permit totals.","letter":"D"}]', 'A', '{"A":"Sentence 3 supplies the cause — the parking rule — that makes Sentence 4''s remedy comprehensible; without it, the vote comes from nowhere.","B":"The interviews show homeowners were blocked by a rule, not that they opposed cottages — a misreading of the sentence.","C":"The forty-permit figure sits in Sentence 2, which would remain after the deletion.","D":"Sentence 3 comes after both the prediction and the totals, so it cannot bridge them."}', 'Sentence 3 is the paragraph''s **causal link**: it explains the slow start and sets up the council''s fix.', 'Because Sentence 2 already establishes the slow start, Sentence 3 can feel like extra detail rather than the paragraph''s hinge.', '1) State each sentence''s job in the paragraph. 2) Delete the target sentence mentally and re-read. 3) Name precisely what no longer makes sense. 4) Match that loss to an option, rejecting options that describe content living in other sentences. 5) Verify the surviving option describes the target sentence accurately.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b81966658a7e0cdf', 'act-english', 's-rhet', 4, 'A canopy survey found that shade trees cover 38 percent of the streets in Oak Hill but only 9 percent of those near the freight yards, a difference the report''s authors describe as <u>notable</u>.', 'The writer wants to convey the severity of the gap in tree cover between the two neighborhoods. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stark","letter":"B"},{"is_no_change":false,"label":"detectable","letter":"C"},{"is_no_change":false,"label":"surprising","letter":"D"}]', 'B', '{"A":"''Notable'' concedes the gap deserves attention but says nothing about how severe it is.","B":"''Stark'' presents the difference as harsh and extreme, delivering exactly the severity the writer wants.","C":"''Detectable'' nearly erases the gap, implying it can barely be measured — the opposite of severe.","D":"''Surprising'' asserts unexpectedness, a different quality from severity."}', 'The goal demands an adjective that asserts **harsh magnitude**, and only one option does.', '''Notable'' sounds appropriately serious, so its actual mildness is easy to miss.', '1) Name the exact quality the stem asks for. 2) For each adjective, state the single quality it asserts. 3) Strike options asserting a different quality. 4) Strike options asserting the right quality at a weaker degree. 5) Keep the survivor and re-read the sentence with the numbers in view.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bdbd94557605eaf7', 'act-english', 's-rhet', 4, '<p>A living reef is more than a tourist attraction; it is a wall. As swells roll in from the open sea, the reef''s rough, branching structure absorbs and scatters their energy, so that only gentle water reaches the shore behind it. Scientists estimate that healthy reefs can cut incoming wave energy by up to ninety-seven percent, sparing shorelines from erosion and flooding. Where reefs have died, the beaches behind them have begun to wash away.</p>', 'Which of the following best describes the primary purpose of the passage?', '[{"is_no_change":false,"label":"To contrast the recreational value of reefs with their scientific value.","letter":"A"},{"is_no_change":false,"label":"To trace the biological steps by which a coral reef is built.","letter":"B"},{"is_no_change":false,"label":"To explain how reefs shield coastlines from the force of ocean waves.","letter":"C"},{"is_no_change":false,"label":"To urge coastal communities to abandon low-lying beaches.","letter":"D"}]', 'C', '{"A":"The passage mentions tourism only in passing and never contrasts two kinds of value (misconception: purpose_minor_detail_as_main).","B":"The passage covers what reefs do for the coast, not how they grow (misconception: purpose_wrong_topic).","C":"Every sentence builds one point: reefs blunt wave energy and protect the land behind them.","D":"The passage never calls for abandoning beaches; it describes their protection (misconception: purpose_unstated_argument)."}', 'The whole passage develops a single idea — reefs **protect** the coast by breaking wave energy.', 'The opening line names tourism, so a purpose about recreation-versus-science feels grounded even though the passage drops that thread immediately.', '1) Read the whole passage and note what every sentence has in common. 2) State that shared idea as the passage''s job in one phrase. 3) Match each option to that job, not to a single sentence. 4) Reject purposes that seize on a minor detail, name the wrong topic, or invent an argument the passage never makes.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c1c17e4ef855b3e4', 'act-english', 's-rhet', 4, 'The 1920 census lists my great-grandparents in a boardinghouse on Mulberry Street, along with eleven other lodgers. The enumerator recorded my great-grandfather''s occupation as ''presser'' and my great-grandmother''s as ''none.'' Her account book from that same year, however, records payments for taking in sewing from half the block. The census, I have come to understand, counted only what its forms had room to ask.', 'The writer is considering deleting the sentence about the great-grandmother''s account book. Should the writer make this deletion?', '[{"is_no_change":false,"label":"Yes, because it introduces a source other than the census and blurs the paragraph''s focus.","letter":"A"},{"is_no_change":false,"label":"Yes, because the great-grandmother''s earnings are not relevant to a paragraph about the census.","letter":"B"},{"is_no_change":false,"label":"No, because it proves the enumerator deliberately falsified the family''s entry.","letter":"C"},{"is_no_change":false,"label":"No, because it supplies the contradiction on which the paragraph''s final point depends.","letter":"D"}]', 'D', '{"A":"The account book is not a distraction; it is the counter-record that makes the closing sentence possible.","B":"Her earnings matter precisely because the census recorded her occupation as ''none.''","C":"Keeping the sentence is right, but the passage blames the form''s limits, not deliberate dishonesty.","D":"Correct: the account book contradicts the census entry and sets up the paragraph''s closing insight."}', 'The sentence supplies the **contradiction** between record and reality on which the paragraph''s conclusion rests.', 'The falsification option tempts because the enumerator did record something untrue, but the passage attributes the gap to the form, not to fraud.', '1) Find the paragraph''s concluding claim. 2) List which sentences that claim rests on. 3) If the candidate sentence is load-bearing, keep it. 4) Check the offered reason against the passage''s actual argument. 5) Accept only the verdict-plus-reason pair in which both parts hold.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c6e07f1fd6bd71aa', 'act-english', 's-rhet', 4, '[1] This essay traces the year of an urban rooftop hive from the first cleansing flights of March to the wrapping of the boxes in November. [2] It follows one keeper''s decisions week by week, weighing when to add space, when to harvest, and when to leave the bees alone. [3] Along the way it shows how a single colony reflects the rhythm of the city''s blooming trees and vacant-lot wildflowers.', 'Suppose the writer''s goal had been to argue that cities should pass ordinances protecting rooftop apiaries. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it describes a rooftop hive located within a city.","letter":"A"},{"is_no_change":false,"label":"Yes, because it mentions the keeper''s week-by-week decisions about the colony.","letter":"B"},{"is_no_change":false,"label":"No, because it focuses only on the springtime portion of the beekeeping year.","letter":"C"},{"is_no_change":false,"label":"No, because it narrates one hive''s yearly cycle rather than advocating for any policy.","letter":"D"}]', 'D', '{"A":"The mere presence of an urban setting does not make the essay an argument for legislation; a shared subject is not the same as a shared purpose.","B":"Describing a keeper''s choices is narration, not advocacy, so this reason confuses recounting events with arguing for a law.","C":"The essay covers the full year from March to November, so the claim that it stops at spring misreads its scope.","D":"Correct: the essay is a chronological account of one colony''s year and never argues for protective ordinances, so it does not serve an advocacy goal."}', 'An essay accomplishes an argumentative goal only if it actually **argues**, and this one narrates a yearly cycle without urging any policy.', 'Because the essay is genuinely about urban beekeeping, students match the topic and answer ''yes,'' overlooking that topic overlap is not the same as making a case.', '1) State the stated goal as a verb (here, ''argue for a law''). 2) State what the essay actually does as a verb (narrate a year). 3) Compare the two verbs, not the shared subject matter. 4) If the essay''s action does not match the goal''s action, it fails the goal no matter how related the topic is.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-eb06a3f0596aef0a', 'act-english', 's-rhet', 4, 'Until the 1980s, a forecaster tracking a thunderstorm could see where rain was falling but not what the wind inside the storm was doing. Doppler radar changed that by measuring whether raindrops were moving toward or away from the antenna. With that upgrade, rotation inside a supercell became visible many minutes before any funnel dropped. Tornado warning lead times, once close to zero, stretched past ten minutes within a decade.', 'Suppose the writer''s goal had been to write a brief essay showing how one technological advance improved severe-weather warnings. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it recounts the full history of radar from its invention to the present day.","letter":"A"},{"is_no_change":false,"label":"Yes, because it identifies a single advance and traces its specific effect on warning capability.","letter":"B"},{"is_no_change":false,"label":"No, because it addresses only the tornado warning process rather than the full range of severe weather.","letter":"C"},{"is_no_change":false,"label":"No, because it never identifies a single measurable effect of the advance it describes.","letter":"D"}]', 'B', '{"A":"The essay covers one upgrade and its aftermath, not radar''s full history, so the verdict is right but the description is false (misconception: a generous misreading of scope).","B":"Correct: the essay names one advance and follows its measurable effect on lead times, which is exactly the stated goal.","C":"The stated goal asks for one advance''s effect on warnings, so a tight focus is fulfillment, not failure (misconception: narrow scope reads as falling short).","D":"The essay cites lead times stretching from near zero past ten minutes — a measurable effect (misconception: skimming past the data sentence)."}', 'The essay does precisely what the goal specifies: **one advance, one traced effect** on warnings, with numbers to prove it.', 'Readers who expect coverage of severe weather generally may judge the tornado-only focus too narrow, forgetting the goal asked for a single advance.', '1) Restate the hypothetical goal in your own words. 2) Summarize what the essay actually does in one sentence. 3) Compare the two: match or mismatch? 4) Discard options whose reasons misdescribe the essay, even if their verdict matches yours. 5) Choose the option where verdict and description are both accurate.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fb221efc285f4764', 'act-english', 's-rhet', 4, 'An enlarger is little more than a lamp, a negative carrier, and a lens mounted on a vertical column. Light passes through the negative, and the lens focuses that image onto the easel below; raising the head makes the projected picture larger, while lowering it makes the picture smaller. A set of bellows lets the printer fine-tune focus at any height.', 'Suppose the writer''s goal had been to explain how one basic piece of darkroom equipment forms an image. Would this passage accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it recounts one printer''s early struggles to focus a negative sharply.","letter":"A"},{"is_no_change":false,"label":"Yes, because it identifies the machine''s main parts and explains how light projects the negative onto the paper.","letter":"B"},{"is_no_change":false,"label":"No, because it explains darkroom safety procedures rather than any one piece of equipment.","letter":"C"},{"is_no_change":false,"label":"No, because it never explains how the projected image is developed into a finished print on paper.","letter":"D"}]', 'B', '{"A":"Reaches the right verdict with a false description (yes_wrong_description): the passage is a general explanation, not a narrative about any one printer''s struggles.","B":"Correct: the passage names the enlarger''s components and traces how light carries the image from negative to easel, which is exactly the stated goal.","C":"Misdescribes the passage entirely (no_false_focus): not one sentence discusses safety procedures.","D":"Applies a criterion the goal never set (no_irrelevant_criterion): the goal asked how the image is formed, not how the print is later developed."}', 'Both the **verdict** and the **reason** must match the passage, and only this option''s reason truthfully describes what the passage does.', 'It is true the passage omits development, so students accept that criticism without checking whether the stated goal ever demanded that topic.', '1) Restate the stated goal in your own words. 2) Summarize what the passage actually does in one sentence. 3) Compare the two: does the passage do the goal''s job? That fixes the yes/no verdict. 4) Then test each option''s reason against the text, discarding any reason that misdescribes the passage or invokes a requirement the goal never set. 5) Choose the option whose verdict and reason are both true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fbd84e33e8d1095c', 'act-english', 's-rhet', 4, 'The scholarship essay closed by describing the applicant''s grandmother, whose nightly lessons at the kitchen table were <u>helpful</u> in ways no classroom could match.', 'The writer wants to convey deep, lasting influence. Which choice best accomplishes that?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"useful","letter":"B"},{"is_no_change":false,"label":"nice","letter":"C"},{"is_no_change":false,"label":"formative","letter":"D"}]', 'D', '{"A":"''Helpful'' is generic and understates a life-shaping influence.","B":"''Useful'' suggests mere practicality, not deep influence.","C":"''Nice'' is weak and vague, conveying no depth.","D":"''Formative'' names an experience that shaped who the applicant became — exactly the lasting influence intended."}', 'The goal is **lasting influence**, and ''formative'' means shaping a person''s development.', '''Useful'' feels concrete, but it reduces a profound relationship to convenience.', 'Choose the word that captures the depth the stem names, not a safe general-purpose synonym.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-143d67cc13976bfb', 'act-english', 's-rhet', 5, 'By 1890, the pressroom of a metropolitan daily <u>hummed</u> from dusk to dawn, and pressmen stuffed cotton in their ears against the din.', 'The writer wants to convey that the presses were overwhelmingly, almost violently loud. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"thundered","letter":"B"},{"is_no_change":false,"label":"clattered","letter":"C"},{"is_no_change":false,"label":"operated","letter":"D"}]', 'B', '{"A":"''Hummed'' suggests a soft, steady murmur — the opposite of overwhelming noise.","B":"''Thundered'' delivers the crushing, room-shaking volume the writer wants, and it fits the detail about earplugs.","C":"''Clattered'' conveys a busy rattling, but its light, tinny register falls short of violent loudness.","D":"''Operated'' says nothing about sound at all, ignoring the goal."}', 'Only the most forceful verb matches the goal of **overwhelming** loudness and the earplug detail.', '''Clattered'' tempts because it is genuinely noisy; the question is whether it reaches the violent intensity the goal specifies.', '1) Underline the intensity words in the stated goal. 2) Rank the candidate verbs from softest to loudest. 3) Eliminate verbs below the goal''s intensity, even if they are ''noisy.'' 4) Check the survivor against nearby context clues. 5) Re-read the sentence for fit of tone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1df2022022bbb6ac', 'act-english', 's-rhet', 5, '<p>A shallow tide pool can heat up sharply on a sunny afternoon. Water trapped by the low tide may climb ten degrees in a single hour, stressing the animals that cannot escape to cooler depths. Their bodies have only limited ways to shed that extra heat.</p>', 'At this point the writer is considering adding the sentence ''Coral reefs, by contrast, endure heat stress across entire ocean basins.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it offers a helpful comparison to another ecosystem.","letter":"A"},{"is_no_change":false,"label":"Yes, because it explains why the tide pool heats up so fast.","letter":"B"},{"is_no_change":false,"label":"No, because it shifts attention away from the trapped pool animals the paragraph describes.","letter":"C"},{"is_no_change":false,"label":"No, because it repeats the earlier point about rising temperature.","letter":"D"}]', 'C', '{"A":"A comparison to reefs pulls the reader away from the tight focus on the pool (add_offtopic).","B":"The added sentence about reefs does not explain the pool''s rapid heating at all.","C":"Correct: the reef comparison diverts from the trapped pool creatures the passage is about.","D":"The reef sentence is new material, not a repeat of the temperature point."}', 'An addition should be rejected when it **derails the focus**, as the reef comparison does.', 'The reef sentence stays on the theme of heat, so it feels topically connected.', '1) Name the passage''s specific subject. 2) Check whether the new sentence stays on that subject. 3) Reject additions that widen or change the subject. 4) Verify your reason names the true flaw.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-202dc3e0a6f26496', 'act-english', 's-rhet', 5, 'Bolted to bedrock on the volcano''s flank, a tiltmeter senses changes in slope as slight as the lift of a coin under a kilometer-long beam. When magma pushes upward, the flank leans outward by fractions of a degree, and the instrument logs every shift. During the last period of unrest, those readings let scientists trace the swelling, week by week, from a single silent point on the mountain.', 'Suppose the writer''s goal had been to provide an overview of the full range of instruments scientists use to monitor volcanoes. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it describes in detail how a single station is used during a period of unrest.","letter":"A"},{"is_no_change":false,"label":"No, because it focuses on a single instrument instead of covering the range of tools the goal describes.","letter":"B"},{"is_no_change":false,"label":"No, because the essay never explains the range of readings the instrument can record.","letter":"C"},{"is_no_change":false,"label":"Yes, because focusing on one well-chosen tool is an effective way to meet the goal.","letter":"D"}]', 'B', '{"A":"Accurately describes the essay but ignores that the goal demands breadth across instruments.","B":"Correct: the goal asks for a survey of the whole toolkit, and the essay offers depth on exactly one device.","C":"Reaches the right verdict for the wrong reason — the shortfall is breadth across devices, not missing detail about this one.","D":"Rationalizes depth as a substitute for the overview the goal explicitly requires."}', 'The goal demands **breadth** — a survey of many instruments — while the essay offers depth on exactly one.', 'Everything the tempting ''yes'' says about the essay is true, which hides the fact that the goal asked for a different scope.', '1) Underline the scope words in the stated goal (overview, full range). 2) Summarize the essay''s actual scope in one phrase. 3) Compare the two scopes: match → yes; mismatch → no. 4) Then check the reason: it must name the actual match or mismatch, not some other feature.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-31e6d27ed212e7b9', 'act-english', 's-rhet', 5, 'What began in the 1930s as scattered nature clubs for campers'' children slowly hardened into a curriculum: by the 1960s, individual parks were printing their own activity booklets. In the 1990s, the National Park Service standardized the Junior Ranger badge across the system, and today more than two hundred parks—plus an online version for children who have never set foot in a park—award it.', 'Suppose the writer''s goal had been to trace how a single national park program developed over time. Would this passage accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it follows one program from informal beginnings to its standardized, nationwide present.","letter":"A"},{"is_no_change":false,"label":"Yes, because it lists the specific activities children complete to earn the badge.","letter":"B"},{"is_no_change":false,"label":"No, because it evaluates the program''s educational effectiveness rather than its history.","letter":"C"},{"is_no_change":false,"label":"No, because it describes several unrelated park programs rather than a single one.","letter":"D"}]', 'A', '{"A":"Accurately matches the passage''s decade-by-decade arc of one program to the stated goal.","B":"Reaches the right verdict on a false basis—the passage never lists any activities.","C":"Inverts the passage, which narrates history and offers no judgment of effectiveness.","D":"Miscounts the subject: clubs, booklets, and badge are stages of one program, not separate programs."}', 'The passage moves **chronologically through one program''s stages**—exactly what the supposed goal demands.', 'The stages look different enough (clubs, booklets, badges) that students mistake one evolving program for several distinct ones.', '1) Restate the supposed goal precisely (how many subjects? what kind of coverage?). 2) Outline what the passage actually does, decade by decade or point by point. 3) Compare outline to goal for both scope and type. 4) Pick the verdict whose reason matches your outline, not just the right yes or no.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4b343d379f42356e', 'act-english', 's-rhet', 5, 'As the afternoon warmed, the clustered swarm grew restless and finally <u>lifted</u> into the air, streaming toward a hollow oak the scouts had already chosen.', 'Which choice is the most precise word for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"hoisted","letter":"B"},{"is_no_change":false,"label":"elevated","letter":"C"},{"is_no_change":false,"label":"boosted","letter":"D"}]', 'A', '{"A":"Correct: ''lifted'' naturally describes the swarm rising into the air under its own power, matching the living, self-propelled motion.","B":"''Hoisted'' implies an external force raising a load, but no outside agent lifts the swarm here.","C":"''Elevated'' is clinical and abstract, ill-suited to the vivid physical motion of a swarm taking flight.","D":"''Boosted'' is colloquial and suggests a push or an increase in amount, not self-propelled flight."}', 'The best word describes motion the swarm produces itself, so a verb of **self-propelled rising** fits where verbs implying an outside force or the wrong register do not.', 'Each alternative loosely means ''raised,'' so students who scan only for a synonym of ''went up'' accept one without testing its connotation.', '1) Identify who or what performs the action and whether an outside force is involved. 2) List the connotation each candidate carries (external lifting, clinical rise, casual push). 3) Keep only the word whose connotation matches self-powered motion in a vivid register. 4) Reject near-synonyms whose implied agent or tone does not fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4c59cac1c7a5ad62', 'act-english', 's-rhet', 5, 'For decades the orchard grafted fewer heirloom apples each year: varieties like Ashmead''s Kernel are too russeted and too small to interest supermarket buyers. The craft-cider boom has reversed that slide, because cider makers prize exactly the tannins and sharp acids that grocery shelves reject. The family now buds two new rows of bittersweet and heirloom varieties every spring.', 'The writer is considering adding the following sentence after the second sentence: ''One local cidery now contracts each fall for the orchard''s entire crop of Ashmead''s Kernel.'' Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it identifies which heirloom varieties supermarkets refuse to stock.","letter":"A"},{"is_no_change":false,"label":"Yes, because it illustrates the renewed demand described in the preceding sentence.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats the point about supermarket buyers made in the first sentence.","letter":"C"},{"is_no_change":false,"label":"No, because it shifts the focus from the orchard''s apples to the finances of one cidery.","letter":"D"}]', 'B', '{"A":"The proposed sentence names a buyer for one variety; it does not catalog what supermarkets refuse.","B":"Correct: a cidery buying an entire crop is concrete evidence of the boom the second sentence asserts.","C":"The sentence is about a cidery''s purchasing, not a repeat of the supermarket point.","D":"One contract detail supports the boom claim without turning the paragraph toward the cidery''s books."}', 'The addition supplies a **concrete example** backing the sentence it follows.', 'Mentioning a business''s contracts sounds like a swerve toward commerce, so the focus-shift objection feels rigorous.', '1) Identify the sentence the addition would follow and restate its claim. 2) Ask what the new sentence does: support, repeat, or digress. 3) If it gives evidence for the claim, favor adding it. 4) Accept a yes-reason only if it accurately describes that function.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4dd01927285711b4', 'act-english', 's-rhet', 5, '[1] The tracking study followed nine coyotes for two years, mapping every den site inside the city limits. [2] Den sites clustered in cemeteries and along rail corridors, where foot traffic is lightest. [3] The researchers mapped each den the coyotes used within the city. [4] Those quiet corridors, the team concluded, function as a hidden greenbelt threading the metro area.', 'The writer is considering deleting Sentence 3. Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it identifies the data on which the conclusion in Sentence 4 depends.","letter":"A"},{"is_no_change":false,"label":"Kept, because it clarifies that the study was limited to the city.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it merely restates information from Sentence 1.","letter":"C"},{"is_no_change":false,"label":"Deleted, because it contradicts the description of den locations in Sentence 2.","letter":"D"}]', 'C', '{"A":"The den-mapping data is fully established in Sentence 1, so Sentence 3 supplies nothing new for the conclusion to depend on (keep_false_necessity).","B":"The city-limits scope is stated plainly in Sentence 1, so there is nothing left to clarify (keep_false_clarification).","C":"Correct: Sentence 3 duplicates Sentence 1''s content, so deleting it removes pure redundancy.","D":"Mapping every den is fully compatible with dens clustering in cemeteries and rail corridors — no contradiction exists (delete_wrong_reason)."}', 'Sentence 3 is a **restatement** of Sentence 1, so deletion is warranted and this option names the actual flaw.', 'The keep-for-the-conclusion option tempts students because Sentence 4 does rest on mapping data — they just miss that Sentence 1 already supplied it.', '1) Decide what the candidate sentence claims. 2) Search the paragraph for an earlier sentence making the same claim. 3) If a duplicate exists, the sentence should go — unless it adds new detail, which you must be able to point to. 4) Before accepting any reason, verify its premise against the text. 5) Keep the option whose verdict and reason both survive the check.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5c36a7fb51e03536', 'act-english', 's-rhet', 5, 'Few animals can vanish as completely as the cuttlefish. By expanding tiny sacs of pigment in its skin, it can match the color and even the texture of the seafloor within seconds. A hunting cuttlefish may then flash rippling bands of color to startle a crab an instant before it strikes.', 'The writer is considering deleting the second sentence of the paragraph. Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it gives a specific example that illustrates the paragraph''s point about vanishing from view.","letter":"A"},{"is_no_change":false,"label":"Kept, because it introduces the paragraph''s main subject for the first time.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it distracts from the paragraph''s focus on hunting.","letter":"C"},{"is_no_change":false,"label":"Deleted, because the information is contradicted elsewhere in the paragraph.","letter":"D"}]', 'A', '{"A":"Correct: the sentence supplies the concrete mechanism that illustrates the opening claim about disappearing.","B":"The subject is already named in the opening sentence, so this is not its first mention (delete_wrong_reason).","C":"The paragraph centers on disappearing, not hunting, and the sentence is on-topic, so it does not distract (delete_wrong_reason).","D":"Nothing in the paragraph contradicts this detail, so the stated reason is false (delete_false_contradiction)."}', 'A sentence should be **kept** when it gives concrete support for the paragraph''s central claim.', 'Because the paragraph ends with a hunting image, students misread the focus as hunting and vote to cut the concealment detail.', '1) State the paragraph''s central claim. 2) Ask whether the sentence supports, restates, or strays from that claim. 3) Keep sentences that add concrete support; cut only true digressions or repeats. 4) Verify each justification''s reason against the actual text.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5dc0512ec0ce5162', 'act-english', 's-rhet', 5, 'Asked at the press conference whether the volcano would erupt within the month, the observatory''s director <u>refused to guess</u>.', 'The writer wants to portray the director as measured and professional rather than evasive. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"kept dodging the question","letter":"B"},{"is_no_change":false,"label":"declined to speculate","letter":"C"},{"is_no_change":false,"label":"wouldn''t say a word","letter":"D"}]', 'C', '{"A":"''Refused to guess'' carries a blunt, stubborn edge that tilts the portrait toward uncooperative.","B":"''Kept dodging'' openly paints the director as evasive — the very impression to avoid.","C":"Correct: it conveys courteous, disciplined restraint grounded in scientific caution.","D":"Total silence reads as stonewalling or concealment, not measured professionalism."}', 'The goal calls for **connotation** work: only this phrasing sounds courteous and disciplined rather than stubborn, slippery, or secretive.', 'The original sits closest to the key in meaning, and ''guess'' even hints at scientific caution, but ''refused'' carries a blunt, uncooperative edge.', '1) Write down the two impressions in play (careful professional vs. evasive official). 2) For each phrase, list its connotations — blunt, courteous, secretive, cautious. 3) Discard any phrase whose connotation feeds the unwanted impression. 4) Choose the phrase whose every word supports the wanted impression.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-775cf9bb5c7af1d4', 'act-english', 's-rhet', 5, 'The old miners'' path climbed straight up the fall line, and decades of boots and runoff had gouged it into a rutted trench. The crew''s reroute abandons that scar entirely, contouring across the slope in long, patient curves. Surveyors set the new alignment at a six percent grade, less than half the pitch of the abandoned path. Hikers add nearly a mile to the climb, but the tread beneath them should shed water for generations.', 'The writer is considering deleting the sentence about the surveyors (the third sentence). Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it supplies the measurement that makes the contrast between the two routes concrete.","letter":"A"},{"is_no_change":false,"label":"Kept, because it establishes that surveyors, rather than the crew, deserve credit for the reroute.","letter":"B"},{"is_no_change":false,"label":"Deleted, because precise figures are inconsistent with the paragraph''s descriptive style.","letter":"C"},{"is_no_change":false,"label":"Deleted, because the paragraph has already specified the grade of the new alignment.","letter":"D"}]', 'A', '{"A":"Correct: the six percent figure quantifies exactly how much gentler the reroute is, turning the old-versus-new contrast from impression into fact.","B":"Right verdict, wrong reason: the paragraph never debates credit, and the sentence matters for its data, not for who did the surveying.","C":"The figure doesn''t clash with the description — it anchors it, proving the ''patient curves'' claim rather than breaking the style.","D":"False premise: the third sentence is the paragraph''s only statement of the grade; nothing earlier gives any figure."}', 'The sentence must stay because it provides the **only quantitative evidence** for the paragraph''s central contrast between the gouged old path and the gentle new one.', 'The style-consistency reason tempts students who assume hard numbers automatically clash with descriptive prose instead of asking what the number proves.', '1) Ask what the sentence uniquely contributes to the paragraph. 2) Ask what breaks if it disappears. 3) Decide keep or delete on that contribution. 4) Vet the stated reason: reject reasons that misdescribe the sentence''s role, even when the verdict matches yours.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8fc1bc67043cdcd8', 'act-english', 's-rhet', 5, '<p>[1] Before any planting began, the founders paid for a full round of soil tests. [2] A state-certified lab screened samples from every corner of the former rail yard. [3] Because of these results, the founders built raised beds filled with trucked-in soil rather than planting in the ground. [4] That early decision still shapes how the garden grows today.</p><p>The writer is considering adding the following sentence after Sentence 2: <em>Every sample showed lead concentrations more than twice the level the state considers safe for growing food.</em></p>', 'Should the writer make this addition?', '[{"is_no_change":false,"label":"Yes, because it supplies the specific findings that Sentence 3 refers to.","letter":"A"},{"is_no_change":false,"label":"Yes, because it proves that raised beds are always safer than planting in the ground.","letter":"B"},{"is_no_change":false,"label":"No, because it repeats information already provided in Sentence 2.","letter":"C"},{"is_no_change":false,"label":"No, because its technical content clashes with the paragraph''s focus on the founders'' decision.","letter":"D"}]', 'A', '{"A":"Correct: without this sentence, the phrase ''these results'' in Sentence 3 points at nothing; the addition supplies the findings the decision rests on.","B":"Overreach: one site''s lead readings cannot prove a universal claim about raised beds everywhere.","C":"False: Sentence 2 describes the act of screening, not what the screening found, so nothing is repeated.","D":"Backwards: the lead figure is the very evidence that motivated the founders'' decision, so it anchors the focus rather than clashing with it."}', 'Sentence 3''s phrase ''these results'' **requires an antecedent**, and only the proposed sentence provides the actual findings the decision was based on.', 'The precise lead statistic feels more technical than the surrounding narrative, so students conclude it clashes with the paragraph rather than noticing it completes the logic chain.', '1) Read the sentence after the insertion point and circle any pointing phrases (''these results,'' ''that decision''). 2) Ask what each pointer refers to in the current draft. 3) If a pointer has no antecedent, the paragraph is missing information. 4) Test whether the proposed sentence supplies exactly that missing content. 5) Accept the addition only when the verdict and its stated reason are both true.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-aff9cb407f6b5488', 'act-english', 's-rhet', 5, 'For the 1959 sessions that produced <em>Kind of Blue</em>, Miles Davis abandoned the dense chord changes of bebop in favor of modal sketches — a scale or two and a bare outline of form. He handed the sketches to the sextet only when the tape was about to roll, so the musicians were discovering the material even as they recorded it. Listeners often say the album sounds like thought happening in real time.', 'The writer is considering deleting the sentence ''He handed the sketches to the sextet only when the tape was about to roll, so the musicians were discovering the material even as they recorded it.'' Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because it supplies the working method that explains the album''s sense of spontaneity.","letter":"A"},{"is_no_change":false,"label":"Kept, because it establishes that Davis led a six-member group at the sessions.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it repeats the description of modal sketches from the previous sentence.","letter":"C"},{"is_no_change":false,"label":"Deleted, because the paragraph''s focus is the album''s reception, not how it was made.","letter":"D"}]', 'A', '{"A":"Correct: the last-minute handoff is the causal bridge between the sketches and the closing ''thought in real time'' effect.","B":"keep_wrong_reason: the group''s size is incidental; the sentence matters for the process it reveals.","C":"The sentence does not repeat the sketches — it tells what Davis *did* with them, which is new information.","D":"The paragraph is chiefly about the method; reception appears only in the last sentence as evidence of the method''s effect."}', 'Cut the sentence and the final claim loses its **explanation** — the paragraph''s logic collapses.', 'Because the closing sentence mentions listeners, readers can misread reception as the paragraph''s focus and call the process sentence a digression.', '1) Delete the sentence mentally and reread the paragraph. 2) Ask what claim now lacks support or explanation. 3) If a later sentence leans on the deleted one, keep it. 4) Then vet the stated reason: it must name that dependency, not a side detail.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bf2f0097cfdd29e9', 'act-english', 's-rhet', 5, 'Printers stored capital letters in an upper case mounted above the small letters'' lower case, giving English ''uppercase'' and ''lowercase.'' The strips of lead once wedged between lines survive in ''leading,'' the term designers still use for line spacing. Even ''out of sorts'' may recall a compositor who had exhausted the pieces of type called sorts. Each phrase preserves a gesture from the composing room long after the room itself fell silent.', 'Suppose the writer''s goal had been to show how the printing trade left lasting marks on ordinary English. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it identifies the individual printers who coined each term.","letter":"A"},{"is_no_change":false,"label":"Yes, because it connects common expressions to the trade''s physical objects and routines.","letter":"B"},{"is_no_change":false,"label":"No, because it concerns page layout rather than the history of language.","letter":"C"},{"is_no_change":false,"label":"No, because it discusses only vocabulary that professional typographers still use.","letter":"D"}]', 'B', '{"A":"The essay names no coiners; this ''yes'' rests on evidence the essay never gives.","B":"The essay repeatedly ties everyday terms to concrete shop practice, exactly the mark-leaving the goal describes.","C":"Language history is the essay''s whole subject; page layout is only the source domain of the terms.","D":"''Out of sorts'' is everyday idiom, not professional jargon, so the essay reaches beyond specialists."}', 'The essay traces everyday terms to shop practice, which **fulfills** the stated goal directly.', 'The ''only professional vocabulary'' objection tempts because ''leading'' is indeed jargon; it takes the idiom example to defeat that reading.', '1) Restate the hypothetical goal precisely. 2) List what the essay actually does, sentence by sentence. 3) Judge yes or no by matching the list to the goal. 4) Then vet the reason: a right verdict with a wrong reason is still wrong. 5) Confirm the chosen reason cites evidence actually present in the essay.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dda8811b64589b85', 'act-english', 's-rhet', 5, 'Restoring the console became my grandfather''s winter meditation. Replacing the brittle wax capacitors <u>was a real pain in the neck</u>, yet he never rushed a single joint of solder.', 'Which choice best maintains the tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"demanded slow, exacting care","letter":"B"},{"is_no_change":false,"label":"was seriously the most annoying part of the whole deal","letter":"C"},{"is_no_change":false,"label":"constituted an endeavor of considerable magnitude","letter":"D"}]', 'B', '{"A":"The breezy body-part idiom snaps the passage''s quiet, reflective register.","B":"Correct: measured and specific, it matches the contemplative voice of ''winter meditation'' and ''never rushed.''","C":"''Seriously'' and ''the whole deal'' push even further into conversational slang.","D":"The inflated, bureaucratic diction overshoots the passage''s modest register as badly as slang undershoots it."}', 'Tone must match the frame: the passage''s **reflective, measured register** calls for plain but dignified wording, neither slangy nor pompous.', 'The grand-sounding ''constituted an endeavor of considerable magnitude'' tempts students who equate formality with quality, but overshooting register is a tone error too.', '1) Collect two or three tone-setting words from the surrounding sentences. 2) Name the register they establish (casual, conversational, measured, formal). 3) Test each option against that register in both directions — too loose and too grand both fail. 4) Choose the option that could have been written by the same voice. 5) Reread the paragraph with it in place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-de74e38aa1587e4a', 'act-english', 's-rhet', 5, 'Support for a campus interpreting program <u>appeared</u> over three semesters, one persuaded administrator and one signed petition at a time.', 'The writer wants to emphasize how gradually the program won support. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"materialized","letter":"B"},{"is_no_change":false,"label":"surfaced","letter":"C"},{"is_no_change":false,"label":"accumulated","letter":"D"}]', 'D', '{"A":"''Appeared'' marks that support existed but says nothing about a slow, additive build.","B":"''Materialized'' suggests support popped into being, if anything implying suddenness.","C":"''Surfaced'' implies hidden support becoming visible, not support growing bit by bit.","D":"Correct — it denotes piling up increment by increment, matching ''one administrator ... at a time.''"}', 'Only a verb meaning **built up piece by piece** matches the sentence''s one-at-a-time details.', '''Surfaced'' tempts readers because emerging support feels gradual, yet the verb describes visibility, not growth.', '1) Convert the stated goal into a test phrase (here: ''bit by bit over time''). 2) Ask of each verb: does its core meaning include that increment-by-increment sense? 3) Use the sentence''s own details (''one ... at a time'') as the tiebreaker. 4) Keep the verb the details could literally describe.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e66889e4db236ea3', 'act-english', 's-rhet', 5, 'Each dawn at Katmai, the bear biologist <u>looks over</u> the overnight signals from the sows'' tracking collars.', 'The writer wants to portray the biologist as examining the data with painstaking care. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"scrutinizes","letter":"B"},{"is_no_change":false,"label":"researches","letter":"C"},{"is_no_change":false,"label":"notices","letter":"D"}]', 'B', '{"A":"''Looks over'' implies a quick, casual skim—the opposite of painstaking care.","B":"Denotes close, critical, detail-by-detail examination, exactly the care the writer wants.","C":"Names a whole scholarly activity, far too broad for the daily act of reading collar signals.","D":"Reduces the examination to passive, incidental awareness."}', 'Only one verb specifically means **examining minutely and critically**.', '''Researches'' sounds scientific and serious, so students equate professional flavor with careful attention.', '1) Underline the goal''s key qualities (here: care and thoroughness). 2) Define each verb candidate precisely. 3) Eliminate verbs that are too casual, too broad, or too passive for those qualities. 4) Keep the verb whose core meaning *is* the goal.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ec994b86a1935b81', 'act-english', 's-rhet', 5, 'Historians describe the signal box as a place of quiet method: levers polished by decades of hands, timetables known to the minute. The signalman''s ledger, in which every passing train was entered, <u>stands as a soul-stirring monument to humanity''s eternal wrestle with time itself</u>.', 'Which choice best matches the tone of the surrounding passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"is a totally awesome window into the signalman''s work","letter":"B"},{"is_no_change":false,"label":"constitutes documentation of considerable operational significance","letter":"C"},{"is_no_change":false,"label":"records the steady rhythm of that work","letter":"D"}]', 'D', '{"A":"The grand, emotional flourish clashes with the passage''s quiet, observational voice.","B":"Chatty slang like ''totally awesome'' falls far below the passage''s measured register.","C":"Stiff bureaucratic phrasing overshoots the passage''s plain, human vocabulary.","D":"Correct: calm, concrete wording continues the passage''s quiet, factual tone."}', 'The passage speaks in a **quiet, measured** voice, and only this choice stays inside it.', 'The sweeping original feels like fine writing, so students reward its drama instead of testing it against the passage.', '1) Read the sentences around the span and label their tone in two words. 2) Label each option''s tone the same way. 3) Reject options that are more casual, more grandiose, or more technical than the passage. 4) Keep the option whose label matches the passage''s.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f08f7b78077e2666', 'act-english', 's-rhet', 5, 'At this studio, torn tapestries are repaired with thread, never adhesive. Stitching lets a future conservator undo every repair without leaving residue. Adhesives, by contrast, seep between fibers and stiffen the weave as they age. A full restitching of a room-sized tapestry can cost more than the tapestry''s insured value.', 'The writer is considering deleting the final sentence ("A full restitching of a room-sized tapestry can cost more than the tapestry''s insured value."). Should the sentence be kept or deleted?', '[{"is_no_change":false,"label":"Kept, because the expense figure proves that stitching is superior to adhesives.","letter":"A"},{"is_no_change":false,"label":"Kept, because it clarifies why some museums still choose adhesives despite their drawbacks.","letter":"B"},{"is_no_change":false,"label":"Deleted, because it repeats the paragraph''s earlier point about residue-free repairs.","letter":"C"},{"is_no_change":false,"label":"Deleted, because it shifts the paragraph''s emphasis from the case for stitching to an unrelated matter of expense.","letter":"D"}]', 'D', '{"A":"The cost detail proves nothing about quality; if anything, a high price argues against stitching, not for it.","B":"The sentence never mentions other museums or adhesives, so this explanatory link is invented, not stated.","C":"The verdict is right but the reason false: no earlier sentence discusses cost, so nothing is repeated.","D":"Correct: the paragraph argues for stitching on conservation grounds, and a jarring cost statistic pulls the discussion off that track."}', 'A concluding detail must **serve the paragraph''s argument**; a cost statistic redirects a paragraph built entirely on reversibility and preservation.', 'Students reward any concrete number as ''good evidence'' without asking what claim the number actually supports.', '1) State the paragraph''s argument in one sentence. 2) Ask what claim the sentence in question supports or undermines. 3) If it supports a different claim than the paragraph''s, it does not belong — even if it is true and vivid. 4) Then audit the because-clause of each verdict: keep only a verdict whose stated reason is factually true of the passage.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f34d81dff7018633', 'act-english', 's-rhet', 5, 'In his memoir, the former champion recounts each defeat with measured candor, examining <u>the miscalculations that cost him decisive games</u>.', 'Given that all the choices are accurate, which one best maintains the essay''s measured, formal tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the bonehead moves that totally tanked his biggest games","letter":"B"},{"is_no_change":false,"label":"the harrowing blunders that forever shattered his fragile spirit","letter":"C"},{"is_no_change":false,"label":"the suboptimal decision outcomes occurring in high-stakes contest scenarios","letter":"D"}]', 'A', '{"A":"The plain, precise phrasing matches the essay''s measured candor: formal without inflation, direct without drama.","B":"''bonehead'' and ''tanked'' are slang, snapping the essay''s calm, formal register.","C":"Melodramatic language (''forever shattered his fragile spirit'') overheats a passage defined by restraint.","D":"Bureaucratic jargon (''decision outcomes,'' ''contest scenarios'') inflates the diction, trading candor for stiffness."}', 'The original phrasing already matches the essay''s **measured**, formal register — precise, calm, and direct.', 'The jargon-heavy version tempts because piled-up formal-sounding nouns can masquerade as sophistication.', '1) Find the passage''s tone cues (''measured candor''). 2) Sort each option by register: slang, melodrama, jargon, or plain formal. 3) Eliminate anything more casual, more emotional, or more inflated than the cues. 4) Keep the phrasing that matches the passage''s own temperature.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f78a56dbd4478456', 'act-english', 's-rhet', 5, 'My grandmother''s kitchen table was my first classroom. There she drilled me on fingerspelling until my knuckles ached, corrected the slope of my signing space, and told stories about the Deaf club she helped found in 1968. Years later, when I raised my right hand to take the interpreter''s oath, I could still feel that table''s worn oak beneath my wrists.', 'Suppose the writer''s goal had been to provide an overview of the certification process for sign language interpreters. Would this essay accomplish that goal?', '[{"is_no_change":false,"label":"Yes, because it ends with the writer taking the interpreter''s oath after years of preparation.","letter":"A"},{"is_no_change":false,"label":"No, because it is a personal tribute to a single teacher rather than a survey of certification requirements.","letter":"B"},{"is_no_change":false,"label":"No, because the essay shows that the writer never completed the certification process.","letter":"C"},{"is_no_change":false,"label":"Yes, because the grandmother''s lessons at the table cover each stage of the certification process.","letter":"D"}]', 'B', '{"A":"One closing image of the oath does not amount to an overview; no exam, rating, or requirement is ever explained.","B":"Correct — the essay honors a formative figure through memory and detail; it never outlines how certification works.","C":"The essay states the writer took the interpreter''s oath, so the claim that certification was never completed contradicts the text.","D":"The lessons named — fingerspelling drills, signing space, club stories — are family teaching, not stages of any formal process."}', 'An overview would explain the **process**; this essay instead lingers on memory, gratitude, and a formative figure.', 'The oath in the final sentence tempts readers to count the essay as process writing, though the process itself is never described.', '1) Restate the hypothetical goal as a checklist of content it would require. 2) Scan the essay for each checklist item. 3) Decide yes/no from coverage, not from a lone matching detail. 4) Then verify the option''s ''because'' clause states a fact the essay actually supports.', 'rhetorical-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f8f176ace6228c38', 'act-english', 's-rhet', 5, 'Because a two-degree drift can shift a print''s contrast, Priya <u>checks</u> the developer''s temperature throughout the entire two-hour session.', 'The writer wants to stress that Priya keeps constant watch over the developer''s temperature for the whole session. Which choice best accomplishes that goal?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"verifies","letter":"B"},{"is_no_change":false,"label":"monitors","letter":"C"},{"is_no_change":false,"label":"inspects","letter":"D"}]', 'C', '{"A":"''Checks'' names discrete, occasional acts (verb_discrete_acts), not the unbroken vigilance the goal demands.","B":"''Verifies'' means confirming a fact once (verb_one_time_confirmation), so it cannot stretch across two hours.","C":"Correct: ''monitors'' denotes sustained, continuous observation, matching ''constant watch'' exactly.","D":"''Inspects'' pictures a single close examination (verb_momentary_scrutiny), not ongoing attention."}', 'Only a verb of **sustained** observation matches ''constant watch'' over ''the whole session.''', '''Checks'' pairs naturally with ''throughout,'' so students assume repeated checking adds up to the continuous vigilance the goal requires.', '1) Circle the duration cues in the stem and sentence (''constant,'' ''whole session,'' ''throughout''). 2) Ask of each verb: does it happen once, repeatedly, or continuously? 3) Eliminate one-time and intermittent verbs. 4) Choose the verb whose built-in duration matches the cues.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-168f4667ffdca01d', 'act-english', 's-sent', 1, 'The county''s tornado sirens date from the 1950s. <u>Although the sirens are tested on the first Wednesday of every month.</u> Few residents have ever heard them in a real emergency.', 'Which choice results in a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Although the sirens being tested on the first Wednesday of every month.","letter":"B"},{"is_no_change":false,"label":"The sirens are tested on the first Wednesday of every month.","letter":"C"},{"is_no_change":false,"label":"While the sirens are tested on the first Wednesday of every month.","letter":"D"}]', 'C', '{"A":"''Although'' turns the statement into a dependent clause that never attaches to a main clause — a fragment (misconception: length plus a period equals a sentence).","B":"''Being tested'' supplies no finite verb, so the word group still cannot stand alone (misconception: an -ing form works as a main verb).","C":"Correct: removing the subordinator leaves a complete statement with a subject and a finite verb.","D":"''While'' subordinates the clause just as ''Although'' did, leaving the fragment intact (misconception: swapping subordinators fixes the structure)."}', 'Deleting the **subordinating word** lets the clause stand alone as a complete sentence.', 'The original is long and information-rich, so it feels sentence-like despite opening with a word that demands a follow-up clause.', '1) Read the word group alone. 2) Find a subject and a finite verb. 3) Check the first word: does it make the clause lean on another sentence (''although,'' ''while,'' ''because'')? 4) If it leans and nothing follows, delete the leaning word or attach the clause. 5) Re-read to confirm it stands alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-38b5fe785ba95a5a', 'act-english', 's-sent', 1, 'The rain finally <u>stopped the players</u> returned to the field.', 'Which choice corrects the fused sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stopped, the players","letter":"B"},{"is_no_change":false,"label":"stopped. The players","letter":"C"},{"is_no_change":false,"label":"stopped the players,","letter":"D"}]', 'C', '{"A":"Two complete sentences run together with no punctuation at all — a fused sentence.","B":"A comma alone between two independent clauses trades the fused sentence for a comma splice.","C":"A period ends the first complete thought and lets the second begin cleanly.","D":"The comma after ''players'' punctuates nothing — the two clauses are still fused."}', 'Two independent clauses need a real boundary — here, a **period**.', 'Read quickly, ''the rain stopped the players'' parses as one clause, hiding the seam.', 'Find where one complete thought ends and the next begins; mark that seam with a period, semicolon, or comma + conjunction.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b92e1e2c56840572', 'act-english', 's-sent', 1, 'The transit agency installed forty new bus shelters along the crosstown line. <u>Each one equipped</u> with solar lighting and a screen showing arrival times.', 'Which choice makes the second statement a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Each one being equipped","letter":"B"},{"is_no_change":false,"label":"Each one is equipped","letter":"C"},{"is_no_change":false,"label":"Each one, equipped","letter":"D"}]', 'C', '{"A":"''Equipped'' is a bare participle, leaving the subject with no main verb — a fragment.","B":"''Being equipped'' is still a participle; adding ''-ing'' does not create a finite verb.","C":"''Is equipped'' supplies the finite verb the subject needs, completing the sentence.","D":"A comma cannot substitute for a verb; the statement remains a fragment."}', 'A complete sentence needs a **finite verb**, and only this option provides one.', 'The fragment reads smoothly after the first sentence, so the missing verb is easy to overlook.', '1) Isolate the statement and find its subject. 2) Hunt for a finite verb — one that changes form for past or future. 3) If every verb-like word is a participle, the statement is a fragment. 4) Fix it by adding a helping verb or attaching the fragment to the previous sentence. 5) Re-read the repaired statement alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ca301b7240c9a794', 'act-english', 's-sent', 1, 'The recipe looked simple <u>it took</u> three tries to get right.', 'Which choice repairs the fused sentence best?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"simple, it took","letter":"B"},{"is_no_change":false,"label":"simple it, took","letter":"C"},{"is_no_change":false,"label":"simple, but it took","letter":"D"}]', 'D', '{"A":"''The recipe looked simple'' and ''it took three tries'' are each complete — fused with no punctuation.","B":"A comma with no conjunction leaves a splice.","C":"The comma lands between the subject ''it'' and its verb ''took'', splitting the wrong pair.","D":"The two thoughts contrast, so comma + ''but'' both separates and signals the reversal."}', 'Comma + a **coordinating conjunction** (here ''but'') joins the clauses and shows the contrast.', 'The sentence reads smoothly, hiding that two full sentences have collided.', 'Locate where one complete thought ends; mark that seam — a lone comma or nothing won''t hold two clauses.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f93b402b9faaa78b', 'act-english', 's-sent', 1, 'Snow fell all night <u>the plows worked</u> until dawn to clear the pass.', 'Which choice best fixes the run-on?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"night the plows, worked","letter":"B"},{"is_no_change":false,"label":"night; the plows worked","letter":"C"},{"is_no_change":false,"label":"night, the plows worked","letter":"D"}]', 'C', '{"A":"Two complete sentences are shoved together with no punctuation at all.","B":"A comma between the subject ''plows'' and its verb ''worked'' breaks the clause instead of the run-on.","C":"A semicolon links two closely related complete thoughts without a conjunction.","D":"A comma alone between two complete thoughts is a splice."}', 'A **semicolon** joins two independent clauses that belong together.', 'The events are so connected that leaving them fused feels natural.', 'Independent + independent → semicolon, period, or comma + conjunction — never nothing, never a lone comma.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-10a90843a6238247', 'act-english', 's-sent', 2, 'The hundred-foot turntable balanced perfectly on its center <u>pivot, a single worker could spin</u> a locomotive weighing eighty tons.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"pivot, however, a single worker could spin","letter":"B"},{"is_no_change":false,"label":"pivot a single worker could spin","letter":"C"},{"is_no_change":false,"label":"pivot, so a single worker could spin","letter":"D"}]', 'D', '{"A":"A comma alone links two independent clauses, creating a comma splice.","B":"''However'' is a conjunctive adverb, not a conjunction, so the splice remains — and its contrast is illogical here.","C":"Removing the comma fuses the two clauses with no boundary at all.","D":"Correct: the comma plus the coordinating conjunction ''so'' legally joins the clauses and captures the cause-effect logic."}', 'Two independent clauses need a **comma plus a coordinating conjunction** (or a stronger stop), and the conjunction chosen matches the cause-effect meaning.', 'The ''however'' version tempts students who believe any transition word can glue two clauses together.', '1) Find each subject-verb pair and confirm both clauses stand alone. 2) Inspect the joint: comma alone = splice; nothing = fused. 3) Legal joints are a period, a semicolon, or a comma plus a coordinating conjunction. 4) Pick the legal joint whose logic — cause, contrast, addition — fits the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1ffca9b74e5f7cd9', 'act-english', 's-sent', 2, 'The shell of a limpet is far thicker than <u>a periwinkle</u> that shares the same rocky ledge.', 'Which choice makes the comparison logical?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a periwinkle is","letter":"B"},{"is_no_change":false,"label":"those of a periwinkle","letter":"C"},{"is_no_change":false,"label":"that of a periwinkle","letter":"D"}]', 'D', '{"A":"This compares a shell to a whole animal, an illogical comparison (illogical_comparison).","B":"Inserting a verb compares the shell to the animal''s existence, still illogical and awkward.","C":"The plural stand-in does not match the singular ''shell,'' so the number is wrong.","D":"Correct: the singular stand-in fills in for ''the shell of,'' comparing shell to shell."}', 'A comparison must match **like with like**; the singular stand-in supplies the second shell.', '''Than a periwinkle'' sounds natural in speech, so students miss that it compares a shell to an animal.', '1) Find the two things being compared. 2) Check they are the same kind of thing. 3) If a possessed noun is compared to a whole thing, insert ''that of'' (singular) or ''those of'' (plural). 4) Match the number to the first noun.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-25b1576fd5f783b9', 'act-english', 's-sent', 2, 'The power flickered during the storm<u>, the</u> projector shut off mid-scene.', 'Which choice corrects the run-on between the two statements?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":" and the","letter":"B"},{"is_no_change":false,"label":", and the","letter":"C"},{"is_no_change":false,"label":" the","letter":"D"}]', 'C', '{"A":"A comma alone splices ''the power flickered'' to ''the projector shut off''.","B":"Dropping the comma before ''and'' between two full clauses leaves them under-punctuated.","C":"Comma + ''and'' correctly joins the two independent clauses.","D":"Removing all punctuation fuses the two complete thoughts."}', 'Two independent clauses take a **comma before the coordinating conjunction**.', 'A single comma looks like enough because a natural pause falls there.', 'Comma-splice repair: add a conjunction after the comma, or upgrade the comma to a semicolon or period.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2a9e2bd8f448b0c7', 'act-english', 's-sent', 2, 'Customers insist that the flavor of a tree-ripened Macoun is sharper than <u>that of</u> any apple shipped in from cold storage.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"DELETE the underlined portion.","letter":"B"},{"is_no_change":false,"label":"the one of","letter":"C"},{"is_no_change":false,"label":"those of","letter":"D"}]', 'A', '{"A":"Correct: ''that of'' stands in for ''the flavor of,'' comparing flavor to flavor.","B":"Deleting the phrase compares a flavor to an apple — an illogical, mismatched comparison.","C":"''The one of'' is unidiomatic; standard English does not use it as a comparison stand-in.","D":"''Those of'' is plural, but its stand-in noun, ''flavor,'' is singular."}', 'Comparisons must match **like with like**: the singular stand-in keeps flavor compared with flavor.', 'Dropping the phrase yields the shortest, smoothest-sounding sentence, hiding the mismatched comparison.', '1) Name the two things being compared. 2) Check that they are the same category (flavor vs. flavor, not flavor vs. apple). 3) If a stand-in pronoun is used, match its number to the noun it replaces. 4) Prefer the version that keeps categories and number aligned.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4575fe54665624b1', 'act-english', 's-sent', 2, 'The spinning wheel hummed <u>steadily; by midnight,</u> every handful of carded fleece had been drawn into yarn.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"steadily, by midnight,","letter":"B"},{"is_no_change":false,"label":"steadily by midnight","letter":"C"},{"is_no_change":false,"label":"steadily; because by midnight,","letter":"D"}]', 'A', '{"A":"Correct: the semicolon legally joins two independent clauses that are closely related.","B":"A comma alone between two independent clauses creates a comma splice.","C":"Removing all punctuation fuses the two clauses into a run-on.","D":"The added ''because'' turns the second half into a fragment that cannot follow a semicolon."}', 'A semicolon may join **two independent clauses**, and both halves here stand alone.', 'The comma version tempts because the pause feels natural aloud, but a comma cannot join complete sentences by itself.', '1) Split the sentence at the punctuation. 2) Test each half: subject + verb + complete thought? 3) Two independents may take a semicolon or a period. 4) If either half is dependent, a semicolon fails. 5) Reject any option creating a splice or fusion.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-472519ba504a2431', 'act-english', 's-sent', 2, 'Even after a downpour, the soil in the hillside plots drains faster than <u>the plots near the creek</u>.', 'Which choice makes the comparison in the sentence logical?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the plots near the creek do","letter":"B"},{"is_no_change":false,"label":"that in the plots near the creek","letter":"C"},{"is_no_change":false,"label":"those in the plots near the creek","letter":"D"}]', 'C', '{"A":"Mismatched comparison: it weighs soil (a substance) against plots (locations).","B":"Adding ''do'' makes the plots the things draining, so soil is still being compared with plots.","C":"Correct: singular ''that'' stands in for ''the soil,'' comparing soil with soil.","D":"Plural ''those'' cannot stand in for the singular noun ''soil.''"}', 'Logical comparison requires soil to be weighed against soil, and singular **that** correctly stands in for ''the soil.''', 'Adding a helper verb makes the sentence sound complete, so students accept it without noticing the two sides of the comparison still don''t match.', '1) Find the word ''than'' and identify what is being compared on its left side. 2) Check the right side: is it the same category of thing? 3) If not, insert a stand-in (''that of/in'' or ''those of/in'') for the left-side noun. 4) Match the stand-in''s number — singular or plural — to that noun. 5) Reread the comparison to confirm both sides align.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-58e89129f9866e2f', 'act-english', 's-sent', 2, 'Sea turtles can hold their breath for hours, <u>but they must</u> eventually surface to breathe air.', 'Which choice best expresses the logical relationship between the clauses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"so they must","letter":"B"},{"is_no_change":false,"label":"they must","letter":"C"},{"is_no_change":false,"label":"for they must","letter":"D"}]', 'A', '{"A":"Correct: ''but'' signals the contrast between long breath-holding and the need to surface.","B":"''So'' implies a cause-effect that does not fit; surfacing is not caused by breath-holding (wrong_conjunction_logic).","C":"Removing the conjunction leaves two clauses joined by only a comma, a comma splice (comma_splice).","D":"''For'' means ''because,'' wrongly framing the second clause as the reason for the first (wrong_conjunction_logic)."}', 'The two ideas oppose each other, so a **contrast** conjunction is the correct link.', '''So'' feels natural after a fact about ability, tempting students to read a result where there is a contrast.', '1) State how the two clauses relate: contrast, cause, or result. 2) Match a coordinating conjunction to that relationship. 3) Keep a conjunction after the comma so the clauses are properly joined. 4) Re-read to confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-75ffdc935d7018d9', 'act-english', 's-sent', 2, 'Passage III — The Mapmaker''s Daughter — Marie Tharp was a geologist who helped change how we see the ocean floor. In the 1950s, working alongside her colleague Bruce Heezen, she plotted thousands of depth measurements collected from ships crossing the Atlantic. At the time, many scientists believed the ocean floor was mostly flat. Tharp''s maps revealed something remarkable, a vast underwater mountain range running down the middle of the Atlantic. This discovery, which supported the then-controversial theory of continental drift, was at first dismissed by Heezen as "girl talk." Eventually, the evidence became impossible to ignore. Tharp''s careful work helped establish the theory of plate tectonics. Today, <u>her once-doubted</u> maps are considered landmarks of earth science.', 'Which choice correctly forms and punctuates the underlined compound modifier?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"her once doubted","letter":"B"},{"is_no_change":false,"label":"her once-doubted,","letter":"C"},{"is_no_change":false,"label":"hers once-doubted","letter":"D"}]', 'A', '{"A":"\"once-doubted maps\" correctly hyphenated; no trailing comma.","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', '"once-doubted maps" correctly hyphenated; no trailing comma.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Conventions (hyphenated modifier)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-77155fe8b8724aa8', 'act-english', 's-sent', 2, 'The regional lightning network locates each strike within <u>seconds, this</u> speed lets utility crews reroute power before damaged lines fail.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"seconds this","letter":"B"},{"is_no_change":false,"label":"seconds. This","letter":"C"},{"is_no_change":false,"label":"seconds. Because this","letter":"D"}]', 'C', '{"A":"The comma tries to join two complete statements by itself — a splice (misconception: a backward-pointing opener like ''this speed'' feels connected enough).","B":"No punctuation at all fuses the two statements (misconception: removing the comma removes the problem).","C":"Correct: a period ends the first complete statement, and the next begins cleanly.","D":"''Because'' makes the second statement a dependent clause stranded alone after the period — a fragment (misconception: subordinators can be sprinkled on for flow)."}', 'A **period** is a clean, legal boundary between these two independent statements.', '''This speed'' refers back so tightly to the previous clause that the comma join feels cohesive.', '1) Find where the first complete thought ends. 2) Verify the second word group is also complete. 3) Choose a legal boundary: period, semicolon, or comma with a coordinating conjunction. 4) If you add a subordinating word, make sure a main clause still follows. 5) Re-read both halves separately.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-897c84ade1ac106d', 'act-english', 's-sent', 2, 'The apprentice lifted the heavy super off the stack. <u>Straining under the weight of forty pounds of capped comb.</u>', 'Which choice makes the underlined portion a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"She strained under the weight of forty pounds of capped comb.","letter":"B"},{"is_no_change":false,"label":"Straining under the weight of forty pounds of capped comb,","letter":"C"},{"is_no_change":false,"label":"Under the weight of forty pounds of capped comb straining.","letter":"D"}]', 'B', '{"A":"The ''-ing'' phrase has no subject and no finite verb, so it is a fragment standing where a sentence should be.","B":"Correct: adding the subject ''she'' and the finite verb ''strained'' turns the fragment into a complete sentence.","C":"Merely swapping the period for a comma still leaves a subjectless participial phrase with no main clause attached.","D":"Rearranges the same words but still supplies no subject and no finite verb, so the fragment remains."}', 'A complete sentence needs a **subject and a finite verb**, and only this version supplies both.', 'The original sounds descriptive and full, so students accept the vivid participial phrase as if it were a sentence.', '1) Look for the subject: who or what performs the action? 2) Look for a finite verb that can carry tense (not just an ''-ing'' or ''-ed'' word). 3) If either is missing, the string is a fragment. 4) Fix it by supplying the missing subject, the missing finite verb, or both.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-91c6a48aea095e8e', 'act-english', 's-sent', 2, 'In puzzle-box trials, the problem-solving success of city squirrels routinely tops <u>rural squirrels</u>.', 'Which choice makes the comparison in this sentence logical?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"that of rural squirrels","letter":"B"},{"is_no_change":false,"label":"those of rural squirrels","letter":"C"},{"is_no_change":false,"label":"rural squirrels themselves","letter":"D"}]', 'B', '{"A":"Compares a success rate to animals — mismatched categories (illogical_comparison).","B":"Correct: the singular stand-in refers back to ''success,'' so ability is compared with ability.","C":"The plural stand-in mismatches the singular ''success'' it must replace (that_those_number).","D":"The intensifier underlines the same mismatched comparison without repairing it (intensified_illogical)."}', 'Comparisons must match **like with like**, and the singular stand-in makes the sentence compare success with success.', 'The plural stand-in tempts students who match it to the nearby plural ''squirrels'' instead of to the singular noun ''success'' it actually replaces.', '1) Identify the two things literally being compared. 2) If the categories differ (a quality versus a creature), insert a stand-in for the quality. 3) Match the stand-in''s number to the noun it replaces, not to nearby nouns. 4) Re-read the sentence substituting the full noun for the stand-in. 5) Confirm both sides of the comparison are now the same kind of thing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9a237b9f8b5ba000', 'act-english', 's-sent', 2, 'The museum galleries were packed<u>, we</u> headed to the sculpture garden instead.', 'Which choice best repairs the comma splice?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", however we","letter":"B"},{"is_no_change":false,"label":" we","letter":"C"},{"is_no_change":false,"label":", so we","letter":"D"}]', 'D', '{"A":"A comma alone cannot join two independent clauses — this is a comma splice.","B":"''However'' is not a coordinating conjunction; it would need a semicolon before it.","C":"Deleting the comma fuses the clauses — no boundary at all.","D":"Comma + the coordinating conjunction ''so'' legally joins the clauses AND names the cause-effect link."}', 'Comma + **coordinating conjunction** (for, and, nor, but, or, yet, so) is a legal clause joiner.', '''However'' feels like a conjunction, but it''s an adverb — the classic splice non-fix.', 'Join independent clauses with comma + FANBOYS, a semicolon, or a period — never a bare comma.', 'underlined-span-mc', '''However'' feels like a conjunction, but it''s an adverb — the classic…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9ead72eeb6cf4017', 'act-english', 's-sent', 2, 'Aquarium scientists have finally learned to spawn coral in the <u>lab, they</u> now ship hardy fragments to reef-restoration projects around the world.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"lab, and they","letter":"B"},{"is_no_change":false,"label":"lab they","letter":"C"},{"is_no_change":false,"label":"lab, thus they","letter":"D"}]', 'B', '{"A":"A comma alone cannot join two independent clauses; this is a comma splice (misconception: comma_splice).","B":"Adding the coordinating conjunction ''and'' properly joins the two independent clauses.","C":"Removing all punctuation fuses the two clauses into a run-on (misconception: fused_sentence).","D":"''Thus'' is a conjunctive adverb, so a comma before it still leaves a splice; it would need a semicolon (misconception: conjunctive_adverb_splice)."}', 'Two independent clauses can be joined by a comma **plus** a coordinating conjunction.', 'The comma marks a natural pause, so it feels like enough to hold the two statements together.', '1) Check whether the words on each side of the join could stand alone. 2) If both are complete sentences, a lone comma is illegal. 3) Fix it with a comma plus a coordinating conjunction, or a semicolon, or a period. 4) Remember a conjunctive adverb after a comma does not repair a splice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b26c26369fb85041', 'act-english', 's-sent', 2, 'The deadline passed at <u>midnight the presses</u> were already humming in the basement.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"midnight; the presses","letter":"B"},{"is_no_change":false,"label":"midnight, the presses","letter":"C"},{"is_no_change":false,"label":"midnight, however the presses","letter":"D"}]', 'B', '{"A":"Fuses two independent clauses with no boundary at all.","B":"Correct: a semicolon legally joins the two closely related independent clauses.","C":"A comma alone between independent clauses creates a comma splice.","D":"''However'' with only a comma still splices the clauses — a conjunctive adverb is not a conjunction."}', 'A **semicolon** is a legal boundary between two independent clauses, which is exactly what these two complete statements need.', 'The comma tempts students because the pause feels sufficient when the two clauses are short and related.', '1) Find each subject-verb pair. 2) Ask whether each could stand alone as a sentence. 3) Two standalones need a real boundary: period, semicolon, or comma plus a coordinating conjunction (FANBOYS). 4) A comma alone — or comma plus ''however'' — is not a boundary. 5) Re-read each clause separately to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bca591af90085261', 'act-english', 's-sent', 2, 'Hundreds of bison <u>graze</u> in Yellowstone''s Lamar Valley on long summer evenings.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"grazing","letter":"B"},{"is_no_change":false,"label":"that graze","letter":"C"},{"is_no_change":false,"label":"to graze","letter":"D"}]', 'A', '{"A":"Keeps a finite main verb, so the sentence remains complete.","B":"Swaps the verb for a participle, leaving the subject with no main verb.","C":"Buries the only verb inside a relative clause, so nothing is left to complete the sentence.","D":"Replaces the verb with an infinitive, which cannot serve as a sentence''s main verb."}', 'A sentence needs a **finite main verb**, and the original is the only version that provides one.', '''Grazing'' paints an appealing picture and sounds fluid aloud, masking that it strands the subject.', '1) Find the subject. 2) Ask: what does the subject *do*—is there a verb with tense? 3) Words ending in -ing or starting with ''to'' don''t count as main verbs by themselves. 4) If no tensed verb survives, it''s a fragment—restore one.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c719811dfc75cf51', 'act-english', 's-sent', 2, 'The morning forecast promised unbroken <u>sunshine, the</u> picnic committee left every tent and tarp at home.', 'Which choice most effectively joins the two statements?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"sunshine, however, the","letter":"B"},{"is_no_change":false,"label":"sunshine the","letter":"C"},{"is_no_change":false,"label":"sunshine, so the","letter":"D"}]', 'D', '{"A":"A comma alone joins two complete statements — a comma splice (misconception: short clauses may share a comma).","B":"''However'' is an adverb, not a conjunction, so the splice remains — and the logic even turns contrastive (misconception: a transition word equals a connector).","C":"Deleting the comma fuses the clauses into a run-on (misconception: removing the flagged comma fixes the join).","D":"Correct: a comma plus the coordinating conjunction links the clauses and states the cause-effect logic."}', 'A comma plus a **coordinating conjunction** legally joins two independent clauses — and this one supplies the cause-and-effect link.', '''However'' looks like a strong connector, so the splice hides behind its formality.', '1) Confirm both sides could stand as sentences. 2) List the legal joins: period, semicolon, comma + coordinating conjunction, or subordinating one clause. 3) Match the join to the logic between the clauses. 4) Reject comma-alone and adverb-with-commas joins. 5) Re-read the repaired sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d63965aa448e8aaf', 'act-english', 's-sent', 2, 'Mangrove roots and seagrass meadows act as nurseries for the <u>reef. Providing</u> shelter and food for young fish until they are large enough for open water.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"reef, providing","letter":"B"},{"is_no_change":false,"label":"reef; providing","letter":"C"},{"is_no_change":false,"label":"reef, they providing","letter":"D"}]', 'B', '{"A":"The period leaves ''Providing shelter and food...'' as a fragment with no subject or main verb (misconception: participial_fragment).","B":"The comma attaches the participial phrase to the main clause, forming one complete sentence.","C":"A semicolon must be followed by an independent clause, but the participial phrase cannot stand alone (misconception: semicolon_before_fragment).","D":"''They providing'' is not a grammatical clause; the -ing form needs a helping verb to be a predicate (misconception: missing_auxiliary)."}', 'A comma links the **participial phrase** to the clause it modifies, curing the fragment.', 'The fragment is long and detailed, so it looks sentence-like enough to end with a period.', '1) Check whether each capital-to-period stretch is a complete sentence. 2) A group built on an -ing word with no subject and helping verb is a fragment. 3) Attach such a phrase to the neighboring clause with a comma. 4) Don''t use a period or semicolon to set off something that can''t stand alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-db66aa33f991f250', 'act-english', 's-sent', 2, 'Because oil-based ink dried slowly, <u>pressmen hung the printed sheets on ropes strung overhead</u>.', 'Which choice makes the sentence grammatically complete?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"pressmen hanging the printed sheets on ropes strung overhead","letter":"B"},{"is_no_change":false,"label":"the printed sheets hanging on ropes strung overhead","letter":"C"},{"is_no_change":false,"label":"with the printed sheets hung on ropes strung overhead","letter":"D"}]', 'A', '{"A":"''Pressmen hung'' supplies a subject and a finite verb, completing the sentence that the ''Because'' clause depends on.","B":"''Pressmen hanging'' has no finite verb, leaving the opening clause attached to a fragment.","C":"''Sheets hanging'' likewise lacks a finite verb; nothing in the sentence can stand alone.","D":"''With...'' is a prepositional phrase, so the sentence never gets a main clause at all."}', 'A sentence opening with a ''Because'' clause must be completed by an **independent clause** with a finite verb.', 'The -ing versions tempt because they sound fluid aloud, disguising the missing finite verb.', '1) Bracket the opening dependent clause. 2) Look at what remains and hunt for a subject plus a finite verb. 3) Remember that an -ing form or a ''with'' phrase alone does not count as finite. 4) If no finite verb remains, the sentence is a fragment — repair it. 5) Re-read the whole sentence from the start.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ec73492d19cea616', 'act-english', 's-sent', 2, 'From above, the bridge stringers looked perfectly sound, <u>and</u> rot had hollowed them out from below.', 'Which choice most logically connects the two parts of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"so","letter":"B"},{"is_no_change":false,"label":"for","letter":"C"},{"is_no_change":false,"label":"but","letter":"D"}]', 'D', '{"A":"*And* merely stacks the two facts as if they agree, missing the reversal between healthy appearance and hidden decay.","B":"*So* falsely claims the rot resulted from the stringers looking sound.","C":"*For* claims the rot explains the healthy appearance, reversing the actual logic.","D":"Correct: the hidden decay contradicts the sound appearance, and this conjunction signals exactly that opposition."}', 'The two clauses **contradict** each other — surface soundness versus hidden rot — so the contrast conjunction is required.', '*And* tempts students because both clauses are true facts about the stringers, hiding that the facts pull in opposite directions.', '1) Restate each clause''s idea in your own words. 2) Name the logical relationship between them: addition, result, reason, or contrast. 3) Match the conjunction to that relationship. 4) Reread to confirm the connector''s claim about the clauses is true.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fbab9de9458c9c07', 'act-english', 's-sent', 2, 'The candy thermometer is essential for <u>caramel work the sugar</u> passes through narrow temperature stages that the eye alone cannot judge.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"caramel work, because the sugar","letter":"B"},{"is_no_change":false,"label":"caramel work, the sugar","letter":"C"},{"is_no_change":false,"label":"caramel work the sugar,","letter":"D"}]', 'B', '{"A":"Fused sentence: two independent clauses run together with no punctuation or conjunction.","B":"Correct: a comma plus the subordinator ''because'' turns the second clause into a reason, joining the ideas cleanly.","C":"Comma splice: a lone comma cannot join two independent clauses.","D":"Misplaced comma: the comma lands inside the second clause and still fuses the two sentences."}', 'Two independent clauses need a real join; adding **''because''** subordinates the second clause and shows it is the reason.', 'The sentence reads smoothly aloud, so the missing boundary between the two clauses is easy to overlook.', '1) Find the subject-verb core on each side of the underline. 2) If both sides are complete sentences, you have a fused sentence. 3) Fix it with a period, a semicolon, a comma-plus-conjunction, or a subordinator. 4) A lone comma is never enough. 5) Reread to confirm the two clauses are now properly linked.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-010cbb92a190e0e6', 'act-english', 's-sent', 3, 'The waiter served a steak to the guest <u>that was cooked medium-rare.</u>', 'Which choice places the description next to the word it modifies?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to the guest, medium-rare being how it was cooked.","letter":"B"},{"is_no_change":false,"label":"that was cooked medium-rare to the guest.","letter":"C"},{"is_no_change":false,"label":"to the guest which had been medium-rare.","letter":"D"}]', 'C', '{"A":"Placed after ''guest'', the clause claims the guest was cooked medium-rare.","B":"The dangling absolute phrase is wordy and still sits away from ''steak''.","C":"Moving the clause beside ''steak'' correctly says the steak was cooked medium-rare.","D":"''Which'' after ''guest'' keeps the description attached to the wrong noun."}', 'A modifier attaches to the **nearest noun** — put it beside the word it truly describes.', 'The sentence''s meaning is obvious to a human, so the misplacement slips by.', 'Move a misplaced modifier so it sits directly next to the noun it modifies.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-09d5d55343810e6d', 'act-english', 's-sent', 3, 'The picking crew starts at the far end of the orchard each morning. <u>Filling canvas shoulder bags that empty through a chute into padded bins.</u>', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"They fill canvas shoulder bags that empty through a chute into padded bins.","letter":"B"},{"is_no_change":false,"label":"Filling canvas shoulder bags, which empty through a chute into padded bins.","letter":"C"},{"is_no_change":false,"label":"Canvas shoulder bags that empty through a chute into padded bins.","letter":"D"}]', 'B', '{"A":"''Filling'' is a participle with no subject or main verb, leaving a fragment.","B":"Correct: adding the subject ''they'' and a main verb turns the fragment into a complete sentence.","C":"Inserting a comma and ''which'' rearranges the fragment without giving it a subject or main verb.","D":"This version is a noun phrase with only a relative clause attached — still no main verb."}', 'A sentence requires a **subject** and a main verb; only this option supplies both.', 'The -ing phrase reads smoothly after the previous sentence, so the missing main verb goes unheard.', '1) Cover the previous sentence and read the underlined part alone. 2) Ask: who or what does something? 3) Find a main verb with tense, not an -ing form standing alone. 4) If either piece is missing, choose the version that supplies both.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-18702ebe60cf2373', 'act-english', 's-sent', 3, '<u>Racing to catch the train and forgetting her umbrella on the platform bench.</u>', 'Which choice turns the fragment into a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Racing to catch the train, and forgetting her umbrella on the platform bench.","letter":"B"},{"is_no_change":false,"label":"She raced to catch the train, forgetting her umbrella on the platform bench.","letter":"C"},{"is_no_change":false,"label":"Racing to catch the train; forgetting her umbrella on the platform bench.","letter":"D"}]', 'C', '{"A":"Two ''-ing'' phrases with no subject and no main verb never form a sentence.","B":"Inserting a comma and ''and'' still leaves the string subjectless and verbless.","C":"Adding the subject ''She'' and the verb ''raced'' supplies a complete main clause.","D":"A semicolon needs a complete clause on each side; both sides here are still fragments."}', 'A sentence needs a **subject and a finite verb** — an ''-ing'' phrase alone supplies neither.', 'The phrase is long and detailed, so it feels like a full sentence.', 'If the word group has no subject doing a real (finite) verb, it is a fragment — give it one.', 'underlined-span-mc', 'the phrase is long and detailed, so it feels like a full sentence', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-18cafb31f227122b', 'act-english', 's-sent', 3, 'In bench tests, the new intake''s grip strength consistently exceeded <u>the old design.</u>', 'Which choice makes the comparison logical and clear?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the old design''s slower rollers.","letter":"B"},{"is_no_change":false,"label":"what the old design was.","letter":"C"},{"is_no_change":false,"label":"that of the old design.","letter":"D"}]', 'D', '{"A":"Compares a strength measurement to an entire design, a category mismatch (illogical_comparison).","B":"Swaps in a physical part, so strength is still compared to an object rather than to a measurement (comparison_wrong_object).","C":"Substitutes a vague clause about the design''s identity instead of its strength (comparison_vague_clause).","D":"Correct: the stand-in phrase makes the sentence compare strength with strength."}', '**That of** makes the comparison logical: the new strength is measured against the strength of the old design.', 'The original sounds complete because everyday speech routinely compares a measurement to a thing.', '1) Name the two items the sentence compares. 2) Confirm they belong to the same category. 3) If they do not, insert ''that of'' or ''those of'' so the second item matches the first.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-28af8f2f93f40156', 'act-english', 's-sent', 3, 'The queen excluder keeps her below the honey supers <u>the metal grid lets</u> smaller workers pass while blocking her wider body.', 'Which choice best establishes the boundary between the two sentences?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"supers, the metal grid lets","letter":"B"},{"is_no_change":false,"label":"supers the metal grid, lets","letter":"C"},{"is_no_change":false,"label":"supers. The metal grid lets","letter":"D"}]', 'D', '{"A":"Runs two complete independent clauses together with no punctuation at all — a fused sentence.","B":"Inserts a comma between the two independent clauses, downgrading the fused sentence to a comma splice.","C":"Drops a comma inside the second clause, splitting its subject from its verb while still fusing the two clauses.","D":"Correct: a period ends the first complete statement and a capital opens the second, giving each independent clause its own sentence."}', 'Two independent clauses need a real boundary, and a **period** cleanly closes one sentence and starts the next.', 'The two clauses share a topic and flow together, so students read them as one sentence and leave them fused.', '1) Locate where the first complete thought ends. 2) Test whether what follows is also a complete thought with its own subject and verb. 3) If both are complete, put a period (or semicolon) at the boundary, not a comma or nothing. 4) Reject fixes that leave the clauses fused or joined by a comma alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2a4ce23acf7429a8', 'act-english', 's-sent', 3, 'The walk-in cooler failed on the hottest weekend of July<u>, so the family</u> hauled every tub of butter to a neighbor''s restaurant before sunrise.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", the family","letter":"B"},{"is_no_change":false,"label":"the family","letter":"C"},{"is_no_change":false,"label":", therefore the family","letter":"D"}]', 'A', '{"A":"Correct — a comma plus the coordinating conjunction ''so'' legally joins the two independent clauses.","B":"Joins two complete sentences with only a comma, creating a comma splice (comma_splice).","C":"Fuses the two complete sentences with no punctuation or conjunction at all (fused_sentence).","D":"''Therefore'' is a conjunctive adverb, not a conjunction, so a comma before it still splices the clauses (splice_conjunctive_adverb)."}', 'Two independent clauses may be joined by a comma **plus a coordinating conjunction**, which is exactly what the sentence does.', '''Therefore'' feels like a connector strong enough to justify a comma, but it lacks a conjunction''s joining power.', '1) Check each side of the junction: can it stand alone as a sentence? 2) If both can, they need a period, a semicolon, or comma + FANBOYS. 3) Treat words like ''therefore'' and ''however'' as adverbs — they need semicolon support. 4) Reread the join.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-36eb52579d0ef14b', 'act-english', 's-sent', 3, '<u>Walking to school, the rain soaked Jordan''s backpack.</u>', 'Which revision corrects the modifier error?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"As Jordan walked to school, the rain soaked his backpack.","letter":"B"},{"is_no_change":false,"label":"Walking to school, the rain quickly soaked Jordan''s backpack.","letter":"C"},{"is_no_change":false,"label":"Walking to school, Jordan''s backpack was soaked by the rain.","letter":"D"}]', 'B', '{"A":"''Walking to school'' has nothing to modify but ''the rain'' — and rain doesn''t walk.","B":"Rewriting the modifier as a clause with its own subject (''As Jordan walked'') puts the walker in the sentence.","C":"Adding ''quickly'' changes nothing: the rain is still the one walking.","D":"Now the backpack is walking to school — the modifier still dangles."}', 'A modifier must attach to the noun that actually performs it — give ''walking'' its walker, **Jordan**.', 'Every option reads smoothly until you ask WHO is walking.', 'Ask who performs the opening modifier''s action; that noun must come immediately after the comma (or be given its own clause).', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4172495b435d0756', 'act-english', 's-sent', 3, 'The archive reading room closed at <u>five we</u> photographed the last ledger pages in the parking lot.', 'Which choice makes the underlined portion grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"five, we","letter":"B"},{"is_no_change":false,"label":"five, however we","letter":"C"},{"is_no_change":false,"label":"five. We","letter":"D"}]', 'D', '{"A":"Nothing separates the two independent clauses — a fused sentence.","B":"Substituting a comma converts the fused sentence into a comma splice, still illegal.","C":"''However'' is a conjunctive adverb, powerless to join clauses across a mere comma, and its contrast logic is wrong here besides.","D":"Correct: a period gives each independent clause its own sentence."}', 'A **period** legally separates the two complete statements that were fused together.', 'The comma version tempts because a pause clearly belongs at the seam, but a pause mark is not a boundary mark.', '1) Locate each subject-verb core. 2) Mark where the first complete thought ends. 3) At that seam, require a period, a semicolon, or a comma plus a coordinating conjunction. 4) Treat words like ''however'' as adverbs, not glue. 5) Choose the option that meets the requirement.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-569e859ddcb13e88', 'act-english', 's-sent', 3, 'Rivets once held the girders <u>together; today,</u> high-strength bolts do the same job.', 'Which choice results in a complete, correctly joined sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"together, today,","letter":"B"},{"is_no_change":false,"label":"together today,","letter":"C"},{"is_no_change":false,"label":"together; because today,","letter":"D"}]', 'A', '{"A":"The semicolon correctly joins two related independent clauses.","B":"A comma alone cannot join two independent clauses; this creates a comma splice (misconception: comma_splice).","C":"Runs the two clauses together with no punctuation at all, producing a fused sentence (misconception: fused_sentence).","D":"Adding ''because'' subordinates the second half, stranding a fragment after the semicolon (misconception: semicolon_plus_subordinator)."}', 'A **semicolon** legally joins two independent clauses, and both halves here can stand alone as sentences.', 'The comma version sounds natural read aloud, so students accept the splice because the pause feels right even though the join is illegal.', '1) Find the junction between the two statements. 2) Test each side: can it stand alone as a sentence? 3) If both can, they need a period, a semicolon, or a comma plus coordinating conjunction. 4) Reject any join that uses a comma alone or nothing. 5) Reread to confirm both sides keep their independence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5874194bff4953f6', 'act-english', 's-sent', 3, 'Hoping to spark a late-season rally, <u>the manager shuffled the batting order</u> ahead of Friday''s doubleheader.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the batting order was shuffled by the manager","letter":"B"},{"is_no_change":false,"label":"the manager''s batting order was shuffled","letter":"C"},{"is_no_change":false,"label":"a shuffle of the batting order was made by the manager","letter":"D"}]', 'A', '{"A":"Correct: ''the manager,'' the one doing the hoping, immediately follows the introductory modifier.","B":"The passive rewrite makes ''the batting order'' the subject, but an order cannot hope — dangling modifier (dangling_passive).","C":"A possessive is not a doer; the head noun is still the order, so the modifier dangles (possessive_not_subject).","D":"Nominalizes the action and buries the doer at the end, leaving the modifier dangling and the sentence bloated (dangling_nominalization)."}', 'An introductory modifier must be followed **immediately** by the person it describes, and the hopeful manager is right there as written.', 'The passive version keeps the manager in the sentence, so students assume the modifier is still anchored even though the subject changed.', '1) Find the opening modifier and ask who performs it (who is hoping?). 2) Look at the noun right after the comma. 3) If that noun is not the performer, the modifier dangles. 4) Reject possessives and passives that displace the performer. 5) Choose the version whose subject is the performer.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5f5a0832e3e835b3', 'act-english', 's-sent', 3, 'A colony of free-tailed bats <u>emerging each summer evening from the expansion joints</u> of the interstate bridge.', 'Which choice makes this a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"that emerges each summer evening from the expansion joints","letter":"B"},{"is_no_change":false,"label":"emerging, each summer evening, from the expansion joints","letter":"C"},{"is_no_change":false,"label":"emerges each summer evening from the expansion joints","letter":"D"}]', 'D', '{"A":"The -ing participle only describes the colony; no finite verb ever asserts anything, leaving a fragment (participle_as_main_verb).","B":"The relative pronoun buries the only conjugated verb inside a description, so the sentence still makes no claim (relative_clause_fragment).","C":"Commas rearrange the pauses but cannot promote a participle into a main verb (punctuation_fixes_fragment).","D":"Correct: the finite verb gives the subject a genuine predicate, completing the sentence."}', 'A sentence needs a **finite main verb**, and only this option lets the subject actually do something rather than just be described.', 'The original sounds complete because it is long and detailed, so students mistake descriptive weight for a working predicate.', '1) Find the subject. 2) Hunt for a conjugated verb that makes a claim about it — an -ing form alone never counts. 3) If every verb is inside a ''that/which'' clause, it serves the noun, not the sentence. 4) Choose the option whose verb directly serves the subject. 5) Re-read and ask: what does the subject do?', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-60d11553962fd438', 'act-english', 's-sent', 3, 'Covered in dust and cobwebs, <u>Maya discovered the old bicycle</u> in the back of the shed.', 'Which choice makes the opening description modify the right noun?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the old bicycle appeared to Maya","letter":"B"},{"is_no_change":false,"label":"Maya found that the old bicycle was","letter":"C"},{"is_no_change":false,"label":"the old bicycle was discovered by Maya","letter":"D"}]', 'D', '{"A":"The opening phrase lands on ''Maya'', saying she was covered in dust and cobwebs.","B":"''Appeared to Maya'' is vague and changes the action from discovering to seeming.","C":"This buries ''bicycle'' in a that-clause, so the phrase still points at Maya.","D":"Making ''the old bicycle'' the subject right after the comma lets the dusty description land on it."}', 'The noun an opening modifier describes must be the **subject that follows the comma** — the bicycle, not Maya.', 'We know the bicycle was dusty, so the sentence ''sounds'' fine despite the misattachment.', 'After an opening descriptive phrase, the very next noun must be the thing it describes.', 'underlined-span-mc', 'we know the bicycle was dusty, so the sentence ''sounds'' fine despite…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-66617fd8e162d976', 'act-english', 's-sent', 3, 'Scanning the ridgeline for the shadow of a circling hawk, <u>the ground squirrel froze</u> at the mouth of its burrow.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the burrow offered no cover","letter":"B"},{"is_no_change":false,"label":"there was a sudden, wary stillness","letter":"C"},{"is_no_change":false,"label":"freezing in place seemed the only choice","letter":"D"}]', 'A', '{"A":"Correct: the squirrel is the one scanning, so it correctly follows the opening modifier as the subject.","B":"Makes ''the burrow'' the scanner, but a burrow cannot scan a ridgeline (dangling_modifier).","C":"Supplies no actor at all for the opening phrase, leaving the modifier dangling (dangling_modifier).","D":"Puts an abstract idea in the subject slot, so ''scanning'' has no logical doer (dangling_modifier)."}', 'An opening -ing modifier must be followed by the **noun that performs its action**, and only the squirrel can do the scanning.', 'Each rewrite sounds smooth on its own, so students judge the fragment in isolation and miss that the opening phrase needs a specific doer.', '1) Read the opening modifier and ask who or what is doing that action. 2) Look at the noun that starts the main clause. 3) Check that this noun could logically perform the modifier''s action. 4) If it cannot, the modifier dangles. 5) Keep the version whose subject truly does the opening action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-67029ad62f4959d5', 'act-english', 's-sent', 3, 'Selenium toner deepens a print''s <u>shadows, it also protects</u> the silver image from fading over decades of display.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shadows, therefore it also protects","letter":"B"},{"is_no_change":false,"label":"shadows it also protects","letter":"C"},{"is_no_change":false,"label":"shadows, and it also protects","letter":"D"}]', 'D', '{"A":"Joins two independent clauses with only a comma (comma_splice).","B":"Places a conjunctive adverb after a bare comma (conjunctive_adverb_splice), which still leaves the clauses unjoined and falsely signals cause-effect.","C":"Deletes the comma without adding a connector (comma_delete_fuse), turning the splice into a fused sentence.","D":"Correct: a comma plus the coordinating conjunction ''and'' legally joins the two independent clauses."}', 'A comma plus the **coordinating conjunction** ''and'' is a legal junction between two independent clauses.', '''Therefore'' feels like a strong connector, so students accept it after a comma without realizing conjunctive adverbs cannot join clauses.', '1) Test each side of the junction for independence by reading it alone. 2) If both sides are independent, require one of: a period, a semicolon, or a comma plus a coordinating conjunction (FANBOYS). 3) Treat conjunctive adverbs like ''therefore'' and ''however'' as impostors — after a comma they still leave a splice. 4) Re-read the sentence with your junction installed to confirm it holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6c98a72fa1eba93a', 'act-english', 's-sent', 3, '<u>The dough had proofed for twelve hours, so it collapsed</u> the moment the baker slid it onto the peel.', 'Which choice most logically expresses the relationship between the two clauses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The dough had proofed for twelve hours, and it collapsed","letter":"B"},{"is_no_change":false,"label":"Because the dough had over-proofed for twelve hours, it collapsed","letter":"C"},{"is_no_change":false,"label":"The dough had proofed for twelve hours, but it collapsed","letter":"D"}]', 'C', '{"A":"Weak logic: ''so'' implies twelve hours of proofing naturally causes collapse, but only over-proofing does, which the original never states.","B":"Mere sequence: ''and'' just lists the two facts without showing that over-proofing caused the collapse.","C":"Correct: ''Because ... over-proofed'' names the true cause and subordinates it, making the collapse a clear consequence.","D":"Wrong logic: ''but'' signals contrast, yet the collapse follows from the proofing rather than opposing it."}', 'The collapse is caused by **over-proofing**, so subordinating that cause with ''Because'' states the relationship precisely.', '''So'' does gesture at cause and effect, so it feels close enough even though it skips the crucial ''over'' that makes the logic true.', '1) Identify the two clauses and the real relationship between them: cause, contrast, or simple sequence. 2) Check that the cause stated is actually sufficient to produce the effect. 3) Choose the connector that names that exact relationship. 4) Prefer subordination when one clause explains the other. 5) Reread to confirm the logic holds.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6cbc25a928512301', 'act-english', 's-sent', 3, '<u>Because the roof leaked during the thunderstorm, the librarians rolled</u> the rare-book carts into an interior hallway.', 'Which choice provides the clearest and most grammatical sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The roof leaked during the thunderstorm, the librarians rolled","letter":"B"},{"is_no_change":false,"label":"Because the roof leaked during the thunderstorm, so the librarians rolled","letter":"C"},{"is_no_change":false,"label":"Because the roof leaking during the thunderstorm, the librarians rolled","letter":"D"}]', 'A', '{"A":"Correct: a subordinate cause clause is properly attached to a complete main clause.","B":"Removing the subordinator leaves two independent clauses joined by only a comma — a splice.","C":"Doubles the connector: with both ''Because'' and ''so,'' no independent clause remains.","D":"The ''-ing'' form ''leaking'' leaves the subordinate clause without a finite verb."}', 'One **subordinating conjunction** marks the cause clause, which then leans on a complete main clause — exactly the required structure.', '''Because … so'' mirrors how many students speak, so the double connector sounds natural even though it strands both clauses.', '1) Identify the cause and the effect. 2) Mark the relationship with exactly one connector — a subordinator on the cause or a coordinator between clauses, never both. 3) Confirm the subordinate clause has a tensed verb. 4) Confirm one clause can still stand alone. 5) Re-read the full sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6d91eff7afa36eb2', 'act-english', 's-sent', 3, 'The observation hive sits against a south window, <u>visitors watch</u> the workers build comb in real time.', 'Which choice most effectively repairs the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"visitors, watch","letter":"B"},{"is_no_change":false,"label":"where visitors watch","letter":"C"},{"is_no_change":false,"label":"visitors; watching","letter":"D"}]', 'C', '{"A":"Joins two independent clauses with only a comma, producing a comma splice.","B":"Adds a stray comma after ''visitors'' but leaves the two independent clauses spliced together.","C":"Correct: ''where'' turns the second clause into a subordinate clause, so a single comma now correctly joins a main clause to a modifier.","D":"Uses a semicolon before an ''-ing'' form, but a semicolon requires a complete independent clause on its right, and ''watching…'' is not one."}', 'Turning the second clause into a **subordinate** clause with ''where'' cures the splice, so one clause depends on the other.', 'The original reads smoothly as two related facts, so students hear one flowing sentence and miss that two complete clauses are spliced by a comma.', '1) Split the sentence at the comma and test each side for a subject and verb. 2) If both sides are independent clauses joined only by a comma, it is a splice. 3) Fix it by subordinating one clause, adding a coordinating conjunction, or using a semicolon or period. 4) Reject any fix that still leaves two independent clauses joined by a comma alone or misuses a semicolon.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-704d2014469d256d', 'act-english', 's-sent', 3, '<u>Piping the last row of rosettes, the oven timer startled Junia</u>, and the icing bag slipped across the cake board.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Piping the last row of rosettes, Junia''s grip was loosened by the oven timer","letter":"B"},{"is_no_change":false,"label":"Piping the last row of rosettes, the oven timer''s buzz startled Junia","letter":"C"},{"is_no_change":false,"label":"As Junia piped the last row of rosettes, the oven timer startled her","letter":"D"}]', 'D', '{"A":"The opening phrase attaches to ''the oven timer,'' absurdly making the timer the one piping (dangling_modifier).","B":"''Junia''s grip'' is a thing, not a person, so the piping phrase still has no doer to attach to (dangling_possessive).","C":"Swapping in ''the oven timer''s buzz'' leaves the modifier dangling — a buzz cannot pipe rosettes (dangling_new_noun).","D":"Correct — converting the phrase to a clause with its own subject puts Junia at the piping and the timer at the startling."}', 'Giving the opening idea its own **subject and verb** removes the dangling phrase entirely, so nothing attaches to the wrong noun.', 'The possessive fix puts Junia''s name right after the comma, which looks like a repair even though ''grip'' is the actual head noun.', '1) Find the opening verbal phrase. 2) Ask: who is doing that action? 3) Check the noun right after the comma — it must be that doer. 4) If it is not, either move the doer there or rewrite the phrase as a full clause. 5) Reread for sense.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-71f061e6a4b8490f', 'act-english', 's-sent', 3, '<u>Barnacles strain food from the passing water with delicate, feathery legs.</u>', 'Which choice is a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Barnacles straining food from the passing water with delicate, feathery legs.","letter":"B"},{"is_no_change":false,"label":"Because barnacles strain food from the passing water with delicate, feathery legs.","letter":"C"},{"is_no_change":false,"label":"Which strain food from the passing water with delicate, feathery legs.","letter":"D"}]', 'A', '{"A":"Correct: the subject and a full verb form a complete, independent sentence.","B":"The -ing form is a participle, not a finite verb, so the group of words is a fragment.","C":"''Because'' turns the clause into a dependent fragment that cannot stand alone.","D":"''Which'' opens a relative clause with no main clause, leaving a fragment."}', 'A complete sentence needs a subject and a **finite verb**, and both are present here.', 'The -ing version reads like an action, so students mistake the participle for a working verb.', '1) Find the subject. 2) Find the main verb and check it is finite, not an -ing or -ed form alone. 3) Make sure no word like ''because'' or ''which'' leaves the clause dependent. 4) Confirm the words can stand alone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-755b08c8dfb0ddf1', 'act-english', 's-sent', 3, 'The lifespan of a Greenland shark far exceeds <u>a bowhead whale.</u>', 'Which choice makes the comparison logical and grammatically correct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"that of a bowhead whale.","letter":"B"},{"is_no_change":false,"label":"those of a bowhead whale.","letter":"C"},{"is_no_change":false,"label":"a bowhead whale''s.","letter":"D"}]', 'B', '{"A":"Compares a lifespan directly to an animal, mismatching a duration with a creature (illogical_comparison).","B":"Correct: ''that of'' supplies a singular stand-in so lifespan is compared with lifespan.","C":"''Those'' is plural and cannot replace the singular ''lifespan'' (comparison_number).","D":"The possessive is left with no noun after it, so the comparison stays incomplete (dangling_possessive)."}', 'A logical comparison must weigh **like against like**, so a singular stand-in for ''lifespan'' is required.', 'The bare noun reads smoothly, so students accept comparing a lifespan to a whale without noticing the mismatch.', '1) Identify the two things being compared. 2) Make sure both are the same kind of thing. 3) If one side names a quality of a noun, use ''that of'' (singular) or ''those of'' (plural) to match it. 4) Confirm the stand-in agrees in number.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-76413bf5bdb571a7', 'act-english', 's-sent', 3, 'William Caslon knew buyers could not judge a typeface from loose letters<u> he therefore printed</u> broadside specimen sheets displaying every size he cast.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", he therefore printed","letter":"B"},{"is_no_change":false,"label":". He therefore printed","letter":"C"},{"is_no_change":false,"label":"; therefore printing","letter":"D"}]', 'C', '{"A":"With no punctuation, two complete statements are fused into a run-on.","B":"A comma cannot join two independent clauses; ''therefore'' is an adverb, not a conjunction, so this is a splice.","C":"A period ends the first complete statement and lets the second begin cleanly.","D":"After the semicolon, ''therefore printing'' has no subject or finite verb — a fragment."}', 'Two independent clauses need a full **boundary** — here a period cleanly separates them.', 'The comma version tempts because ''therefore'' feels strong enough to carry the joint, but adverbs cannot join clauses.', '1) Locate where one complete thought ends and another begins. 2) Check each side for its own subject and finite verb. 3) Join two independents only with a period, a semicolon, or a comma plus a coordinating conjunction. 4) Confirm any words after the mark still form a complete clause. 5) Re-read both statements.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-764a6f35897d96e7', 'act-english', 's-sent', 3, 'A sparse network of microphones listens for <u>infrasound. Which travels</u> hundreds of kilometers through the atmosphere and can betray an eruption at a peak no one is watching.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"infrasound; which travels","letter":"B"},{"is_no_change":false,"label":"infrasound, which travels","letter":"C"},{"is_no_change":false,"label":"infrasound. Traveling","letter":"D"}]', 'C', '{"A":"The period strands a ''which'' clause on its own — a fragment with no independent clause.","B":"A semicolon, like a period, must be followed by an independent clause, and a ''which'' clause is not one.","C":"Correct: a comma attaches the nonrestrictive relative clause to the noun it describes.","D":"After the period there is still no subject or finite main verb — the fragment survives in new clothes."}', 'A relative clause cannot stand alone; a **comma** must attach it to the noun it modifies.', 'Swapping the period for a semicolon feels like a fix, but a semicolon carries the very same requirement the period does.', '1) Read what follows each end-stop as if it were alone: subject? finite verb? complete thought? 2) A clause beginning with a relative pronoun can''t stand alone. 3) Attach dependent add-ons to the noun they describe with a comma. 4) Re-read the joined sentence to confirm one complete main clause remains.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7844e247db8e8b97', 'act-english', 's-sent', 3, 'Hoping to finish before closing time, <u>the cart of returned novels was pushed by Mara</u> toward the fiction aisles.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the cart of returned novels was moved by Mara","letter":"B"},{"is_no_change":false,"label":"Mara pushed the cart of returned novels","letter":"C"},{"is_no_change":false,"label":"Mara''s cart of returned novels was pushed","letter":"D"}]', 'C', '{"A":"The opening modifier attaches to ''the cart,'' but a cart cannot hope — the modifier dangles.","B":"Swapping the verb leaves the same inanimate subject after the comma, so the modifier still dangles.","C":"Correct: the person who was hoping now sits directly after the comma, so the modifier attaches logically.","D":"The possessive buries the person inside the noun phrase; the grammatical subject is still the cart."}', 'An opening modifier must describe the **first noun after the comma**, and only this option puts the hopeful person there.', 'The possessive version mentions the person early, so students believe the modifier has something human to attach to.', '1) Find the opening modifier and ask who performs it. 2) Look at the first noun after the comma. 3) If that noun is not the performer, the modifier dangles. 4) Rewrite so the performer sits immediately after the comma. 5) Re-read the pair to confirm the match.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-829e5962e71820d5', 'act-english', 's-sent', 3, '<u>Strumming a borrowed guitar, the audience was quickly won over by the teenage singer.</u>', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Strumming a borrowed guitar, the audience found the teenage singer impossible to resist.","letter":"B"},{"is_no_change":false,"label":"The teenage singer, strumming a borrowed guitar, the audience was quickly won over.","letter":"C"},{"is_no_change":false,"label":"Strumming a borrowed guitar, the teenage singer quickly won over the audience.","letter":"D"}]', 'D', '{"A":"The opening phrase attaches to ''the audience,'' absurdly making the crowd the guitarist.","B":"Rewords the ending but still hands the guitar to the audience.","C":"Stacks the singer before a full clause about the audience, leaving the singer grammatically adrift.","D":"Correct: the doer of the strumming — the singer — stands immediately after the modifier."}', 'An opening participial phrase must be followed **immediately** by its doer, and only this version puts the singer there.', 'The original tempts students because the intended meaning is obvious, so the grammatical misattachment slips past the ear.', '1) Find the opening ''-ing'' phrase and ask: who performs this action? 2) Look at the first noun after the comma. 3) If that noun is not the performer, the modifier dangles. 4) Rearrange so the performer directly follows the comma. 5) Re-read to confirm every noun does what the sentence says it does.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-856529950b4dea4e', 'act-english', 's-sent', 3, 'In its final issue of the year, the Courier endorsed the school <u>bond, and its editorial board</u> had opposed the same measure only a year earlier.', 'Which choice most effectively signals the logical relationship between the two clauses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"bond, so its editorial board","letter":"B"},{"is_no_change":false,"label":"bond even though its editorial board","letter":"C"},{"is_no_change":false,"label":"bond, for its editorial board","letter":"D"}]', 'C', '{"A":"''And'' treats a striking reversal as mere addition, hiding the tension between the clauses.","B":"''So'' claims this year''s endorsement caused last year''s opposition — backward causation.","C":"Correct: it subordinates the earlier opposition as a concession, capturing the surprising reversal.","D":"''For'' asserts the old opposition was the reason for endorsing, which inverts the logic."}', 'The clauses pull against each other, so the joint must signal **concession** — an endorsement made despite the board''s earlier opposition.', '''And'' tempts students because it is never ungrammatical, so the flattened logic slips past them.', '1) State each clause''s point in plain words. 2) Name the logical link: addition, cause, result, or concession/surprise. 3) Pick the connector built for that link. 4) Watch direction: cause words point from reason to result. 5) Re-read to confirm the connector matches the meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8e86623f53154733', 'act-english', 's-sent', 3, '<u>Although the batik workshop lost power, so the artisans</u> continued waxing cloth by lantern light.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Although the batik workshop lost power, but the artisans","letter":"B"},{"is_no_change":false,"label":"Although the batik workshop lost power, the artisans","letter":"C"},{"is_no_change":false,"label":"The batik workshop lost power, although the artisans","letter":"D"}]', 'C', '{"A":"''Although'' already links the clauses, so adding ''so'' doubles the connectors and leaves no true main clause.","B":"''But'' duplicates the contrast that ''although'' has already established.","C":"Correct: one subordinator is all the sentence needs; the main clause follows cleanly.","D":"Moving ''although'' to the second clause claims the artisans'' persistence is the concession, inverting the logic."}', 'A subordinate clause needs exactly **one** connector; ''although'' alone carries the contrast.', '''But'' tempts because the contrast feels like it needs reinforcing — English marks it only once.', '1) Underline every connecting word (although, but, so, because). 2) Count the clauses. 3) Allow one connector per clause pair. 4) Delete extras. 5) Check that the subordinator sits on the clause being conceded.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97d774beb5f6168c', 'act-english', 's-sent', 3, 'Resin-coated paper dries flat in <u>minutes fiber paper</u> can curl for a whole day unless it is pressed.', 'Which choice best punctuates the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"minutes, fiber paper","letter":"B"},{"is_no_change":false,"label":"minutes; fiber paper","letter":"C"},{"is_no_change":false,"label":"minutes; although fiber paper","letter":"D"}]', 'C', '{"A":"Lets two independent clauses touch with no boundary at all (fused_sentence).","B":"Swaps the missing boundary for a bare comma (comma_splice), which is still too weak to join two independent clauses.","C":"Correct: a semicolon legally joins the two related independent clauses.","D":"Adds ''although'' after the semicolon (semicolon_fragment), demoting the second clause when the semicolon demands independence on both sides."}', 'A **semicolon** legally joins the two related independent clauses about the two kinds of paper.', 'The comma version matches the small pause readers hear between the two claims, so the splice sneaks past anyone trusting the ear.', '1) Read each side of the boundary alone and label it independent or dependent. 2) Two independent clauses need a period, a semicolon, or a comma plus a coordinating conjunction. 3) If a subordinating word appears, re-test the demoted side — a semicolon cannot precede a dependent clause. 4) Pick the boundary that matches your labels and re-read.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9b824ee4a3f416d0', 'act-english', 's-sent', 3, 'She <u>almost</u> drove her friends to every practice that season.', 'Which placement of the modifier fits the sentence''s likely meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"drove her friends almost to every practice","letter":"B"},{"is_no_change":false,"label":"drove almost her friends to every practice","letter":"C"},{"is_no_change":false,"label":"drove her friends to almost every practice","letter":"D"}]', 'D', '{"A":"''Almost drove'' means she nearly drove but didn''t — not the intended sense.","B":"''Almost to every practice'' suggests she never quite arrived.","C":"''Almost her friends'' nonsensically modifies who the friends were.","D":"''Almost every practice'' limits how many practices, which is what the sentence means."}', 'Place a limiting word like *almost* **directly before the word it limits** — here, ''every practice''.', '''Almost'' drifts to the front in speech, even when it belongs deeper in the sentence.', 'only / almost / just / even modify whatever immediately follows them — position them there.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a21d18bcf0091601', 'act-english', 's-sent', 3, '<u>Although the flood ruined the storefront''s tin ceiling, the</u> family reopened the bakery within six weeks.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Because the flood ruined the storefront''s tin ceiling, the","letter":"B"},{"is_no_change":false,"label":"The flood ruined the storefront''s tin ceiling, the","letter":"C"},{"is_no_change":false,"label":"Although the flood ruined the storefront''s tin ceiling, but the","letter":"D"}]', 'A', '{"A":"Correct — ''Although'' concedes the setback, logically setting up the surprising quick reopening.","B":"''Because'' claims the flood caused the reopening, reversing the logic (subordinator_wrong_logic).","C":"Removing the subordinator leaves two independent clauses joined by a comma — a splice (splice_dropped_subordinator).","D":"Doubles the connection with both ''Although'' and ''but,'' so the contrast is marked twice and no main clause remains (double_connector)."}', 'The sentence needs a **concession**: despite the flood''s damage, the family reopened fast — exactly what ''Although'' signals.', '''Although … but'' mirrors how some speakers talk, so the doubled contrast can sound natural to the ear.', '1) Identify the logical relationship between the clauses (cause, contrast, concession, time). 2) Pick one connector that encodes it. 3) Never stack a subordinator and a coordinator on the same pair of clauses. 4) Confirm one clause remains fully independent.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a8a34a37d1e9304a', 'act-english', 's-sent', 3, 'The book drop jammed late on <u>Friday night it stayed</u> full until the Monday crew pried it open.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Friday night, and it stayed","letter":"B"},{"is_no_change":false,"label":"Friday night, it stayed","letter":"C"},{"is_no_change":false,"label":"Friday night; it staying","letter":"D"}]', 'B', '{"A":"Fuses two independent clauses together with no punctuation or conjunction at all.","B":"Correct: a comma plus the coordinating conjunction legally joins the two independent clauses.","C":"A comma alone between two independent clauses creates a comma splice.","D":"The semicolon is a legal joiner, but ''it staying'' has no finite verb, leaving a fragment on the right side."}', 'Two independent clauses require a **comma plus a coordinating conjunction**, a semicolon, or a period — this option supplies the first.', 'The comma-only version sounds like a natural breath when read aloud, so students miss that both halves are complete sentences.', '1) Find each subject-verb pair and test whether each half could stand alone. 2) If both halves are independent, check the joint. 3) Accept only a period, a semicolon, or a comma plus a coordinating conjunction. 4) Reject bare contact or a lone comma. 5) Confirm both sides still have finite verbs after the fix.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a97a39b3359bc8bb', 'act-english', 's-sent', 3, '<u>Crouching behind a driftwood log, the photographer</u> waited for the snowy plover to lead its chicks across the open sand.', 'Which choice results in the clearest, most logical sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Crouching behind a driftwood log, the photographer''s camera","letter":"B"},{"is_no_change":false,"label":"Crouching behind a driftwood log, there was a photographer who","letter":"C"},{"is_no_change":false,"label":"A driftwood log, which the photographer crouched behind,","letter":"D"}]', 'A', '{"A":"Correct: the doer of the crouching — the photographer — sits immediately after the modifier.","B":"Makes the camera the croucher; the possessive pushes the true doer out of the subject slot.","C":"Parks the empty placeholder ''there'' where the doer belongs, leaving the modifier dangling.","D":"Hands the main verb to the log, so a piece of driftwood ends up waiting for the plover."}', 'An opening participial phrase must be followed **immediately** by the noun performing it — here, the photographer.', 'The possessive version keeps the word ''photographer'' visible, so students miss that the grammatical subject has become the camera.', '1) Find the opening action phrase. 2) Ask who or what performs that action. 3) Check the first noun after the comma. 4) If they do not match, the modifier dangles. 5) Also confirm the main clause''s subject can logically do the main verb.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ae31c054438bee1d', 'act-english', 's-sent', 3, '<u>Working frame by frame for nearly three months, the mural of galloping horses slowly took shape under the animator''s brush.</u>', 'Which choice best corrects the underlined sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Working frame by frame for nearly three months, the mural of galloping horses was slowly painted by the animator.","letter":"B"},{"is_no_change":false,"label":"Working frame by frame for nearly three months, the animator slowly painted the mural of galloping horses.","letter":"C"},{"is_no_change":false,"label":"The mural of galloping horses, working frame by frame for nearly three months, slowly took shape under the animator''s brush.","letter":"D"}]', 'C', '{"A":"The opening phrase dangles: the mural, not a person, ends up doing the ''working.''","B":"The passive rewrite still parks ''the mural'' next to the modifier, so the dangler survives.","C":"The doer — the animator — now directly follows the introductory phrase, which finally modifies the right noun.","D":"Relocating the phrase beside ''the mural'' still attaches the working to the artwork rather than the artist."}', 'An opening participial phrase must be followed **immediately by its doer**, and only here is that the animator.', 'Adding ''by the animator'' names the artist, so the passive version feels fixed even though the modifier still grabs the mural.', '1) Find the opening (or movable) modifier. 2) Ask who or what performs its action. 3) Check the noun right next to the modifier. 4) If they do not match, choose the version that puts the true doer beside the modifier.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b6c20ffb4a35c5e0', 'act-english', 's-sent', 3, 'By late morning the sun blazed straight down over the salt flats<u>, the sand grew</u> too scorching for even a lizard to cross.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":": the sand grew","letter":"B"},{"is_no_change":false,"label":"; the sand grew","letter":"C"},{"is_no_change":false,"label":"the sand grew","letter":"D"}]', 'C', '{"A":"Joins two complete independent clauses with only a comma, creating a comma splice (comma_splice).","B":"A colon should introduce an explanation or list, not link two equal independent clauses (colon_misuse).","C":"Correct: a semicolon properly links two closely related independent clauses.","D":"Removing all punctuation fuses the two independent clauses into a run-on (fused_sentence)."}', 'Two complete independent clauses of equal weight are correctly joined by a **semicolon**.', 'The comma marks the natural pause between the clauses, so students accept it without noticing that both sides could stand alone.', '1) Test each side of the junction: can it stand alone as a sentence? 2) If both can, they are independent clauses. 3) A comma alone cannot join them, and no punctuation fuses them. 4) Use a semicolon (or period, or comma-plus-conjunction) to join equal clauses. 5) Confirm the second clause is not merely explaining the first, which a colon would require.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c79b95bf8cca51b9', 'act-english', 's-sent', 3, 'The alarm from the tremor network sounded at 3 a.m.<u>, the</u> duty scientist reached the control room within four minutes.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", therefore the","letter":"B"},{"is_no_change":false,"label":", and the","letter":"C"},{"is_no_change":false,"label":"the","letter":"D"}]', 'C', '{"A":"Two independent clauses joined by only a comma form a comma splice.","B":"''Therefore'' is a conjunctive adverb, not a coordinating conjunction, so the splice remains.","C":"Correct: a comma plus the coordinating conjunction legally joins the two clauses.","D":"Deleting the comma fuses the two complete sentences with nothing between them."}', 'Two independent clauses may be joined by a comma **plus a coordinating conjunction** — that pairing repairs the splice.', '''Therefore'' feels like a connector, but it is an adverb, and with only a comma in front of it the splice survives.', '1) Confirm both sides of the boundary are independent clauses. 2) Legal joins: period; semicolon; comma + FANBOYS conjunction. 3) Remember that words like ''therefore'' and ''however'' are adverbs — with only a comma they still splice. 4) Apply one legal join and re-read.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-cfce6f60abd8e0e9', 'act-english', 's-sent', 3, 'Haleakala''s summit rises above the island''s cloud <u>layer. Which</u> means sunrise visitors look down on a rolling sea of white.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"layer; which","letter":"B"},{"is_no_change":false,"label":"layer, which","letter":"C"},{"is_no_change":false,"label":"layer: which","letter":"D"}]', 'C', '{"A":"Cuts the relative clause off as its own ''sentence,'' creating a fragment.","B":"A semicolon requires an independent clause on both sides, and the ''which'' clause is not one.","C":"Attaches the nonrestrictive ''which'' clause to the main clause with a comma, as required.","D":"A colon cannot introduce a relative clause that leans back on the sentence."}', 'A ''which'' clause is **dependent**—it must be attached to its sentence with a comma, not severed by end-stop punctuation.', 'The period version mimics a casual written style (''Which means...'') common in blogs and texts, so it looks familiar.', '1) Ask whether the words after the punctuation could stand alone as a sentence. 2) A clause beginning with a relative pronoun cannot. 3) Periods, semicolons, and colons all demand more independence than such a clause has. 4) Attach dependent add-ons with a comma.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d695906ab0114f7f', 'act-english', 's-sent', 3, '<u>Hoping to beat the heat, the hike started before sunrise.</u>', 'Which revision gives the opening phrase a subject that can perform its action?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Hoping to beat the heat, we started the hike before sunrise.","letter":"B"},{"is_no_change":false,"label":"Hoping to beat the heat, the hike was started before sunrise.","letter":"C"},{"is_no_change":false,"label":"The hike, hoping to beat the heat, started before sunrise.","letter":"D"}]', 'B', '{"A":"A hike cannot hope — the dangling phrase has no one to attach to.","B":"''We'' hoped and ''we'' started, so the phrase finally has a doer.","C":"The passive keeps ''the hike'' as subject, so the hike is still doing the hoping.","D":"Tucking the phrase mid-sentence still attaches ''hoping'' to ''the hike''."}', 'A dangling modifier needs a **subject capable of the action** placed right after it — a person can hope; a hike cannot.', 'The intended meaning is clear, so the impossible attachment is easy to miss.', 'Ask who performs the opening phrase''s action; make that noun the subject that follows the comma.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ebf6ba3010882c3e', 'act-english', 's-sent', 3, 'The fire lookout on Mount Harkness was built in <u>1933, and it</u> still shelters a volunteer spotter every summer.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"1933, it","letter":"B"},{"is_no_change":false,"label":"1933; and it","letter":"C"},{"is_no_change":false,"label":"1933, however, it","letter":"D"}]', 'A', '{"A":"Joins the two independent clauses correctly with a comma plus the coordinating conjunction ''and.''","B":"Drops the conjunction, leaving a comma splice.","C":"Stacks a semicolon on the conjunction, doubling the join.","D":"Treats ''however'' like a conjunction, but a conjunctive adverb set off by commas still leaves a splice."}', 'Comma **plus coordinating conjunction** is a legal weld between independent clauses—and it is already in place.', '''However'' feels like a strong connector, so students assume it can legally join clauses with commas alone.', '1) Confirm both sides are independent clauses. 2) Legal joins: period; semicolon; comma + FANBOYS. 3) Conjunctive adverbs (however, therefore) need a semicolon before them, not a comma. 4) Never combine a semicolon with a FANBOYS word.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ec19ebe2d58a698a', 'act-english', 's-sent', 3, 'Arriving an hour before the first round, <u>the veteran claimed her favorite table</u> beside the tall windows.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"her favorite table was claimed by the veteran","letter":"B"},{"is_no_change":false,"label":"the veteran''s favorite table was claimed","letter":"C"},{"is_no_change":false,"label":"it was the veteran who claimed her favorite table","letter":"D"}]', 'A', '{"A":"The person who arrived — the veteran — stands immediately after the opening modifier, exactly where the doer belongs.","B":"The passive makes the table the subject, so the opening phrase absurdly describes furniture arriving early.","C":"A possessive cannot serve as the doer; this version leaves no one performing the arrival.","D":"The placeholder ''it'' sits where the doer belongs, leaving the opening modifier dangling."}', 'The **doer of the opening modifier** — the veteran — correctly stands right after the comma.', 'The passive version tempts because every word is still present, obscuring that the subject slot now holds furniture instead of the person who arrived.', '1) Find the opening modifier and ask who performs its action. 2) Look at the noun immediately after the comma. 3) If that noun is not the performer, the modifier dangles. 4) Choose the version that puts the performer in the subject slot, then reread.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f1a9bd02d9424a66', 'act-english', 's-sent', 3, '<u>After studying all weekend, the exam felt easy to Priya.</u>', 'Which choice corrects the dangling modifier?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The exam, after studying all weekend, felt easy to Priya.","letter":"B"},{"is_no_change":false,"label":"After studying all weekend, the exam was easy for Priya.","letter":"C"},{"is_no_change":false,"label":"After studying all weekend, Priya found the exam easy.","letter":"D"}]', 'D', '{"A":"The exam did not study all weekend — the phrase dangles.","B":"Relocating the phrase keeps ''the exam'' as the studier.","C":"''The exam was easy'' still leaves the exam as the one who studied.","D":"''Priya'' both studied and found the exam easy, so the modifier attaches correctly."}', 'The doer of ''studying'' (Priya) must be the **subject right after the comma**.', 'Everyone knows Priya studied, so the sentence feels acceptable as written.', 'An introductory -ing/-ed phrase modifies the noun that immediately follows it — make that noun the actor.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f8d37c7f1a8d0af8', 'act-english', 's-sent', 3, 'Balancing carefully on the top rung of the ladder, <u>the technician angled the spotlight</u> toward center stage.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the spotlight was angled by the technician","letter":"B"},{"is_no_change":false,"label":"the spotlight''s angle was adjusted","letter":"C"},{"is_no_change":false,"label":"it was angled by the technician","letter":"D"}]', 'A', '{"A":"Correct: the person doing the balancing — the technician — immediately follows the introductory modifier.","B":"Placing the equipment after the comma makes the modifier claim the fixture is balancing on the ladder (dangling_subject).","C":"With only an angle being adjusted, nothing in the sentence can be the balancer, and the doer vanishes (dangling_subject + agent_deleted).","D":"The vague pronoun gives the modifier nothing concrete to attach to and hides what was angled (dangling_pronoun)."}', 'An introductory **modifier** must be followed immediately by the person or thing it describes, and only the original places the balancer there.', 'The passive version tempts students because it still names the technician later in the sentence, obscuring that the opening phrase now describes the equipment.', '1) Find the introductory phrase and ask who or what it describes. 2) Look at the first noun after the comma. 3) Require those two to match. 4) If they don''t, the modifier dangles — reject the option. 5) Also confirm the doer of the main action survives in the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ff836d1e3c8d4921', 'act-english', 's-sent', 3, '<u>Hoping to hear the championship broadcast, the radio was tuned by Marta</u> a full hour before airtime.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Hoping to hear the championship broadcast, the dial was set by Marta","letter":"B"},{"is_no_change":false,"label":"Hoping to hear the championship broadcast, Marta tuned the radio","letter":"C"},{"is_no_change":false,"label":"Hoping to hear the championship broadcast, Marta''s radio was tuned","letter":"D"}]', 'C', '{"A":"The opening modifier attaches to ''the radio,'' which cannot hope — a classic dangler.","B":"Swapping in ''the dial'' changes the noun but not the problem; a dial cannot hope either.","C":"Correct: the hoper, Marta, stands immediately after the modifier as the clause''s subject.","D":"A noun buried in a possessive cannot anchor the modifier; the subject is still the radio."}', 'An opening participial phrase must attach to the **very next noun**, so the person doing the hoping must be the subject of the main clause.', 'The possessive version tempts students because Marta''s name appears right after the comma, hiding that the true subject is still the radio.', '1) Read the opening phrase and ask who performs its action. 2) Look at the first noun after the comma. 3) If they don''t match, the modifier dangles. 4) Beware possessives: an owner inside another noun doesn''t count as the subject. 5) Choose the version whose after-the-comma noun is the true performer.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-063c456b53168b9d', 'act-english', 's-sent', 4, 'Demand for video relay interpreting has soared over the past decade<u>, the</u> national centers now schedule staff in overlapping around-the-clock shifts.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", consequently the","letter":"B"},{"is_no_change":false,"label":". The","letter":"C"},{"is_no_change":false,"label":"the","letter":"D"}]', 'C', '{"A":"A comma alone between two independent clauses is a comma splice.","B":"''Consequently'' is a conjunctive adverb, not a conjunction, so the clauses remain illegally spliced.","C":"Correct — a period cleanly separates the two independent clauses into two sentences.","D":"Removing the comma fuses the clauses with no boundary at all."}', 'Two independent clauses can be separated by a **period**; a bare comma or no mark at all cannot join them.', '''Consequently'' seems to supply the missing connection, but adverbs cannot legally join clauses across a comma.', '1) Test each side of the underlined punctuation as its own sentence. 2) If both pass, a bare comma is a splice. 3) List legal fixes: period, semicolon, or comma plus a FANBOYS word. 4) Match the options against the legal list and eliminate everything else.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0714c0f5e9650fc6', 'act-english', 's-sent', 4, '<u>Yellowed and brittle, my mother unfolded the telegram</u> that had announced her grandfather''s safe arrival in 1923.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Yellowed and brittle, my mother carefully unfolded the telegram","letter":"B"},{"is_no_change":false,"label":"My mother unfolded the yellowed, brittle telegram","letter":"C"},{"is_no_change":false,"label":"Yellowed and brittle, my mother''s hands unfolded the telegram","letter":"D"}]', 'C', '{"A":"The opening modifier attaches to ''my mother,'' absurdly describing her as yellowed and brittle.","B":"Adding ''carefully'' decorates the verb but leaves the modifier still pointing at the mother.","C":"Correct: moving the description next to ''telegram'' lets the adjectives modify the paper they describe.","D":"Shifting the description onto her hands still misassigns it; the document, not the hands, is aged."}', 'Adjectives must sit **next to the noun they describe**, so the description belongs beside the telegram.', 'The ''hands'' version tempts because hands touch the paper, so the image feels almost sensible while remaining misattached.', '1) Find the opening descriptive phrase. 2) Identify the first noun after the comma — that is what it modifies. 3) Ask whether that pairing makes sense. 4) If not, rearrange so describer and described are adjacent. 5) Re-read to confirm no new misattachment appears.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0786739d71ccafa4', 'act-english', 's-sent', 4, 'The window display changes with the <u>seasons in October the</u> mannequins wear flannel and carry paper lanterns.', 'Which choice best establishes the boundary between the sentence''s two statements?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"seasons, in October the","letter":"B"},{"is_no_change":false,"label":"seasons. In October, the","letter":"C"},{"is_no_change":false,"label":"seasons; while in October the","letter":"D"}]', 'C', '{"A":"Runs two complete statements together with no punctuation — a fused sentence.","B":"Substitutes a comma for the missing boundary, producing a comma splice.","C":"Correct: a period ends the first statement, and a comma sets off the introductory phrase ''In October.''","D":"''While'' turns the second half into a dependent clause, which a semicolon cannot legally precede."}', 'Two independent statements need a full **boundary** — here a period — plus a comma after the introductory time phrase.', 'A comma marks the pause the ear wants, so it masquerades as a sufficient boundary between the clauses.', '1) Locate where one complete thought ends and another begins. 2) Confirm both sides pass the stand-alone test. 3) Choose a boundary of legal strength: period, semicolon, or comma + coordinating conjunction. 4) Punctuate any introductory phrase that opens the second statement. 5) Re-read both statements separately.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-222802ddd1dc6f0a', 'act-english', 's-sent', 4, 'The platform interpreter wrapped up the keynote at noon<u>, then</u> she debriefed with the sound crew about the afternoon panels.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", then,","letter":"B"},{"is_no_change":false,"label":"then","letter":"C"},{"is_no_change":false,"label":"; then","letter":"D"}]', 'D', '{"A":"''Then'' is an adverb, not a conjunction, so a comma before it splices the two independent clauses.","B":"Wrapping ''then'' in commas adds a pause but leaves the same illegal splice in place.","C":"Dropping the comma fuses the clauses together with no boundary at all.","D":"Correct — a semicolon can join the two independent clauses, with ''then'' acting as an adverb in the second."}', 'Because ''then'' is **not** a coordinating conjunction, the clauses need a semicolon (or period) at the seam.', '''Then'' feels like ''and then,'' so students treat comma-plus-''then'' as a legal joint between clauses.', '1) Verify each side of the seam is an independent clause. 2) Ask whether the joining word is one of the seven FANBOYS. 3) ''Then,'' ''however,'' and ''therefore'' are adverbs — they need a semicolon or period before them. 4) Keep the option whose punctuation, not its adverb, does the joining.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-31e0a62ecc0b5a4f', 'act-english', 's-sent', 4, 'A good tour guide is patient, knowledgeable, and <u>speaks with enthusiasm</u>.', 'Which choice keeps the list of qualities parallel?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"enthusiastic","letter":"B"},{"is_no_change":false,"label":"has enthusiasm","letter":"C"},{"is_no_change":false,"label":"speaks enthusiastically","letter":"D"}]', 'B', '{"A":"''Patient'' and ''knowledgeable'' are adjectives; ''speaks with enthusiasm'' is a verb phrase, breaking the pattern.","B":"''Enthusiastic'' is an adjective, matching the first two items.","C":"''Has enthusiasm'' is a verb phrase, not an adjective.","D":"''Speaks enthusiastically'' is still a verb phrase, out of step with the adjectives."}', 'Every item in a series must share the **same grammatical form** — three adjectives here.', 'The verb phrase carries the same idea, so it feels interchangeable with an adjective.', 'Match each list item to the form the first items set — adjective with adjectives, noun with nouns, verb with verbs.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-338e392d0c46d1af', 'act-english', 's-sent', 4, '<u>Because</u> the forecast promised three days of clear weather, the crew postponed the traverse until the following week.', 'Which choice makes the relationship between the two parts of the sentence most logical?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Since","letter":"B"},{"is_no_change":false,"label":"Although","letter":"C"},{"is_no_change":false,"label":"Whenever","letter":"D"}]', 'C', '{"A":"''Because'' claims good weather caused the delay, which reverses common sense (cause where concession is needed).","B":"''Since'' makes the same causal claim in different clothing (synonym of the same error).","C":"The crew postponed despite favorable conditions — the concession this sentence needs.","D":"''Whenever'' turns a single decision into a recurring habit triggered by forecasts (time-trigger distortion)."}', 'The main clause acts **against** what the opening clause would predict, so the joint needs a concession word.', '''Because'' and ''since'' sound natural at the start of a clause, and readers accept the cause without testing its direction.', '1) Read the subordinate clause and predict what should follow. 2) Read the main clause and check: does it fulfill or defy the prediction? 3) Fulfilled → cause word; defied → concession word; repeated → time word. 4) Reread with your connector to verify the logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-41d49644ac23ae91', 'act-english', 's-sent', 4, 'Marisol refuses to price anything sight <u>unseen, she</u> inspects every seam and zipper herself.', 'Which of the following alternatives best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"unseen; she","letter":"B"},{"is_no_change":false,"label":"unseen she","letter":"C"},{"is_no_change":false,"label":"unseen, however she","letter":"D"}]', 'B', '{"A":"Two independent clauses fused with only a comma — a comma splice.","B":"Correct: the semicolon legally joins the two closely related independent clauses.","C":"Deleting the comma creates a fused sentence, an even harder crash between the clauses.","D":"''However'' is a conjunctive adverb, so a comma before it still leaves a splice — and the sentence''s logic isn''t contrastive."}', 'Independent clauses need a **period, semicolon, or comma plus coordinating conjunction** — the semicolon satisfies that here.', 'Removing the comma feels like removing the error, but no punctuation at all fuses the clauses even more tightly.', '1) Find the spot where two clauses meet. 2) Test each side for stand-alone completeness. 3) If both stand alone, pick from: period, semicolon, comma + coordinating conjunction. 4) Rule out bare commas, bare adverbs, and no punctuation. 5) Confirm the chosen joint preserves the sentence''s logic.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-466117fc76ab1be0', 'act-english', 's-sent', 4, 'Having spent weeks mailing a survey to every household in the annexation area, <u>the low response rate frustrated the planners</u>.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the response rate frustrated the planners with its lowness","letter":"B"},{"is_no_change":false,"label":"frustration over the low response rate grew among the planners","letter":"C"},{"is_no_change":false,"label":"the planners were frustrated by the low response rate","letter":"D"}]', 'D', '{"A":"The opening participial phrase attaches to ''the low response rate,'' which did not mail any surveys — a dangling modifier.","B":"Rewording the tail still leaves ''the response rate'' as the noun the opener grabs, so the dangle remains.","C":"''Frustration'' becomes the subject, but an emotion cannot have spent weeks mailing surveys either — the misconception that any rewrite fixes the problem.","D":"''The planners,'' the actual doers of the mailing, now follow the modifier directly, repairing the dangle."}', 'An introductory participial phrase must be followed immediately by its **doer** — the planners.', 'The original''s meaning is perfectly clear to the ear, so the structural mismatch goes unnoticed.', '1) Find the opening ''-ing'' or ''having'' phrase. 2) Ask who performed that action. 3) Check the first noun after the comma. 4) If the noun and the doer don''t match, the modifier dangles. 5) Re-choose or rewrite so the doer sits right after the comma, then re-read.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4dd2ac692ce2c62e', 'act-english', 's-sent', 4, '<u>Balanced on a narrow bat, Tomas carried the still-wet vase across the studio</u> while classmates cleared a path.', 'Which of the following provides the clearest, most logical version of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Balanced on a narrow bat, the studio watched Tomas carry the still-wet vase","letter":"B"},{"is_no_change":false,"label":"Tomas carried the still-wet vase, balanced on a narrow bat, across the studio","letter":"C"},{"is_no_change":false,"label":"Being balanced on a narrow bat, Tomas carried the still-wet vase across the studio","letter":"D"}]', 'C', '{"A":"The opening modifier grabs the first noun after it — Tomas — absurdly claiming the potter is balanced on the bat (dangling modifier).","B":"Recasting the subject as ''the studio'' hands the modifier an even less plausible owner (wrong noun promoted).","C":"Correct: the participial phrase now sits beside ''vase,'' the thing actually balanced on the bat.","D":"Adding ''being'' is cosmetic; the phrase still attaches to Tomas (surface fix, same dangler)."}', 'A modifier must sit **next to the noun it describes** — the vase, not the person carrying it.', 'Adding ''being'' makes the phrase sound more deliberate, so students believe the attachment problem has been repaired when it hasn''t.', '1) Find the modifying phrase. 2) Ask: who or what does it really describe? 3) Find the noun the phrase currently touches. 4) If the two don''t match, rearrange so the phrase sits beside its true owner. 5) Reread each option running the same touch test.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4f9ae62dd1f98376', 'act-english', 's-sent', 4, '<u>Inverting the tank every thirty seconds, fresh developer washes over</u> each frame of the film.', 'Which choice results in the clearest, most logical sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Inverting the tank every thirty seconds, it is ensured that fresh developer washes over","letter":"B"},{"is_no_change":false,"label":"By inverting the tank every thirty seconds, the photographer washes fresh developer over","letter":"C"},{"is_no_change":false,"label":"Inverted every thirty seconds, fresh developer washes over","letter":"D"}]', 'C', '{"A":"Leaves the opening phrase dangling (dangling_modifier): the noun after the comma is the developer, which cannot invert a tank.","B":"Hides the doer behind an empty ''it is ensured'' construction (dangling_passive_patch), so the modifier still has nothing to attach to.","C":"Correct: the person who performs the inverting now stands immediately after the modifier.","D":"Re-aims the participle at the liquid (misattached_participle), absurdly claiming the developer itself is inverted."}', 'Naming **the photographer** right after the modifier gives the opening phrase a doer that can actually invert the tank.', 'The original keeps the sentence''s spotlight on the developer, which feels natural because the developer is what the sentence is really about.', '1) Find the opening modifier and ask who performs its action. 2) Check the first noun after the comma. 3) If that noun cannot perform the action, the modifier dangles. 4) Choose the version that places the true doer immediately after the comma, and reject rewrites that merely bury the problem in passive padding.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-521269745852cbc2', 'act-english', 's-sent', 4, 'In the 1950s, Norman McLaren scratched and painted images directly onto clear film <u>stock he bypassed</u> the camera entirely.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"stock, he bypassed","letter":"B"},{"is_no_change":false,"label":"stock, therefore he bypassed","letter":"C"},{"is_no_change":false,"label":"stock, bypassing","letter":"D"}]', 'D', '{"A":"Two independent clauses stand fused with no punctuation or connector between them.","B":"A comma alone cannot join two independent clauses; this is a comma splice.","C":"''Therefore'' is a conjunctive adverb, not a conjunction; after a mere comma it still leaves a splice.","D":"Turning the second clause into the participial phrase ''bypassing ...'' attaches it grammatically to the main clause."}', 'Reducing the second clause to a **participial phrase** removes the second independent clause — and the boundary problem with it.', 'The comma-plus-''therefore'' version sounds formal and connected, masking that a comma still cannot hold two clauses together.', '1) Count the independent clauses. 2) If there are two, check the joint: it needs a period, a semicolon, or a comma plus coordinating conjunction. 3) Conjunctive adverbs like ''therefore'' need a semicolon before them. 4) Alternatively, demote one clause to a phrase or dependent clause. 5) Pick the option that satisfies one of these fixes.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-526f5a96ad6ca48b', 'act-english', 's-sent', 4, 'The final week of the taper felt endless to <u>Priya, she</u> reminded herself that fresh legs would matter more than one last hard workout.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Priya, consequently she","letter":"B"},{"is_no_change":false,"label":"Priya she","letter":"C"},{"is_no_change":false,"label":"Priya, but she","letter":"D"}]', 'D', '{"A":"A bare comma cannot join two independent clauses, so the original is a splice (comma_splice).","B":"A conjunctive adverb after a comma leaves the splice intact and asserts a cause-effect link the sentence does not make (conj_adverb_splice).","C":"Deleting the comma fuses the clauses into a run-on, one step worse than the splice (fused_sentence).","D":"Correct: a comma plus a coordinating conjunction legally joins the clauses and captures the turn from dread to reassurance."}', 'Two independent clauses need a **conjunction** with the comma, and the contrast word matches the sentence''s pivot from frustration to trust.', 'The ''consequently'' version tempts students because adding any connecting word feels like a repair, even though the comma splice survives underneath it.', '1) Test each side of the underlined seam: could it stand alone? 2) If both sides are independent, a comma alone is illegal. 3) Legal repairs: comma + coordinating conjunction, semicolon, or period. 4) Check that the chosen connector also matches the logic between the clauses. 5) Re-read the repaired sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-65e9643edd0781d7', 'act-english', 's-sent', 4, '<u>To qualify for the finals, a clean routine must be landed by every gymnast.</u>', 'Which revision attaches the infinitive phrase to the ones who must act?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"A clean routine, to qualify for the finals, must be landed by every gymnast.","letter":"B"},{"is_no_change":false,"label":"To qualify for the finals, a clean routine is what every gymnast must land.","letter":"C"},{"is_no_change":false,"label":"To qualify for the finals, every gymnast must land a clean routine.","letter":"D"}]', 'D', '{"A":"A ''clean routine'' cannot qualify for the finals; the gymnasts do.","B":"The passive keeps ''a clean routine'' as subject, so the phrase still misattaches.","C":"The cleft still leaves ''a clean routine'' as the grammatical subject the phrase modifies.","D":"Making ''every gymnast'' the subject lets the opening ''to qualify'' phrase attach to the ones who act."}', 'An opening infinitive of purpose (''to qualify…'') modifies the **subject that follows** — it must be the one qualifying.', 'The passive voice sounds formal and ''test-like'', masking the misattachment.', 'After an opening ''to + verb'' purpose phrase, name the actor as the subject; avoid a passive that hides them.', 'underlined-span-mc', 'the passive voice sounds formal and ''test-like'', masking the misattac…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-67e90e9423956f61', 'act-english', 's-sent', 4, 'Members quickly noticed that the new mount''s tracking accuracy far exceeds <u>the club''s older mount</u>, keeping Jupiter centered in the eyepiece for minutes at a time.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the club''s older mount''s","letter":"B"},{"is_no_change":false,"label":"those of the club''s older mount","letter":"C"},{"is_no_change":false,"label":"that of the club''s older mount","letter":"D"}]', 'D', '{"A":"Illogical comparison: it weighs an abstract quality (accuracy) against a physical object (a mount).","B":"Dangling possessive: the trailing -''s has no noun to own, leaving the comparison unfinished.","C":"Number error: ''those'' is plural, but the compared quality, ''accuracy,'' is singular.","D":"Correct: singular ''that of'' stands in for the accuracy of the older mount, matching like with like."}', 'Comparisons must match categories: **''that of''** supplies the older mount''s accuracy so the sentence compares accuracy to accuracy.', 'The original tempts students because readers mentally supply the missing ''accuracy,'' so the mismatch is easy to hear past.', '1) Name the quality being compared (here, tracking accuracy). 2) Check the second half: is it the same category of thing? 3) If not, insert a stand-in—''that of'' for singular qualities, ''those of'' for plurals. 4) Match the stand-in''s number to the quality, not to the objects. 5) Re-read to confirm both sides are now parallel.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b42b709e28ec71f', 'act-english', 's-sent', 4, 'In the black depths far below the waves, the anglerfish <u>drifting silently and luring prey with its glowing lure.</u>', 'Which choice makes the underlined portion a complete sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"drifting silently and luring prey with its glowing lure,","letter":"B"},{"is_no_change":false,"label":"drifts silently and lures prey with its glowing lure.","letter":"C"},{"is_no_change":false,"label":"silently drifting and luring prey with its glowing lure.","letter":"D"}]', 'C', '{"A":"Offers only ''-ing'' forms and no finite verb, leaving a fragment (fragment_no_verb).","B":"Adds a comma but still supplies no main verb, so it remains a fragment (fragment_no_verb).","C":"Correct: the finite verbs give the subject a complete predicate.","D":"Rearranges the modifiers but keeps the participles, so it is still a fragment (fragment_no_verb)."}', 'A complete sentence needs a **finite (tensed) verb**, which only the conjugated forms provide.', 'The long string of descriptive ''-ing'' words reads like action, so students miss that no main verb anchors the subject.', '1) Find the subject. 2) Look for a finite verb that tells what the subject does. 3) If only ''-ing'' or ''-ed'' participles appear, it is a fragment. 4) Supply a tensed verb so the subject has a complete predicate.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6cb24370d8242f1b', 'act-english', 's-sent', 4, 'The coach praised the team for practicing daily, playing fairly, and <u>that they communicated</u> clearly.', 'Which choice keeps the series parallel?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to communicate","letter":"B"},{"is_no_change":false,"label":"communicating","letter":"C"},{"is_no_change":false,"label":"they communicated","letter":"D"}]', 'C', '{"A":"''That they communicated'' breaks the -ing pattern set by ''practicing'' and ''playing''.","B":"The infinitive ''to communicate'' mismatches the -ing forms.","C":"''Communicating'' matches the two -ing verbs, keeping the series parallel.","D":"''They communicated'' inserts a full clause where the series expects a single -ing verb."}', 'Items in a series must share one grammatical form — here the **-ing** form.', 'Each option is grammatical in isolation; only the series pattern exposes the mismatch.', 'Match every item in a list to the form the first items establish (parallel structure).', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6cea8796ed3ec748', 'act-english', 's-sent', 4, 'The tide was dropping fast<u>, we hurried to reach the far pools</u> before the light failed.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", so we hurried to reach the far pools","letter":"B"},{"is_no_change":false,"label":"we hurried to reach the far pools","letter":"C"},{"is_no_change":false,"label":", therefore we hurried to reach the far pools","letter":"D"}]', 'B', '{"A":"A comma alone joins two independent clauses, creating a comma splice (comma_splice).","B":"Correct: the comma plus ''so'' properly coordinates the two independent clauses.","C":"Removing the comma fuses the clauses into a run-on.","D":"''Therefore'' is a conjunctive adverb; after a comma it still leaves a splice."}', 'A comma with a **coordinating conjunction** (''so'') correctly links two independent clauses.', '''Therefore'' expresses the cause-effect logic, so students accept it despite the punctuation flaw.', '1) Confirm both sides are complete sentences. 2) A comma alone cannot join them. 3) Add a coordinating conjunction (and, but, so...) after the comma, or use a semicolon. 4) Note that ''therefore'' is not a coordinating conjunction.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-80514a8a2e8a3512', 'act-english', 's-sent', 4, 'Although the pontoon design cost half as much as a conventional span, <u>but it</u> demanded round-the-clock pumping to stay afloat.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"and it","letter":"B"},{"is_no_change":false,"label":"it","letter":"C"},{"is_no_change":false,"label":"so it","letter":"D"}]', 'C', '{"A":"''Although'' has already subordinated the first clause, so adding ''but'' doubles the connector and breaks the structure (misconception: double_connector_although_but).","B":"Coordinating with ''and'' leaves the subordinate clause attached to nothing (misconception: double_connector_and).","C":"After an ''although'' clause and a comma, the main clause attaches directly with no added conjunction.","D":"''So'' both duplicates the existing connection and asserts a cause-effect link the sentence does not intend (misconception: double_connector_false_cause)."}', 'One connector per clause pair: the subordinator **''although''** already links the clauses, so the main clause must follow the comma unadorned.', 'Students hear ''although...but'' in casual speech and in some other languages, so the doubled connector sounds complete rather than redundant.', '1) Circle every connecting word (although, but, and, so, because). 2) Count the clauses being linked. 3) Allow exactly one connector per pair of clauses. 4) If a subordinator opens the sentence, the main clause needs no conjunction. 5) Reread the sentence to confirm it has one backbone.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8d75cd3f2cf8b3d9', 'act-english', 's-sent', 4, 'According to the press association''s annual tally, the Sentinel''s letters page draws more submissions <u>than the Tribune</u>, its only competitor in the county.', 'Which choice makes the comparison in the sentence logical and grammatically correct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"than the Tribune''s","letter":"B"},{"is_no_change":false,"label":"than the Tribunes","letter":"C"},{"is_no_change":false,"label":"then the Tribune''s","letter":"D"}]', 'B', '{"A":"Compares submissions to an entire newspaper — a category mismatch.","B":"Correct: the possessive stands in for ''the Tribune''s letters page,'' balancing the comparison.","C":"Adds an s without an apostrophe, creating a plural rather than a possessive.","D":"Swaps in ''then,'' a time word, where the comparison word is required."}', 'The **possessive** makes the sentence compare like with like — one paper''s submissions against the other paper''s.', 'The original tempts students because speech routinely shortens comparisons this way, masking the category mismatch.', '1) Find the two things compared. 2) Ask: are they the same category (page vs. page, count vs. count)? 3) If not, repair with a possessive or ''that of / those of.'' 4) Confirm ''than'' (comparison), not ''then'' (time). 5) Re-read the comparison with both halves spelled out.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9d2a131f803d5bc8', 'act-english', 's-sent', 4, 'The aroma of a freshly cracked vanilla pod is far more complex than <u>a synthetic extract</u> bottled on a factory line.', 'Which choice makes the comparison logical?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"a synthetic extract''s","letter":"B"},{"is_no_change":false,"label":"synthetic extracts","letter":"C"},{"is_no_change":false,"label":"that of a synthetic extract","letter":"D"}]', 'D', '{"A":"Illogical comparison: it pits an aroma against an extract, comparing a smell to a whole product.","B":"Incomplete: the possessive dangles with no noun, and it still fails to name the aroma being compared.","C":"Same flaw as the original: it compares the aroma to the extracts themselves, not to their aroma.","D":"Correct: ''that of'' supplies the missing noun, so an aroma is compared to an aroma."}', 'A comparison must be **parallel in kind**; ''that of'' stands in for ''the aroma of,'' matching aroma to aroma.', 'The original reads smoothly and the intended meaning is obvious, so the mismatched terms slip by unnoticed.', '1) Find the two things being compared. 2) Name the category of each — is it aroma vs. aroma, or aroma vs. product? 3) If the categories differ, the comparison is illogical. 4) Insert ''that of'' or ''those of'' to supply the matching noun. 5) Reread to confirm like is compared with like.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a42b5cacf649a56f', 'act-english', 's-sent', 4, '<u>Drifting weightlessly above the reef, the camera recorded</u> a hawksbill turtle sliding gracefully between the branching corals.', 'Which choice most clearly and correctly expresses the intended meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Drifting weightlessly above the reef, the diver recorded","letter":"B"},{"is_no_change":false,"label":"Drifting weightlessly above the reef, there was a recording made by the camera of","letter":"C"},{"is_no_change":false,"label":"The camera, drifting weightlessly above the reef, recorded","letter":"D"}]', 'B', '{"A":"The opening modifier illogically attaches to ''the camera,'' as if the camera were drifting on its own (misconception: dangling_modifier).","B":"Naming the person as the subject gives the introductory phrase a logical thing to modify.","C":"The passive construction still leaves the modifier without a sensible subject and adds wordiness (misconception: passive_evades_subject).","D":"Moving the phrase mid-sentence still says the camera is doing the drifting (misconception: relocated_but_still_dangling)."}', 'The introductory modifier must sit beside the **person** actually drifting, not the equipment.', 'The camera does the recording, so making it the subject feels natural even though it isn''t what drifts.', '1) Find the introductory -ing phrase and ask who or what performs its action. 2) Locate the subject right after the comma. 3) Make sure that subject is the doer of the introductory action. 4) If it isn''t, rewrite so the true doer becomes the subject — don''t just move the phrase or hide the subject in a passive.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ae777d0f2697e351', 'act-english', 's-sent', 4, 'The gilded frame, which had survived two fires and a flood<u>, arriving</u> at the lab in surprisingly stable condition.', 'Which choice makes the sentence grammatically complete?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", it arrived","letter":"B"},{"is_no_change":false,"label":", and arriving","letter":"C"},{"is_no_change":false,"label":", arrived","letter":"D"}]', 'D', '{"A":"With only the -ing form, the subject ''frame'' never gets a main verb, leaving a fragment.","B":"Adding ''it'' creates a double subject — ''The frame ... it arrived'' — a nonstandard restatement.","C":"''And'' joins the -ing form to nothing; the sentence still lacks a finite main verb.","D":"Correct: the past-tense verb gives the subject ''frame'' its finite main verb, completing the sentence."}', 'Every sentence needs a **finite main verb** for its subject; an -ing form alone cannot serve that role.', 'The long which-clause makes the fragment sound complete, since a verb (''had survived'') does appear — just not one belonging to the main clause.', '1) Bracket off any which/who clause and other interrupters. 2) Read what remains: subject + ??? 3) Ask whether a finite verb (one showing tense) is left for that subject. 4) An -ing form without a helper is not finite. 5) Choose the option that gives the stripped-down sentence a tensed verb without doubling the subject.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b90d87516b23e2fb', 'act-english', 's-sent', 4, '<u>Peering through the mesh veil, the keeper spotted</u> the supersedure cell hanging from the bottom bar of the frame.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Peering through the mesh veil, the supersedure cell was spotted by the keeper","letter":"B"},{"is_no_change":false,"label":"Peering through the mesh veil, the frame held","letter":"C"},{"is_no_change":false,"label":"The supersedure cell, peering through the mesh veil, was spotted","letter":"D"}]', 'A', '{"A":"Correct: the opening modifier ''Peering through the mesh veil'' attaches to ''the keeper,'' the only one in the sentence who can peer.","B":"The passive construction makes ''the supersedure cell'' the subject the modifier lands on, but a cell cannot peer through a veil.","C":"Puts ''the frame'' right after the modifier, illogically implying the frame did the peering.","D":"Wedges the modifier next to ''the supersedure cell,'' the one thing in the sentence that cannot look through a veil."}', 'An introductory participial phrase must modify the **subject that follows it**, and only the keeper can peer through a veil.', 'The passive rewrite sounds formal and objective, so students pick it without checking that its new subject cannot perform the opening action.', '1) Read the introductory ''-ing'' phrase and ask who or what performs its action. 2) Find the subject that comes right after the comma. 3) Confirm that subject is the doer of the phrase''s action. 4) Reject any version whose post-comma subject cannot logically perform the opening action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c460b9d55b0b2362', 'act-english', 's-sent', 4, '<u>While reviewing the applications, several errors were noticed by the committee.</u>', 'Which choice fixes the dangling modifier without shifting the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Several errors were noticed by the committee while reviewing the applications.","letter":"B"},{"is_no_change":false,"label":"While reviewing the applications, several errors got noticed by the committee.","letter":"C"},{"is_no_change":false,"label":"While reviewing the applications, the committee noticed several errors.","letter":"D"}]', 'D', '{"A":"''Several errors'' were not reviewing the applications; the committee was.","B":"Moving the phrase to the end still leaves ''reviewing'' pointing at ''errors''.","C":"Swapping ''were'' for ''got'' keeps ''errors'' as the subject doing the reviewing.","D":"The committee both reviews and notices, so the opening phrase attaches to the right subject."}', 'The reviewer (the committee) must be the **subject the opening phrase modifies**.', 'The passive ''were noticed by the committee'' names the committee, so it seems attached — but grammatically it isn''t the subject.', 'A ''While + -ing'' opener modifies the sentence''s subject; make the actor that subject, not a later ''by'' phrase.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-cc2fc80b45aa8ddd', 'act-english', 's-sent', 4, '<u>Although the understudy had rehearsed the role for weeks, but she</u> still asked to run her scenes one more time before the house opened.', 'Which choice results in the most logical and grammatically sound sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Although the understudy had rehearsed the role for weeks, she","letter":"B"},{"is_no_change":false,"label":"The understudy had rehearsed the role for weeks, she","letter":"C"},{"is_no_change":false,"label":"Although the understudy had rehearsed the role for weeks, and she","letter":"D"}]', 'B', '{"A":"Pairing the subordinator ''Although'' with the coordinator ''but'' doubles the connector and leaves no independent clause (double_conjunction).","B":"Correct: the single subordinator marks the contrast, and the main clause follows cleanly after the comma.","C":"Dropping the subordinator leaves two independent clauses joined by only a comma (comma_splice).","D":"''Although'' plus ''and'' still stacks two connectors, so no clause is left to stand as the main statement (double_conjunction)."}', 'One clause relationship gets **one** connector: the subordinating opener alone handles the contrast, leaving a clean main clause.', 'The original tempts students because ''although... but'' mirrors how people talk, and each connector sounds correct in isolation.', '1) Underline every connecting word in the sentence. 2) Count the clauses being related. 3) Allow exactly one connector per relationship. 4) If two connectors compete, delete one and check that a full main clause remains. 5) Reread to confirm the sentence has one subordinate clause attached to one independent clause.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-cc4452d8304c2c1b', 'act-english', 's-sent', 4, 'The negotiations dragged on for hours<u>, however, both</u> sides finally signed the agreement.', 'Which choice correctly punctuates the transition between the two clauses?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", however both","letter":"B"},{"is_no_change":false,"label":" however both","letter":"C"},{"is_no_change":false,"label":"; however, both","letter":"D"}]', 'D', '{"A":"''However'' is a conjunctive adverb, not a conjunction; a comma before it splices the two complete clauses.","B":"A comma before ''however'' still leaves a splice — ''however'' cannot join clauses the way ''but'' can.","C":"With no punctuation the two complete thoughts fuse.","D":"A semicolon before ''however'' and a comma after it correctly links the independent clauses."}', 'A conjunctive adverb joining two clauses takes a **semicolon before and a comma after**.', '''However'' feels like ''but'', so a comma before it seems to work — but it can''t glue clauses.', 'however / therefore / moreover between two complete clauses ⇒ ; before, , after.', 'underlined-span-mc', '''However'' feels like ''but'', so a comma before it seems to work — but…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d1745e0a36e5f0c7', 'act-english', 's-sent', 4, 'After inking the rollers by hand, <u>the first proof was pulled by the apprentice</u> so the master could judge the impression.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the first proof was pulled","letter":"B"},{"is_no_change":false,"label":"the apprentice pulled the first proof","letter":"C"},{"is_no_change":false,"label":"the apprentice''s first proof was pulled","letter":"D"}]', 'C', '{"A":"The opening phrase describes someone inking rollers, but this version makes ''the first proof'' the doer — proofs cannot ink.","B":"Shortening the passive does not supply a doer; the modifier still dangles.","C":"This places the person who inked the rollers directly after the modifier, so the opener describes its true subject.","D":"A possessive is not a subject; the clause''s subject is still ''proof,'' so the opener still lacks its doer."}', 'An opening modifier must be followed immediately by the **doer** it describes.', 'The possessive version tempts because the person''s title appears right after the comma, hiding that the true subject is still the proof.', '1) Find the opening modifier and ask: who performs this action? 2) Look at the subject that follows the comma. 3) If the subject is not the performer, the modifier dangles. 4) Rewrite so the performer stands as the grammatical subject right after the comma. 5) Re-read to confirm the opener now describes its neighbor.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-edd247e2ef9ff76d', 'act-english', 's-sent', 4, 'The internship taught her to manage budgets, to draft reports, and <u>public speaking</u>.', 'Which choice maintains parallel structure in the list?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"how public speaking works","letter":"B"},{"is_no_change":false,"label":"she learned public speaking","letter":"C"},{"is_no_change":false,"label":"to speak in public","letter":"D"}]', 'D', '{"A":"The noun phrase ''public speaking'' breaks the ''to + verb'' pattern set by ''to manage'' and ''to draft''.","B":"''How public speaking works'' is a clause, not the infinitive the series expects — and it changes the meaning.","C":"''She learned public speaking'' inserts a whole new clause into a series of infinitives.","D":"''To speak in public'' matches ''to manage'' and ''to draft'' — three parallel infinitives."}', 'Every item in the series must repeat the established form — here, the **infinitive** (''to ___'').', '''Public speaking'' is a perfectly natural phrase on its own; only the series pattern exposes it.', 'Match each list item to the grammatical form the first item establishes.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ee184a6faaad71be', 'act-english', 's-sent', 4, 'Paddling through Voyageurs'' island channels at dusk, <u>loons startled the kayakers</u> at nearly every bend.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the kayakers were startled by loons","letter":"B"},{"is_no_change":false,"label":"loons were startling to the kayakers","letter":"C"},{"is_no_change":false,"label":"the loons'' cries startled the kayakers","letter":"D"}]', 'B', '{"A":"Makes the loons the paddlers—the opening modifier grabs the first noun after the comma.","B":"Places ''the kayakers,'' the actual paddlers, right after the modifier, repairing the dangler.","C":"Keeps ''loons'' in the modifier''s grip, so the birds are still doing the paddling.","D":"Hands the paddling to the loons'' cries, which is even less plausible."}', 'An introductory participial phrase must be followed **immediately by its true doer**—the kayakers.', 'The ''cries'' version adds vivid detail while leaving the dangling structure untouched, so it feels like an upgrade.', '1) Find the opening modifier and ask: who performs this action? 2) Check the first noun after the comma. 3) If doer and noun don''t match, the modifier dangles. 4) Rewrite so the doer lands directly after the comma—even if that means the passive voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f7f5a218f3a8b7e4', 'act-english', 's-sent', 4, '<u>Hoping to verify the hail reports, the flattened cornfield was photographed by the survey team</u> before insurance adjusters arrived.', 'Which of the following provides the most logical version of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Hoping to verify the hail reports, the survey team photographed the flattened cornfield","letter":"B"},{"is_no_change":false,"label":"Hoping to verify the hail reports, the cornfield''s flattened rows were photographed by the survey team","letter":"C"},{"is_no_change":false,"label":"The flattened cornfield, hoping to verify the hail reports, was photographed by the survey team","letter":"D"}]', 'B', '{"A":"The opening modifier grabs the nearest subject, making the cornfield do the hoping (misconception: the doer can arrive later in the sentence).","B":"Correct: the survey team — the only party capable of hoping — sits immediately after the modifier.","C":"Swapping in ''rows'' still leaves a non-hoping subject beside the modifier (misconception: rewording the subject phrase fixes the dangle).","D":"Moving the modifier inside the clause attaches it even more firmly to the cornfield (misconception: modifier placement is flexible if commas fence it)."}', 'An opening participial modifier must be followed **immediately by its doer** — here, the survey team.', 'The passive rewrite with ''rows'' keeps the original''s rhythm, so its unchanged subject slips past inspection.', '1) Find the opening -ing phrase. 2) Ask: who performs that action? 3) Check the very next noun after the comma. 4) If doer and next noun differ, rewrite so the doer follows the comma. 5) Re-read to confirm the action pairs with a capable subject.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-09399fbbaee023a2', 'act-english', 's-sent', 5, 'Stacked haphazardly near the register, <u>shoppers often overlook the crate of sheet music</u>.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shoppers often miss the crate of sheet music entirely","letter":"B"},{"is_no_change":false,"label":"the crate of sheet music is easy to overlook","letter":"C"},{"is_no_change":false,"label":"there is a crate of sheet music that shoppers often overlook","letter":"D"}]', 'C', '{"A":"Puts *shoppers* right after the opening modifier, absurdly claiming the shoppers are stacked near the register.","B":"Rewords the clause but still hands the modifier to *shoppers*, leaving it dangling.","C":"Correct: the crate — the thing actually stacked — immediately follows the modifier it belongs to.","D":"Opens with the empty subject *there*, so the modifier still has nothing stacked to attach to."}', 'An opening modifier attaches to the **first noun after the comma**, which must be the thing the modifier describes.', 'The ''there is'' construction mentions the crate soon after the comma, so it feels like the modifier finds its target.', '1) Bracket the opening modifier. 2) Ask: who or what does this describe? 3) Check the first noun after the comma — it must be that answer. 4) If not, choose the version that moves the right noun into that slot. 5) Re-read to confirm the image makes sense.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4472935cd867edcf', 'act-english', 's-sent', 5, '<u>Although the station''s tower stood barely sixty feet tall, its signal carried</u> across the valley on clear winter nights.', 'Which choice is most logical and grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Although the station''s tower stood barely sixty feet tall, but its signal carried","letter":"B"},{"is_no_change":false,"label":"The station''s tower stood barely sixty feet tall, its signal carried","letter":"C"},{"is_no_change":false,"label":"Because the station''s tower stood barely sixty feet tall, its signal carried","letter":"D"}]', 'A', '{"A":"Correct: one subordinator sets up the concession, and the main clause delivers the surprising reach.","B":"''Although... but'' doubles the connectors, leaving the sentence with two dependent-feeling halves and no main clause.","C":"Dropping the connector leaves two independent clauses spliced by a comma and erases the logical relationship.","D":"''Because'' claims the tower''s small size caused the long reach, reversing the sentence''s logic of surprising contrast."}', 'One **concessive subordinator** plus one main clause expresses the intended surprise: a small tower whose signal nonetheless traveled far.', '''Although... but'' tempts students because both words feel like they reinforce the contrast, when in fact each pair of clauses allows only one connector.', '1) Count the clauses. 2) Count the connecting words — a clause pair gets exactly one. 3) Name the logical relationship the sentence intends (cause, contrast, concession). 4) Confirm the surviving connector expresses that relationship. 5) Verify one clause remains fully independent.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5951b5e406e50a8f', 'act-english', 's-sent', 5, '<u>Although the refuge protects ten thousand acres, and its</u> wetlands still depend on water released from dams far upstream.', 'Which choice results in the clearest, most effective sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Although the refuge protects ten thousand acres, its","letter":"B"},{"is_no_change":false,"label":"The refuge protects ten thousand acres, its","letter":"C"},{"is_no_change":false,"label":"Although the refuge protects ten thousand acres, so its","letter":"D"}]', 'B', '{"A":"''Although'' plus ''and'' double-marks the link, leaving no clause free to stand as the main one — a fragment.","B":"Correct: one subordinator sets up the concession, and the second clause stands independent to complete the sentence.","C":"Dropping the subordinator leaves two independent clauses joined by a bare comma — a splice — and loses the concessive logic.","D":"''Although'' and ''so'' both mark the relationship, contradicting each other and again leaving no clean main clause."}', 'One relationship gets **one connector**: subordinate the first clause and let the second stand as the main clause.', 'The double-connector versions sound complete when read quickly, because each clause individually flows smoothly.', '1) Count the clauses. 2) Count the connectors joining them. 3) Two clauses need exactly one link — a subordinator or a coordinator, never both. 4) Confirm one clause remains fully independent. 5) Re-read to check the logical relationship survives.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-61f409a3d2cb275c', 'act-english', 's-sent', 5, '<u>Weakened by a century of ice storms, the family finally braced the Wolf River''s largest limb</u> before the autumn winds arrived.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Weakened by a century of ice storms, the family''s brace finally supported the largest limb of the Wolf River","letter":"B"},{"is_no_change":false,"label":"The family, weakened by a century of ice storms, finally braced the Wolf River''s largest limb","letter":"C"},{"is_no_change":false,"label":"Weakened by a century of ice storms, the Wolf River''s largest limb was finally braced by the family","letter":"D"}]', 'D', '{"A":"The opening modifier attaches to ''the family,'' absurdly claiming the people were weakened by ice storms.","B":"Shifting to ''the family''s brace'' hands the storm damage to the brand-new brace instead of the limb.","C":"Placing the modifier beside ''family'' makes the misreading explicit rather than fixing it.","D":"Correct: the weakened thing — the limb — now sits directly after the modifier that describes it."}', 'An opening participial phrase must be followed **immediately** by the noun it describes.', '''The family''s brace'' begins with new hardware, so the modifier seems re-aimed even though the head noun is still the wrong thing.', '1) Bracket the opening modifier. 2) Ask: who or what was actually weakened? 3) Check the first noun phrase after the comma — its head noun must be that exact thing (watch possessives: the head is the last word of the phrase). 4) If it is not, choose the version that moves the right noun next to the modifier.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6ff15380f6fcd522', 'act-english', 's-sent', 5, 'The new turbines generate more electricity than <u>the old plant</u>, and they do it with half the fuel.', 'Which choice completes the comparison so like is compared with like?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the old plant did","letter":"B"},{"is_no_change":false,"label":"that of the old plants","letter":"C"},{"is_no_change":false,"label":"the old plant''s electricity generation was","letter":"D"}]', 'B', '{"A":"As written, the turbines'' electricity is compared to ''the old plant'' itself, not to what it generated.","B":"''did'' supplies the missing verb, comparing how much the turbines generate to how much the plant generated.","C":"''that of the old plants'' is plural and disagrees with the single old plant the sentence names.","D":"This is grammatical but bloated, and the tense ''was'' clashes with the active ''generate''."}', 'Finish the comparison with the **parallel verb** (''did'') so ''generate'' is measured against ''generated''.', '''Than the old plant'' sounds complete, hiding that a turbine''s output is being set against a building.', 'Complete a comparison so both sides name the same kind of thing — often by adding the echoing verb (did, does, is).', 'underlined-span-mc', '''Than the old plant'' sounds complete, hiding that a turbine''s output…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-850ac543a78e429f', 'act-english', 's-sent', 5, '<u>Clinging to the rock with a broad, muscular foot, the snail held firm.</u>', 'Which choice is grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Clinging to the rock with a broad, muscular foot, firmness was maintained by the snail.","letter":"B"},{"is_no_change":false,"label":"Clinging to the rock with a broad, muscular foot, the crashing wave could not budge the snail.","letter":"C"},{"is_no_change":false,"label":"Clinging to the rock with a broad, muscular foot, and the snail held firm.","letter":"D"}]', 'A', '{"A":"Correct: the opening modifier logically describes ''the snail,'' the subject that follows it.","B":"The modifier now describes ''firmness,'' which cannot cling, creating a dangling modifier (dangling_subject).","C":"The modifier attaches to ''the crashing wave,'' which is not what clings to the rock.","D":"Adding ''and'' after the modifier breaks the connection and leaves a faulty construction."}', 'An introductory participial phrase must modify the **subject that immediately follows**, and ''the snail'' clings correctly.', 'The passive version sounds formal, so students accept it despite the illogical modifier.', '1) Find the introductory -ing phrase. 2) Identify who or what performs that action. 3) Make sure the noun right after the comma is that performer. 4) Reject versions where something else follows the comma.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-888139978be5073c', 'act-english', 's-sent', 5, 'The pianist''s technique is more polished than <u>the other finalists</u>.', 'Which choice makes the comparison logical?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the other finalists are","letter":"B"},{"is_no_change":false,"label":"that of the other finalists","letter":"C"},{"is_no_change":false,"label":"the other finalists'' were","letter":"D"}]', 'C', '{"A":"As written, the sentence compares a TECHNIQUE to PEOPLE — apples to orchestra members.","B":"''Than the other finalists are'' still measures the people, not their technique.","C":"''That of the other finalists'' compares technique to technique — like to like.","D":"''The other finalists'' were'' garbles the grammar and shifts tense mid-comparison."}', 'Comparisons must pair like with like: technique vs **that of** the others.', 'The shorthand comparison is how people actually talk, so the mismatch hides.', 'When comparing possessions or attributes, add ''that of'' / ''those of'' so both sides match.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8af409b05a85324e', 'act-english', 's-sent', 5, 'Critics agreed that the sequel''s soundtrack was far more inventive than <u>the original film</u>.', 'Which choice makes the comparison logically consistent?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"in the original film","letter":"B"},{"is_no_change":false,"label":"that of the original film","letter":"C"},{"is_no_change":false,"label":"the original film was inventive","letter":"D"}]', 'C', '{"A":"This compares a soundtrack to an entire film, not to the film''s soundtrack.","B":"''In the original film'' compares the soundtrack to a location, still not to another soundtrack.","C":"''That of the original film'' stands in for ''the soundtrack of the original film'', matching soundtrack to soundtrack.","D":"Adding ''was inventive'' repeats the adjective and produces a lopsided, redundant clause."}', 'Use **''that of''** so the sequel''s soundtrack is compared with the original''s soundtrack, not the film.', '''Than the original film'' is idiomatic-sounding, masking the soundtrack-to-film mismatch.', 'When comparing an attribute, insert ''that of'' / ''those of'' so both sides name the same attribute.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8bd47dda7b5e8113', 'act-english', 's-sent', 5, '<u>Because it was the oldest trophy in the federation''s vault, the silver rook was</u> left out of an exhibit meant to celebrate the federation''s proudest history.', 'Which choice most effectively expresses the logical relationship between the ideas in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Although it was the oldest trophy in the federation''s vault, the silver rook was","letter":"B"},{"is_no_change":false,"label":"The silver rook was the oldest trophy in the federation''s vault, it was","letter":"C"},{"is_no_change":false,"label":"Because of it being the oldest trophy in the federation''s vault, the silver rook was","letter":"D"}]', 'B', '{"A":"The causal connector claims the trophy''s age explains its exclusion, but a history exhibit would be expected to feature its oldest treasure.","B":"A concession connector correctly signals that the exclusion defies what the trophy''s status leads us to expect.","C":"A comma alone cannot join two independent clauses, and dropping the connector erases the relationship entirely.","D":"''Because of it being'' is nonstandard in formal prose and still asserts cause where the sentence implies contradiction."}', 'A **concession** connector signals that the exclusion runs against what the trophy''s status would lead us to expect.', 'The causal opener tempts because age could plausibly explain many things, hiding that a history exhibit should prize its oldest piece.', '1) Read the two ideas and predict: given the first, what outcome would you expect? 2) If the actual outcome matches the expectation, a cause connector fits. 3) If the outcome defies the expectation, use a concession connector. 4) Check the join is also grammatical: a subordinate clause attached to a full main clause.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-994a46c05db2a76d', 'act-english', 's-sent', 5, '<u>Having skipped his last two long runs, the marathon''s final miles punished Alonzo</u> with cramps no stretch could relieve.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Having skipped his last two long runs, Alonzo was punished by the marathon''s final miles","letter":"B"},{"is_no_change":false,"label":"Having skipped his last two long runs, the punishment of the marathon''s final miles found Alonzo","letter":"C"},{"is_no_change":false,"label":"The marathon''s final miles, having skipped his last two long runs, punished Alonzo","letter":"D"}]', 'B', '{"A":"The opening modifier attaches to ''the marathon''s final miles,'' which never skipped any runs (dangling_subject).","B":"Correct: the runner, the true doer of the skipping, immediately follows the modifier, so the phrase attaches logically.","C":"Swaps in ''the punishment'' as the following noun, which still cannot have skipped workouts (dangling_new_abstract).","D":"Relocates the modifier next to ''miles,'' so the wrong noun still owns the skipped runs (misplaced_modifier)."}', 'A participial opener grabs the **nearest** following subject, so the runner who skipped the training must sit right after the comma.', 'The original tempts students because the intended meaning is easy to recover, so the grammatical misattachment slips past the ear.', '1) Find the opening or inserted -ing phrase. 2) Ask: who performs that action? 3) Locate the noun the phrase actually touches. 4) If the toucher and the doer differ, the modifier misfires. 5) Choose the version whose adjacent noun is the true doer, and re-read to confirm.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a0183ef65f5d2531', 'act-english', 's-sent', 5, '<u>Signing at a furious pace, the audience struggled to follow the interpreter''s poetry-slam rendition.</u>', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Signing at a furious pace, the interpreter''s poetry-slam rendition confused the audience.","letter":"B"},{"is_no_change":false,"label":"The audience, signing at a furious pace, struggled to follow the interpreter.","letter":"C"},{"is_no_change":false,"label":"Signing at a furious pace, the interpreter delivered a poetry-slam rendition that the audience struggled to follow.","letter":"D"}]', 'D', '{"A":"The opening modifier attaches to ''the audience,'' absurdly claiming the audience was doing the signing.","B":"A possessive cannot anchor the modifier; ''the interpreter''s rendition'' makes the rendition itself the signer.","C":"Moving the modifier next to ''audience'' now states outright that the audience signed at a furious pace.","D":"Correct — the doer of ''signing,'' the interpreter, immediately follows the modifier."}', 'An opening participial phrase must be followed **immediately** by the noun performing its action — here, the person signing.', 'The possessive version tempts students because ''interpreter''s'' appears right after the comma, though the actual subject is ''rendition.''', '1) Bracket the opening -ing phrase. 2) Ask: who performs that action? 3) The very first noun after the comma must be that performer — possessives don''t count. 4) Reject any version whose post-comma subject could not logically do the action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c601cdcd4f37232d', 'act-english', 's-sent', 5, '<u>Flying low over the churning lava lake, the intense heat forced the drone to climb</u> to a safer altitude before its cameras could finish mapping the vent.', 'Which choice makes the sentence most grammatically acceptable?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Flying low over the churning lava lake, the drone was forced by the intense heat to climb","letter":"B"},{"is_no_change":false,"label":"The intense heat, flying low over the churning lava lake, forced the drone to climb","letter":"C"},{"is_no_change":false,"label":"Flying low over the churning lava lake, it was the intense heat that forced the drone to climb","letter":"D"}]', 'B', '{"A":"The opening modifier dangles — it describes the drone, but ''the intense heat'' occupies the subject slot.","B":"Correct: the flyer, the drone, immediately follows the modifier that describes it.","C":"Relocates the modifier next to ''heat,'' absurdly making the heat the thing that flies.","D":"The expletive ''it'' still leaves the modifier with no true actor beside it — the dangler survives in disguise."}', 'An opening participial phrase must be followed **immediately** by the noun it describes — here, the machine that was flying.', 'Rearranging words feels like a repair, and ''it was the intense heat'' sounds emphatic and formal, but the modifier still lacks its true actor.', '1) Find the opening -ing modifier and ask: who or what performs this action? 2) Check the first noun after the comma — it must be that performer. 3) If it isn''t, rewrite so the doer lands right after the comma (or give the modifier its own subject). 4) Re-read: the sentence should answer ''who was doing this?'' instantly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e837d1c29c445707', 'act-english', 's-sent', 5, 'The report explains not only what the drought destroyed <u>but also how communities rebuilt afterward, being resilient.</u>', 'Which choice makes the two halves of the ''not only … but also'' pair parallel?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"but also how communities rebuilt afterward.","letter":"B"},{"is_no_change":false,"label":"but communities rebuilding afterward with resilience.","letter":"C"},{"is_no_change":false,"label":"but also the resilient rebuilding done by communities afterward.","letter":"D"}]', 'B', '{"A":"''What the drought destroyed'' is a clause; tacking on ''being resilient'' unbalances the paired halves.","B":"''How communities rebuilt'' mirrors ''what the drought destroyed'' — clause matched to clause.","C":"Dropping ''also'' breaks the fixed ''not only … but also'' pair and switches to a phrase.","D":"The noun phrase ''the resilient rebuilding'' no longer matches the ''what …'' clause on the other side."}', 'In ''not only X but also Y'', **X and Y must be the same structure** — here, two ''wh-'' clauses.', 'The extra ''being resilient'' adds a nice idea, so it''s tempting to keep despite breaking the balance.', 'Correlative pairs (not only/but also, either/or) demand identical grammatical forms on both sides.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-186b7588e3978eae', 'act-english', 's-style', 1, 'On a good night, a single barn owl <u>can catch</u> a dozen mice along the fence lines of the vacant rail yard.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"is capable of catching","letter":"B"},{"is_no_change":false,"label":"has the ability to catch","letter":"C"},{"is_no_change":false,"label":"possesses the capacity for the catching of","letter":"D"}]', 'A', '{"A":"Correct: the modal verb expresses the ability in the fewest words with no loss of meaning.","B":"Restates the same ability in a longer ''is capable of'' frame that adds no information (wordy_paraphrase).","C":"Wraps the idea in the empty scaffold ''has the ability to'' (ability_noun_padding).","D":"Triples the length with stacked abstract nouns while saying nothing new (abstract_noun_inflation)."}', 'When options mean the same thing, the **shortest accurate** version wins, and the simple modal already says everything.', '''Is capable of catching'' sounds more formal and deliberate, so students equate its length with precision.', '1) Check whether the options differ in meaning. 2) If they do not, strike every phrase that restates rather than adds. 3) Convert ''has the ability to'' or ''is capable of'' frames back to a simple verb and compare. 4) Choose the shortest version that keeps the full meaning. 5) Re-read to confirm nothing was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-357971fd05521008', 'act-english', 's-style', 1, 'Volunteers <u>gathered together</u> at the trailhead kiosk each morning before the day''s assignments were read out.', 'Which choice best avoids redundancy in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gathered together as a group","letter":"B"},{"is_no_change":false,"label":"gathered","letter":"C"},{"is_no_change":false,"label":"gathered together in one place","letter":"D"}]', 'C', '{"A":"*Together* restates the coming-together already guaranteed by the verb, so the pair is redundant.","B":"Triples the same idea: *together* and *as a group* both repeat what the verb already means.","C":"Correct: the verb alone carries the full meaning of assembling in one spot.","D":"*Together* and *in one place* each duplicate meaning built into the verb, doubling the redundancy."}', 'The verb already **contains** the idea of coming into one group, so every added phrase repeats it.', 'The original tempts students because ''gathered together'' is a common spoken collocation that sounds natural despite repeating itself.', '1) Define the verb''s built-in meaning. 2) Test each added word: does it say anything the verb doesn''t already guarantee? 3) Delete every word that fails the test. 4) Reread to confirm the meaning is unchanged.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-440ab66f21002d90', 'act-english', 's-style', 1, 'Test prints pile up quickly, so most printers <u>reuse</u> the backs of failed sheets for notes.', 'Which choice expresses the idea most concisely while preserving the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"make reuse of","letter":"B"},{"is_no_change":false,"label":"reuse once again","letter":"C"},{"is_no_change":false,"label":"utilize and reuse","letter":"D"}]', 'A', '{"A":"Correct: the single verb already carries the complete idea.","B":"Buries the action in a noun propped up by ''make'' (nominalization_padding), adding words but no meaning.","C":"Adds ''once again'' (redundant_re_prefix) even though the re- prefix already means the action is repeated.","D":"Bolts on ''utilize'' (doubled_verb), a dressed-up synonym that contributes nothing new."}', 'The single verb already carries the **complete** idea; every alternative adds words without adding meaning.', '''Make reuse of'' sounds formal and deliberate, so students mistake extra bulk for extra sophistication.', '1) Identify the core action of the underlined portion. 2) Strip each option down to the words that add information. 3) Cross out helper constructions like ''make ... of,'' repetitions of a prefix''s meaning, and synonym pairs. 4) Select the option with zero crossed-out words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-461f9009dd87f24e', 'act-english', 's-style', 1, 'The dawn chorus began <u>at that point in time</u> when the first robin sang from the top of the maple.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"at that particular point in time","letter":"B"},{"is_no_change":false,"label":"at the point of the time","letter":"C"},{"is_no_change":false,"label":"DELETE the underlined portion","letter":"D"}]', 'D', '{"A":"''At that point in time'' is filler — the ''when'' clause already fixes the moment.","B":"Adds ''particular,'' stretching the filler even longer without adding meaning.","C":"Reshuffles the same empty phrase into something clumsier and unidiomatic.","D":"Correct: ''began when the first robin sang'' says everything with no padding."}', 'The **''when'' clause** already pins down the moment, so the time phrase adds nothing but bulk.', '''At that point in time'' is so common in speech that it sounds like normal, harmless phrasing rather than filler.', '1) Read the sentence without the underlined phrase. 2) Ask whether any meaning disappeared. 3) If nothing was lost, the phrase is empty filler. 4) Prefer the version that keeps every unit of meaning in the fewest words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5c393a6b913316a8', 'act-english', 's-style', 1, 'Scientists study plankton closely <u>due to the fact that</u> these tiny organisms form the base of the ocean''s food web.', 'Which choice is most concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"owing to the fact that","letter":"B"},{"is_no_change":false,"label":"on account of the fact that","letter":"C"},{"is_no_change":false,"label":"because","letter":"D"}]', 'D', '{"A":"''Due to the fact that'' is a wordy phrase for a one-word conjunction (wordy_phrase).","B":"''Owing to the fact that'' is another inflated substitute for the simple conjunction (wordy_phrase).","C":"''On account of the fact that'' pads a simple link across five words (wordy_phrase).","D":"Correct: the single conjunction conveys the same reason with no wasted words."}', 'A reason can be signaled by one **conjunction**, so a multi-word phrase for it is padding.', 'The longer phrases sound more formal, so students keep them believing formality requires extra words.', '1) Spot phrases built around ''the fact that.'' 2) Ask what single conjunction expresses the same relationship. 3) Replace the phrase with that one word. 4) Re-read to confirm the meaning is unchanged.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-672521a75dc49fe0', 'act-english', 's-style', 1, 'Researchers now fly small camera drones over the shallows <u>in order to</u> photograph an entire reef in a single low pass.', 'Which choice is the most concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"so as to","letter":"B"},{"is_no_change":false,"label":"to","letter":"C"},{"is_no_change":false,"label":"in an effort to","letter":"D"}]', 'C', '{"A":"''In order to'' is a padded way of saying ''to'' (misconception: filler_purpose_phrase).","B":"''So as to'' is another wordy substitute for the plain ''to'' (misconception: wordy_purpose_variant).","C":"''To'' expresses the purpose in a single word — nothing is lost.","D":"''In an effort to'' adds an unneeded sense of striving and extra words (misconception: filler_with_extra_connotation)."}', 'A simple ''to'' states purpose completely; the longer versions are just **filler**.', '''In order to'' sounds formal and complete, so it seems more correct than the bare ''to.''', '1) Spot phrases whose whole job is to signal purpose. 2) Test whether replacing them with ''to'' changes the meaning. 3) If not, the longer phrase is filler. 4) Choose the shortest form that still reads smoothly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a78ebd8db67af5b', 'act-english', 's-style', 1, 'Even at the peak of their fame, swing orchestras <u>toured</u> for most of the year, stringing together one-nighters across the map.', 'Which choice is the most effective way to phrase the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"went out on tours","letter":"B"},{"is_no_change":false,"label":"engaged in the activity of touring","letter":"C"},{"is_no_change":false,"label":"carried out a touring schedule","letter":"D"}]', 'A', '{"A":"Correct: one exact verb does the entire job.","B":"wordy_phrase: four words deliver what the single verb already says.","C":"*Engaged in the activity of* is classic inflation wrapped around a simple action.","D":"*Carried out a schedule* smothers the action inside an empty noun phrase."}', 'The single **verb** is the tightest phrasing that keeps the full meaning.', 'Longer phrasings sound more formal, and students equate formal with better.', '1) Find the action in the sentence. 2) Ask whether that action can live in one verb. 3) Cut helper nouns like ''activity'' and ''schedule'' unless they add real information. 4) Reread to confirm the meaning is untouched.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6cabae3a3e4356d5', 'act-english', 's-style', 1, 'Coral polyps build their stony skeletons from the calcium carbonate they <u>extract</u> from the surrounding seawater.', 'Which choice is most concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"extract and remove","letter":"B"},{"is_no_change":false,"label":"extract out","letter":"C"},{"is_no_change":false,"label":"remove and extract out","letter":"D"}]', 'A', '{"A":"Correct: a single precise verb states the action with no repetition.","B":"Pairs two verbs that mean essentially the same thing, a redundant doubling (redundant_synonym).","C":"Adds ''out,'' which merely repeats the pulling-out sense already in the verb (redundant_particle).","D":"Combines a redundant synonym with an unnecessary particle, doubling the wordiness (redundant_synonym)."}', 'The lone verb already carries the full meaning, so any added synonym or particle is **redundant**.', 'The paired phrasing sounds thorough, so students add a second verb thinking it strengthens the idea.', '1) Read the phrase and ask whether any two words mean the same thing. 2) Check whether an added particle repeats meaning built into the verb. 3) Cut every word that adds no new information. 4) Keep the shortest phrasing that preserves the meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6ce1824d9d1c682e', 'act-english', 's-style', 1, 'Theater owners booked cartoon shorts <u>due to the fact that</u> audiences expected one before every feature.', 'Which choice makes the sentence most concise without losing meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"in light of the fact that","letter":"B"},{"is_no_change":false,"label":"because","letter":"C"},{"is_no_change":false,"label":"because of the fact that","letter":"D"}]', 'C', '{"A":"''Due to the fact that'' spends five words on a link one word can make.","B":"''In light of the fact that'' adds formality but no meaning — six words of filler.","C":"''Because'' states the causal link completely in one word.","D":"''Because of the fact that'' wraps the working word in pure padding."}', '''The fact that'' constructions are classic **filler**; the bare conjunction does the whole job.', 'The longer connectors sound more formal and essay-like, so students equate length with sophistication.', '1) Spot any phrase containing ''the fact that.'' 2) Ask what single connector the phrase reduces to. 3) Substitute the one-word version and reread. 4) If the meaning is unchanged, the shorter form wins.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6dd635f4b24cf7b2', 'act-english', 's-style', 1, 'The chess club <u>meets on Thursdays</u> in the library annex.', 'Which choice provides the most effective wording?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"meets, as a rule, on Thursdays","letter":"B"},{"is_no_change":false,"label":"basically meets on Thursdays, for all intents and purposes,","letter":"C"},{"is_no_change":false,"label":"meets, as it happens, on Thursdays","letter":"D"}]', 'A', '{"A":"The wording is already lean and exact; every word carries information.","B":"''as a rule'' hedges a plain fact without qualifying anything real.","C":"''basically'' and ''for all intents and purposes'' are empty intensifiers stacked on a simple statement.","D":"''as it happens'' is a filler aside that interrupts the sentence while adding nothing."}', 'Every word in the original carries **information**; each alternative inserts empty filler.', '''as a rule'' tempts because schedules do have exceptions, so a hedge feels responsibly cautious even though it adds no facts.', '1) Read each option and underline any word not stating a fact. 2) Delete the underlined words mentally and reread. 3) If the meaning is identical, those words were filler. 4) Keep the version where nothing can be deleted without losing meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-777aa9b0f6c6d0fe', 'act-english', 's-style', 1, 'On harvest mornings, members <u>gather</u> at the toolshed before sunrise to divide the picking routes.', 'Which choice avoids redundancy while preserving the meaning of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gather together","letter":"B"},{"is_no_change":false,"label":"gather and assemble together","letter":"C"},{"is_no_change":false,"label":"gather collectively in one place","letter":"D"}]', 'A', '{"A":"Correct: the single verb already contains the idea of coming together; nothing more is needed.","B":"Redundant modifier: ''together'' repeats meaning built into the verb itself.","C":"Triple redundancy: a synonym pair plus a built-in modifier say the same thing three times.","D":"Both add-ons restate what the verb and the toolshed setting already establish."}', 'The verb alone carries the full idea of coming together, so any added modifier is **redundant**.', '''Gather together'' is such a common spoken pairing that students hear it as natural rather than as repetition.', '1) Define the underlined verb in your own words. 2) Take each added word and ask: does it add information not already inside the verb''s definition? 3) Cut any word that repeats built-in meaning. 4) Reread the leanest version and confirm nothing was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97328f3161a58a87', 'act-english', 's-style', 1, 'Rangers at Grand Teton close the cliff trail <u>due to the fact that</u> ice glazes the ledges each January.', 'Which choice best improves the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because","letter":"B"},{"is_no_change":false,"label":"owing to the fact that","letter":"C"},{"is_no_change":false,"label":"for the reason that","letter":"D"}]', 'B', '{"A":"Stretches one connecting idea across five words.","B":"Expresses the causal link in a single exact word.","C":"Swaps in an equally bloated five-word formula.","D":"Trades one wordy formula for another four-word one."}', 'One word can carry the causal link, and ACT style always prefers the **shortest grammatical option that preserves meaning**.', '''Due to the fact that'' appears constantly in official-sounding writing, so it reads as extra formality rather than padding.', '1) Identify the job the underlined phrase does (here: linking cause to effect). 2) Ask if a single word does the same job. 3) Substitute and re-read for meaning. 4) If nothing is lost, take the shorter version.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a3ef2a7fa776731f', 'act-english', 's-style', 1, 'In 1917, the Original Dixieland Jass Band cut what most historians call the <u>first initial</u> jazz recording.', 'Which choice makes the sentence most concise without changing its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"first and initial","letter":"B"},{"is_no_change":false,"label":"very first initial","letter":"C"},{"is_no_change":false,"label":"first","letter":"D"}]', 'D', '{"A":"redundant_synonym: *first* and *initial* mean the same thing, so the pair says one thing twice.","B":"Joining the synonyms with *and* doubles the redundancy rather than fixing it.","C":"*Very* piles an intensifier onto the same doubled meaning.","D":"Correct: one word carries the entire meaning."}', 'One word says everything; its **synonym** adds words but no meaning.', 'Paired words feel more thorough, as if two synonyms make the claim stronger.', '1) Define each underlined word separately. 2) If two definitions overlap completely, cut one. 3) Reread: has any meaning been lost? 4) If nothing is lost, the trimmed version wins.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bd969c2414b0af7b', 'act-english', 's-style', 1, '<u>As a matter of fact, the</u> first commercial broadcasting license in the United States was issued in 1920.', 'Which choice makes the sentence clearest and most direct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In point of fact, the","letter":"B"},{"is_no_change":false,"label":"The","letter":"C"},{"is_no_change":false,"label":"It is actually a fact that the","letter":"D"}]', 'C', '{"A":"''As a matter of fact'' is throat-clearing that adds nothing to the sentence''s content.","B":"''In point of fact'' is the same filler formula in different clothes.","C":"Correct: the sentence states its fact plainly with no empty preamble.","D":"The expletive frame ''It is actually a fact that'' certifies its own sentence — the emptiest kind of filler."}', '**Empty openers** that announce a fact before stating it can be deleted with zero loss of meaning.', 'Filler openers sound conversational and confident, so students read them as emphasis instead of padding.', '1) Cover the opening phrase and reread the sentence. 2) Ask: did any information disappear? 3) If nothing disappeared, the opener is filler — cut it. 4) Repeat for any candidate replacement. 5) Keep the version that starts with the real subject.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d5230c64d9fca00a', 'act-english', 's-style', 1, 'Customs officials <u>made an inspection of</u> every trunk stacked on the pier.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"inspected","letter":"B"},{"is_no_change":false,"label":"conducted an inspection of","letter":"C"},{"is_no_change":false,"label":"gave an inspection to","letter":"D"}]', 'B', '{"A":"''Made an inspection of'' stretches one action into a padded verb-plus-noun phrase.","B":"Correct: the single verb delivers the entire action without padding.","C":"''Conducted an inspection of'' dresses the padding in a fancier verb but keeps every extra word.","D":"''Gave an inspection to'' is unidiomatic as well as wordy."}', 'One **strong verb** carries the whole action that the noun phrase buries.', '''Conducted an inspection of'' tempts because it sounds official and formal, which masks the wordiness.', '1) Find the action hiding inside a noun. 2) Rewrite the sentence with that action as the verb. 3) Compare: if the meaning is identical, prefer the tighter version. 4) Reject swaps still built around the buried noun. 5) Check the survivor for idiom and tense.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d6571d2d53b36fc3', 'act-english', 's-style', 1, 'Each spring, the same mallard hens <u>return back again</u> to the courtyard fountain where they hatched.', 'Which choice makes the sentence most concise without changing its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"return back","letter":"B"},{"is_no_change":false,"label":"return","letter":"C"},{"is_no_change":false,"label":"make their return back","letter":"D"}]', 'C', '{"A":"''Back'' and ''again'' both repeat ideas already built into the verb (redundant_double_modifier).","B":"Trims one duplicate but keeps ''back,'' which the verb already expresses (redundant_partial_trim).","C":"Correct: the verb alone carries the full meaning of coming back to a place once more.","D":"Swaps a crisp verb for a padded noun phrase and keeps the redundant direction word (nominalization_padding)."}', 'The verb already means to come back, so any added **direction or repetition word** is redundant.', '''Return back'' survives many students'' ear-check because the pairing is common in casual speech.', '1) Define the underlined verb in your own words. 2) Cross out any nearby word repeating part of that definition. 3) Re-read the trimmed sentence and confirm no meaning was lost. 4) If two options survive, prefer the one with zero duplicated ideas. 5) Confirm the final version still says exactly what the original meant.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e0ec37ffff8c0bac', 'act-english', 's-style', 1, '<u>Because</u> the beds are built waist-high, gardeners who use wheelchairs can work without bending or reaching.', 'Which choice best avoids unnecessary wordiness?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Due to the fact that","letter":"B"},{"is_no_change":false,"label":"On account of the fact that","letter":"C"},{"is_no_change":false,"label":"Being that","letter":"D"}]', 'A', '{"A":"Correct: one precise conjunction does the entire job.","B":"Inflated: ''the fact that'' adds five words and zero meaning.","C":"Even more inflated: six words performing a one-word task.","D":"Short but nonstandard: a colloquialism that formal written English avoids."}', 'Formal writing prefers the **tightest** construction that keeps the meaning, and the one-word conjunction loses nothing.', 'The ''fact that'' constructions sound official and essay-like, so students equate their bulk with formality.', '1) Isolate the connecting phrase. 2) Swap in the shortest conjunction with the same meaning and reread. 3) If nothing is lost, the longer phrase is padding — cut it. 4) Also screen the short options for register: brief but casual phrases fail too. 5) Keep the version that is both shortest and standard.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-00c97e9d5b86e00f', 'act-english', 's-style', 2, 'A good ballad <u>says</u> a complete story in only a handful of verses.', 'Which word most precisely fits the context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"speaks","letter":"B"},{"is_no_change":false,"label":"remarks","letter":"C"},{"is_no_change":false,"label":"tells","letter":"D"}]', 'D', '{"A":"''Says a story'' is not idiomatic — ''say'' takes words or statements, not stories.","B":"''Speaks'' cannot take ''a story'' as its object; one speaks a language, not a story.","C":"''Remarks'' means to comment briefly in passing, the opposite of delivering a full narrative.","D":"Correct: stories are told; the verb pairs precisely with the object."}', 'Precision here is about **collocation** — the verb that English pairs with ''a story'' as its object.', '''Says'' tempts students because it is the everyday verb for speech, and the ear forgives it on a quick read.', '1) Find the verb''s object (''a story''). 2) Ask which verbs naturally take that object in everyday English. 3) Test each option in the frame ''to ___ a story.'' 4) Reject any verb that breaks the pairing or changes the scale of the action. 5) Choose the verb that fits the object exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-02d2d036c07c5d7e', 'act-english', 's-style', 2, 'In its final report, the review board <u>commended</u> the team for its meticulous record keeping.', 'Which choice best maintains the formal style of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gave a shout-out to","letter":"B"},{"is_no_change":false,"label":"was totally impressed with","letter":"C"},{"is_no_change":false,"label":"thought the world of","letter":"D"}]', 'A', '{"A":"''Commended'' matches the formal register of ''final report'' and ''review board.''","B":"''Shout-out'' is social-media slang, clashing with an official report (slang intrusion).","C":"''Totally impressed'' is conversational intensifier talk, not report language (casual intensifier).","D":"''Thought the world of'' is a cozy idiom too informal for the context (folksy idiom)."}', 'The original verb already matches the sentence''s **formal register**, so it should stand.', '''Was totally impressed with'' feels vivid and clear, so students trade formality for punch without noticing the register clash.', '1) Identify the context clues for register (''final report,'' ''review board''). 2) Label the required register: formal. 3) Grade each option against that label. 4) If the original already matches, keep it; revise only what is broken.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-038f8016ffed3337', 'act-english', 's-style', 2, 'Last February, the sorting team <u>made the decision to donate</u> unsold coats to a nearby shelter.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"decided to donate","letter":"B"},{"is_no_change":false,"label":"decided on making a donation of","letter":"C"},{"is_no_change":false,"label":"came to the decision that it would be best to donate","letter":"D"}]', 'B', '{"A":"''Made the decision to'' is a padded version of a single verb.","B":"Correct: one verb delivers the entire meaning without padding.","C":"Trades one padded phrase for another, burying the action in ''making a donation of.''","D":"Expands the padding further with an empty judgment clause."}', 'When a phrase can shrink to a single verb with **no loss of meaning**, the shorter version is correct.', '''Made the decision'' sounds weightier and more official, so students equate its bulk with precision.', '1) Find the action hiding inside the noun phrase. 2) Replace the phrase with that verb. 3) Compare meanings — if identical, keep the verb. 4) Scan the shorter option for leftover padding. 5) Confirm grammar still works in context.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0cae2ba3f5c992eb', 'act-english', 's-style', 2, 'To count the faint die scratches on the ancient coin, the intern <u>looked at</u> it under a stereo microscope for more than an hour.', 'Which choice most precisely conveys the intern''s action?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"glanced at","letter":"B"},{"is_no_change":false,"label":"witnessed","letter":"C"},{"is_no_change":false,"label":"examined","letter":"D"}]', 'D', '{"A":"''Looked at'' is grammatical but vague; it misses the sustained, purposeful scrutiny the context describes.","B":"''Glanced at'' means a brief look, contradicting the hour of close work.","C":"''Witnessed'' applies to observing events, not studying objects.","D":"Correct: this verb denotes close, systematic inspection — exactly what an hour at a microscope involves."}', 'Precision means choosing the verb whose **specific meaning matches the context**: prolonged, detailed inspection.', 'The vague original is not wrong-sounding, so students keep it rather than seek the sharper verb.', '1) Gather the context clues about the action (purpose, duration, tools). 2) Define each option''s verb in a short phrase. 3) Eliminate verbs whose definitions contradict a clue (too brief, wrong object type). 4) Among the survivors, choose the most specific verb, not merely an acceptable one.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0cb0370b41c69ad2', 'act-english', 's-style', 2, 'Frost can whiten low-lying fields <u>even when official thermometer readings stay</u> a few degrees above freezing.', 'Which choice expresses the idea most effectively and concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"even when, as a matter of fact, official thermometer readings stay","letter":"B"},{"is_no_change":false,"label":"even in the event that it so happens that official thermometer readings stay","letter":"C"},{"is_no_change":false,"label":"even when official thermometer readings, for all intents and purposes, stay","letter":"D"}]', 'A', '{"A":"Correct: the original states the condition directly, with no filler.","B":"''As a matter of fact'' asserts nothing the sentence does not already assert (misconception: filler phrases add emphasis).","C":"''In the event that it so happens that'' buries the simple time word under empty machinery (misconception: elaborate phrasing sounds precise).","D":"''For all intents and purposes'' hedges a plain factual claim for no reason (misconception: stock phrases add authority)."}', 'The original is already **filler-free**; every candidate revision adds words that assert nothing.', '''For all intents and purposes'' is common in serious-sounding prose, so it passes as a scholarly touch.', '1) Read the sentence and mark any phrase you could delete without losing a fact. 2) Delete it mentally and re-read. 3) If the meaning is untouched, the phrase is filler. 4) Prefer the version with zero deletable phrases. 5) Confirm the survivor still reads smoothly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-158e2333a24d5401', 'act-english', 's-style', 2, 'Interest in the seedling swap <u>doubled</u> after the newsletter ran a front-page profile of the event.', 'Which choice expresses the idea most concisely while keeping its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"increased by a factor of two","letter":"B"},{"is_no_change":false,"label":"grew until it reached twice its former level","letter":"C"},{"is_no_change":false,"label":"underwent a doubling","letter":"D"}]', 'A', '{"A":"Correct: one verb carries the entire quantity with no loss of precision.","B":"Unpacks the verb into a formula that adds words but no accuracy.","C":"Narrates the climb step by step when only the end result matters.","D":"Nominalization: burying the action in a noun forces in the empty verb ''underwent.''"}', 'A single verb states the **entire** change; every longer version repeats that same quantity in more words.', '''Increased by a factor of two'' sounds mathematically precise, so students assume it says more than the one-word verb — it doesn''t.', '1) State the fact the sentence must convey. 2) For each option, ask: does it add information, or only words? 3) Watch for two padding patterns — formulas that restate a verb, and nouns that swallow the action and demand an empty helper verb. 4) Keep the shortest version that preserves every fact. 5) Reread for smoothness.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1666105e3526bbff', 'act-english', 's-style', 2, 'In a statement released Tuesday, the league office <u>approved</u> the franchise''s request to relocate its Class A affiliate.', 'Which choice best maintains the formal style established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gave a thumbs-up to","letter":"B"},{"is_no_change":false,"label":"was totally on board with","letter":"C"},{"is_no_change":false,"label":"okayed","letter":"D"}]', 'A', '{"A":"Correct: the verb matches the official register of a formal league statement.","B":"A breezy gesture idiom that clashes with institutional language (casual_idiom).","C":"A slang intensifier plus a conversational idiom — two register violations at once (slang_register).","D":"Informal clipped verb that dips below press-release diction (colloquial_clip)."}', 'The frame — an official statement — sets a formal **register**, and the original verb is the only option written at that level.', '''Okayed'' is short and clear, so students mistake its brevity for appropriate directness despite its casual register.', '1) Identify the sentence''s setting from its non-underlined words (an official statement). 2) Label the required register: formal, neutral, or casual. 3) Label each option''s register. 4) Eliminate every mismatch, even vivid ones. 5) Keep the option that could appear in the original document''s own prose.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1b07b0cd107fed38', 'act-english', 's-style', 2, 'The two editors <u>collaborated</u> on the investigation for six months before publishing a single word.', 'Which choice is most concise while preserving the meaning of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"collaborated together","letter":"B"},{"is_no_change":false,"label":"collaborated jointly together","letter":"C"},{"is_no_change":false,"label":"collaborated with each other jointly","letter":"D"}]', 'A', '{"A":"Correct: the verb already contains the idea of working together, so nothing more is needed.","B":"''Together'' repeats meaning built into the verb itself — a redundant modifier.","C":"Stacks two redundant modifiers that both restate the verb''s core idea.","D":"Adds two more ways of saying what the verb already says, tripling the same idea."}', '**Collaborated** already means worked together, so any added modifier only repeats it.', '''Collaborated together'' tempts students because the pairing is common in casual speech and sounds emphatic rather than repetitive.', '1) Define the underlined verb precisely. 2) Ask what each added word contributes beyond that definition. 3) Delete any word whose meaning the verb already carries. 4) Prefer the leanest version that keeps the full meaning. 5) Re-read to confirm nothing was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2a5b343626547275', 'act-english', 's-style', 2, 'Before the regional, the mechanical and software subteams <u>combined</u> their separate checklists into a single pit binder.', 'Which choice is the most effective for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"combined together","letter":"B"},{"is_no_change":false,"label":"combined and merged","letter":"C"},{"is_no_change":false,"label":"mutually combined together","letter":"D"}]', 'A', '{"A":"Correct: the verb alone carries the complete idea of joining the checklists.","B":"Adds ''together,'' which merely repeats meaning already inside the verb (redundant_adverb).","C":"Stacks a synonym onto the verb, doubling the same idea (redundant_synonym_pair).","D":"Layers two redundant modifiers onto the verb at once (redundant_double_layer)."}', 'The single verb already expresses the full idea; every alternative adds words that **repeat** its built-in meaning.', '''Combined together'' is so common in casual speech that the redundancy is invisible to most readers.', '1) Define the verb precisely. 2) Test every added word: does it repeat part of that definition? 3) Delete each word that does. 4) Keep the version with zero repeats.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2c333a5e989049b3', 'act-english', 's-style', 2, '<u>It is interesting to note that the</u> family''s first apartment stood two blocks from the harbor, close enough to hear the ferry horns.', 'Which choice expresses the idea most directly?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"As a matter of fact, the","letter":"B"},{"is_no_change":false,"label":"The","letter":"C"},{"is_no_change":false,"label":"It should be noted that the","letter":"D"}]', 'C', '{"A":"''It is interesting to note that'' announces interest without adding any information.","B":"''As a matter of fact'' swaps one empty opener for another; nothing is being corrected or emphasized.","C":"Correct: deleting the filler lets the sentence begin with its actual subject.","D":"''It should be noted that'' is throat-clearing in an academic costume."}', 'Cutting the **filler** phrase lets the sentence lead with its real content at no cost in meaning.', '''It should be noted that'' tempts because it sounds scholarly, but formality is not the same as content.', '1) Bracket the opening phrase. 2) Delete it mentally and re-read. 3) If no meaning is lost, the phrase is filler — cut it. 4) Watch for replacement fillers sneaking in. 5) Keep the version that starts with the subject.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2ef6e5e33b63da7b', 'act-english', 's-style', 2, 'The suspension cables are inspected annually <u>each year</u> by a team of certified climbers.', 'Which choice makes the sentence most concise without losing information?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"every single year","letter":"B"},{"is_no_change":false,"label":"on a yearly basis","letter":"C"},{"is_no_change":false,"label":"DELETE the underlined portion.","letter":"D"}]', 'D', '{"A":"''Each year'' repeats exactly what ''annually'' already states (misconception: redundant_synonym_kept).","B":"Swaps in a wordier duplicate, deepening the redundancy (misconception: redundant_intensified).","C":"Restates ''annually'' with extra padding; the doubling remains (misconception: redundant_reworded).","D":"Removing the phrase leaves ''annually'' to state the frequency once, cleanly."}', 'Since ''annually'' already gives the frequency, **removing** the duplicate phrase is the only fix that ends the repetition.', '''On a yearly basis'' sounds more polished than ''each year,'' so students reword the duplicate instead of noticing it duplicates at all.', '1) Underline every word or phrase expressing the same fact. 2) If two expressions match in meaning, keep exactly one. 3) Test the sentence with the extra expression removed — no meaning should be lost. 4) Reject any option that rewords the duplicate instead of removing it.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-368be8b8afa61032', 'act-english', 's-style', 2, 'At Rocky Mountain National Park, visitors should <u>basically just plan on trying to</u> reach the Bear Lake lot before eight in the morning.', 'Which choice best improves the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"basically plan to","letter":"B"},{"is_no_change":false,"label":"plan to","letter":"C"},{"is_no_change":false,"label":"just plan on","letter":"D"}]', 'C', '{"A":"Strings three fillers—''basically,'' ''just,'' and ''trying to''—around the real advice.","B":"Deletes some padding but keeps the empty qualifier ''basically.''","C":"Strips every filler, leaving the complete instruction.","D":"Trades one filler for another and keeps the casual idiom ''plan on.''"}', '''Basically,'' ''just,'' and ''trying to'' add **no information**—the bare instruction says everything.', 'Keeping ''basically'' feels like preserving the sentence''s easygoing tone rather than deleting dead weight.', '1) Delete each qualifier one at a time. 2) After each deletion, ask: did any meaning vanish? 3) If not, the word was filler—leave it out. 4) Keep only words that change what the reader knows or must do.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3b65d25513ef6927', 'act-english', 's-style', 2, '<u>Due to the fact that</u> the creek had jumped its banks in the spring flood, the crew rerouted a quarter mile of tread onto higher ground.', 'Which choice makes the sentence most concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In light of the fact that","letter":"B"},{"is_no_change":false,"label":"Owing to the fact that","letter":"C"},{"is_no_change":false,"label":"Because","letter":"D"}]', 'D', '{"A":"Spends five words on a signal that a single conjunction can send; the ''the fact that'' scaffold adds bulk, not meaning.","B":"Trades one padded formula for an even more inflated one; the empty scaffold remains.","C":"Keeps the identical filler under a different opener, so nothing has actually been trimmed.","D":"Correct: one conjunction performs the entire cause-signaling job the five-word phrase was doing."}', 'A single **conjunction** does everything the padded phrase does, so the shorter form wins with zero loss of meaning.', 'The longer openers tempt students who equate formality with quality, mistaking padding for polish.', '1) Find the phrase''s single function — here, signaling cause. 2) Ask how few words can perform that function. 3) Cut scaffold phrases like ''the fact that'' on sight. 4) Reread to confirm no meaning was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3c570ac19b6c03e6', 'act-english', 's-style', 2, 'The recipe insisted that we chill the dough <u>first before</u> rolling it, or the butter would leak out during baking.', 'Which choice best eliminates the redundancy?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"at first before","letter":"B"},{"is_no_change":false,"label":"before","letter":"C"},{"is_no_change":false,"label":"first, and before","letter":"D"}]', 'C', '{"A":"Redundant pair: ''first'' and ''before'' both mark the earlier action, so one repeats the other.","B":"Worse redundancy: ''at first'' still overlaps entirely with ''before.''","C":"Correct: ''before'' alone conveys the sequence, so dropping ''first'' removes the repetition.","D":"Adds clutter: the comma-and-conjunction patch keeps ''first'' and tangles the sentence further."}', '''First'' and ''before'' both signal the earlier step, so keeping only **''before''** ends the redundancy.', 'Pairing ''first'' with ''before'' feels like helpful emphasis of the sequence rather than repetition.', '1) Look for two words that carry the same meaning side by side. 2) Ask whether removing one changes the meaning. 3) If not, the pair is redundant. 4) Keep the single word that does the job. 5) Reread to confirm the sentence still says everything it needs to.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3e4a4c2facf222c9', 'act-english', 's-style', 2, 'For eighty years, the narrow-gauge line <u>carried</u> slate from the mountain quarries down to the harbor.', 'Which choice is best for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"basically carried","letter":"B"},{"is_no_change":false,"label":"carried, for all intents and purposes,","letter":"C"},{"is_no_change":false,"label":"in a very real sense carried","letter":"D"}]', 'A', '{"A":"Correct: the plain verb states the fact; nothing about it needs qualifying.","B":"''Basically'' hedges a claim that is not approximate, adding filler.","C":"''For all intents and purposes'' is a stock idiom that delays the object without adding meaning.","D":"''In a very real sense'' insists the claim is real without supplying any information."}', 'The verb needs no hedge: **filler** phrases that can be deleted without changing meaning must be deleted.', '''For all intents and purposes'' sounds like polished adult prose, so students mistake the familiar idiom for substance.', '1) Bracket any phrase you could delete without altering the sentence''s claim. 2) If deletion changes nothing, the phrase is filler. 3) Reject options that insert hedges, intensifiers, or stock idioms. 4) Reread the surviving sentence to confirm it says everything the original did.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3ea61487bd2c8347', 'act-english', 's-style', 2, 'As the loaves cooled on the rack, their crusts <u>crackled</u> softly—a sound the baker''s children raced downstairs to catch.', 'Which choice most precisely conveys the sound described?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shattered","letter":"B"},{"is_no_change":false,"label":"chattered","letter":"C"},{"is_no_change":false,"label":"rustled","letter":"D"}]', 'A', '{"A":"Correct — ''crackled'' names the small, sharp popping sounds a cooling crust actually makes.","B":"''Shattered'' describes violent breaking apart, far too destructive for a cooling loaf (precision_too_extreme).","C":"''Chattered'' belongs to teeth and talkers, not to baked crusts (precision_wrong_agent).","D":"''Rustled'' is the soft whisper of paper or leaves, missing the crisp popping quality (precision_wrong_texture)."}', 'Cooling crusts give tiny sharp pops, and **crackled** is the verb that names exactly that sound.', '''Rustled'' is also a quiet sound, so its softness feels compatible with the adverb ''softly.''', '1) Picture the literal scene. 2) Define each candidate word precisely — what sound, made by what, at what intensity? 3) Eliminate words that are too strong, too weak, or tied to the wrong source. 4) Choose the word matching the scene exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-422adeecf4610ae9', 'act-english', 's-style', 2, 'The county''s iron drawbridge <u>expired</u> in 1988, when a fixed concrete span replaced it.', 'Which choice most precisely describes what happened to the drawbridge?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was retired","letter":"B"},{"is_no_change":false,"label":"passed on","letter":"C"},{"is_no_change":false,"label":"went extinct","letter":"D"}]', 'B', '{"A":"''Expired'' belongs to licenses, deadlines, and perishables, not to structures taken out of service (misconception: precision_wrong_domain).","B":"The standard verb for equipment or structures withdrawn from service, precisely matching the event.","C":"A euphemism for a person''s death, absurd for a machine (misconception: precision_person_euphemism).","D":"Extinction describes an entire category dying out, not one structure''s end (misconception: precision_category_for_individual)."}', 'Precision means matching the verb to its **domain**: structures withdrawn from use take this verb, not words for documents, people, or species.', '''Expired'' feels close because the drawbridge''s useful life ended, but the word''s domain is dated documents and perishables, not steel structures.', '1) Identify what literally happened (the county stopped using the structure). 2) For each verb, list its usual companions (what kinds of things do this?). 3) Reject verbs whose companions are documents, people, or species. 4) Keep the verb whose domain includes machinery and infrastructure. 5) Reread the sentence to confirm the fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-488b0c11aa4121d9', 'act-english', 's-style', 2, 'A downward-facing color sensor <u>notices</u> changes in floor brightness as the robot crosses the white gaffer-tape line.', 'Which choice most precisely describes the sensor''s function?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"witnesses","letter":"B"},{"is_no_change":false,"label":"feels","letter":"C"},{"is_no_change":false,"label":"detects","letter":"D"}]', 'D', '{"A":"Attributes casual human awareness to an electronic component (verb_personification).","B":"Imports a bystander, almost legal connotation that misfits an instrument (verb_wrong_connotation).","C":"Implies touch or emotion, which a color sensor has neither of (verb_literal_mismatch).","D":"Correct: this is the standard, precise verb for an instrument registering a signal."}', 'It is the **standard, precise verb** for an instrument registering a signal.', 'The original tempts readers because we casually personify machines in everyday speech.', '1) Identify the subject''s nature: person or device? 2) Strike verbs implying consciousness or touch when the subject is a device. 3) Choose the verb used in technical writing for that exact operation.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-49b30384f3e5fdfc', 'act-english', 's-style', 2, 'With Sunday''s extra-inning win, the Owls <u>returned back</u> to first place in the Valley Division.', 'Which choice makes the sentence most concise while preserving its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"returned back again","letter":"B"},{"is_no_change":false,"label":"returned","letter":"C"},{"is_no_change":false,"label":"made a return back","letter":"D"}]', 'C', '{"A":"''Back'' duplicates the meaning already built into the ''re-'' verb (redundant_particle).","B":"Piles a second duplicate, ''again,'' onto the first (double_redundancy).","C":"Correct: the verb alone carries the entire idea of going back.","D":"A wordy nominalization that keeps the same redundancy (nominalization_plus_redundancy)."}', '**Redundancy** check: the ''re-'' verb already means going back, so every added word repeats it.', '''Returned back'' is common in casual speech, so the doubled idea sounds normal rather than repetitive.', '1) Define the verb in plain words. 2) Compare each neighboring word to that definition. 3) Cross out any word whose meaning the verb already contains. 4) Re-read the trimmed sentence and confirm no meaning was lost. 5) Prefer the version where every word earns its place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4a10abf81ef90ccc', 'act-english', 's-style', 2, '<u>Due to the fact that</u> wooden poster type swells in humid weather, printers stored it beside the stove.', 'Which choice makes the sentence most concise while preserving its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Because","letter":"B"},{"is_no_change":false,"label":"In light of the fact that","letter":"C"},{"is_no_change":false,"label":"Being as how","letter":"D"}]', 'B', '{"A":"''Due to the fact that'' spends five words doing one word''s job.","B":"''Because'' delivers the causal link in a single word with no loss of meaning.","C":"''In light of the fact that'' is an even longer formula around the same simple link.","D":"''Being as how'' is both wordy and nonstandard in written English."}', 'One exact word replaces the entire filler formula while keeping the **causal** link intact.', '''Due to the fact that'' tempts because its formality sounds academic, though it adds only bulk.', '1) Spot formula phrases built around ''the fact that.'' 2) Ask what single word expresses the same link. 3) Substitute the single word and re-read. 4) If meaning and grammar hold, keep the substitution. 5) Scan the rest of the sentence for similar formulas.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4e41a0b434807a9a', 'act-english', 's-style', 2, 'In its letter to the county historical society, the family wrote that the bakery <u>has hung onto a ton of</u> its original fixtures, including the marble counter installed in 1931.', 'Which choice best maintains the formal style appropriate to a letter to a historical society?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"has preserved many of","letter":"B"},{"is_no_change":false,"label":"has kept ahold of loads of","letter":"C"},{"is_no_change":false,"label":"is still totally rocking","letter":"D"}]', 'B', '{"A":"''Hung onto a ton of'' is casual spoken idiom, mismatched with a formal letter (register_colloquial_idiom).","B":"Correct — measured, formal diction suited to official correspondence with a historical society.","C":"''Kept ahold of loads of'' doubles down on informal idiom and a nonstandard form (register_informal_double).","D":"''Still totally rocking'' is slang, wildly out of register for the context (register_slang)."}', 'A formal letter calls for **standard, measured diction**, and this phrasing reports the fact without idiom or slang.', '''Hung onto a ton of'' is vivid and familiar, so its informality is easy to overlook in a quick read.', '1) Identify the document type and audience. 2) Set the register bar accordingly (official letter = formal). 3) Flag idioms, slang, and chatty intensifiers in each option. 4) Choose the option whose diction clears the bar.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-51297f56d655efb0', 'act-english', 's-style', 2, 'As the runner rounded third, the roar of the crowd <u>inflated</u> until the press box windows rattled.', 'Which choice most precisely describes what the crowd''s roar did?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"bloated","letter":"B"},{"is_no_change":false,"label":"swelled","letter":"C"},{"is_no_change":false,"label":"enlarged","letter":"D"}]', 'C', '{"A":"''Inflated'' belongs to balloons and prices — things filled with air or artificially increased — not sound (wrong_collocation).","B":"''Bloated'' drags in connotations of sickness and unhealthy excess (negative_connotation).","C":"Correct: the conventional verb for a sound rising steadily in volume and force.","D":"''Enlarged'' applies to physical dimensions and images, not audio (category_mismatch)."}', 'Precision means matching the verb to its noun''s **category**, and this is the verb English customarily pairs with rising sound.', '''Inflated'' shares the general grow-bigger meaning, so students accept it without testing what kinds of things actually inflate.', '1) Identify the noun the verb acts on (a roar — a sound). 2) List what each candidate verb usually happens to. 3) Eliminate verbs tied to the wrong category (air-filled objects, body tissue, physical size). 4) Check connotation: positive, neutral, negative. 5) Choose the verb whose habits and tone both fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-54493c97fcb290fa', 'act-english', 's-style', 2, 'When the wall of sand swallowed the horizon in minutes, the seasoned expedition <u>totally freaked out</u> and scrambled to lash down the tents.', 'Which choice best fits the formal style of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"kind of lost it","letter":"B"},{"is_no_change":false,"label":"grew alarmed","letter":"C"},{"is_no_change":false,"label":"was bugging out","letter":"D"}]', 'C', '{"A":"''Totally freaked out'' is slang that clashes with the passage''s measured, formal tone (register_too_casual).","B":"''Kind of lost it'' is vague, conversational filler unsuited to the passage (register_too_casual).","C":"Correct: the phrasing is composed and formal, matching the surrounding style.","D":"''Was bugging out'' is slang out of keeping with the formal narrative (register_too_casual)."}', 'The passage''s **formal narrative style** calls for composed diction rather than slang.', 'The slang phrase vividly conveys panic, so students choose it for energy without checking that it clashes with the formal tone.', '1) Judge the passage''s register from its surrounding diction (formal, composed). 2) Label each option as slang, casual, or formal. 3) Discard any slangy or conversational phrasing. 4) Keep the option whose tone matches the passage. 5) Re-read the sentence to confirm the register stays consistent.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5deba2fa670c0838', 'act-english', 's-style', 2, 'The Friends of the Library gather <u>each month on a monthly basis</u> to plan the spring used-book sale.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"on a monthly basis each month","letter":"B"},{"is_no_change":false,"label":"each and every month on a monthly basis","letter":"C"},{"is_no_change":false,"label":"each month","letter":"D"}]', 'D', '{"A":"States the meeting frequency twice — ''each month'' and ''on a monthly basis'' mean the same thing.","B":"Reorders the two frequency phrases without removing the duplication.","C":"Piles the emphatic doublet ''each and every'' onto the duplicate phrase, tripling the repetition.","D":"Correct: it states the frequency exactly once with no loss of meaning."}', '**Redundancy** is the error: the frequency must be stated once, and this option does exactly that.', 'The reordered version sounds revised, so students assume the problem was word order rather than duplication.', '1) Ask what fact the underlined words convey. 2) Count how many times that same fact is stated. 3) If more than once, cut until it appears exactly once. 4) Re-read to confirm no meaning was lost. 5) Reject any option that keeps or multiplies the duplicate.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7151295456fb55d9', 'act-english', 's-style', 2, 'The library''s new circulation policy states that patrons <u>gotta hang onto</u> their date-due receipts until all items are returned.', 'Which choice is most appropriate for the formal register of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"should hang onto","letter":"B"},{"is_no_change":false,"label":"gotta keep","letter":"C"},{"is_no_change":false,"label":"should retain","letter":"D"}]', 'D', '{"A":"''Gotta'' and ''hang onto'' are both casual speech, clashing with the formal policy language.","B":"Fixes the nonstandard verb but keeps the conversational idiom ''hang onto.''","C":"Keeps ''gotta,'' a spoken contraction that never belongs in a written policy.","D":"Correct: both words match the formal register of an official circulation policy."}', 'A formal document requires **formal diction in every word**, and only this option replaces both casual elements.', 'Replacing the most glaring slang word feels like enough, so students keep the informal idiom that remains.', '1) Identify the document''s register from its context — here, an official policy. 2) Flag every casual word or idiom in the underlined portion. 3) Replace all flagged items with standard formal equivalents, not just the worst one. 4) Re-read the sentence in the document''s voice to confirm consistency.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7905d977a4e7ca98', 'act-english', 's-style', 2, 'The chef explained that <u>due to the fact that</u> the oven runs hot, every recipe''s baking time must be trimmed by a few minutes.', 'Which choice is most concise while keeping the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because","letter":"B"},{"is_no_change":false,"label":"in view of the fact that","letter":"C"},{"is_no_change":false,"label":"on account of the reason that","letter":"D"}]', 'B', '{"A":"Wordy: ''due to the fact that'' is a five-word way of saying one word.","B":"Correct: ''because'' says exactly the same thing in a single word.","C":"Equally bloated: ''in view of the fact that'' merely swaps one padded phrase for another.","D":"Even wordier: ''on account of the reason that'' compounds the padding with a redundant ''reason.''"}', '''Due to the fact that'' is a classic filler phrase that **''because''** replaces exactly and cleanly.', 'The long phrase sounds formal and academic, so it can feel more polished than a plain single word.', '1) Spot bloated connector phrases like ''due to the fact that.'' 2) Ask what single conjunction carries the same meaning. 3) Replace the phrase with that one word. 4) Confirm no meaning is lost. 5) Reread for the leanest version that still works.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-818131b30c9d2091', 'act-english', 's-style', 2, 'For nearly three centuries, the hidden spring <u>gave</u> water to every weary caravan lucky enough to stumble upon it.', 'Which choice most precisely conveys that the spring furnished water dependably over time?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"supplied","letter":"B"},{"is_no_change":false,"label":"granted","letter":"C"},{"is_no_change":false,"label":"donated","letter":"D"}]', 'B', '{"A":"''Gave'' is too general to capture the steady, dependable provision the sentence describes (imprecise_word).","B":"Correct: it precisely names the reliable, ongoing furnishing of a needed resource.","C":"''Granted'' implies bestowing permission or a favor, not furnishing a physical resource (wrong_connotation).","D":"''Donated'' suggests a charitable, one-time gift rather than steady provision (wrong_connotation)."}', 'The context calls for a verb meaning to **furnish a resource steadily**, which the precise choice captures and ''gave'' does not.', '''Gave'' is broadly correct and familiar, so students settle for it instead of the verb that names dependable provision exactly.', '1) Pin down the exact shade of meaning the sentence needs (steady furnishing of a resource). 2) Test each verb''s precise connotation. 3) Rule out verbs implying permission, charity, or vague giving. 4) Keep the verb whose meaning matches the context exactly. 5) Re-read to confirm the nuance fits.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-843fad2b5de8bf22', 'act-english', 's-style', 2, 'The alert level can change <u>in a very rapid manner</u> once fresh magma reaches shallow depths beneath the crater floor.', 'Which choice most concisely expresses the idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"rapidly","letter":"B"},{"is_no_change":false,"label":"in a rapid way","letter":"C"},{"is_no_change":false,"label":"at a rapid rate of speed","letter":"D"}]', 'B', '{"A":"Five words stand where a single adverb serves.","B":"Correct: one adverb delivers the full meaning.","C":"Trims a little but keeps the wordy ''in a ___ way'' scaffold.","D":"''Rate of speed'' is internally redundant on top of the wordy frame."}', 'A single **adverb** replaces the entire prepositional scaffold with no loss of meaning.', 'The mid-length option looks trimmed compared with the original, so it feels like the concise pick even though the scaffold remains.', '1) Ask what single word the whole phrase is standing in for. 2) Replace ''in a ___ manner/way'' constructions with the matching adverb. 3) Check the survivors for internal redundancy. 4) Choose the shortest version that keeps the exact meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-89220be51c362df2', 'act-english', 's-style', 2, 'The sidewalk repair fund, approved by voters last November, <u>covers</u> the full cost of replacing broken panels on residential blocks.', 'Which choice is most effective for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"basically covers","letter":"B"},{"is_no_change":false,"label":"covers, for all intents and purposes,","letter":"C"},{"is_no_change":false,"label":"is the thing that covers","letter":"D"}]', 'A', '{"A":"''Covers'' states the fact directly; the sentence needs no qualifier or padding.","B":"''Basically'' is an empty hedge that adds vagueness, not information.","C":"''For all intents and purposes'' is a filler idiom that muddies a straightforward factual claim.","D":"''Is the thing that'' inflates the verb into a wordy frame without adding meaning."}', 'The plain verb already makes the claim; every alternative adds a **filler** word or phrase that contributes nothing.', '''Basically'' feels like it appropriately softens the claim, so the empty hedge passes as careful writing.', '1) Read the sentence with the candidate in place. 2) Delete each added word or phrase and re-read. 3) If the meaning is unchanged, the addition is filler. 4) Keep only words that add information the sentence needs. 5) Confirm the final version states the fact directly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-892f43482b30dbdb', 'act-english', 's-style', 2, 'In its final report, the state commission concluded that the bearings beneath the deck were <u>pretty much shot</u> and recommended immediate replacement.', 'Which choice best maintains the formal register of the surrounding sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"totally done for","letter":"B"},{"is_no_change":false,"label":"severely deteriorated","letter":"C"},{"is_no_change":false,"label":"kind of worn out","letter":"D"}]', 'C', '{"A":"''Pretty much shot'' is slang, jarring inside a commission''s formal findings (misconception: register_slang_kept).","B":"''Totally done for'' trades one piece of slang for another (misconception: register_slang_swap).","C":"Precise, professional wording that matches ''commission,'' ''concluded,'' and ''recommended.''","D":"The hedge ''kind of'' is casual and vague, the opposite of a formal conclusion (misconception: register_casual_hedge)."}', 'A formal report demands **professional, exact diction**, and only this option names the bearings'' condition in that register.', '''Kind of worn out'' avoids obvious slang, so students accept it without noticing the casual hedge that softens a formal finding.', '1) Read the surrounding sentence and label its register (formal, neutral, casual). 2) Flag slang, hedges, and conversational intensifiers in each option. 3) Eliminate every option carrying a flag. 4) Confirm the survivor states the condition precisely. 5) Reread the sentence in the report''s voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9d08e441c6bfbb2b', 'act-english', 's-style', 2, 'In the printed program, the director wrote that the ensemble had <u>totally crushed</u> the show''s most demanding choreography.', 'Which choice is most consistent with the formal style of the director''s note?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"pretty much nailed","letter":"B"},{"is_no_change":false,"label":"been awesome at","letter":"C"},{"is_no_change":false,"label":"mastered","letter":"D"}]', 'D', '{"A":"''Totally crushed'' is conversational slang out of place in a printed program note (register_slang).","B":"''Pretty much'' hedges vaguely and ''nailed'' is casual idiom — doubly informal (register_hedge_plus_slang).","C":"''Been awesome at'' is empty conversational praise that neither fits the register nor names the achievement (register_colloquial_vague).","D":"Correct: the single formal verb suits a printed note and states the accomplishment precisely."}', 'A printed program note demands **formal** register, and only this verb matches that setting while naming the achievement exactly.', '''Pretty much nailed'' tempts students because it feels vivid and confident, masking that both the hedge and the idiom are conversational.', '1) Identify where the sentence will be read and by whom. 2) Set the expected register for that setting. 3) Flag slang, hedges, and empty praise words in each option. 4) Eliminate options that miss the register in either direction. 5) Choose the wording that a careful writer would publish in that document.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ad6ed7fbefe3a475', 'act-english', 's-style', 2, 'The match ended early <u>due to the fact that</u> the servo controlling the lift overheated.', 'Which choice makes the sentence most concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because","letter":"B"},{"is_no_change":false,"label":"in light of the fact that","letter":"C"},{"is_no_change":false,"label":"because of the fact that","letter":"D"}]', 'B', '{"A":"Uses a five-word filler phrase where one word does the same job (filler_fact_that).","B":"Correct: a single conjunction delivers the entire causal meaning.","C":"Swaps one padded formula for an even more formal-sounding one (filler_formal_variant).","D":"Trims halfway but still drags the empty ''of the fact that'' along (filler_partial_trim)."}', 'The one-word conjunction delivers the **entire causal meaning** of the padded five-word phrase.', 'The half-trimmed version feels like a safe compromise since it keeps the familiar opening word.', '1) Spot formula phrases built on ''the fact that.'' 2) Replace the whole phrase with a one-word conjunction. 3) Re-read to confirm no meaning was lost. 4) Reject any option that still contains removable words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b11e70858a9ea936', 'act-english', 's-style', 2, 'The historical society''s handbook, written in careful and courteous prose, encourages members to <u>hang out at</u> the monthly song circle.', 'Which choice best maintains the formal style of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"swing by","letter":"B"},{"is_no_change":false,"label":"drop in on","letter":"C"},{"is_no_change":false,"label":"attend","letter":"D"}]', 'D', '{"A":"''Hang out at'' is casual slang jarring against ''careful and courteous prose.''","B":"''Swing by'' is breezier still, pure conversational idiom.","C":"''Drop in on'' softens the slang but remains a casual idiom, not handbook language.","D":"Correct: a single formal verb matching the handbook''s register."}', 'The sentence itself announces its **formal register**, so the verb must match handbook prose, not hallway talk.', '''Drop in on'' tempts students because it feels politer than the original, but politer slang is still slang.', '1) Find the passage''s own clues about register (''careful and courteous prose''). 2) Label each option: slang, casual idiom, neutral, or formal. 3) Eliminate every label that clashes with the passage''s register. 4) Confirm the survivor preserves the sentence''s meaning. 5) Re-read the sentence in the surrounding voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b227f1f75d46992a', 'act-english', 's-style', 2, 'The mount maker <u>measured the helmet twice</u> before cutting its brass supports.', 'Which choice makes the sentence most effective?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"measured the helmet twice, checking its dimensions two times,","letter":"B"},{"is_no_change":false,"label":"took measurements of the size of the helmet twice","letter":"C"},{"is_no_change":false,"label":"measured and also gauged the helmet twice","letter":"D"}]', 'A', '{"A":"Correct: the original states the action once, cleanly, with no repeated ideas.","B":"''Checking its dimensions two times'' restates ''measured ... twice'' word for word in disguise.","C":"''Took measurements of the size'' buries the verb and repeats the idea of measuring within itself.","D":"''Gauged'' is a synonym for ''measured,'' so pairing them says the same thing twice."}', 'The original expresses the action **once**; every alternative smuggles in a second copy of an idea already stated.', 'Longer options look more thorough, so students equate added words with added information.', '1) Paraphrase the underlined idea in your own words. 2) Scan each option for any word or phrase that re-says part of that paraphrase. 3) Cross out exact-idea repeats (synonym pairs, restated numbers, nested nouns like ''measurements of the size''). 4) Prefer the version where every word adds new information — even if that is the version already on the page.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b8067145180c87a5', 'act-english', 's-style', 2, 'The pallid bats stream out of the cavern to hunt <u>at night after dark</u>, combing the canyon walls for sleeping moths.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"during the nighttime hours of darkness","letter":"B"},{"is_no_change":false,"label":"at night","letter":"C"},{"is_no_change":false,"label":"after dark at night","letter":"D"}]', 'C', '{"A":"''At night'' and ''after dark'' say the same thing, so the pair is redundant (redundant_synonym).","B":"Stacks ''nighttime,'' ''hours,'' and ''darkness,'' which all repeat one idea in an even wordier way (redundant_synonym).","C":"Correct: it states the time once, with no repetition.","D":"Merely reorders the same two synonymous phrases, keeping the redundancy (redundant_synonym)."}', '''At night'' and ''after dark'' name the **same time**, so only one of them is needed.', 'Doubling the time phrase feels like helpful emphasis, so students keep both parts instead of spotting the repetition.', '1) Read the underlined phrase and list the ideas it contains. 2) Ask whether any two words or phrases mean the same thing. 3) If they do, keep only one. 4) Reject options that repeat or merely rearrange the synonyms. 5) Re-read to confirm the meaning survives with no loss.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bab2d25358817f93', 'act-english', 's-style', 2, 'Each January, the cousins <u>collaborate together</u> on a new king cake design before the Carnival season begins.', 'Which choice most effectively expresses the idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"collaborate","letter":"B"},{"is_no_change":false,"label":"collaborate jointly","letter":"C"},{"is_no_change":false,"label":"collaborate with each other as a group","letter":"D"}]', 'B', '{"A":"''Together'' repeats what ''collaborate'' already means — working with others (redundant_together).","B":"Correct — ''collaborate'' alone carries the full meaning of working together.","C":"''Jointly'' restates collaboration''s built-in meaning, just with a fancier word (redundant_synonym).","D":"Piles on two phrases that both repeat the verb''s meaning (redundant_double)."}', '**Collaborate** already means ''work together,'' so any added together-type word is deadweight.', '''Collaborate together'' is so common in everyday speech that the repetition slides past the ear unnoticed.', '1) Define the key word in the span. 2) Check whether any neighboring word repeats part of that definition. 3) Delete the repeaters and reread. 4) Keep only words that add new information.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bc2c9249862df9c5', 'act-english', 's-style', 2, 'Hydration planning matters <u>due to the fact that</u> sweat losses climb steeply during the race''s final hour.', 'Which choice most concisely expresses the idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"owing to the fact that","letter":"B"},{"is_no_change":false,"label":"because of the fact that","letter":"C"},{"is_no_change":false,"label":"because","letter":"D"}]', 'D', '{"A":"''Due to the fact that'' is a five-word scaffold around a simple causal link (padded_connector).","B":"Swaps one padded ''fact that'' construction for another of identical length (synonym_same_padding).","C":"Keeps a working connector but hitches four filler words to it (partial_trim_filler).","D":"Correct: a single plain connector expresses the entire causal relationship."}', 'Concision keeps only what carries meaning, and the whole causal link lives in one plain **connector**.', '''Owing to the fact that'' tempts students because it sounds more formal, and formality is easily mistaken for better writing.', '1) Identify the logical job of the underlined phrase (here: signaling cause). 2) Ask what the fewest words are that still do that job. 3) Treat any ''the fact that'' construction as filler to test. 4) Re-read the sentence with the trimmed version to confirm the meaning is intact. 5) Choose the option with zero idle words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ca729512b2a3c613', 'act-english', 's-style', 2, 'Painted turtles line up on the fallen sycamore <u>in the vicinity of</u> the boathouse dock, basking until the afternoon shade arrives.', 'Which choice states the idea in the clearest, most economical way?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"near","letter":"B"},{"is_no_change":false,"label":"in an area near to","letter":"C"},{"is_no_change":false,"label":"positioned in close proximity to","letter":"D"}]', 'B', '{"A":"A five-word formal detour around a one-word spatial idea (wordy_prepositional_phrase).","B":"Correct: one plain word expresses the entire relationship with no loss of meaning.","C":"Keeps the padding it was meant to remove — ''an area'' and ''to'' are empty scaffolding (residual_padding).","D":"Trades one bloated phrase for a longer one; ''positioned'' and ''proximity'' add formality, not facts (formal_inflation)."}', 'Concision questions reward the **shortest wording that keeps the meaning**, and the one-word preposition does the phrase''s entire job.', '''Positioned in close proximity to'' sounds official and exact, so students mistake its formality for added precision.', '1) State what the underlined phrase does in the sentence. 2) Ask whether an everyday word covers the same ground. 3) Compare each option''s word count against its added meaning — zero added meaning means the extra words fail. 4) Pick the leanest survivor. 5) Re-read to confirm the sentence lost nothing.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ce9aec8c5eb11427', 'act-english', 's-style', 2, '<u>Due to the fact that</u> the game stretched into a twelfth inning, the concession stands ran out of soft pretzels.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In light of the fact that","letter":"B"},{"is_no_change":false,"label":"Owing to the fact that","letter":"C"},{"is_no_change":false,"label":"Because","letter":"D"}]', 'D', '{"A":"''The fact that'' is pure padding — five words doing the work of one (fact_that_padding).","B":"Swaps in an equally bloated formula that adds no meaning (formal_sounding_padding).","C":"Keeps the same ''fact that'' scaffolding under a different opener (fact_that_padding).","D":"Correct: a single subordinating conjunction expresses the entire cause-link."}', 'One **subordinating** word carries the whole cause-link, so every ''the fact that'' formula is dead weight.', 'The longer formulas sound more formal and academic, so students equate extra words with extra polish.', '1) Spot formulas built around ''the fact that.'' 2) Ask what relationship the phrase signals (cause, contrast, time). 3) Swap in the single conjunction that signals the same relationship. 4) Re-read to confirm identical meaning. 5) Keep the shorter version unless meaning changed.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ceeaeb375babef54', 'act-english', 's-style', 2, 'Every family at the solar viewing event received a <u>free complimentary</u> pair of eclipse glasses to take home.', 'Which choice best eliminates redundant language from the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"complimentary free","letter":"B"},{"is_no_change":false,"label":"free","letter":"C"},{"is_no_change":false,"label":"free, no-cost","letter":"D"}]', 'C', '{"A":"Redundant pair: ''free'' and ''complimentary'' mean the same thing, so the phrase says it twice.","B":"Reordering the two synonyms leaves the doubled meaning fully intact.","C":"Correct: one word carries the entire meaning with nothing repeated.","D":"Swapping in ''no-cost'' just replaces one twin with another; the duplication remains."}', 'When two modifiers are **synonyms**, keep exactly one—the meaning survives untouched.', 'The original tempts students because doubling adjectives feels emphatic rather than repetitive.', '1) Define each modifier in the underlined phrase separately. 2) If two definitions overlap completely, mark the pair redundant. 3) Delete until each remaining word adds distinct meaning. 4) Re-read the sentence to confirm nothing was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d147d0a59cf96d64', 'act-english', 's-style', 2, 'When a child dropped an eyepiece into the gravel, a volunteer <u>calmly retrieved and cleaned it</u> before the line had even moved.', 'Which choice expresses the idea most clearly and concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"proceeded in a calm manner to retrieve and clean it","letter":"B"},{"is_no_change":false,"label":"was calm in the retrieving and cleaning of it","letter":"C"},{"is_no_change":false,"label":"engaged in calmly retrieving it and cleaning it as well","letter":"D"}]', 'A', '{"A":"Correct: direct verbs and a single adverb deliver the full idea with no wasted words.","B":"''Proceeded in a calm manner to'' buries the action under filler that adds no meaning.","C":"Nominalization: turning the verbs into ''the retrieving and cleaning of'' swells and flattens the sentence.","D":"''Engaged in'' and ''as well'' are padding that add syllables, not sense."}', 'The tightest version keeps the **actions as verbs** and trusts one adverb to do the describing.', '''Proceeded in a calm manner'' tempts students because longer, formal-sounding phrasing feels more sophisticated.', '1) Circle the core actions. 2) Flag filler frames: ''proceeded to,'' ''engaged in,'' ''in a ___ manner,'' ''the ___ing of.'' 3) Delete each flagged phrase and re-read—if meaning survives, the phrase was padding. 4) Keep the version where every word earns its place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d1c341cb59496881', 'act-english', 's-style', 2, 'To keep the dye bath at a steady temperature, Elena <u>looked at</u> the thermometer every few minutes.', 'Which choice most precisely conveys Elena''s deliberate, repeated checking?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"glanced toward","letter":"B"},{"is_no_change":false,"label":"witnessed","letter":"C"},{"is_no_change":false,"label":"monitored","letter":"D"}]', 'D', '{"A":"''Looked at'' is serviceable but vague; it misses the purposeful, ongoing attention described.","B":"''Glanced toward'' suggests a casual flick of the eyes, weaker than the careful checking intended.","C":"''Witnessed'' describes observing an event happen, not tracking an instrument over time.","D":"Correct: the verb means to watch something systematically over time, matching the steady-temperature purpose."}', '**Precision**: the right verb encodes systematic, purposeful watching — exactly what tending a dye bath requires.', '''Looked at'' tempts because it is not wrong, merely weak; precision items reward the exact verb over the adequate one.', '1) Identify what the sentence needs the word to convey (manner, purpose, duration). 2) Define each option in a phrase. 3) Eliminate words whose definitions add wrong shades or drop needed ones. 4) Pick the definition that matches the context exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d896c378ca8e72e1', 'act-english', 's-style', 2, 'In her artist''s statement for the fiber-arts fellowship, Maya wrote that hand-spinning her own yarn <u>lets her mess around with</u> texture in ways commercial thread cannot.', 'Which choice is most appropriate for the formal context of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gives her a shot at playing with","letter":"B"},{"is_no_change":false,"label":"allows her to experiment with","letter":"C"},{"is_no_change":false,"label":"furnishes her the wherewithal to manipulate","letter":"D"}]', 'C', '{"A":"''Mess around with'' is casual slang, out of place in a formal fellowship statement.","B":"''A shot at playing with'' swaps one colloquialism for two.","C":"Correct: plain, professional wording suited to an application read by a review committee.","D":"''Furnishes her the wherewithal'' is stiff, antique phrasing that overcorrects into pomposity."}', '**Register** must fit audience and occasion: a fellowship statement calls for straightforward professional diction.', 'The ornate version tempts students who equate formal writing with fancy words, but overdressed prose misses the register just as slang does.', '1) Name the document and its audience. 2) Decide the register they expect. 3) Sort each option: too casual, too stiff, or fitting. 4) Choose the phrasing the audience would not notice — appropriate register is invisible.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e7376e7f0777e712', 'act-english', 's-style', 2, 'The astronomer opened every session with the same blunt safety reminder: she <u>implied</u> that no one should ever aim binoculars at the Sun, even during an eclipse.', 'Which choice conveys the astronomer''s action most precisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"inferred","letter":"B"},{"is_no_change":false,"label":"hinted","letter":"C"},{"is_no_change":false,"label":"warned","letter":"D"}]', 'D', '{"A":"''Implied'' means suggested indirectly, which contradicts the sentence''s own word ''blunt.''","B":"''Inferred'' reverses direction: listeners infer conclusions; speakers state them.","C":"''Hinted'' is even more indirect than ''implied,'' the opposite of a blunt reminder.","D":"Correct: it matches a direct, urgent safety statement delivered bluntly."}', 'Precision means matching the verb to the sentence''s own cue: a **blunt** reminder is delivered directly and urgently.', '''Implied'' tempts students because it is a common formal verb of communication, and the implied/inferred pair blurs in memory.', '1) Find the sentence''s cue words about manner (''blunt,'' ''safety reminder''). 2) Place each verb on the directness scale, from faint suggestion to outright alarm. 3) Check direction: is the subject sending the message or receiving it? 4) Choose the verb whose directness and direction both match the cues.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e916ba6cb6cabe27', 'act-english', 's-style', 2, '<u>Due to the fact that</u> fluorescent tubes emit ultraviolet radiation, the archive switched its reading room to LED lamps.', 'Which choice most effectively tightens the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Because of the fact that","letter":"B"},{"is_no_change":false,"label":"In light of the fact that","letter":"C"},{"is_no_change":false,"label":"Because","letter":"D"}]', 'D', '{"A":"''Due to the fact that'' spends five words doing a one-word job.","B":"This swaps one bloated formula for another; ''of the fact that'' adds no meaning.","C":"Another padded variant — and ''in light of'' is an awkward pun beside a sentence about lamps.","D":"Correct: a single subordinating conjunction expresses the entire causal link."}', 'Wordy scaffolds like ''the fact that'' collapse into a single **subordinating conjunction** with no loss of meaning.', 'Multi-word openers sound weighty and academic, so students trust them over the plain one-word connector.', '1) Circle any phrase built around ''the fact that.'' 2) Ask what relationship it signals (cause, contrast, time). 3) Replace the whole phrase with the single word that signals the same relationship. 4) Reread to confirm the meaning is unchanged — if it is, the shorter version wins.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ea1f4341b173861c', 'act-english', 's-style', 2, 'Because silk fibers are exceptionally strong, weavers <u>use them</u> for warp threads that must withstand constant tension.', 'Which choice makes the sentence most effective?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"make use of them","letter":"B"},{"is_no_change":false,"label":"put them to use in their work","letter":"C"},{"is_no_change":false,"label":"have a tendency to select them","letter":"D"}]', 'A', '{"A":"Correct: the plain verb states the action directly with no wasted words.","B":"''Make use of'' stretches one verb into three words without adding meaning.","C":"''In their work'' adds an empty phrase on top of an inflated verb.","D":"''Have a tendency to'' hedges a fact and buries the action in filler."}', 'The **direct verb** already says everything; every alternative pads it without adding meaning.', '''Make use of them'' tempts because the extra words sound more formal, but formality gained by padding is wordiness.', '1) Identify the core action. 2) Ask of each option: what does each extra word add? 3) If the answer is nothing, the shorter phrasing wins. 4) Confirm the short version keeps the full meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f3102a85b386c4c6', 'act-english', 's-style', 2, '<u>It is important to note that when</u> the temperature drops below fifty degrees, foragers stop leaving the hive.', 'Which choice best removes the empty phrasing from the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"For all intents and purposes, when","letter":"B"},{"is_no_change":false,"label":"When","letter":"C"},{"is_no_change":false,"label":"It should be understood that when","letter":"D"}]', 'C', '{"A":"''It is important to note that'' is a filler opener that adds no information before the real clause.","B":"''For all intents and purposes'' is an empty stock phrase that pads the sentence with no added meaning.","C":"Correct: cutting straight to ''When'' removes the filler and lets the real idea begin at once.","D":"''It should be understood that'' is the same kind of empty announcer, swapping one filler for another."}', 'Empty announcer phrases can simply be **deleted**, so the sentence should open directly with the real clause.', 'The ''it is important to note that'' opener sounds thoughtful and academic, so students keep it as if it signaled significance.', '1) Check whether the opening words announce that something matters rather than saying anything. 2) Test whether deleting them changes the meaning; if not, they are filler. 3) Cut the filler and start with the substantive clause. 4) Reject any option that trades one empty announcer for another.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f3ca9ba2974fbba4', 'act-english', 's-style', 2, 'Over one winter, the Gazette''s archivist <u>invented</u> a catalog of every photograph the paper had published since 1946.', 'Which choice most precisely describes the archivist''s work?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"compiled","letter":"B"},{"is_no_change":false,"label":"concocted","letter":"C"},{"is_no_change":false,"label":"imagined","letter":"D"}]', 'B', '{"A":"''Invented'' means created from nothing, but the photographs already existed and only needed organizing.","B":"Correct: it means gathered and arranged existing items — exactly the archivist''s task.","C":"''Concocted'' implies improvised mixtures or schemes, with a shady connotation wrong for archival work.","D":"''Imagined'' would mean the catalog exists only in her head, not on paper."}', 'The archivist **gathered and organized existing photographs**, and only this verb means precisely that.', '''Invented'' tempts students because inventing and creating feel interchangeable when something new is produced.', '1) Pin down what literally happened (existing photos were organized into a list). 2) Define each verb candidate precisely. 3) Reject verbs implying creation from nothing, deception, or unreality. 4) Choose the verb whose core meaning matches the literal event. 5) Re-read for fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f8f8f5d4b1fe34fa', 'act-english', 's-style', 2, 'The crab, <u>due to the fact that</u> it sensed a shadow overhead, darted into a narrow crevice.', 'Which choice is most concise while keeping the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because","letter":"B"},{"is_no_change":false,"label":"owing to the fact that","letter":"C"},{"is_no_change":false,"label":"in light of the fact that","letter":"D"}]', 'B', '{"A":"The underlined phrase is a wordy way of signaling a cause (wordiness).","B":"Correct: a single conjunction conveys the same cause with no padding.","C":"This is another inflated substitute for a one-word cause.","D":"This is equally padded and no clearer."}', 'The shortest phrase that preserves the causal meaning is best; **one word** replaces the four-word phrase.', 'The longer phrase sounds formal, so students equate its length with correctness.', '1) Spot multi-word phrases that signal cause. 2) Ask whether a single conjunction says the same thing. 3) Replace padded phrases with the concise word. 4) Confirm the meaning is unchanged.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fa86d88d550bb03c', 'act-english', 's-style', 2, 'The referral agency <u>screens</u> every freelance interpreter before adding a name to its on-call roster.', 'Which choice expresses the idea most concisely while preserving the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"conducts a screening of","letter":"B"},{"is_no_change":false,"label":"engages in the process of screening","letter":"C"},{"is_no_change":false,"label":"makes it a point to screen","letter":"D"}]', 'A', '{"A":"Correct — ''screens'' delivers the full meaning in one word.","B":"''Conducts a screening of'' swaps a crisp verb for a noun-heavy phrase with no added meaning.","C":"''Engages in the process of'' is pure filler wrapped around the same action.","D":"''Makes it a point to'' adds words about intention without changing what happens."}', 'The single verb already says everything; every alternative pads it with **empty** words.', '''Conducts a screening of'' sounds official, and students often equate formality with correctness.', '1) Find the core action of the underlined portion. 2) For each option, cross out words that add no new information. 3) Whatever survives should match the core action. 4) Keep the version with zero crossed-out words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fb5c64a37c803482', 'act-english', 's-style', 2, 'The county fair judges <u>rated</u> the orchard''s late-season cider best in its class.', 'Which choice is the most concise way to express the idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gave a rating to","letter":"B"},{"is_no_change":false,"label":"made the decision to rate","letter":"C"},{"is_no_change":false,"label":"rated and evaluated","letter":"D"}]', 'A', '{"A":"Correct: the single verb ''rated'' says everything the longer options say.","B":"''Gave a rating to'' swaps a strong verb for a weak verb plus a noun.","C":"''Made the decision to rate'' buries the action under an empty decision phrase.","D":"''Rated and evaluated'' doubles the verb with a synonym, adding words but no meaning."}', 'Prefer the **shortest** option that preserves the full meaning.', '''Rated and evaluated'' sounds thorough and official, so the synonym pair masquerades as added precision.', '1) Identify the core action. 2) Ask of each option: does it add meaning or only length? 3) Cut verb-plus-noun bundles and synonym pairs. 4) Keep the shortest version that changes nothing about the meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fc74c10c8aca700b', 'act-english', 's-style', 2, '<u>Due to the fact that</u> the press broke down on Wednesday, the weekend edition shipped a day late.', 'Which choice most effectively eliminates wordiness?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In light of the fact that","letter":"B"},{"is_no_change":false,"label":"Because","letter":"C"},{"is_no_change":false,"label":"Being that","letter":"D"}]', 'C', '{"A":"Five words doing one word''s job — bureaucratic padding around a simple cause.","B":"Swaps one padded ''the fact that'' formula for an equally padded one.","C":"Correct: a single standard conjunction carries the full causal meaning.","D":"A colloquialism that standard written English rejects as a cause connector."}', 'One standard **conjunction** expresses the entire causal link that the five-word formula labors to state.', 'The original tempts students because official-sounding phrases feel more formal and therefore more correct.', '1) Ask what logical job the underlined phrase performs (here: cause). 2) List the shortest standard word for that job. 3) Compare candidates: same meaning, fewer words wins. 4) Reject phrases containing ''the fact that.'' 5) Re-read with the lean version to confirm nothing changed but length.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0104d697f908031f', 'act-english', 's-style', 3, 'Each morning, she would <u>rise up</u> at dawn to water the garden.', 'Which choice removes the redundant word?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"get up to rise","letter":"B"},{"is_no_change":false,"label":"rise upward","letter":"C"},{"is_no_change":false,"label":"rise","letter":"D"}]', 'D', '{"A":"''Rise'' already means to move up — ''up'' repeats it.","B":"''Get up to rise'' says the same thing twice in two ways.","C":"''Upward'' is the same redundancy in a longer word.","D":"''Rise'' alone carries the full meaning."}', 'The direction is **inside the verb**: rising is upward by definition.', '''Rise up'' is common in speech and song, so it sounds idiomatic.', 'Drop particles that repeat the verb''s built-in direction (rise up, descend down, return back).', 'underlined-span-mc', '''Rise up'' is common in speech and song, so it sounds idiomatic', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-04577d127b765666', 'act-english', 's-style', 3, 'A cutback week <u>lets</u> tired legs absorb the previous month of hard training.', 'Which choice best avoids empty or filler language?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"basically serves the function of letting","letter":"B"},{"is_no_change":false,"label":"is the kind of thing that lets","letter":"C"},{"is_no_change":false,"label":"works, in a sense, to let","letter":"D"}]', 'A', '{"A":"Correct: the single direct verb states the action with no padding.","B":"''Basically'' hedges and ''serves the function of'' restates the verb in bureaucratic packaging (filler_function_phrase).","C":"''Is the kind of thing that'' converts a direct action into a vague classification (filler_classifier).","D":"''In a sense'' hedges a claim the writer fully means, diluting a direct verb (filler_hedge)."}', 'The plain verb already says everything, so any added phrase is **filler** by definition.', '''Serves the function of letting'' tempts students because longer, official-sounding phrasing can feel more academic than a bare verb.', '1) Read the shortest version and note the core action. 2) For each longer option, underline the added words. 3) Ask of each addition: does it change the meaning or only the length? 4) Strike hedges and classifiers that soften nothing. 5) Keep the version in which every word carries content.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-06144da3cecffe30', 'act-english', 's-style', 3, 'The trio booked studio time after midnight <u>due to the fact that</u> the engineer charged half price once the day''s paying sessions had ended.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"owing to the fact that","letter":"B"},{"is_no_change":false,"label":"because","letter":"C"},{"is_no_change":false,"label":"because of the fact that","letter":"D"}]', 'C', '{"A":"''Due to the fact that'' spends five words doing a one-word job.","B":"''Owing to the fact that'' swaps the opener but keeps the same bloated construction.","C":"Correct: a single conjunction expresses the causal link completely.","D":"''Because of the fact that'' buries the right word inside four unnecessary ones."}', 'One **conjunction** expresses the entire causal relationship, so the five-word scaffolding is dead weight.', 'The longer phrases tempt students because they sound weighty and formal, and formality is easily mistaken for correctness.', '1) Spot the phrase ''the fact that'' — it is almost always removable. 2) Ask what relationship the phrase expresses (here: cause). 3) Try the shortest word that names that relationship. 4) If the sentence still says the same thing, the shorter version wins.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0a7267ca1e6232f1', 'act-english', 's-style', 3, 'According to the refuge''s annual report, volunteer participation <u>shot up like crazy</u> after the new boardwalk opened.', 'Which choice is most consistent with the formal style of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"rose sharply","letter":"B"},{"is_no_change":false,"label":"skyrocketed to the max","letter":"C"},{"is_no_change":false,"label":"went through the roof","letter":"D"}]', 'B', '{"A":"''Shot up like crazy'' is casual slang inside a sentence citing an official report.","B":"Correct: plain, precise wording matched to the report''s formal register.","C":"''To the max'' is even more slangy than the original phrase.","D":"''Went through the roof'' is an informal idiom that clashes with the documentary tone."}', 'A sentence attributing data to an official report needs **measured, formal** wording, not slang or idiom.', 'The colloquial idioms are vivid and familiar, so students mistake their energy for effective style.', '1) Identify the sentence''s register from its cues (here, a citation of an annual report). 2) Label each option: slang, idiom, neutral, or formal. 3) Eliminate anything the source document itself would never print. 4) Choose the option matching the established register.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1072dd878a469af1', 'act-english', 's-style', 3, '<u>As far as what it demanded of players is concerned, bebop</u> required blistering technique and split-second harmonic thinking.', 'Which choice best avoids unnecessary wording?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In terms of its demands on players, bebop","letter":"B"},{"is_no_change":false,"label":"When you consider the question of its demands, bebop","letter":"C"},{"is_no_change":false,"label":"Bebop","letter":"D"}]', 'D', '{"A":"filler_throat_clearing: the *as far as … is concerned* frame delays the sentence without adding content.","B":"*In terms of* is a shorter throat-clearer, but the predicate states the demands anyway, making the frame redundant.","C":"*When you consider the question of* adds a second-person aside and an empty ''question of.''","D":"Correct: the sentence''s own predicate states the demands, so no preamble is needed."}', 'The predicate already **states** the demands, so any lead-in frame repeats work the sentence does itself.', '*In terms of* is short and common in academic-sounding prose, so it seems harmless.', '1) Bracket any lead-in that comes before the subject. 2) Read the sentence without it. 3) If nothing is lost, the lead-in is filler — cut it. 4) Keep only openers that add real information, such as time, place, or contrast.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-159376b73575aabe', 'act-english', 's-style', 3, 'Emergency managers urge coastal residents to make <u>advance preparations ahead of time</u> whenever a tropical system organizes offshore.', 'Which choice makes the sentence most concise without losing information?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"preparations","letter":"B"},{"is_no_change":false,"label":"advance preparations beforehand","letter":"C"},{"is_no_change":false,"label":"preparations in advance ahead of the storm","letter":"D"}]', 'B', '{"A":"''Advance'' and ''ahead of time'' say the same thing twice (misconception: reinforcing a point strengthens it).","B":"Correct: the noun already implies action taken before the event, so no time-stamp is needed.","C":"''Beforehand'' merely swaps one duplicate for another (misconception: changing the redundant word cures the redundancy).","D":"''In advance'' plus ''ahead of the storm'' doubles the time idea yet again (misconception: extra phrasing adds precision)."}', 'The bare noun already contains the **before-the-event** idea, so every added time phrase is redundant.', '''Advance preparations beforehand'' rearranges the words enough to feel edited while keeping the doubled meaning.', '1) Define the head word (preparing = getting ready before something happens). 2) Check each modifier: does it add new information or repeat the definition? 3) Delete the repeaters. 4) Prefer the shortest version that keeps the full meaning. 5) Re-read for anything lost — if nothing, the cut stands.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-15d657b571e492e2', 'act-english', 's-style', 3, 'In his 1901 reports to investors, Marconi maintained that transatlantic signaling <u>was going to be a pretty big deal</u> for shipping companies.', 'Which choice best maintains the formal register of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"would prove commercially valuable","letter":"B"},{"is_no_change":false,"label":"was bound to be huge","letter":"C"},{"is_no_change":false,"label":"would represent a majorly significant development","letter":"D"}]', 'B', '{"A":"''A pretty big deal'' is a casual idiom badly out of place in formal reports to investors.","B":"Correct: measured, businesslike diction that fits the investor-report frame.","C":"''Bound to be huge'' stays at conversational pitch, trading one casual idiom for another.","D":"''Majorly'' is a colloquial intensifier that contaminates an otherwise formal phrase — a register mix."}', 'Register must match the frame: **formal business context** demands measured diction with no colloquial intruders.', 'The ''majorly significant development'' option sounds elevated at a glance, so students miss the single slang intensifier buried inside it.', '1) Identify the sentence''s frame and its formality level (''reports to investors'' = formal). 2) Test each option word by word against that level. 3) Reject any option containing even one colloquial word, however formal its wrapper. 4) Reject options that are entirely casual. 5) Keep the option whose every word fits the frame.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-17fdb4a4ee295f8d', 'act-english', 's-style', 3, 'Students <u>who are members of</u> the robotics club meet on Tuesdays.', 'Which choice is most concise while preserving the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"in","letter":"B"},{"is_no_change":false,"label":"who happen to belong to","letter":"C"},{"is_no_change":false,"label":"that are being members of","letter":"D"}]', 'B', '{"A":"''Who are members of'' is grammatical but spends four words on what one preposition can do.","B":"''Students in the robotics club'' — same meaning, three words saved.","C":"''Happen to belong to'' adds hedging the sentence never asked for.","D":"''That are being members of'' is both wordier and ungrammatical."}', 'The ACT rewards the **shortest choice that keeps the meaning** — here, ''in''.', 'The longer relative clause sounds more formal and ''complete''.', 'Try replacing a relative clause with a single preposition; if nothing is lost, the preposition wins.', 'underlined-span-mc', 'the longer relative clause sounds more formal and ''complete''', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1a09c7cb7471f71e', 'act-english', 's-style', 3, 'The sommelier swirled the glass and, <u>in a manner that was quite deliberate and unhurried, she</u> inhaled before naming three distinct notes.', 'Which choice is the most concise while keeping the sentence clear and complete?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"unhurried, she","letter":"B"},{"is_no_change":false,"label":"in a way that took her time and was not rushed, she","letter":"C"},{"is_no_change":false,"label":"she, unhurried and taking her time and slow,","letter":"D"}]', 'B', '{"A":"Padded: ''in a manner that was quite deliberate and unhurried'' stacks synonyms to say one thing.","B":"Correct: a single adjective, ''unhurried,'' delivers the whole idea and keeps the sentence grammatical.","C":"Still wordy: it just paraphrases the padding into another long relative clause.","D":"Redundant and clumsy: ''unhurried,'' ''taking her time,'' and ''slow'' triple the same idea and jumble the syntax."}', 'One precise adjective, **''unhurried,''** carries the full meaning, so the shortest grammatical version wins.', 'The long original sounds elegant and descriptive, so its repetition reads like richness rather than padding.', '1) Identify the core idea the phrase conveys. 2) Ask what single word or short phrase expresses it. 3) Cut synonyms that repeat that idea. 4) Confirm the trimmed version stays grammatical and complete. 5) Choose the shortest option that preserves meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1b62b895b471e38a', 'act-english', 's-style', 3, 'In its annual report to the council, the planning commission <u>conceded</u> that the permit backlog had grown despite the addition of two reviewers.', 'Which choice best maintains the formal tone of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"let on","letter":"B"},{"is_no_change":false,"label":"fessed up","letter":"C"},{"is_no_change":false,"label":"was straight with everybody","letter":"D"}]', 'A', '{"A":"The original verb matches the formal register of an official report while conveying a reluctant admission.","B":"''Let on'' is conversational and also implies revealing a secret rather than formally admitting a shortfall.","C":"''Fessed up'' is slang, far below the register of a report addressed to a council.","D":"''Was straight with everybody'' is a breezy colloquialism that trades precision for chattiness."}', 'The original verb keeps the sentence''s **formal, official register** while preserving the sense of an admission.', '''Fessed up'' vividly captures admitting fault, so its casual register slips past students focused only on meaning.', '1) Identify the passage''s register from its setting and diction — here, an official report. 2) Rate each option on a scale: slang, conversational, neutral, formal. 3) Eliminate options below (or absurdly above) the passage''s register. 4) Among survivors, check that the meaning fits the context. 5) Re-read the sentence in the passage''s voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2253fdbaf268b3b7', 'act-english', 's-style', 3, 'On warm afternoons, meltwater <u>goes</u> down through the porous upper layers of the snowpack.', 'Which choice most precisely describes the movement of the meltwater?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"moves","letter":"B"},{"is_no_change":false,"label":"travels","letter":"C"},{"is_no_change":false,"label":"percolates","letter":"D"}]', 'D', '{"A":"''Goes'' is the vaguest possible motion verb and specifies nothing about how the water descends (maximum vagueness).","B":"''Moves'' is scarcely more specific than ''goes'' (generic swap).","C":"''Travels'' suggests distance covered but not the manner of passing through pores (near-precise but wrong emphasis).","D":"This verb names precisely the slow filtering of liquid down through a porous material."}', 'Precision means naming the **specific manner** of motion — a slow filtering through tiny pores — not motion in general.', '''Travels'' sounds more writerly than ''goes,'' so students upgrade the vagueness slightly instead of choosing the exact term.', '1) Ask what the sentence''s own details demand (porous layers → passage through pores). 2) For each verb, state exactly what picture it draws. 3) Eliminate verbs that could describe almost any motion. 4) Choose the verb whose picture matches the sentence''s details.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-226502e5e889a8f2', 'act-english', 's-style', 3, 'Under blue light, some corals blaze in neon greens and reds, a glow created by special proteins that <u>give off</u> light at a color different from the light they absorb.', 'Which choice most precisely conveys the intended meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"emit","letter":"B"},{"is_no_change":false,"label":"release","letter":"C"},{"is_no_change":false,"label":"reflect","letter":"D"}]', 'B', '{"A":"''Give off'' is loose and informal for a precise optical process (misconception: vague_phrasal_verb).","B":"''Emit'' precisely names the act of sending out light.","C":"''Release'' suggests letting go of a stored substance, not producing light (misconception: imprecise_near_synonym).","D":"''Reflect'' means bouncing back existing light, which misstates how fluorescence works (misconception: wrong_technical_meaning)."}', 'The **exact** term for giving out light fits the scientific context.', '''Give off'' is common and roughly right, so it slips by when a sharper term is available.', '1) Name the precise action the sentence describes. 2) For each option, ask whether it means exactly that or only approximately. 3) Rule out words that imply a different process. 4) Keep the word whose technical meaning fits perfectly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2439a63f27063eb2', 'act-english', 's-style', 3, 'Next spring, the transit authority will <u>combine</u> the two overlapping bus routes into a single crosstown line.', 'Which choice makes the sentence most concise while preserving its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"combine together","letter":"B"},{"is_no_change":false,"label":"combine and merge","letter":"C"},{"is_no_change":false,"label":"combine, uniting them as one,","letter":"D"}]', 'A', '{"A":"''Combine'' alone carries the full meaning, and ''into a single crosstown line'' already states the result.","B":"''Together'' is built into the meaning of ''combine'' — a redundant particle adding no information.","C":"''Merge'' repeats ''combine''; pairing synonyms adds words, not meaning — the redundant-synonym trap.","D":"''Uniting them as one'' restates both the verb and ''into a single line,'' doubling the redundancy."}', 'The verb already contains the idea of joining, and **''into a single crosstown line''** states the result — nothing needs repeating.', '''Combine and merge'' feels thorough, as though two verbs make the action more complete.', '1) Ask what the underlined verb already means. 2) Scan the rest of the sentence for words that repeat that meaning. 3) Strike any word or phrase whose idea is already present elsewhere. 4) Prefer the version that expresses each idea exactly once. 5) Re-read to confirm no meaning was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2db60badb0fde815', 'act-english', 's-style', 3, 'Analysts agreed that, after five hours of precise defense, the defending champion <u>totally botched</u> a drawn endgame in one careless moment.', 'Which choice best maintains the formal style of the essay?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"mishandled","letter":"B"},{"is_no_change":false,"label":"goofed up","letter":"C"},{"is_no_change":false,"label":"made a total hash of","letter":"D"}]', 'B', '{"A":"The casual intensifier ''totally'' and the slangy verb clash with the sentence''s analytic voice.","B":"A single restrained verb reports the error in the same formal register as ''analysts agreed'' and ''precise defense.''","C":"''goofed up'' is schoolyard slang, even further from the essay''s register.","D":"The kitchen idiom is breezy and conversational, mismatched with a measured match report."}', 'The formal context calls for **restrained diction**, and this verb reports the error without slang or idiom.', 'Keeping the original tempts because ''totally botched'' is vivid and clear, so its casual register slips past the ear.', '1) Identify the passage''s register from its surrounding vocabulary. 2) Label each option: slang, idiom, casual intensifier, or formal diction. 3) Eliminate every option below the passage''s register. 4) Reread the sentence with the survivor to confirm the voice stays even.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-33703c28c120dc77', 'act-english', 's-style', 3, 'The festival''s keynote speaker <u>made reference to the fact that</u> shorebird numbers have fallen sharply since the 1980s.', 'Which choice results in the clearest, most effective sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"noted that","letter":"B"},{"is_no_change":false,"label":"made a notation of the fact that","letter":"C"},{"is_no_change":false,"label":"referenced the fact of how","letter":"D"}]', 'B', '{"A":"''Made reference to the fact that'' buries one verb''s worth of meaning under five extra words.","B":"Correct: one precise reporting verb does the entire job.","C":"Even wordier, piling a noun phrase on top of the same padding.","D":"Keeps the empty ''the fact'' padding and adds the unidiomatic ''of how.''"}', '**Concision** wins: a single direct verb replaces the five-word scaffold without losing any meaning.', 'The longer constructions sound official and speech-like, so students equate their bulk with formality.', '1) Ask what action the phrase performs. 2) Try to say it in one verb. 3) If the one-verb version keeps the full meaning, the extra words are padding. 4) Watch especially for ''made ___ to'' and ''the fact that'' constructions — they usually hide a strong verb.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-338edbfd00343a2e', 'act-english', 's-style', 3, 'Each vendor must <u>submit an annual application</u> to keep a reserved booth at the market.', 'Which choice avoids redundancy while preserving the sentence''s meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"submit an annual application every year","letter":"B"},{"is_no_change":false,"label":"submit an annual yearly application","letter":"C"},{"is_no_change":false,"label":"annually submit an annual application","letter":"D"}]', 'A', '{"A":"Correct — ''annual'' already carries the once-a-year meaning, so nothing repeats.","B":"''Every year'' restates what ''annual'' already says (redundant_time_phrase).","C":"''Yearly'' is a direct synonym of ''annual,'' stacked beside it (redundant_synonym).","D":"''Annually'' repeats the same idea in adverb form (redundant_adverb)."}', 'The adjective **annual** already states the once-a-year timing, so any added time expression repeats it.', 'Adding ''every year'' feels like helpful clarification rather than repetition, since the phrase is so common in speech.', '1) Underline every word or phrase that expresses timing. 2) Ask what each one adds that the others don''t. 3) If two expressions encode the same fact, cut until one remains. 4) Reread to confirm the meaning survived. 5) Prefer the version stating each idea exactly once.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-36cb403fca6b9925', 'act-english', 's-style', 3, 'A single follow spot <u>looked at</u> the soloist as she wove between the darkened set pieces.', 'Which choice most precisely describes the action of the follow spot?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"witnessed","letter":"B"},{"is_no_change":false,"label":"tracked","letter":"C"},{"is_no_change":false,"label":"stared down","letter":"D"}]', 'C', '{"A":"''Looked at'' vaguely personifies the fixture and misses the continuous following of a moving performer (imprecise_vague_verb).","B":"''Witnessed'' carries courtroom-observer connotations and suggests passive watching, not active following (imprecise_connotation).","C":"Correct: the verb precisely captures a light continuously following a performer in motion.","D":"''Stared down'' injects hostility into a neutral technical action (imprecise_hostile_connotation)."}', 'Precision means matching the verb to the **action** — a light continuously following a moving performer — and only this verb conveys that motion.', '''Witnessed'' tempts students because it sounds elevated and formal, though its bystander connotation contradicts the light''s active role.', '1) Picture the literal action the sentence describes. 2) For each verb, name its core image and its connotation. 3) Eliminate verbs whose image misses the motion or mechanism. 4) Eliminate verbs whose connotation adds attitude the scene lacks. 5) Choose the verb that matches both the action and the mood.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3d6b6d45ecb6d445', 'act-english', 's-style', 3, 'With its wings folded tight, the falcon <u>fell</u> toward the flock of starlings, reaching nearly two hundred miles an hour.', 'Which choice provides the most precise word in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"descended","letter":"B"},{"is_no_change":false,"label":"tumbled","letter":"C"},{"is_no_change":false,"label":"dove","letter":"D"}]', 'D', '{"A":"''Fell'' implies gravity acting on a passive object, not a hunter''s deliberate attack.","B":"''Descended'' is accurate but bland, suggesting a gentle, gradual drop rather than a strike.","C":"''Tumbled'' means falling out of control — the opposite of a falcon''s precision.","D":"Correct: it names the swift, purposeful plunge of a hunting bird."}', 'Precision demands a verb of **deliberate, high-speed attack**, matching the folded wings and the two-hundred-mile-an-hour figure.', '''Descended'' feels safe because it is formal and technically true, but it drains the speed and intent from the action.', '1) List what the context tells you: speed, posture, purpose. 2) For each verb, ask whether it matches all three. 3) Cut verbs that add wrong ideas (accident, chaos, slowness). 4) Choose the verb whose core image fits the scene exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-42559db77d383418', 'act-english', 's-style', 3, 'Agencies <u>generally</u> assign interpreters in pairs for any event scheduled to run longer than an hour.', 'Which choice best expresses the idea clearly and without unnecessary words?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"in most cases, generally","letter":"B"},{"is_no_change":false,"label":"as a general rule of thumb,","letter":"C"},{"is_no_change":false,"label":"for all intents and purposes,","letter":"D"}]', 'A', '{"A":"Correct — ''generally'' states the qualification in a single precise word.","B":"''In most cases, generally'' says the same thing twice.","C":"''As a general rule of thumb'' swells one word into a five-word cliché with no gain.","D":"''For all intents and purposes'' is filler that means ''effectively,'' not ''usually,'' so it also distorts the meaning."}', 'One well-chosen adverb does the work; the alternatives add **filler** or blur the meaning.', 'The rule-of-thumb phrase sounds folksy and authoritative, so its bulk feels like substance.', '1) Identify the qualification the sentence needs (how often? how sure?). 2) Ask whether each option states that qualification once, twice, or not at all. 3) Strike doubled or off-target qualifiers. 4) Keep the version that qualifies the claim exactly once, in the fewest words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-467340b176d6367d', 'act-english', 's-style', 3, 'The director explained that the new catalog system <u>has the ability to give patrons the option of being able to renew</u> loans from their phones.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"gives patrons the ability to have the option to renew","letter":"B"},{"is_no_change":false,"label":"lets patrons renew","letter":"C"},{"is_no_change":false,"label":"is capable of offering patrons the opportunity to renew","letter":"D"}]', 'C', '{"A":"Buries one simple action under four stacked filler constructions.","B":"Reshuffles the same padding — ''ability'' and ''option'' still duplicate one idea.","C":"Correct: a single direct verb delivers the full meaning with no filler.","D":"Swaps in equally bloated phrasing dressed up in formal-sounding words."}', '**Wordiness** is the error: one direct verb expresses the entire idea that the padded versions bury.', 'The ''is capable of offering … the opportunity'' version sounds official and polished, so students mistake formality for quality.', '1) Find the buried action — here, renewing. 2) Ask who does it. 3) Rewrite as actor + strong verb + action. 4) Delete scaffolding like ''has the ability to'' and ''the option of.'' 5) Keep the shortest version that preserves the full meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-473761e950feceac', 'act-english', 's-style', 3, 'The detective grew <u>curious</u> when the same gray sedan appeared outside the shop for the third day.', 'Which word best conveys the wary interest the situation calls for?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"interested","letter":"B"},{"is_no_change":false,"label":"nosy","letter":"C"},{"is_no_change":false,"label":"suspicious","letter":"D"}]', 'D', '{"A":"''Curious'' is mild interest, missing the alarm of a car that keeps returning.","B":"''Interested'' is even flatter than ''curious''.","C":"''Nosy'' implies prying into others'' business, the wrong flavor for a detective on alert.","D":"''Suspicious'' captures the wary, something-is-wrong reaction the repetition provokes."}', 'The repeated sedan warrants **wariness**, and only ''suspicious'' carries that shade.', '''Curious'' and ''interested'' are true in a loose sense, so they seem adequate.', 'Pick the related word whose precise connotation fits the situation''s emotional cue.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-47d43b436b06865d', 'act-english', 's-style', 3, 'The two leads practiced their duet <u>together with each other</u> until every harmony locked into place.', 'Which choice makes the sentence most concise without losing information?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"together, with each other,","letter":"B"},{"is_no_change":false,"label":"with each other together","letter":"C"},{"is_no_change":false,"label":"DELETE the underlined portion.","letter":"D"}]', 'D', '{"A":"''Together with each other'' states three times what ''duet'' by two leads already guarantees (redundant_synonym).","B":"Commas dress up the redundancy but add no new information (redundant_repunctuated).","C":"Reordering the redundant phrases leaves them just as repetitive, in a clumsier sequence (redundant_reordered).","D":"Correct: a duet practiced by the two leads is by definition a joint effort, so the phrase can be dropped with no loss."}', 'The word ''duet'' already **implies** joint performance by the two leads, so the underlined phrase adds words without meaning.', 'Keeping the original tempts students because the phrase sounds natural in speech, where such doubling is common and goes unnoticed.', '1) Ask what each underlined word adds beyond the rest of the sentence. 2) Check whether another word in the sentence already carries that meaning. 3) Test the sentence without the phrase. 4) If nothing is lost, the phrase is redundant. 5) Prefer the version where every remaining word earns its place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-492510199007ce4f', 'act-english', 's-style', 3, 'By uploading their dive photos to a shared database, volunteers give marine biologists <u>a ton of</u> observations that a small research team could never collect alone.', 'Which choice best fits the formal style of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"loads of","letter":"B"},{"is_no_change":false,"label":"a whole bunch of","letter":"C"},{"is_no_change":false,"label":"a wealth of","letter":"D"}]', 'D', '{"A":"''A ton of'' is casual, conversational register unsuited to formal scientific writing (misconception: colloquial_quantifier).","B":"''Loads of'' is equally informal slang for a large amount (misconception: colloquial_quantifier).","C":"''A whole bunch of'' is chatty and imprecise for this register (misconception: colloquial_quantifier).","D":"''A wealth of'' conveys a large, valuable quantity in appropriately formal language."}', 'The formal context calls for an elevated quantifier rather than **conversational** phrasing.', '''A ton of'' is vivid and familiar, so it feels expressive even though it clashes with the formal tone.', '1) Judge the passage''s register — formal, neutral, or casual. 2) Rate each quantifier''s formality. 3) Rule out slangy or conversational phrasings in formal contexts. 4) Choose the option whose register matches the surrounding prose.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4eea6eb5ac66aee0', 'act-english', 's-style', 3, 'Residents raised concerns <u>in connection with the matter of</u> whether tolls would rise after the renovation.', 'Which choice expresses the idea most clearly and concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"about the question of","letter":"B"},{"is_no_change":false,"label":"pertaining to the matter of","letter":"C"},{"is_no_change":false,"label":"about","letter":"D"}]', 'D', '{"A":"Five words of scaffolding convey a one-word relationship (misconception: wordy_bureaucratic_phrase).","B":"''The question of'' duplicates the job ''whether'' already does (misconception: wordy_nested_filler).","C":"Formal-sounding padding that adds syllables, not substance (misconception: wordy_formal_padding).","D":"A single preposition carries the full meaning with no loss."}', 'Concision keeps the **fewest words that preserve the meaning**, and the entire underlined stretch reduces to one preposition.', '''Pertaining to the matter of'' sounds elevated and official, so students mistake formality for precision.', '1) State what the underlined portion means in plain words. 2) Cross out any words whose work is already done elsewhere (like ''the question of'' before ''whether''). 3) Compare the surviving options: reject any that add words without adding meaning. 4) Reread the sentence with the leanest survivor to confirm nothing was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4fa3adf87962d08c', 'act-english', 's-style', 3, 'Volunteers arrive two hours early <u>due to the fact that</u> aligning a dozen telescopes takes time.', 'Which choice makes the sentence most concise without changing its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because of the fact that","letter":"B"},{"is_no_change":false,"label":"because","letter":"C"},{"is_no_change":false,"label":"for the reason that","letter":"D"}]', 'C', '{"A":"''Due to the fact that'' is a five-word detour around a simple causal link.","B":"Swaps in an equally bloated formula built on the same ''the fact that'' scaffolding.","C":"Correct: a single connector expresses the cause with nothing lost.","D":"''For the reason that'' is another inflated equivalent that adds length, not meaning."}', 'When a phrase can **collapse with zero meaning lost**, the collapsed version wins.', '''Due to the fact that'' tempts students because its formality sounds more academic than a plain connector.', '1) Isolate the connector phrase. 2) Ask what logical job it does (cause, contrast, time). 3) Try the shortest expression of that same job in its place. 4) If the sentence''s meaning is identical, the longer phrase was filler—choose the compression.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-566bb619ce9381a9', 'act-english', 's-style', 3, 'The bakery switched to a local rye grower <u>due to the fact that</u> the imported flour kept arriving stale.', 'Which choice most effectively expresses the idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"owing to the fact that","letter":"B"},{"is_no_change":false,"label":"because","letter":"C"},{"is_no_change":false,"label":"for the reason that","letter":"D"}]', 'C', '{"A":"''Due to the fact that'' is a five-word detour around a one-word causal connector (wordy_fact_that).","B":"''Owing to the fact that'' swaps one bloated formula for another of the same length (wordy_swap_formula).","C":"Correct — a single conjunction expresses the causal link completely.","D":"''For the reason that'' is another padded phrase that delays the cause (wordy_reason_that)."}', 'One direct conjunction does everything the padded phrases do, so the **leanest** version wins.', '''Owing to the fact that'' sounds more formal, and students often equate formality with correctness.', '1) Identify the relationship the phrase expresses (here: cause). 2) List shorter ways to express that same relationship. 3) Pick the tightest version that keeps the meaning and grammar intact. 4) Reread to confirm nothing was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-573f347282dd425c', 'act-english', 's-style', 3, 'Each Monday morning, the stage manager <u>posts the rehearsal schedule</u> outside the choir room.', 'Which choice expresses the idea most effectively?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"engages in the posting of the rehearsal schedule","letter":"B"},{"is_no_change":false,"label":"posts, in a timely manner, the rehearsal schedule","letter":"C"},{"is_no_change":false,"label":"makes it a point to post the rehearsal schedule","letter":"D"}]', 'A', '{"A":"Correct: the direct verb states the action completely, with no padding.","B":"Nominalizing the verb into ''the posting of'' inflates one action into a ceremony (wordy_nominalization).","C":"The inserted phrase duplicates the timing already fixed by ''Each Monday morning'' while interrupting the verb (wordy_redundant_insert).","D":"''Makes it a point to'' is an empty frame that delays the verb without informing the reader (wordy_filler_frame)."}', 'The original is already **direct** — one verb, one object — and every alternative adds words that carry no new information.', 'The ''makes it a point to'' version tempts students because it seems to add earnestness, though it tells the reader nothing the plain verb doesn''t.', '1) Identify the core action and its object. 2) For each option, list any words beyond that core. 3) Ask what new information each extra word supplies. 4) Strike phrases that duplicate the sentence or merely wrap the verb. 5) Keep the version where nothing can be cut without losing meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5c09954c36fd171d', 'act-english', 's-style', 3, 'Museum conservators vacuum antique samplers <u>at a low level of suction that is gentle</u> in order to lift dust without stressing the threads.', 'Which choice expresses the idea most concisely while preserving the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"with gentle suction","letter":"B"},{"is_no_change":false,"label":"using a suction level that is low and gentle","letter":"C"},{"is_no_change":false,"label":"gently, at a suction level kept low","letter":"D"}]', 'B', '{"A":"''A low level of suction that is gentle'' doubles the idea — low, gentle — inside a padded frame.","B":"Correct: three words carry the entire meaning of careful, soft airflow.","C":"''Low and gentle'' repeats one quality twice inside a wordy scaffold.","D":"The split construction scatters the same idea across the phrase without adding precision."}', 'The **shortest** phrasing that keeps every unit of meaning wins; nothing in the longer versions survives the cut test.', 'Longer phrasings tempt because they feel more careful, but each extra word repeats rather than refines.', '1) List the meaning units the underlined portion must convey. 2) Strike every word that repeats a unit. 3) Choose the option carrying all units in the fewest words. 4) Re-read for grammar and fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-60f7c23a725fa3d6', 'act-english', 's-style', 3, 'The arrival of synchronized sound in 1928 <u>transformed</u> the animation industry almost overnight.', 'Which choice makes the sentence most concise without losing meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was something that transformed","letter":"B"},{"is_no_change":false,"label":"had the effect of transforming","letter":"C"},{"is_no_change":false,"label":"brought about a state of transformation in","letter":"D"}]', 'A', '{"A":"The single direct verb delivers the action with no wasted words.","B":"''Was something that'' is an empty frame adding words but no meaning.","C":"''Had the effect of transforming'' restates the verb''s own meaning in five words.","D":"''Brought about a state of transformation in'' buries the action in an abstract noun phrase."}', 'The original verb is already **concise and direct**; every alternative pads it.', '''Had the effect of'' sounds analytically precise, as if it were describing causation more carefully.', '1) Identify the core action. 2) For each option, ask what each added word contributes. 3) Strike phrases that restate the verb (''had the effect of,'' ''was something that''). 4) Select the version in which every word earns its place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-624e6d018ee983c0', 'act-english', 's-style', 3, 'Static <u>crackled</u> through the speaker grille whenever lightning flashed over the ridge.', 'Which choice provides the most precise word for the context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"occurred","letter":"B"},{"is_no_change":false,"label":"emerged","letter":"C"},{"is_no_change":false,"label":"was heard","letter":"D"}]', 'A', '{"A":"Correct: the onomatopoeic verb captures the abrupt, spitting character of storm interference.","B":"''Occurred'' is an all-purpose event verb that erases the sound entirely.","C":"''Emerged'' implies gradual coming-into-view, the wrong sense for sudden bursts.","D":"''Was heard'' is a flat passive that reports reception, not the noise''s texture."}', 'Precision means the verb carries the **specific character** of the action — here, the abrupt texture of storm static.', '''Was heard'' tempts students because it is unimpeachably grammatical, but grammatical safety is not the same as exactness.', '1) Picture the action the sentence describes. 2) For each verb, ask what specific manner it conveys. 3) Eliminate all-purpose verbs that could describe anything. 4) Eliminate verbs whose manner contradicts the scene. 5) Keep the verb whose sense matches the event exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-670a5cc4945b3eb0', 'act-english', 's-style', 3, '<u>Due to the fact that</u> the bridge was icy, the road crew closed it overnight.', 'Which choice trims the wordy opener?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In light of the fact that","letter":"B"},{"is_no_change":false,"label":"Because","letter":"C"},{"is_no_change":false,"label":"Being that","letter":"D"}]', 'C', '{"A":"''Due to the fact that'' spends five words doing one word''s job.","B":"''In light of the fact that'' is even wordier than the original.","C":"''Because'' states the cause directly.","D":"''Being that'' is both nonstandard and no shorter in spirit."}', '**Because** replaces the five-word scaffold with the one word it means.', 'The long phrase sounds official, which reads as ''more correct''.', 'Swap wordy connectors for their one-word equivalents (due to the fact that → because).', 'underlined-span-mc', 'the long phrase sounds official, which reads as ''more correct''', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-687045490bdb746d', 'act-english', 's-style', 3, 'In its grant application, the market described its central mission: <u>to increase residents'' access to</u> fresh, affordable produce.', 'Which choice best maintains the formal style established in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"to hook residents up with","letter":"B"},{"is_no_change":false,"label":"to help residents snag","letter":"C"},{"is_no_change":false,"label":"to boost folks'' chances of grabbing","letter":"D"}]', 'A', '{"A":"Correct — precise, formal diction suited to a grant application.","B":"''Hook up with'' is a slang idiom out of place in official prose (register_slang_idiom).","C":"''Snag'' is casual, grab-bag diction that deflates a mission statement (register_casual_verb).","D":"''Folks'' and ''grabbing'' are conversational words unsuited to a document for funders (register_conversational)."}', 'A grant application demands **formal**, precise diction, and this phrasing alone maintains it.', '''Hook residents up with'' sounds friendly and energetic, so students mistake warmth for effective style.', '1) Identify the document type named in the sentence. 2) Set the expected register from that document (formal, neutral, casual). 3) Flag any option containing slang, idioms, or conversational words. 4) Keep only options a reader of that document would expect. 5) Reread the sentence to confirm one consistent voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-68bc818dbb54d0e0', 'act-english', 's-style', 3, 'A printed tide chart tells divers <u>when</u> the water along the reef will be calmest.', 'Which choice is most concise while preserving the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the time at which","letter":"B"},{"is_no_change":false,"label":"the particular time when","letter":"C"},{"is_no_change":false,"label":"at what point in time","letter":"D"}]', 'A', '{"A":"Correct: a single word conveys the timing with nothing wasted.","B":"''The time at which'' inflates a one-word idea into three (wordy_phrase).","C":"Adds the filler ''particular'' to an already wordy phrase (wordy_phrase).","D":"''At what point in time'' stretches a simple word across four (wordy_phrase)."}', 'The **shortest** phrasing that keeps the meaning is best, and one word already conveys the timing.', 'The longer phrases feel more precise, so students choose bulk over the tighter single word.', '1) Identify the meaning the phrase must convey. 2) Test whether one word can convey it. 3) Reject phrases that add words without adding meaning. 4) Choose the shortest option that keeps the sense.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-68da5845d139c8a3', 'act-english', 's-style', 3, 'Before recommending a route through the pass, the survey team <u>looked at</u> the valley floor for an entire season, measuring snowmelt and charting every flood channel.', 'Which choice most precisely describes the survey team''s work?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"studied","letter":"B"},{"is_no_change":false,"label":"glimpsed","letter":"C"},{"is_no_change":false,"label":"regarded","letter":"D"}]', 'B', '{"A":"''Looked at'' is too vague to convey a season of systematic measurement.","B":"Correct: it conveys sustained, careful examination, matching the measuring and charting the sentence describes.","C":"''Glimpsed'' means a brief, often accidental look — the opposite of a season''s deliberate work.","D":"''Regarded'' suggests a manner of viewing or an opinion, not methodical investigation."}', 'Only one option matches the **sustained, systematic** examination the sentence goes on to describe.', '''Regarded'' tempts students who reach for a formal-sounding synonym without checking whether its meaning fits the described work.', '1) List what the sentence says the actor actually did. 2) For each verb option, state its core meaning — duration, intent, and method. 3) Eliminate verbs that are too vague, too brief, or about attitude rather than action. 4) Choose the verb whose meaning covers all the described work.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6956c9cc571e3b71', 'act-english', 's-style', 3, 'Fireflies <u>persist</u> in the older neighborhoods, where hedges stay damp and porch lights go dark by ten.', 'Which choice is most effective for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"persist, as a matter of fact,","letter":"B"},{"is_no_change":false,"label":"basically persist, in a sense,","letter":"C"},{"is_no_change":false,"label":"persist, or at least it seems that they do,","letter":"D"}]', 'A', '{"A":"Correct: the plain verb states the claim directly, and the passage supplies its support.","B":"''As a matter of fact'' announces a fact without adding one — pure filler (empty_announcer).","C":"''Basically'' and ''in a sense'' hedge a claim the passage treats as straightforwardly true (double_hedge).","D":"The tacked-on doubt clause contradicts the passage''s confident evidence and pads the sentence (unearned_doubt)."}', 'Every insertion here is **filler** — announcing, hedging, or doubting — while the plain verb already carries the full claim.', '''As a matter of fact'' feels like it strengthens the claim, so students add it for emphasis without noticing it contributes no content.', '1) Delete the inserted phrase and re-read. 2) If nothing is lost, the phrase was filler. 3) Check hedges against the passage: softening is only justified by real uncertainty in the text. 4) Check announcers (''as a matter of fact,'' ''needless to say'') — they never add facts. 5) Keep the version where every word earns its place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b4c31b173541f20', 'act-english', 's-style', 3, 'The new noise ordinance <u>limits</u> amplified music near the hospital district to sixty decibels after 10 p.m.', 'Which choice conveys the sentence''s meaning most precisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"restrains","letter":"B"},{"is_no_change":false,"label":"shortens","letter":"C"},{"is_no_change":false,"label":"lessens","letter":"D"}]', 'A', '{"A":"The original verb precisely expresses a cap set at a stated level, fitting the ''to sixty decibels'' phrase.","B":"''Restrains'' suggests physically holding something back and does not idiomatically pair with ''to sixty decibels.''","C":"''Shortens'' concerns duration, not volume — the wrong dimension for a decibel figure.","D":"''Lessens'' means reduces but cannot express a maximum; ''lessens ... to sixty decibels'' garbles the intended cap."}', 'Only the original verb expresses a **cap at a stated level**, which the decibel figure requires.', '''Lessens'' shares the idea of reduction, so it feels interchangeable until it is tested against the ''to sixty decibels'' phrase.', '1) Identify what the verb must do in this exact sentence. 2) Note the phrases the verb must connect to — here, a measured level. 3) Test each candidate in the frame: does it fit the dimension (volume, not time) and the structure (''to'' plus a level)? 4) Reject near-synonyms that fail either test. 5) Re-read with the survivor in place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6f0cd0d7341e719c', 'act-english', 's-style', 3, 'After the long climb, the hikers were <u>skinny</u> and ready to collapse in the shade.', 'Which word best fits the meaning the sentence intends?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"thin","letter":"B"},{"is_no_change":false,"label":"spent","letter":"C"},{"is_no_change":false,"label":"slim","letter":"D"}]', 'C', '{"A":"''Skinny'' describes body shape, not the exhaustion the sentence is about.","B":"''Thin'' is also about size, missing ''ready to collapse''.","C":"''Spent'' means used up and exhausted, which matches collapsing in the shade.","D":"''Slim'' likewise refers to being narrow, not tired."}', 'The context signals **exhaustion**, and among these near-synonyms only ''spent'' means worn out.', '''Skinny'', ''thin'', and ''slim'' are close cousins, so it''s easy to swap one for another.', 'Related words differ in meaning — pick the one whose sense the sentence actually needs.', 'underlined-span-mc', '''Skinny'', ''thin'', and ''slim'' are close cousins, so it''s easy to swap…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-702a4ea3471dd966', 'act-english', 's-style', 3, '<u>It is important to note that most</u> of the ocean floor has never been mapped in detail.', 'Which choice most effectively eliminates unnecessary words?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Most","letter":"B"},{"is_no_change":false,"label":"It is a well-known fact that most","letter":"C"},{"is_no_change":false,"label":"What is important is that most","letter":"D"}]', 'B', '{"A":"''It is important to note that'' is an empty frame that adds no information (empty_filler).","B":"Correct: cutting the filler opener leaves a direct, complete statement.","C":"''It is a well-known fact that'' is another hollow lead-in adding no content (empty_filler).","D":"''What is important is that'' only announces importance without adding meaning (empty_filler)."}', 'An **empty introductory phrase** that adds no information should be deleted entirely.', 'The framing phrases sound authoritative, so students keep them thinking they signal importance.', '1) Check whether the opening words state a fact or merely announce that one is coming. 2) Delete the phrase and see if any meaning is lost. 3) If nothing is lost, cut it. 4) Begin with the actual statement.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-74185039391e8c26', 'act-english', 's-style', 3, 'The committee will meet <u>at 9 a.m. in the morning</u> on Thursday.', 'Which choice cuts the repeated time reference?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"in the morning at 9 a.m.","letter":"B"},{"is_no_change":false,"label":"at 9 a.m.","letter":"C"},{"is_no_change":false,"label":"at 9 a.m. in the early morning","letter":"D"}]', 'C', '{"A":"''a.m.'' already MEANS morning — ''in the morning'' repeats it.","B":"Reordering the phrases doesn''t remove the repetition.","C":"''At 9 a.m.'' states the time once, completely.","D":"''Early'' adds a third layer to the same redundancy."}', '''**a.m.**'' contains ''morning''; saying both is saying it twice.', 'The doubled phrase is common in speech, where redundancy aids the listener.', 'Expand abbreviations mentally (a.m. = morning) to catch hidden repetition.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-7e18faf969bf244c', 'act-english', 's-style', 3, 'Years of Saturday foot traffic had <u>demolished</u> shallow ruts into the grassy field where the market sets up.', 'Which choice most precisely conveys how the ruts formed?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"punctured","letter":"B"},{"is_no_change":false,"label":"erased","letter":"C"},{"is_no_change":false,"label":"worn","letter":"D"}]', 'D', '{"A":"''Demolished'' means destroyed outright and cannot describe gradually forming ruts (overstated_intensity).","B":"''Punctured'' means pierced a hole through — the wrong physical action for slow, repeated footsteps (wrong_physical_action).","C":"''Erased'' means removed, the opposite of creating ruts (reversed_direction).","D":"Correct — ''worn'' captures gradual shaping by repeated contact and fits the idiom of ruts formed into a field."}', 'Only this verb captures **gradual** shaping by repeated contact and fits the idiom of ruts formed into a surface.', '''Demolished'' sounds forceful and vivid, so students reward its drama instead of testing its literal meaning.', '1) Picture the literal physical event the sentence describes. 2) For each verb, state its literal action and intensity. 3) Check the direction: does the verb create or remove the named thing? 4) Check intensity: sudden force or gradual repetition? 5) Choose the verb matching both the direction and the pace.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8014f7bd65dd1add', 'act-english', 's-style', 3, 'By June the chassis work was <u>completely finished in its entirety</u>, and only the cabinet still needed attention.', 'Which choice makes the sentence most concise without losing information?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"finished","letter":"B"},{"is_no_change":false,"label":"completely finished","letter":"C"},{"is_no_change":false,"label":"finished in its entirety","letter":"D"}]', 'B', '{"A":"Both ''completely'' and ''in its entirety'' restate what ''finished'' already guarantees — a double redundancy.","B":"Correct: the verb alone carries the full meaning.","C":"''Completely'' repeats the completion already built into ''finished.''","D":"''In its entirety'' is the same redundancy as ''completely,'' dressed as a prepositional phrase."}', '''Finished'' is an **absolute**: modifiers that restate its built-in completion add words but no information.', 'Keeping ''completely'' feels like added emphasis, so students treat the intensifier as meaningful rather than redundant.', '1) Ask what the verb already guarantees by definition. 2) Test each modifier: does it add information or repeat the verb''s meaning? 3) Delete every repeater, one at a time. 4) Reread to confirm nothing factual was lost. 5) Keep the leanest version that still says everything.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-85ec1f849e8c5fe7', 'act-english', 's-style', 3, 'Completed in 1848 and still carrying its original boiler plate, the museum''s oldest locomotive <u>is a pretty big deal for</u> visiting historians, who often travel hundreds of miles to examine it.', 'Which choice best maintains the register of the sentence as a whole?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"is seriously cool to","letter":"B"},{"is_no_change":false,"label":"is an object of ineffable, transcendent wonder to","letter":"C"},{"is_no_change":false,"label":"holds particular interest for","letter":"D"}]', 'D', '{"A":"''A pretty big deal'' is conversational slang, well below the sentence''s formal, historical register.","B":"''Seriously cool'' is even more casual, clashing with the measured description around it.","C":"''Ineffable, transcendent wonder'' overshoots into ornate prose the plain passage never uses.","D":"Correct: measured, formal phrasing matches the sentence''s historical voice."}', 'Measured, formal phrasing keeps the **register** consistent with the sentence''s historical voice.', 'The ornate option lures students who assume the most elevated vocabulary must be the most appropriately formal.', '1) Label the passage''s register in two words (e.g., formal-historical). 2) Label each option the same way. 3) Reject anything more casual than the passage and anything more ornate. 4) Read the survivor in place to confirm one consistent voice.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-87320507356d0f55', 'act-english', 's-style', 3, 'The referee''s <u>firm</u> decision to stop the match drew boos, but replays proved she was right.', 'Which word best captures a decision that would not be changed?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"hard","letter":"B"},{"is_no_change":false,"label":"solid","letter":"C"},{"is_no_change":false,"label":"stiff","letter":"D"}]', 'A', '{"A":"''Firm'' means resolute and unwavering — precisely a decision that holds.","B":"''Hard'' suggests difficulty or harshness, not resolve.","C":"''Solid'' describes reliability of a thing, an awkward fit for ''decision''.","D":"''Stiff'' implies rigidity or awkwardness, wrong for a judgment call."}', '''Firm'' carries the shade of **resolute and final**, which the sentence needs — and it''s already correct.', '''Hard'', ''solid'', and ''stiff'' all touch firmness physically, so one seems swappable for ''firm''.', 'Check whether the underlined word already carries the right shade before replacing it.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-891be373652d0cc6', 'act-english', 's-style', 3, 'The expedition was delayed for a week <u>due to the fact that</u> the helicopter needed a replacement rotor.', 'Which choice most effectively expresses this idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because","letter":"B"},{"is_no_change":false,"label":"because of the fact that","letter":"C"},{"is_no_change":false,"label":"in light of the fact that it was the case that","letter":"D"}]', 'B', '{"A":"''Due to the fact that'' spends five words on a job one word can do (empty formula).","B":"A single subordinating word delivers the causal link cleanly.","C":"This version keeps the empty ''the fact that'' scaffolding around the useful word (partial trim).","D":"Two nested filler formulas make this the wordiest option of all (compounded padding)."}', 'The **shortest construction that preserves the meaning** wins, and one word states the cause completely.', '''Due to the fact that'' appears constantly in official-sounding prose, so it reads as formal rather than inflated.', '1) Bracket the connector phrase. 2) Ask what work it does (here: signal cause). 3) Try the shortest expression of that work. 4) If nothing is lost, adopt the shorter form. 5) Beware phrases containing ''the fact that'' — they almost always deflate.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8c3989a050180124', 'act-english', 's-style', 3, 'Network radio favored hotel dance orchestras <u>because</u> their polished, unhurried sound suited late-evening broadcasts.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"due to the fact that","letter":"B"},{"is_no_change":false,"label":"being that","letter":"C"},{"is_no_change":false,"label":"on account of the fact that","letter":"D"}]', 'A', '{"A":"Correct: the original connector expresses the entire causal link directly.","B":"wordy_formula: *due to the fact that* spends five words on a one-word job.","C":"*Being that* is nonstandard in formal prose and no more precise.","D":"*On account of the fact that* is the most inflated version of the same connector."}', 'The original connector expresses the causal relationship with **no filler**.', '*Due to the fact that* appears constantly in official-sounding prose, so it reads as formal rather than as padding.', '1) Identify the logical link the connector must express. 2) Weigh each option''s length against that one job. 3) Strike options built on ''the fact that'' and options that are nonstandard idioms. 4) Choose the connector that is both standard and unpadded.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8f21ec06f0eef174', 'act-english', 's-style', 3, '<u>It is interesting to note that the</u> retaining walls the CCC crews stacked in the 1930s still hold the hillside above the river trail.', 'Which choice makes this sentence most effective?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"It should be pointed out that the","letter":"B"},{"is_no_change":false,"label":"The","letter":"C"},{"is_no_change":false,"label":"As a matter of fact, the","letter":"D"}]', 'C', '{"A":"Empty throat-clearing: it announces that a fact is interesting instead of letting the fact impress the reader.","B":"The same announcement formula in stuffier clothes; six words still point at the statement instead of making it.","C":"Correct: dropping the empty frame lets the sentence start at its first information-bearing word.","D":"''As a matter of fact'' signals a correction or contrast, and nothing in the sentence is being corrected."}', 'Cutting the **filler frame** lets the eighty-year endurance of the walls speak for itself, starting the sentence at real information.', 'The original tempts students because ''It is interesting to note'' feels like sophisticated academic style rather than the empty preamble it is.', '1) Ask whether the opening phrase delivers information or merely announces it. 2) Delete announcements such as ''It is interesting to note'' or ''It should be pointed out.'' 3) Check emphasis phrases for a real contrast that justifies them. 4) Start the sentence at its first information-bearing word.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-90ce78fa5643c3ae', 'act-english', 's-style', 3, 'The survey team rationed every canteen carefully <u>due to the fact that</u> the next reliable spring lay a full three days'' march to the north.', 'Which choice most effectively reduces the wordiness of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"on account of the fact that","letter":"B"},{"is_no_change":false,"label":"because","letter":"C"},{"is_no_change":false,"label":"in light of the fact that","letter":"D"}]', 'C', '{"A":"A five-word phrase does the work of a single causal conjunction (wordy_phrase).","B":"Swaps in an equally bloated phrase for the same simple idea (wordy_phrase).","C":"Correct: one causal conjunction expresses the link concisely with no lost meaning.","D":"Replaces one padded phrase with another just as long (wordy_phrase)."}', 'A single causal conjunction conveys the same ''cause'' relationship that the **padded phrase** buries in five words.', 'The long phrase sounds formal and careful, so students mistake its bulk for precision instead of trimming it.', '1) Spot any multi-word phrase that signals cause (''due to the fact that,'' ''on account of the fact that''). 2) Ask what single word it stands for. 3) Replace the padded phrase with that one word. 4) Confirm the meaning is unchanged. 5) Reject any option that keeps the extra words.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-931c4e7713d2bc57', 'act-english', 's-style', 3, 'By steadily grazing on fast-growing seagrass and algae, green sea turtles keep the beds <u>trimmed</u> so that sunlight can still reach the coral below.', 'Which choice is the most concise version of the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"trimmed and cut back","letter":"B"},{"is_no_change":false,"label":"trimmed down and shortened","letter":"C"},{"is_no_change":false,"label":"trimmed and thereby reduced in length","letter":"D"}]', 'A', '{"A":"''Trimmed'' says everything needed; the single verb is complete and non-redundant.","B":"''Cut back'' merely repeats the meaning of ''trimmed,'' a redundant pair (misconception: redundant_synonym).","C":"''Down'' and ''shortened'' pile on meanings ''trimmed'' already carries (misconception: redundant_particle_and_synonym).","D":"''Thereby reduced in length'' restates ''trimmed'' in wordier form (misconception: redundant_restatement)."}', 'One precise verb conveys the idea; adding synonyms only **repeats** it.', 'Pairing verbs sounds thorough, so a doubled phrase feels more complete than the lone word.', '1) Identify the core meaning of the underlined verb. 2) Check whether the added words say anything the verb doesn''t already say. 3) If they only restate it, they are redundant. 4) Prefer the shortest wording that keeps the full meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97cf1d12c90d64ab', 'act-english', 's-style', 3, 'The museum''s new wing was designed to <u>respect</u> the traditions of the surrounding historic district.', 'Which word best expresses paying active tribute to those traditions through the design itself?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"notice","letter":"B"},{"is_no_change":false,"label":"honor","letter":"C"},{"is_no_change":false,"label":"admire","letter":"D"}]', 'C', '{"A":"''Respect the traditions'' is acceptable but abstract; a building ''honors'' traditions more precisely through form.","B":"''Notice'' merely means to observe, far too weak.","C":"''Honor'' means to embody and pay tribute to, exactly what a sympathetic design does.","D":"''Admire'' describes an inward feeling, which a building cannot literally do."}', '''Honor'' carries the shade of **actively paying tribute**, which a design can do; the others fall short.', '''Respect'' is a common near-synonym, so leaving it feels safe.', 'When several related words fit loosely, choose the one whose exact shade the sentence rewards.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9e8e72b34bcb715d', 'act-english', 's-style', 3, 'The novelist was praised for her <u>childish</u> sense of wonder at the natural world.', 'Which word best conveys the admiring meaning the sentence intends?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"juvenile","letter":"B"},{"is_no_change":false,"label":"immature","letter":"C"},{"is_no_change":false,"label":"childlike","letter":"D"}]', 'D', '{"A":"''Childish'' is an insult, implying petty or silly — wrong for praise.","B":"''Juvenile'' also disparages, suggesting silliness.","C":"''Immature'' is negative, the opposite of admiration.","D":"''Childlike'' admiringly means innocent and openhearted, matching ''praised'' and ''wonder''."}', '''Childlike'' and ''childish'' share a root but differ in charge: only **''childlike'' is positive**.', 'The words look almost identical, so the negative one slips in unnoticed.', 'Related words can carry opposite connotations — match the emotional charge to the context.', 'underlined-span-mc', 'the words look almost identical, so the negative one slips in unnoticed', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9fb6fd5eaae7fdf9', 'act-english', 's-style', 3, 'The committee reached a <u>consensus of opinion</u> after two hours of debate.', 'Which choice is the most concise without losing meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"consensus","letter":"B"},{"is_no_change":false,"label":"consensus of shared opinion","letter":"C"},{"is_no_change":false,"label":"unanimous consensus of opinion","letter":"D"}]', 'B', '{"A":"A consensus IS an agreement of opinion — ''of opinion'' repeats what the word already says.","B":"''Consensus'' alone carries the full meaning.","C":"''Shared'' stacks a third redundancy onto the phrase.","D":"''Unanimous'' adds yet another layer of the same idea."}', 'The ACT rewards the **shortest** option that preserves the meaning — ''consensus'' says it all.', 'Longer phrases feel more formal and thorough.', 'Cut words that restate what another word already contains.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a0e86515ceff7f2a', 'act-english', 's-style', 3, 'Meteorologists warn that a single failed buoy can <u>injure</u> the accuracy of wave forecasts along an entire stretch of coastline.', 'Which choice provides the most precise word for the context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"wound","letter":"B"},{"is_no_change":false,"label":"degrade","letter":"C"},{"is_no_change":false,"label":"shrink","letter":"D"}]', 'C', '{"A":"''Injure'' applies to living things; accuracy cannot be injured (misconception: any harm word fits any harmed thing).","B":"''Wound'' has the same living-victim problem, only more vividly (misconception: vivid equals precise).","C":"Correct: it names the gradual lowering of quality that data loss actually causes.","D":"''Shrink'' means to get smaller in size or amount; accuracy worsens rather than gets smaller (misconception: any lessening verb fits any decline)."}', 'The key verb pairs correctly with **quality nouns** like accuracy, naming a lowering of quality rather than a bodily harm or a size change.', '''Shrink'' correctly signals reduction, so it feels compatible with accuracy going down.', '1) Identify the object of the verb (''accuracy''). 2) Ask what kind of noun it is: living thing, quantity, or quality. 3) Test each verb against that kind — can this verb act on a quality? 4) Reject verbs built for bodies or sizes. 5) Choose the verb whose natural partners include the object.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a4b84f7f376c6065', 'act-english', 's-style', 3, 'Each spring the members <u>collaborate together on</u> a single monumental sculpture for the courthouse lawn.', 'Which choice is most effective for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"collaborate on","letter":"B"},{"is_no_change":false,"label":"collaborate jointly on","letter":"C"},{"is_no_change":false,"label":"together collaborate on","letter":"D"}]', 'B', '{"A":"''Collaborate'' already means work together, so adding ''together'' repeats the idea (unnoticed redundancy).","B":"Correct: the bare verb carries the whole idea without repetition.","C":"''Jointly'' is a synonym for the idea already inside the verb, so the redundancy survives (synonym swap).","D":"Reordering the words leaves the doubled meaning fully intact (order-not-meaning fix)."}', '**Redundancy** is cut by deleting the word whose meaning the verb already contains.', 'Swapping ''together'' for the more formal ''jointly'' feels like an improvement, but the meaning is still stated twice.', '1) Define the verb in your own words. 2) Check every nearby modifier: does any repeat part of that definition? 3) If so, the modifier is redundant no matter what synonym or position it takes. 4) Keep the version that states the idea exactly once. 5) Reread to confirm no meaning was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a6ad921f42a04f31', 'act-english', 's-style', 3, 'The forager returns to the hive and <u>shares and distributes the nectar</u> to several house bees waiting near the entrance.', 'Which choice best eliminates the redundancy in the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shares and gives out the nectar","letter":"B"},{"is_no_change":false,"label":"distributes the nectar","letter":"C"},{"is_no_change":false,"label":"shares, distributes, and passes the nectar","letter":"D"}]', 'C', '{"A":"''Shares and distributes'' pairs two verbs that mean essentially the same thing, so one is redundant.","B":"''Shares and gives out'' still doubles up two near-synonymous verbs, keeping the redundancy in new words.","C":"Correct: a single precise verb conveys the whole action with no repetition.","D":"Piles up three overlapping verbs, making the redundancy worse rather than removing it."}', 'When two words carry the same meaning, keep only one, so a **single** verb says everything the pair did.', 'The paired verbs sound thorough and emphatic, so students read the doubling as richness rather than repetition.', '1) Underline each verb in the span and paraphrase its meaning. 2) If two verbs mean the same thing, one is redundant. 3) Keep the single verb that best carries the action and delete the twin. 4) Reject any option that keeps or adds a second same-meaning verb.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a86b51f1ac1bc491', 'act-english', 's-style', 3, 'The scouting app <u>has the ability to</u> rank every alliance pairing by projected score within seconds.', 'Which choice expresses the idea most efficiently?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"can","letter":"B"},{"is_no_change":false,"label":"possesses the capability to","letter":"C"},{"is_no_change":false,"label":"is able to","letter":"D"}]', 'B', '{"A":"Stretches a simple capability into a four-word idiom (wordy_capability_idiom).","B":"Correct: one modal verb conveys the full capability with nothing lost.","C":"Inflates the diction without adding any meaning (inflated_diction).","D":"Trims some fat but still uses three words where one identical-meaning word exists (partial_concision)."}', 'One **modal verb** conveys the full capability, so every longer equivalent fails the concision test.', '''Is able to'' tempts students because it is shorter than the original and feels like an improvement.', '1) List what each option literally means. 2) Group the options that mean exactly the same thing. 3) Within that group, keep the fewest words. 4) Only keep extra words when they add real meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a8b7324e195f7d16', 'act-english', 's-style', 3, 'When a sequence tested poorly with preview audiences, the director would <u>revert back to</u> an earlier version of the storyboard.', 'Which choice makes the sentence most concise without losing meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"revert back again to","letter":"B"},{"is_no_change":false,"label":"revert to","letter":"C"},{"is_no_change":false,"label":"make a reversion back to","letter":"D"}]', 'C', '{"A":"''Revert'' already means to go back, so ''back'' repeats the idea.","B":"''Back'' and ''again'' both duplicate the return built into ''revert.''","C":"''Revert to'' expresses the complete idea once, with no repetition.","D":"Nominalizing into ''make a reversion'' adds bulk, and ''back'' still doubles the direction."}', '**Redundancy** check: the direction is already inside ''revert,'' so nothing may repeat it.', '''Revert back'' is so common in speech that the doubling is invisible to the ear.', '1) Define the key verb precisely. 2) Ask whether any nearby word repeats part of that definition. 3) Delete the repeaters and reread. 4) Keep the version that preserves the full meaning with no duplicated idea.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b2fee8407d19eefd', 'act-english', 's-style', 3, 'The archive''s shellac discs are <u>fragile</u>, so librarians handle them only while wearing cotton gloves.', 'Which choice best avoids redundancy while preserving the meaning of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"fragile and easily breakable","letter":"B"},{"is_no_change":false,"label":"fragile, delicate objects","letter":"C"},{"is_no_change":false,"label":"fragile in nature","letter":"D"}]', 'A', '{"A":"Correct: one precise adjective carries the full meaning with nothing repeated.","B":"''Easily breakable'' restates what ''fragile'' already means, doubling the idea.","C":"''Delicate'' is a synonym stacked onto ''fragile,'' adding words but no information.","D":"''In nature'' is filler that adds no meaning to the adjective it trails."}', 'The single adjective already says everything, so any addition is **redundant**.', '''Fragile and easily breakable'' tempts students because paired descriptions feel thorough, even when the second half repeats the first.', '1) Define the underlined word in your own words. 2) Define each added word or phrase the same way. 3) If two definitions overlap, one of them must go. 4) Strip any phrase (like ''in nature'') that could vanish without changing meaning. 5) Keep the leanest version that still says everything.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b37b2b5e45edd9f9', 'act-english', 's-style', 3, 'The monitoring flights are repeated <u>each year on an annual basis</u> so that thinning rates can be compared.', 'Which choice best conforms to the conventions of standard English?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"each year","letter":"B"},{"is_no_change":false,"label":"annually every single year","letter":"C"},{"is_no_change":false,"label":"each year, annually,","letter":"D"}]', 'B', '{"A":"''Each year'' and ''on an annual basis'' say the same thing twice (redundant_synonym).","B":"One time expression carries the full meaning without repetition.","C":"''Annually'' and ''every single year'' stack the same idea into a bigger pile (double redundancy).","D":"The added ''annually,'' restates ''each year'' and litters the sentence with commas (redundant appositive)."}', 'One time phrase suffices; the other versions repeat the **same meaning** in different words.', '''On an annual basis'' sounds official and technical, so the doubling masquerades as precision.', '1) Circle every word or phrase that expresses time. 2) Ask whether any two circles mean the same thing. 3) Delete duplicates, keeping the simplest. 4) Reread: has any information been lost? If not, the cut was right.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b3b8de54b4b091c5', 'act-english', 's-style', 3, 'Before the inspection, the keeper <u>looked at</u> each frame against the sunlight to judge how much brood the queen had laid.', 'Which choice most precisely conveys careful, deliberate observation?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"examined","letter":"B"},{"is_no_change":false,"label":"glimpsed","letter":"C"},{"is_no_change":false,"label":"eyed","letter":"D"}]', 'B', '{"A":"''Looked at'' is neutral and vague, giving no sense of the close, purposeful scrutiny the sentence describes.","B":"Correct: ''examined'' names a careful, methodical inspection that fits judging brood on each frame.","C":"''Glimpsed'' means a brief, partial look — the opposite of the deliberate study the sentence requires.","D":"''Eyed'' suggests a casual or suspicious glance, not the careful assessment being described."}', 'The most **precise** verb names deliberate, close inspection, which is exactly what judging brood frame by frame demands.', '''Looked at'' is true and safe, so students accept it without asking whether a sharper verb captures the care involved.', '1) Name the exact manner of the action the sentence describes (here, careful, methodical study). 2) Test each candidate verb''s connotation against that manner. 3) Eliminate verbs that are vague, too brief, or too casual. 4) Keep the verb whose precise sense matches the described care.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bcba8ab9c81233f5', 'act-english', 's-style', 3, 'The 1941 animators'' strike, which halted production for five weeks, <u>got super ugly</u> before federal mediators stepped in.', 'Which choice best maintains the style and tone of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was a real train wreck","letter":"B"},{"is_no_change":false,"label":"kind of spiraled","letter":"C"},{"is_no_change":false,"label":"grew increasingly bitter","letter":"D"}]', 'D', '{"A":"''Got super ugly'' is casual slang out of step with the sentence''s formal, historical register.","B":"''A real train wreck'' is colloquial hyperbole that clashes with ''federal mediators'' and ''halted production.''","C":"''Kind of spiraled'' hedges vaguely, in chatty diction unsuited to a serious labor dispute.","D":"This choice describes the escalation in measured, formal language matching the passage."}', 'The passage''s **formal register** requires precise, measured diction for the strike''s escalation.', '''Got super ugly'' is vivid and roughly accurate, so its energy tempts students despite the register clash.', '1) Identify the passage''s register from surrounding word choices. 2) Label each option formal, neutral, or colloquial. 3) Eliminate register mismatches. 4) Among matches, keep the most precise description of events.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c6efad6b7b58966d', 'act-english', 's-style', 3, 'The new scoreboard operator <u>has the ability to</u> update out-of-town scores within seconds of each final.', 'Which choice makes the sentence most direct without changing its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"is in a position to","letter":"B"},{"is_no_change":false,"label":"can","letter":"C"},{"is_no_change":false,"label":"possesses the capability to","letter":"D"}]', 'C', '{"A":"Unfolds a single modal idea into a four-word phrase with no added meaning (ability_phrase_padding).","B":"A vague idiom that is both roomier and fuzzier than a plain statement of ability (vague_idiom).","C":"Correct: one modal verb states the ability completely.","D":"The most inflated version — grand vocabulary disguising the same simple idea (inflated_diction)."}', 'A single **modal** verb expresses ability completely, so the multi-word ability phrases are padding.', '''Possesses the capability'' sounds sophisticated, so students mistake its formality for precision.', '1) Find ability-phrases (''has the ability to,'' ''is able to,'' ''is capable of''). 2) Replace the phrase with a single modal helper. 3) Re-read: did any meaning vanish? 4) If not, the shorter version wins. 5) Repeat for other unfolded phrases in the sentence.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c83a4630df734ca3', 'act-english', 's-style', 3, 'By reusing background paintings across dozens of episodes, the producers <u>conserved</u> both money and time.', 'Which choice provides the most precise word in context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"hoarded","letter":"B"},{"is_no_change":false,"label":"salvaged","letter":"C"},{"is_no_change":false,"label":"withheld","letter":"D"}]', 'A', '{"A":"''Conserved'' precisely names careful, planned economy of resources.","B":"''Hoarded'' implies secretive, excessive stockpiling the passage never suggests.","C":"''Salvaged'' presupposes rescue from loss or wreckage, not planned reuse.","D":"''Withheld'' means refusing to give something owed, importing a recipient the sentence lacks."}', 'Precision questions hinge on **connotation and scenario**: only the original names prudent resource management.', '''Salvaged'' shares the sense of making the most of materials, so its rescue scenario slips past many readers.', '1) State the sentence''s literal situation. 2) For each verb, name the scenario it presupposes (rescue, greed, denial, economy). 3) Match scenario to situation. 4) Reject any verb that imports facts the passage does not support.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-cf2b45104727a651', 'act-english', 's-style', 3, '<u>Due to the fact that</u> late frosts are common in the valley, growers postpone their pruning as long as possible.', 'Which choice most effectively streamlines the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"In light of the fact that","letter":"B"},{"is_no_change":false,"label":"Because of the fact that","letter":"C"},{"is_no_change":false,"label":"Because","letter":"D"}]', 'D', '{"A":"''Due to the fact that'' spends five words doing one word''s job.","B":"''In light of the fact that'' is an even more formal wrapper around the same empty phrase.","C":"''Because of the fact that'' keeps the filler ''of the fact that'' bolted onto the useful word.","D":"Correct: ''Because'' alone expresses the entire causal link."}', 'Empty scaffolding like ''the fact that'' should be cut when a single **conjunction** does the work.', '''Because of the fact that'' contains the right causal word, so it feels like a fix while keeping the padding.', '1) Circle the phrase and ask what logical job it does. 2) Find the single word that does that job. 3) Delete every word that survives only as packaging. 4) Reread to confirm the meaning is untouched.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d177ac4c09a673d3', 'act-english', 's-style', 3, 'The twins wore <u>identical matching</u> costumes to the parade.', 'Which choice eliminates the redundant description?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"identical","letter":"B"},{"is_no_change":false,"label":"matching identical","letter":"C"},{"is_no_change":false,"label":"identically matching","letter":"D"}]', 'B', '{"A":"''Identical'' and ''matching'' say the same thing — one of them is dead weight.","B":"''Identical'' alone carries the full meaning.","C":"Reversing the order keeps both redundant words.","D":"''Identically matching'' fuses the two redundancies into one phrase."}', 'Two words with one meaning → keep **one**.', 'Doubling adjectives feels emphatic, as if two synonyms are stronger than one.', 'Cut any word that repeats what a neighboring word already says.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d964811598bf7eb2', 'act-english', 's-style', 3, 'After months of debate, the committee <u>made the decision to give its approval to</u> a second market day on Wednesdays.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"made a decision to approve of","letter":"B"},{"is_no_change":false,"label":"decided it would go about approving","letter":"C"},{"is_no_change":false,"label":"approved","letter":"D"}]', 'D', '{"A":"Buries the action inside two padded noun phrases, ''made the decision'' and ''give its approval'' (nominalization_stack).","B":"Trims one layer but keeps the padded ''made a decision'' and adds unidiomatic ''approve of'' for formal authorization (partial_trim_wrong_idiom).","C":"The filler ''go about'' adds motion without meaning (empty_filler).","D":"Correct — a single strong verb conveys the entire action."}', 'One **strong verb** replaces two padded noun phrases with no loss of meaning.', 'Students equate longer, noun-heavy phrasing with formality, so the original''s official sound feels appropriate for a committee.', '1) Find the real action hiding inside the noun phrases. 2) Convert it to a single verb. 3) Compare each option''s meaning to the original. 4) Prefer the shortest option that keeps the meaning and stays idiomatic. 5) Confirm nothing essential disappeared.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e27d5e23cee8e361', 'act-english', 's-style', 3, 'The county''s guide to backyard beekeeping advises that novices <u>consult</u> an experienced mentor before installing their first colony.', 'Which choice best maintains the formal register of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"hit up","letter":"B"},{"is_no_change":false,"label":"touch base with","letter":"C"},{"is_no_change":false,"label":"get the lowdown from","letter":"D"}]', 'A', '{"A":"Correct: ''consult'' is a formal, precise verb that matches the register of an official county guide.","B":"''Hit up'' is slang that clashes with the formal tone of an advisory document.","C":"''Touch base with'' is casual business jargon, too colloquial for this formal guide.","D":"''Get the lowdown from'' is informal, idiomatic speech unsuited to an official publication."}', 'An official guide calls for **formal** diction, and only the original verb keeps that professional register.', 'The casual alternatives sound friendly and approachable, so students pick them to make the advice feel welcoming.', '1) Identify the passage''s register from its context (here, an official county guide = formal). 2) Rate each option as formal, neutral, or colloquial. 3) Keep the option whose register matches the passage. 4) Reject slang or casual idioms even when they feel warmer or friendlier.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e6f59ca66b1dd2da', 'act-english', 's-style', 3, 'Each spring, the lakeside invitational <u>returns again for another year</u> to the same resort where it began.', 'Which choice makes the sentence most concise without changing its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"returns once more for another year","letter":"B"},{"is_no_change":false,"label":"returns back","letter":"C"},{"is_no_change":false,"label":"returns","letter":"D"}]', 'D', '{"A":"''again'' and ''for another year'' both restate the yearly repetition that ''Each spring'' already establishes.","B":"''once more for another year'' is the same doubled repetition in different clothes.","C":"''back'' is built into the verb itself, so the pair says one thing twice.","D":"The bare verb carries the full meaning once ''Each spring'' has established the repetition."}', '''Each spring'' already establishes the repetition, so the bare verb is the only **non-redundant** option.', 'The two-word version tempts because it trims most of the phrase while quietly keeping a duplicated direction inside it.', '1) Circle every word in the underlined portion. 2) For each, ask: is this idea already stated elsewhere in the sentence or inside the verb itself? 3) Delete every duplicate. 4) Reread to confirm no meaning was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e82992a31790aa9c', 'act-english', 's-style', 3, 'According to the ledger, donations <u>doubled</u> in the year after the highway exit opened.', 'Which choice makes the statement clearest and most direct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"basically doubled, more or less,","letter":"B"},{"is_no_change":false,"label":"doubled, as a matter of fact,","letter":"C"},{"is_no_change":false,"label":"doubled, in terms of their numbers,","letter":"D"}]', 'A', '{"A":"Correct: the bare verb states the fact cleanly, with the ledger already establishing accuracy.","B":"Hedges the figure twice — ''basically'' and ''more or less'' — while adding no information.","C":"''As a matter of fact'' is filler; the ledger citation already vouches for the fact.","D":"''In terms of their numbers'' is an empty qualifier — doubling is already numerical."}', 'Every added phrase in the other options is **filler**: it hedges or repeats what the sentence already establishes.', '''As a matter of fact'' feels like it strengthens the claim, so it reads as emphasis rather than padding.', '1) Delete the candidate phrase and re-read. 2) Ask: did any information disappear? 3) If nothing disappeared, the phrase is filler. 4) Watch for double-hedges and ''in terms of'' constructions. 5) Choose the version where deletion is complete.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e86a8361fbda8402', 'act-english', 's-style', 3, 'The soil-test results <u>convinced the board</u> to replace the four oldest beds before spring.', 'Which choice keeps the sentence clear and direct?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"convinced, for all intents and purposes, the board","letter":"B"},{"is_no_change":false,"label":"basically convinced the board, in a sense,","letter":"C"},{"is_no_change":false,"label":"convinced the board, needless to say,","letter":"D"}]', 'A', '{"A":"Correct: the verb moves straight to its object with no filler.","B":"An empty stock idiom interrupts the verb and its object while hedging a plain fact.","C":"Two stacked hedges blur a definite event without adding any meaning.","D":"''Needless to say'' is self-canceling filler: if it were needless, it wouldn''t be said."}', 'Every added phrase in the other versions is **filler** — it changes nothing about what happened and only delays the object.', 'Hedging phrases feel sophisticated and cautious, so students insert them to sound measured even when the fact is definite.', '1) Delete the inserted phrase and reread. 2) Ask: did the sentence lose any information or gain any inaccuracy? 3) If nothing changed, the phrase is filler — leave it out. 4) Repeat for every qualifier. 5) Keep the version where the verb reaches its object without detours.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-eafb184928f1138d', 'act-english', 's-style', 3, 'In its annual summary, the state climate office reported that the summer''s rainfall totals were <u>totally out of whack with</u> the fifty-year average.', 'Which choice best maintains the tone and register of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"way off from","letter":"B"},{"is_no_change":false,"label":"crazily different from","letter":"C"},{"is_no_change":false,"label":"sharply inconsistent with","letter":"D"}]', 'D', '{"A":"''Out of whack'' is slangy conversation, jarring inside an official annual summary (misconception: familiar idioms are universally acceptable).","B":"''Way off'' is casual intensifier-speak, mismatched with a formal report (misconception: shorter always sounds cleaner).","C":"''Crazily'' keeps the chatty register even though ''different from'' is standard (misconception: fixing half the phrase fixes the register).","D":"Correct: measured, precise wording that matches the document''s formal register."}', 'A formal report requires **register-matched** wording — measured and precise rather than conversational.', '''Crazily different from'' upgrades part of the phrase, so it can pass a quick scan as the formal fix.', '1) Identify the document and audience named in the sentence. 2) Set the register bar: official report = formal. 3) Test every word of each option against that bar, not just the obvious slang. 4) Reject any option with even one word below the bar. 5) Choose the option whose every word a careful report writer would sign.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ec92b2302e7b0993', 'act-english', 's-style', 3, 'The dining-car crew iced the lockers at Albany while the chef planned each <u>evening menu in advance before</u> the train left the yard.', 'Which choice makes the sentence most concise while preserving its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"evening menu before","letter":"B"},{"is_no_change":false,"label":"evening menu ahead of time before","letter":"C"},{"is_no_change":false,"label":"evening menu in advance, well before","letter":"D"}]', 'B', '{"A":"''In advance'' and ''before'' make the same time claim, so the phrase says ''early'' twice.","B":"Correct: one time expression carries the full meaning with nothing repeated.","C":"''Ahead of time'' merely swaps in a third synonym while keeping the doubled time idea.","D":"''In advance, well before'' still tells the reader twice that the planning came early."}', 'A single time expression does the job; stacking synonyms for *earlier* is **redundancy**.', '''Ahead of time before'' tempts students who sense the problem but repair redundancy by rewording it instead of cutting it.', '1) Underline every word or phrase in the span that expresses time. 2) Ask whether any two of them answer the same question. 3) Keep exactly one and delete its twins. 4) Reread to confirm no meaning was lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ef00036ef66cef7b', 'act-english', 's-style', 3, 'Thirty seconds into the developer, gray tones begin to <u>occur</u> across the white sheet.', 'Which word most precisely describes how the gray tones appear on the sheet?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"emerge","letter":"B"},{"is_no_change":false,"label":"erupt","letter":"C"},{"is_no_change":false,"label":"accumulate","letter":"D"}]', 'B', '{"A":"''Occur'' merely reports that something happened (vague_verb), painting no picture of gradual appearance.","B":"Correct: it precisely pictures tones gradually coming into view, matching the slow development.","C":"''Erupt'' injects sudden violence (overstated_verb) that contradicts a thirty-second, gentle process.","D":"''Accumulate'' describes quantity piling up (wrong_mechanism), not an image becoming visible in place."}', '**Emerge** captures tones gradually coming into view, matching both the timescale and the mechanism of development.', '''Accumulate'' appeals because the tones do intensify over time, but it pictures quantity piling up rather than an image appearing.', '1) Picture the literal scene the sentence describes. 2) Define each option verb in your own words. 3) Match each definition against the scene''s speed, force, and mechanism. 4) Eliminate verbs that are vague, overstated, or mechanically wrong, and pick the one whose picture matches exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f4901a1805d23a4e', 'act-english', 's-style', 3, '<u>It is important to note that the</u> tide pool refills completely when the ocean returns at high tide.', 'Which choice best eliminates unnecessary words?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"The","letter":"B"},{"is_no_change":false,"label":"What is worth mentioning is that the","letter":"C"},{"is_no_change":false,"label":"There is the fact that the","letter":"D"}]', 'B', '{"A":"The opening is an empty filler that adds no content (empty_phrase).","B":"Correct: cutting the filler leaves a clean, direct sentence beginning with the real subject.","C":"This swaps one hollow opener for another equally empty one.","D":"This filler is wordy and awkward, delaying the real subject."}', 'Empty **filler openers** should be deleted so the sentence starts with its real subject.', 'The filler sounds like it signals importance, so students think it strengthens the sentence.', '1) Check the sentence opening for throat-clearing phrases. 2) Ask whether removing them loses any information. 3) If not, delete the filler. 4) Begin with the true subject.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f5acdce5ce0dde10', 'act-english', 's-style', 3, 'Dye tests at Wind Cave revealed how quickly rainwater <u>percolates</u> through fractured limestone into pools far below.', 'Which choice provides the most precise word for this context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"wanders","letter":"B"},{"is_no_change":false,"label":"evaporates","letter":"C"},{"is_no_change":false,"label":"moves along","letter":"D"}]', 'A', '{"A":"''Percolates'' names precisely the slow filtering of water down through porous rock.","B":"Personifies the water as aimless, losing the downward-filtering precision.","C":"Names the wrong process entirely—turning to vapor, not sinking through stone.","D":"Is so generic it could describe traffic, saying nothing about filtering."}', 'The sentence needs the verb that specifically means **filtering downward through a porous medium**.', '''Evaporates'' is a familiar science word about water, so it borrows unearned credibility.', '1) Identify exactly what is happening physically. 2) Define each verb candidate. 3) Eliminate verbs that name a different process or are too vague to name any. 4) Keep the verb whose definition matches the physics.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f7a0efe11991f360', 'act-english', 's-style', 3, 'An X-ray revealed an earlier portrait <u>that was hidden beneath and concealed under</u> the visible paint layer.', 'Which choice expresses the idea most concisely without changing the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"that was hidden beneath and also concealed under","letter":"B"},{"is_no_change":false,"label":"hidden beneath, concealed under,","letter":"C"},{"is_no_change":false,"label":"hidden beneath","letter":"D"}]', 'D', '{"A":"''Hidden beneath'' and ''concealed under'' are twin phrases; saying both doubles one idea.","B":"Adding ''also'' advertises the duplication instead of deleting it.","C":"Dropping ''that was'' shortens the frame but still keeps both synonymous phrases.","D":"Correct: two words preserve the full meaning that the original spread across seven."}', 'When two phrases are synonyms, the **shortest version that keeps the meaning** — one phrase, trimmed frame — wins.', 'Partial trims feel safer than full ones, so students keep one redundant phrase as insurance.', '1) List each idea the span expresses. 2) Mark any two phrases expressing the same idea — synonym pairs count as one idea. 3) Delete every duplicate, then delete frame words (''that was'') that the sentence works without. 4) Reread to confirm meaning is intact; if so, the shortest survivor is the answer.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f999acadf141df77', 'act-english', 's-style', 3, 'Asked about the missing festival funds, the county treasurer <u>gave a response in which she declined</u> to comment.', 'Which choice best expresses the idea in the clearest, most economical way?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"declined","letter":"B"},{"is_no_change":false,"label":"gave her refusal and declined","letter":"C"},{"is_no_change":false,"label":"responded by way of declining","letter":"D"}]', 'B', '{"A":"Wraps one working verb inside an empty ''gave a response in which'' frame.","B":"Correct: one verb carries the complete meaning of the whole span.","C":"Names the refusal twice — ''gave her refusal'' and ''declined'' describe one act.","D":"''By way of'' pads the sentence without adding any information."}', 'A single verb preserves **every shade of meaning** in the span, so all longer versions lose on economy.', 'The original tempts students because its roundabout frame sounds like careful, official reporting.', '1) Identify the single action the span reports. 2) Try expressing it as one verb. 3) If the one-verb version keeps every shade of meaning, longer versions lose. 4) Watch for empty frames (''gave a response,'' ''by way of''). 5) Re-read the sentence with the shortest survivor.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-07667c23b6508031', 'act-english', 's-style', 4, 'Marine pathologists are still trying to pin down <u>the specific underlying cause that is responsible for producing</u> stony coral tissue loss, a disease that can kill a colony within weeks.', 'Which choice best expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"the cause of","letter":"B"},{"is_no_change":false,"label":"the causal factor that lies behind and produces","letter":"C"},{"is_no_change":false,"label":"what it is that actually causes","letter":"D"}]', 'B', '{"A":"The phrase stacks ''specific,'' ''underlying,'' ''responsible for,'' and ''producing'' to say what a short phrase says (misconception: wordiness_pileup).","B":"''The cause of'' expresses the full idea with no wasted words.","C":"''Lies behind and produces'' doubles the same idea and stays bloated (misconception: wordy_redundant_pair).","D":"''What it is that actually'' is an empty filler frame around a simple idea (misconception: empty_expletive_frame)."}', 'The **shortest** phrasing that keeps the meaning is best; the long version adds no information.', 'Extra qualifiers sound more scientific, so the padded phrase feels more precise than it is.', '1) Find the core idea of the underlined phrase. 2) Cross out any word that doesn''t change the meaning. 3) Rebuild the phrase from what''s left. 4) Choose the option that matches that lean version, not the one that sounds most elaborate.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0fa50a43166a835f', 'act-english', 's-style', 4, 'From the chair''s hand-cut dovetail joints, the appraiser <u>implied</u> that it predated factory production.', 'Which choice most precisely conveys the appraiser''s reasoning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"hinted","letter":"B"},{"is_no_change":false,"label":"inferred","letter":"C"},{"is_no_change":false,"label":"assumed","letter":"D"}]', 'C', '{"A":"*Implied* means to suggest without stating — but the appraiser is drawing a conclusion, not dropping hints.","B":"*Hinted* likewise describes indirect suggestion, the reverse of reasoning from evidence.","C":"Correct: *inferred* names exactly the act of reasoning from evidence to a conclusion.","D":"*Assumed* means accepting without evidence, but the joints are the evidence."}', 'The appraiser reasons **from evidence to a conclusion**, and only one verb names that receiving-and-reasoning act.', '*Implied* and its counterpart form a classic confused pair, and either can sound natural after ''the appraiser.''', '1) Identify who sends information and who receives it. 2) The sender suggests; the receiver reasons to a conclusion. 3) Ask which role the sentence''s subject plays. 4) Match the verb to that role. 5) Check the remaining options for evidence-versus-no-evidence distinctions.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-14972e0d8fa9d17c', 'act-english', 's-style', 4, 'A grain magnifier lets the printer focus the enlarger with real <u>precision, sharpening the projected image until the film''s grain itself is visible</u>.', 'Which choice most effectively expresses the idea without redundancy?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"precision, sharpening the projected image until the film''s grain itself is visible to the eye","letter":"B"},{"is_no_change":false,"label":"precision and exactness, sharpening the projected image until the film''s grain itself is visible","letter":"C"},{"is_no_change":false,"label":"precision, sharpening and refining the projected image until the film''s grain itself is visible","letter":"D"}]', 'A', '{"A":"Correct: every word does distinct work, and no idea is repeated.","B":"Appends ''to the eye'' (redundant_tail), restating an idea already built into ''visible.''","C":"Pairs ''precision'' with its synonym ''exactness'' (redundant_synonym_pair), saying one thing twice.","D":"Doubles the verb with ''refining'' (redundant_verb_pair), which re-performs the job ''sharpening'' already does."}', 'Every word in the original does **distinct** work; each revision smuggles in a synonym or an already-built-in idea.', '''Visible to the eye'' sounds like a natural, complete-feeling phrase, so students add it without noticing that ''visible'' already contains the idea.', '1) Read each option word by word. 2) For every added word, ask: does it introduce a new idea, or restate one already present? 3) Check pairs joined by ''and'' for synonym doubling, and check modifiers for meanings already built into their headwords. 4) Keep the version in which nothing repeats.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-194fe50d9e1f0892', 'act-english', 's-style', 4, 'Residents who wish to comment on the draft comprehensive plan <u>are able to make use of the online portal for the purpose of submitting</u> their remarks before the June hearing.', 'Which choice expresses the idea most clearly and concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"may use the online portal to submit","letter":"B"},{"is_no_change":false,"label":"are able to utilize the online portal so as to submit","letter":"C"},{"is_no_change":false,"label":"may, through the use of the online portal, submit","letter":"D"}]', 'B', '{"A":"''Are able to,'' ''make use of,'' and ''for the purpose of'' are three stacked padding phrases, each replaceable by a single plain word.","B":"Every padded phrase is replaced by its plain one-word equivalent, cutting the span to its working words.","C":"''Utilize'' and ''so as to'' merely swap one set of inflated phrases for another — the misconception that formal-sounding words are more correct.","D":"''Through the use of'' buries the action in a prepositional detour that a direct construction handles in fewer words."}', 'The concise version replaces each **inflated phrase** with its plain one-word equivalent and loses no information.', '''Utilize'' and ''so as to'' sound elevated, so that rewrite feels like an upgrade rather than a repackaging of the same padding.', '1) Underline each multi-word phrase in the span. 2) For each, ask whether a one-word equivalent exists. 3) Substitute the plain equivalents. 4) Compare the candidates and reject any that trade one inflated phrase for another. 5) Re-read to confirm the trimmed sentence keeps the full meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1b50f01a1757c59d', 'act-english', 's-style', 4, 'The stationmaster''s log <u>shows</u> that freight tonnage doubled during the war years, straining every siding on the division.', 'Which choice most effectively expresses the writer''s point?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"serves to show","letter":"B"},{"is_no_change":false,"label":"is capable of showing","letter":"C"},{"is_no_change":false,"label":"provides an indication of the fact","letter":"D"}]', 'A', '{"A":"Correct: the single verb states the log''s action directly with no padding.","B":"''Serves to'' adds an empty helper that delays the verb without adding meaning.","C":"''Is capable of showing'' shifts from what the log does to what it could do, inflating the phrase and weakening the claim.","D":"''Provides an indication of the fact'' buries the action under a chain of nouns and filler."}', 'The bare verb states the log''s action directly, and **concise** wording that loses no meaning is always preferred.', '''Serves to show'' attracts students who equate longer, more ceremonial phrasing with stronger academic style.', '1) Find the core action of the clause. 2) Delete candidate words one at a time; if the meaning survives, the words were padding. 3) Reject any option that adds helpers, hedges, or noun chains around the action. 4) Keep the version in which every remaining word changes the meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-1ea070e603996fc7', 'act-english', 's-style', 4, 'The survey concluded that runoff pollution <u>had significantly reduced</u> the number of species living in the northern pools.', 'Which choice best fits the passage''s formal register?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"had totally cut down on","letter":"B"},{"is_no_change":false,"label":"had really messed with","letter":"C"},{"is_no_change":false,"label":"had put a big dent in","letter":"D"}]', 'A', '{"A":"Correct: the original is precise and matches the formal survey register.","B":"''Cut down on'' is casual phrasing unsuited to a formal report (informal_register).","C":"''Really messed with'' is slang, clashing with the formal context.","D":"''Put a big dent in'' is a colloquial idiom out of place in a survey."}', 'The passage is a formal survey, so the **precise, formal** verb phrase is appropriate.', 'The casual phrases feel punchy and vivid, tempting students who overlook register.', '1) Gauge the passage''s register from its surrounding words. 2) Label each option formal or casual. 3) Eliminate slang and idioms in a formal report. 4) Keep the precise, register-matching phrase.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2758483c822c70a3', 'act-english', 's-style', 4, 'The anemone slowly drew in its tentacles <u>at a gradual, unhurried pace</u> as the shadow passed overhead.', 'Which choice best corrects the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"in a slow and gradual manner","letter":"B"},{"is_no_change":false,"label":"at a pace that was not fast","letter":"C"},{"is_no_change":false,"label":"DELETE the underlined portion.","letter":"D"}]', 'D', '{"A":"The underlined phrase repeats the idea already carried by ''slowly'' (redundant_synonym).","B":"This still restates ''slowly'' with two more synonyms, keeping the redundancy.","C":"This wordy phrase again duplicates ''slowly'' while adding empty bulk.","D":"Correct: removing the phrase eliminates the redundancy, since ''slowly'' already conveys the pace."}', '''Slowly'' already states the pace, so the added phrase is **redundant** and should be cut.', 'The added phrase sounds descriptive, so students keep it for detail without noticing the repeat.', '1) Read the whole sentence for repeated ideas. 2) Locate the word already expressing the idea (''slowly''). 3) Cut any phrase that restates it. 4) Confirm the sentence still reads smoothly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2e0a772869e0c812', 'act-english', 's-style', 4, 'The engineer explained that the older bridge design was <u>not very good at</u> handling sudden gusts across the span.', 'Which choice states the design''s shortcoming most precisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"unstable in","letter":"B"},{"is_no_change":false,"label":"bad with","letter":"C"},{"is_no_change":false,"label":"not the best for","letter":"D"}]', 'B', '{"A":"''Not very good at'' is colloquial and vague about the actual failure mode.","B":"''Unstable in'' names the precise engineering problem — instability under wind load.","C":"''Bad with'' is casual and imprecise.","D":"''Not the best for'' is a soft understatement that hides the real flaw."}', '''Unstable'' names the **specific technical failure**, unlike the vague hedges.', '''Not very good at'' sounds appropriately cautious, but caution isn''t precision.', 'In technical description, choose the exact term for the failure over a vague qualifier.', 'underlined-span-mc', '''Not very good at'' sounds appropriately cautious, but caution isn''t p…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2e3eda6d9075d574', 'act-english', 's-style', 4, 'The surgeon''s report noted that the incision had to be <u>very exact</u> to avoid the nerve running beside the joint.', 'Which choice is the single exact word for the required accuracy?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"precise","letter":"B"},{"is_no_change":false,"label":"careful","letter":"C"},{"is_no_change":false,"label":"neat","letter":"D"}]', 'B', '{"A":"''Very exact'' pads an already strong word with a vague intensifier.","B":"''Precise'' says exactly what''s needed — accurate to a fine tolerance — in one word.","C":"''Careful'' describes attitude, not the geometric accuracy of the cut.","D":"''Neat'' refers to tidiness, not surgical accuracy."}', '''Precise'' captures **fine-tolerance accuracy** in a single exact word.', '''Very exact'' feels emphatic, but the intensifier adds no meaning ''precise'' lacks.', 'Prefer the one word that names the exact quality over an intensifier-plus-adjective.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2e5a1d1a1162deaa', 'act-english', 's-style', 4, 'The station finally rebuilt its on-air graphics <u>due to the fact that viewers were of the opinion that</u> the old maps looked cluttered and dated.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because viewers thought","letter":"B"},{"is_no_change":false,"label":"owing to the fact that viewers held the opinion that","letter":"C"},{"is_no_change":false,"label":"because of the reason that viewers thought that","letter":"D"}]', 'B', '{"A":"''Due to the fact that'' and ''were of the opinion that'' are inflated stand-ins for two short words (misconception: longer phrasing sounds more professional).","B":"Correct: it delivers the same cause and the same belief in three words.","C":"''Owing to the fact that'' trades one padded formula for another (misconception: swapping formal phrases counts as trimming).","D":"''Because of the reason that'' states the cause idea twice — the connector already means ''for the reason that'' (misconception: piling on connectors adds clarity)."}', 'The tightest version keeps every fact — the cause and the belief — while cutting the **empty formula phrases**.', 'The original''s roundabout formality reads like news-report style, so the padding masquerades as professionalism.', '1) Bracket each multi-word formula (''due to the fact that,'' ''of the opinion that''). 2) Ask what single word does the same job. 3) Substitute the single word. 4) Confirm no meaning was lost. 5) Keep the shortest version that survives steps 1 through 4.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-2ff6d9c26984f4d9', 'act-english', 's-style', 4, 'Crew volunteers who <u>are the kind of people that show up</u> early usually get first choice of painting assignments.', 'Which choice makes the sentence clearest and most concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"show up","letter":"B"},{"is_no_change":false,"label":"happen to show up","letter":"C"},{"is_no_change":false,"label":"are known for showing up","letter":"D"}]', 'B', '{"A":"''The kind of people that'' wraps the action in empty classification that restates nothing new (wordy_classification_frame).","B":"Correct: the bare verb phrase delivers the full meaning in the fewest words.","C":"''Happen to'' pads the phrase and miscolors habitual early arrival as accidental (filler_meaning_shift).","D":"''Known for'' swaps the act itself for a reputation about it, changing the meaning while adding words (concision_meaning_shift)."}', 'The **shortest** version that preserves the exact meaning wins, and the plain verb phrase loses nothing the frame provided.', 'The ''known for'' version tempts students because it sounds polished, hiding that a reputation is not the same as actually being there early.', '1) State the sentence''s core claim in your own words. 2) Strip each option to what it literally asserts. 3) Reject options that add scaffolding with no new content. 4) Reject options that quietly change the claim. 5) Keep the briefest version whose meaning matches the original claim exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3fc7ebe3585d0f6e', 'act-english', 's-style', 4, 'After the race, the clinic''s medical director advised her to <u>chill out for a couple of weeks</u> before resuming structured training.', 'Which choice best maintains the formal tone of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"rest for two weeks","letter":"B"},{"is_no_change":false,"label":"rest up and take it easy for a while","letter":"C"},{"is_no_change":false,"label":"undertake a fortnight of convalescent inactivity","letter":"D"}]', 'B', '{"A":"''Chill out'' is a slang idiom that clashes with the clinical, professional frame (register_slang).","B":"Correct: plain professional wording with a definite time span matches the medical director''s advice.","C":"''Rest up,'' ''take it easy,'' and ''for a while'' stay casual and blur the time frame (register_still_casual_vague).","D":"Latinate, stilted phrasing overcorrects into pomp no doctor would write (register_hypercorrect)."}', 'Formal tone is achieved by **plain** professional wording, not by slang on one side or ornate diction on the other.', 'The ornate version tempts students who equate longer, fancier words with greater formality.', '1) Identify the sentence''s register from its frame (who is speaking, in what setting). 2) Read each option in that voice. 3) Flag slang and idioms as too casual. 4) Flag ornate, Latinate phrasing as overcorrection. 5) Choose the plain, professional wording pitched at the sentence''s natural level.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4210f42d39c6bb63', 'act-english', 's-style', 4, 'To stay accurate during the eight-hour deposition, the two interpreters <u>alternated back and forth</u> every quarter hour.', 'Which choice makes the sentence most concise without changing its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"alternated","letter":"B"},{"is_no_change":false,"label":"alternated in turn","letter":"C"},{"is_no_change":false,"label":"took turns alternating","letter":"D"}]', 'B', '{"A":"''Back and forth'' restates what ''alternated'' already means, creating redundancy.","B":"Correct — ''alternated'' alone carries the full meaning of switching repeatedly.","C":"''In turn'' duplicates the idea of alternation just as ''back and forth'' does.","D":"''Took turns alternating'' doubles the idea twice over — taking turns is alternating."}', '''Alternated'' already means switched **by turns**, so any added phrase repeats it.', '''Back and forth'' feels like helpful detail because the rhythm of switching is easy to picture.', '1) Define the underlined verb in your own words. 2) Compare each added phrase to that definition. 3) Cut any phrase whose meaning the verb already contains. 4) Keep the shortest version that loses no information.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-49aca528aa893263', 'act-english', 's-style', 4, 'Modern seismometers can <u>detect</u> ground movements far too faint for anyone standing on the volcano to feel.', 'Which choice provides the most precise word for the context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"notice","letter":"B"},{"is_no_change":false,"label":"witness","letter":"C"},{"is_no_change":false,"label":"uncover","letter":"D"}]', 'A', '{"A":"Correct: this is the precise term for an instrument registering a faint signal.","B":"''Notice'' implies casual human awareness, the wrong register for a machine''s sensitivity.","C":"''Witness'' implies seeing an event happen, not registering an imperceptible signal.","D":"''Uncover'' implies revealing something hidden through investigation, not sensing in real time."}', 'The sentence needs the **technical** verb for an instrument registering signals below human perception.', 'In everyday speech we casually ''notice'' small things, so that verb feels natural even though machines don''t have casual awareness.', '1) Identify the subject doing the action (person or instrument?). 2) List each verb''s built-in scenario: casual awareness, eyewitnessing, investigative revealing, instrumental sensing. 3) Match the scenario to the sentence''s actual situation. 4) Keep the verb whose connotation fits the subject and object exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-4a7c20ad66966eb3', 'act-english', 's-style', 4, 'Regulars line up on the sidewalk <u>in order to be able to buy</u> the first sourdough loaves out of the oven.', 'Which choice makes the sentence most effective?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"so that they will be able to buy","letter":"B"},{"is_no_change":false,"label":"with the purpose of buying","letter":"C"},{"is_no_change":false,"label":"to buy","letter":"D"}]', 'D', '{"A":"''In order to be able to'' spends extra words saying what a bare infinitive already says (wordy_in_order_to_able).","B":"''So that they will be able to'' restates the same purpose with a full clause of padding (wordy_purpose_clause).","C":"''With the purpose of buying'' is a heavy nominal phrase for a simple purpose (wordy_nominal_purpose).","D":"Correct — the plain infinitive expresses the purpose completely in two words."}', 'The bare infinitive carries the entire meaning of purpose, so every added word is **padding**.', '''In order to'' appears constantly in academic-sounding prose, so it reads as properly formal rather than wordy.', '1) State what the phrase contributes (here: purpose). 2) Try the simplest standard construction for that function. 3) If meaning and grammar survive, prefer it. 4) Only keep longer forms when they add real meaning, like contrast or emphasis.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5462a26a26d29d29', 'act-english', 's-style', 4, 'After recalibrating the spectrometer, the chemists <u>revised</u> their estimate of the volcano''s daily gas output.', 'Which choice makes the sentence most concise while preserving its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"revised and updated","letter":"B"},{"is_no_change":false,"label":"went back and revised","letter":"C"},{"is_no_change":false,"label":"made revisions and changes to","letter":"D"}]', 'A', '{"A":"Correct: one precise verb does the whole job.","B":"''Updated'' merely repeats what ''revised'' already says.","C":"''Went back and'' adds nothing — revising an earlier estimate already implies returning to it.","D":"Doubles the redundancy and buries the action in weak noun phrases."}', 'One **precise verb** already carries the complete meaning; every alternative repeats it in extra words.', 'Pairing near-synonyms sounds thorough and official, so the doubled verbs feel like an upgrade rather than a repeat.', '1) Circle the underlined words and ask what each adds. 2) Cut any word restating another''s meaning; cut any phrase already implied by the main verb. 3) Prefer one exact verb over a noun-heavy paraphrase. 4) Re-read: if the meaning is untouched after a cut, the cut was right.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-566a007e16fece12', 'act-english', 's-style', 4, 'The mentor explained that a small entrance matters <u>because</u> a weak colony can guard it against robbing bees more easily.', 'Which choice is most concise while keeping the sentence''s meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"due to the fact that","letter":"B"},{"is_no_change":false,"label":"for the reason that","letter":"C"},{"is_no_change":false,"label":"on account of the fact that","letter":"D"}]', 'A', '{"A":"Correct: a single plain connector states the cause directly with no padding.","B":"''Due to the fact that'' is a bulky, four-word stand-in for a one-word cause connector.","C":"''For the reason that'' pads the cause link into a multi-word phrase that adds no meaning.","D":"''On account of the fact that'' is the wordiest cause frame of the set, stacking filler onto a simple link."}', 'Wordiness is cured by keeping the tightest form, and a single plain **connector** already states the cause with no padding.', 'The longer cause frames sound more formal, so students swap in bulk, mistaking extra words for greater rigor.', '1) Find the words that link cause to effect. 2) Ask whether a single connector can do that job. 3) Prefer the one-word link over any multi-word ''due to the fact that'' style frame. 4) Reject any option that expands a simple cause link into a padded phrase.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5a6a2b4567a2f45a', 'act-english', 's-style', 4, 'As the submersible sank lower, its floodlights <u>showed</u> a towering wall of coral rising out of the darkness.', 'Which choice most precisely conveys the intended meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"revealed","letter":"B"},{"is_no_change":false,"label":"exposed","letter":"C"},{"is_no_change":false,"label":"exhibited","letter":"D"}]', 'B', '{"A":"''Showed'' is a broad, catch-all verb that does not precisely capture bringing the coral into view (imprecise_word).","B":"Correct: it precisely conveys the lights making the hidden coral visible.","C":"''Exposed'' carries a connotation of vulnerability or laying bare to harm, which the scene does not call for (wrong_connotation).","D":"''Exhibited'' implies a deliberate act of display, but the lights are not putting the coral on show (wrong_connotation)."}', 'The most **precise** verb captures lights bringing a hidden object into view without added connotations.', '''Showed'' is grammatically fine and familiar, so students accept the vague verb over a sharper one.', '1) State exactly what the sentence means (lights making something visible). 2) Weigh each verb''s precision and connotation. 3) Reject vague verbs and verbs with the wrong overtone. 4) Choose the verb that fits the meaning exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-5aa213e50a0c59c1', 'act-english', 's-style', 4, 'Volunteers tally attendance <u>by means of the use of a handheld clicker</u> at each of the market''s three gates.', 'Which choice expresses the idea most clearly and concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"through the use of a handheld clicker","letter":"B"},{"is_no_change":false,"label":"with a handheld clicker","letter":"C"},{"is_no_change":false,"label":"by utilizing a handheld clicker for the count","letter":"D"}]', 'C', '{"A":"Chains two prepositional formulas — ''by means of'' and ''the use of'' — around one simple tool (double_formula).","B":"Keeps the padded ''the use of'' construction after a partial trim (partial_trim).","C":"Correct — a single small preposition expresses the instrument cleanly and completely.","D":"Swaps in the inflated ''utilizing'' and repeats the counting idea already present in ''tally'' (inflated_verb_plus_echo)."}', 'An instrument needs only one small preposition, making this the **shortest** option that keeps the full meaning.', 'Cutting ''by means of'' feels like enough trimming, so students stop before removing the equally empty ''the use of.''', '1) Identify the core fact (tool used to tally). 2) Strip every formula that can vanish without losing that fact. 3) Compare the surviving candidates for idiomatic fit. 4) Check the longest options for repeated ideas already in the sentence. 5) Pick the shortest version that still says everything.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-60df6286c7916681', 'act-english', 's-style', 4, 'In her acceptance speech she thanked the mentors who had <u>said good things about</u> her work when no one else would.', 'Which choice most precisely and concisely expresses their support?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"were nice about","letter":"B"},{"is_no_change":false,"label":"liked","letter":"C"},{"is_no_change":false,"label":"championed","letter":"D"}]', 'D', '{"A":"''Said good things about'' is wordy and weak for mentors who backed her against the crowd.","B":"''Were nice about'' is vague and casual, understating real advocacy.","C":"''Liked'' names a private feeling, not public support.","D":"''Championed'' precisely means actively advocated for, matching ''when no one else would''."}', '''Championed'' packs **active advocacy** into one precise word.', 'The phrase ''said good things about'' sounds specific because it''s long, but it''s imprecise.', 'Replace a vague multi-word phrase with the single verb that names the exact action.', 'underlined-span-mc', 'the phrase ''said good things about'' sounds specific because it''s long…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6103f051041d41bf', 'act-english', 's-style', 4, 'Nineteenth-century foundries guarded their designs jealously; when a rival''s new face sold well, competitors would <u>rip it off</u> within a season.', 'Which choice best maintains the formal tone of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"jump on the bandwagon","letter":"B"},{"is_no_change":false,"label":"copy its whole vibe","letter":"C"},{"is_no_change":false,"label":"imitate it closely","letter":"D"}]', 'D', '{"A":"''Rip it off'' is slang, clashing with the essay''s formal historical register.","B":"''Jump on the bandwagon'' is a colloquial idiom and also blurs the meaning from copying to mere trend-following.","C":"''Vibe'' is casual contemporary slang, jarring in a sentence about the 1800s.","D":"''Imitate it closely'' matches the formal register and states the action exactly."}', 'Formal prose requires the **standard-register** phrasing, which also preserves the precise meaning of copying.', '''Jump on the bandwagon'' tempts because it is a familiar idiom for following success, but idioms of that stripe are conversational, not essayistic.', '1) Establish the passage''s register from its surrounding sentences. 2) Flag any candidate containing slang, casual idiom, or trendy diction. 3) Check that the surviving candidates preserve the original meaning. 4) Pick the one matching both register and meaning. 5) Re-read the sentence inside the paragraph to confirm the fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6245ed8555de092b', 'act-english', 's-style', 4, 'When the panel discussion ran past its scheduled hour, the support interpreter <u>tagged in</u> so her partner could rest her hands.', 'Which choice best maintains the essay''s consistent, professional tone?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"jumped into the mix","letter":"B"},{"is_no_change":false,"label":"took over","letter":"C"},{"is_no_change":false,"label":"commenced the performance of her interpreting duties","letter":"D"}]', 'C', '{"A":"''Tagged in'' borrows wrestling slang, too casual for the essay''s professional register.","B":"''Jumped into the mix'' is even chattier slang, drifting further from the essay''s tone.","C":"Correct — plain, neutral phrasing that matches a professional description without stiffness.","D":"The stiff, legalistic pile-up of nouns overcorrects into pompous wording no natural essay would use."}', 'The essay''s voice is professional but plain, so the replacement must be **neutral** — neither slang nor ceremony.', 'The formal-sounding option lures students who assume the fanciest phrasing is always the safest fix.', '1) Read two neighboring sentences and label the passage''s register (casual, neutral, formal). 2) Label each option''s register the same way. 3) Eliminate both extremes: slang and stuffiness. 4) Keep the option matching the passage''s label, at natural sentence length.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a9e293fa93f3dd7', 'act-english', 's-style', 4, 'The songbook printed simple tablature so that readers <u>could themselves attempt to try playing</u> the tunes at home.', 'Which choice expresses the idea in the clearest, most concise way?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"could attempt to try playing","letter":"B"},{"is_no_change":false,"label":"could try playing","letter":"C"},{"is_no_change":false,"label":"could make an attempt at trying to play","letter":"D"}]', 'C', '{"A":"''Themselves'' is unnecessary and ''attempt to try'' says the same thing twice.","B":"Trims one word but keeps the doubled ''attempt to try.''","C":"Correct: every remaining word is doing work, and no meaning is lost.","D":"Inflates the doubling further with ''make an attempt at,'' the wordiest version of all."}', '''Attempt'' and ''try'' are the **same action**, so the sentence needs only one of them — plus nothing else.', 'The middle-length version tempts students who trim the obvious extra word but miss that the two verbs duplicate each other.', '1) List the verbs and verb-like words in the underlined span. 2) Ask which ones name the same action. 3) Keep exactly one word per action. 4) Delete self-evident additions (like ''themselves''). 5) Re-read: if meaning is intact, the shortest surviving version is correct.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6a9e74b956a1a566', 'act-english', 's-style', 4, 'The restoration crew at Indiana Dunes <u>was totally psyched to</u> begin replanting marram grass along the storm-scoured foredunes.', 'Which choice best matches the tone of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was eager to","letter":"B"},{"is_no_change":false,"label":"was pretty stoked to","letter":"C"},{"is_no_change":false,"label":"was desirous of the opportunity to","letter":"D"}]', 'B', '{"A":"''Totally psyched'' is slang, clashing with the passage''s reportorial register.","B":"Conveys the same enthusiasm in standard, register-neutral English.","C":"Replaces one slang phrase with another.","D":"Overcorrects into stilted, antique formality that sticks out as much as slang does."}', 'Formal prose needs a **standard-register** word for enthusiasm—neither slang nor starch.', 'The stiff, elaborate option sounds extra formal, and students often equate maximal formality with correctness.', '1) Read the surrounding sentences and name the register (conversational, standard, academic). 2) Flag any option that is slang for that register—or costume-formal beyond it. 3) The right word should be invisible: same meaning, no register spike. 4) Re-read the sentence with your pick to confirm it blends in.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-6b8c92efff6f2081', 'act-english', 's-style', 4, 'In each month''s newsletter, the owner <u>returns back to</u> the story of the shop''s founding.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"returns again to","letter":"B"},{"is_no_change":false,"label":"returns to","letter":"C"},{"is_no_change":false,"label":"makes a return back to","letter":"D"}]', 'C', '{"A":"''Back'' repeats the idea already inside *returns*, creating redundancy.","B":"''Again'' duplicates the repetition already built into *returns*.","C":"Correct: *returns* alone carries the full meaning of going back.","D":"Piles a wordy noun construction on top of the same redundant ''back.''"}', '*Returns* already means ''goes back,'' so any added **back/again** is redundant.', '''Returns again'' feels like it emphasizes the monthly repetition, so the duplication hides in plain sight.', '1) Define the underlined verb precisely. 2) Ask whether any nearby word repeats part of that definition. 3) Delete the duplicate and re-read. 4) If the sentence keeps its full meaning, the shorter version wins. 5) Check the remaining option for new padding.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-70f61537f01421d5', 'act-english', 's-style', 4, 'A carved sign reminds visitors that the espaliered pear and apple trees along the south wall are fragile <u>and easily damaged</u>.', 'Which choice makes the sentence most concise without losing information?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"DELETE the underlined portion.","letter":"B"},{"is_no_change":false,"label":"and can be damaged without much effort","letter":"C"},{"is_no_change":false,"label":"and, in addition, delicate","letter":"D"}]', 'B', '{"A":"''Easily damaged'' restates what ''fragile'' already means, doubling the idea.","B":"Correct: removing the phrase leaves ''fragile,'' which fully carries the meaning.","C":"This expands the same redundant idea into an even wordier clause.","D":"''Delicate'' is a third synonym, and ''in addition'' falsely promises new information."}', 'When a phrase merely repeats an earlier word''s meaning, **cutting** it is the strongest revision.', '''And easily damaged'' feels like helpful emphasis, so the exact overlap with ''fragile'' slips past.', '1) Define the underlined phrase in your own words. 2) Define the nearby descriptor the same way. 3) If the definitions match, the phrase is redundant — cut it. 4) Reject any option that re-words the repetition instead of removing it.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-742799c550a58e1a', 'act-english', 's-style', 4, 'The old stone bridge <u>goes over</u> the gorge at a height of ninety meters.', 'Which choice is the most precise description of the bridge?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"sits over","letter":"B"},{"is_no_change":false,"label":"spans","letter":"C"},{"is_no_change":false,"label":"happens across","letter":"D"}]', 'C', '{"A":"''Goes over'' is vague — people go over bridges; bridges do something more specific.","B":"''Sits over'' suggests resting on top of something, not stretching across it.","C":"''Spans'' is the precise verb for a structure stretching across a gap.","D":"''Happens across'' means to encounter by chance — bridges don''t do that."}', 'Precision means the verb built for the job: a bridge **spans** a gorge.', '''Goes over'' is technically true, and ''true enough'' masquerades as ''precise''.', 'Prefer the specific verb over a general verb + preposition when one exists.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-760a68005523b0ff', 'act-english', 's-style', 4, 'Passage IV — Night Shift at the Observatory — My first night as a volunteer at the observatory, I expected glamour. Instead, I found cold floors, humming machines, and a long checklist. The astronomer on duty, Dr. Okafor, <u>greeted me warmly but immediately put me to work.</u> Their were dozens of small tasks: calibrating instruments, logging temperatures, and to check the dome''s rotation. None of it looked like the dramatic discoveries I had imagined. Yet as the hours passed, I began to understand that this quiet, careful labor was the real work of science. Around 2 a.m., Dr. Okafor called me over. On the screen was a faint smudge of light — a distant galaxy. "It isn''t much to look at," she said, "but light from there left before humans existed." In that moment, the cold floors and checklists seemed worth it.', 'Which underlined choice adds the most relevant detail about the mentor at this point?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"was a tall person with glasses.","letter":"B"},{"is_no_change":false,"label":"had worked there for many years.","letter":"C"},{"is_no_change":false,"label":"liked to drink coffee at night.","letter":"D"}]', 'A', '{"A":"Original best contrasts expectation vs. reality.","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Original best contrasts expectation vs. reality.', 'The original can read smoothly until you apply the rule.', 'Rule focus: Production (emphasis/contrast)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-887b0a6885128859', 'act-english', 's-style', 4, 'During a storm, rainwater <u>trickles</u> from the shed roof into the first barrel, filling it within minutes.', 'Which choice most precisely matches the action described in the rest of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"seeps","letter":"B"},{"is_no_change":false,"label":"gushes","letter":"C"},{"is_no_change":false,"label":"meanders","letter":"D"}]', 'C', '{"A":"A thin, slow flow contradicts a barrel filling within minutes.","B":"Describes liquid working gradually through small openings — the wrong manner and the wrong speed for storm runoff.","C":"Correct: conveys a strong, fast flow consistent with rapid filling during a storm.","D":"Paints a lazy, winding course across flat ground — wrong image for water pouring off a roof."}', 'The verb must match **every** surrounding clue, and only a word for forceful, fast flow fits a barrel filled within minutes.', '''Trickles'' pairs so often with rain gutters and barrels that students keep it without checking it against the sentence''s own speed clue.', '1) Collect the sentence''s evidence: a storm, roof runoff, a barrel filled within minutes. 2) For each verb, state its built-in speed and manner. 3) Eliminate any verb whose image contradicts a single piece of evidence. 4) Choose the verb whose picture matches all the clues. 5) Reread the sentence to confirm the scene is consistent.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-89c7ff6378446caf', 'act-english', 's-style', 4, 'The biographer wrote that the composer <u>made</u> more than forty symphonies before his fortieth birthday.', 'Which choice is the most precise verb for producing musical works?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"built","letter":"B"},{"is_no_change":false,"label":"did","letter":"C"},{"is_no_change":false,"label":"composed","letter":"D"}]', 'D', '{"A":"''Made'' is generic and undersells the craft of writing symphonies.","B":"''Built'' suits structures, not symphonies.","C":"''Did'' is even vaguer than ''made''.","D":"''Composed'' is the exact verb for creating music."}', '''Composed'' is the **domain-precise verb** for creating musical works.', '''Made'' is technically true, so it passes unless you reach for the exact term.', 'Choose the specific verb the field uses over a general-purpose one.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8d6fa09255742d03', 'act-english', 's-style', 4, 'At mile nine, the half-marathon and marathon courses <u>merge together into one shared route</u> beneath the old rail bridge.', 'Which choice best expresses the idea without redundancy?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"merge","letter":"B"},{"is_no_change":false,"label":"merge together","letter":"C"},{"is_no_change":false,"label":"combine and merge into a single route","letter":"D"}]', 'B', '{"A":"''Together'' and ''into one shared route'' both restate what the verb already means, doubling the redundancy (redundant_double_tail).","B":"Correct: the verb alone carries the full idea of coming together into one path.","C":"Trims the longer tail but keeps ''together,'' which the verb already contains (redundant_partial_trim).","D":"Stacks a synonym verb and re-adds the one-route idea, multiplying the repetition (redundant_synonym_stack)."}', 'The verb already **contains** the ideas of joining and becoming one, so every trailing word repeats meaning the sentence has.', 'Keeping ''together'' tempts students who cut the obvious tail but never test whether the remaining word adds anything new.', '1) Define the underlined verb by itself. 2) Take each following word and ask: does it add information the verb lacks? 3) Cross out any word that repeats the verb''s built-in meaning. 4) Re-read the trimmed sentence to confirm nothing was lost. 5) Prefer the version where every word earns its place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8e11b43bc28b2296', 'act-english', 's-style', 4, 'The historical society''s newsletter praised the exhibit, noting that the curators had <u>pulled together a bunch of</u> documents from a dozen family collections.', 'Which choice best maintains the tone established in the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"scraped up a pile of","letter":"B"},{"is_no_change":false,"label":"effectuated the amalgamation of numerous","letter":"C"},{"is_no_change":false,"label":"assembled a wide range of","letter":"D"}]', 'D', '{"A":"''Pulled together a bunch of'' is conversational slang inside a formal newsletter sentence.","B":"''Scraped up a pile of'' is slangier still and belittles the curators'' work.","C":"''Effectuated the amalgamation of numerous'' overcorrects into pompous, inflated diction.","D":"Correct: it is formal, natural, and precise — matching the newsletter''s register."}', '**Register** must match the passage: standard formal diction, neither slang nor pomposity.', 'The Latinate option tempts because bigger words feel more formal, but inflation is its own register error.', '1) Sample the passage''s diction (''praised,'' ''curators,'' ''collections''). 2) Label each option: slang, standard formal, or inflated. 3) Discard both extremes. 4) Confirm the survivor keeps the original meaning. 5) Re-read the sentence for smooth fit.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-8ece691079362431', 'act-english', 's-style', 4, '<u>In light of the fact that</u> engines can evaluate any position instantly, commentators now spend broadcasts explaining ideas rather than reporting moves.', 'Which choice best avoids wordiness while preserving the meaning of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"Owing to the fact that","letter":"B"},{"is_no_change":false,"label":"Because","letter":"C"},{"is_no_change":false,"label":"In consideration of how","letter":"D"}]', 'C', '{"A":"Five words of packaging perform the job of a single causal connector.","B":"This merely swaps one ''the fact that'' scaffold for its twin, keeping the padding.","C":"The single-purpose connector states the cause relationship with no padding.","D":"''In consideration of how'' is both inflated and off-meaning, turning a cause into a manner."}', 'A single **causal connector** does the entire job of the five-word scaffold.', '''Owing to the fact that'' tempts because it sounds elevated, so students mistake its formality for concision.', '1) Ask what relationship the underlined phrase expresses (here: cause). 2) Flag scaffolds built on ''the fact that'' as padding. 3) Substitute the plainest connector that expresses the same relationship. 4) Reread to confirm the meaning is untouched.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-901918c43858403f', 'act-english', 's-style', 4, 'After weighing three bids, the co-op <u>made the decision to go forward with purchasing</u> a second slab roller.', 'Which choice expresses the idea most concisely?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"decided to purchase","letter":"B"},{"is_no_change":false,"label":"made the decision to purchase","letter":"C"},{"is_no_change":false,"label":"decided that they would go forward with purchasing","letter":"D"}]', 'B', '{"A":"''Made the decision to go forward with purchasing'' buries one action under three layers of padding (noun-heavy inflation).","B":"Correct: ''decided to purchase'' states the entire idea in three words.","C":"Trimming ''go forward with'' still leaves the buried-verb opener ''made the decision to'' (half-trim).","D":"Opens with a strong verb but re-inflates the sentence with an empty trailing clause (relocated wordiness)."}', 'Concision means converting **buried actions** back into direct verbs and dropping every phrase that adds no meaning.', 'The half-trimmed version feels reformed because it is shorter than the original, so students stop auditing before the padding is gone.', '1) Find the real action hiding in the phrase. 2) Convert noun constructions like ''made the decision'' into their verb. 3) Delete connector padding such as ''go forward with.'' 4) Reread: is any remaining word free of a job? 5) Keep the version where every word earns its place and no meaning is lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9518068dc5acaa2a', 'act-english', 's-style', 4, 'The great dunes <u>shift</u> a little with every strong gust that sweeps across the open basin.', 'Which choice best states the idea in the fewest words while keeping its meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"shift and move around","letter":"B"},{"is_no_change":false,"label":"undergo a gradual shifting","letter":"C"},{"is_no_change":false,"label":"are subject to a shifting motion","letter":"D"}]', 'A', '{"A":"Correct: a single precise verb conveys the whole idea with nothing to spare.","B":"Pairs the verb with a synonym that repeats the same action (redundant_synonym).","C":"Turns the verb into a noun phrase, adding words without adding meaning (nominalization).","D":"Wraps the idea in a wordy passive construction that says no more than the verb (wordy_passive)."}', 'One exact verb already carries the full meaning, so the **shortest** version that works is best.', 'The longer phrases sound more descriptive, so students equate extra words with richer meaning rather than clutter.', '1) Identify the core action the sentence needs. 2) Check whether a single verb already expresses it. 3) Compare each longer option to see if it adds meaning or only words. 4) If the extra words add nothing, prefer the shortest accurate form. 5) Re-read to confirm no meaning is lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97a3748e3e5c6b8b', 'act-english', 's-style', 4, 'Patrons <u>who are waiting in expectation of</u> reserved titles receive a text alert the moment their items reach the hold shelf.', 'Which choice is correct for the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"awaiting","letter":"B"},{"is_no_change":false,"label":"who are awaiting","letter":"C"},{"is_no_change":false,"label":"DELETE the underlined portion","letter":"D"}]', 'B', '{"A":"''Waiting in expectation of'' is swollen — expectation is already built into waiting for something.","B":"Correct: one participle carries the complete meaning and keeps the sentence grammatical.","C":"Grammatical but longer — ''who are'' adds nothing that the bare participle doesn''t already convey.","D":"Deletion smashes ''Patrons'' directly into ''reserved titles,'' garbling the sentence."}', 'On concision questions the **shortest grammatical option that preserves the meaning** wins, and the single participle does exactly that.', 'The longer relative-clause version sounds complete and correct, so students stop before testing whether a shorter equivalent works.', '1) Identify the idea the underlined words must preserve. 2) Line the options up from shortest to longest. 3) Test the shortest: does the sentence stay grammatical and keep the full meaning? 4) If yes, take it; if no, step up one length. 5) Never delete words the sentence''s grammar depends on.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9ab632fa209a305c', 'act-english', 's-style', 4, 'Researchers rely on <u>data that has been gathered and collected by automated sensors</u> to track winter snowfall.', 'Which choice most effectively expresses this idea?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"data gathered and also collected by automated sensors","letter":"B"},{"is_no_change":false,"label":"data gathered by automated sensors","letter":"C"},{"is_no_change":false,"label":"the gathered data collected via automated sensor readings","letter":"D"}]', 'C', '{"A":"''Gathered'' and ''collected'' duplicate each other inside a padded ''that has been'' clause (doubled verb plus clause bulk).","B":"Trimming the clause but keeping ''and also collected'' preserves the doubling (incomplete cut).","C":"One participle and the essential agent, with nothing repeated and no fact lost.","D":"Rearranging the pile-up still says the collecting twice and adds ''via... readings'' clutter (reshuffled redundancy)."}', 'The best version keeps every fact — the data and its source — while cutting the **duplicate verb** and the clause padding.', 'The full clause ''that has been gathered and collected'' sounds thorough and precise, hiding its redundancy.', '1) List the facts the phrase must keep (what, obtained by what). 2) Strike words that repeat a fact already stated. 3) Prefer a participle to a full ''that has been'' clause when meaning survives. 4) Choose the shortest option that still lists every fact.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-9f7e1371d0f7b3b1', 'act-english', 's-style', 4, 'When the tremor spiked just after midnight, the overnight crew <u>totally freaked out and</u> alerted civil-defense officials in the towns below.', 'Which choice best maintains the tone and style of the passage?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"got seriously rattled and","letter":"B"},{"is_no_change":false,"label":"hit the panic button and","letter":"C"},{"is_no_change":false,"label":"immediately","letter":"D"}]', 'D', '{"A":"''Totally freaked out'' is slang that clashes with the passage''s formal, factual register.","B":"''Seriously rattled'' softens the slang but remains conversational rather than formal.","C":"''Hit the panic button'' is an idiom too casual for the context, and it adds panic the facts don''t state.","D":"Correct: formal and factual, it keeps the focus on the crew''s swift official response."}', '**Register** governs here: a factual report calls for neutral wording that centers the swift official response, not dramatized emotion.', 'The softened idiom sheds the most obvious slang and can masquerade as a formal revision while staying conversational at its core.', '1) Identify the passage''s register (formal report vs. casual talk). 2) Flag underlined idioms or slang that belong to the other register. 3) Prefer wording that states the verifiable action, not dramatized emotion. 4) Re-read the revised sentence in the passage''s voice to confirm the tone matches.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a840be689a2e6be6', 'act-english', 's-style', 4, 'Over centuries, the retreating tide <u>made</u> a branching network of channels across the muddy flat.', 'Which choice most precisely describes the tide''s effect on the flat?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"did","letter":"B"},{"is_no_change":false,"label":"gave","letter":"C"},{"is_no_change":false,"label":"carved","letter":"D"}]', 'D', '{"A":"The original verb is vague and misses the cutting action that shaped the channels (imprecise_word).","B":"This is even vaguer, a placeholder verb with no descriptive force.","C":"This verb implies handing over, which does not describe shaping channels.","D":"Correct: this verb precisely conveys the tide cutting the channels over time."}', 'The chosen verb captures the **precise action** of cutting channels, unlike the generic verbs.', 'The original is technically true, so students accept it without seeking a sharper verb.', '1) Identify the exact action being described. 2) Rank the verbs by how precisely they name that action. 3) Reject vague, all-purpose verbs. 4) Choose the verb that pictures the action.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b7168654a6dd0813', 'act-english', 's-style', 4, 'In the early 1920s, talent scouts for northern record labels <u>looked over</u> Southern cities and rail towns, determined to sign every promising blues singer before a rival company could.', 'Which choice most precisely fits the context of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"scoured","letter":"B"},{"is_no_change":false,"label":"glanced at","letter":"C"},{"is_no_change":false,"label":"gazed upon","letter":"D"}]', 'B', '{"A":"imprecise_casual: *looked over* suggests a quick, cursory inspection, clashing with the mission to find *every* promising singer.","B":"Correct: it conveys exhaustive, urgent searching, matching the scouts'' competitive determination.","C":"*Glanced at* is even more cursory than the original.","D":"*Gazed upon* is contemplative and passive — admiration, not searching."}', 'Only this verb matches the sentence''s stakes: a **thorough**, competitive hunt through whole cities.', '*Looked over* is familiar and roughly right, so its casual, skim-the-surface connotation slips past.', '1) Collect the sentence''s context clues (here: ''every promising'' and ''before a rival could''). 2) Write down the intensity those clues demand. 3) Rate each verb''s connotation against that intensity. 4) Reject verbs that are near the meaning but wrong in degree.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-b83b0f5d79a219f8', 'act-english', 's-style', 4, 'Replacement tubes, <u>owing to the fact that they had become scarce</u>, often cost more than the radios they were meant to revive.', 'Which choice best eliminates wordiness while preserving the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"because of their having become scarce","letter":"B"},{"is_no_change":false,"label":"now scarce","letter":"C"},{"is_no_change":false,"label":"being that they are now scarce","letter":"D"}]', 'C', '{"A":"''Owing to the fact that'' is a six-word runway carrying no information of its own.","B":"The possessive-gerund construction rearranges the baggage without lightening it.","C":"Correct: a two-word appositive delivers the scarcity and its cause-flavor with no scaffolding.","D":"''Being that'' is nonstandard, and the clause it drags in restates what a bare description shows."}', 'Concision keeps only the **idea itself**: a compact appositive conveys the scarcity without connective scaffolding.', '''Because of their having become scarce'' feels like a real revision since the wording changed, but the word count and machinery barely did.', '1) Isolate the single idea the phrase must express. 2) Count the words each option spends on it. 3) Strike options using scaffolding formulas (''the fact that,'' ''being that''). 4) Check the shortest survivor still preserves the meaning and fits grammatically. 5) Reread the sentence with it in place.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-bdbcbe226d86801b', 'act-english', 's-style', 4, 'The novel''s final chapter<u>, which comes at the end of the book,</u> resolves the mystery.', 'Which choice best trims the redundant clause?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":", which is located at the book''s end,","letter":"B"},{"is_no_change":false,"label":"DELETE the underlined portion","letter":"C"},{"is_no_change":false,"label":", coming at the end of the book''s final pages,","letter":"D"}]', 'C', '{"A":"A ''final chapter'' by definition comes at the end — the clause adds nothing.","B":"Rewording the redundancy doesn''t remove it.","C":"Deleting the clause leaves ''The novel''s final chapter resolves the mystery'' — complete and tighter.","D":"''End of the book''s final pages'' doubles the redundancy it was meant to fix."}', 'When a clause restates what ''final'' already means, the fix is **deletion**, not rephrasing.', 'Rewritten versions look like improvements because they change the words — but not the waste.', 'If a modifier repeats information the noun already carries, delete it entirely.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c8566ee144b7baef', 'act-english', 's-style', 4, 'From the light pole above the parkway median, the red-tailed hawk <u>looked at</u> the grass strip for the faint stir of a vole.', 'Which choice most precisely conveys the hawk''s methodical, section-by-section search of the median?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"glared at","letter":"B"},{"is_no_change":false,"label":"scanned","letter":"C"},{"is_no_change":false,"label":"glimpsed","letter":"D"}]', 'C', '{"A":"''Looked at'' reports only eye direction, conveying nothing about method or thoroughness (vague_generic_verb).","B":"''Glared at'' imports anger or menace the passage never asserts and still says nothing about method (wrong_connotation).","C":"Correct: the verb''s core meaning is a systematic, sweeping visual search — exactly the stated manner.","D":"''Glimpsed'' means a brief, accidental sighting, clashing with a sustained hunt ''for'' something not yet seen (wrong_duration)."}', 'Precision means the verb''s **core meaning matches the described manner** — a deliberate, sweeping search — and only one option encodes that.', '''Glared at'' tempts students because raptors look fierce, but intensity of expression is not precision about the search.', '1) Underline the manner words in the stem (methodical, section-by-section). 2) Define each option''s verb in one phrase: direction only, emotion, sweep, or split-second sight. 3) Eliminate verbs that are vague, emotionally loaded, or wrong in duration. 4) Keep the verb whose definition restates the stem''s manner. 5) Re-read the sentence to confirm the image fits.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d513e3c1e2c4b03a', 'act-english', 's-style', 4, 'Each January, Isle Royale''s wolf-count team <u>collaborates together with</u> volunteer pilots to spot the island''s packs from the air.', 'Which choice best improves the underlined portion?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"collaborates jointly with","letter":"B"},{"is_no_change":false,"label":"collaborates with","letter":"C"},{"is_no_change":false,"label":"works in collaboration together with","letter":"D"}]', 'C', '{"A":"''Together'' repeats the togetherness already built into ''collaborates.''","B":"''Jointly'' duplicates the same built-in meaning in a dressier word.","C":"Trims to the verb alone, which already contains the idea of working together.","D":"Piles three redundant layers onto a single idea."}', 'The prefix in ''collaborates'' already means together, so the verb alone is complete—**redundancy adds no meaning**.', '''Jointly'' sounds technical and precise, so students read the duplication as added rigor.', '1) Define the underlined verb: does its meaning already include the modifier''s idea? 2) Delete any word restating that built-in meaning. 3) Re-read: if the sentence loses nothing, the deletion stands. 4) Prefer the tightest version that keeps the full meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-d895b6e62645c3d6', 'act-english', 's-style', 4, 'Passage II — The Science of Sourdough — Bread may seem simple, <u>but sourdough is surprisingly complex.</u> Unlike breads made with packaged yeast, sourdough rises using wild yeast and bacteria captured from the air. Bakers maintain a "starter," a mixture of flour and water that they feed regularly. The starter, it ferments over several days. During fermentation, the microbes produce carbon dioxide, which makes the dough rise. They also produce acids, giving sourdough its tangy flavor. Because of these reactions, no two starters taste exactly alike. Some bakers, claim that a starter''s flavor reflects the place where it was made. A San Francisco starter, for instance, may taste different from one in Paris. Whether or not that is true, sourdough remains a small marvel of biology and patience.', 'Which underlined choice most precisely completes the contrast the sentence sets up?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"but many people enjoy eating it.","letter":"B"},{"is_no_change":false,"label":"but it can be expensive to buy.","letter":"C"},{"is_no_change":false,"label":"but bakeries are common.","letter":"D"}]', 'A', '{"A":"Only A previews the biological process. (Form-805 intro item.)","B":"This option leaves or introduces an error under the tested rule.","C":"This option leaves or introduces an error under the tested rule.","D":"This option leaves or introduces an error under the tested rule."}', 'Only A previews the biological process. (Form-805 intro item.)', 'The original can read smoothly until you apply the rule.', 'Rule focus: Production (introduction)..', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-dc971d59cd41534f', 'act-english', 's-style', 4, 'Engineers rely on sensors <u>that are attached in a permanent way</u> to the tower''s base to catch even faint vibrations.', 'Which choice best expresses the idea in the fewest words while keeping the meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"permanently attached","letter":"B"},{"is_no_change":false,"label":"attached in a manner that is permanent","letter":"C"},{"is_no_change":false,"label":"that are attached there permanently","letter":"D"}]', 'B', '{"A":"''In a permanent way'' spells out what a single adverb conveys (misconception: adverb_unpacked_to_phrase).","B":"Compresses the clause to a tight participial phrase with zero loss of meaning.","C":"Stretches the padding further with a relative clause inside the prepositional phrase (misconception: wordy_relative_clause).","D":"Keeps the unneeded ''that are'' and adds ''there,'' which duplicates the stated location (misconception: filler_duplicate_location)."}', 'The **shortest option that keeps every fact** wins: the whole clause collapses into a two-word participial phrase.', 'The ''attached there permanently'' version is fairly short and sounds natural, so students overlook that ''there'' and ''that are'' do no work.', '1) Identify the facts the underlined portion asserts. 2) For each option, delete it mentally and check which facts survive. 3) Eliminate options carrying words with no job (''that are,'' ''there,'' ''in a way''). 4) Among the survivors, take the most compact. 5) Reread the sentence to confirm smooth grammar.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-df551b86be138e8c', 'act-english', 's-style', 4, 'Because every matrix was <u>reusable</u>, a foundry could cast thousands of identical letters from a single mold.', 'Which choice is most effective and concise?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"reusable more than once","letter":"B"},{"is_no_change":false,"label":"reusable and could be used repeatedly","letter":"C"},{"is_no_change":false,"label":"reusable, capable of repeated use,","letter":"D"}]', 'A', '{"A":"''Reusable'' alone carries the full meaning; the sentence is already concise.","B":"''More than once'' merely restates what ''reusable'' already means.","C":"''Could be used repeatedly'' duplicates ''reusable'' word for word in longer clothing.","D":"''Capable of repeated use'' is a third way of saying ''reusable,'' adding bulk but no information."}', 'Each longer version repeats the idea already inside ''reusable,'' so the original is the only **non-redundant** choice.', 'The expansions tempt because extra phrasing feels more thorough, though it adds no new content.', '1) Define the underlined word in plain terms. 2) Compare each added phrase against that definition. 3) Strike any phrase whose meaning is already inside the word. 4) Keep additions only if they contribute genuinely new information. 5) Re-read the leanest version to confirm nothing is lost.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e0108ec26fdc30bb', 'act-english', 's-style', 4, 'The extension bulletin urges growers to <u>keep tabs on</u> their codling-moth traps at least twice each week.', 'Which choice best matches the formal register of the bulletin?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"keep an eyeball on","letter":"B"},{"is_no_change":false,"label":"monitor","letter":"C"},{"is_no_change":false,"label":"undertake ongoing surveillance of","letter":"D"}]', 'C', '{"A":"''Keep tabs on'' is an idiom too casual for a technical bulletin.","B":"''Keep an eyeball on'' is even more slangy than the original.","C":"Correct: ''monitor'' matches the bulletin''s professional, technical register in a single precise word.","D":"''Undertake ongoing surveillance of'' is inflated bureaucratic phrasing that overshoots the register."}', 'Formal technical prose wants the plain **professional** verb, neither slang nor bureaucratic inflation.', '''Undertake ongoing surveillance of'' sounds impressively official, so students confuse stiffness with formality.', '1) Identify the document type and its register. 2) Rate each option: slang, plain professional, or inflated. 3) Reject both extremes. 4) Choose the wording a professional writer would actually use.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e7edf1bbdba00516', 'act-english', 's-style', 4, 'Near mile twenty-two, her form began to <u>deteriorate</u>: her shoulders crept upward, and each footfall landed flatter than the last.', 'Which choice provides the most precise word in this context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"decompose","letter":"B"},{"is_no_change":false,"label":"evaporate","letter":"C"},{"is_no_change":false,"label":"shrivel","letter":"D"}]', 'A', '{"A":"Correct: the word precisely names a gradual decline in quality, matching the creeping, step-by-step details.","B":"''Decompose'' names literal biological rot, importing a jarringly physical image (nuance_literal_process).","C":"''Evaporate'' means to vanish, overstating a decline as a disappearance (nuance_overstatement).","D":"''Shrivel'' evokes shrinking and drying, a size-and-moisture image that misdescribes running mechanics (nuance_wrong_image)."}', 'Precision means matching the word''s **core sense** — gradual worsening — to the evidence of slow, step-by-step decline.', '''Shrivel'' tempts students because it is vivid and negative, and vividness can masquerade as precision.', '1) Gather the sentence''s evidence for what actually happened. 2) Define each candidate word''s core sense and home territory. 3) Ask: does the word''s literal image match the evidence? 4) Reject words that overstate, understate, or import the wrong physical process. 5) Keep the word whose meaning maps onto the details exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fb46eff954da3ba6', 'act-english', 's-style', 4, 'In its annual grant report, the nonprofit noted that shop revenue <u>totally bankrolled</u> the after-school tutoring program.', 'Which choice best matches the register of the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"fully funded","letter":"B"},{"is_no_change":false,"label":"footed the bill for","letter":"C"},{"is_no_change":false,"label":"shelled out for","letter":"D"}]', 'B', '{"A":"''Totally bankrolled'' mixes a casual intensifier with showbiz slang, clashing with a grant report.","B":"Correct: measured, professional wording suited to a formal report.","C":"''Footed the bill'' is a conversational idiom out of place in grant writing.","D":"''Shelled out'' is slang and also implies grudging payment, distorting the meaning."}', 'A grant report demands **formal register**, and only one option uses the measured diction such a document would print.', '''Footed the bill for'' is a familiar, respectable-sounding idiom, so its casualness is easy to miss.', '1) Identify the document type named in the sentence. 2) Set the register bar accordingly (grant report = formal). 3) Screen each option for slang, idiom, and casual intensifiers. 4) Eliminate options that a professional editor would flag. 5) Confirm the survivor preserves the meaning.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-0a9808afaaedc6d9', 'act-english', 's-style', 5, 'The gallery placard noted that the sketches were, so to speak, the artist''s <u>day in the sun</u> — quick studies never meant for display.', 'Which choice replaces the misused idiom with wording that fits the intended meaning?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"raison d''être","letter":"B"},{"is_no_change":false,"label":"rough drafts","letter":"C"},{"is_no_change":false,"label":"swan song","letter":"D"}]', 'C', '{"A":"''Day in the sun'' means a moment of glory, contradicting ''never meant for display''.","B":"''Raison d''être'' means reason for existing, which quick throwaway studies were not.","C":"''Rough drafts'' plainly and correctly describes preliminary studies never meant to be shown.","D":"''Swan song'' means a final performance, unrelated to preliminary sketches."}', 'The sketches were **preliminary**, so ''rough drafts'' fits where the glory idiom fails.', 'A fancy foreign phrase like ''raison d''être'' can feel sophisticated enough to be right.', 'Test an idiom or borrowed phrase against the literal meaning; replace it if the senses clash.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-10f0b02354ecfdf4', 'act-english', 's-style', 5, 'The chef described the tasting menu as her <u>magnum opus</u>, though she admitted it was just a rough first attempt she might scrap by morning.', 'Which choice fits the tentative, unfinished nature the sentence describes?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"pièce de résistance","letter":"B"},{"is_no_change":false,"label":"trial run","letter":"C"},{"is_no_change":false,"label":"tour de force","letter":"D"}]', 'C', '{"A":"''Magnum opus'' means a crowning masterpiece, contradicting ''rough first attempt''.","B":"''Pièce de résistance'' means the standout highlight, again too grand for a draft.","C":"''Trial run'' plainly fits a tentative first attempt she might scrap.","D":"''Tour de force'' means a feat of brilliance, the opposite of an unfinished experiment."}', 'The dish is a **tentative draft**, so plain ''trial run'' fits where the grand phrases fail.', 'The elevated phrases sound impressive on a menu, tempting you past their meaning.', 'When a borrowed superlative clashes with the facts, a plain accurate phrase is the correct fix.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-3d16a3afd16b2422', 'act-english', 's-style', 5, 'The article called the mayor''s abrupt reversal a complete <u>180 degree turn</u> from the position she had defended for years.', 'Which choice corrects the redundant expression?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"about-face","letter":"B"},{"is_no_change":false,"label":"complete 180","letter":"C"},{"is_no_change":false,"label":"360 degree turn","letter":"D"}]', 'B', '{"A":"''Complete 180 degree turn'' is redundant — a 180 is already a complete reversal, and ''complete'' repeats it.","B":"''About-face'' names a total reversal in one clean term with no redundancy.","C":"''Complete 180'' still pairs ''complete'' with a figure that already means a full reversal.","D":"A ''360 degree turn'' returns to the starting point — the opposite of a reversal."}', '''About-face'' states a **full reversal** without the doubled ''complete'' or the mismatched figure.', '''180 degree turn'' is a familiar way to say reversal, so its built-in redundancy hides.', 'Cut redundancy in stock phrases, and check that any figure of speech points the right direction.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-61af7a4ba8314159', 'act-english', 's-style', 5, 'Because the sky-brightness figures come from volunteers'' naked-eye star counts rather than from calibrated meters, the club is careful to say only that the data <u>proves</u> light pollution is rising in the county.', 'Which choice most precisely matches the caution described earlier in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"establishes","letter":"B"},{"is_no_change":false,"label":"suggests","letter":"C"},{"is_no_change":false,"label":"confirms","letter":"D"}]', 'C', '{"A":"''Proves'' claims total certainty, which both the rough method and the phrase ''careful to say only'' rule out.","B":"''Establishes'' makes the same overclaim in formal dress—settling a matter beyond doubt.","C":"Correct: a tentative verb matches evidence from uncalibrated counts and the club''s hedged framing.","D":"''Confirms'' presupposes a prior conclusion now being verified, again overstating the certainty."}', 'Precision here is **calibration**: the verb''s strength must match imprecise evidence and the sentence''s explicit hedging.', '''Confirms'' tempts students because the data does point the same direction as the claim, making full verification feel earned.', '1) Rate the evidence: precise instrument or rough estimate? 2) Find the sentence''s own confidence cues (''careful to say only''). 3) Rank the candidate verbs from tentative to absolute. 4) Choose the verb whose rank matches the evidence and the cues—never stronger. 5) Re-read to confirm the claim no longer outruns its support.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-97f16d6e3edea26f', 'act-english', 's-style', 5, 'The retouching pigments were deliberately chosen to <u>approximate</u> the portrait''s original palette rather than duplicate it, so that future conservators can distinguish the new paint from the old.', 'Which choice provides the most precise word for the context?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"replicate","letter":"B"},{"is_no_change":false,"label":"estimate","letter":"C"},{"is_no_change":false,"label":"match","letter":"D"}]', 'A', '{"A":"Correct: the verb means to come close without being exact — precisely the near-but-distinguishable effect described.","B":"''Replicate'' means to copy exactly, which the sentence explicitly rules out with ''rather than duplicate.''","C":"''Estimate'' describes a mental calculation of quantity, not the visual relationship of paints.","D":"''Match'' implies equivalence so close as to be indistinguishable, defeating the stated purpose."}', 'The context demands a verb meaning **close but deliberately inexact**, and the original is the only option carrying that nuance.', '''Match'' sounds like standard studio language for paint, so students miss that exact matching is what the conservators are avoiding.', '1) Find the sentence''s built-in contrast or purpose clause (''rather than...'', ''so that...''). 2) Write down what the verb must mean to satisfy it. 3) Define each option in a phrase and test it against that requirement. 4) Reject any verb that contradicts the contrast, even if it collocates naturally with the topic. 5) Keep the original if it alone fits.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-a07a23176fd0a16a', 'act-english', 's-style', 5, 'Without naming anyone, the unsigned letter to the editor <u>indicated</u> that a council member had leaked the sealed bids.', 'Which choice most precisely describes how the letter made its charge?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"insinuated","letter":"B"},{"is_no_change":false,"label":"announced","letter":"C"},{"is_no_change":false,"label":"disclosed","letter":"D"}]', 'B', '{"A":"''Indicated'' is flat and neutral, missing the letter''s sly, indirect accusation.","B":"Correct: it means to suggest something discreditable indirectly — matching ''without naming anyone.''","C":"''Announced'' means declared openly, the opposite of an unsigned, nameless hint.","D":"''Disclosed'' means revealed verified information, which an anonymous accusation is not."}', 'The context — unsigned, accusatory, naming no one — demands a verb of **indirect, discreditable suggestion**, and only one choice carries that exact shade.', '''Indicated'' tempts students because it is a safe, general-purpose verb that never sounds wrong.', '1) Collect the context clues (''without naming anyone,'' ''unsigned,'' an accusation). 2) Profile the needed verb: indirect, suggestive, accusatory. 3) Define each candidate and score it against all three features. 4) Eliminate verbs that are too open, too neutral, or too factual. 5) Keep the verb matching every clue.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-c53704861efec902', 'act-english', 's-style', 5, 'Her memoir revisits, <u>ad nauseam</u>, the single summer that changed everything — each chapter circling back with fresh tenderness.', 'Which choice best fits the appreciative tone the sentence establishes?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"time and again","letter":"B"},{"is_no_change":false,"label":"in perpetuity","letter":"C"},{"is_no_change":false,"label":"willy-nilly","letter":"D"}]', 'B', '{"A":"''Ad nauseam'' means to a sickening excess, clashing with ''fresh tenderness''.","B":"''Time and again'' neutrally conveys repeated return, matching the fond, appreciative tone.","C":"''In perpetuity'' means forever, a legalistic phrase that doesn''t fit revisiting a summer.","D":"''Willy-nilly'' means haphazardly, contradicting the deliberate circling back."}', 'The tone is **affectionate**, so ''time and again'' fits where the negative ''ad nauseam'' can''t.', '''Ad nauseam'' is a familiar Latin tag for repetition, so it seems apt on the surface.', 'Weigh a borrowed phrase''s connotation against the sentence''s tone, not just its literal sense.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-e68996d993ddbf5a', 'act-english', 's-style', 5, 'The reason the trail closed <u>is because</u> erosion damaged the footbridge.', 'Which choice corrects the wordy construction after ''reason''?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"is due to the fact that","letter":"B"},{"is_no_change":false,"label":"is on account of because","letter":"C"},{"is_no_change":false,"label":"is that","letter":"D"}]', 'D', '{"A":"''The reason is because'' says ''reason'' twice — ''because'' already means ''for the reason that''.","B":"''Due to the fact that'' swaps one redundancy for five words of another.","C":"''On account of because'' stacks two causal phrases — doubly redundant.","D":"''The reason is that'' states the cause once, cleanly."}', 'After ''the reason is'', use **that** — ''because'' would smuggle in a second ''reason''.', '''The reason is because'' is extremely common in speech and sounds natural.', 'Pair ''the reason'' with ''that''; pair ''because'' with a plain clause — never both.', 'underlined-span-mc', '''The reason is because'' is extremely common in speech and sounds natural', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f024373485663990', 'act-english', 's-style', 5, 'In their scouting reports, rival teams described our defensive robot as <u>stubborn</u>, praising the way it refused to surrender its zone even against double-teams.', 'Which choice most precisely conveys the admiring judgment described in the sentence?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"pigheaded","letter":"B"},{"is_no_change":false,"label":"tenacious","letter":"C"},{"is_no_change":false,"label":"rigid","letter":"D"}]', 'C', '{"A":"Shares the core meaning of refusing to yield but tilts toward criticism, clashing with ''praising'' (connotation_negative_synonym).","B":"Frames persistence as a flaw, nearly an insult, inside a sentence built on praise (connotation_insult).","C":"Correct: it means admirably persistent, matching both the meaning and the praising tone.","D":"Describes inflexibility of form or attitude rather than determined effort, with a faint negative shade (connotation_wrong_nuance)."}', 'The key word means **admirably persistent**, matching both the meaning and the praising tone of the sentence.', 'The original shares the core meaning of refusing to yield, so students who check denotation alone keep it.', '1) Pin down the required meaning from context. 2) Check each synonym''s connotation: positive, neutral, or negative. 3) Match the connotation to the sentence''s attitude — here, explicit praise. 4) Keep the word that passes both checks.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
ON CONFLICT ("id") DO UPDATE SET "subject" = EXCLUDED."subject", "skill_id" = EXCLUDED."skill_id", "difficulty" = EXCLUDED."difficulty", "context_html" = EXCLUDED."context_html", "stem_md" = EXCLUDED."stem_md", "choices" = EXCLUDED."choices", "answer_letter" = EXCLUDED."answer_letter", "per_choice_rationale" = EXCLUDED."per_choice_rationale", "why_correct_md" = EXCLUDED."why_correct_md", "why_tempted_md" = EXCLUDED."why_tempted_md", "rule_md" = EXCLUDED."rule_md", "item_type" = EXCLUDED."item_type", "misconception" = EXCLUDED."misconception", "reviewed" = EXCLUDED."reviewed", "generated_by" = EXCLUDED."generated_by";
INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-f19724b908798592', 'act-english', 's-style', 5, 'The startup''s founders were, in the reporter''s words, <u>enfants terribles</u> who quietly followed every industry norm and rarely spoke to the press.', 'Which choice corrects the expression so it fits the founders described?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"mavericks","letter":"B"},{"is_no_change":false,"label":"provocateurs","letter":"C"},{"is_no_change":false,"label":"traditionalists","letter":"D"}]', 'D', '{"A":"''Enfants terribles'' means shocking rule-breakers, contradicting founders who followed every norm.","B":"''Mavericks'' means independent nonconformists, contradicting ''followed every industry norm''.","C":"''Provocateurs'' means those who deliberately provoke, again the opposite of quiet conformists.","D":"''Traditionalists'' matches people who quietly observe industry norms."}', 'The founders **followed every norm**, so ''traditionalists'' fits where the rebel phrase can''t.', '''Enfants terribles'' sounds worldly and startup-flavored, masking that it means the reverse.', 'Confirm a borrowed phrase''s meaning agrees with the surrounding facts before keeping it.', 'underlined-span-mc', '''Enfants terribles'' sounds worldly and startup-flavored, masking that…', true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
