INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-fc86542c1155d628', 'act-english', 's-style', 5, 'Bracing the six-foot steel bar against a stump for leverage, the youngest crew member <u>moved</u> the half-ton boulder off the tread an inch at a time.', 'Which choice most precisely describes the action performed with the bar?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"displaced","letter":"B"},{"is_no_change":false,"label":"hauled","letter":"C"},{"is_no_change":false,"label":"pried","letter":"D"}]', 'D', '{"A":"*Moved* is grammatical but generic — it could describe a forklift or a flood and wastes the sentence''s leverage setup.","B":"*Displaced* names the result in clinical, lab-report language, erasing the method and effort the sentence stages.","C":"*Hauled* means dragged or pulled by main strength, contradicting the braced-bar-and-fulcrum technique described.","D":"Correct: it names the exact lever action the setup describes — working a heavy object up and over, inch by inch."}', 'Precision means matching the verb to the **exact physical technique** the sentence stages: a bar braced against a fulcrum, working the load loose inch by inch.', '*Displaced* tempts students who equate a technical-sounding word with a precise one, even when it names the outcome rather than the action.', '1) Inventory the sentence''s physical details: tools, technique, pace. 2) Define each candidate verb precisely. 3) Eliminate verbs that are vague, wrong in method, or wrong in register. 4) Choose the verb whose definition matches the staged action exactly.', 'underlined-span-mc', NULL, true, 'claude-fable-5+claude-opus-4-8>=v1@4931561dee2300e4a1b57ee1413067b6')
