INSERT INTO "test_item" ("id", "subject", "skill_id", "difficulty", "context_html", "stem_md", "choices", "answer_letter", "per_choice_rationale", "why_correct_md", "why_tempted_md", "rule_md", "item_type", "misconception", "reviewed", "generated_by") VALUES ('ti-gen-ffcac62995b325e2', 'act-english', 's-style', 5, 'The critic dismissed the sequel as a <u>fait accompli</u> of clichés, every twist visible from the opening scene.', 'Which choice corrects the misused expression?', '[{"is_no_change":true,"label":"NO CHANGE","letter":"A"},{"is_no_change":false,"label":"faux pas","letter":"B"},{"is_no_change":false,"label":"renaissance","letter":"C"},{"is_no_change":false,"label":"pastiche","letter":"D"}]', 'D', '{"A":"''Fait accompli'' means a done deal, which doesn''t describe a film full of clichés.","B":"''Faux pas'' means a social blunder, not a derivative artwork.","C":"''Renaissance'' means a revival, the opposite of a stale sequel.","D":"''Pastiche'' means a derivative work stitched from borrowed parts — exactly a predictable cliché-collage."}', '''Pastiche'' correctly names a **work built from borrowed, familiar parts**, unlike ''fait accompli''.', 'Both are French borrowings, so one can seem as fitting as the other to an unsure reader.', 'Match a borrowed expression to its true meaning; sophistication doesn''t excuse a misfit.', 'underlined-span-mc', NULL, true, 'gpt-4o-mini+gpt-4o>=d2@d5532ef964cc4b0c864e72539eed376c')
