-- tutorial: 1 row(s)
INSERT INTO "tutorial" ("id", "subject", "skill_id", "body_md", "examples", "generated_from", "reviewed", "ground_md", "pitfall_md", "question_md", "self_explain_prompt", "worked_example", "completion_try", "annotated_examples") VALUES ('tut-hand-nec-s-punc', 'act-english', 's-punc', 'Run the removal test: lift the clause out of the sentence. If it still stands, the clause is non-essential — fence it with a pair of commas. If the clause pins down which thing you mean, it''s essential — no commas.', '["My kitchen, which provides an alternative to eating out, is small.","The car that I bought is electric."]', 'hand:rajnish@2026-07-11', true, 'You already use commas every day — to list things, to mark a pause, to keep parts of a sentence from colliding. Nothing here is new machinery; it builds on habits you already have.', 'But one clause can need a pair of commas while another needs none — and the wrong choice quietly flips what the sentence means. The clauses that catch people cluster right after words like "which" and "who."', 'So how do you tell when a clause actually needs its commas?', 'Before you read the rule — take a guess. When do you think a clause needs commas around it?', '{"answer":"Keep both commas.","sentence":"My kitchen, which provides an alternative to eating out, is small.","steps":["Remove the clause → \"My kitchen is small.\" Still a complete sentence.","So the clause is extra detail — non-essential.","Non-essential → fence it with a pair of commas."]}', '{"choices":[{"correct":true,"text":"Keep both commas"},{"correct":false,"text":"Delete the commas"}],"sentence":"The teacher, who grades fairly, is popular.","why":"Remove \"who grades fairly\" → \"The teacher is popular\" still stands, so the clause is non-essential — keep both commas."}', '[{"callouts":["remove it → \"My kitchen is small.\" still works","so → fence with a pair of commas"],"clause":"which provides an alternative to eating out","essential":false,"post":" is small.","pre":"My kitchen"},{"callouts":["identifies which car → essential → no commas"],"clause":"that I bought","essential":true,"post":" is electric.","pre":"The car "}]')
